            &alpha_square_multipliers,
            &alpha_cube_multipliers,
        ));

        let (circle_inv_2x, circle_inv_2y, line_tables, final_x): (
            &[u32],
            &[u32],
            [&[u32]; 3],
            &[u32],
        ) = match geometry.layer0_binary_depth {
            10 => (
                &FIXED_CIRCLE_INV_2X,
                &FIXED_CIRCLE_INV_2Y,
                [&FIXED_LINE1_INV, &FIXED_LINE2_INV, &FIXED_LINE3_INV],
                &FIXED_FINAL_X,
