    /// Check every authenticated query for an additive fixed-log-10 PCS
    /// shape. Widths and tags were already enforced by
    /// [`verify_circle_pcs_openings_for_shape`]; this method canonical-decodes
    /// the selected C1/C2 fibers, recombines them with the same generator used
    /// for point claims, and follows all four normalized folds.
    pub fn check_circle_pcs_queries_for_shape(
        &self,
        shape: CirclePcsShape,
        prepared: &CirclePcsPreparedClaims,
        alphas: [QM31; FIXED_ARITY4_ROUNDS as usize],
        final_coefficients: [QM31; CANDIDATE_FINAL_POLY_LEN],
        inverse: fn(M31) -> M31,
    ) -> Result<(), CirclePcsOpeningsError> {
        let shape = shape.validate()?;
        let queries = &self.later.indices.layer0;
        if queries.len() != usize::from(shape.query_count) {
            return Err(CirclePcsOpeningsError::QueryCountMismatch {
                expected: usize::from(shape.query_count),
                actual: queries.len(),
            });
        }
        if prepared.powers.len() != shape.total_columns()
            || prepared.claims.len() != usize::from(shape.opening_points)
        {
            return Err(CirclePcsOpeningsError::Decode(
                CirclePcsDecodeError::EvaluationLength {
                    expected: shape.evaluation_bytes(),
                    actual: prepared.claims.len() * shape.total_columns() * 16,
                },
            ));
        }

        let coordinates = derive_query_fold_inverses_for_circle(
            u32::from(shape.domain_log_size),
            queries,
            [
                &self.later.indices.later[0],
                &self.later.indices.later[1],
                &self.later.indices.later[2],
            ],
            inverse,
        )?;
        let alpha_squared = alphas.map(QM31::square);
        let alpha = alphas.map(PreparedQm31Multiplier::new);
        let alpha_squared = alpha_squared.map(PreparedQm31Multiplier::new);
        let alpha_cubed: [PreparedQm31Multiplier; FIXED_ARITY4_ROUNDS as usize] =
            core::array::from_fn(|round| {
                PreparedQm31Multiplier::new(alphas[round].square().mul(alphas[round]))
            });

        for (ordinal, &query) in queries.iter().enumerate() {
            let c1 =
                self.layer0
                    .c1_leaf(ordinal)
                    .ok_or(CirclePcsOpeningsError::MissingOpening {
                        layer: 0,
                        index: query,
                    })?;
            let c2 =
                self.layer0
                    .c2_leaf(ordinal)
                    .ok_or(CirclePcsOpeningsError::MissingOpening {
                        layer: 0,
                        index: query,
                    })?;
            let combined = gamma_combine_circle_pcs_layer0(shape, c1, c2, &prepared.powers)?;
            let [inv_2x, inv_2y] =
                *coordinates
                    .circle
                    .get(ordinal)
                    .ok_or(CirclePcsOpeningsError::MissingOpening {
                        layer: 0,
                        index: query,
                    })?;
            let folded =
                crate::circle_fri::normalized_circle_to_line_arity4_prepared_polynomial_candidate(
                    combined,
                    alpha[0],
                    alpha_squared[0],
                    alpha_cubed[0],
                    inv_2x,
                    inv_2y,
                );
            let parent = query >> 2;
            let parent_ordinal =
                self.later.indices.later[0]
                    .binary_search(&parent)
                    .map_err(|_| CirclePcsOpeningsError::MissingOpening {
                        layer: 1,
                        index: parent,
                    })?;
            let leaf = self.later.openings.layers[0].leaf(parent_ordinal).ok_or(
                CirclePcsOpeningsError::MissingOpening {
                    layer: 1,
                    index: parent,
                },
            )?;
            let offset = (query & 3) as usize * 16;
            let expected = QM31::from_le_bytes(&leaf[offset..offset + 16])
                .ok_or(CirclePcsOpeningsError::NonCanonicalLater { layer: 1, offset })?;
            if folded != expected {
                return Err(CirclePcsOpeningsError::FirstFoldMismatch { query });
            }
        }

        for layer in 0..CIRCLE_QUERY_LATER_LAYERS {
            for (ordinal, &index) in self.later.indices.later[layer].iter().enumerate() {
                let incoming = self.later.openings.layers[layer].leaf(ordinal).ok_or(
                    CirclePcsOpeningsError::MissingOpening {
                        layer: layer as u8 + 1,
                        index,
                    },
                )?;
                let inverses = *coordinates.later[layer].get(ordinal).ok_or(
                    CirclePcsOpeningsError::MissingOpening {
                        layer: layer as u8 + 1,
                        index,
                    },
                )?;
                if layer + 1 < CIRCLE_QUERY_LATER_LAYERS {
                    let parent = index >> 2;
                    let parent_ordinal = self.later.indices.later[layer + 1]
                        .binary_search(&parent)
                        .map_err(|_| CirclePcsOpeningsError::MissingOpening {
                            layer: layer as u8 + 2,
                            index: parent,
                        })?;
                    let outgoing = self.later.openings.layers[layer + 1]
                        .leaf(parent_ordinal)
                        .ok_or(CirclePcsOpeningsError::MissingOpening {
                            layer: layer as u8 + 2,
                            index: parent,
                        })?;
                    check_fixed_line_transition_prepared_polynomial(
                        incoming,
                        outgoing,
                        index as usize,
                        layer as u8 + 1,
                        inverses,
                        alpha[layer + 1],
                        alpha_squared[layer + 1],
                        alpha_cubed[layer + 1],
                    )?;
                } else {
                    let final_x = *coordinates
                        .final_x
                        .get(ordinal)
                        .ok_or(CirclePcsOpeningsError::MissingOpening { layer: 4, index })?;
                    check_fixed_terminal_transition_prepared_polynomial(
                        incoming,
                        final_coefficients,
                        index as usize,
                        inverses,
                        final_x,
                        alpha[3],
                        alpha_squared[3],
                        alpha_cubed[3],
                    )?;
                }
            }
        }
        Ok(())
    }
}

/// Authenticate the complete layer0||layer1||layer2||layer3 opening suffix.
pub fn verify_circle_openings<'a>(
    hash: HashFn,
    c1_root: &[u8; 32],
    c2_root: &[u8; 32],
    later_roots: &[[u8; 32]; CIRCLE_LINE_LAYER_COUNT],
    layer0_queries: &[u32],
    proof_bytes: &'a [u8],
) -> Result<VerifiedCircleOpenings<'a>, CircleOpeningsError> {
    let indices = derive_circle_line_query_indices(layer0_queries)?;
    let (layer0, remainder) = verify_circle_layer0_opening_from_proof(
        hash,
        c1_root,
        c2_root,
        &indices.layer0,
        proof_bytes,
    )?;
    let later = verify_circle_line_openings_for_geometry_with_indices(
        hash,
        later_roots,
        indices,
        remainder,
        FIXED_CIRCLE_OPENING_GEOMETRY,
    )?;
    Ok(VerifiedCircleOpenings { layer0, later })
}

/// Authenticate all fixed openings while deferring canonical decoding to the
/// immediately following all-query check. Every opened leaf is visited by
/// that check, so the composed acceptance predicate is unchanged.
pub(crate) fn verify_circle_openings_deferred_canonical<'a>(
    hash: HashFn,
    c1_root: &[u8; 32],
    c2_root: &[u8; 32],
    later_roots: &[[u8; 32]; CIRCLE_LINE_LAYER_COUNT],
    layer0_queries: &[u32],
    proof_bytes: &'a [u8],
) -> Result<VerifiedCircleOpenings<'a>, CircleOpeningsError> {
    verify_circle_openings_deferred_canonical_for_geometry(
        hash,
        c1_root,
        c2_root,
        later_roots,
        layer0_queries,
        proof_bytes,
        FIXED_CIRCLE_OPENING_GEOMETRY,
    )
}

pub(crate) fn verify_circle_openings_deferred_canonical_for_geometry<'a>(
    hash: HashFn,
    c1_root: &[u8; 32],
    c2_root: &[u8; 32],
    later_roots: &[[u8; 32]; CIRCLE_LINE_LAYER_COUNT],
    layer0_queries: &[u32],
    proof_bytes: &'a [u8],
    geometry: CircleOpeningGeometry,
) -> Result<VerifiedCircleOpenings<'a>, CircleOpeningsError> {
    verify_circle_openings_deferred_canonical_for_geometry_and_c2_leaf_bytes(
        hash,
        c1_root,
        c2_root,
        later_roots,
        layer0_queries,
        proof_bytes,
        geometry,
        CIRCLE_C2_LEAF_BYTES,
    )
}

pub(crate) fn verify_circle_openings_deferred_canonical_for_geometry_and_c2_leaf_bytes<'a>(
    hash: HashFn,
    c1_root: &[u8; 32],
    c2_root: &[u8; 32],
    later_roots: &[[u8; 32]; CIRCLE_LINE_LAYER_COUNT],
    layer0_queries: &[u32],
    proof_bytes: &'a [u8],
    geometry: CircleOpeningGeometry,
    c2_leaf_bytes: usize,
) -> Result<VerifiedCircleOpenings<'a>, CircleOpeningsError> {
    verify_circle_openings_deferred_canonical_for_geometry_and_leaf_bytes(
        hash,
        c1_root,
        c2_root,
        later_roots,
        layer0_queries,
        proof_bytes,
        geometry,
        crate::circle_merkle::CIRCLE_C1_LEAF_BYTES,
        c2_leaf_bytes,
    )
}

pub(crate) fn verify_circle_openings_deferred_canonical_for_geometry_and_leaf_bytes<'a>(
    hash: HashFn,
    c1_root: &[u8; 32],
    c2_root: &[u8; 32],
    later_roots: &[[u8; 32]; CIRCLE_LINE_LAYER_COUNT],
    layer0_queries: &[u32],
    proof_bytes: &'a [u8],
    geometry: CircleOpeningGeometry,
    c1_leaf_bytes: usize,
    c2_leaf_bytes: usize,
) -> Result<VerifiedCircleOpenings<'a>, CircleOpeningsError> {
    let indices = if geometry == FIXED_CIRCLE_OPENING_GEOMETRY {
        derive_circle_line_query_indices(layer0_queries)?
    } else {
        derive_circle_line_query_indices_for_count(
            layer0_queries,
            1usize << geometry.layer0_binary_depth,
        )?
    };
    let (layer0, remainder) =
        verify_circle_layer0_opening_from_proof_deferred_canonical_for_depth_and_leaf_bytes(
            hash,
            c1_root,
            c2_root,
            &indices.layer0,
            proof_bytes,
            geometry.layer0_binary_depth,
            c1_leaf_bytes,
            c2_leaf_bytes,
        )?;
    let later = verify_circle_line_openings_deferred_canonical_for_geometry_with_indices(
        hash,
        later_roots,
        indices,
        remainder,
        geometry,
    )?;
    Ok(VerifiedCircleOpenings { layer0, later })
}

/// Authenticate roots from the fixed prefix, then check every derived query
/// against explicit transcript challenges and the prefix's natural final4.
/// Challenge derivation and relation verification remain outside this helper.
pub fn verify_and_check_circle_openings_for_prefix<'a>(
    hash: HashFn,
    prefix: &CandidatePrefix<'_>,
    layer0_queries: &[u32],
    proof_bytes: &'a [u8],
    gamma: QM31,
    alphas: [QM31; FIXED_ARITY4_ROUNDS as usize],
) -> Result<VerifiedCircleOpenings<'a>, CircleOpeningsError> {
    let expected_query_count = usize::from(CANDIDATE_QUERY_COUNT);
    if layer0_queries.len() != expected_query_count {
        return Err(CircleOpeningsError::QueryCountMismatch {
            expected: expected_query_count,
            actual: layer0_queries.len(),
        });
    }
    let mut later_roots = [[0u8; 32]; CIRCLE_LINE_LAYER_COUNT];
    for (layer, root) in later_roots.iter_mut().enumerate() {
        *root = prefix.rounds[layer + 1]
            .root
            .copied()
            .ok_or(CircleOpeningsError::PrefixShape)?;
    }
    let mut final_natural = [QM31::ZERO; CANDIDATE_FINAL_POLY_LEN];
    for (coefficient, value) in final_natural.iter_mut().enumerate() {
        *value = prefix
            .final_coefficient(coefficient)
            .ok_or(CircleOpeningsError::PrefixShape)?;
    }
    let verified = verify_circle_openings(
        hash,
        prefix.c1_root,
        prefix.c2_root,
        &later_roots,
        layer0_queries,
        proof_bytes,
    )?;
    verified.check_all_queries(gamma, alphas, final_natural)?;
    Ok(verified)
}

/// Authenticate and check one complete opening suffix for an explicitly
/// selected rate geometry. This is the composed acceptance boundary used by
/// rate-1/32 tests and future profiles: canonical decoding is deferred only
/// until the immediately following all-query arithmetic, which visits every
/// opened leaf.
pub fn verify_and_check_circle_openings_for_geometry<'a>(
    hash: HashFn,
    c1_root: &[u8; 32],
    c2_root: &[u8; 32],
    later_roots: &[[u8; 32]; CIRCLE_LINE_LAYER_COUNT],
    layer0_queries: &[u32],
    proof_bytes: &'a [u8],
    gamma: QM31,
    alphas: [QM31; FIXED_ARITY4_ROUNDS as usize],
    final_natural: [QM31; CANDIDATE_FINAL_POLY_LEN],
    geometry: CircleOpeningGeometry,
) -> Result<VerifiedCircleOpenings<'a>, CircleOpeningsError> {
    let verified = verify_circle_openings_deferred_canonical_for_geometry(
        hash,
        c1_root,
        c2_root,
        later_roots,
        layer0_queries,
        proof_bytes,
        geometry,
    )?;
    verified.check_query_segment_for_geometry(
        gamma,
        alphas,
        final_natural,
        CircleQuerySegment::Full,
        geometry,
    )?;
    Ok(verified)
}

/// Composed Merkle-plus-query acceptance boundary for the width-18
/// state-only profile. Both leaf widths are fixed here so a profile cannot
/// authenticate one byte layout and decode another.
pub fn verify_and_check_state_only_circle_openings_for_geometry<'a>(
    hash: HashFn,
    c1_root: &[u8; 32],
    c2_root: &[u8; 32],
    later_roots: &[[u8; 32]; CIRCLE_LINE_LAYER_COUNT],
    layer0_queries: &[u32],
    proof_bytes: &'a [u8],
    powers: &StateOnlyQueryPowers,
    alphas: [QM31; FIXED_ARITY4_ROUNDS as usize],
    final_natural: [QM31; CANDIDATE_FINAL_POLY_LEN],
    geometry: CircleOpeningGeometry,
) -> Result<VerifiedCircleOpenings<'a>, CircleOpeningsError> {
    let verified = verify_state_only_circle_openings_for_geometry(
        hash,
        c1_root,
        c2_root,
        later_roots,
        layer0_queries,
        proof_bytes,
        geometry,
    )?;
    verified.check_state_only_query_segment_prepared_for_geometry(
        powers,
        alphas,
        final_natural,
        CircleQuerySegment::Full,
        geometry,
    )?;
    Ok(verified)
}

/// Authenticate and parse the complete state-only opening suffix without yet
/// running the query arithmetic. This split is acceptance-neutral: callers
/// must immediately invoke
/// [`VerifiedCircleOpenings::check_state_only_query_segment_prepared_for_geometry`]
/// with `CircleQuerySegment::Full`. It exists so an on-chain measurement can
/// name the Merkle/opening cost separately from the all-query recombination.
pub fn verify_state_only_circle_openings_for_geometry<'a>(
    hash: HashFn,
    c1_root: &[u8; 32],
    c2_root: &[u8; 32],
    later_roots: &[[u8; 32]; CIRCLE_LINE_LAYER_COUNT],
    layer0_queries: &[u32],
    proof_bytes: &'a [u8],
    geometry: CircleOpeningGeometry,
) -> Result<VerifiedCircleOpenings<'a>, CircleOpeningsError> {
    verify_circle_openings_deferred_canonical_for_geometry_and_leaf_bytes(
        hash,
        c1_root,
        c2_root,
        later_roots,
        layer0_queries,
        proof_bytes,
        geometry,
        STATE_ONLY_C1_LEAF_BYTES,
        STATE_ONLY_C2_LEAF_BYTES,
    )
}

/// Authenticate the complete opening forest for an additive fixed-log-10 PCS
/// shape. Exact leaf widths, rate-derived depths, and all five Merkle tags
/// are supplied by the transcript-bound shape descriptor.
pub fn verify_circle_pcs_openings_for_shape<'a>(
    hash: HashFn,
    shape: CirclePcsShape,
    c1_root: &[u8; 32],
    c2_root: &[u8; 32],
    later_roots: &[[u8; 32]; CIRCLE_LINE_LAYER_COUNT],
    layer0_queries: &[u32],
    proof_bytes: &'a [u8],
) -> Result<VerifiedCircleOpenings<'a>, CirclePcsOpeningsError> {
    let shape = shape.validate()?;
    if layer0_queries.len() != usize::from(shape.query_count) {
        return Err(CirclePcsOpeningsError::QueryCountMismatch {
            expected: usize::from(shape.query_count),
            actual: layer0_queries.len(),
        });
    }
    let geometry = shape.opening_geometry()?;
    let indices = derive_circle_line_query_indices_for_count(
        layer0_queries,
        1usize << geometry.layer0_binary_depth,
    )?;
    let (layer0, remainder) = verify_circle_layer0_opening_from_proof_for_shape(
        hash,
        c1_root,
        c2_root,
        &indices.layer0,
        proof_bytes,
        geometry.layer0_binary_depth,
        shape.c1_leaf_bytes_checked()?,
        shape.c2_leaf_bytes_checked()?,
        shape.c1_layer0_tag,
        shape.c2_layer0_tag,
    )?;
    let later = verify_circle_line_openings_for_geometry_and_tags_with_indices(
        hash,
        later_roots,
        indices,
        remainder,
        geometry,
        shape.later_layer_tags,
    )?;
    Ok(VerifiedCircleOpenings { layer0, later })
}

#[cfg(test)]
mod tests {
    use super::*;
    use alloc::vec::Vec;

    #[test]
    fn monotone_routing_matches_binary_search_for_random_nested_query_sets() {
        let mut state = 0x4d4f_4e4f_544f_4e45u64;
        for schedule in 0..64 {
            let depth = if schedule & 1 == 0 { 10 } else { 12 };
            let bound = 1u32 << depth;
            let mut queries = Vec::with_capacity(36);
            for _ in 0..36 {
                state = state
                    .wrapping_mul(6_364_136_223_846_793_005)
                    .wrapping_add(1_442_695_040_888_963_407);
                queries.push(((state >> 32) as u32) & (bound - 1));
            }
            let indices =
                derive_circle_line_query_indices_for_count(&queries, bound as usize).unwrap();

            let mut layer1_ordinal = 0usize;
            for &query in &indices.layer0 {
                let target = query >> 2;
                let expected = indices.later[0].binary_search(&target).unwrap();
                assert_eq!(
                    advance_monotone_ordinal(&indices.later[0], &mut layer1_ordinal, target, 1,)
                        .unwrap(),
                    expected,
                );
            }

            for layer in 0..2 {
                let mut outgoing_ordinal = 0usize;
                for &index in &indices.later[layer] {
                    let target = index >> 2;
                    let expected = indices.later[layer + 1].binary_search(&target).unwrap();
                    assert_eq!(
                        advance_monotone_ordinal(
                            &indices.later[layer + 1],
                            &mut outgoing_ordinal,
                            target,
                            layer as u8 + 2,
                        )
                        .unwrap(),
                        expected,
                    );
                }
            }
        }

        let mut ordinal = 0;
        assert_eq!(
            advance_monotone_ordinal(&[1, 3, 7], &mut ordinal, 2, 1),
            Err(CircleOpeningsError::Later(
                CircleLineMerkleError::LeafIndexNotFound { layer: 1, index: 2 }
            )),
        );
    }
}

crates/aspis-core/src/circle_pcs_shape.r:
//! Additive shape layer for fixed-log-10 circle PCS profiles.
//!
//! Frozen V4 wrappers retain their existing constants and byte grammars.
//! This module only describes the shared four-slot, four-round substrate so
//! later profiles can select different C1/C2 widths and Merkle tags without
//! reusing a V4 domain accidentally.

use alloc::vec::Vec;

use crate::circle_line_merkle::CircleOpeningGeometry;
use crate::field::{M31, QM31};

pub const CIRCLE_PCS_SHAPE_VERSION: u8 = 1;
pub const CIRCLE_PCS_SHAPE_BYTES: usize = 24;
pub const CIRCLE_PCS_TRACE_LOG_SIZE: u8 = 10;
pub const CIRCLE_PCS_FIBER_SLOTS: usize = 4;
pub const CIRCLE_PCS_ARITY4_ROUNDS: u8 = 4;
pub const CIRCLE_PCS_LATER_LAYERS: usize = 3;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct CirclePcsShape {
    pub trace_log_size: u8,
    pub domain_log_size: u8,
    pub query_count: u16,
    pub opening_points: u8,
    pub c1_columns: u16,
    pub c2_columns: u16,
    pub c1_layer0_tag: u8,
    pub c2_layer0_tag: u8,
    pub later_layer_tags: [u8; CIRCLE_PCS_LATER_LAYERS],
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum CirclePcsShapeError {
    UnsupportedTraceLog { actual: u8 },
    DomainTooSmall { trace_log: u8, domain_log: u8 },
    DomainTooLarge { actual: u8 },
    EmptyQueries,
    TooManyQueries { count: u16, fibers: usize },
    EmptyOpeningPoints,
    EmptyC1,
    EmptyC2,
    WidthOverflow,
    DuplicateTreeTag { tag: u8 },
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum CirclePcsDecodeError {
    Shape(CirclePcsShapeError),
    EvaluationLength { expected: usize, actual: usize },
    C1LeafLength { expected: usize, actual: usize },
    C2LeafLength { expected: usize, actual: usize },
    NonCanonicalEvaluation { index: usize },
    NonCanonicalC1 { offset: usize },
    NonCanonicalC2 { offset: usize },
}

impl From<CirclePcsShapeError> for CirclePcsDecodeError {
    fn from(error: CirclePcsShapeError) -> Self {
        Self::Shape(error)
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct CirclePcsPreparedClaims {
    pub claims: Vec<QM31>,
    pub powers: Vec<QM31>,
}

impl CirclePcsShape {
    pub fn validate(self) -> Result<Self, CirclePcsShapeError> {
        if self.trace_log_size != CIRCLE_PCS_TRACE_LOG_SIZE {
            return Err(CirclePcsShapeError::UnsupportedTraceLog {
                actual: self.trace_log_size,
            });
        }
        if self.domain_log_size < self.trace_log_size + 2 {
            return Err(CirclePcsShapeError::DomainTooSmall {
                trace_log: self.trace_log_size,
                domain_log: self.domain_log_size,
            });
        }
        if self.domain_log_size > 30 {
            return Err(CirclePcsShapeError::DomainTooLarge {
                actual: self.domain_log_size,
            });
        }
        if self.query_count == 0 {
            return Err(CirclePcsShapeError::EmptyQueries);
        }
        let fibers = self.fiber_count();
        if usize::from(self.query_count) > fibers {
            return Err(CirclePcsShapeError::TooManyQueries {
                count: self.query_count,
                fibers,
            });
        }
        if self.opening_points == 0 {
            return Err(CirclePcsShapeError::EmptyOpeningPoints);
        }
        if self.c1_columns == 0 {
            return Err(CirclePcsShapeError::EmptyC1);
        }
        if self.c2_columns == 0 {
            return Err(CirclePcsShapeError::EmptyC2);
        }
        self.c1_leaf_bytes_checked()?;
        self.c2_leaf_bytes_checked()?;

        let tags = [
            self.c1_layer0_tag,
            self.c2_layer0_tag,
            self.later_layer_tags[0],
            self.later_layer_tags[1],
            self.later_layer_tags[2],
        ];
        for (index, tag) in tags.iter().copied().enumerate() {
            if tags[..index].contains(&tag) {
                return Err(CirclePcsShapeError::DuplicateTreeTag { tag });
            }
        }
        Ok(self)
    }

    pub const fn message_len(self) -> usize {
        1usize << self.trace_log_size
    }

    pub const fn codeword_len(self) -> usize {
        1usize << self.domain_log_size
    }

    pub const fn fiber_count(self) -> usize {
        1usize << (self.domain_log_size - 2)
    }

    pub const fn total_columns(self) -> usize {
        self.c1_columns as usize + self.c2_columns as usize
    }

    pub const fn opening_count(self) -> usize {
        self.total_columns() * self.opening_points as usize
    }

    pub const fn evaluation_bytes(self) -> usize {
        self.opening_count() * 16
    }

    pub fn c1_leaf_bytes_checked(self) -> Result<usize, CirclePcsShapeError> {
        usize::from(self.c1_columns)
            .checked_mul(CIRCLE_PCS_FIBER_SLOTS * 4)
            .ok_or(CirclePcsShapeError::WidthOverflow)
    }

    pub fn c2_leaf_bytes_checked(self) -> Result<usize, CirclePcsShapeError> {
        usize::from(self.c2_columns)
            .checked_mul(CIRCLE_PCS_FIBER_SLOTS * 16)
            .ok_or(CirclePcsShapeError::WidthOverflow)
    }

    pub fn opening_geometry(self) -> Result<CircleOpeningGeometry, CirclePcsShapeError> {
        self.validate()?;
        let layer0_binary_depth = u32::from(self.domain_log_size - 2);
        Ok(CircleOpeningGeometry {
            layer0_binary_depth,
            later_binary_depths: [
                layer0_binary_depth - 2,
                layer0_binary_depth - 4,
                layer0_binary_depth - 6,
            ],
        })
    }

    pub fn encode(self) -> Result<[u8; CIRCLE_PCS_SHAPE_BYTES], CirclePcsShapeError> {
        self.validate()?;
        let c1_leaf_bytes: u16 = self
            .c1_leaf_bytes_checked()?
            .try_into()
            .map_err(|_| CirclePcsShapeError::WidthOverflow)?;
        let c2_leaf_bytes: u16 = self
            .c2_leaf_bytes_checked()?
            .try_into()
            .map_err(|_| CirclePcsShapeError::WidthOverflow)?;
        let mut bytes = [0u8; CIRCLE_PCS_SHAPE_BYTES];
        bytes[0] = CIRCLE_PCS_SHAPE_VERSION;
        bytes[1] = self.trace_log_size;
        bytes[2] = self.domain_log_size;
        bytes[3] = CIRCLE_PCS_ARITY4_ROUNDS;
        bytes[4..6].copy_from_slice(&self.query_count.to_le_bytes());
        bytes[6] = self.opening_points;
        bytes[7] = CIRCLE_PCS_FIBER_SLOTS as u8;
        bytes[8..10].copy_from_slice(&self.c1_columns.to_le_bytes());
        bytes[10..12].copy_from_slice(&self.c2_columns.to_le_bytes());
        bytes[12..14].copy_from_slice(&c1_leaf_bytes.to_le_bytes());
        bytes[14..16].copy_from_slice(&c2_leaf_bytes.to_le_bytes());
        bytes[16] = self.c1_layer0_tag;
        bytes[17] = self.c2_layer0_tag;
        bytes[18..21].copy_from_slice(&self.later_layer_tags);
        Ok(bytes)
    }
}

/// Extraction-only root for checking the exact successful return value of
/// `CirclePcsShape::validate`. The production build does not enable this
/// feature, so this wrapper is absent from the deployed program.
#[cfg(feature = "formal-verification")]
pub fn formal_validate_shape(input: CirclePcsShape) -> Result<CirclePcsShape, CirclePcsShapeError> {
    input.validate()
}

pub fn prepare_circle_pcs_claims(
    shape: CirclePcsShape,
    gamma: QM31,
    evaluation_bytes: &[u8],
) -> Result<CirclePcsPreparedClaims, CirclePcsDecodeError> {
    let shape = shape.validate()?;
    let expected = shape.evaluation_bytes();
    if evaluation_bytes.len() != expected {
        return Err(CirclePcsDecodeError::EvaluationLength {
            expected,
            actual: evaluation_bytes.len(),
        });
    }
    let mut powers = Vec::with_capacity(shape.total_columns());
    let mut power = QM31::ONE;
    for column in 0..shape.total_columns() {
        powers.push(power);
        if column + 1 != shape.total_columns() {
            power = power.mul(gamma);
        }
    }
    let mut claims = Vec::with_capacity(usize::from(shape.opening_points));
    for point in 0..usize::from(shape.opening_points) {
        let mut claim = QM31::ZERO;
        for (column, power) in powers.iter().copied().enumerate() {
            let index = point * shape.total_columns() + column;
            let offset = index * 16;
            let value = QM31::from_le_bytes(&evaluation_bytes[offset..offset + 16])
                .ok_or(CirclePcsDecodeError::NonCanonicalEvaluation { index })?;
            claim = claim.add(power.mul(value));
        }
        claims.push(claim);
    }
    Ok(CirclePcsPreparedClaims { claims, powers })
}

pub fn gamma_combine_circle_pcs_layer0(
    shape: CirclePcsShape,
    c1_leaf: &[u8],
    c2_leaf: &[u8],
    powers: &[QM31],
) -> Result<[QM31; CIRCLE_PCS_FIBER_SLOTS], CirclePcsDecodeError> {
    let shape = shape.validate()?;
    let c1_expected = shape.c1_leaf_bytes_checked()?;
    let c2_expected = shape.c2_leaf_bytes_checked()?;
    if c1_leaf.len() != c1_expected {
        return Err(CirclePcsDecodeError::C1LeafLength {
            expected: c1_expected,
            actual: c1_leaf.len(),
        });
    }
    if c2_leaf.len() != c2_expected {
        return Err(CirclePcsDecodeError::C2LeafLength {
            expected: c2_expected,
            actual: c2_leaf.len(),
        });
    }
    if powers.len() != shape.total_columns() {
        return Err(CirclePcsDecodeError::EvaluationLength {
            expected: shape.total_columns() * 16,
            actual: powers.len() * 16,
        });
    }

    let mut combined = [QM31::ZERO; CIRCLE_PCS_FIBER_SLOTS];
    for (slot, output) in combined.iter_mut().enumerate() {
        for (column, power) in powers
            .iter()
            .copied()
            .take(usize::from(shape.c1_columns))
            .enumerate()
        {
            let offset = (slot * usize::from(shape.c1_columns) + column) * 4;
            let encoded: [u8; 4] = c1_leaf[offset..offset + 4].try_into().unwrap();
            let value = M31::from_le_bytes(encoded)
                .ok_or(CirclePcsDecodeError::NonCanonicalC1 { offset })?;
            *output = output.add(power.mul_m31(value));
        }
    }
    for helper in 0..usize::from(shape.c2_columns) {
        let power = powers[usize::from(shape.c1_columns) + helper];
        for (slot, output) in combined.iter_mut().enumerate() {
            let offset = (helper * CIRCLE_PCS_FIBER_SLOTS + slot) * 16;
            let value = QM31::from_le_bytes(&c2_leaf[offset..offset + 16])
                .ok_or(CirclePcsDecodeError::NonCanonicalC2 { offset })?;
            *output = output.add(power.mul(value));
        }
    }
    Ok(combined)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::field::CM31;

    const PROFILE24: CirclePcsShape = CirclePcsShape {
        trace_log_size: 10,
        domain_log_size: 19,
        query_count: 20,
        opening_points: 3,
        c1_columns: 16,
        c2_columns: 1,
        c1_layer0_tag: 0x50,
        c2_layer0_tag: 0xd0,
        later_layer_tags: [0x51, 0x52, 0x53],
    };

    fn q(value: u32) -> QM31 {
        QM31 {
            c0: CM31::new(M31(value), M31(value + 1)),
            c1: CM31::new(M31(value + 2), M31(value + 3)),
        }
    }

    #[test]
    fn profile24_shape_pins_widths_geometry_and_descriptor() {
        assert_eq!(PROFILE24.validate(), Ok(PROFILE24));
        assert_eq!(PROFILE24.message_len(), 1_024);
        assert_eq!(PROFILE24.codeword_len(), 1 << 19);
        assert_eq!(PROFILE24.fiber_count(), 1 << 17);
        assert_eq!(PROFILE24.total_columns(), 17);
        assert_eq!(PROFILE24.opening_count(), 51);
        assert_eq!(PROFILE24.evaluation_bytes(), 816);
        assert_eq!(PROFILE24.c1_leaf_bytes_checked(), Ok(256));
        assert_eq!(PROFILE24.c2_leaf_bytes_checked(), Ok(64));
        assert_eq!(
            PROFILE24.opening_geometry(),
            Ok(CircleOpeningGeometry {
                layer0_binary_depth: 17,
                later_binary_depths: [15, 13, 11],
            })
        );
        let encoded = PROFILE24.encode().unwrap();
        assert_eq!(&encoded[..8], &[1, 10, 19, 4, 20, 0, 3, 4]);
        assert_eq!(&encoded[12..16], &[0, 1, 64, 0]);
        assert_eq!(&encoded[16..21], &[0x50, 0xd0, 0x51, 0x52, 0x53]);
        assert_eq!(&encoded[21..], &[0, 0, 0]);
    }

    #[test]
    fn claims_and_opened_fiber_share_one_generator_order() {
        let gamma = q(5);
        let powers = prepare_circle_pcs_claims(PROFILE24, gamma, &[0u8; 816])
            .unwrap()
            .powers;
        let mut c1 = [0u8; 256];
        let mut c2 = [0u8; 64];
        let mut expected = [QM31::ZERO; 4];
        for (slot, expected_slot) in expected.iter_mut().enumerate() {
            for (column, power) in powers.iter().copied().take(16).enumerate() {
                let value = M31((slot * 19 + column + 1) as u32);
                let offset = (slot * 16 + column) * 4;
                c1[offset..offset + 4].copy_from_slice(&value.to_le_bytes());
                *expected_slot = expected_slot.add(power.mul_m31(value));
            }
            let helper = q(100 + slot as u32 * 7);
            helper.write_le_bytes(&mut c2[slot * 16..slot * 16 + 16]);
            *expected_slot = expected_slot.add(powers[16].mul(helper));
        }
        assert_eq!(
            gamma_combine_circle_pcs_layer0(PROFILE24, &c1, &c2, &powers),
            Ok(expected)
        );
    }

    #[test]
    fn malformed_shapes_fail_before_width_or_tag_use() {
        assert_eq!(
            CirclePcsShape {
                query_count: 0,
                ..PROFILE24
            }
            .validate(),
            Err(CirclePcsShapeError::EmptyQueries)
        );
        assert_eq!(
            CirclePcsShape {
                c2_layer0_tag: 0x50,
                ..PROFILE24
            }
            .validate(),
            Err(CirclePcsShapeError::DuplicateTreeTag { tag: 0x50 })
        );
    }
}

