struct CandidatePrefixTranscript {
    transcript: Transcript,
    result: CandidatePrefixScheduleResult,
}

/// Run the candidate host transcript only through `gamma`.
///
/// The function intentionally has no batching challenge and consumes no OOD,
/// sumcheck, final-polynomial, nonce, or opening bytes.
pub fn run_candidate_prefix_schedule_host(
    hash: HashFn,
    prefix: &CandidatePrefix<'_>,
    statement_digest: &[u8; 32],
    z: &[QM31; CANDIDATE_STATEMENT_POINT_COORDINATES],
) -> Result<CandidatePrefixScheduleResult, ChallengeSampleExhausted> {
    Ok(begin_candidate_prefix_schedule_host(hash, prefix, statement_digest, z)?.result)
}

fn begin_candidate_prefix_schedule_host(
    hash: HashFn,
    prefix: &CandidatePrefix<'_>,
    statement_digest: &[u8; 32],
    z: &[QM31; CANDIDATE_STATEMENT_POINT_COORDINATES],
) -> Result<CandidatePrefixTranscript, ChallengeSampleExhausted> {
    let mut transcript = Transcript::new(hash);
    transcript.absorb(label::PROFILE, prefix.header_bytes);
    transcript.absorb(label::M31_CIRCLE_BASIS, M31_CIRCLE_BASIS_DISCRIMINATOR);
    transcript.absorb(label::STATEMENT, statement_digest);

    let mut c1_root_record = [0u8; 1 + ROOT_LEN];
    c1_root_record[1..].copy_from_slice(prefix.c1_root);
    transcript.absorb(label::M31_CIRCLE_ROUND_ROOT, &c1_root_record);

    let lambda = transcript.challenge_qm31()?;
    let chi = transcript.challenge_qm31()?;

    transcript.absorb(label::M31_CIRCLE_C2_ROOT, prefix.c2_root);

    let points = encode_statement_points(z);
    transcript.absorb(label::M31_CIRCLE_STATEMENT_POINTS, &points);
    transcript.absorb(
        label::M31_CIRCLE_STATEMENT_EVALUATIONS,
        prefix.statement_evaluations_bytes,
    );
    let gamma = transcript.challenge_qm31()?;

    let result = CandidatePrefixScheduleResult {
        lambda,
        chi,
        gamma,
        state_after_gamma: transcript.diagnostic_state(),
    };
    Ok(CandidatePrefixTranscript { transcript, result })
}

pub fn encode_payment_statement_points(
    z: &[QM31; CANDIDATE_STATEMENT_POINT_COORDINATES],
) -> [u8; CANDIDATE_STATEMENT_POINT_COUNT * CANDIDATE_STATEMENT_POINT_COORDINATES * ENCODED_QM31_LEN]
{
    let mut shifted = *z;
    for bit in [0usize, 1, 3] {
        let coordinate = CANDIDATE_STATEMENT_POINT_COORDINATES - 1 - bit;
        shifted[coordinate] = QM31::ONE.sub(shifted[coordinate]);
    }
    let points = [*z, shifted];
    let mut bytes = [0u8; CANDIDATE_STATEMENT_POINT_COUNT
        * CANDIDATE_STATEMENT_POINT_COORDINATES
        * ENCODED_QM31_LEN];
    for (point, coordinates) in points.iter().enumerate() {
        for (coordinate, value) in coordinates.iter().enumerate() {
            let index = point * CANDIDATE_STATEMENT_POINT_COORDINATES + coordinate;
            value.write_le_bytes(&mut bytes[index * ENCODED_QM31_LEN..][..ENCODED_QM31_LEN]);
        }
    }
    bytes
}

/// Production prefix schedule: C1 -> (lambda,chi) -> C2 -> payment
/// zerocheck -> derived z -> 102 values -> gamma.
#[cfg(not(target_os = "solana"))]
pub fn run_payment_candidate_prefix_schedule_host(
    hash: HashFn,
    prefix: &PaymentCandidatePrefix<'_>,
    statement_digest: &[u8; 32],
) -> Result<PaymentCandidatePrefixScheduleResult, ChallengeSampleExhausted> {
    Ok(begin_payment_candidate_prefix_schedule_host(hash, prefix, statement_digest)?.1)
}

#[cfg(not(target_os = "solana"))]
fn begin_payment_candidate_prefix_schedule_host(
    hash: HashFn,
    prefix: &PaymentCandidatePrefix<'_>,
    statement_digest: &[u8; 32],
) -> Result<(Transcript, PaymentCandidatePrefixScheduleResult), ChallengeSampleExhausted> {
    let candidate = &prefix.candidate;
    let mut transcript = Transcript::new(hash);
    transcript.absorb(label::PROFILE, candidate.header_bytes);
    transcript.absorb(label::M31_CIRCLE_BASIS, M31_CIRCLE_BASIS_DISCRIMINATOR);
    transcript.absorb(label::STATEMENT, statement_digest);
    let mut c1_root_record = [0u8; 1 + ROOT_LEN];
    c1_root_record[1..].copy_from_slice(candidate.c1_root);
    transcript.absorb(label::M31_CIRCLE_ROUND_ROOT, &c1_root_record);
    let lambda = transcript.challenge_qm31()?;
    let chi = transcript.challenge_qm31()?;
    transcript.absorb(label::M31_CIRCLE_C2_ROOT, candidate.c2_root);
    let batching = begin_payment_zerocheck(&mut transcript)?;
    let messages = prefix
        .payment_sumcheck_messages()
        .expect("parser validated payment sumcheck fields");
    let verified = verify_payment_sumcheck_messages(&mut transcript, &messages)?;
    let z = verified.point;
    transcript.absorb(
        label::M31_CIRCLE_STATEMENT_POINTS,
        &encode_payment_statement_points(&z),
    );
    transcript.absorb(
        label::M31_CIRCLE_STATEMENT_EVALUATIONS,
        candidate.statement_evaluations_bytes,
    );
    let gamma = transcript.challenge_qm31()?;
    let result = PaymentCandidatePrefixScheduleResult {
        lambda,
        chi,
        batching,
        z,
        payment_terminal_claim: verified.terminal_claim,
        gamma,
        state_after_gamma: transcript.diagnostic_state(),
    };
    Ok((transcript, result))
}

#[cfg(not(target_os = "solana"))]
pub fn run_payment_candidate_transcript_schedule_host<const QUERY_COUNT: usize>(
    hash: HashFn,
    prefix: &PaymentCandidatePrefix<'_>,
    statement_digest: &[u8; 32],
) -> Result<PaymentCandidateTranscriptScheduleResult<QUERY_COUNT>, CandidateTranscriptScheduleError>
{
    if QUERY_COUNT != usize::from(RATE16_PAYMENT_CANDIDATE_SHAPE.query_count) {
        return Err(CandidateTranscriptScheduleError::ChallengeSampleExhausted);
    }
    let (mut transcript, prefix_result) =
        begin_payment_candidate_prefix_schedule_host(hash, prefix, statement_digest)?;
    let kappa = transcript.challenge_qm31()?;
    let second_point_scale = kappa;
    let candidate = &prefix.candidate;
    let mut circle_ood_points = [SecureCirclePoint {
        x: QM31::ZERO,
        y: QM31::ZERO,
    }; CANDIDATE_OOD_SAMPLES];
    let mut line_ood_points = [[QM31::ZERO; CANDIDATE_OOD_SAMPLES]; CANDIDATE_ROUND_COUNT - 1];
    let mut mu = [[QM31::ZERO; CANDIDATE_OOD_SAMPLES]; CANDIDATE_ROUND_COUNT];
    let mut alpha = [QM31::ZERO; CANDIDATE_ROUND_COUNT];

    for sample in 0..CANDIDATE_OOD_SAMPLES {
        circle_ood_points[sample] = transcript.challenge_secure_circle_point()?;
        absorb_candidate_ood_value(
            &mut transcript,
            label::M31_CIRCLE_OOD_VALUE,
            0,
            sample,
            candidate.rounds[0].ood_value(sample).unwrap(),
        );
        mu[0][sample] = transcript.challenge_qm31()?;
    }
    absorb_candidate_sumcheck(&mut transcript, &candidate.rounds[0]);
    check_and_absorb_candidate_fold_pow(
        &mut transcript,
        candidate,
        CandidateOneLaneBatchingMode::FreshKappa,
        0,
    )?;
    alpha[0] = transcript.challenge_qm31()?;

    for layer in 1..CANDIDATE_ROUND_COUNT {
        absorb_candidate_round_root(
            &mut transcript,
            layer,
            candidate.rounds[layer].root.unwrap(),
        );
        for sample in 0..CANDIDATE_OOD_SAMPLES {
            line_ood_points[layer - 1][sample] = transcript.challenge_ood_qm31()?;
            absorb_candidate_ood_value(
                &mut transcript,
                label::M31_LINE_OOD_VALUE,
                layer,
                sample,
                candidate.rounds[layer].ood_value(sample).unwrap(),
            );
            mu[layer][sample] = transcript.challenge_qm31()?;
        }
        absorb_candidate_sumcheck(&mut transcript, &candidate.rounds[layer]);
        check_and_absorb_candidate_fold_pow(
            &mut transcript,
            candidate,
            CandidateOneLaneBatchingMode::FreshKappa,
            layer,
        )?;
        alpha[layer] = transcript.challenge_qm31()?;
    }
    absorb_candidate_final(&mut transcript, candidate);
    let state_before_grinding = transcript.diagnostic_state();
    if !transcript.grinding_ok(
        candidate.nonce,
        RATE16_PAYMENT_CANDIDATE_SHAPE.grinding_bits,
    ) {
        return Err(CandidateTranscriptScheduleError::GrindingRejected);
    }
    transcript.absorb(label::GRIND_NONCE, &candidate.nonce.to_le_bytes());
    let query_log_size = candidate.header.log_rows + candidate.header.log_blowup - 2;
    let queries: [u32; QUERY_COUNT] = transcript
        .challenge_queries(QUERY_COUNT, 1u32 << query_log_size)
        .try_into()
        .unwrap();
    Ok(PaymentCandidateTranscriptScheduleResult {
        prefix: prefix_result,
        kappa,
        second_point_scale,
        circle_ood_points,
        line_ood_points,
        mu,
        alpha,
        state_before_grinding,
        queries,
        state_after_queries: transcript.diagnostic_state(),
    })
}

/// The two one-lane shapes retained for transcript-tail comparison. Their
/// presence here is diagnostic evidence, not a protocol selection.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum CandidateOneLaneBatchingMode {
    FreshKappa,
    DisjointGamma51,
}

impl CandidateOneLaneBatchingMode {
    pub const ALL: [Self; 2] = [Self::FreshKappa, Self::DisjointGamma51];
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum CandidateTranscriptScheduleError {
    ChallengeSampleExhausted,
    CirclePointSample(CirclePointSampleError),
    LinePointSample(OodSampleError),
    QuerySample(QuerySampleError),
    BatchGrindingRejected,
    GrindingRejected,
    FoldGrindingRejected { round: usize },
}

impl From<ChallengeSampleExhausted> for CandidateTranscriptScheduleError {
    fn from(_: ChallengeSampleExhausted) -> Self {
        Self::ChallengeSampleExhausted
    }
}

impl From<CirclePointSampleError> for CandidateTranscriptScheduleError {
    fn from(error: CirclePointSampleError) -> Self {
        Self::CirclePointSample(error)
    }
}

impl From<OodSampleError> for CandidateTranscriptScheduleError {
    fn from(error: OodSampleError) -> Self {
        Self::LinePointSample(error)
    }
}

impl From<QuerySampleError> for CandidateTranscriptScheduleError {
    fn from(error: QuerySampleError) -> Self {
        Self::QuerySample(error)
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct CandidateTranscriptScheduleResult<
    const QUERY_COUNT: usize = { CANDIDATE_QUERY_COUNT as usize },
> {
    pub prefix: CandidatePrefixScheduleResult,
    pub batching_mode: CandidateOneLaneBatchingMode,
    /// Present only for the fresh-kappa diagnostic shape.
    pub kappa: Option<QM31>,
    /// `kappa` or `gamma^51`, according to the diagnostic shape.
    pub second_point_scale: QM31,
    pub circle_ood_points: [SecureCirclePoint; CANDIDATE_OOD_SAMPLES],
    pub line_ood_points: [[QM31; CANDIDATE_OOD_SAMPLES]; CANDIDATE_ROUND_COUNT - 1],
    pub mu: [[QM31; CANDIDATE_OOD_SAMPLES]; CANDIDATE_ROUND_COUNT],
    pub alpha: [QM31; CANDIDATE_ROUND_COUNT],
    pub state_before_grinding: [u8; 32],
    pub queries: [u32; QUERY_COUNT],
    pub state_after_queries: [u8; 32],
}

#[derive(Clone, Copy)]
struct CandidateTailChallenges {
    prefix: CandidatePrefixScheduleResult,
    batching_mode: CandidateOneLaneBatchingMode,
    kappa: Option<QM31>,
    second_point_scale: QM31,
    circle_ood_points: [SecureCirclePoint; CANDIDATE_OOD_SAMPLES],
    line_ood_points: [[QM31; CANDIDATE_OOD_SAMPLES]; CANDIDATE_ROUND_COUNT - 1],
    mu: [[QM31; CANDIDATE_OOD_SAMPLES]; CANDIDATE_ROUND_COUNT],
    alpha: [QM31; CANDIDATE_ROUND_COUNT],
}

/// Continue the candidate host transcript through the complete fixed schedule.
///
/// This is transcript evidence only. It verifies the grinding witness because
/// query positions are unavailable before that check, but performs no Merkle,
/// OOD-value, sumcheck, fold, terminal, or statement relation verification.
pub fn run_candidate_transcript_schedule_host(
    hash: HashFn,
    prefix: &CandidatePrefix<'_>,
    statement_digest: &[u8; 32],
    z: &[QM31; CANDIDATE_STATEMENT_POINT_COORDINATES],
    batching_mode: CandidateOneLaneBatchingMode,
) -> Result<CandidateTranscriptScheduleResult, CandidateTranscriptScheduleError> {
    run_candidate_transcript_schedule_host_for_shape::<{ CANDIDATE_QUERY_COUNT as usize }>(
        hash,
        prefix,
        statement_digest,
        z,
        batching_mode,
        CANDIDATE_GRINDING_BITS,
    )
}

pub fn run_candidate_transcript_schedule_host_for_shape<const QUERY_COUNT: usize>(
    hash: HashFn,
    prefix: &CandidatePrefix<'_>,
    statement_digest: &[u8; 32],
    z: &[QM31; CANDIDATE_STATEMENT_POINT_COORDINATES],
    batching_mode: CandidateOneLaneBatchingMode,
    grinding_bits: u8,
) -> Result<CandidateTranscriptScheduleResult<QUERY_COUNT>, CandidateTranscriptScheduleError> {
    let (mut transcript, challenges) =
        candidate_transcript_before_grinding(hash, prefix, statement_digest, z, batching_mode)?;
    let state_before_grinding = transcript.diagnostic_state();
    if !transcript.grinding_ok(prefix.nonce, grinding_bits) {
        return Err(CandidateTranscriptScheduleError::GrindingRejected);
    }
    transcript.absorb(label::GRIND_NONCE, &prefix.nonce.to_le_bytes());
    let query_log_size = prefix
        .header
        .log_rows
        .checked_add(prefix.header.log_blowup)
        .and_then(|value| value.checked_sub(2))
        .unwrap();
    let queries: [u32; QUERY_COUNT] = transcript
        .challenge_queries(QUERY_COUNT, 1u32 << query_log_size)
        .try_into()
        .unwrap();

    Ok(CandidateTranscriptScheduleResult {
        prefix: challenges.prefix,
        batching_mode: challenges.batching_mode,
        kappa: challenges.kappa,
        second_point_scale: challenges.second_point_scale,
        circle_ood_points: challenges.circle_ood_points,
        line_ood_points: challenges.line_ood_points,
        mu: challenges.mu,
        alpha: challenges.alpha,
        state_before_grinding,
        queries,
        state_after_queries: transcript.diagnostic_state(),
    })
}

fn candidate_transcript_before_grinding(
    hash: HashFn,
    prefix: &CandidatePrefix<'_>,
    statement_digest: &[u8; 32],
    z: &[QM31; CANDIDATE_STATEMENT_POINT_COORDINATES],
    batching_mode: CandidateOneLaneBatchingMode,
) -> Result<(Transcript, CandidateTailChallenges), CandidateTranscriptScheduleError> {
    let CandidatePrefixTranscript {
        mut transcript,
        result: prefix_result,
    } = begin_candidate_prefix_schedule_host(hash, prefix, statement_digest, z)?;

    let kappa = match batching_mode {
        CandidateOneLaneBatchingMode::FreshKappa => Some(transcript.challenge_qm31()?),
        CandidateOneLaneBatchingMode::DisjointGamma51 => None,
    };
    let second_point_scale = kappa.unwrap_or_else(|| prefix_result.gamma.pow(51));

    let mut circle_ood_points = [SecureCirclePoint {
        x: QM31::ZERO,
        y: QM31::ZERO,
    }; CANDIDATE_OOD_SAMPLES];
    let mut line_ood_points = [[QM31::ZERO; CANDIDATE_OOD_SAMPLES]; CANDIDATE_ROUND_COUNT - 1];
    let mut mu = [[QM31::ZERO; CANDIDATE_OOD_SAMPLES]; CANDIDATE_ROUND_COUNT];
    let mut alpha = [QM31::ZERO; CANDIDATE_ROUND_COUNT];

    for sample in 0..CANDIDATE_OOD_SAMPLES {
        circle_ood_points[sample] = transcript.challenge_secure_circle_point()?;
        absorb_candidate_ood_value(
            &mut transcript,
            label::M31_CIRCLE_OOD_VALUE,
            0,
            sample,
            prefix.rounds[0].ood_value(sample).unwrap(),
        );
        mu[0][sample] = transcript.challenge_qm31()?;
    }
    absorb_candidate_sumcheck(&mut transcript, &prefix.rounds[0]);
    check_and_absorb_candidate_fold_pow(&mut transcript, prefix, batching_mode, 0)?;
    alpha[0] = transcript.challenge_qm31()?;

    for layer in 1..CANDIDATE_ROUND_COUNT {
        absorb_candidate_round_root(&mut transcript, layer, prefix.rounds[layer].root.unwrap());
        for sample in 0..CANDIDATE_OOD_SAMPLES {
            line_ood_points[layer - 1][sample] = transcript.challenge_ood_qm31()?;
            absorb_candidate_ood_value(
                &mut transcript,
                label::M31_LINE_OOD_VALUE,
                layer,
                sample,
                prefix.rounds[layer].ood_value(sample).unwrap(),
            );
            mu[layer][sample] = transcript.challenge_qm31()?;
        }
        absorb_candidate_sumcheck(&mut transcript, &prefix.rounds[layer]);
        check_and_absorb_candidate_fold_pow(&mut transcript, prefix, batching_mode, layer)?;
        alpha[layer] = transcript.challenge_qm31()?;
    }

    absorb_candidate_final(&mut transcript, prefix);
    Ok((
        transcript,
        CandidateTailChallenges {
            prefix: prefix_result,
            batching_mode,
            kappa,
            second_point_scale,
            circle_ood_points,
            line_ood_points,
            mu,
            alpha,
        },
    ))
}

fn check_and_absorb_candidate_fold_pow(
    transcript: &mut Transcript,
    prefix: &CandidatePrefix<'_>,
    _batching_mode: CandidateOneLaneBatchingMode,
    round: usize,
) -> Result<(), CandidateTranscriptScheduleError> {
    // The profile id in the already-absorbed header uniquely selects this
    // difficulty schedule. A zero-difficulty legacy shape carries no nonce
    // record, preserving every historical transcript byte-for-byte.
    let shape = match prefix.header.profile_id {
        RATE16_HARDENED_CANDIDATE_PROFILE_ID => RATE16_HARDENED_CANDIDATE_SHAPE,
        RATE16_PAYMENT_CANDIDATE_PROFILE_ID => RATE16_PAYMENT_CANDIDATE_SHAPE,
        _ => return Ok(()),
    };
    let bits = shape.fold_pow_bits[round];
    let nonce = prefix.fold_nonces[round];
    if !transcript.grinding_ok(nonce, bits) {
        return Err(CandidateTranscriptScheduleError::FoldGrindingRejected { round });
    }
    absorb_candidate_fold_pow(transcript, round, nonce);
    Ok(())
}

fn absorb_candidate_fold_pow(transcript: &mut Transcript, round: usize, nonce: u64) {
    let mut record = [0u8; 1 + CANDIDATE_NONCE_LEN];
    record[0] = round as u8;
    record[1..].copy_from_slice(&nonce.to_le_bytes());
    transcript.absorb(label::M31_CIRCLE_FOLD_POW_NONCE, &record);
}

fn absorb_candidate_round_root(transcript: &mut Transcript, layer: usize, root: &[u8; ROOT_LEN]) {
    let mut record = [0u8; 1 + ROOT_LEN];
    record[0] = layer as u8;
    record[1..].copy_from_slice(root);
    transcript.absorb(label::M31_CIRCLE_ROUND_ROOT, &record);
}

fn absorb_candidate_ood_value(
    transcript: &mut Transcript,
    ood_label: u8,
    layer: usize,
    sample: usize,
    value: QM31,
) {
    let mut record = [0u8; 2 + ENCODED_QM31_LEN];
    record[0] = layer as u8;
    record[1] = sample as u8;
    value.write_le_bytes(&mut record[2..]);
    transcript.absorb(ood_label, &record);
}

fn absorb_candidate_sumcheck(transcript: &mut Transcript, round: &CandidateRoundRecord<'_>) {
    let mut record = [0u8; 1 + SUMCHECK_BYTES];
    record[0] = round.layer;
    for coefficient in 0..SUMCHECK_COEFFICIENTS {
        round
            .sumcheck_coefficient(coefficient)
            .unwrap()
            .write_le_bytes(
                &mut record
                    [1 + coefficient * ENCODED_QM31_LEN..1 + (coefficient + 1) * ENCODED_QM31_LEN],
            );
    }
    transcript.absorb(label::M31_CIRCLE_RELATION_SUMCHECK, &record);
}

fn absorb_candidate_final(transcript: &mut Transcript, prefix: &CandidatePrefix<'_>) {
    let mut coefficients = [0u8; CANDIDATE_FINAL_POLY_BYTES];
    for index in 0..CANDIDATE_FINAL_POLY_LEN {
        prefix.final_coefficient(index).unwrap().write_le_bytes(
            &mut coefficients[index * ENCODED_QM31_LEN..(index + 1) * ENCODED_QM31_LEN],
        );
    }
    transcript.absorb(label::M31_CIRCLE_FINAL_TENSOR_POLY, &coefficients);
}

fn encode_statement_points(
    z: &[QM31; CANDIDATE_STATEMENT_POINT_COORDINATES],
) -> [u8; CANDIDATE_STATEMENT_POINT_COUNT * CANDIDATE_STATEMENT_POINT_COORDINATES * ENCODED_QM31_LEN]
{
    let mut points = [0u8; CANDIDATE_STATEMENT_POINT_COUNT
        * CANDIDATE_STATEMENT_POINT_COORDINATES
        * ENCODED_QM31_LEN];
    for (index, value) in z.iter().enumerate() {
        value.write_le_bytes(&mut points[index * ENCODED_QM31_LEN..][..ENCODED_QM31_LEN]);
    }
    for (index, value) in z.iter().enumerate() {
        let value = if index >= CANDIDATE_STATEMENT_POINT_COORDINATES - 2 {
            QM31::ONE.sub(*value)
        } else {
            *value
        };
        let point_index = CANDIDATE_STATEMENT_POINT_COORDINATES + index;
        value.write_le_bytes(&mut points[point_index * ENCODED_QM31_LEN..][..ENCODED_QM31_LEN]);
    }
    points
}

/// Bind the external point pair and the proof-carried 102-value block to the
/// tag-24 instruction argument. This diagnostic digest is not a payment
/// statement and does not replace transcript absorption of the same bytes.
pub fn candidate_statement_evaluations_digest(
    hash: HashFn,
    z: &[QM31; CANDIDATE_STATEMENT_POINT_COORDINATES],
    statement_evaluations_bytes: &[u8; CANDIDATE_STATEMENT_EVALUATIONS_LEN],
) -> [u8; 32] {
    let points = encode_statement_points(z);
    hash(&[
        CANDIDATE_STATEMENT_EVALUATIONS_DIGEST_DOMAIN,
        &points,
        statement_evaluations_bytes,
    ])
}

crates/aspis-core/src/circle_query.rs:
//! Fixed per-query arithmetic consistency for the M31 circle candidate.
//!
//! The caller supplies leaves that were authenticated elsewhere. This module
//! only canonical-decodes their fixed layouts, gamma-combines layer zero,
//! follows one query through four normalized arity-4 folds, and checks the
//! natural-order terminal tensor. It does not parse a proof, authenticate a
//! Merkle path, drive a transcript, enable tag 24, or accept a proof.

use crate::circle_fri::{
    evaluate_final_line_tensor, evaluate_final_line_tensor_ref, fixed_line_domain_x,
    map_fixed_query, normalized_circle_to_line_arity4_at_fiber,
    normalized_circle_to_line_arity4_prepared,
    normalized_circle_to_line_arity4_prepared_multipliers,
    normalized_circle_to_line_arity4_prepared_polynomial_candidate,
    normalized_line_arity4_at_fiber, normalized_line_arity4_prepared,
    normalized_line_arity4_prepared_multipliers, normalized_line_arity4_prepared_polynomial_refs,
    CircleFriError, FixedQueryPath, FIXED_ARITY4_ROUNDS, FIXED_FINAL_LINE_LAYER,
    FIXED_QUERY_FIBER_COUNT,
};
use crate::field::{
    qm31_m31_dot4_prepared_limbs49_bytes, qm31_power_table, PreparedQm31Multiplier, CM31, M31, P,
    QM31,
};
use crate::proof::{M31_CIRCLE_C1_COLUMNS, M31_CIRCLE_C1_FIBER_LEN, SECOND_PHASE_LEAF_LEN_V4_S2};

pub const CIRCLE_QUERY_C1_LEAF_BYTES: usize = M31_CIRCLE_C1_FIBER_LEN;
pub const CIRCLE_QUERY_C2_LEAF_BYTES: usize = SECOND_PHASE_LEAF_LEN_V4_S2;
pub const CIRCLE_QUERY_LATER_LEAF_BYTES: usize = 4 * 16;
pub const CIRCLE_QUERY_LATER_LAYERS: usize = 3;
pub const CIRCLE_QUERY_C1_SLOT_BYTES: usize = M31_CIRCLE_C1_COLUMNS * 4;
pub const CIRCLE_QUERY_C2_HELPER_BYTES: usize = 4 * 16;
pub const CIRCLE_QUERY_QM31_BYTES: usize = 16;
pub const CIRCLE_QUERY_TOTAL_COLUMNS: usize = M31_CIRCLE_C1_COLUMNS + 2;

/// Byte offset of one M31 C1 symbol inside the slot-major layer-zero leaf.
pub const fn c1_symbol_offset(slot: usize, column: usize) -> Option<usize> {
    if slot < 4 && column < M31_CIRCLE_C1_COLUMNS {
        Some((slot * M31_CIRCLE_C1_COLUMNS + column) * 4)
    } else {
        None
    }
}

/// Byte offset of one QM31 C2 symbol inside the helper-major layer-zero leaf.
pub const fn c2_symbol_offset(helper: usize, slot: usize) -> Option<usize> {
    if helper < 2 && slot < 4 {
        Some((helper * 4 + slot) * CIRCLE_QUERY_QM31_BYTES)
    } else {
        None
    }
}

/// Byte offset of one QM31 slot inside any later 64-byte leaf.
pub const fn later_slot_offset(slot: usize) -> Option<usize> {
    if slot < 4 {
        Some(slot * CIRCLE_QUERY_QM31_BYTES)
    } else {
        None
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum CircleQueryLeaf {
    C1,
    C2,
    Later(u8),
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum CircleQueryError {
    QueryOutOfRange {
        query: usize,
    },
    LeafLength {
        leaf: CircleQueryLeaf,
        expected: usize,
        actual: usize,
    },
    NonCanonicalM31 {
        offset: usize,
    },
    NonCanonicalQm31 {
        leaf: CircleQueryLeaf,
        offset: usize,
    },
    C1KernelInvariant,
    LayerValueMismatch {
        layer: u8,
        offset: usize,
    },
    TerminalValueMismatch {
        final_index: usize,
    },
    Fold(CircleFriError),
}

impl From<CircleFriError> for CircleQueryError {
    fn from(error: CircleFriError) -> Self {
        Self::Fold(error)
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct CircleQueryCheck {
    pub path: FixedQueryPath,
    pub combined_layer0: [QM31; 4],
    /// Matched values at layers 1, 2, and 3, followed by the terminal value.
    pub folded_values: [QM31; FIXED_ARITY4_ROUNDS as usize],
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct CircleQueryGammaPowers {
    pub c1_limbs: [[u32; 4]; M31_CIRCLE_C1_COLUMNS],
    pub helpers: [PreparedQm31Multiplier; 2],
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct CircleQueryFoldInverses {
    pub circle: [M31; 2],
    pub later: [[M31; 3]; CIRCLE_QUERY_LATER_LAYERS],
    pub final_x: M31,
}

impl CircleQueryGammaPowers {
    pub fn new(gamma: QM31) -> Self {
        let powers = qm31_power_table::<CIRCLE_QUERY_TOTAL_COLUMNS>(gamma);
        Self::from_full_table(&powers)
    }

    pub fn from_full_table(powers: &[QM31; CIRCLE_QUERY_TOTAL_COLUMNS]) -> Self {
        let c1: [QM31; M31_CIRCLE_C1_COLUMNS] = core::array::from_fn(|index| powers[index]);
        Self {
            c1_limbs: c1.map(|weight| [weight.c0.a.0, weight.c0.b.0, weight.c1.a.0, weight.c1.b.0]),
            helpers: [
                PreparedQm31Multiplier::new(powers[M31_CIRCLE_C1_COLUMNS]),
                PreparedQm31Multiplier::new(powers[M31_CIRCLE_C1_COLUMNS + 1]),
            ],
        }
    }
}

fn check_leaf_length(
    leaf: &[u8],
    kind: CircleQueryLeaf,
    expected: usize,
) -> Result<(), CircleQueryError> {
    if leaf.len() != expected {
        return Err(CircleQueryError::LeafLength {
            leaf: kind,
            expected,
            actual: leaf.len(),
        });
    }
    Ok(())
}

fn first_noncanonical_m31_offset(bytes: &[u8]) -> Option<usize> {
    bytes
        .chunks_exact(4)
        .enumerate()
        .find_map(|(index, bytes)| {
            M31::from_le_bytes(bytes.try_into().ok()?)
                .is_none()
                .then_some(index * 4)
        })
}

pub(crate) fn canonical_m31_leaf_error(bytes: &[u8]) -> CircleQueryError {
    match first_noncanonical_m31_offset(bytes) {
        Some(offset) => CircleQueryError::NonCanonicalM31 { offset },
        None => CircleQueryError::C1KernelInvariant,
    }
}

/// Decode and gamma-combine one exact layer-zero C1/C2 pair.
///
/// C1 is slot-major with powers `0..=48`; C2 is helper-major with powers 49
/// and 50. The fused C1 byte kernel still reports the first invalid byte
/// offset through an explicit canonicality scan on rejection.
pub fn gamma_combine_fixed_layer0(
    c1_leaf: &[u8],
    c2_leaf: &[u8],
    gamma: QM31,
) -> Result<[QM31; 4], CircleQueryError> {
    let powers = CircleQueryGammaPowers::new(gamma);
    gamma_combine_fixed_layer0_prepared(c1_leaf, c2_leaf, &powers)
}

pub fn gamma_combine_fixed_layer0_prepared(
    c1_leaf: &[u8],
    c2_leaf: &[u8],
    powers: &CircleQueryGammaPowers,
) -> Result<[QM31; 4], CircleQueryError> {
    check_leaf_length(c1_leaf, CircleQueryLeaf::C1, CIRCLE_QUERY_C1_LEAF_BYTES)?;
    check_leaf_length(c2_leaf, CircleQueryLeaf::C2, CIRCLE_QUERY_C2_LEAF_BYTES)?;

    let mut combined = match qm31_m31_dot4_prepared_limbs49_bytes(&powers.c1_limbs, c1_leaf) {
        Some(combined) => combined,
        None => return Err(canonical_m31_leaf_error(c1_leaf)),
    };
    for (helper, power) in powers.helpers.into_iter().enumerate() {
        for (slot, value) in combined.iter_mut().enumerate() {
            let offset = (helper * 4 + slot) * CIRCLE_QUERY_QM31_BYTES;
            let symbol = QM31::from_le_bytes(&c2_leaf[offset..offset + CIRCLE_QUERY_QM31_BYTES])
                .ok_or(CircleQueryError::NonCanonicalQm31 {
                    leaf: CircleQueryLeaf::C2,
                    offset,
                })?;
            *value = value.add(power.mul(symbol));
        }
    }
    Ok(combined)
}

fn decode_later_leaf(leaf: &[u8], layer: u8) -> Result<[QM31; 4], CircleQueryError> {
    let kind = CircleQueryLeaf::Later(layer);
    check_leaf_length(leaf, kind, CIRCLE_QUERY_LATER_LEAF_BYTES)?;
    let mut values = [QM31::ZERO; 4];
    for (slot, value) in values.iter_mut().enumerate() {
        let offset = slot * CIRCLE_QUERY_QM31_BYTES;
        let encoded = &leaf[offset..offset + CIRCLE_QUERY_QM31_BYTES];
        let limbs = [
            u32::from_le_bytes(encoded[0..4].try_into().unwrap()),
            u32::from_le_bytes(encoded[4..8].try_into().unwrap()),
            u32::from_le_bytes(encoded[8..12].try_into().unwrap()),
            u32::from_le_bytes(encoded[12..16].try_into().unwrap()),
        ];
        if limbs.iter().any(|&limb| limb >= P) {
            return Err(CircleQueryError::NonCanonicalQm31 { leaf: kind, offset });
        }
        *value = QM31 {
            c0: CM31::new(M31(limbs[0]), M31(limbs[1])),
            c1: CM31::new(M31(limbs[2]), M31(limbs[3])),
        };
    }
    Ok(values)
}

/// Validate a complete later leaf in the same slot order as
/// `decode_later_leaf`, but materialize only the slot consumed by this
/// transition.  Rejection priority and offsets remain byte-for-byte equal to
/// the full decoder; the other three canonical values are simply not copied
/// into a dead array.
fn decode_selected_later_slot(
    leaf: &[u8],
    layer: u8,
    selected_slot: usize,
) -> Result<QM31, CircleQueryError> {
    let kind = CircleQueryLeaf::Later(layer);
    check_leaf_length(leaf, kind, CIRCLE_QUERY_LATER_LEAF_BYTES)?;
    if selected_slot >= 4 {
        return Err(CircleQueryError::QueryOutOfRange {
            query: selected_slot,
        });
    }
    let mut selected = [0u32; 4];
    for slot in 0..4 {
        let offset = slot * CIRCLE_QUERY_QM31_BYTES;
        let encoded = &leaf[offset..offset + CIRCLE_QUERY_QM31_BYTES];
        let limbs = [
            u32::from_le_bytes(encoded[0..4].try_into().unwrap()),
            u32::from_le_bytes(encoded[4..8].try_into().unwrap()),
            u32::from_le_bytes(encoded[8..12].try_into().unwrap()),
            u32::from_le_bytes(encoded[12..16].try_into().unwrap()),
        ];
        if limbs.iter().any(|&limb| limb >= P) {
            return Err(CircleQueryError::NonCanonicalQm31 { leaf: kind, offset });
        }
        if slot == selected_slot {
            selected = limbs;
        }
    }
    Ok(QM31 {
        c0: CM31::new(M31(selected[0]), M31(selected[1])),
        c1: CM31::new(M31(selected[2]), M31(selected[3])),
    })
}

/// Verification-only entry point for the exact private decoder above.
///
/// This is absent from normal verifier builds.  The isolated Kani package
/// enables `formal-verification` to compare the unchanged production decoder
/// universally with a loop-free reference that Charon/Aeneas can translate.
#[cfg(feature = "formal-verification")]
#[doc(hidden)]
pub fn formal_decode_later_leaf(leaf: &[u8], layer: u8) -> Result<[QM31; 4], CircleQueryError> {
    decode_later_leaf(leaf, layer)
}

/// Verification-only entry point for the exact selected-slot decoder above.
#[cfg(feature = "formal-verification")]
#[doc(hidden)]
pub fn formal_decode_selected_later_slot(
    leaf: &[u8],
    layer: u8,
    selected_slot: usize,
) -> Result<QM31, CircleQueryError> {
    decode_selected_later_slot(leaf, layer, selected_slot)
}

fn require_layer_value(
    layer: u8,
    leaf: &[QM31; 4],
    slot: u8,
    expected: QM31,
) -> Result<(), CircleQueryError> {
    if leaf[usize::from(slot)] != expected {
        return Err(CircleQueryError::LayerValueMismatch {
            layer,
            offset: usize::from(slot) * CIRCLE_QUERY_QM31_BYTES,
        });
    }
    Ok(())
}

/// Check one fixed query's arithmetic chain through the circle candidate.
///
/// The three later leaves must already correspond to authenticated leaf
/// indices `q>>2`, `q>>4`, and `q>>6`; this function checks the slots selected
/// by the intervening two-bit chunks. Merkle authentication and leaf-index
/// binding remain the caller's responsibility.
pub fn check_fixed_circle_query(
    c1_leaf: &[u8],
    c2_leaf: &[u8],
    later_leaves: [&[u8]; CIRCLE_QUERY_LATER_LAYERS],
    query: usize,
    gamma: QM31,
    alphas: [QM31; FIXED_ARITY4_ROUNDS as usize],
    final_natural: [QM31; 4],
) -> Result<CircleQueryCheck, CircleQueryError> {
    let powers = CircleQueryGammaPowers::new(gamma);
    check_fixed_circle_query_prepared(
        c1_leaf,
        c2_leaf,
        later_leaves,
        query,
        &powers,
        alphas,
        final_natural,
    )
}

pub fn check_fixed_circle_query_prepared(
    c1_leaf: &[u8],
    c2_leaf: &[u8],
    later_leaves: [&[u8]; CIRCLE_QUERY_LATER_LAYERS],
    query: usize,
    powers: &CircleQueryGammaPowers,
    alphas: [QM31; FIXED_ARITY4_ROUNDS as usize],
    final_natural: [QM31; 4],
) -> Result<CircleQueryCheck, CircleQueryError> {
    if query >= FIXED_QUERY_FIBER_COUNT {
        return Err(CircleQueryError::QueryOutOfRange { query });
    }
    let path = map_fixed_query(query)?;
    let combined_layer0 = gamma_combine_fixed_layer0_prepared(c1_leaf, c2_leaf, powers)?;
    let later = [
        decode_later_leaf(later_leaves[0], 1)?,
        decode_later_leaf(later_leaves[1], 2)?,
        decode_later_leaf(later_leaves[2], 3)?,
    ];

    let layer1 =
        normalized_circle_to_line_arity4_at_fiber(combined_layer0, alphas[0], path.layer0_fiber)?;
    require_layer_value(1, &later[0], path.later[0].slot, layer1)?;

    let layer2 = normalized_line_arity4_at_fiber(later[0], alphas[1], 1, path.later[0].leaf)?;
    require_layer_value(2, &later[1], path.later[1].slot, layer2)?;

    let layer3 = normalized_line_arity4_at_fiber(later[1], alphas[2], 2, path.later[1].leaf)?;
    require_layer_value(3, &later[2], path.later[2].slot, layer3)?;

    let terminal = normalized_line_arity4_at_fiber(later[2], alphas[3], 3, path.later[2].leaf)?;
    let final_x = fixed_line_domain_x(FIXED_FINAL_LINE_LAYER, path.final_index)?;
    if evaluate_final_line_tensor(final_natural, final_x) != terminal {
        return Err(CircleQueryError::TerminalValueMismatch {
            final_index: path.final_index,
        });
    }

    Ok(CircleQueryCheck {
        path,
        combined_layer0,
        folded_values: [layer1, layer2, layer3, terminal],
    })
}

pub fn check_fixed_circle_query_fully_prepared(
    c1_leaf: &[u8],
    c2_leaf: &[u8],
    later_leaves: [&[u8]; CIRCLE_QUERY_LATER_LAYERS],
    query: usize,
    powers: &CircleQueryGammaPowers,
    inverses: CircleQueryFoldInverses,
    alphas: [QM31; FIXED_ARITY4_ROUNDS as usize],
    final_natural: [QM31; 4],
) -> Result<CircleQueryCheck, CircleQueryError> {
    if query >= FIXED_QUERY_FIBER_COUNT {
        return Err(CircleQueryError::QueryOutOfRange { query });
    }
    let path = map_fixed_query(query)?;
    let combined_layer0 = gamma_combine_fixed_layer0_prepared(c1_leaf, c2_leaf, powers)?;
    let later = [
        decode_later_leaf(later_leaves[0], 1)?,
        decode_later_leaf(later_leaves[1], 2)?,
        decode_later_leaf(later_leaves[2], 3)?,
    ];

    let layer1 = normalized_circle_to_line_arity4_prepared(
        combined_layer0,
        alphas[0],
        inverses.circle[0],
        inverses.circle[1],
    );
    require_layer_value(1, &later[0], path.later[0].slot, layer1)?;
    let layer2 = normalized_line_arity4_prepared(later[0], alphas[1], inverses.later[0]);
    require_layer_value(2, &later[1], path.later[1].slot, layer2)?;
    let layer3 = normalized_line_arity4_prepared(later[1], alphas[2], inverses.later[1]);
    require_layer_value(3, &later[2], path.later[2].slot, layer3)?;
    let terminal = normalized_line_arity4_prepared(later[2], alphas[3], inverses.later[2]);
    if evaluate_final_line_tensor(final_natural, inverses.final_x) != terminal {
        return Err(CircleQueryError::TerminalValueMismatch {
            final_index: path.final_index,
        });
    }
    Ok(CircleQueryCheck {
        path,
        combined_layer0,
        folded_values: [layer1, layer2, layer3, terminal],
    })
}

pub fn check_fixed_layer0_transition_prepared(
    c1_leaf: &[u8],
    c2_leaf: &[u8],
    layer1_leaf: &[u8],
    query: usize,
    powers: &CircleQueryGammaPowers,
    inverses: [M31; 2],
    alpha: PreparedQm31Multiplier,
    alpha_squared: PreparedQm31Multiplier,
) -> Result<(), CircleQueryError> {
    check_layer0_transition_prepared_for_fiber_count(
        c1_leaf,
        c2_leaf,
        layer1_leaf,
        query,
        FIXED_QUERY_FIBER_COUNT,
        powers,
        inverses,
        alpha,
        alpha_squared,
    )
}

pub fn check_layer0_transition_prepared_for_fiber_count(
    c1_leaf: &[u8],
    c2_leaf: &[u8],
    layer1_leaf: &[u8],
    query: usize,
    fiber_count: usize,
    powers: &CircleQueryGammaPowers,
    inverses: [M31; 2],
    alpha: PreparedQm31Multiplier,
    alpha_squared: PreparedQm31Multiplier,
) -> Result<(), CircleQueryError> {
    let combined = gamma_combine_fixed_layer0_prepared(c1_leaf, c2_leaf, powers)?;
    check_combined_layer0_transition_prepared_for_fiber_count(
        combined,
        layer1_leaf,
        query,
        fiber_count,
        inverses,
        alpha,
        alpha_squared,
    )
}

pub(crate) fn check_combined_layer0_transition_prepared_for_fiber_count(
    combined: [QM31; 4],
    layer1_leaf: &[u8],
    query: usize,
    fiber_count: usize,
    inverses: [M31; 2],
    alpha: PreparedQm31Multiplier,
    alpha_squared: PreparedQm31Multiplier,
) -> Result<(), CircleQueryError> {
    let path = crate::circle_fri::map_query_for_fiber_count(query, fiber_count)?;
    let layer1_leaf = decode_later_leaf(layer1_leaf, 1)?;
    let folded = normalized_circle_to_line_arity4_prepared_multipliers(
        combined,
        alpha,
        alpha_squared,
        inverses[0],
        inverses[1],
    );
    require_layer_value(1, &layer1_leaf, path.later[0].slot, folded)
}

/// Exact polynomial-basis variant of
/// [`check_combined_layer0_transition_prepared_for_fiber_count`].
pub(crate) fn check_combined_layer0_transition_prepared_polynomial_for_fiber_count(
    combined: [QM31; 4],
    layer1_leaf: &[u8],
    query: usize,
    fiber_count: usize,
    inverses: [M31; 2],
    alpha: PreparedQm31Multiplier,
    alpha_squared: PreparedQm31Multiplier,
    alpha_cubed: PreparedQm31Multiplier,
) -> Result<(), CircleQueryError> {
    let path = crate::circle_fri::map_query_for_fiber_count(query, fiber_count)?;
    let layer1_leaf = decode_later_leaf(layer1_leaf, 1)?;
    let folded = normalized_circle_to_line_arity4_prepared_polynomial_candidate(
        combined,
        alpha,
        alpha_squared,
        alpha_cubed,
        inverses[0],
        inverses[1],
    );
    require_layer_value(1, &layer1_leaf, path.later[0].slot, folded)
}

pub fn check_fixed_line_transition_prepared(
    incoming_leaf: &[u8],
    outgoing_leaf: &[u8],
    incoming_leaf_index: usize,
    layer: u8,
    inverses: [M31; 3],
    alpha: PreparedQm31Multiplier,
    alpha_squared: PreparedQm31Multiplier,
) -> Result<(), CircleQueryError> {
    let incoming = decode_later_leaf(incoming_leaf, layer)?;
    let outgoing = decode_later_leaf(outgoing_leaf, layer + 1)?;
    let folded =
        normalized_line_arity4_prepared_multipliers(incoming, alpha, alpha_squared, inverses);
    require_layer_value(
        layer + 1,
        &outgoing,
        (incoming_leaf_index & 3) as u8,
        folded,
    )
}

/// Exact polynomial-basis variant of [`check_fixed_line_transition_prepared`].
///
/// Decoding, canonicality, slot selection and errors are unchanged.  Only the
/// reduction schedule for the identical cubic fold polynomial differs.
pub fn check_fixed_line_transition_prepared_polynomial(
    incoming_leaf: &[u8],
    outgoing_leaf: &[u8],
    incoming_leaf_index: usize,
    layer: u8,
    inverses: [M31; 3],
    alpha: PreparedQm31Multiplier,
    alpha_squared: PreparedQm31Multiplier,
    alpha_cubed: PreparedQm31Multiplier,
) -> Result<(), CircleQueryError> {
    check_fixed_line_transition_prepared_polynomial_powers(
        incoming_leaf,
        outgoing_leaf,
        incoming_leaf_index,
        layer,
        inverses,
        &[alpha, alpha_squared, alpha_cubed],
    )
}

/// Borrowed-power form of
/// [`check_fixed_line_transition_prepared_polynomial`].
pub fn check_fixed_line_transition_prepared_polynomial_powers(
    incoming_leaf: &[u8],
    outgoing_leaf: &[u8],
    incoming_leaf_index: usize,
    layer: u8,
    inverses: [M31; 3],
    alpha_powers: &[PreparedQm31Multiplier; 3],
) -> Result<(), CircleQueryError> {
    let incoming = decode_later_leaf(incoming_leaf, layer)?;
    let slot = incoming_leaf_index & 3;
    let outgoing = decode_selected_later_slot(outgoing_leaf, layer + 1, slot)?;
    let folded = normalized_line_arity4_prepared_polynomial_refs(&incoming, alpha_powers, inverses);
    if outgoing != folded {
        return Err(CircleQueryError::LayerValueMismatch {
            layer: layer + 1,
            offset: slot * CIRCLE_QUERY_QM31_BYTES,
        });
    }
    Ok(())
}

pub fn check_fixed_terminal_transition_prepared(
    incoming_leaf: &[u8],
    final_natural: [QM31; 4],
    final_index: usize,
    inverses: [M31; 3],
    final_x: M31,
    alpha: PreparedQm31Multiplier,
    alpha_squared: PreparedQm31Multiplier,
) -> Result<(), CircleQueryError> {
    let incoming = decode_later_leaf(incoming_leaf, 3)?;
    let terminal =
        normalized_line_arity4_prepared_multipliers(incoming, alpha, alpha_squared, inverses);
    if evaluate_final_line_tensor(final_natural, final_x) != terminal {
        return Err(CircleQueryError::TerminalValueMismatch { final_index });
    }
    Ok(())
}

/// Exact polynomial-basis variant of
/// [`check_fixed_terminal_transition_prepared`].
pub fn check_fixed_terminal_transition_prepared_polynomial(
    incoming_leaf: &[u8],
    final_natural: [QM31; 4],
    final_index: usize,
    inverses: [M31; 3],
    final_x: M31,
    alpha: PreparedQm31Multiplier,
    alpha_squared: PreparedQm31Multiplier,
    alpha_cubed: PreparedQm31Multiplier,
) -> Result<(), CircleQueryError> {
    check_fixed_terminal_transition_prepared_polynomial_powers(
        incoming_leaf,
        final_natural,
        final_index,
        inverses,
        final_x,
        &[alpha, alpha_squared, alpha_cubed],
    )
}

/// Borrowed-power form of
/// [`check_fixed_terminal_transition_prepared_polynomial`].
pub fn check_fixed_terminal_transition_prepared_polynomial_powers(
    incoming_leaf: &[u8],
    final_natural: [QM31; 4],
    final_index: usize,
    inverses: [M31; 3],
    final_x: M31,
    alpha_powers: &[PreparedQm31Multiplier; 3],
) -> Result<(), CircleQueryError> {
    check_fixed_terminal_transition_prepared_polynomial_refs(
        incoming_leaf,
        &final_natural,
        final_index,
        inverses,
        final_x,
        alpha_powers,
    )
}

/// Fully borrowed form of
/// [`check_fixed_terminal_transition_prepared_polynomial_powers`].
pub fn check_fixed_terminal_transition_prepared_polynomial_refs(
    incoming_leaf: &[u8],
    final_natural: &[QM31; 4],
    final_index: usize,
    inverses: [M31; 3],
    final_x: M31,
    alpha_powers: &[PreparedQm31Multiplier; 3],
) -> Result<(), CircleQueryError> {
    let incoming = decode_later_leaf(incoming_leaf, 3)?;
    let terminal =
        normalized_line_arity4_prepared_polynomial_refs(&incoming, alpha_powers, inverses);
    if evaluate_final_line_tensor_ref(final_natural, final_x) != terminal {
        return Err(CircleQueryError::TerminalValueMismatch { final_index });
    }
    Ok(())
}

#[cfg(test)]
mod polynomial_transition_tests {
    use super::*;
    use crate::field::{CM31, P};

    fn next_m31(state: &mut u64) -> M31 {
        *state = state
            .wrapping_mul(6_364_136_223_846_793_005)
            .wrapping_add(1_442_695_040_888_963_407);
        M31((*state % u64::from(P)) as u32)
    }

    fn next_qm31(state: &mut u64) -> QM31 {
        QM31 {
            c0: CM31::new(next_m31(state), next_m31(state)),
            c1: CM31::new(next_m31(state), next_m31(state)),
        }
    }

    fn encode(values: &[QM31; 4]) -> [u8; CIRCLE_QUERY_LATER_LEAF_BYTES] {
        let mut bytes = [0u8; CIRCLE_QUERY_LATER_LEAF_BYTES];
        for (slot, value) in values.iter().enumerate() {
            value.write_le_bytes(&mut bytes[slot * 16..(slot + 1) * 16]);
        }
        bytes
    }

    #[test]
    fn manual_later_decoders_match_qm31_bytes_and_rejection_offsets() {
        let mut state = 0x4c41_5445_5244_4543u64;
        for case in 0..128usize {
            let values = core::array::from_fn(|_| next_qm31(&mut state));
            let encoded = encode(&values);
            assert_eq!(decode_later_leaf(&encoded, 2), Ok(values));
            for selected_slot in 0..4 {
                assert_eq!(
                    decode_selected_later_slot(&encoded, 2, selected_slot),
                    Ok(values[selected_slot]),
                    "case {case}, selected slot {selected_slot}",
                );
            }
        }

        let canonical = encode(&[QM31::ZERO; 4]);
        for bad_slot in 0..4 {
            for bad_limb in 0..4 {
                let offset = bad_slot * CIRCLE_QUERY_QM31_BYTES;
                let limb_offset = offset + bad_limb * 4;
                let mut noncanonical = canonical;
                noncanonical[limb_offset..limb_offset + 4].copy_from_slice(&P.to_le_bytes());
                let expected = CircleQueryError::NonCanonicalQm31 {
                    leaf: CircleQueryLeaf::Later(2),
                    offset,
                };
                assert_eq!(decode_later_leaf(&noncanonical, 2), Err(expected));
                for selected_slot in 0..4 {
                    assert_eq!(
                        decode_selected_later_slot(&noncanonical, 2, selected_slot),
                        Err(expected),
                        "bad slot {bad_slot}, limb {bad_limb}, selected slot {selected_slot}",
                    );
                }
            }
        }
    }

    #[test]
    fn polynomial_transition_wrappers_match_nested_acceptance_and_canonical_teeth() {
        let mut state = 0x504f_4c59_5452_414eu64;
        for case in 0..128usize {
            let incoming_values = core::array::from_fn(|_| next_qm31(&mut state));
            let alpha_value = next_qm31(&mut state);
            let alpha_squared_value = alpha_value.square();
            let alpha = PreparedQm31Multiplier::new(alpha_value);
            let alpha_squared = PreparedQm31Multiplier::new(alpha_squared_value);
            let alpha_cubed = PreparedQm31Multiplier::new(alpha_squared_value.mul(alpha_value));
            let inverses = core::array::from_fn(|_| next_m31(&mut state));
            let folded = normalized_line_arity4_prepared_multipliers(
                incoming_values,
                alpha,
                alpha_squared,
                inverses,
            );
            let incoming = encode(&incoming_values);
            let slot = case & 3;
            let mut outgoing_values = core::array::from_fn(|_| next_qm31(&mut state));
            outgoing_values[slot] = folded;
            let outgoing = encode(&outgoing_values);
            let nested = check_fixed_line_transition_prepared(
                &incoming,
                &outgoing,
                case,
                1,
                inverses,
                alpha,
                alpha_squared,
            );
            let polynomial = check_fixed_line_transition_prepared_polynomial(
                &incoming,
                &outgoing,
                case,
                1,
                inverses,
                alpha,
                alpha_squared,
                alpha_cubed,
            );
            assert_eq!(polynomial, nested, "valid line case {case}");
            assert_eq!(polynomial, Ok(()));

            let final_natural = [folded, QM31::ZERO, QM31::ZERO, QM31::ZERO];
            let final_x = next_m31(&mut state);
            let nested_terminal = check_fixed_terminal_transition_prepared(
                &incoming,
                final_natural,
                case,
                inverses,
                final_x,
                alpha,
                alpha_squared,
            );
            let polynomial_terminal = check_fixed_terminal_transition_prepared_polynomial(
                &incoming,
                final_natural,
                case,
                inverses,
                final_x,
                alpha,
                alpha_squared,
                alpha_cubed,
            );
            assert_eq!(polynomial_terminal, nested_terminal, "terminal case {case}");
            assert_eq!(
                check_fixed_terminal_transition_prepared_polynomial_refs(
                    &incoming,
                    &final_natural,
                    case,
                    inverses,
                    final_x,
                    &[alpha, alpha_squared, alpha_cubed],
                ),
                polynomial_terminal,
                "borrowed terminal case {case}",
            );

            let mut noncanonical_incoming = incoming;
            noncanonical_incoming[..4].copy_from_slice(&P.to_le_bytes());
            assert_eq!(
                check_fixed_line_transition_prepared_polynomial(
                    &noncanonical_incoming,
                    &outgoing,
                    case,
                    1,
                    inverses,
                    alpha,
                    alpha_squared,
                    alpha_cubed,
                ),
                check_fixed_line_transition_prepared(
                    &noncanonical_incoming,
                    &outgoing,
                    case,
                    1,
                    inverses,
                    alpha,
                    alpha_squared,
                ),
                "canonical tooth case {case}",
            );

            let mut noncanonical_outgoing = outgoing;
            let bad_slot = (case >> 2) & 3;
            let bad_limb = case & 3;
            let bad_offset = bad_slot * 16 + bad_limb * 4;
            noncanonical_outgoing[bad_offset..bad_offset + 4].copy_from_slice(&P.to_le_bytes());
            assert_eq!(
                check_fixed_line_transition_prepared_polynomial(
                    &incoming,
                    &noncanonical_outgoing,
                    case,
                    1,
                    inverses,
                    alpha,
                    alpha_squared,
                    alpha_cubed,
                ),
                check_fixed_line_transition_prepared(
                    &incoming,
                    &noncanonical_outgoing,
                    case,
                    1,
                    inverses,
                    alpha,
                    alpha_squared,
                ),
                "outgoing canonical tooth case {case}",
            );
        }
    }
}

