pub struct StateOnlyCandidatePrefix<'a> {
    pub shape: StateOnlyProfileShape,
    pub header: Header,
    pub header_bytes: &'a [u8; HEADER_LEN],
    pub mask_nonce: &'a [u8; 32],
    pub c1_root: &'a [u8; ROOT_LEN],
    pub c2_root: &'a [u8; ROOT_LEN],
