    #[test]
    fn profile21_schedule_binds_u_tau_and_translated_root_before_q16() {
        let statement = [0x71; 32];
        let bytes = profile21_zero_fixture();
        let parsed = StateOnlyProfile21Prefix::parse_exact(&bytes).unwrap();
        let schedule =
