        );

        let mut changed_u = bytes;
        let logical_u_start = STATE_ONLY_PREFIX_LEN + CANDIDATE_NONCE_LEN;
        changed_u[logical_u_start] = 1;
        let changed = StateOnlyProfile21Prefix::parse_exact(&changed_u).unwrap();
        let changed_schedule =
