            v: QM31::ZERO,
        };
        let mut weights = WeightAccumulator::from_claim(4, Some(&claim));
        weights.add_geometric(q(7), q(9));

        let polynomial = polynomial_for_extension(&values, &weights);
        assert_eq!(boundary_sum(&polynomial), weights.dot(&values));

        let alpha = q(11);
