const DOM_ABSORB: u8 = 0x00;
const DOM_SQUEEZE: u8 = 0x01;
const DOM_ADVANCE: u8 = 0x02;
const DOM_GRIND: u8 = 0x03;

/// Maximum candidate draws per QM31 limb before the transcript is declared
/// exhausted. Per-limb exhaustion probability (2^-31)^8 = 2^-248.
pub const CHALLENGE_RETRY_LIMIT: u32 = 8;

/// Maximum exact-uniform QM31 draws used when a protocol challenge must be
/// nonzero. Exhaustion has probability `|QM31|^-3` apart from the separately
/// bounded per-limb rejection event.
pub const NONZERO_QM31_RETRY_LIMIT: u32 = 3;

/// Maximum field draws used to obtain a point outside the CM31 subfield.
/// A random QM31 point lands in CM31 with probability 1/|CM31| ~= 2^-62;
/// exhausting all three attempts is therefore below 2^-186.
pub const OOD_RETRY_LIMIT: u32 = 3;

/// Maximum exact-uniform parameters tried for one secure circle OOD point.
/// Rejections cover the rational map's two poles and the CM31 parameter
/// subfield. This sampler is for the layer-zero circle polynomial only;
/// later line layers continue to use [`Transcript::challenge_ood_qm31`].
pub const CIRCLE_POINT_RETRY_LIMIT: u32 = 3;

/// Fixed rational-map parameters used by the R0 reference schedule when a
/// sampled circle parameter is rejected: `t₀ = (0 + 1·u)`, `t₁ = (1 + 1·u)`
/// in `(c0, c1)` tower order, i.e. `R0P.CircleSampler.circleFallbackParameter0/1`.
/// Both have `c1 ≠ 0`, so neither is a pole nor in CM31, and they differ.
pub const CIRCLE_FALLBACK_PARAMETERS: [QM31; 2] = [
    QM31 {
        c0: crate::field::CM31::ZERO,
        c1: crate::field::CM31::ONE,
    },
    QM31 {
        c0: crate::field::CM31::ONE,
        c1: crate::field::CM31::ONE,
    },
];

/// The fallback circle point for OOD row `sample` (0 or 1): the image of
/// [`CIRCLE_FALLBACK_PARAMETERS`] under the secure rational map. The map
/// cannot fail on these parameters (`c1 ≠ 0`), so the unwrap is total; it is
/// written as an explicit match to keep this crate panic-free in practice.
pub fn circle_fallback_point(sample: usize) -> SecureCirclePoint {
    let parameter = CIRCLE_FALLBACK_PARAMETERS[sample % 2];
    match secure_ood_circle_point_from_parameter(parameter) {
        Ok(point) => point,
        // Unreachable: `c1 = 1 ≠ 0` for both parameters.
        Err(_) => SecureCirclePoint {
            x: QM31::ONE,
            y: QM31::ZERO,
        },
    }
}

/// The bounded rejection-sampling loop ran out of retries (a 2^-248-per-limb
/// completeness event). The verifier maps this to proof rejection.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub struct ChallengeSampleExhausted;

/// Failure of bounded exact-uniform query sampling without replacement.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum QuerySampleError {
    /// Masking is exact only when the domain size is a nonzero power of two.
    BoundNotPowerOfTwo { bound: u32 },
    /// A without-replacement sample cannot contain more points than its domain.
    CountExceedsBound { count: usize, bound: u32 },
    /// The configured candidate-draw cap was reached before `count` distinct
    /// positions were accepted. This is an explicit completeness abort.
    DrawLimitExhausted { accepted: usize, max_draws: usize },
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum OodSampleError {
    /// The exact-uniform field sampler exhausted its per-limb retry bound.
    ChallengeSampleExhausted,
    /// Three independently sampled QM31 points all landed in CM31.
    SubfieldSampleExhausted,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum CirclePointSampleError {
    /// The exact-uniform QM31 parameter sampler exhausted its limb retry.
    ChallengeSampleExhausted,
    /// Every bounded parameter candidate was either in CM31 or a pole of the
    /// rational circle map.
    ParameterSampleExhausted,
}

#[derive(Clone)]
pub struct Transcript {
    state: [u8; 32],
    hash: HashFn,
}

impl Transcript {
    pub fn new(hash: HashFn) -> Transcript {
        Transcript {
            state: [0u8; 32],
            hash,
        }
    }

    #[inline(never)]
    pub fn absorb(&mut self, label: u8, data: &[u8]) {
        // Most transcript records are short. Packing their fixed state and
        // framing into one buffer reduces SBF slice translation while the
        // large point/final vectors retain the zero-copy hashv path.
        const PACKED_ABSORB_BYTES: usize = 192;
        if data.len() <= PACKED_ABSORB_BYTES - 34 {
            let mut input = [0u8; PACKED_ABSORB_BYTES];
            input[..32].copy_from_slice(&self.state);
            input[32] = DOM_ABSORB;
            input[33] = label;
            input[34..34 + data.len()].copy_from_slice(data);
            self.state = (self.hash)(&[&input[..34 + data.len()]]);
        } else {
            self.state = (self.hash)(&[&self.state, &[DOM_ABSORB, label], data]);
        }
    }

    /// Absorb two logical pieces as one transcript record without allocating
    /// their concatenation. Hash backends implement `hashv` semantics, so this
    /// is byte-identical to the large-record branch of `absorb(label,
    /// concat(first, second))`.
    #[inline(never)]
    pub fn absorb_two(&mut self, label: u8, first: &[u8], second: &[u8]) {
        self.state = (self.hash)(&[&self.state, &[DOM_ABSORB, label], first, second]);
    }

    /// Internal evidence hook for candidate schedule teeth. This is not a
    /// transcript challenge, wire field, or production KAT surface.
    pub const fn diagnostic_state(&self) -> [u8; 32] {
        self.state
    }

    /// Squeeze one 32-byte block and advance the state.
    #[inline(never)]
    pub fn squeeze_block(&mut self) -> [u8; 32] {
        let mut squeeze = [0u8; 33];
        squeeze[..32].copy_from_slice(&self.state);
        squeeze[32] = DOM_SQUEEZE;
        let out = (self.hash)(&[&squeeze]);
        squeeze[32] = DOM_ADVANCE;
        self.state = (self.hash)(&[&squeeze]);
        out
    }

    /// Sample a QM31 challenge by per-limb rejection sampling (exactly
    /// uniform; soundness-note §3 T9).
    ///
    /// Each limb draw takes 31 bits of a LE u32 and REJECTS the single
    /// non-canonical value P, redrawing from fresh transcript bytes: retries
    /// consume the next word of the block stream, and a spent block is
    /// replaced via `squeeze_block`, which advances the duplex state — no
    /// input is ever re-hashed, so retries cannot repeat a rejected value
    /// deterministically. The retry loop is bounded (`CHALLENGE_RETRY_LIMIT`)
    /// and exhaustion is an error the verifier surfaces as proof rejection:
    /// per-limb exhaustion probability is (2^-31)^8 = 2^-248, a completeness
    /// event (soundness-note §6), the correct trade on a CU-metered chain
    /// versus an unmetered loop.
    ///
    /// In the non-rejecting case (all real transcripts, whp) this consumes
    /// exactly one block and produces the same limbs as the pre-fix sampler
    /// except on a P-hit, where the old code folded P to 0 (the ~2^-31
    /// per-limb bias this fix removes).
    pub fn challenge_qm31(&mut self) -> Result<QM31, ChallengeSampleExhausted> {
        let mut limbs = [M31::ZERO; 4];
        let mut block = self.squeeze_block();
        let mut word_index = 0usize;
        for limb in limbs.iter_mut() {
            let mut accepted = false;
            for _ in 0..CHALLENGE_RETRY_LIMIT {
                if word_index == 8 {
                    block = self.squeeze_block();
                    word_index = 0;
                }
                let word = u32::from_le_bytes(
                    block[word_index * 4..word_index * 4 + 4]
                        .try_into()
                        .unwrap(),
                );
                word_index += 1;
                let masked = word & crate::field::P;
                if masked != crate::field::P {
                    *limb = M31(masked);
                    accepted = true;
                    break;
                }
            }
            if !accepted {
                return Err(ChallengeSampleExhausted);
            }
        }
        Ok(QM31 {
            c0: crate::field::CM31 {
                a: limbs[0],
                b: limbs[1],
            },
            c1: crate::field::CM31 {
                a: limbs[2],
                b: limbs[3],
            },
        })
    }

    /// Sample exactly uniformly from `QM31 ∖ {0}` with a bounded
    /// rejection loop. Every rejected zero consumes fresh transcript blocks;
    /// exhaustion is a completeness rejection, never a zero fallback.
    pub fn challenge_nonzero_qm31(&mut self) -> Result<QM31, ChallengeSampleExhausted> {
        for _ in 0..NONZERO_QM31_RETRY_LIMIT {
            let value = self.challenge_qm31()?;
            if value != QM31::ZERO {
                return Ok(value);
            }
        }
        Err(ChallengeSampleExhausted)
    }

    /// Sample exactly uniformly from QM31 \ CM31. Since every evaluation
    /// domain used by Aspis lies in CM31, this makes the point genuinely
    /// out-of-domain by construction instead of relying on a negligible
    /// collision probability. The bounded outer retry is a completeness
    /// trade (below 2^-186), not a soundness term.
    pub fn challenge_ood_qm31(&mut self) -> Result<QM31, OodSampleError> {
        for _ in 0..OOD_RETRY_LIMIT {
            let point = self
                .challenge_qm31()
                .map_err(|_| OodSampleError::ChallengeSampleExhausted)?;
            if point.c1 != crate::field::CM31::ZERO {
                return Ok(point);
            }
        }
        Err(OodSampleError::SubfieldSampleExhausted)
    }

    /// Sample a secure layer-zero circle OOD point through an exact-uniform
    /// QM31 parameter `t` and the rational map. The bounded policy rejects
    /// `t in CM31` and `1+t^2=0`; the pure map reports those reasons in
    /// [`crate::circle::CirclePointError`], while this transcript API exposes
    /// one bounded-candidate exhaustion result. No inversion path panics.
    pub fn challenge_secure_circle_point(
        &mut self,
    ) -> Result<SecureCirclePoint, CirclePointSampleError> {
        for _ in 0..CIRCLE_POINT_RETRY_LIMIT {
            let parameter = self
                .challenge_qm31()
                .map_err(|_| CirclePointSampleError::ChallengeSampleExhausted)?;
            if let Ok(point) = secure_ood_circle_point_from_parameter(parameter) {
                return Ok(point);
            }
        }
        Err(CirclePointSampleError::ParameterSampleExhausted)
    }

    /// Sample the layer-zero circle OOD point for row `sample` of the R0
    /// reference schedule with a total one-block law and no retry: one
    /// `challenge_qm31` parameter `t`; if the rational map rejects it
    /// (`t in CM31`, which contains both poles), the point is the fixed
    /// row-specific fallback [`circle_fallback_point`] instead of a fresh
    /// draw. The fallbacks lie outside CM31, are distinct, and are the
    /// points `R0P.CircleSampler.circleFallback0/1` of the formal model, so
    /// the sampled point is never base-rational and each row's bad set is
    /// the proved `(1+δQ)/P⁴` fiber. Only the per-limb exhaustion of
    /// `challenge_qm31` remains an error.
    pub fn challenge_reference_circle_point(
        &mut self,
        sample: usize,
    ) -> Result<SecureCirclePoint, ChallengeSampleExhausted> {
        let parameter = self.challenge_qm31()?;
        Ok(secure_ood_circle_point_from_parameter(parameter)
            .unwrap_or_else(|_| circle_fallback_point(sample)))
    }

    /// Derive `count` query positions in [0, bound) where bound is a power of
    /// two (exact-uniform masking, no modulo bias).
    pub fn challenge_queries(&mut self, count: usize, bound: u32) -> alloc::vec::Vec<u32> {
        debug_assert!(bound.is_power_of_two());
        let mask = bound - 1;
        let mut out = alloc::vec::Vec::with_capacity(count);
        'outer: loop {
            let block = self.squeeze_block();
            for word in block.chunks_exact(4) {
                if out.len() == count {
                    break 'outer;
                }
                let word = u32::from_le_bytes(word.try_into().unwrap());
                out.push(word & mask);
            }
            if out.len() == count {
                break;
            }
        }
        out
    }

    /// Derive an ordered exact-uniform sample without replacement from
    /// `[0, bound)`, where `bound` is a power of two.
    ///
    /// Candidate words use the same mask and block stream as
    /// [`Self::challenge_queries`]. Duplicate candidates are rejected while
    /// preserving the order of first occurrence. Consequently, whenever the
    /// first `count` candidates are already distinct, this method returns the
    /// same query bytes and leaves the transcript in exactly the same state as
    /// the legacy with-replacement method. The bounded draw cap turns an
    /// exceptionally collision-heavy transcript into an explicit proof
    /// rejection instead of an unmetered loop.
    pub fn challenge_queries_without_replacement(
        &mut self,
        count: usize,
        bound: u32,
        max_draws: usize,
    ) -> Result<alloc::vec::Vec<u32>, QuerySampleError> {
        if !bound.is_power_of_two() {
            return Err(QuerySampleError::BoundNotPowerOfTwo { bound });
        }
        if count > bound as usize {
            return Err(QuerySampleError::CountExceedsBound { count, bound });
        }
        if count == 0 {
            return Ok(alloc::vec::Vec::new());
        }
        let mask = bound - 1;
        let mut out = alloc::vec::Vec::with_capacity(count);
        let mut draws = 0usize;
        'outer: while draws < max_draws {
            let block = self.squeeze_block();
            for word in block.chunks_exact(4) {
                if out.len() == count || draws == max_draws {
                    break 'outer;
                }
                draws += 1;
                let candidate = u32::from_le_bytes(word.try_into().unwrap()) & mask;
                if !out.contains(&candidate) {
                    out.push(candidate);
                }
            }
        }
        if out.len() == count {
            Ok(out)
        } else {
            Err(QuerySampleError::DrawLimitExhausted {
                accepted: out.len(),
                max_draws,
            })
        }
    }

    /// Grinding check: hash(state, DOM_GRIND, nonce) must have
    /// `bits` leading zero bits. Verifier-side cost: one hash call.
    pub fn grinding_ok(&self, nonce: u64, bits: u8) -> bool {
        let digest = (self.hash)(&[&self.state, &[DOM_GRIND], &nonce.to_le_bytes()]);
        digest_has_leading_zero_bits(digest, bits)
    }
}

/// Known-answer transcript vector (soundness-note appendix): absorb a fixed
/// pattern, sample the full challenge menu (QM31 rejection sampler, grinding
/// check, query derivation), and fold every output into one digest. The
/// pinned expected value lives in the host test `transcript_kat_pinned` and
/// is asserted bit-identical on SBF via the program's `TranscriptKat`
/// instruction — a silent host/chain sampler divergence costs a test
/// failure here instead of a week.
pub fn transcript_kat(hash: HashFn) -> [u8; 32] {
    let mut t = Transcript::new(hash);
    t.absorb(label::PROFILE, b"aspis-transcript-kat-v3-c2");
    t.absorb(label::STATEMENT, &[0xA5; 32]);
    let mut acc = [0u8; 32];

    // Canonical two-phase prefix: C1 -> (lambda, chi) -> C2 -> claimed
    // evaluations -> gamma. Each squeezed value contributes to the KAT
    // digest, so deleting or moving any one of them is a loud re-pin.
    t.absorb(label::ROOT, &[0u8; 32]);
    for _ in 0..2 {
        let challenge = t
            .challenge_qm31()
            .expect("kat: phase challenge sampler exhausted (2^-248 per limb)");
        let mut bytes = [0u8; 16];
        challenge.write_le_bytes(&mut bytes);
        acc = hash(&[&acc, &bytes]);
    }
    t.absorb(label::SECOND_PHASE_ROOT, &[0x22; 32]);
    t.absorb(label::CLAIM, &[0x33; 176]);
    t.absorb(label::SECOND_PHASE_CLAIM, &[0x44; 16]);
    let gamma = t
        .challenge_qm31()
        .expect("kat: gamma sampler exhausted (2^-248 per limb)");
    let mut gamma_bytes = [0u8; 16];
    gamma.write_le_bytes(&mut gamma_bytes);
    acc = hash(&[&acc, &gamma_bytes]);

    for i in 0..8u8 {
        if i > 0 {
            t.absorb(label::ROOT, &[i; 32]);
        }
        let ood_point = t
            .challenge_ood_qm31()
            .expect("kat: OOD sampler exhausted (<2^-186)");
        let mut point_bytes = [0u8; 16];
        ood_point.write_le_bytes(&mut point_bytes);
        acc = hash(&[&acc, &point_bytes]);
        t.absorb(label::OOD_VALUE, &[0x40 + i; 16]);
        let mix = t
            .challenge_qm31()
            .expect("kat: claim-mix sampler exhausted (2^-248 per limb)");
        let mut mix_bytes = [0u8; 16];
        mix.write_le_bytes(&mut mix_bytes);
        acc = hash(&[&acc, &mix_bytes]);
        t.absorb(
            label::SUMCHECK_POLY,
            &[0x80 + i; crate::sumcheck::SUMCHECK_BYTES],
        );
        let alpha = t
            .challenge_qm31()
            .expect("kat: sampler exhausted (2^-248 per limb)");
        let mut bytes = [0u8; 16];
        alpha.write_le_bytes(&mut bytes);
        acc = hash(&[&acc, &bytes]);
    }
    t.absorb(label::FINAL_POLY, &[0x77; 64]);
    let grind = t.grinding_ok(0xDEAD_BEEF, 8);
    acc = hash(&[&acc, &[grind as u8]]);
    t.absorb(label::GRIND_NONCE, &0xDEAD_BEEFu64.to_le_bytes());
    for q in t.challenge_queries(16, 1 << 10) {
        acc = hash(&[&acc, &q.to_le_bytes()]);
    }
    acc
}

/// V4/s=2 PCS-scaffold known-answer transcript vector.
///
/// V4 extends the v3 two-phase prefix by absorbing a second helper evaluation
/// under the same combined C2 root before gamma. Each committed layer then
/// carries two sequential `(beta, y, mu)` triples before the single relation
/// sumcheck polynomial and fold challenge. Keeping this function distinct
/// makes both supported schedules independently auditable.
pub fn transcript_kat_v4_s2_pcs_scaffold(hash: HashFn) -> [u8; 32] {
    let mut t = Transcript::new(hash);
    t.absorb(label::PROFILE, b"aspis-transcript-kat-v4-s2-c2");
    t.absorb(label::STATEMENT, &[0xA5; 32]);
    let mut acc = [0u8; 32];

    t.absorb(label::ROOT, &[0u8; 32]);
    for _ in 0..2 {
        let challenge = t
            .challenge_qm31()
            .expect("v4 kat: phase challenge sampler exhausted (2^-248 per limb)");
        let mut bytes = [0u8; 16];
        challenge.write_le_bytes(&mut bytes);
        acc = hash(&[&acc, &bytes]);
    }
    t.absorb(label::SECOND_PHASE_ROOT, &[0x22; 32]);
    t.absorb(label::CLAIM, &[0x33; 176]);
    t.absorb(label::SECOND_PHASE_CLAIM, &[0x44; 16]);
    t.absorb(label::SECOND_PHASE_CLAIM, &[0x45; 16]);
    let gamma = t
        .challenge_qm31()
        .expect("v4 kat: gamma sampler exhausted (2^-248 per limb)");
    let mut gamma_bytes = [0u8; 16];
    gamma.write_le_bytes(&mut gamma_bytes);
    acc = hash(&[&acc, &gamma_bytes]);

    for layer in 0..8u8 {
        if layer > 0 {
            t.absorb(label::ROOT, &[layer; 32]);
        }
        for sample in 0..2u8 {
            let ood_point = t
                .challenge_ood_qm31()
                .expect("v4 kat: OOD sampler exhausted (<2^-186)");
            let mut point_bytes = [0u8; 16];
            ood_point.write_le_bytes(&mut point_bytes);
            acc = hash(&[&acc, &point_bytes]);

            t.absorb(label::OOD_VALUE, &[0x40 + 2 * layer + sample; 16]);
            let mix = t
                .challenge_qm31()
                .expect("v4 kat: claim-mix sampler exhausted (2^-248 per limb)");
            let mut mix_bytes = [0u8; 16];
            mix.write_le_bytes(&mut mix_bytes);
            acc = hash(&[&acc, &mix_bytes]);
        }
        t.absorb(
            label::SUMCHECK_POLY,
            &[0x80 + layer; crate::sumcheck::SUMCHECK_BYTES],
        );
        let alpha = t
            .challenge_qm31()
            .expect("v4 kat: sampler exhausted (2^-248 per limb)");
        let mut alpha_bytes = [0u8; 16];
        alpha.write_le_bytes(&mut alpha_bytes);
        acc = hash(&[&acc, &alpha_bytes]);
    }

    t.absorb(label::FINAL_POLY, &[0x77; 64]);
    let grind = t.grinding_ok(0xDEAD_BEEF, 8);
    acc = hash(&[&acc, &[grind as u8]]);
    t.absorb(label::GRIND_NONCE, &0xDEAD_BEEFu64.to_le_bytes());
    for query in t.challenge_queries(16, 1 << 10) {
        acc = hash(&[&acc, &query.to_le_bytes()]);
    }
    acc
}

/// Full payment-v4 schedule KAT.
///
/// The byte payloads are deterministic fixtures, while every challenge and
/// query uses the production sampler.  The KAT's purpose is schedule and
/// host/SBF parity: it pins C1 -> lambda/chi -> C2 -> payment zerocheck -> all
/// statement rows -> batch work -> gamma, followed by the exact two-OOD,
/// per-fold-work, final-work, distinct-query tail.
pub fn transcript_kat_final_payment_v4(hash: HashFn) -> [u8; 32] {
    fn fold_value(hash: HashFn, acc: &mut [u8; 32], value: QM31) {
        let mut bytes = [0u8; 16];
        value.write_le_bytes(&mut bytes);
        *acc = hash(&[acc, &bytes]);
    }

    let mut t = Transcript::new(hash);
    let mut acc = [0u8; 32];

    t.absorb(label::PROFILE, b"aspis-payment-v4-kat");
    t.absorb(label::M31_CIRCLE_BASIS, b"aspis:c1:m31-circle:v0");
    t.absorb(label::STATEMENT, &[0xa5; 32]);
    let mut root_record = [0x11u8; 33];
    root_record[0] = 0;
    t.absorb(label::M31_CIRCLE_ROUND_ROOT, &root_record);
    for _ in 0..2 {
        fold_value(
            hash,
            &mut acc,
            t.challenge_qm31().expect("payment KAT phase sampler"),
        );
    }
    t.absorb(label::M31_CIRCLE_C2_ROOT, &[0x22; 32]);

    let registry = [2u8, 252, 0, 67, 0, 10, 10, 10];
    t.absorb(label::M31_PAYMENT_CONSTRAINT_REGISTRY, &registry);
    t.absorb(label::M31_PAYMENT_HELPER_SUMS, &[0u8; 32]);
    fold_value(
        hash,
        &mut acc,
        t.challenge_qm31().expect("payment KAT theta sampler"),
    );
    for _ in 0..10 {
        fold_value(
            hash,
            &mut acc,
            t.challenge_qm31().expect("payment KAT zero-point sampler"),
        );
    }
    fold_value(
        hash,
        &mut acc,
        t.challenge_qm31().expect("payment KAT mu sampler"),
    );

    t.absorb(label::M31_PAYMENT_HIDING_MASK_CLAIM, &[0x31; 16]);
    fold_value(
        hash,
        &mut acc,
        t.challenge_qm31().expect("payment KAT eta sampler"),
    );
    let mut z = [QM31::ZERO; 10];
    for round in 0..10usize {
        let mut record = [0u8; 161];
        record[0] = round as u8;
        record[1..].fill(0x40 + round as u8);
        t.absorb(label::M31_PAYMENT_ZEROCHECK_SUMCHECK, &record);
        z[round] = t.challenge_qm31().expect("payment KAT sumcheck sampler");
        fold_value(hash, &mut acc, z[round]);
    }

    let mut points = [0u8; 320];
    for (point, mut coordinates) in [z, z].into_iter().enumerate() {
        if point == 1 {
            for coordinate in [6usize, 8, 9] {
                coordinates[coordinate] = QM31::ONE.sub(coordinates[coordinate]);
            }
        }
        for (coordinate, value) in coordinates.into_iter().enumerate() {
            value.write_le_bytes(&mut points[(point * 10 + coordinate) * 16..][..16]);
        }
    }
    t.absorb(label::M31_CIRCLE_STATEMENT_POINTS, &points);
    t.absorb(label::M31_CIRCLE_STATEMENT_EVALUATIONS, &[0x52; 1_632]);

    let batch_nonce = 0x6261_7463_685f_706fu64;
    let batch_ok = t.grinding_ok(batch_nonce, 8);
    acc = hash(&[&acc, &[batch_ok as u8]]);
    t.absorb(
        label::M31_PAYMENT_BATCH_POW_NONCE,
        &batch_nonce.to_le_bytes(),
    );
    fold_value(
        hash,
        &mut acc,
        t.challenge_qm31().expect("payment KAT gamma sampler"),
    );
    fold_value(
        hash,
        &mut acc,
        t.challenge_qm31().expect("payment KAT point-scale sampler"),
    );

    for layer in 0..4usize {
        if layer > 0 {
            let mut record = [0x60 + layer as u8; 33];
            record[0] = layer as u8;
            t.absorb(label::M31_CIRCLE_ROUND_ROOT, &record);
        }
        for sample in 0..2usize {
            if layer == 0 {
                let point = t
                    .challenge_secure_circle_point()
                    .expect("payment KAT circle sampler");
                fold_value(hash, &mut acc, point.x);
                fold_value(hash, &mut acc, point.y);
            } else {
                fold_value(
                    hash,
                    &mut acc,
                    t.challenge_ood_qm31().expect("payment KAT line sampler"),
                );
            }
            let mut record = [0x70 + (2 * layer + sample) as u8; 18];
            record[0] = layer as u8;
            record[1] = sample as u8;
            t.absorb(
                if layer == 0 {
                    label::M31_CIRCLE_OOD_VALUE
                } else {
                    label::M31_LINE_OOD_VALUE
                },
                &record,
            );
            fold_value(
                hash,
                &mut acc,
                t.challenge_qm31().expect("payment KAT OOD mix sampler"),
            );
        }
        let mut sumcheck = [0x80 + layer as u8; 113];
        sumcheck[0] = layer as u8;
        t.absorb(label::M31_CIRCLE_RELATION_SUMCHECK, &sumcheck);
        let fold_nonce = 0x666f_6c64_0000_0000u64 | layer as u64;
        let fold_ok = t.grinding_ok(fold_nonce, 8);
        acc = hash(&[&acc, &[fold_ok as u8]]);
        let mut record = [0u8; 9];
        record[0] = layer as u8;
        record[1..].copy_from_slice(&fold_nonce.to_le_bytes());
        t.absorb(label::M31_CIRCLE_FOLD_POW_NONCE, &record);
        fold_value(
            hash,
            &mut acc,
            t.challenge_qm31().expect("payment KAT fold sampler"),
        );
    }

    t.absorb(label::M31_CIRCLE_FINAL_TENSOR_POLY, &[0x91; 64]);
    let final_nonce = 0x7175_6572_795f_706fu64;
    let final_ok = t.grinding_ok(final_nonce, 8);
    acc = hash(&[&acc, &[final_ok as u8]]);
    t.absorb(label::GRIND_NONCE, &final_nonce.to_le_bytes());
    for query in t
        .challenge_queries_without_replacement(36, 1 << 12, 64)
        .expect("payment KAT distinct-query sampler")
    {
        acc = hash(&[&acc, &query.to_le_bytes()]);
    }
    acc
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::field::{CM31, P};

    const CIRCLE_S2_FIXTURE_EXPECTED: [u8; 32] = [
        8, 72, 150, 167, 42, 224, 50, 159, 107, 60, 253, 10, 218, 217, 96, 40, 11, 204, 190, 117,
        157, 189, 68, 117, 30, 223, 188, 172, 120, 178, 4, 85,
    ];

    fn test_hash(inputs: &[&[u8]]) -> [u8; 32] {
        use sha2::{Digest, Sha256};
        let mut h = Sha256::new();
        for i in inputs {
            h.update(i);
        }
        h.finalize().into()
    }

    /// Return the transcript state from either the original two-slice hashv
    /// spelling or the allocation-free packed spelling used by production.
    /// Test-only adversarial backends model the concatenated hash input, so
    /// they must not depend on how that byte string is split into slices.
    fn framed_state<'a>(inputs: &'a [&'a [u8]], domain: u8) -> Option<&'a [u8]> {
        match inputs {
            [state, frame] if state.len() == 32 && *frame == [domain] => Some(*state),
            [packed] if packed.len() == 33 && packed[32] == domain => Some(&packed[..32]),
            _ => None,
        }
    }

    fn grinding_input_probe(inputs: &[&[u8]]) -> [u8; 32] {
        assert_eq!(inputs.len(), 3);
        assert_eq!(inputs[0], &[0u8; 32]);
        assert_eq!(inputs[1], &[DOM_GRIND]);
        assert_eq!(inputs[2], &0x0102_0304_0506_0708u64.to_le_bytes());
        let mut digest = [0u8; 32];
        digest[..8].copy_from_slice(&(u32::MAX as u64).to_be_bytes());
        digest
    }

    #[test]
    fn grinding_digest_predicate_has_exact_boundaries_and_byte_order() {
        for bits in [37u8, 34, 33, 30, 25, 32] {
            let threshold = 1u64 << (64 - bits as u32);
            let mut below = [0u8; 32];
            below[..8].copy_from_slice(&(threshold - 1).to_be_bytes());
            let mut at = [0u8; 32];
            at[..8].copy_from_slice(&threshold.to_be_bytes());
            assert!(digest_has_leading_zero_bits(below, bits));
            assert!(!digest_has_leading_zero_bits(at, bits));
        }

        assert!(digest_has_leading_zero_bits([0xff; 32], 0));

        let mut canonical = [0u8; 32];
        canonical[..8].copy_from_slice(&(u32::MAX as u64).to_be_bytes());
        let mut byte_reversed = canonical;
        byte_reversed[..8].reverse();
        assert!(digest_has_leading_zero_bits(canonical, 32));
        assert!(!digest_has_leading_zero_bits(byte_reversed, 32));
    }

    #[test]
    fn grinding_ok_hashes_exact_state_domain_and_little_endian_nonce_chunks() {
        let transcript = Transcript::new(grinding_input_probe);
        assert!(transcript.grinding_ok(0x0102_0304_0506_0708, 32));
    }

    #[test]
    fn transcript_kat_pinned() {
        let digest = transcript_kat(test_hash);
        let mut hex = alloc::string::String::new();
        for b in digest {
            use core::fmt::Write;
            let _ = write!(hex, "{b:02x}");
        }
        assert_eq!(
            digest, TRANSCRIPT_KAT_EXPECTED,
            "transcript KAT drifted; computed {hex} — a deliberate protocol \
             change must re-pin TRANSCRIPT_KAT_EXPECTED and say so in the log"
        );
    }

    #[test]
    fn transcript_kat_v4_s2_pcs_scaffold_pinned() {
        let digest = transcript_kat_v4_s2_pcs_scaffold(test_hash);
        let mut hex = alloc::string::String::new();
        for byte in digest {
            use core::fmt::Write;
            let _ = write!(hex, "{byte:02x}");
        }
        assert_eq!(
            digest, TRANSCRIPT_KAT_V4_S2_PCS_SCAFFOLD_EXPECTED,
            "v4/s2 two-helper PCS-scaffold transcript KAT drifted; computed {hex} — update this diagnostic pin and its ledger entry only as one named protocol change"
        );
    }

    #[test]
    fn transcript_kat_final_payment_v4_pinned() {
        let digest = transcript_kat_final_payment_v4(test_hash);
        let mut hex = alloc::string::String::new();
        for byte in digest {
            use core::fmt::Write;
            let _ = write!(hex, "{byte:02x}");
        }
        assert_eq!(
            digest, TRANSCRIPT_KAT_FINAL_PAYMENT_V4_EXPECTED,
            "final payment-v4 transcript KAT drifted; computed {hex}"
        );
    }

    /// Adversarial backend: every squeezed word masks to P, so every draw is
    /// rejected and the bounded loop must exhaust with an error, not spin.
    fn all_p_hash(_inputs: &[&[u8]]) -> [u8; 32] {
        [0xFF; 32]
    }

    #[test]
    fn sampler_exhaustion_is_bounded_error() {
        let mut t = Transcript::new(all_p_hash);
        assert_eq!(t.challenge_qm31(), Err(ChallengeSampleExhausted));
    }

    #[test]
    fn ordered_queries_without_replacement_are_unique_bounded_and_deterministic() {
        let mut first = Transcript::new(test_hash);
        first.absorb(label::PROFILE, b"ordered-query-sampler-v1");
        let mut second = first.clone();
        let first_queries = first
            .challenge_queries_without_replacement(36, 1 << 12, 64)
            .unwrap();
        let second_queries = second
            .challenge_queries_without_replacement(36, 1 << 12, 64)
            .unwrap();
        assert_eq!(first_queries, second_queries);
        assert_eq!(first.diagnostic_state(), second.diagnostic_state());
        assert_eq!(first_queries.len(), 36);
        assert!(first_queries.iter().all(|query| *query < 1 << 12));
        for (index, query) in first_queries.iter().enumerate() {
            assert!(!first_queries[..index].contains(query));
        }
    }

    #[test]
    fn no_collision_without_replacement_sampling_is_legacy_byte_and_state_identical() {
        let mut legacy = Transcript::new(test_hash);
        legacy.absorb(label::PROFILE, b"query-sampler-no-collision-kat-v1");
        let mut distinct = legacy.clone();
        let legacy_queries = legacy.challenge_queries(36, 1 << 12);
        for (index, query) in legacy_queries.iter().enumerate() {
            assert!(
                !legacy_queries[..index].contains(query),
                "fixture unexpectedly contains a collision at {index}"
            );
        }
        let distinct_queries = distinct
            .challenge_queries_without_replacement(36, 1 << 12, 64)
            .unwrap();
        assert_eq!(distinct_queries, legacy_queries);
        assert_eq!(distinct.diagnostic_state(), legacy.diagnostic_state());
    }

    /// Adversarial query stream whose first two candidates collide. The
    /// sampler must skip the duplicate, consume the next block, and retain
    /// the order of the first occurrence of every accepted position.
    fn duplicate_query_prefix_hash(inputs: &[&[u8]]) -> [u8; 32] {
        if let Some(state) = framed_state(inputs, DOM_SQUEEZE) {
            let first = state[0] == 0;
            let words = if first {
                [7u32, 7, 8, 9, 10, 11, 12, 13]
            } else {
                [14u32, 15, 16, 17, 18, 19, 20, 21]
            };
            let mut block = [0u8; 32];
            for (index, word) in words.into_iter().enumerate() {
                block[index * 4..index * 4 + 4].copy_from_slice(&word.to_le_bytes());
            }
            block
        } else if let Some(state) = framed_state(inputs, DOM_ADVANCE) {
            let mut state: [u8; 32] = state.try_into().unwrap();
            state[0] = state[0].wrapping_add(1);
            state
        } else {
            test_hash(inputs)
        }
    }

    #[test]
    fn without_replacement_sampler_skips_an_adversarial_duplicate_prefix() {
        let mut transcript = Transcript::new(duplicate_query_prefix_hash);
        let queries = transcript
            .challenge_queries_without_replacement(8, 1 << 12, 16)
            .unwrap();
        assert_eq!(queries, [7, 8, 9, 10, 11, 12, 13, 14]);
        assert_eq!(transcript.diagnostic_state()[0], 2);
    }

    fn all_zero_hash(_inputs: &[&[u8]]) -> [u8; 32] {
        [0u8; 32]
    }

    fn zero_then_nonzero_hash(inputs: &[&[u8]]) -> [u8; 32] {
        if let Some(state) = framed_state(inputs, DOM_SQUEEZE) {
            let mut block = [0u8; 32];
            if state[0] != 0 {
                for (word, chunk) in block.chunks_exact_mut(4).enumerate() {
                    chunk.copy_from_slice(&(word as u32 + 1).to_le_bytes());
                }
            }
            block
        } else if let Some(state) = framed_state(inputs, DOM_ADVANCE) {
            let mut state: [u8; 32] = state.try_into().unwrap();
            state[0] = state[0].wrapping_add(1);
            state
        } else {
            test_hash(inputs)
        }
    }

    #[test]
    fn nonzero_qm31_sampler_rejects_zero_with_fresh_state_and_is_bounded() {
        let mut accepts_second = Transcript::new(zero_then_nonzero_hash);
        let value = accepts_second.challenge_nonzero_qm31().unwrap();
        assert_eq!(
            value,
            QM31 {
                c0: CM31::new(M31(1), M31(2)),
                c1: CM31::new(M31(3), M31(4)),
            }
        );
        assert_eq!(accepts_second.diagnostic_state()[0], 2);

        let mut exhausts = Transcript::new(all_zero_hash);
        assert_eq!(
            exhausts.challenge_nonzero_qm31(),
            Err(ChallengeSampleExhausted)
        );
    }

    #[test]
    fn without_replacement_query_sampler_has_explicit_bounded_exhaustion() {
        let mut transcript = Transcript::new(all_zero_hash);
        assert_eq!(
            transcript.challenge_queries_without_replacement(2, 8, 8),
            Err(QuerySampleError::DrawLimitExhausted {
                accepted: 1,
                max_draws: 8,
            })
        );
        let mut invalid = Transcript::new(test_hash);
        assert_eq!(
            invalid.challenge_queries_without_replacement(1, 7, 8),
            Err(QuerySampleError::BoundNotPowerOfTwo { bound: 7 })
        );
        assert_eq!(
            invalid.challenge_queries_without_replacement(9, 8, 16),
            Err(QuerySampleError::CountExceedsBound { count: 9, bound: 8 })
        );
    }

    fn cm31_only_hash(inputs: &[&[u8]]) -> [u8; 32] {
        if framed_state(inputs, DOM_SQUEEZE).is_some() {
            let mut block = [0u8; 32];
            block[0..4].copy_from_slice(&1u32.to_le_bytes());
            block[4..8].copy_from_slice(&2u32.to_le_bytes());
            // c1 limbs stay zero: every candidate is in the CM31 subfield.
            block
        } else {
            test_hash(inputs)
        }
    }

    #[test]
    fn ood_sampler_rejects_subfield_points_with_a_bound() {
        let mut t = Transcript::new(cm31_only_hash);
        assert_eq!(
            t.challenge_ood_qm31(),
            Err(OodSampleError::SubfieldSampleExhausted)
        );

        let mut circle = Transcript::new(cm31_only_hash);
        assert_eq!(
            circle.challenge_secure_circle_point(),
            Err(CirclePointSampleError::ParameterSampleExhausted)
        );
    }

    #[test]
    fn reference_circle_fallback_points_are_valid_distinct_and_outside_cm31() {
        for (sample, parameter) in CIRCLE_FALLBACK_PARAMETERS.iter().enumerate() {
            assert_ne!(parameter.c1, crate::field::CM31::ZERO);
            let point = secure_ood_circle_point_from_parameter(*parameter)
                .expect("fallback parameter must be accepted by the secure map");
            assert_eq!(circle_fallback_point(sample), point);
            // Outside CM31: the inverse parameter y/(1+x) has c1 ≠ 0, so the
            // point cannot have both coordinates in CM31.
            assert!(point.x.c1 != crate::field::CM31::ZERO || point.y.c1 != crate::field::CM31::ZERO);
        }
        assert_ne!(circle_fallback_point(0), circle_fallback_point(1));
    }

    #[test]
    fn reference_circle_sampler_uses_row_fallback_without_retry() {
        // Every block is a CM31 parameter: row 0 falls back to f0, row 1 to
        // f1, and each row consumes exactly the one block of its parameter.
        let mut t = Transcript::new(cm31_only_hash);
        let before = t.state;
        assert_eq!(t.challenge_reference_circle_point(0), Ok(circle_fallback_point(0)));
        let mut one_block = Transcript { state: before, hash: cm31_only_hash };
        let _ = one_block.challenge_qm31().unwrap();
        assert_eq!(t.state, one_block.state);
        assert_eq!(t.challenge_reference_circle_point(1), Ok(circle_fallback_point(1)));

        // Accepted draws agree with the legacy retry sampler on its first try.
        let mut legacy = Transcript::new(test_hash);
        let mut reference = Transcript::new(test_hash);
        for sample in 0..2 {
            assert_eq!(
                reference.challenge_reference_circle_point(sample).unwrap(),
                legacy.challenge_secure_circle_point().unwrap()
            );
        }
        assert_eq!(reference.state, legacy.state);
    }

    fn singular_circle_hash(inputs: &[&[u8]]) -> [u8; 32] {
        if framed_state(inputs, DOM_SQUEEZE).is_some() {
            let mut block = [0u8; 32];
            // t = i in CM31, hence 1+t^2 = 0. The pure helper reports the
            // singularity; the bounded transcript sampler retries then errs.
            block[4..8].copy_from_slice(&1u32.to_le_bytes());
            block
        } else {
            test_hash(inputs)
        }
    }

    #[test]
    fn circle_sampler_bounds_singular_parameter_retries() {
        let mut transcript = Transcript::new(singular_circle_hash);
        assert_eq!(
            transcript.challenge_secure_circle_point(),
            Err(CirclePointSampleError::ParameterSampleExhausted)
        );
    }

    /// Backend that rejects exactly the first draw: word 0 masks to P, the
    /// retry must consume the NEXT word (fresh bytes), not re-hash.
    fn first_word_p_hash(inputs: &[&[u8]]) -> [u8; 32] {
        if framed_state(inputs, DOM_SQUEEZE).is_some() {
            // DOM_SQUEEZE block: word0 = P (rejected), then 1, 2, 3, 4, ...
            let mut block = [0u8; 32];
            block[0..4].copy_from_slice(&0x7FFF_FFFFu32.to_le_bytes());
            for (w, chunk) in block[4..].chunks_exact_mut(4).enumerate() {
                chunk.copy_from_slice(&(w as u32 + 1).to_le_bytes());
            }
            block
        } else {
            test_hash(inputs)
        }
    }

    #[test]
    fn sampler_rejects_p_and_uses_fresh_word() {
        let mut t = Transcript::new(first_word_p_hash);
        let alpha = t.challenge_qm31().expect("must accept on retry");
        assert_eq!(
            alpha,
            QM31 {
                c0: CM31 {
                    a: M31(1),
                    b: M31(2)
                },
                c1: CM31 {
                    a: M31(3),
                    b: M31(4)
                },
            }
        );
        // and no limb can ever be the folded-P artifact of the old sampler
        assert!(alpha.c0.a.0 < P);
    }

    fn point_bytes(point: SecureCirclePoint) -> [u8; 32] {
        let mut bytes = [0u8; 32];
        point.x.write_le_bytes(&mut bytes[..16]);
        point.y.write_le_bytes(&mut bytes[16..]);
        bytes
    }

    fn circle_s2_fixture(weakened: bool) -> (SecureCirclePoint, SecureCirclePoint, [u8; 32]) {
        let mut transcript = Transcript::new(test_hash);
        transcript.absorb(label::PROFILE, b"aspis-circle-s2-sampler-fixture-v0");
        transcript.absorb(label::ROOT, &[0x31; 32]);

        let first = transcript
            .challenge_secure_circle_point()
            .expect("fixture first circle parameter must accept");
        let (second, first_mix, second_mix) = if weakened {
            // Deliberately wrong: squeeze the second point before the first
            // claimed value and mix bind the transcript.
            let second = transcript
                .challenge_secure_circle_point()
                .expect("weakened fixture second circle parameter must accept");
            transcript.absorb(label::OOD_VALUE, &[0x41; 16]);
            let first_mix = transcript.challenge_qm31().unwrap();
            transcript.absorb(label::OOD_VALUE, &[0x42; 16]);
            let second_mix = transcript.challenge_qm31().unwrap();
            (second, first_mix, second_mix)
        } else {
            transcript.absorb(label::OOD_VALUE, &[0x41; 16]);
            let first_mix = transcript.challenge_qm31().unwrap();
            let second = transcript
                .challenge_secure_circle_point()
                .expect("fixture second circle parameter must accept");
            transcript.absorb(label::OOD_VALUE, &[0x42; 16]);
            let second_mix = transcript.challenge_qm31().unwrap();
            (second, first_mix, second_mix)
        };

        let first_bytes = point_bytes(first);
        let second_bytes = point_bytes(second);
        let mut first_mix_bytes = [0u8; 16];
        let mut second_mix_bytes = [0u8; 16];
        first_mix.write_le_bytes(&mut first_mix_bytes);
        second_mix.write_le_bytes(&mut second_mix_bytes);
        let digest = test_hash(&[
            &first_bytes,
            &first_mix_bytes,
            &second_bytes,
            &second_mix_bytes,
        ]);
        (first, second, digest)
    }

    #[test]
    fn two_sequential_circle_samples_fixture_is_pinned() {
        let (first, second, digest) = circle_s2_fixture(false);
        assert_ne!(first, second);
        for point in [first, second] {
            assert_eq!(point.x.square().add(point.y.square()), QM31::ONE);
            assert!(point.x.c1 != CM31::ZERO || point.y.c1 != CM31::ZERO);
        }
        assert_eq!(digest, CIRCLE_S2_FIXTURE_EXPECTED);
    }

    #[test]
    fn weakened_two_sample_ordering_has_teeth() {
        let (canonical_first, canonical_second, canonical_digest) = circle_s2_fixture(false);
        let (weakened_first, weakened_second, weakened_digest) = circle_s2_fixture(true);
        assert_eq!(canonical_first, weakened_first);
        assert_ne!(canonical_second, weakened_second);
        assert_ne!(canonical_digest, weakened_digest);
    }
}

crates/aspis-core/src/v6_onefold.rs:
//! Host/SBF-neutral wire prototype for the selected V6 one-fold profile.
//!
//! This is deliberately isolated from every deployed instruction. It fixes
//! the 26-C1 + 3-C2 byte arithmetic, rejects non-canonical packed M31 limbs,
//! derives the exact body length from the two public frontier counts, and
//! exposes borrowed sections without allocating.

use alloc::vec::Vec;

use crate::circle_fri::{
    line_domain_x_for_circle, normalized_circle_to_line_arity4_prepared_polynomial_refs,
    selected_circle_fiber_points_shared,
};
use crate::field::{
    m31_batch_inverse, qm31_sum_products3_prepared, PreparedQm31Multiplier, CM31, M31, P, QM31,
};
use crate::merkle::verify_two_minimal_subtrees_bytes;
use crate::state_only_private_merkle::private_leaf_hash;
use crate::state_only_spend_query::StateOnlySpendQueryPowers;
use crate::HashFn;

pub const V6_C1_COLUMNS: usize = 26;
pub const V6_C2_COLUMNS: usize = 3;
pub const V6_TOTAL_COLUMNS: usize = V6_C1_COLUMNS + V6_C2_COLUMNS;
pub const V6_QUERY_COUNT: usize = 16;
pub const V6_FRONTIER_CAP_PER_TREE: usize = 209;
pub const V6_SEMANTIC_ROUNDS: usize = 10;
pub const V6_SEMANTIC_SENT_VALUES: usize = 27;
/// Three PCS evaluation rows: `z`, the binary successor of `z`, and the
/// low-bit-XOR-12 point.  The selected 26+3 hiding terminal is already a
/// public function of these rows.  V5's fourth structured-mask row therefore
/// has no role in this profile and is deliberately absent.
pub const V6_POINT_CLAIM_ROWS: usize = 3;
pub const V6_RELATION_ROUNDS: usize = 4;
pub const V6_RELATION_SENT_VALUES: usize = 6;
pub const V6_INITIAL_CLAIM_OFFSET: usize = 0;
pub const V6_SEMANTIC_QM31_OFFSET: usize = V6_INITIAL_CLAIM_OFFSET + 1;
pub const V6_POINT_CLAIMS_QM31_OFFSET: usize =
    V6_SEMANTIC_QM31_OFFSET + V6_SEMANTIC_ROUNDS * V6_SEMANTIC_SENT_VALUES;
pub const V6_INACTIVE_CLAIM_QM31_OFFSET: usize =
    V6_POINT_CLAIMS_QM31_OFFSET + V6_POINT_CLAIM_ROWS * V6_TOTAL_COLUMNS;
pub const V6_OOD_QM31_OFFSET: usize = V6_INACTIVE_CLAIM_QM31_OFFSET + 1;
pub const V6_RELATION_QM31_OFFSET: usize = V6_OOD_QM31_OFFSET + 2;
pub const V6_FINAL_QM31_OFFSET: usize =
    V6_RELATION_QM31_OFFSET + V6_RELATION_ROUNDS * V6_RELATION_SENT_VALUES;
pub const V6_FINAL_QM31_VALUES: usize = 256;
pub const V6_FIXED_QM31_VALUES: usize = V6_FINAL_QM31_OFFSET + V6_FINAL_QM31_VALUES;
pub const V6_FIXED_M31_LIMBS: usize = 4 * V6_FIXED_QM31_VALUES;
pub const V6_FIXED_PACKED_FIELD_BYTES: usize = packed_bytes(V6_FIXED_M31_LIMBS);
pub const V6_ROOT_BYTES: usize = 2 * 32;
pub const V6_WORK_NONCE_BYTES: usize = 3 * 8;
pub const V6_FIXED_BYTES: usize = V6_FIXED_PACKED_FIELD_BYTES + V6_ROOT_BYTES + V6_WORK_NONCE_BYTES;

pub const V6_C1_LIMBS_PER_QUERY: usize = 4 * V6_C1_COLUMNS;
pub const V6_C2_LIMBS_PER_QUERY: usize = 4 * 4 * V6_C2_COLUMNS;
pub const V6_C1_PACKED_BYTES_PER_QUERY: usize = packed_bytes(V6_C1_LIMBS_PER_QUERY);
pub const V6_C2_PACKED_BYTES_PER_QUERY: usize = packed_bytes(V6_C2_LIMBS_PER_QUERY);
pub const V6_PRIVATE_SALT_BYTES: usize = 32;
pub const V6_QUERY_BYTES: usize =
    V6_C1_PACKED_BYTES_PER_QUERY + V6_C2_PACKED_BYTES_PER_QUERY + V6_PRIVATE_SALT_BYTES;
pub const V6_QUERY_SECTION_BYTES: usize = V6_QUERY_COUNT * V6_QUERY_BYTES;
pub const V6_BODY_WITHOUT_FRONTIERS: usize = V6_FIXED_BYTES + V6_QUERY_SECTION_BYTES;
pub const V6_MAX_BODY_BYTES: usize = V6_BODY_WITHOUT_FRONTIERS + 2 * V6_FRONTIER_CAP_PER_TREE * 32;
pub const V6_HARD_BODY_LIMIT: usize = 40 * 1024;
pub const V6_C1_TREE_TAG: u8 = 0x70;
pub const V6_C2_TREE_TAG: u8 = 0xf0;

const fn packed_bytes(limbs: usize) -> usize {
    (limbs * 31 + 7) / 8
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum V6WireError {
    FrontierTooLarge,
    WrongLength,
    NonCanonicalM31,
    InvalidQuerySchedule,
    MerkleMismatch,
    FriMismatch,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct V6QueryRecord<'a> {
    pub c1_packed: &'a [u8],
    pub c2_packed: &'a [u8],
    pub salt: &'a [u8; V6_PRIVATE_SALT_BYTES],
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct V6OneFoldWire<'a> {
    pub fixed_fields_packed: &'a [u8],
    pub c1_root: &'a [u8; 32],
    pub c2_root: &'a [u8; 32],
    pub work_nonces: &'a [u8; V6_WORK_NONCE_BYTES],
    query_section: &'a [u8],
    pub c1_frontier: &'a [u8],
    pub c2_frontier: &'a [u8],
}

impl<'a> V6OneFoldWire<'a> {
    pub fn parse(
        bytes: &'a [u8],
        c1_frontier_nodes: usize,
        c2_frontier_nodes: usize,
    ) -> Result<Self, V6WireError> {
        let wire = Self::parse_layout(bytes, c1_frontier_nodes, c2_frontier_nodes)?;
        validate_packed_m31(wire.fixed_fields_packed, V6_FIXED_M31_LIMBS)?;
        for query in 0..V6_QUERY_COUNT {
            let start = query * V6_QUERY_BYTES;
            let c1_end = start + V6_C1_PACKED_BYTES_PER_QUERY;
            let c2_end = c1_end + V6_C2_PACKED_BYTES_PER_QUERY;
            validate_packed_m31(&wire.query_section[start..c1_end], V6_C1_LIMBS_PER_QUERY)?;
            validate_packed_m31(&wire.query_section[c1_end..c2_end], V6_C2_LIMBS_PER_QUERY)?;
        }
        Ok(wire)
    }

    /// Parse exact section boundaries while deferring field canonicality to
    /// the consumers that already decode each section.
    ///
    /// A complete verifier must consume and canonically decode every field.
    /// This avoids a redundant whole-proof scan; it does not permit any field
    /// to remain unchecked.
    pub fn parse_deferred_canonicality(
        bytes: &'a [u8],
        c1_frontier_nodes: usize,
        c2_frontier_nodes: usize,
    ) -> Result<Self, V6WireError> {
        Self::parse_layout(bytes, c1_frontier_nodes, c2_frontier_nodes)
    }

    #[inline(always)]
    fn parse_layout(
        bytes: &'a [u8],
        c1_frontier_nodes: usize,
        c2_frontier_nodes: usize,
    ) -> Result<Self, V6WireError> {
        if c1_frontier_nodes > V6_FRONTIER_CAP_PER_TREE
            || c2_frontier_nodes > V6_FRONTIER_CAP_PER_TREE
        {
            return Err(V6WireError::FrontierTooLarge);
        }
        let c1_frontier_bytes = c1_frontier_nodes
            .checked_mul(32)
            .ok_or(V6WireError::WrongLength)?;
        let c2_frontier_bytes = c2_frontier_nodes
            .checked_mul(32)
            .ok_or(V6WireError::WrongLength)?;
        let expected = V6_BODY_WITHOUT_FRONTIERS
            .checked_add(c1_frontier_bytes)
            .and_then(|n| n.checked_add(c2_frontier_bytes))
            .ok_or(V6WireError::WrongLength)?;
        if bytes.len() != expected || bytes.len() > V6_HARD_BODY_LIMIT {
            return Err(V6WireError::WrongLength);
        }

        let (fixed_fields_packed, rest) = bytes.split_at(V6_FIXED_PACKED_FIELD_BYTES);
        // The fixed section occupies 79,484 meaningful bits in 9,936 bytes.
        // Reject its four otherwise-ignored high bits even on the fused
        // deferred-canonicality path, so accepted proof bytes are unique.
        validate_packed_padding(fixed_fields_packed, V6_FIXED_M31_LIMBS)?;
        let (c1_root_bytes, rest) = rest.split_at(32);
        let (c2_root_bytes, rest) = rest.split_at(32);
        let (nonce_bytes, rest) = rest.split_at(V6_WORK_NONCE_BYTES);
        let (query_section, rest) = rest.split_at(V6_QUERY_SECTION_BYTES);

        let (c1_frontier, c2_frontier) = rest.split_at(c1_frontier_bytes);
        debug_assert_eq!(c2_frontier.len(), c2_frontier_bytes);
        Ok(Self {
            fixed_fields_packed,
            c1_root: c1_root_bytes
                .try_into()
                .map_err(|_| V6WireError::WrongLength)?,
            c2_root: c2_root_bytes
                .try_into()
                .map_err(|_| V6WireError::WrongLength)?,
            work_nonces: nonce_bytes
                .try_into()
                .map_err(|_| V6WireError::WrongLength)?,
            query_section,
            c1_frontier,
            c2_frontier,
        })
    }

    pub fn query(&self, index: usize) -> Option<V6QueryRecord<'a>> {
        if index >= V6_QUERY_COUNT {
            return None;
        }
        let start = index * V6_QUERY_BYTES;
        let c1_end = start + V6_C1_PACKED_BYTES_PER_QUERY;
        let c2_end = c1_end + V6_C2_PACKED_BYTES_PER_QUERY;
        let end = c2_end + V6_PRIVATE_SALT_BYTES;
        Some(V6QueryRecord {
            c1_packed: &self.query_section[start..c1_end],
            c2_packed: &self.query_section[c1_end..c2_end],
            salt: self.query_section[c2_end..end].try_into().ok()?,
        })
    }
}

/// Free-function source-translation boundary for the exact deferred parser
/// used by the V6 production verifier.  Charon cannot select an inherent
/// method as a translation root, so keep this wrapper in the production call
/// graph and force it to inline in the SBF build.
#[inline(always)]
pub fn parse_v6_onefold_wire_deferred(
    bytes: &[u8],
    c1_frontier_nodes: usize,
    c2_frontier_nodes: usize,
) -> Result<V6OneFoldWire<'_>, V6WireError> {
    V6OneFoldWire::parse_deferred_canonicality(bytes, c1_frontier_nodes, c2_frontier_nodes)
}

pub fn packed_m31_at(bytes: &[u8], index: usize) -> Option<u32> {
    let bit_start = index.checked_mul(31)?;
    if bit_start.checked_add(31)? > bytes.len().checked_mul(8)? {
        return None;
    }
    let byte_start = bit_start / 8;
    let shift = bit_start % 8;
    let mut window = 0u64;
    let available = core::cmp::min(5, bytes.len() - byte_start);
    for offset in 0..available {
        window |= u64::from(bytes[byte_start + offset]) << (8 * offset);
    }
    Some(((window >> shift) & 0x7fff_ffff) as u32)
}

pub fn packed_qm31_at(bytes: &[u8], index: usize) -> Option<QM31> {
    let limb = index.checked_mul(4)?;
    Some(QM31 {
        c0: CM31::new(
            M31(packed_m31_at(bytes, limb)?),
            M31(packed_m31_at(bytes, limb + 1)?),
        ),
        c1: CM31::new(
            M31(packed_m31_at(bytes, limb + 2)?),
            M31(packed_m31_at(bytes, limb + 3)?),
        ),
    })
}

/// Sequential reader for the proof's little-endian 31-bit limb packing.
///
/// Query-record sections contain a multiple of eight limbs, so their final
/// limb ends on a byte boundary. The fixed-field section has four padding
/// bits; its parser rejects nonzero padding before any consumer is invoked.
struct PackedM31Reader<'a> {
    bytes: &'a [u8],
    byte_index: usize,
    buffer: u64,
    buffered_bits: u8,
}

/// Canonical one-pass decoder for the protocol-fixed 641-QM31 field section.
///
/// The V6 transcript consumes every fixed field exactly once. Keeping the
/// bit buffer across fields avoids recomputing 2,564 limb offsets and loading
/// overlapping five-byte windows, while returning the same canonical QM31
/// values as [`packed_qm31_at`].
pub(crate) trait V6FixedFieldStream {
    fn next_qm31(&mut self) -> Result<QM31, V6WireError>;
    fn finish(self) -> Result<(), V6WireError>;
}

pub(crate) struct V6FixedFieldReader<'a> {
    packed: PackedM31Reader<'a>,
    remaining: usize,
}

impl<'a> V6FixedFieldReader<'a> {
    pub(crate) fn new(bytes: &'a [u8]) -> Result<Self, V6WireError> {
        validate_packed_padding(bytes, V6_FIXED_M31_LIMBS)?;
        Ok(Self {
            packed: PackedM31Reader::new(bytes),
            remaining: V6_FIXED_QM31_VALUES,
        })
    }

    #[inline(always)]
    pub(crate) fn next_qm31(&mut self) -> Result<QM31, V6WireError> {
        if self.remaining == 0 {
            return Err(V6WireError::WrongLength);
        }
        let value = self.packed.qm31();
        self.remaining -= 1;
        if value.c0.a.0 >= P || value.c0.b.0 >= P || value.c1.a.0 >= P || value.c1.b.0 >= P {
            return Err(V6WireError::NonCanonicalM31);
        }
        Ok(value)
    }

    pub(crate) fn finish(self) -> Result<(), V6WireError> {
        if self.remaining == 0 {
            Ok(())
        } else {
            Err(V6WireError::WrongLength)
        }
    }
}

impl V6FixedFieldStream for V6FixedFieldReader<'_> {
    #[inline(always)]
    fn next_qm31(&mut self) -> Result<QM31, V6WireError> {
        V6FixedFieldReader::next_qm31(self)
    }

    fn finish(self) -> Result<(), V6WireError> {
        V6FixedFieldReader::finish(self)
    }
}

impl<'a> PackedM31Reader<'a> {
    #[inline(always)]
    fn new(bytes: &'a [u8]) -> Self {
        Self {
            bytes,
            byte_index: 0,
            buffer: 0,
            buffered_bits: 0,
        }
    }

    #[inline(always)]
    fn next(&mut self) -> u32 {
        while self.buffered_bits < 31 {
            debug_assert!(self.byte_index < self.bytes.len());
            self.buffer |= u64::from(self.bytes[self.byte_index]) << self.buffered_bits;
            self.byte_index += 1;
            self.buffered_bits += 8;
        }
        let value = (self.buffer & 0x7fff_ffff) as u32;
        self.buffer >>= 31;
        self.buffered_bits -= 31;
        value
    }

    #[inline(always)]
    fn qm31(&mut self) -> QM31 {
        QM31 {
            c0: CM31::new(M31(self.next()), M31(self.next())),
            c1: CM31::new(M31(self.next()), M31(self.next())),
        }
    }
}

/// Decode a byte-aligned stream whose limb count is a multiple of eight.
///
/// Eight packed 31-bit limbs occupy exactly 31 bytes.  Loading each limb from
/// its containing little-endian machine word removes the byte-at-a-time
/// refill loop from the q16 opening hot path while preserving the literal bit
/// layout and the `P` rejection.  The V6/V7 query sections have fixed widths
/// 104 and 48, so both are exact multiples of eight with no padding bits.
#[inline(always)]
fn decode_packed_m31_eight_aligned<const N: usize>(bytes: &[u8]) -> Result<[u32; N], V6WireError> {
    if N == 0 || N % 8 != 0 || bytes.len() != (N / 8) * 31 {
        return Err(V6WireError::WrongLength);
    }
    let mut output = [0u32; N];
    let mut invalid = 0u32;
    let mut block = 0usize;
    while block < N / 8 {
        let byte = block * 31;
        let chunk = &bytes[byte..byte + 31];
        let load64 =
            |offset: usize| u64::from_le_bytes(chunk[offset..offset + 8].try_into().unwrap());
        let base = block * 8;
        output[base] = (load64(0) & u64::from(P)) as u32;
        output[base + 1] = ((load64(3) >> 7) & u64::from(P)) as u32;
        output[base + 2] = ((load64(7) >> 6) & u64::from(P)) as u32;
        output[base + 3] = ((load64(11) >> 5) & u64::from(P)) as u32;
        output[base + 4] = ((load64(15) >> 4) & u64::from(P)) as u32;
        output[base + 5] = ((load64(19) >> 3) & u64::from(P)) as u32;
        output[base + 6] = ((load64(23) >> 2) & u64::from(P)) as u32;
        output[base + 7] = (u32::from_le_bytes(chunk[27..31].try_into().unwrap()) >> 1) & P;
        for value in &output[base..base + 8] {
            invalid |= u32::from(*value >= P);
        }
        block += 1;
    }
    if invalid == 0 {
        Ok(output)
    } else {
        Err(V6WireError::NonCanonicalM31)
    }
}

pub fn validate_packed_m31(bytes: &[u8], limbs: usize) -> Result<(), V6WireError> {
    if bytes.len() != packed_bytes(limbs) {
        return Err(V6WireError::WrongLength);
    }
    for index in 0..limbs {
        let value = packed_m31_at(bytes, index).ok_or(V6WireError::WrongLength)?;
        if value >= P {
            return Err(V6WireError::NonCanonicalM31);
        }
    }
    let used_bits = limbs * 31;
    for bit in used_bits..bytes.len() * 8 {
        if ((bytes[bit / 8] >> (bit % 8)) & 1) != 0 {
            return Err(V6WireError::NonCanonicalM31);
        }
    }
    Ok(())
}

#[inline(always)]
fn validate_packed_padding(bytes: &[u8], limbs: usize) -> Result<(), V6WireError> {
    if bytes.len() != packed_bytes(limbs) {
        return Err(V6WireError::WrongLength);
    }
    let used_in_last_byte = (limbs * 31) % 8;
    if used_in_last_byte != 0 {
        let unused_mask = !((1u8 << used_in_last_byte) - 1);
        if bytes.last().copied().unwrap_or_default() & unused_mask != 0 {
            return Err(V6WireError::NonCanonicalM31);
        }
    }
    Ok(())
}

/// Number of sibling hashes in the minimal binary authentication frontier.
///
/// The input may arrive in any order. Duplicates and indices outside the
/// depth-`depth` tree are rejected. For sorted leaves `q[i]`, the exact count
/// is
///
/// `depth + 1 - Q + sum_i floor(log2(q[i] XOR q[i + 1]))`.
///
/// This is the level-walk count written in terms of adjacent common prefixes:
/// at level `l`, the number of active parents is one plus the number of
/// adjacent pairs whose shifted indices still differ. It avoids rebuilding
/// all eighteen parent levels for every rejected compact-query candidate.
pub fn binary_frontier_nodes<const Q: usize>(
    mut queries: [u32; Q],
    depth: u8,
) -> Result<usize, V6WireError> {
    if Q == 0 || depth >= 32 {
        return Err(V6WireError::InvalidQuerySchedule);
    }
    let leaf_count = 1u32
        .checked_shl(u32::from(depth))
        .ok_or(V6WireError::InvalidQuerySchedule)?;

    for index in 1..Q {
        let value = queries[index];
        let mut cursor = index;
        while cursor > 0 && value < queries[cursor - 1] {
            queries[cursor] = queries[cursor - 1];
            cursor -= 1;
        }
        queries[cursor] = value;
    }
    if queries[Q - 1] >= leaf_count {
        return Err(V6WireError::InvalidQuerySchedule);
    }
    for index in 1..Q {
        if queries[index - 1] == queries[index] {
            return Err(V6WireError::InvalidQuerySchedule);
        }
    }

    let mut expanded = usize::from(depth) + 1;
    for pair in queries.windows(2) {
        let differing_bits = pair[0] ^ pair[1];
        debug_assert!(differing_bits != 0);
        expanded += (u32::BITS - 1 - differing_bits.leading_zeros()) as usize;
    }
    expanded
        .checked_sub(Q)
        .ok_or(V6WireError::InvalidQuerySchedule)
}

/// Return the first compact candidate and reject malformed candidate streams.
/// A future transcript driver must derive `candidates` itself; accepting a
/// proof-carried counter without checking every earlier candidate is unsafe.
pub fn first_compact_candidate<const Q: usize, const C: usize>(
    candidates: &[[u32; Q]; C],
    depth: u8,
    frontier_cap: usize,
) -> Result<Option<(usize, usize)>, V6WireError> {
    for (index, candidate) in candidates.iter().enumerate() {
        let frontier = binary_frontier_nodes(*candidate, depth)?;
        if frontier <= frontier_cap {
            return Ok(Some((index, frontier)));
        }
    }
    Ok(None)
}

/// Authenticate the sixteen packed C1 and C2 records against two distinct
/// typed binary trees. Each query uses one shared hidden salt, but the tree
/// tags make a C1 leaf and a C2 leaf different hash inputs even when their
/// values happen to agree.
pub fn verify_v6_binary_openings(
    hash: HashFn,
    wire: &V6OneFoldWire<'_>,
    queries: [u32; V6_QUERY_COUNT],
) -> Result<(), V6WireError> {
    let mut order: [(u32, usize); V6_QUERY_COUNT] =
        core::array::from_fn(|ordinal| (queries[ordinal], ordinal));
    order.sort_unstable_by_key(|entry| entry.0);
    if order[V6_QUERY_COUNT - 1].0 >= 1 << 18 {
        return Err(V6WireError::InvalidQuerySchedule);
    }
    for pair in order.windows(2) {
        if pair[0].0 == pair[1].0 {
            return Err(V6WireError::InvalidQuerySchedule);
        }
    }

    let mut entries = Vec::with_capacity(V6_QUERY_COUNT);
    for (query, ordinal) in order {
        let record = wire
            .query(ordinal)
            .ok_or(V6WireError::InvalidQuerySchedule)?;
        validate_packed_m31(record.c1_packed, V6_C1_LIMBS_PER_QUERY)?;
        validate_packed_m31(record.c2_packed, V6_C2_LIMBS_PER_QUERY)?;
        entries.push((
            query,
            private_leaf_hash(hash, V6_C1_TREE_TAG, record.c1_packed, record.salt),
            private_leaf_hash(hash, V6_C2_TREE_TAG, record.c2_packed, record.salt),
        ));
    }

    let mut level = Vec::with_capacity(V6_QUERY_COUNT);
    let mut next = Vec::with_capacity(V6_QUERY_COUNT);
    if !verify_two_minimal_subtrees_bytes(
        hash,
        (wire.c1_root, wire.c2_root),
        18,
        &entries,
        (wire.c1_frontier, wire.c2_frontier),
        &mut level,
        &mut next,
    ) {
        return Err(V6WireError::MerkleMismatch);
    }
    Ok(())
}

/// Authenticate and gamma-combine the same packed records in one decoding
/// pass. This is the composed verifier path: the combination routine performs
/// the canonical M31 checks that the Merkle-only wrapper performs separately,
/// while the hash still binds the exact packed bytes and shared salt.
pub fn verify_and_gamma_combine_v6_binary_openings(
    hash: HashFn,
    wire: &V6OneFoldWire<'_>,
    queries: [u32; V6_QUERY_COUNT],
    gamma: QM31,
) -> Result<[[QM31; 4]; V6_QUERY_COUNT], V6WireError> {
    let powers = StateOnlySpendQueryPowers::new(gamma);
    verify_and_gamma_combine_v6_binary_openings_prepared(hash, wire, queries, &powers)
}

/// Prepared-power twin of [`verify_and_gamma_combine_v6_binary_openings`].
/// The caller may reuse the exact gamma table already consumed by another
/// linear claim; authentication and canonical decoding are unchanged.
pub fn verify_and_gamma_combine_v6_binary_openings_prepared(
    hash: HashFn,
    wire: &V6OneFoldWire<'_>,
    queries: [u32; V6_QUERY_COUNT],
    powers: &StateOnlySpendQueryPowers,
) -> Result<[[QM31; 4]; V6_QUERY_COUNT], V6WireError> {
    let mut order: [(u32, usize); V6_QUERY_COUNT] =
        core::array::from_fn(|ordinal| (queries[ordinal], ordinal));
    order.sort_unstable_by_key(|entry| entry.0);
    if order[V6_QUERY_COUNT - 1].0 >= 1 << 18 {
        return Err(V6WireError::InvalidQuerySchedule);
    }
    for pair in order.windows(2) {
        if pair[0].0 == pair[1].0 {
            return Err(V6WireError::InvalidQuerySchedule);
        }
    }

    let mut combined = [[QM31::ZERO; 4]; V6_QUERY_COUNT];
    let mut entries = Vec::with_capacity(V6_QUERY_COUNT);
    for (query, ordinal) in order {
        let record = wire
            .query(ordinal)
            .ok_or(V6WireError::InvalidQuerySchedule)?;
        combined[ordinal] =
            gamma_combine_v6_packed_layer0(record.c1_packed, record.c2_packed, powers)?;
        entries.push((
            query,
            private_leaf_hash(hash, V6_C1_TREE_TAG, record.c1_packed, record.salt),
            private_leaf_hash(hash, V6_C2_TREE_TAG, record.c2_packed, record.salt),
        ));
    }

    let mut level = Vec::with_capacity(V6_QUERY_COUNT);
    let mut next = Vec::with_capacity(V6_QUERY_COUNT);
    if !verify_two_minimal_subtrees_bytes(
        hash,
        (wire.c1_root, wire.c2_root),
        18,
        &entries,
        (wire.c1_frontier, wire.c2_frontier),
        &mut level,
        &mut next,
    ) {
        return Err(V6WireError::MerkleMismatch);
    }
    Ok(combined)
}

/// Combine one packed 26-M31-plus-3-QM31 fibre with the exact scalar-power
/// table used by the selected state-only spend profile.
#[inline(never)]
pub fn gamma_combine_v6_packed_layer0(
    c1_packed: &[u8],
    c2_packed: &[u8],
    powers: &StateOnlySpendQueryPowers,
) -> Result<[QM31; 4], V6WireError> {
    if c1_packed.len() != V6_C1_PACKED_BYTES_PER_QUERY
        || c2_packed.len() != V6_C2_PACKED_BYTES_PER_QUERY
    {
        return Err(V6WireError::WrongLength);
    }

    let c1 = decode_packed_m31_eight_aligned::<V6_C1_LIMBS_PER_QUERY>(c1_packed)?;
    #[cfg(not(feature = "v7-gamma-four-slot-block-audit"))]
    let mut combined = gamma_combine_v6_c1_slot_major(&c1, powers);
    #[cfg(feature = "v7-gamma-four-slot-block-audit")]
    let mut combined = gamma_combine_v6_c1_four_slot_block(&c1, powers);

    let helper_powers = [powers.base.helpers[0], powers.base.helpers[1], powers.d];
    let c2 = decode_packed_m31_eight_aligned::<V6_C2_LIMBS_PER_QUERY>(c2_packed)?;
    let mut helpers = [[QM31::ZERO; 4]; V6_C2_COLUMNS];
    for (helper, values) in helpers.iter_mut().enumerate() {
        for (slot, value) in values.iter_mut().enumerate() {
            let limb = 4 * (helper * 4 + slot);
            *value = QM31 {
                c0: CM31::new(M31(c2[limb]), M31(c2[limb + 1])),
                c1: CM31::new(M31(c2[limb + 2]), M31(c2[limb + 3])),
            };
        }
    }
    for (slot, output) in combined.iter_mut().enumerate() {
        let values = [helpers[0][slot], helpers[1][slot], helpers[2][slot]];
        *output = output.add(qm31_sum_products3_prepared(&helper_powers, &values));
    }
    Ok(combined)
}

#[cfg(any(test, not(feature = "v7-gamma-four-slot-block-audit")))]
#[inline(never)]
fn gamma_combine_v6_c1_slot_major(
    c1: &[u32; V6_C1_LIMBS_PER_QUERY],
    powers: &StateOnlySpendQueryPowers,
) -> [QM31; 4] {
    let mut combined = [QM31::ZERO; 4];
    for (slot, output) in combined.iter_mut().enumerate() {
        let mut sums = [0u64; 4];
        for block in 0..(V6_C1_COLUMNS / 4) {
            let mut raw = [0u64; 4];
            for column in block * 4..block * 4 + 4 {
                let value = c1[slot * V6_C1_COLUMNS + column];
                let value = u64::from(value & P);
                let limbs = powers.base.c1_limbs[column];
                for limb in 0..4 {
                    raw[limb] += u64::from(limbs[limb]) * value;
                }
            }
            for limb in 0..4 {
                sums[limb] += u64::from(M31::reduce_u64(raw[limb]).0);
            }
        }
        let mut raw = [0u64; 4];
        for column in V6_C1_COLUMNS - 2..V6_C1_COLUMNS {
            let value = c1[slot * V6_C1_COLUMNS + column];
            let value = u64::from(value & P);
            let limbs = powers.base.c1_limbs[column];
            for limb in 0..4 {
                raw[limb] += u64::from(limbs[limb]) * value;
            }
        }
        for limb in 0..4 {
            sums[limb] += u64::from(M31::reduce_u64(raw[limb]).0);
        }
        *output = QM31 {
            c0: CM31::new(M31::reduce_u64(sums[0]), M31::reduce_u64(sums[1])),
            c1: CM31::new(M31::reduce_u64(sums[2]), M31::reduce_u64(sums[3])),
        };
    }
    combined
}

/// Exact loop-interchanged twin of `gamma_combine_v6_c1_slot_major`.
///
/// The fixed 26-column power row is consumed once for all four slots.  Every
/// block uses the same four-term integer dot products and the same M31
/// reduction boundaries as the literal slot-major evaluator, so this changes
/// neither the field expression nor its reduction order within any output.
#[cfg(any(test, feature = "v7-gamma-four-slot-block-audit"))]
#[inline(never)]
fn gamma_combine_v6_c1_four_slot_block(
    c1: &[u32; V6_C1_LIMBS_PER_QUERY],
    powers: &StateOnlySpendQueryPowers,
) -> [QM31; 4] {
    let mut sums = [[0u64; 4]; 4];
    for block in 0..(V6_C1_COLUMNS / 4) {
        let mut raw = [[0u64; 4]; 4];
        for column in block * 4..block * 4 + 4 {
            let limbs = powers.base.c1_limbs[column];
            for slot in 0..4 {
                let value = u64::from(c1[slot * V6_C1_COLUMNS + column]);
                for limb in 0..4 {
                    raw[slot][limb] += u64::from(limbs[limb]) * value;
                }
            }
        }
        for slot in 0..4 {
            for limb in 0..4 {
                sums[slot][limb] += u64::from(M31::reduce_u64(raw[slot][limb]).0);
            }
        }
    }

    let mut raw = [[0u64; 4]; 4];
    for column in V6_C1_COLUMNS - 2..V6_C1_COLUMNS {
        let limbs = powers.base.c1_limbs[column];
        for slot in 0..4 {
            let value = u64::from(c1[slot * V6_C1_COLUMNS + column]);
            for limb in 0..4 {
                raw[slot][limb] += u64::from(limbs[limb]) * value;
            }
        }
    }
    for slot in 0..4 {
        for limb in 0..4 {
            sums[slot][limb] += u64::from(M31::reduce_u64(raw[slot][limb]).0);
        }
    }

    core::array::from_fn(|slot| QM31 {
        c0: CM31::new(
            M31::reduce_u64(sums[slot][0]),
            M31::reduce_u64(sums[slot][1]),
        ),
        c1: CM31::new(
            M31::reduce_u64(sums[slot][2]),
            M31::reduce_u64(sums[slot][3]),
        ),
    })
}

fn natural_line_weights_256(mut point: M31) -> [M31; V6_FINAL_QM31_VALUES] {
    let mut factors = [M31::ZERO; 8];
    for factor in &mut factors {
        *factor = point;
        point = point.mul(point).double().sub(M31::ONE);
    }
    let mut weights = [M31::ZERO; V6_FINAL_QM31_VALUES];
    weights[0] = M31::ONE;
    for index in 1..V6_FINAL_QM31_VALUES {
        let bit = index.trailing_zeros() as usize;
        weights[index] = weights[index ^ (1usize << bit)].mul(factors[bit]);
    }
    weights
}

/// Evaluate the disclosed 256-coefficient natural line tensor directly from
/// its packed 31-bit representation. This needs a 1-KiB M31 weight table and
/// never materializes the 4-KiB QM31 coefficient vector on the SBF stack.
pub fn evaluate_packed_final256(
    fixed_fields_packed: &[u8],
    point: M31,
) -> Result<QM31, V6WireError> {
    if fixed_fields_packed.len() != V6_FIXED_PACKED_FIELD_BYTES {
        return Err(V6WireError::WrongLength);
    }
    let weights = natural_line_weights_256(point);
    let mut result = QM31::ZERO;
    for (index, weight) in weights.iter().copied().enumerate() {
        let coefficient = packed_qm31_at(fixed_fields_packed, V6_FINAL_QM31_OFFSET + index)
            .ok_or(V6WireError::WrongLength)?;
        if coefficient.c0.a.0 >= P
            || coefficient.c0.b.0 >= P
            || coefficient.c1.a.0 >= P
            || coefficient.c1.b.0 >= P
        {
            return Err(V6WireError::NonCanonicalM31);
        }
        result = result.add(coefficient.mul_m31(weight));
    }
    Ok(result)
}

pub fn evaluate_packed_final256_at_query(
    fixed_fields_packed: &[u8],
    query: u32,
) -> Result<QM31, V6WireError> {
    if query >= 1 << 18 {
        return Err(V6WireError::InvalidQuerySchedule);
    }
    let point = line_domain_x_for_circle(20, 1, query as usize)
        .map_err(|_| V6WireError::InvalidQuerySchedule)?;
    evaluate_packed_final256(fixed_fields_packed, point)
}

pub fn decode_packed_final256(fixed_fields_packed: &[u8]) -> Result<Vec<QM31>, V6WireError> {
    if fixed_fields_packed.len() != V6_FIXED_PACKED_FIELD_BYTES {
        return Err(V6WireError::WrongLength);
    }
    let mut coefficients = Vec::with_capacity(V6_FINAL_QM31_VALUES);
    for index in 0..V6_FINAL_QM31_VALUES {
        let coefficient = packed_qm31_at(fixed_fields_packed, V6_FINAL_QM31_OFFSET + index)
            .ok_or(V6WireError::WrongLength)?;
        if coefficient.c0.a.0 >= P
            || coefficient.c0.b.0 >= P
            || coefficient.c1.a.0 >= P
            || coefficient.c1.b.0 >= P
        {
            return Err(V6WireError::NonCanonicalM31);
        }
        coefficients.push(coefficient);
    }
    Ok(coefficients)
}

pub fn evaluate_final256_coefficients(
    coefficients: &[QM31],
    point: M31,
) -> Result<QM31, V6WireError> {
    if coefficients.len() != V6_FINAL_QM31_VALUES {
        return Err(V6WireError::WrongLength);
    }
    let weights = natural_line_weights_256(point);
    // Four canonical products fit strictly below 2^64. Reduce each four-term
    // block, then accumulate the 64 canonical block results in u64. This is
    // the same dot product as the whole-vector u128 form, but avoids emulated
    // 128-bit carry-chain additions in the SBF hot loop.
    let mut sums = [0u64; 4];
    for block in 0..V6_FINAL_QM31_VALUES / 4 {
        let mut raw = [0u64; 4];
        for index in block * 4..block * 4 + 4 {
            let coefficient = coefficients[index];
            let weight = u64::from(weights[index].0);
            raw[0] += u64::from(coefficient.c0.a.0) * weight;
            raw[1] += u64::from(coefficient.c0.b.0) * weight;
            raw[2] += u64::from(coefficient.c1.a.0) * weight;
            raw[3] += u64::from(coefficient.c1.b.0) * weight;
        }
        for limb in 0..4 {
            sums[limb] += u64::from(M31::reduce_u64(raw[limb]).0);
        }
    }
    Ok(QM31 {
        c0: CM31::new(M31::reduce_u64(sums[0]), M31::reduce_u64(sums[1])),
        c1: CM31::new(M31::reduce_u64(sums[2]), M31::reduce_u64(sums[3])),
    })
}

/// Canonically decode the disclosed terminal vector once, then evaluate it at
/// all sixteen verifier queries. The shared heap allocation avoids sixteen
/// repeated packed-bit scans without putting the 4-KiB coefficient vector on
/// the SBF stack.
pub fn evaluate_packed_final256_at_queries(
    fixed_fields_packed: &[u8],
    queries: [u32; V6_QUERY_COUNT],
) -> Result<[QM31; V6_QUERY_COUNT], V6WireError> {
    let coefficients = decode_packed_final256(fixed_fields_packed)?;
    let mut outputs = [QM31::ZERO; V6_QUERY_COUNT];
    for (output, query) in outputs.iter_mut().zip(queries) {
        if query >= 1 << 18 {
            return Err(V6WireError::InvalidQuerySchedule);
        }
        let point = line_domain_x_for_circle(20, 1, query as usize)
            .map_err(|_| V6WireError::InvalidQuerySchedule)?;
        *output = evaluate_final256_coefficients(&coefficients, point)?;
    }
    Ok(outputs)
}

/// Evaluate one already-canonical decoded final vector at all selected
/// positions. The complete V6 verifier uses this after the relation checker
/// has consumed the same vector, avoiding a second packed-field scan.
pub fn evaluate_final256_coefficients_at_queries(
    coefficients: &[QM31],
    queries: [u32; V6_QUERY_COUNT],
) -> Result<[QM31; V6_QUERY_COUNT], V6WireError> {
    if coefficients.len() != V6_FINAL_QM31_VALUES {
        return Err(V6WireError::WrongLength);
    }
    let mut outputs = [QM31::ZERO; V6_QUERY_COUNT];
    for (output, query) in outputs.iter_mut().zip(queries) {
        if query >= 1 << 18 {
            return Err(V6WireError::InvalidQuerySchedule);
        }
        let point = line_domain_x_for_circle(20, 1, query as usize)
            .map_err(|_| V6WireError::InvalidQuerySchedule)?;
        *output = evaluate_final256_coefficients(coefficients, point)?;
    }
    Ok(outputs)
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct V6OneFoldCoordinates {
    pub inv_2x: [M31; V6_QUERY_COUNT],
    pub inv_2y: [M31; V6_QUERY_COUNT],
    /// Exact layer-one line coordinate `pi(circle_x)` for each query.  The
    /// relation tail reuses these values instead of repeating sixteen group
    /// exponentiations for the same transcript-derived positions.
    pub line_x: [M31; V6_QUERY_COUNT],
}

/// Derive the two public inverse coordinates used by the sole circle fold at
/// each selected fibre. One batch inversion serves all sixteen queries.
pub fn prepare_v6_onefold_coordinates(
    queries: [u32; V6_QUERY_COUNT],
) -> Result<V6OneFoldCoordinates, V6WireError> {
    let points = selected_circle_fiber_points_shared(20, &queries)
        .map_err(|_| V6WireError::InvalidQuerySchedule)?;
    let mut denominators = [M31::ZERO; 2 * V6_QUERY_COUNT];
    for (ordinal, point) in points.iter().enumerate() {
        let x = point.x.double();
        let y = point.y.double();
        if x.is_zero() || y.is_zero() {
            return Err(V6WireError::InvalidQuerySchedule);
        }
        denominators[2 * ordinal] = x;
        denominators[2 * ordinal + 1] = y;
    }
    let mut inverses = [M31::ZERO; 2 * V6_QUERY_COUNT];
    m31_batch_inverse(&denominators, &mut inverses);
    if denominators[0].mul(inverses[0]) != M31::ONE {
        return Err(V6WireError::InvalidQuerySchedule);
    }
    Ok(V6OneFoldCoordinates {
        inv_2x: core::array::from_fn(|ordinal| inverses[2 * ordinal]),
        inv_2y: core::array::from_fn(|ordinal| inverses[2 * ordinal + 1]),
        line_x: core::array::from_fn(|ordinal| {
            points[ordinal]
                .x
                .mul(points[ordinal].x)
                .double()
                .sub(M31::ONE)
        }),
    })
}

/// Decode and gamma-combine all authenticated query records. The caller must
/// first authenticate and canonically validate these exact records with
/// [`verify_v6_binary_openings`].
pub fn gamma_combine_v6_queries(
    wire: &V6OneFoldWire<'_>,
    gamma: QM31,
) -> Result<[[QM31; 4]; V6_QUERY_COUNT], V6WireError> {
    let powers = StateOnlySpendQueryPowers::new(gamma);
    let mut combined = [[QM31::ZERO; 4]; V6_QUERY_COUNT];
    for (ordinal, output) in combined.iter_mut().enumerate() {
        let record = wire
            .query(ordinal)
            .ok_or(V6WireError::InvalidQuerySchedule)?;
        *output = gamma_combine_v6_packed_layer0(record.c1_packed, record.c2_packed, &powers)?;
    }
    Ok(combined)
}

/// Apply the sole circle-to-line fold to already gamma-combined values.
pub fn fold_v6_onefold_queries(
    combined: &[[QM31; 4]; V6_QUERY_COUNT],
    coordinates: &V6OneFoldCoordinates,
    alpha: QM31,
) -> [QM31; V6_QUERY_COUNT] {
    let alpha_squared = alpha.square();
    let alpha_powers = [
        PreparedQm31Multiplier::new(alpha),
        PreparedQm31Multiplier::new(alpha_squared),
        PreparedQm31Multiplier::new(alpha_squared.mul(alpha)),
    ];
    core::array::from_fn(|ordinal| {
        normalized_circle_to_line_arity4_prepared_polynomial_refs(
            &combined[ordinal],
            &alpha_powers,
            coordinates.inv_2x[ordinal],
            coordinates.inv_2y[ordinal],
        )
    })
}

/// Check the sole V6 circle-to-line fold at every authenticated query.
///
/// The caller must first run [`verify_v6_binary_openings`] over the same wire
/// and query schedule. This function then decodes the packed fibre values,
/// combines all 29 columns with scalar powers of `gamma`, derives and
/// batch-inverts the public circle coordinates, and compares the folded value
/// with the disclosed degree-<256 object at the corresponding line point.
pub fn check_v6_onefold_queries(
    wire: &V6OneFoldWire<'_>,
    queries: [u32; V6_QUERY_COUNT],
    gamma: QM31,
    alpha: QM31,
) -> Result<[QM31; V6_QUERY_COUNT], V6WireError> {
    let expected = evaluate_packed_final256_at_queries(wire.fixed_fields_packed, queries)?;
    let coordinates = prepare_v6_onefold_coordinates(queries)?;
    let combined = gamma_combine_v6_queries(wire, gamma)?;
    let folded = fold_v6_onefold_queries(&combined, &coordinates, alpha);
    for ordinal in 0..V6_QUERY_COUNT {
        if folded[ordinal] != expected[ordinal] {
            return Err(V6WireError::FriMismatch);
        }
    }
    Ok(folded)
}

