    #[test]
    fn fold_coefficients_sum_to_one_and_have_a_reconstructible_slot() {
        let mut state = 0x7630_0f17_c0de_0001;
        for _ in 0..64 {
            let alpha = next_qm31(&mut state);
            let x = next_m31(&mut state);
            let y = next_m31(&mut state);
            if x.is_zero() || y.is_zero() {
                continue;
            }
            let coefficients = fold_coefficients(alpha, x.inv(), y.inv());
            assert_eq!(
                coefficients,
                fold_coefficients_basis_reference(alpha, x.inv(), y.inv())
            );
            assert_eq!(
                coefficients.into_iter().fold(QM31::ZERO, QM31::add),
                QM31::ONE
            );
            assert!(first_reconstructible_slot(&coefficients).is_some());
        }
    }

    #[test]
    fn qm31_batch_inverse_matches_all_sixteen_individual_inverses() {
        let mut state = 0x7630_ba7c_1a10_0001;
        for _ in 0..16 {
            let values: [QM31; V6_QUERY_COUNT] = core::array::from_fn(|_| {
                let candidate = next_qm31(&mut state);
                if candidate.is_zero() {
                    QM31::ONE
                } else {
                    candidate
                }
            });
            let inverses = qm31_batch_inverse_16(&values).unwrap();
            for ordinal in 0..V6_QUERY_COUNT {
                assert_eq!(inverses[ordinal], values[ordinal].inv());
                assert_eq!(values[ordinal].mul(inverses[ordinal]), QM31::ONE);
            }
        }
        let mut with_zero = [QM31::ONE; V6_QUERY_COUNT];
        with_zero[7] = QM31::ZERO;
        assert!(qm31_batch_inverse_16(&with_zero).is_none());
    }

    #[test]
    fn omitted_d_reconstruction_restores_the_exact_fold() {
        let mut state = 0x7630_d00d_f01d_0001;
        for _ in 0..64 {
            let mut gamma = next_qm31(&mut state);
            if gamma.is_zero() {
                gamma = QM31::ONE;
            }
            let alpha = next_qm31(&mut state);
            let x = next_m31(&mut state);
            let y = next_m31(&mut state);
            if x.is_zero() || y.is_zero() {
                continue;
            }
            let inv_2x = x.inv();
            let inv_2y = y.inv();
            let coefficients = fold_coefficients(alpha, inv_2x, inv_2y);
            let omitted_slot = first_reconstructible_slot(&coefficients).unwrap();
            let d_power = qm31_power_table::<SPEND_TOTAL_COLUMNS>(gamma)[SPEND_D_GENERATOR_INDEX];
            let d = next_qm31(&mut state);
            let mut partial = core::array::from_fn(|_| next_qm31(&mut state));
            let mut complete = partial;
            complete[omitted_slot] = complete[omitted_slot].add(d_power.mul(d));
            let expected =
                normalized_circle_to_line_arity4_prepared(complete, alpha, inv_2x, inv_2y);
            let (reconstructed_slot, reconstructed_d) =
                reconstruct_omitted_d(partial, expected, gamma, alpha, inv_2x, inv_2y).unwrap();
            assert_eq!(reconstructed_slot, omitted_slot);
            assert_eq!(reconstructed_d, d);
            partial[reconstructed_slot] =
                partial[reconstructed_slot].add(d_power.mul(reconstructed_d));
            assert_eq!(
                normalized_circle_to_line_arity4_prepared(partial, alpha, inv_2x, inv_2y,),
                expected
            );
        }
    }

    #[test]
    fn compact_c2_roundtrip_reconstructs_the_committed_leaf() {
        let mut state = 0x7630_c2c2_f01d_0001;
        let c1 = [0u8; V6_C1_PACKED_BYTES_PER_QUERY];
        for _ in 0..64 {
            let mut gamma = next_qm31(&mut state);
            if gamma.is_zero() {
                gamma = QM31::ONE;
            }
            let alpha = next_qm31(&mut state);
            let x = next_m31(&mut state);
            let y = next_m31(&mut state);
            if x.is_zero() || y.is_zero() {
                continue;
            }
            let inv_2x = x.inv();
            let inv_2y = y.inv();
            let helpers = core::array::from_fn(|_| core::array::from_fn(|_| next_qm31(&mut state)));
            let full = encode_full_c2_leaf(&helpers).unwrap();
            let powers = StateOnlySpendQueryPowers::new(gamma);
            let combined = gamma_combine_v6_packed_layer0(&c1, &full, &powers).unwrap();
            let expected =
                normalized_circle_to_line_arity4_prepared(combined, alpha, inv_2x, inv_2y);
            let coefficients = fold_coefficients(alpha, inv_2x, inv_2y);
            let omitted_slot = first_reconstructible_slot(&coefficients).unwrap();
            let compact = encode_compact_c2_query(&helpers, omitted_slot).unwrap();
            let (reconstructed, reconstructed_combined, selected_slot) =
                reconstruct_compact_c2_query(&c1, &compact, expected, gamma, alpha, inv_2x, inv_2y)
                    .unwrap();
            assert_eq!(selected_slot, omitted_slot);
            assert_eq!(reconstructed, full);
            assert_eq!(reconstructed_combined, combined);
        }
    }

    #[test]
    fn composed_compact_opening_reconstructs_before_merkle_authentication() {
        let queries: [u32; V6_QUERY_COUNT] = core::array::from_fn(|ordinal| ordinal as u32);
        let frontier_nodes = binary_frontier_nodes(queries, 18).unwrap();
        let coordinates = prepare_v6_onefold_coordinates(queries).unwrap();
        let gamma = QM31 {
            c0: CM31::new(M31(17), M31(19)),
            c1: CM31::new(M31(23), M31(29)),
        };
        let alpha = QM31 {
            c0: CM31::new(M31(31), M31(37)),
            c1: CM31::new(M31(41), M31(43)),
        };
        let gamma_powers = qm31_power_table::<SPEND_TOTAL_COLUMNS>(gamma);
        let d_power = gamma_powers[SPEND_D_GENERATOR_INDEX];
        let powers = StateOnlySpendQueryPowers::from_full_table(&gamma_powers);
        let mut state = 0x7630_2160_c2c2_0001;
        let mut expected_folds = [QM31::ZERO; V6_QUERY_COUNT];
        let mut expected_combined = [[QM31::ZERO; 4]; V6_QUERY_COUNT];
        let mut c1_entries = Vec::new();
        let mut c2_entries = Vec::new();
        let mut body = vec![
            0u8;
            V7_COMPACT_BODY_WITHOUT_FRONTIERS
                + 2 * frontier_nodes * V7_COMPACT_DIGEST_BYTES
        ];
        let query_section_offset =
            V6_FIXED_PACKED_FIELD_BYTES + V7_COMPACT_ROOT_BYTES + V6_WORK_NONCE_BYTES;

        for ordinal in 0..V6_QUERY_COUNT {
            let helpers = core::array::from_fn(|_| core::array::from_fn(|_| next_qm31(&mut state)));
            let full_c2 = encode_full_c2_leaf(&helpers).unwrap();
            let c1 = [0u8; V6_C1_PACKED_BYTES_PER_QUERY];
            let combined = gamma_combine_v6_packed_layer0(&c1, &full_c2, &powers).unwrap();
            expected_combined[ordinal] = combined;
            expected_folds[ordinal] = normalized_circle_to_line_arity4_prepared(
                combined,
                alpha,
                coordinates.inv_2x[ordinal],
                coordinates.inv_2y[ordinal],
            );
            let coefficients = fold_coefficients(
                alpha,
                coordinates.inv_2x[ordinal],
                coordinates.inv_2y[ordinal],
            );
            let omitted_slot = first_reconstructible_slot(&coefficients).unwrap();
            let compact_c2 = encode_compact_c2_query(&helpers, omitted_slot).unwrap();
            let salt: [u8; 32] =
                core::array::from_fn(|byte| (ordinal as u8).wrapping_mul(17) ^ byte as u8);
            let record_offset = query_section_offset + ordinal * V7_COMPACT_QUERY_BYTES;
            body[record_offset..record_offset + V7_COMPACT_C1_BYTES_PER_QUERY].copy_from_slice(&c1);
            let c2_offset = record_offset + V7_COMPACT_C1_BYTES_PER_QUERY;
            body[c2_offset..c2_offset + V7_COMPACT_C2_BYTES_PER_QUERY].copy_from_slice(&compact_c2);
            body[c2_offset + V7_COMPACT_C2_BYTES_PER_QUERY
                ..c2_offset + V7_COMPACT_C2_BYTES_PER_QUERY + 32]
                .copy_from_slice(&salt);
            c1_entries.push((
                queries[ordinal],
                private_leaf_hash216(test_hash, V7_C1_TREE_TAG, &c1, &salt),
            ));
            c2_entries.push((
                queries[ordinal],
                private_leaf_hash216(test_hash, V7_C2_TREE_TAG, &full_c2, &salt),
            ));
        }

        let zero_frontier = vec![[0u8; V7_COMPACT_DIGEST_BYTES]; frontier_nodes];
        let c1_root = minimal_root216(&c1_entries, 18, &zero_frontier);
        let c2_root = minimal_root216(&c2_entries, 18, &zero_frontier);
        body[V6_FIXED_PACKED_FIELD_BYTES..V6_FIXED_PACKED_FIELD_BYTES + V7_COMPACT_DIGEST_BYTES]
            .copy_from_slice(&c1_root);
        body[V6_FIXED_PACKED_FIELD_BYTES + V7_COMPACT_DIGEST_BYTES
            ..V6_FIXED_PACKED_FIELD_BYTES + V7_COMPACT_ROOT_BYTES]
            .copy_from_slice(&c2_root);

        let wire = V7CompactOneFoldWire::parse(&body, frontier_nodes).unwrap();
        let actual = verify_reconstruct_and_gamma_combine_v7_openings(
            test_hash,
            &wire,
            queries,
            expected_folds,
            &powers,
            d_power,
            alpha,
            &coordinates,
        )
        .unwrap();
        assert_eq!(actual, expected_combined);

        let first_c2_offset = query_section_offset + V7_COMPACT_C1_BYTES_PER_QUERY;
        body[first_c2_offset] ^= 1;
        let changed = V7CompactOneFoldWire::parse(&body, frontier_nodes).unwrap();
        assert_eq!(
            verify_reconstruct_and_gamma_combine_v7_openings(
                test_hash,
                &changed,
                queries,
                expected_folds,
                &powers,
                d_power,
                alpha,
                &coordinates,
            ),
            Err(V6WireError::MerkleMismatch)
        );
    }

    #[test]
    fn zero_gamma_is_rejected_before_reconstruction() {
        assert_eq!(
            reconstruct_omitted_d(
                [QM31::ZERO; 4],
                QM31::ZERO,
                QM31::ZERO,
                QM31::ZERO,
                M31::ONE,
                M31::ONE,
            ),
            None
        );
    }
}

crates/aspis-core/src/v7_fixed_canonical:
//! Default-off canonical fixed-field byte-for-CU experiment for Tag-73.
//!
//! The selected proof packs 641 QM31 values into 9,936 bytes. This audit wire
//! carries the same values as 641 canonical 16-byte records (10,256 bytes), a
//! precise +320-byte proof-account trade. Roots, nonces, query records, salts,
//! and both Merkle frontiers are byte-for-byte unchanged.

use alloc::vec::Vec;

use crate::field::QM31;
use crate::state_only_spend_query::StateOnlySpendQueryPowers;
use crate::v6_onefold::{
    gamma_combine_v6_packed_layer0, validate_packed_m31, V6FixedFieldStream, V6WireError,
    V6_C1_LIMBS_PER_QUERY, V6_C1_PACKED_BYTES_PER_QUERY, V6_C2_LIMBS_PER_QUERY,
    V6_C2_PACKED_BYTES_PER_QUERY, V6_FIXED_M31_LIMBS, V6_FIXED_PACKED_FIELD_BYTES,
    V6_FIXED_QM31_VALUES, V6_QUERY_COUNT, V6_WORK_NONCE_BYTES,
};
use crate::v7_merkle208::{
    private_leaf_hash_v7, verify_two_minimal_subtrees_v7_bytes, V7Digest, V7_C1_TREE_TAG,
    V7_C2_TREE_TAG,
};
use crate::v7_onefold::{
    V7CompactOneFoldWire, V7_COMPACT_DIGEST_BYTES, V7_COMPACT_FRONTIER_CAP_PER_TREE,
    V7_COMPACT_PRIVATE_SALT_BYTES, V7_COMPACT_QUERY_BYTES, V7_COMPACT_QUERY_SECTION_BYTES,
};
use crate::HashFn;

pub const V7_CANONICAL_FIXED_BYTES: usize = 16 * V6_FIXED_QM31_VALUES;
pub const V7_CANONICAL_FIXED_DELTA_BYTES: usize =
    V7_CANONICAL_FIXED_BYTES - V6_FIXED_PACKED_FIELD_BYTES;
pub const V7_CANONICAL_BODY_WITHOUT_FRONTIERS: usize = V7_CANONICAL_FIXED_BYTES
    + 2 * V7_COMPACT_DIGEST_BYTES
    + V6_WORK_NONCE_BYTES
    + V7_COMPACT_QUERY_SECTION_BYTES;
pub const V7_CANONICAL_QUERY_M31_LIMBS: usize =
    V6_QUERY_COUNT * (V6_C1_LIMBS_PER_QUERY + V6_C2_LIMBS_PER_QUERY);
pub const V7_CANONICAL_TOTAL_M31_LIMBS: usize = V6_FIXED_M31_LIMBS + V7_CANONICAL_QUERY_M31_LIMBS;

#[derive(Clone, Copy)]
pub(crate) struct V7CanonicalFixedFieldReader<'a> {
    bytes: &'a [u8],
    ordinal: usize,
}

impl<'a> V7CanonicalFixedFieldReader<'a> {
    fn new(bytes: &'a [u8]) -> Result<Self, V6WireError> {
        if bytes.len() != V7_CANONICAL_FIXED_BYTES {
            return Err(V6WireError::WrongLength);
        }
        Ok(Self { bytes, ordinal: 0 })
    }
}

impl V6FixedFieldStream for V7CanonicalFixedFieldReader<'_> {
    #[inline(always)]
    fn next_qm31(&mut self) -> Result<QM31, V6WireError> {
        if self.ordinal >= V6_FIXED_QM31_VALUES {
            return Err(V6WireError::WrongLength);
        }
        let start = 16 * self.ordinal;
        let value = QM31::from_le_bytes(&self.bytes[start..start + 16])
            .ok_or(V6WireError::NonCanonicalM31)?;
        self.ordinal += 1;
        Ok(value)
    }

    fn finish(self) -> Result<(), V6WireError> {
        if self.ordinal == V6_FIXED_QM31_VALUES {
            Ok(())
        } else {
            Err(V6WireError::WrongLength)
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct V7CanonicalQueryRecord<'a> {
    pub c1_packed: &'a [u8],
    pub c2_packed: &'a [u8],
    pub salt: &'a [u8; V7_COMPACT_PRIVATE_SALT_BYTES],
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct V7CanonicalOneFoldWire<'a> {
    pub fixed_fields: &'a [u8],
    pub c1_root: &'a V7Digest,
    pub c2_root: &'a V7Digest,
    pub work_nonces: &'a [u8; V6_WORK_NONCE_BYTES],
    query_section: &'a [u8],
    pub c1_frontier: &'a [u8],
    pub c2_frontier: &'a [u8],
}

impl<'a> V7CanonicalOneFoldWire<'a> {
    pub fn parse(bytes: &'a [u8], frontier_nodes: usize) -> Result<Self, V6WireError> {
        let wire = Self::parse_deferred_query_canonicality(bytes, frontier_nodes)?;
        for ordinal in 0..V6_QUERY_COUNT {
            let record = wire
                .query(ordinal)
                .ok_or(V6WireError::InvalidQuerySchedule)?;
            validate_packed_m31(record.c1_packed, V6_C1_LIMBS_PER_QUERY)?;
            validate_packed_m31(record.c2_packed, V6_C2_LIMBS_PER_QUERY)?;
        }
        Ok(wire)
    }

    /// Parse exact section boundaries for the +320-byte fixed-field audit
    /// grammar while deferring packed-query canonicality to the sole consumer
    /// that decodes and gamma-combines every query record.
    ///
    /// This is not a permissive parser: the fixed reader checks all 2,564
    /// fixed limbs before `finish`, and `gamma_combine_v6_packed_layer0`
    /// checks all 2,432 query limbs before an opening can authenticate.  The
    /// full [`Self::parse`] remains available to standalone callers that do
    /// not promise complete proof consumption.
    pub fn parse_deferred_query_canonicality(
        bytes: &'a [u8],
        frontier_nodes: usize,
    ) -> Result<Self, V6WireError> {
        if frontier_nodes > V7_COMPACT_FRONTIER_CAP_PER_TREE {
            return Err(V6WireError::FrontierTooLarge);
        }
        let frontier_bytes = frontier_nodes
            .checked_mul(V7_COMPACT_DIGEST_BYTES)
            .ok_or(V6WireError::WrongLength)?;
        let expected = V7_CANONICAL_BODY_WITHOUT_FRONTIERS
            .checked_add(2 * frontier_bytes)
            .ok_or(V6WireError::WrongLength)?;
        if bytes.len() != expected {
            return Err(V6WireError::WrongLength);
        }
        let (fixed_fields, rest) = bytes.split_at(V7_CANONICAL_FIXED_BYTES);
        let (c1_root, rest) = rest.split_at(V7_COMPACT_DIGEST_BYTES);
        let (c2_root, rest) = rest.split_at(V7_COMPACT_DIGEST_BYTES);
        let (work_nonces, rest) = rest.split_at(V6_WORK_NONCE_BYTES);
        let (query_section, rest) = rest.split_at(V7_COMPACT_QUERY_SECTION_BYTES);
        let (c1_frontier, c2_frontier) = rest.split_at(frontier_bytes);
        // Canonicality is checked lazily by the one-pass transcript reader;
        // every one of the 641 records is consumed before acceptance.
        V7CanonicalFixedFieldReader::new(fixed_fields)?;
        Ok(Self {
            fixed_fields,
            c1_root: c1_root.try_into().map_err(|_| V6WireError::WrongLength)?,
            c2_root: c2_root.try_into().map_err(|_| V6WireError::WrongLength)?,
            work_nonces: work_nonces
                .try_into()
                .map_err(|_| V6WireError::WrongLength)?,
            query_section,
            c1_frontier,
            c2_frontier,
        })
    }

    pub(crate) fn fixed_reader(&self) -> Result<V7CanonicalFixedFieldReader<'a>, V6WireError> {
        V7CanonicalFixedFieldReader::new(self.fixed_fields)
    }

    pub fn query(&self, ordinal: usize) -> Option<V7CanonicalQueryRecord<'a>> {
        if ordinal >= V6_QUERY_COUNT {
            return None;
        }
        let start = ordinal * V7_COMPACT_QUERY_BYTES;
        let c1_end = start + V6_C1_PACKED_BYTES_PER_QUERY;
        let c2_end = c1_end + V6_C2_PACKED_BYTES_PER_QUERY;
        let end = c2_end + V7_COMPACT_PRIVATE_SALT_BYTES;
        Some(V7CanonicalQueryRecord {
            c1_packed: &self.query_section[start..c1_end],
            c2_packed: &self.query_section[c1_end..c2_end],
            salt: self.query_section[c2_end..end].try_into().ok()?,
        })
    }
}

pub fn verify_and_gamma_combine_v7_canonical_openings(
    hash: HashFn,
    wire: &V7CanonicalOneFoldWire<'_>,
    queries: [u32; V6_QUERY_COUNT],
    powers: &StateOnlySpendQueryPowers,
) -> Result<[[QM31; 4]; V6_QUERY_COUNT], V6WireError> {
    let mut order: [(u32, usize); V6_QUERY_COUNT] =
        core::array::from_fn(|ordinal| (queries[ordinal], ordinal));
    order.sort_unstable_by_key(|entry| entry.0);
    if order[V6_QUERY_COUNT - 1].0 >= 1 << 18 || order.windows(2).any(|pair| pair[0].0 == pair[1].0)
    {
        return Err(V6WireError::InvalidQuerySchedule);
    }
    let mut combined = [[QM31::ZERO; 4]; V6_QUERY_COUNT];
    let mut entries = Vec::with_capacity(V6_QUERY_COUNT);
    for (query, ordinal) in order {
        let record = wire
            .query(ordinal)
            .ok_or(V6WireError::InvalidQuerySchedule)?;
        combined[ordinal] =
            gamma_combine_v6_packed_layer0(record.c1_packed, record.c2_packed, powers)?;
        entries.push((
            query,
            private_leaf_hash_v7(hash, V7_C1_TREE_TAG, record.c1_packed, record.salt),
            private_leaf_hash_v7(hash, V7_C2_TREE_TAG, record.c2_packed, record.salt),
        ));
    }
    let mut level = Vec::with_capacity(V6_QUERY_COUNT);
    let mut next = Vec::with_capacity(V6_QUERY_COUNT);
    if !verify_two_minimal_subtrees_v7_bytes(
        hash,
        (wire.c1_root, wire.c2_root),
        18,
        &entries,
        (wire.c1_frontier, wire.c2_frontier),
        &mut level,
        &mut next,
    ) {
        return Err(V6WireError::MerkleMismatch);
    }
    Ok(combined)
}

/// Convert only the selected proof's fixed section; the authenticated tail is
/// copied byte-for-byte. Used by host harnesses to build a fair paired input.
pub fn transcode_tag73_to_canonical_fixed(
    proof: &[u8],
    frontier_nodes: usize,
) -> Result<Vec<u8>, V6WireError> {
    let wire = V7CompactOneFoldWire::parse(proof, frontier_nodes)?;
    let mut reader = crate::v6_onefold::V6FixedFieldReader::new(wire.fixed_fields_packed)?;
    let mut output = Vec::with_capacity(proof.len() + V7_CANONICAL_FIXED_DELTA_BYTES);
    for _ in 0..V6_FIXED_QM31_VALUES {
        let value = reader.next_qm31()?;
        let start = output.len();
        output.resize(start + 16, 0);
        value.write_le_bytes(&mut output[start..start + 16]);
    }
    reader.finish()?;
    output.extend_from_slice(&proof[V6_FIXED_PACKED_FIELD_BYTES..]);
    V7CanonicalOneFoldWire::parse(&output, frontier_nodes)?;
    Ok(output)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::field::P;
    use alloc::vec;

    fn overwrite_packed_m31(bytes: &mut [u8], limb: usize, value: u32) {
        let bit_start = 31 * limb;
        for bit in 0..31 {
            let output = bit_start + bit;
            let mask = 1u8 << (output % 8);
            if (value >> bit) & 1 == 0 {
                bytes[output / 8] &= !mask;
            } else {
                bytes[output / 8] |= mask;
            }
        }
    }

    #[test]
    fn canonical_fixed_delta_is_exactly_320_bytes() {
        assert_eq!(V6_FIXED_PACKED_FIELD_BYTES, 9_936);
        assert_eq!(V7_CANONICAL_FIXED_BYTES, 10_256);
        assert_eq!(V7_CANONICAL_FIXED_DELTA_BYTES, 320);
        assert_eq!(V6_FIXED_M31_LIMBS, 2_564);
        assert_eq!(V7_CANONICAL_QUERY_M31_LIMBS, 2_432);
        assert_eq!(V7_CANONICAL_TOTAL_M31_LIMBS, 4_996);
    }

    #[test]
    fn exact_once_fixed_reader_rejects_each_of_2564_noncanonical_limbs() {
        let mut fixed = vec![0u8; V7_CANONICAL_FIXED_BYTES];
        for ordinal in 0..V6_FIXED_QM31_VALUES {
            for limb in 0..4 {
                fixed[16 * ordinal + 4 * limb..16 * ordinal + 4 * limb + 4]
                    .copy_from_slice(&P.to_le_bytes());
                let mut reader = V7CanonicalFixedFieldReader::new(&fixed).unwrap();
                for _ in 0..ordinal {
                    reader.next_qm31().unwrap();
                }
                assert_eq!(reader.next_qm31(), Err(V6WireError::NonCanonicalM31));
                fixed[16 * ordinal + 4 * limb..16 * ordinal + 4 * limb + 4].fill(0);
            }
        }
    }

    #[test]
    fn deferred_query_parser_leaves_all_2432_limbs_to_checked_gamma_consumer() {
        let mut proof = vec![0u8; V7_CANONICAL_BODY_WITHOUT_FRONTIERS];
        let query_start =
            V7_CANONICAL_FIXED_BYTES + 2 * V7_COMPACT_DIGEST_BYTES + V6_WORK_NONCE_BYTES;
        let powers = StateOnlySpendQueryPowers::new(QM31::ONE);
        for ordinal in 0..V6_QUERY_COUNT {
            let record_start = query_start + ordinal * V7_COMPACT_QUERY_BYTES;
            for limb in 0..V6_C1_LIMBS_PER_QUERY + V6_C2_LIMBS_PER_QUERY {
                let (section_start, section_limb) = if limb < V6_C1_LIMBS_PER_QUERY {
                    (record_start, limb)
                } else {
                    (
                        record_start + V6_C1_PACKED_BYTES_PER_QUERY,
                        limb - V6_C1_LIMBS_PER_QUERY,
                    )
                };
                let section_len = if limb < V6_C1_LIMBS_PER_QUERY {
                    V6_C1_PACKED_BYTES_PER_QUERY
                } else {
                    V6_C2_PACKED_BYTES_PER_QUERY
                };
                overwrite_packed_m31(
                    &mut proof[section_start..section_start + section_len],
                    section_limb,
                    P,
                );
                let wire =
                    V7CanonicalOneFoldWire::parse_deferred_query_canonicality(&proof, 0).unwrap();
                let record = wire.query(ordinal).unwrap();
                assert_eq!(
                    gamma_combine_v6_packed_layer0(record.c1_packed, record.c2_packed, &powers,),
                    Err(V6WireError::NonCanonicalM31),
                    "ordinal {ordinal} limb {limb}",
                );
                overwrite_packed_m31(
                    &mut proof[section_start..section_start + section_len],
                    section_limb,
                    0,
                );
            }
        }
    }

    #[test]
    fn standalone_parser_keeps_eager_query_teeth() {
        let mut proof = vec![0u8; V7_CANONICAL_BODY_WITHOUT_FRONTIERS];
        let query_start =
            V7_CANONICAL_FIXED_BYTES + 2 * V7_COMPACT_DIGEST_BYTES + V6_WORK_NONCE_BYTES;
        overwrite_packed_m31(
            &mut proof[query_start..query_start + V6_C1_PACKED_BYTES_PER_QUERY],
            0,
            P,
        );
        assert!(V7CanonicalOneFoldWire::parse_deferred_query_canonicality(&proof, 0).is_ok());
        assert_eq!(
            V7CanonicalOneFoldWire::parse(&proof, 0),
            Err(V6WireError::NonCanonicalM31)
        );
    }
}

crates/aspis-core/src/v7_lane_zeta.rs:
//! V7 Phase-1 reference algebra for the split-tensor lane restriction.
//!
//! The committed lane tables contain Boolean subset-zeta values over M31.
//! Their multilinear extensions are evaluated in the deployed QM31 tower.
//! This module has no transcript, Merkle, PCS, or production-verifier surface;
//! it is the small executable oracle that must be proved before integration.

use crate::field::{CM31, M31, QM31};
use crate::v7_profile::{
    COMBINED_LANES, QM31_LIMBS, STAGE_A_LANE_VARIABLES, STAGE_A_PADDED_LANES, STAGE_A_SOURCE_LANES,
    STAGE_B_LANE_VARIABLES, STAGE_B_OUTER_GAMMA_POWER, STAGE_B_PADDED_LANES, STAGE_B_QM31_LANES,
};

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ZetaError {
    EmptyTable,
    LengthNotPowerOfTwo,
    DimensionMismatch,
}

pub const QM31_I: QM31 = QM31 {
    c0: CM31 {
        a: M31::ZERO,
        b: M31::ONE,
    },
    c1: CM31::ZERO,
};

pub const QM31_U: QM31 = QM31 {
    c0: CM31::ZERO,
    c1: CM31::ONE,
};

#[inline(always)]
pub const fn qm31_from_limbs(limbs: [M31; QM31_LIMBS]) -> QM31 {
    QM31 {
        c0: CM31 {
            a: limbs[0],
            b: limbs[1],
        },
        c1: CM31 {
            a: limbs[2],
            b: limbs[3],
        },
    }
}

#[inline(always)]
pub const fn qm31_limbs(value: QM31) -> [M31; QM31_LIMBS] {
    [value.c0.a, value.c0.b, value.c1.a, value.c1.b]
}

#[inline(always)]
fn lift_m31(value: M31) -> QM31 {
    QM31::from_cm31(CM31::from_m31(value))
}

fn validate_power_of_two_length(length: usize) -> Result<(), ZetaError> {
    if length == 0 {
        Err(ZetaError::EmptyTable)
    } else if !length.is_power_of_two() {
        Err(ZetaError::LengthNotPowerOfTwo)
    } else {
        Ok(())
    }
}

/// In-place Boolean subset-zeta transform:
/// `table[B] = sum_{S subseteq B} coefficients[S]`.
pub fn zeta_in_place_m31(table: &mut [M31]) -> Result<(), ZetaError> {
    validate_power_of_two_length(table.len())?;
    let mut bit = 1usize;
    while bit < table.len() {
        let mut mask = 0usize;
        while mask < table.len() {
            if mask & bit != 0 {
                table[mask] = table[mask].add(table[mask ^ bit]);
            }
            mask += 1;
        }
        bit <<= 1;
    }
    Ok(())
}

/// Exact inverse of [`zeta_in_place_m31`].
pub fn mobius_in_place_m31(table: &mut [M31]) -> Result<(), ZetaError> {
    validate_power_of_two_length(table.len())?;
    let mut bit = 1usize;
    while bit < table.len() {
        let mut mask = 0usize;
        while mask < table.len() {
            if mask & bit != 0 {
                table[mask] = table[mask].sub(table[mask ^ bit]);
            }
            mask += 1;
        }
        bit <<= 1;
    }
    Ok(())
}

fn expected_table_length(dimension: usize) -> Result<usize, ZetaError> {
    1usize
        .checked_shl(dimension as u32)
        .ok_or(ZetaError::DimensionMismatch)
}

/// Evaluate the multilinear extension of a Boolean table over QM31.
pub fn evaluate_mle_zeta<const N: usize>(
    table: &[M31; N],
    point: &[QM31],
) -> Result<QM31, ZetaError> {
    validate_power_of_two_length(N)?;
    if expected_table_length(point.len())? != N {
        return Err(ZetaError::DimensionMismatch);
    }

    let mut scratch = [QM31::ZERO; N];
    let mut index = 0usize;
    while index < N {
        scratch[index] = lift_m31(table[index]);
        index += 1;
    }

    let mut active = N;
    for coordinate in point {
        let half = active / 2;
        let mut pair = 0usize;
        while pair < half {
            let low = scratch[2 * pair];
            let high = scratch[2 * pair + 1];
            scratch[pair] = low.add(coordinate.mul(high.sub(low)));
            pair += 1;
        }
        active = half;
    }
    Ok(scratch[0])
}

/// Literal monomial evaluation of pre-zeta coefficients.  This intentionally
/// uses a different loop shape from [`evaluate_mle_zeta`] for differential
/// checking.
pub fn evaluate_monomial_coefficients<const N: usize>(
    coefficients: &[M31; N],
    point: &[QM31],
) -> Result<QM31, ZetaError> {
    validate_power_of_two_length(N)?;
    if expected_table_length(point.len())? != N {
        return Err(ZetaError::DimensionMismatch);
    }

    let mut result = QM31::ZERO;
    let mut mask = 0usize;
    while mask < N {
        let mut term = lift_m31(coefficients[mask]);
        let mut bit = 0usize;
        while bit < point.len() {
            if mask & (1usize << bit) != 0 {
                term = term.mul(point[bit]);
            }
            bit += 1;
        }
        result = result.add(term);
        mask += 1;
    }
    Ok(result)
}

pub fn stage_a_coefficients(source: &[M31; STAGE_A_SOURCE_LANES]) -> [M31; STAGE_A_PADDED_LANES] {
    let mut coefficients = [M31::ZERO; STAGE_A_PADDED_LANES];
    coefficients[..STAGE_A_SOURCE_LANES].copy_from_slice(source);
    coefficients
}

pub fn stage_a_zeta_table(source: &[M31; STAGE_A_SOURCE_LANES]) -> [M31; STAGE_A_PADDED_LANES] {
    let mut table = stage_a_coefficients(source);
    zeta_in_place_m31(&mut table).expect("fixed Stage-A table is power-of-two");
    table
}

/// Flatten three QM31 lanes as `(c0.a,c0.b,c1.a,c1.b)` with basis index in
/// the low two bits and source-lane index in the high two bits.
pub fn stage_b_coefficients(source: &[QM31; STAGE_B_QM31_LANES]) -> [M31; STAGE_B_PADDED_LANES] {
    let mut coefficients = [M31::ZERO; STAGE_B_PADDED_LANES];
    let mut lane = 0usize;
    while lane < STAGE_B_QM31_LANES {
        let limbs = qm31_limbs(source[lane]);
        coefficients[lane * QM31_LIMBS..(lane + 1) * QM31_LIMBS].copy_from_slice(&limbs);
        lane += 1;
    }
    coefficients
}

pub fn stage_b_zeta_table(source: &[QM31; STAGE_B_QM31_LANES]) -> [M31; STAGE_B_PADDED_LANES] {
    let mut table = stage_b_coefficients(source);
    zeta_in_place_m31(&mut table).expect("fixed Stage-B table is power-of-two");
    table
}

pub fn stage_a_lane_point(gamma: QM31) -> [QM31; STAGE_A_LANE_VARIABLES] {
    let gamma2 = gamma.square();
    let gamma4 = gamma2.square();
    let gamma8 = gamma4.square();
    let gamma16 = gamma8.square();
    [gamma, gamma2, gamma4, gamma8, gamma16]
}

pub fn stage_b_lane_point(gamma: QM31) -> [QM31; STAGE_B_LANE_VARIABLES] {
    [QM31_I, QM31_U, gamma, gamma.square()]
}

pub fn stage_a_restriction(table: &[M31; STAGE_A_PADDED_LANES], gamma: QM31) -> QM31 {
    evaluate_mle_zeta(table, &stage_a_lane_point(gamma)).expect("fixed Stage-A dimensions agree")
}

pub fn stage_b_restriction(table: &[M31; STAGE_B_PADDED_LANES], gamma: QM31) -> QM31 {
    evaluate_mle_zeta(table, &stage_b_lane_point(gamma)).expect("fixed Stage-B dimensions agree")
}

pub fn split_tensor_restriction(
    stage_a_table: &[M31; STAGE_A_PADDED_LANES],
    stage_b_table: &[M31; STAGE_B_PADDED_LANES],
    gamma: QM31,
) -> QM31 {
    stage_a_restriction(stage_a_table, gamma).add(
        gamma
            .pow(STAGE_B_OUTER_GAMMA_POWER)
            .mul(stage_b_restriction(stage_b_table, gamma)),
    )
}

/// Literal V6 width-29 gamma batch in the selected lane order.
pub fn width29_batch(
    stage_a_source: &[M31; STAGE_A_SOURCE_LANES],
    stage_b_source: &[QM31; STAGE_B_QM31_LANES],
    gamma: QM31,
) -> QM31 {
    let mut result = QM31::ZERO;
    let mut power = QM31::ONE;
    let mut lane = 0usize;
    while lane < STAGE_A_SOURCE_LANES {
        result = result.add(power.mul_m31(stage_a_source[lane]));
        power = power.mul(gamma);
        lane += 1;
    }
    let mut extension_lane = 0usize;
    while extension_lane < STAGE_B_QM31_LANES {
        result = result.add(power.mul(stage_b_source[extension_lane]));
        power = power.mul(gamma);
        extension_lane += 1;
    }
    debug_assert_eq!(lane + extension_lane, COMBINED_LANES);
    result
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::field::P;

    fn basis(index: usize) -> QM31 {
        let mut limbs = [M31::ZERO; QM31_LIMBS];
        limbs[index] = M31::ONE;
        qm31_from_limbs(limbs)
    }

    fn next_m31(state: &mut u64) -> M31 {
        *state = state
            .wrapping_mul(6_364_136_223_846_793_005)
            .wrapping_add(1_442_695_040_888_963_407);
        M31((*state % u64::from(P)) as u32)
    }

    fn next_qm31(state: &mut u64) -> QM31 {
        qm31_from_limbs([
            next_m31(state),
            next_m31(state),
            next_m31(state),
            next_m31(state),
        ])
    }

    #[test]
    fn zeta_mobius_round_trip_and_mle_identity() {
        let coefficients = [
            M31(2),
            M31(3),
            M31(5),
            M31(7),
            M31(11),
            M31(13),
            M31(17),
            M31(19),
        ];
        let original = coefficients;
        let mut table = coefficients;
        zeta_in_place_m31(&mut table).unwrap();
        let point = [
            qm31_from_limbs([M31(23), M31(29), M31(31), M31(37)]),
            qm31_from_limbs([M31(41), M31(43), M31(47), M31(53)]),
            qm31_from_limbs([M31(59), M31(61), M31(67), M31(71)]),
        ];
        assert_eq!(
            evaluate_mle_zeta(&table, &point),
            evaluate_monomial_coefficients(&original, &point)
        );
        mobius_in_place_m31(&mut table).unwrap();
        assert_eq!(table, original);
    }

    #[test]
    fn malformed_zeta_shapes_are_rejected() {
        let mut empty: [M31; 0] = [];
        let mut three = [M31::ZERO; 3];
        assert_eq!(zeta_in_place_m31(&mut empty), Err(ZetaError::EmptyTable));
        assert_eq!(
            mobius_in_place_m31(&mut three),
            Err(ZetaError::LengthNotPowerOfTwo)
        );
        assert_eq!(
            evaluate_mle_zeta(&[M31::ZERO; 4], &[QM31::ZERO]),
            Err(ZetaError::DimensionMismatch)
        );
    }

    #[test]
    fn every_stage_a_lane_and_padding_position_is_exact() {
        let gamma = qm31_from_limbs([M31(7), M31(11), M31(13), M31(17)]);
        for lane in 0..STAGE_A_SOURCE_LANES {
            let mut source = [M31::ZERO; STAGE_A_SOURCE_LANES];
            source[lane] = M31::ONE;
            let table = stage_a_zeta_table(&source);
            assert_eq!(stage_a_restriction(&table, gamma), gamma.pow(lane as u64));

            let mut recovered = table;
            mobius_in_place_m31(&mut recovered).unwrap();
            assert_eq!(recovered, stage_a_coefficients(&source));
            assert!(recovered[STAGE_A_SOURCE_LANES..]
                .iter()
                .all(|value| value.is_zero()));
        }
    }

    #[test]
    fn every_stage_b_limb_and_padding_position_is_exact() {
        let gamma = qm31_from_limbs([M31(19), M31(23), M31(29), M31(31)]);
        for lane in 0..STAGE_B_QM31_LANES {
            for limb in 0..QM31_LIMBS {
