                let mut recovered = table;
                mobius_in_place_m31(&mut recovered).unwrap();
                assert_eq!(recovered, stage_b_coefficients(&source));
                assert!(recovered[STAGE_B_QM31_LANES * QM31_LIMBS..]
                    .iter()
                    .all(|value| value.is_zero()));
