        let body = vec![0u8; V7_STAGED_PAIR_MAX_BODY_BYTES];
        let wire = V7StagedPairOneFoldWire::parse(&body, V7_COMPACT_FRONTIER_CAP_PER_TREE).unwrap();
        assert_eq!(wire.fixed_fields_packed.len(), 9_936);
        assert_eq!(wire.query(0).unwrap().c1_packed.len(), 403);
        assert_eq!(wire.query(0).unwrap().c2_packed.len(), 186);
        assert_eq!(wire.query(15).unwrap().salt.len(), 32);
        assert_eq!(wire.c1_frontier.len(), 203 * 26);
        assert_eq!(wire.c2_frontier.len(), 203 * 26);
    }

    #[test]
    fn staged_pair_parser_rejects_wrong_length_frontier_and_padding() {
        let mut body = vec![0u8; V7_STAGED_PAIR_MAX_BODY_BYTES];
        assert_eq!(
            V7StagedPairOneFoldWire::parse(&body[..body.len() - 1], 203),
            Err(V6WireError::WrongLength)
        );
        assert_eq!(
            V7StagedPairOneFoldWire::parse(&body, 204),
            Err(V6WireError::FrontierTooLarge)
        );
        body[V7_STAGED_PAIR_FIXED_FIELD_BYTES - 1] = 0x10;
        assert_eq!(
            V7StagedPairOneFoldWire::parse(&body, 203),
            Err(V6WireError::NonCanonicalM31)
        );
    }
}

crates/aspis-core/src/verify.rs:
//! The on-chain verifier logic (also the host reference — byte-exact shared
//! code path).
//!
//! What this proves, stated precisely (Stage 1 OOD-binding revision): transcript-bound
//! local fold consistency of a committed evaluation table down to an explicit
//! final polynomial, with grinding, against a bound statement digest, plus
//! transcript-derived per-round OOD points and an interleaved degree-6
//! sumcheck that enforces the OOD and external evaluation relations against
//! the explicit final coefficients. Version 3 also authenticates a
//! post-challenge C2 and folds its gamma-RLC with C1. Version 4 executes two
//! complete, sequential `(beta, y, mu)` OOD samples before each round's
//! sumcheck/fold challenge; its C2 leaf jointly authenticates two helper
//! columns. Scalar v4 folds `C1 + gamma*C2[0] + gamma^2*C2[1]`; the flagged
//! exact-wide PCS scaffold authenticates 49 CM31 C1 columns and replaces that
//! scalar layer-zero operation in place with powers 0..50. It is not paper
//! WHIR; the soundness note states the exact assumption and remaining
//! statement-layer delta.

use alloc::boxed::Box;
use alloc::vec;
use alloc::vec::Vec;

use crate::field::{
    cm31_batch_inverse_with, qm31_cm31_dot4_prepared_bytes, PreparedQm31Cm31Weights, CM31, M31,
    M31_QUARTER, QM31,
};
use crate::merkle::{
    leaf_hash, verify_minimal_subtree_bytes, verify_radix4_minimal_subtree_bytes,
    verify_single_path_bytes,
};
use crate::params::{
    profile_by_id, FoldPayload, MerkleMode, Profile, CIRCLE_GEN, CIRCLE_LOG_ORDER,
    FINAL_POLY_LOG_LEN, FOLD_VARS,
};
use crate::proof::{
    fiber_value_bytes, Cursor, Header, EXACT_WIDE_C1_COLUMNS, HEADER_LEN, OOD_VALUE_LEN,
    SECOND_PHASE_LAYER_TAG,
};
use crate::sumcheck::{
    boundary_sum as sumcheck_boundary, evaluate as evaluate_sumcheck, SumcheckPolynomial,
    WeightAccumulator, SUMCHECK_BYTES,
};
