/// Deliberately insecure schedules used only to prove that the canonical
/// challenge-order tests have teeth. This API does not exist unless the
/// explicit test feature is enabled.
#[cfg(feature = "insecure-test-ordering")]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum InsecureOrdering {
    ChiBeforeC1,
    GammaBeforeClaims,
    /// V4-only teeth schedule: helper claim 1 is absorbed, gamma is squeezed,
    /// then helper claim 2 is absorbed.
    GammaBeforeSecondHelperClaim,
    OodAfterFoldChallenge,
    /// V4-only teeth schedule: the first OOD triple is canonical, but alpha
    /// is squeezed between the second beta and its y/mu absorption.
    SecondOodAfterFoldChallenge,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum OrderingPolicy {
    Canonical,
    #[cfg(feature = "insecure-test-ordering")]
    ChiBeforeC1,
    #[cfg(feature = "insecure-test-ordering")]
    GammaBeforeClaims,
    #[cfg(feature = "insecure-test-ordering")]
    GammaBeforeSecondHelperClaim,
    #[cfg(feature = "insecure-test-ordering")]
    OodAfterFoldChallenge,
    #[cfg(feature = "insecure-test-ordering")]
    SecondOodAfterFoldChallenge,
}

impl OrderingPolicy {
    fn chi_before_c1(self) -> bool {
        #[cfg(feature = "insecure-test-ordering")]
        if self == Self::ChiBeforeC1 {
            return true;
        }
        false
    }

    fn gamma_before_claims(self) -> bool {
        #[cfg(feature = "insecure-test-ordering")]
        if self == Self::GammaBeforeClaims {
            return true;
        }
        false
    }

    fn gamma_before_second_helper_claim(self) -> bool {
        #[cfg(feature = "insecure-test-ordering")]
        if self == Self::GammaBeforeSecondHelperClaim {
            return true;
        }
        false
    }

    fn ood_after_fold_challenge(self) -> bool {
        #[cfg(feature = "insecure-test-ordering")]
        if self == Self::OodAfterFoldChallenge {
            return true;
        }
        false
    }

    fn second_ood_after_fold_challenge(self) -> bool {
        #[cfg(feature = "insecure-test-ordering")]
        if self == Self::SecondOodAfterFoldChallenge {
            return true;
        }
        false
    }
}

#[cfg(feature = "insecure-test-ordering")]
pub fn verify_with_insecure_ordering(
    proof: &[u8],
    statement_digest: &[u8; 32],
    claim: Option<&EvaluationClaim>,
    hash: HashFn,
    ordering: InsecureOrdering,
) -> Result<(), VerifyError> {
    let policy = match ordering {
        InsecureOrdering::ChiBeforeC1 => OrderingPolicy::ChiBeforeC1,
        InsecureOrdering::GammaBeforeClaims => OrderingPolicy::GammaBeforeClaims,
        InsecureOrdering::GammaBeforeSecondHelperClaim => {
            OrderingPolicy::GammaBeforeSecondHelperClaim
        }
        InsecureOrdering::OodAfterFoldChallenge => OrderingPolicy::OodAfterFoldChallenge,
        InsecureOrdering::SecondOodAfterFoldChallenge => {
            OrderingPolicy::SecondOodAfterFoldChallenge
        }
    };
    verify_inner(
        proof,
        statement_digest,
        claim,
        hash,
        None,
        VerificationMode {
            ordering: policy,
            denominator_backend: DenominatorBackend::CircleConjugate,
            allow_exact_wide_scaffold: false,
            allow_m31_circle_as_legacy: false,
        },
    )
}

/// Deliberately weakened framing used only by the adversarial proof-format
/// test. It accepts the new M31 discriminator but parses layer zero exactly
/// like the legacy scalar CM31 PCS, recreating the misclassification that the
/// production guard is intended to make impossible.
#[cfg(feature = "insecure-test-framing")]
pub fn verify_with_insecure_m31_circle_as_legacy_for_tests(
    proof: &[u8],
    statement_digest: &[u8; 32],
    claim: Option<&EvaluationClaim>,
    hash: HashFn,
) -> Result<(), VerifyError> {
    verify_inner(
        proof,
        statement_digest,
        claim,
        hash,
        None,
        VerificationMode {
            ordering: OrderingPolicy::Canonical,
            denominator_backend: DenominatorBackend::CircleConjugate,
            allow_exact_wide_scaffold: false,
            allow_m31_circle_as_legacy: true,
        },
    )
}

fn verify_inner(
    proof: &[u8],
    statement_digest: &[u8; 32],
    claim: Option<&EvaluationClaim>,
    hash: HashFn,
    trace_fn: Option<TraceFn>,
    mode: VerificationMode,
) -> Result<(), VerifyError> {
    trace(trace_fn, TraceEvent::Start);
    let header = Header::parse(proof).ok_or(VerifyError::BadHeader)?;
    if header.has_exact_wide_c1() && !mode.allow_exact_wide_scaffold {
        return Err(VerifyError::BadHeader);
    }
    if header.has_m31_circle_c1_diagnostic() && !mode.allow_m31_circle_as_legacy {
        return Err(VerifyError::BadHeader);
    }
    let profile = profile_by_id(header.profile_id).ok_or(VerifyError::UnknownProfile)?;
    if header.log_rows != profile.log_rows
        || header.log_blowup != profile.log_blowup
        || header.query_count != profile.query_count
        || header.grinding_bits != profile.grinding_bits
        || header.num_rounds != profile.num_rounds()
        || header.final_poly_log_len != FINAL_POLY_LOG_LEN
    {
        return Err(VerifyError::HeaderProfileMismatch);
    }
    let fold_payload = FoldPayload::from_u8(header.fold_payload).ok_or(VerifyError::BadHeader)?;
    let merkle_mode = MerkleMode::from_u8(header.merkle_mode).ok_or(VerifyError::BadHeader)?;
    // Claim flag and supplied claim must agree, and the point dimension must
    // match the profile — before anything is derived. Claim-carrying proofs
    // require C2 so gamma can bind v3's one or v4's two helper evaluations.
    match (header.has_claim(), claim) {
        (false, None) => {}
        (true, Some(claim)) => {
            if claim.z.len() != profile.log_rows as usize {
                return Err(VerifyError::ClaimShape);
            }
        }
        (true, None) => return Err(VerifyError::ClaimMissing),
        (false, Some(_)) => return Err(VerifyError::ClaimUnexpected),
    }
    if header.has_claim() && !header.has_second_phase() {
        return Err(VerifyError::BadHeader);
    }
    trace(trace_fn, TraceEvent::HeaderParsed);

    let num_rounds = profile.num_rounds();
    let query_count = profile.query_count as usize;

    let mut cursor = Cursor::new(proof);
    let header_bytes = cursor.take(HEADER_LEN).ok_or(VerifyError::BadLength)?;

    // ---- transcript phase ----
    let mut transcript = Transcript::new(hash);
    transcript.absorb(label::PROFILE, header_bytes);
    transcript.absorb(label::STATEMENT, statement_digest);

    // The insecure chi-before-C1 policy deliberately squeezes these values
    // before C1. Canonical verification takes the same two squeezes only
    // after the first root has been absorbed.
    if header.has_second_phase() && mode.ordering.chi_before_c1() {
        transcript
            .challenge_qm31()
            .map_err(|_| VerifyError::ChallengeSampleExhausted)?;
        transcript
            .challenge_qm31()
            .map_err(|_| VerifyError::ChallengeSampleExhausted)?;
    }

    let mut roots = Vec::with_capacity(num_rounds as usize);
    let mut alphas = Vec::with_capacity(num_rounds as usize);
    let mut relation_weights = WeightAccumulator::empty(profile.log_rows);
    let mut relation_value = QM31::ZERO;
    let mut second_phase_root = None;
    let mut gamma = None;
    let mut exact_wide_weights: Option<Box<ExactWideCombinationWeights>> = None;
    for layer in 0..num_rounds {
        let root = cursor.take_hash().ok_or(VerifyError::BadLength)?;
        transcript.absorb(label::ROOT, &root);
        roots.push(root);

        if layer == 0 && header.has_second_phase() {
            if !mode.ordering.chi_before_c1() {
                // lambda and chi: both are verifier-derived only after C1.
                transcript
                    .challenge_qm31()
                    .map_err(|_| VerifyError::ChallengeSampleExhausted)?;
                transcript
                    .challenge_qm31()
                    .map_err(|_| VerifyError::ChallengeSampleExhausted)?;
            }

            let c2_root = cursor.take_hash().ok_or(VerifyError::BadLength)?;
            transcript.absorb(label::SECOND_PHASE_ROOT, &c2_root);
            second_phase_root = Some(c2_root);

            let mut early_gamma = if mode.ordering.gamma_before_claims() {
                Some(
                    transcript
                        .challenge_qm31()
                        .map_err(|_| VerifyError::ChallengeSampleExhausted)?,
                )
            } else {
                None
            };

            let mut helper_claims = [None; 2];
            if let Some(main_claim) = claim {
                transcript.absorb(label::CLAIM, &main_claim.to_bytes());
                for (helper_index, helper_claim) in helper_claims
                    .iter_mut()
                    .take(header.second_phase_claim_count())
                    .enumerate()
                {
                    let bytes = cursor.take(OOD_VALUE_LEN).ok_or(VerifyError::BadLength)?;
                    let value = QM31::from_le_bytes(bytes).ok_or(VerifyError::NonCanonicalValue)?;
                    transcript.absorb(label::SECOND_PHASE_CLAIM, bytes);
                    *helper_claim = Some(value);
                    if helper_index == 0
                        && header.second_phase_claim_count() == 2
                        && mode.ordering.gamma_before_second_helper_claim()
                    {
                        early_gamma = Some(
                            transcript
                                .challenge_qm31()
                                .map_err(|_| VerifyError::ChallengeSampleExhausted)?,
                        );
                    }
                }
            }

            let sampled_gamma = match early_gamma {
                Some(value) => value,
                None => transcript
                    .challenge_qm31()
                    .map_err(|_| VerifyError::ChallengeSampleExhausted)?,
            };
            gamma = Some(sampled_gamma);
            let helper_weights = if header.has_exact_wide_c1() {
                let prepared = Box::new(prepare_exact_wide_combination(sampled_gamma));
                let helper_weights = prepared.helpers;
                exact_wide_weights = Some(prepared);
                helper_weights
            } else {
                [sampled_gamma, sampled_gamma.square()]
            };

            if let Some(main_claim) = claim {
                relation_weights = WeightAccumulator::from_claim(profile.log_rows, claim);
                relation_value = main_claim
                    .v
                    .add(helper_weights[0].mul(helper_claims[0].ok_or(VerifyError::BadHeader)?));
                if header.second_phase_claim_count() == 2 {
                    relation_value = relation_value.add(
                        helper_weights[1].mul(helper_claims[1].ok_or(VerifyError::BadHeader)?),
                    );
                }
            }
        }

        // Canonical v3 schedule: (beta_1, y_1, mu_1). Canonical v4 appends a
        // complete second triple before the shared sumcheck and alpha. The
        // deliberately weakened schedules insert alpha after the selected
        // beta and before its y/mu; all paths share the exact y/mu kernel.
        let mut early_alpha = None;
        for sample in 0..header.ood_samples_per_round() {
            let weaken_this_sample = (sample == 0 && mode.ordering.ood_after_fold_challenge())
                || (sample == 1 && mode.ordering.second_ood_after_fold_challenge());
            if weaken_this_sample {
                let point = sample_ood_point(&mut transcript)?;
                early_alpha = Some(
                    transcript
                        .challenge_qm31()
                        .map_err(|_| VerifyError::ChallengeSampleExhausted)?,
                );
                let bytes: &[u8; OOD_VALUE_LEN] = cursor
                    .take(OOD_VALUE_LEN)
                    .ok_or(VerifyError::BadLength)?
                    .try_into()
                    .map_err(|_| VerifyError::BadLength)?;
                absorb_ood_value_and_accumulate(
                    &mut transcript,
                    point,
                    bytes,
                    &mut relation_value,
                    &mut relation_weights,
                )?;
            } else {
                let bytes: &[u8; OOD_VALUE_LEN] = cursor
                    .take(OOD_VALUE_LEN)
                    .ok_or(VerifyError::BadLength)?
                    .try_into()
                    .map_err(|_| VerifyError::BadLength)?;
                accumulate_canonical_ood_sample(
                    &mut transcript,
                    bytes,
                    &mut relation_value,
                    &mut relation_weights,
                )?;
            }
        }
        // This marker denotes all complete beta/y/mu relation samples.
        trace(trace_fn, TraceEvent::LayerOodDone(layer as u8));

        let sumcheck_bytes = cursor.take(SUMCHECK_BYTES).ok_or(VerifyError::BadLength)?;
        let mut sumcheck: SumcheckPolynomial = [QM31::ZERO; 7];
        for (index, chunk) in sumcheck_bytes.chunks_exact(16).enumerate() {
            sumcheck[index] = QM31::from_le_bytes(chunk).ok_or(VerifyError::NonCanonicalValue)?;
        }
        if sumcheck_boundary(&sumcheck) != relation_value {
            return Err(VerifyError::SumcheckBoundaryMismatch { layer: layer as u8 });
        }
        transcript.absorb(label::SUMCHECK_POLY, sumcheck_bytes);
        trace(trace_fn, TraceEvent::LayerSumcheckDone(layer as u8));

        let alpha = match early_alpha {
            Some(value) => value,
            None => transcript
                .challenge_qm31()
                .map_err(|_| VerifyError::ChallengeSampleExhausted)?,
        };
        relation_value = evaluate_sumcheck(&sumcheck, alpha);
        relation_weights.fold(alpha);
        alphas.push(alpha);
    }

    let final_poly_len = profile.final_poly_len() as usize;
    let final_poly_bytes = cursor
        .take(final_poly_len * 16)
        .ok_or(VerifyError::BadLength)?;
    transcript.absorb(label::FINAL_POLY, final_poly_bytes);
    let mut final_poly = Vec::with_capacity(final_poly_len);
    for chunk in final_poly_bytes.chunks_exact(16) {
        final_poly.push(QM31::from_le_bytes(chunk).ok_or(VerifyError::NonCanonicalValue)?);
    }
    if relation_weights.dot(&final_poly) != relation_value {
        return Err(VerifyError::EvaluationRelationMismatch);
    }

    let nonce = cursor.take_u64().ok_or(VerifyError::BadLength)?;
    if !transcript.grinding_ok(nonce, profile.grinding_bits) {
        return Err(VerifyError::GrindingFailed);
    }
    transcript.absorb(label::GRIND_NONCE, &nonce.to_le_bytes());
    trace(trace_fn, TraceEvent::TranscriptReady);

    let mut domain_table = DomainPowerTable::new(profile);
    let queries = transcript.challenge_queries(query_count, domain_table.geometry.fiber_count);
    trace(trace_fn, TraceEvent::QueriesReady);

    // ---- opening + fold phase ----
    // per-query running domain index i_r (i_0 = sampled fiber index)
    let mut index: Vec<u32> = queries.clone();
    // raw mode: expected incoming value per query; carried mode: deferred check3
    let mut expected: Vec<QM31> = vec![QM31::ZERO; query_count];
    let mut deferred: Vec<Option<CarriedDeferred>> = Vec::new();
    if fold_payload == FoldPayload::ProofCarriedRoundLocal {
        deferred = (0..query_count).map(|_| None).collect();
    }

    let mut fiber_index: Vec<u32> = Vec::with_capacity(query_count);
    let mut slot: Vec<u32> = Vec::with_capacity(query_count);
    let mut unique: Vec<u32> = Vec::with_capacity(query_count);
    let mut fibers: Vec<Fiber> = Vec::with_capacity(query_count);
    let mut helper_fibers: Vec<([QM31; 4], Option<[QM31; 4]>)> = Vec::with_capacity(query_count);
    let mut carried: Vec<(QM31, QM31)> = Vec::with_capacity(query_count);
    let mut entries: Vec<(u32, [u8; 32])> = Vec::with_capacity(query_count);
    let mut merkle_level: Vec<(u32, [u8; 32])> = Vec::with_capacity(query_count);
    let mut merkle_next: Vec<(u32, [u8; 32])> = Vec::with_capacity(query_count);
    let mut s_values: Vec<CM31> = Vec::with_capacity(query_count);
    let mut folded: Vec<QM31> = Vec::with_capacity(query_count);
    let mut denoms: Vec<CM31> = Vec::with_capacity(query_count * 3);
    let mut invs: Vec<CM31> = Vec::with_capacity(query_count * 3);

    for layer in 0..num_rounds {
        trace(trace_fn, TraceEvent::LayerStart(layer as u8));
        let geom = domain_table.geometry;
        let alpha = alphas[layer as usize];
        let alpha2 = alpha.square();
        let fiber_mask = geom.fiber_count - 1;

        // geometry per query
        fiber_index.clear();
        slot.clear();
        for i in &index {
            fiber_index.push(*i & fiber_mask);
            slot.push(*i >> geom.log_fiber_count);
        }
        unique.clear();
        unique.extend_from_slice(&fiber_index);
        unique.sort_unstable();
        unique.dedup();

        let unique_count = cursor.take_u16().ok_or(VerifyError::BadLength)? as usize;
        if unique_count != unique.len() {
            return Err(VerifyError::UniqueCountMismatch { layer: layer as u8 });
        }
        let exact_wide_layer_zero = layer == 0 && header.has_exact_wide_c1();
        let value_bytes = if layer == 0
            && header.has_m31_circle_c1_diagnostic()
            && mode.allow_m31_circle_as_legacy
        {
            fiber_value_bytes(layer)
        } else {
            header.first_phase_leaf_len(layer)
        };
        let values_section = cursor
            .take(unique_count * value_bytes)
            .ok_or(VerifyError::BadLength)?;
        fibers.clear();
        if !exact_wide_layer_zero {
            for k in 0..unique_count {
                fibers.push(parse_fiber(
                    &values_section[k * value_bytes..(k + 1) * value_bytes],
                    layer,
                )?);
            }
        }

        // C2 is opened only in the first layer. V3 authenticates one helper
        // fiber; v4 authenticates two helpers in one combined leaf. Scalar
        // v4 materializes those helper fibers. Exact-wide v4 instead replaces
        // the scalar layer-zero operation in place: the once-prepared byte
        // kernel consumes each 1,568-byte C1 leaf and matching 128-byte C2
        // leaf directly, then supplies the same four extension slots to the
        // unchanged fold path.
        let second_phase_values_section = if layer == 0 && header.has_second_phase() {
            let helper_value_bytes = header.second_phase_leaf_len();
            let section = cursor
                .take(unique_count * helper_value_bytes)
                .ok_or(VerifyError::BadLength)?;
            if exact_wide_layer_zero {
                let weights = exact_wide_weights
                    .as_deref()
                    .ok_or(VerifyError::BadHeader)?;
                for index in 0..unique_count {
                    let c1_leaf = &values_section[index * value_bytes..(index + 1) * value_bytes];
                    let c2_leaf =
                        &section[index * helper_value_bytes..(index + 1) * helper_value_bytes];
                    fibers.push(combine_exact_wide_sections(c1_leaf, c2_leaf, weights)?);
                }
            } else {
                helper_fibers.clear();
                for index in 0..unique_count {
                    let leaf =
                        &section[index * helper_value_bytes..(index + 1) * helper_value_bytes];
                    helper_fibers.push(if header.second_phase_helper_count() == 1 {
                        (parse_extension_fiber(leaf)?, None)
                    } else {
                        let (helper_1, helper_2) = parse_double_extension_fiber(leaf)?;
                        (helper_1, Some(helper_2))
                    });
                }
                let gamma = gamma.ok_or(VerifyError::BadHeader)?;
                for index in 0..unique_count {
                    let (helper_1, helper_2) = helper_fibers[index];
                    fibers[index] =
                        combine_first_phase_fibers(&fibers[index], helper_1, helper_2, gamma)?;
                }
            }
            Some(section)
        } else {
            None
        };

        carried.clear();
        if fold_payload == FoldPayload::ProofCarriedRoundLocal {
            let carried_section = cursor
                .take(unique_count * 32)
                .ok_or(VerifyError::BadLength)?;
            for chunk in carried_section.chunks_exact(32) {
                let g1 =
                    QM31::from_le_bytes(&chunk[0..16]).ok_or(VerifyError::NonCanonicalValue)?;
                let g2 =
                    QM31::from_le_bytes(&chunk[16..32]).ok_or(VerifyError::NonCanonicalValue)?;
                carried.push((g1, g2));
            }
        }

        // Merkle verification over the unique C1 fiber leaves.
        let root = &roots[layer as usize];
        let depth = geom.log_fiber_count;
        verify_merkle_section(
            &mut cursor,
            hash,
            merkle_mode,
            root,
            depth,
            &unique,
            values_section,
            value_bytes,
            layer as u8,
            layer as u8,
            &mut entries,
            &mut merkle_level,
            &mut merkle_next,
        )?;

        if let Some(section) = second_phase_values_section {
            let c2_root = second_phase_root.as_ref().ok_or(VerifyError::BadHeader)?;
            verify_merkle_section(
                &mut cursor,
                hash,
                merkle_mode,
                c2_root,
                depth,
                &unique,
                section,
                header.second_phase_leaf_len(),
                SECOND_PHASE_LAYER_TAG,
                SECOND_PHASE_LAYER_TAG,
                &mut entries,
                &mut merkle_level,
                &mut merkle_next,
            )?;
        }
        trace(trace_fn, TraceEvent::LayerMerkleDone(layer as u8));

        // Slot consistency for the incoming value (layers >= 1).
        for q in 0..query_count {
            let k = unique.binary_search(&fiber_index[q]).unwrap();
            if layer > 0 {
                let opened = fibers[k].get(slot[q]);
                match fold_payload {
                    FoldPayload::RawFibers => {
                        if opened != expected[q] {
                            return Err(VerifyError::SlotMismatch { layer: layer as u8 });
                        }
                    }
                    FoldPayload::ProofCarriedRoundLocal => {
                        let d = deferred[q].as_ref().unwrap();
                        if opened.mul_cm31(d.two_s2) != d.rhs {
                            return Err(VerifyError::CarriedFoldMismatch {
                                layer: layer as u8 - 1,
                            });
                        }
                    }
                }
            }
        }

        // Fold each unique fiber once (round_batch_inversion in raw mode).
        s_values.clear();
        for &fidx in &unique {
            s_values.push(domain_table.point(fidx));
        }
        folded.clear();
        folded.resize(unique.len(), QM31::ZERO);
        match fold_payload {
            FoldPayload::RawFibers => {
                invs.clear();
                match mode.denominator_backend {
                    DenominatorBackend::CircleConjugate => {
                        // Every s is derived from the unit circle, hence
                        // s^-1 = conjugate(s). The constant iota is -i, so
                        // iota^-1 = i and inv(2*iota*s) is just a swap/negate
                        // of inv(2s). No batch inversion or denominator
                        // materialization is needed.
                        for &s in &s_values {
                            let inv_s = s.conjugate();
                            let inv_2s = inv_s.half();
                            invs.push(inv_2s);
                            invs.push(inv_2s.mul_i());
                            invs.push(inv_s.square().half());
                        }
                    }
                    DenominatorBackend::BatchInverse(inverse) => {
                        denoms.clear();
                        for &s in &s_values {
                            denoms.push(s.double());
                            denoms.push(s.mul(geom.iota).double());
                            denoms.push(s.square().double());
                        }
                        invs.resize(denoms.len(), CM31::ZERO);
                        cm31_batch_inverse_with(&denoms, &mut invs, inverse);
                    }
                }
                for (k, fiber) in fibers.iter().enumerate() {
                    folded[k] = fold_fiber(
                        fiber,
                        alpha,
                        alpha2,
                        invs[k * 3],
                        invs[k * 3 + 1],
                        invs[k * 3 + 2],
                    );
                }
            }
            FoldPayload::ProofCarriedRoundLocal => {
                for (k, fiber) in fibers.iter().enumerate() {
                    let (g1, g2) = carried[k];
                    let (ok, d) =
                        carried_checks(fiber, g1, g2, alpha, alpha2, s_values[k], geom.iota);
                    if !ok {
                        return Err(VerifyError::CarriedFoldMismatch { layer: layer as u8 });
                    }
                    // store per-fiber deferred into every query hitting it
                    for q in 0..query_count {
                        if fiber_index[q] == unique[k] {
                            deferred[q] = Some(CarriedDeferred {
                                two_s2: d.two_s2,
                                rhs: d.rhs,
                            });
                        }
                    }
                }
            }
        }
        if fold_payload == FoldPayload::RawFibers {
            for q in 0..query_count {
                let k = unique.binary_search(&fiber_index[q]).unwrap();
                expected[q] = folded[k];
            }
        }

        index[..query_count].copy_from_slice(&fiber_index[..query_count]);
        domain_table.fold_layer();
        trace(trace_fn, TraceEvent::LayerFoldDone(layer as u8));
    }

    // ---- final polynomial check ----
    trace(trace_fn, TraceEvent::FinalCheckStart);
    // After all arity-4 folds the q transcript queries land in a tiny final
    // domain (16 points for the frozen blowup-2 profiles). Cache each cubic
    // evaluation by index instead of repeating it for colliding queries.
    folded.clear();
    folded.resize(domain_table.geometry.domain_size as usize, QM31::ZERO);
    slot.clear();
    slot.resize(domain_table.geometry.domain_size as usize, 0);
    for q in 0..query_count {
        let final_index = index[q] as usize;
        if slot[final_index] == 0 {
            let x = domain_table.point(index[q]);
            // Horner over QM31 coefficients at a CM31 point (late lift).
            let mut acc = *final_poly.last().unwrap();
            for c in final_poly.iter().rev().skip(1) {
                acc = acc.mul_cm31(x).add(*c);
            }
            folded[final_index] = acc;
            slot[final_index] = 1;
        }
        let acc = folded[final_index];
        match fold_payload {
            FoldPayload::RawFibers => {
                if acc != expected[q] {
                    return Err(VerifyError::FinalPolyMismatch);
                }
            }
            FoldPayload::ProofCarriedRoundLocal => {
                let d = deferred[q].as_ref().unwrap();
                if acc.mul_cm31(d.two_s2) != d.rhs {
                    return Err(VerifyError::FinalPolyMismatch);
                }
            }
        }
    }

    if !cursor.is_empty() {
        return Err(VerifyError::TrailingBytes);
    }
    trace(trace_fn, TraceEvent::Done);
    Ok(())
}

#[cfg(test)]
mod probe_tests {
    use super::*;
    use core::sync::atomic::{AtomicUsize, Ordering};

    static HASH_CALLS: AtomicUsize = AtomicUsize::new(0);

    fn host_hash(inputs: &[&[u8]]) -> [u8; 32] {
        use sha2::{Digest, Sha256};
        let mut hasher = Sha256::new();
        for input in inputs {
            hasher.update(input);
        }
        hasher.finalize().into()
    }

    fn counting_host_hash(inputs: &[&[u8]]) -> [u8; 32] {
        HASH_CALLS.fetch_add(1, Ordering::SeqCst);
        host_hash(inputs)
    }

    fn encoded_probe_output(samples_per_round: u8) -> [u8; 16] {
        let value = ood_sample_relation_probe(host_hash, samples_per_round)
            .expect("fixed probe transcript must not exhaust");
        let mut encoded = [0u8; 16];
        value.write_le_bytes(&mut encoded);
        encoded
    }

    #[test]
    fn ood_sample_probe_sinks_are_pinned() {
        assert_eq!(
            encoded_probe_output(1),
            OOD_SAMPLE_PROBE_S1_EXPECTED,
            "s=1 OOD probe sink drifted; re-pin only for a deliberate probe-kernel change"
        );
        assert_eq!(
            encoded_probe_output(2),
            OOD_SAMPLE_PROBE_S2_EXPECTED,
            "s=2 OOD probe sink drifted; re-pin only for a deliberate probe-kernel change"
        );
    }

    #[test]
    fn preencoded_ood_probe_values_match_the_reference_formula() {
        for (index, expected) in OOD_PROBE_ENCODED_VALUES.iter().enumerate() {
            let mut actual = [0u8; OOD_VALUE_LEN];
            ood_probe_value(index as u32, 3).write_le_bytes(&mut actual);
            assert_eq!(&actual, expected);
        }
    }

    #[test]
    fn ood_sample_probe_rejects_non_protocol_counts() {
        assert_eq!(
            ood_sample_relation_probe(host_hash, 0),
            Err(VerifyError::BadHeader)
        );
        assert_eq!(
            ood_sample_relation_probe(host_hash, 3),
            Err(VerifyError::BadHeader)
        );
    }

    #[test]
    fn second_samples_add_exactly_twenty_no_retry_hash_calls() {
        HASH_CALLS.store(0, Ordering::SeqCst);
        ood_sample_relation_probe(counting_host_hash, 1).unwrap();
        let s1_calls = HASH_CALLS.load(Ordering::SeqCst);
        HASH_CALLS.store(0, Ordering::SeqCst);
        ood_sample_relation_probe(counting_host_hash, 2).unwrap();
        let s2_calls = HASH_CALLS.load(Ordering::SeqCst);
        assert_eq!(s2_calls - s1_calls, 20);
    }
}

crates/aspis-core/tests/fuzz_field.rs:
//! Fuzz-style harness for field/encoding invariants (canonical M31/QM31
//! decoding and degenerate circle-point handling).
//!
//! Approach: proptest on the pinned stable toolchain, same rationale as
//! `fuzz_parser.rs` (cargo-fuzz would require nightly + libFuzzer).
//!
//! Invariants exercised:
//!  * `M31::from_le_bytes` accepts a 4-byte word iff it is canonical (`< P`),
//!    rejects every non-canonical word (`>= P`, including the exact modulus),
//!    and canonical decodes round-trip through `to_le_bytes`.
//!  * `CM31`/`QM31` decoding accepts a wire encoding iff *every* limb is
//!    canonical, and round-trips.
//!  * The circle-point maps never panic on arbitrary parameters, land on the
//!    unit circle when they succeed, and the OOD map rejects the whole CM31
//!    parameter subfield and the singular parameter with the defined errors.

use aspis_core::circle::{
    secure_circle_point_from_parameter, secure_ood_circle_point_from_parameter, CirclePointError,
};
use aspis_core::field::{CM31, M31, P, QM31};
use proptest::prelude::*;

fn cm31(a: u32, b: u32) -> CM31 {
    CM31::new(M31(a % P), M31(b % P))
}

fn qm31(limbs: [u32; 4]) -> QM31 {
    QM31 {
        c0: cm31(limbs[0], limbs[1]),
        c1: cm31(limbs[2], limbs[3]),
    }
}

proptest! {
    #![proptest_config(ProptestConfig::with_cases(512))]

    /// M31 decoding is exactly canonical: Some iff value < P, and round-trips.
    #[test]
    fn m31_decode_is_canonical(value in any::<u32>()) {
        let bytes = value.to_le_bytes();
        match M31::from_le_bytes(bytes) {
            Some(elem) => {
                prop_assert!(value < P, "accepted a non-canonical M31 word {value:#x}");
                prop_assert_eq!(elem.to_le_bytes(), bytes, "canonical M31 did not round-trip");
            }
            None => {
                prop_assert!(value >= P, "rejected a canonical M31 word {value:#x}");
            }
        }
    }

    /// The exact modulus and everything above it is non-canonical.
    #[test]
    fn m31_rejects_non_canonical(excess in 0u32..=(u32::MAX - P)) {
        let value = P.wrapping_add(excess);
        prop_assert!(M31::from_le_bytes(value.to_le_bytes()).is_none());
    }

    /// CM31 accepts iff both limbs are canonical; round-trips when accepted.
    #[test]
    fn cm31_decode_is_canonical(a in any::<u32>(), b in any::<u32>()) {
        let mut bytes = [0u8; 8];
        bytes[0..4].copy_from_slice(&a.to_le_bytes());
        bytes[4..8].copy_from_slice(&b.to_le_bytes());
        match CM31::from_le_bytes(&bytes) {
            Some(elem) => {
                prop_assert!(a < P && b < P);
                let mut out = [0u8; 8];
                elem.write_le_bytes(&mut out);
                prop_assert_eq!(out, bytes);
            }
            None => prop_assert!(a >= P || b >= P),
        }
    }

    /// QM31 accepts iff all four limbs are canonical; round-trips when accepted.
    #[test]
    fn qm31_decode_is_canonical(limbs in any::<[u32; 4]>()) {
        let mut bytes = [0u8; 16];
        for (i, limb) in limbs.iter().enumerate() {
            bytes[i * 4..i * 4 + 4].copy_from_slice(&limb.to_le_bytes());
        }
        match QM31::from_le_bytes(&bytes) {
            Some(elem) => {
                prop_assert!(limbs.iter().all(|&l| l < P));
                let mut out = [0u8; 16];
                elem.write_le_bytes(&mut out);
                prop_assert_eq!(out, bytes);
            }
            None => prop_assert!(limbs.iter().any(|&l| l >= P)),
        }
    }

    /// Poison one QM31 limb to exactly P: decoding must reject.
    #[test]
    fn qm31_rejects_single_non_canonical_limb(
        mut limbs in any::<[u32; 4]>(),
        poison in 0usize..4,
    ) {
        for l in limbs.iter_mut() {
            *l %= P;
        }
        limbs[poison] = P; // exactly the modulus: non-canonical
        let mut bytes = [0u8; 16];
        for (i, limb) in limbs.iter().enumerate() {
            bytes[i * 4..i * 4 + 4].copy_from_slice(&limb.to_le_bytes());
        }
        prop_assert!(QM31::from_le_bytes(&bytes).is_none());
    }

    /// The circle parameterization never panics and lands on the unit circle.
    #[test]
    fn circle_point_is_non_panicking_and_on_circle(limbs in any::<[u32; 4]>()) {
        let parameter = qm31(limbs);
        if let Ok(point) = secure_circle_point_from_parameter(parameter) {
            prop_assert_eq!(point.x.square().add(point.y.square()), QM31::ONE);
        }
        // The OOD variant never panics and agrees with the plain map on success.
        if let Ok(point) = secure_ood_circle_point_from_parameter(parameter) {
            prop_assert_eq!(point.x.square().add(point.y.square()), QM31::ONE);
        }
    }

    /// Degenerate circle points: any parameter drawn from the CM31 subfield
    /// (c1 == 0) is rejected canonically by the OOD policy — either as the
    /// singular parameter (t = ±i) or as a CM31-subfield parameter.
    #[test]
    fn ood_rejects_cm31_subfield_parameters(a in any::<u32>(), b in any::<u32>()) {
        let parameter = QM31::from_cm31(cm31(a, b));
        match secure_ood_circle_point_from_parameter(parameter) {
            Err(CirclePointError::ParameterInCm31Subfield)
            | Err(CirclePointError::SingularParameter) => {}
            other => prop_assert!(
                false,
                "CM31-subfield parameter was not rejected canonically: {other:?}"
            ),
        }
    }
}

/// The two circle singularities `t = ±i` are reported as the defined singular
/// error rather than panicking through the inverse.
#[test]
fn circle_singularities_are_defined_errors() {
    let plus_i = QM31::from_cm31(CM31::new(M31::ZERO, M31::ONE));
    let minus_i = QM31::from_cm31(CM31::new(M31::ZERO, M31(P - 1)));
    for singular in [plus_i, minus_i] {
        assert_eq!(
            secure_circle_point_from_parameter(singular),
            Err(CirclePointError::SingularParameter)
        );
        assert_eq!(
            secure_ood_circle_point_from_parameter(singular),
            Err(CirclePointError::SingularParameter)
        );
    }
}

crates/aspis-core/tests/fuzz_parser.rs:
//! Fuzz-style harness for the fixed-layout proof/prefix parser surface.
//!
//! Approach: the workspace is pinned to a stable toolchain (the CI job uses
//! `dtolnay/rust-toolchain@stable`), so cargo-fuzz's nightly + libFuzzer
//! requirement is out of scope. These are `proptest` harnesses that run under
//! the ordinary `cargo test` on the same stable pin.
//!
//! Guarantees exercised:
//!  * `proof::Header::parse` never panics on arbitrary bytes, and every
//!    accepted header round-trips: `write(parse(x)) == x[..HEADER_LEN]`.
//!  * The candidate/state-only/spend prefix parsers never panic on arbitrary
//!    or fixture-mutated bytes and only ever return a defined `Result`.
//!  * The absolute-offset helpers never panic and never return an offset
//!    outside the supplied proof bytes.
//!
//! The committed valid release proof fixture seeds a small deterministic
//! corpus so the harness explores structurally valid inputs and their local
//! mutations, not only random noise.

use aspis_core::circle_prefix::PaymentCandidatePrefix;
use aspis_core::proof::{
    first_layer_first_phase_opening_offset, first_layer_second_phase_helper_offset,
    first_layer_second_phase_opening_offset, ood_value_offset, second_phase_claim_offset, Cursor,
    Header, HEADER_LEN,
};
use aspis_core::state_only_prefix::{
    StateOnlyCandidatePrefix, StateOnlyProfile21Prefix, StateOnlySpendPrefix,
};
use proptest::prelude::*;

/// The committed valid Spend release proof. Used only to seed a structurally
/// valid starting corpus; the harness asserts no panics, not acceptance.
const RELEASE_PROOF: &[u8] =
    include_bytes!("../../aspis-prover/fixtures/spend_q18_g37_release.bin");

/// Drive every parser and offset helper on one byte string. Returns nothing;
/// the contract is that none of these calls may panic and every offset that
/// is returned lies within `bytes`.
fn exercise_all_parsers(bytes: &[u8]) {
    // Header: never panics, and any accepted header re-serializes to the same
    // 16 header bytes (canonical round-trip).
    if let Some(header) = Header::parse(bytes) {
        let mut written = [0u8; HEADER_LEN];
        header.write(&mut written);
        assert_eq!(
            &written[..],
            &bytes[..HEADER_LEN],
            "accepted header did not round-trip through write()"
        );

        // The pure header-arithmetic offset helpers are exercised only for
        // no-panic / no-overflow: they compute where a value *would* sit in a
        // complete proof, so their result may legitimately exceed a truncated
        // input's length. They must, however, never panic.
        for layer in 0..(header.num_rounds as usize).min(64) + 1 {
            for sample in 0..header.ood_samples_per_round() + 1 {
                let _ = ood_value_offset(&header, layer, sample);
            }
        }
        for helper in 0..header.second_phase_claim_count() + 1 {
            let _ = second_phase_claim_offset(&header, helper);
        }
    }

    // Proof-byte offset helpers: never panic, never return an offset that would
    // index past the slice.
    if let Some(offset) = first_layer_first_phase_opening_offset(bytes) {
        assert!(offset <= bytes.len(), "c1 opening offset out of bounds");
    }
    if let Some(offset) = first_layer_second_phase_opening_offset(bytes) {
        assert!(offset <= bytes.len(), "c2 opening offset out of bounds");
    }
    for helper in 0..3 {
        if let Some(offset) = first_layer_second_phase_helper_offset(bytes, helper) {
            assert!(offset <= bytes.len(), "c2 helper offset out of bounds");
        }
    }

    // The structured prefix parsers: reject-or-parse, never panic. Any leftover
    // openings slice returned must be a suffix of the input.
    if let Ok((_, rest)) = PaymentCandidatePrefix::parse_from_proof(bytes) {
        assert!(rest.len() <= bytes.len());
    }
    if let Ok((_, rest)) = StateOnlyCandidatePrefix::parse_from_proof(bytes) {
        assert!(rest.len() <= bytes.len());
    }
    if let Ok((_, rest)) = StateOnlySpendPrefix::parse_from_proof(bytes) {
        assert!(rest.len() <= bytes.len());
    }
    if let Ok((_, rest)) = StateOnlyProfile21Prefix::parse_from_proof(bytes) {
        assert!(rest.len() <= bytes.len());
    }

    // The bounded cursor must never read past its slice.
    let mut cursor = Cursor::new(bytes);
    let _ = cursor.take_u32();
    let _ = cursor.take_hash();
    let _ = cursor.take_u64();
    assert!(cursor.position() <= bytes.len());
}

proptest! {
    #![proptest_config(ProptestConfig::with_cases(256))]

    /// Arbitrary bytes must never panic any parser or offset helper.
    #[test]
    fn arbitrary_bytes_never_panic(bytes in proptest::collection::vec(any::<u8>(), 0..320)) {
        exercise_all_parsers(&bytes);
    }

    /// Arbitrary bytes carrying a plausible header prefix (correct magic and a
    /// supported version) reach deeper into the parsers than pure noise.
    #[test]
    fn plausible_header_bytes_never_panic(
        mut bytes in proptest::collection::vec(any::<u8>(), HEADER_LEN..320)
    ) {
        bytes[0..4].copy_from_slice(b"ASP0");
        // Restrict the version byte to the two recognised envelopes so parsing
        // proceeds past the header gate more often.
        bytes[4] = if bytes[4] & 1 == 0 { 3 } else { 4 };
        exercise_all_parsers(&bytes);
    }

    /// Single-byte mutations of the committed valid proof: exercises the
    /// accept/reject boundary around a structurally valid input.
    #[test]
    fn single_byte_mutation_of_valid_proof_never_panics(
        index in 0usize..RELEASE_PROOF.len(),
        delta in 1u8..=255,
    ) {
        let mut bytes = RELEASE_PROOF.to_vec();
        bytes[index] = bytes[index].wrapping_add(delta);
        exercise_all_parsers(&bytes);
    }

    /// Truncations of the committed valid proof at arbitrary lengths.
    #[test]
    fn truncations_of_valid_proof_never_panic(len in 0usize..=RELEASE_PROOF.len()) {
        exercise_all_parsers(&RELEASE_PROOF[..len]);
    }
}

