//! Actual-core differential checks for the retained sequential cursor model.
//! Exhaustive over bounded retry schedules, NOT over values or oracle histories.
//! The scripted backend is deterministic by input; this is not an RO-law test.
use aspis_core::field::{P, QM31};
use aspis_core::transcript::{Transcript, CHALLENGE_RETRY_LIMIT};
use std::cell::RefCell;

#[derive(Default)]
struct Script {
    words: Vec<u32>,
    calls: Vec<(usize, u8)>,
}
thread_local! { static SCRIPT: RefCell<Script> = RefCell::new(Script::default()); }

fn hash(parts: &[&[u8]]) -> [u8; 32] {
    let input: Vec<u8> = parts.iter().flat_map(|p| p.iter().copied()).collect();
    assert_eq!(input.len(), 33);
    assert!(input[8..32].iter().all(|&b| b == 0));
    let index = u64::from_le_bytes(input[..8].try_into().unwrap()) as usize;
    let domain = input[32];
    SCRIPT.with(|s| {
        let mut s = s.borrow_mut();
        s.calls.push((index, domain));
        let mut out = [0; 32];
        match domain {
            1 => {
                for (slot, word) in out
                    .chunks_exact_mut(4)
                    .zip(&s.words[index * 8..(index + 1) * 8])
                {
                    slot.copy_from_slice(&word.to_le_bytes());
                }
            }
            2 => out[..8].copy_from_slice(&((index + 1) as u64).to_le_bytes()),
            _ => panic!("unexpected domain {domain}"),
        }
        out
    })
}

// Operational counterpart of scanMany: one shared cursor, resetting only
// the per-limb attempt budget. A short input is a fixture error, not an abort.
fn cursor_model(words: &[u32]) -> (Option<[u32; 4]>, usize) {
    let mut cursor = 0;
    let mut values = [0; 4];
    for value in &mut values {
        let candidates = &words[cursor..cursor + 8];
        match candidates.iter().position(|w| w & P != P) {
            Some(rejected) => {
                *value = candidates[rejected] & P;
                cursor += rejected + 1;
            }
            None => return (None, cursor + 8),
        }
    }
    (Some(values), cursor)
}

fn limbs(q: QM31) -> [u32; 4] {
    [q.c0.a.0, q.c0.b.0, q.c1.a.0, q.c1.b.0]
}

fn check_schedule(rejections: &[usize], exhaust: bool, high_bit_phase: usize) {
    assert_eq!(CHALLENGE_RETRY_LIMIT, 8, "pinned model budget changed");
    let accepted = [0, 1, P - 1, 0x0123_4567];
    let mut words: Vec<u32> = (0..48).map(|i| 0x0203_0405 + i).collect();
    let mut cursor = 0;
    for (limb, &rejected) in rejections.iter().enumerate() {
        words[cursor..cursor + rejected].fill(P);
        cursor += rejected;
        words[cursor] = accepted[limb];
        cursor += 1;
    }
    if exhaust {
        words[cursor..cursor + 8].fill(P);
        cursor += 8;
    }
    // Both encodings of every masked candidate occur across the two runs.
    // Rejected words include both 0x7fffffff and 0xffffffff.
    for (i, word) in words.iter_mut().enumerate() {
        *word |= (((i + high_bit_phase) % 2) as u32) << 31;
    }
    let (expected, used) = cursor_model(&words);
    assert_eq!(used, cursor);
    assert_eq!(expected.is_none(), exhaust);
    if !exhaust {
        assert_eq!(expected, Some(accepted));
    }
    let blocks = used.div_ceil(8);
    let (next_expected, next_used) = cursor_model(&words[blocks * 8..]);
    assert_eq!(next_used, 4);
    SCRIPT.with(|s| {
        *s.borrow_mut() = Script {
            words,
            calls: Vec::new(),
        }
    });
    let mut transcript = Transcript::new(hash);
    assert_eq!(transcript.challenge_qm31().ok().map(limbs), expected);
    let mut expected_state = [0; 32];
    expected_state[..8].copy_from_slice(&(blocks as u64).to_le_bytes());
    assert_eq!(transcript.diagnostic_state(), expected_state);
    SCRIPT.with(|s| {
        let s = s.borrow();
        let expected_calls: Vec<_> = (0..blocks).flat_map(|i| [(i, 1), (i, 2)]).collect();
        assert_eq!(s.calls, expected_calls);
    });
    // A new call starts a new block, not at the previous unconsumed word.
    // This also checks the retained transcript state after an explicit abort.
    assert_eq!(transcript.challenge_qm31().ok().map(limbs), next_expected);
    expected_state[..8].copy_from_slice(&((blocks + 1) as u64).to_le_bytes());
    assert_eq!(transcript.diagnostic_state(), expected_state);
    SCRIPT.with(|s| {
        let s = s.borrow();
        let expected_calls: Vec<_> = (0..=blocks).flat_map(|i| [(i, 1), (i, 2)]).collect();
        assert_eq!(s.calls, expected_calls);
    });
}

fn digits(mut code: usize, count: usize) -> Vec<usize> {
    (0..count)
        .map(|_| {
            let digit = code % 8;
            code /= 8;
            digit
        })
        .collect()
}

#[test]
fn every_successful_retry_schedule_matches_shared_cursor() {
    let mut checked = 0;
    for code in 0..8usize.pow(4) {
        for phase in 0..2 {
            check_schedule(&digits(code, 4), false, phase);
            checked += 1;
        }
    }
    assert_eq!(checked, 8192);
    println!("checked 4096 success schedules, both high-bit phases, next-call discard");
}

#[test]
fn every_reachable_limb_exhaustion_schedule_matches_shared_cursor() {
    let mut checked = 0;
    for preceding_limbs in 0..4 {
        for code in 0..8usize.pow(preceding_limbs) {
            for phase in 0..2 {
                check_schedule(&digits(code, preceding_limbs as usize), true, phase);
                checked += 1;
            }
        }
    }
    assert_eq!(checked, 1170);
    println!("checked 585 exhaustion schedules, both high-bit phases, post-abort state");
}

crates/aspis-core/tests/r17_transcript_f:
//! Operational sampler boundaries, not a random-oracle or SHA-256 security test.
//! A deterministic injected backend is permitted by Transcript's API. Freshness
//! therefore needs an explicit cryptographic good-event argument, not just an
//! appeal to the presence of a DOM_ADVANCE call.
use aspis_core::field::{CM31, M31, P, QM31};
use aspis_core::transcript::{CirclePointSampleError, Transcript};
use std::cell::RefCell;
use sha2::{Digest, Sha256};

#[derive(Default)]
struct Trace {
    calls: Vec<Vec<u8>>,
    mode: u8,
}
thread_local! { static TRACE: RefCell<Trace> = RefCell::new(Trace::default()); }

fn reset(mode: u8) {
    TRACE.with(|t| *t.borrow_mut() = Trace { calls: Vec::new(), mode });
}

fn scripted_hash(parts: &[&[u8]]) -> [u8; 32] {
    let input: Vec<u8> = parts.iter().flat_map(|x| x.iter().copied()).collect();
    assert_eq!(input.len(), 33, "these tests exercise squeezes/advances only");
    TRACE.with(|t| {
        let mut t = t.borrow_mut();
        t.calls.push(input.clone());
        let mut out = [0u8; 32];
        match input[32] {
            1 => {
                let words = match t.mode {
                    // Accepted non-subfield parameter; repeated input, repeated output.
                    0 => [17, 18, 19, 20, 21, 22, 23, 24],
                    // Seven rejected words before each accepted limb; four blocks.
                    1 => [P, P, P, P, P, P, P, 17 + u32::from(input[0])],
                    // Every QM31 value is zero, hence rejected by the OOD policy.
                    2 => [0; 8],
                    // The first limb exhausts all eight allowed attempts.
                    3 => [P; 8],
                    _ => unreachable!(),
                };
                for (slot, word) in out.chunks_exact_mut(4).zip(words) {
                    slot.copy_from_slice(&word.to_le_bytes());
                }
            }
            2 => {
                // Mode zero deliberately cycles to the initial state. Other modes
                // use a distinct, deterministic next state for each block.
                if t.mode != 0 { out[0] = input[0].checked_add(1).unwrap(); }
            }
            _ => panic!("unexpected domain"),
        }
        out
    })
}

fn squeezes() -> Vec<Vec<u8>> {
    TRACE.with(|t| t.borrow().calls.iter().filter(|x| x[32] == 1).cloned().collect())
}

fn logged_sha256(parts: &[&[u8]]) -> [u8; 32] {
    let input: Vec<u8> = parts.iter().flat_map(|x| x.iter().copied()).collect();
    TRACE.with(|t| t.borrow_mut().calls.push(input.clone()));
    Sha256::digest(&input).into()
}

#[test]
fn public_next_squeeze_can_be_prequeried_without_a_collision() {
    reset(0);
    let mut next_input = [0u8; 33];
    next_input[32] = 1;
    let _prior_answer = logged_sha256(&[&next_input]);
    let mut t = Transcript::new(logged_sha256);
    t.challenge_qm31().unwrap();
    let inputs = squeezes();
    assert_eq!(inputs.len(), 2);
    assert_eq!(inputs[0], inputs[1]);
    TRACE.with(|t| assert_eq!(t.borrow().calls.len(), 3));
}

#[test]
fn advancing_state_does_not_unconditionally_imply_fresh_inputs() {
    reset(0);
    let mut t = Transcript::new(scripted_hash);
    let first = t.challenge_qm31().unwrap();
    for _ in 0..5 { assert_eq!(t.challenge_qm31().unwrap(), first); }
    let inputs = squeezes();
    assert_eq!(inputs.len(), 6);
    assert!(inputs.iter().all(|x| x == &inputs[0]));
    assert_eq!(t.diagnostic_state(), [0; 32]);
    TRACE.with(|t| assert_eq!(t.borrow().calls.len(), 12));
}

#[test]
fn maximal_successful_limb_retries_consume_four_blocks() {
    reset(1);
    let mut t = Transcript::new(scripted_hash);
    assert_eq!(t.challenge_qm31().unwrap(), QM31 {
        c0: CM31::new(M31(17), M31(18)),
        c1: CM31::new(M31(19), M31(20)),
    });
    let inputs = squeezes();
    assert_eq!(inputs.len(), 4);
    for (i, input) in inputs.iter().enumerate() { assert_eq!(input[0], i as u8); }
    TRACE.with(|t| assert_eq!(t.borrow().calls.len(), 8));
}

#[test]
fn outer_circle_exhaustion_and_inner_limb_exhaustion_stay_distinct() {
    reset(2);
    let mut t = Transcript::new(scripted_hash);
    assert_eq!(t.challenge_secure_circle_point(), Err(CirclePointSampleError::ParameterSampleExhausted));
    assert_eq!(squeezes().len(), 3);
    reset(3);
    let mut t = Transcript::new(scripted_hash);
    assert_eq!(t.challenge_secure_circle_point(), Err(CirclePointSampleError::ChallengeSampleExhausted));
    assert_eq!(squeezes().len(), 1);
}

#[test]
fn core_circle_sampler_does_not_enforce_distinct_successive_points() {
    reset(0);
    let mut t = Transcript::new(scripted_hash);
    let first = t.challenge_secure_circle_point().unwrap();
    assert_eq!(t.challenge_secure_circle_point().unwrap(), first);
    assert_eq!(squeezes().len(), 2);
}

