    pub(crate) deposit_event_ids: Vec<DepositEventIdV1>,
    pub(crate) deposit_outcomes: Vec<DepositScanOutcomeV1>,
    pub(crate) transition_outcomes: Vec<PublicOutputScanOutcomeV1>,
