        ));
        assert_eq!(signer.calls, 0);
        assert_eq!(rpc.simulation_calls, 0);
        assert_eq!(rpc.submit_calls, 0);
        assert_eq!(journal.record_count_v2(), 0);
        cleanup(&path);
    }
