    #[test]
    fn encrypted_deposit_hook_tracks_pair_witness_and_private_transfer_is_one_append() {
        let (_, _, _, _, mut state) = fixtures();
        let (secret, public) = derive_viewing_keypair_v1(&[0x42; 32]).unwrap();
        let note = NoteOpeningV1::new(
            encode_digest_canonical(&digest(100)),
            7,
            4,
            encode_digest_canonical(&digest(200)),
        )
        .unwrap();
        let commitment = recompute_note_commitment_v1(&note).unwrap();
        let lane_id = LaneIdV2::new(commitment[0] & 7).unwrap();
        let context = NoteContextV1::new(
            state.core.master.address,
            state.core.master.value.identity.deployment_domain,
            0,
            commitment,
        )
        .unwrap();
        let payload = encrypt_note_v1(&mut FixedTestRng(9), &public, &context, &note).unwrap();
        let deposit = deposit_event(&state, event(20, 1, 0), commitment, Some(payload));
        let outcomes = state
            .ingest_finalized_append_v2(deposit, Some(&secret))
            .unwrap();
        assert!(matches!(
            outcomes[0].outcome,
            ForestNoteAssociationOutcomeV2::Recovered(_)
        ));
        assert_eq!(state.lane(lane_id).1.tracked().len(), 1);

        let nullifier = encode_digest_canonical(&digest(301));
        let output_lane = LaneIdV2::new(nullifier[0] & 7).unwrap();
        let recipient = encode_digest_canonical(&digest(401));
        let change = encode_digest_canonical(&digest(501));
        let pair_leaf = PoolV1PairLeafWitnessV1::two_outputs(
            decode_digest_canonical(&recipient).unwrap(),
            decode_digest_canonical(&change).unwrap(),
        )
        .unwrap()
        .leaf_digest()
        .unwrap();
        let before = state.core.lanes[output_lane.index()]
            .account
            .value
            .tree
            .next_leaf_index;
        let (address, image) = after_lane_for_leaf(&state, output_lane, pair_leaf);
        let transfer = ForestFinalizedAppendEventV2 {
            master: state.core.master.address,
            lane_id: output_lane,
            pair_leaf_index: before,
            root_sequence: before + 1,
            after_lane_address: address,
            after_lane_image: image,
            kind: ForestFinalizedAppendKindV2::PrivateTransfer {
                recipient_event_id: event(21, 2, 0),
                change_event_id: event(21, 2, 1),
                nullifier,
                recipient_commitment: recipient,
                change_commitment: change,
                recipient_encrypted_note: None,
                change_encrypted_note: None,
            },
        };
        let wire = encode_forest_finalized_append_event_v2(&transfer).unwrap();
        let transfer = decode_forest_finalized_append_event_v2(&wire).unwrap();
        state.ingest_finalized_append_v2(transfer, None).unwrap();
        assert_eq!(
            state.core.lanes[output_lane.index()]
                .account
                .value
                .tree
                .next_leaf_index,
            before + 1
        );
    }

    #[test]
    fn checkpoint_durable_roundtrip_and_finalized_rollback_is_rejected() {
        let (_, _, _, _, mut state) = fixtures();
        let first = deposit_event(
            &state,
            event(30, 1, 0),
            encode_digest_canonical(&digest(601)),
            None,
        );
        state.ingest_finalized_append_v2(first, None).unwrap();
        let (master_address, master_image, lanes, checkpoint_address, checkpoint_image) =
            checkpoint_inputs(&state);
        state
            .ingest_finalized_checkpoint_v2(
                FinalizedChainPointV1::new(31, [32; 32]).unwrap(),
                master_address,
                &master_image,
                &lanes,
                checkpoint_address,
                &checkpoint_image,
            )
            .unwrap();
        let at_checkpoint = state.clone();
        let encoded = encode_lane_forest_durable_state_v2(&state).unwrap();
        assert_eq!(
            decode_lane_forest_durable_state_v2(&encoded).unwrap(),
            state
        );
        let mut tampered = encoded;
        *tampered.last_mut().unwrap() ^= 1;
        assert_eq!(
            decode_lane_forest_durable_state_v2(&tampered),
            Err(LaneForestDurableErrorV2::ChecksumMismatch)
        );

        let second = deposit_event(
            &state,
            event(32, 1, 0),
            encode_digest_canonical(&digest(701)),
            None,
        );
        state.ingest_finalized_append_v2(second, None).unwrap();
        let after_second = state.clone();
        assert_eq!(
            state.rollback_to_finalized_checkpoint_v2(0),
            Err(LaneForestDurableErrorV2::InvalidRollback)
        );
        assert_eq!(state, after_second);
        assert_ne!(state, at_checkpoint);
    }

    #[test]
    fn retained_checkpoint_exports_authenticated_live_spend_membership() {
        let (_, _, _, _, mut state) = fixtures();
        let output_id = event(40, 1, 0);
        let commitment = encode_digest_canonical(&digest(801));
        let append = deposit_event(&state, output_id, commitment, None);
        let input_lane = append.lane_id;
        state
            .ingest_finalized_append_preselected_v2(append, &[output_id])
            .unwrap();
        let (master_address, master_image, lanes, checkpoint_address, checkpoint_image) =
            checkpoint_inputs(&state);
        let checkpoint_point = FinalizedChainPointV1::new(41, [42; 32]).unwrap();
        state
            .ingest_finalized_checkpoint_v2(
                checkpoint_point,
                master_address,
                &master_image,
                &lanes,
                checkpoint_address,
                &checkpoint_image,
            )
            .unwrap();

        let membership = state
            .authenticated_spend_membership_v2(output_id, 0)
            .unwrap();
        assert_eq!(membership.checkpoint_point, checkpoint_point);
        assert_eq!(membership.checkpoint_address, checkpoint_address);
        assert_eq!(membership.checkpoint_sequence, 0);
        assert_eq!(membership.input_lane, input_lane);
        assert_eq!(membership.pair_leaf_index, 0);
        assert_eq!(membership.slot, PairSlotV2::First);
        assert_eq!(membership.first_commitment, commitment);
        assert_eq!(membership.second_commitment, None);
        for (actual, expected) in membership
            .pair_siblings
            .iter()
            .zip(&POOL_V1_PAIR_EMPTY_ROOTS[..POOL_V1_TREE_DEPTH])
        {
            assert_eq!(*actual, encode_digest_canonical(expected));
        }
        assert_eq!(
            lane_forest_global_root_v2(&membership.checkpoint_lane_roots).unwrap(),
            encode_digest_canonical(&state.checkpoints[0].checkpoint.value.global_root)
        );
        assert_eq!(
            state.authenticated_spend_membership_v2(output_id, 1),
            Err(LaneForestDurableErrorV2::CheckpointSequenceMismatch)
        );
    }

    #[test]
    fn atomic_file_reopens_and_replaces_the_exact_durable_forest() {
        let (_, _, _, _, initial) = fixtures();
        let nonce = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_nanos();
        let path = std::env::temp_dir().join(format!(
            "aspis-eight-lane-durable-v2-{}-{nonce}.bin",
            std::process::id()
        ));
        let lock_path = path.with_file_name(format!(
            "{}.lock",
            path.file_name().unwrap().to_string_lossy()
        ));
        let mut advanced = initial.clone();
        advanced
            .ingest_finalized_append_v2(
                deposit_event(
                    &advanced,
                    event(40, 1, 0),
                    encode_digest_canonical(&digest(801)),
                    None,
                ),
                None,
            )
            .unwrap();
        {
            let mut file =
                DurableLaneForestWalletFileV2::open_or_create_v2(&path, initial.clone()).unwrap();
            assert_eq!(file.state(), &initial);
            file.replace_state_v2(advanced.clone()).unwrap();
            assert_eq!(file.state(), &advanced);
        }
        {
            let file = DurableLaneForestWalletFileV2::open_or_create_v2(&path, initial).unwrap();
            assert_eq!(file.state(), &advanced);
        }
        std::fs::remove_file(&path).unwrap();
        std::fs::remove_file(&lock_path).unwrap();
    }
}

//! Default-off finalized RPC adapter for the eight-lane pair forest.
//!
//! `ASF8` is exclusively the 1,880-byte cryptographic semantic statement. The
//! compact wallet-side normalized scanner record in this module is `ASFE`; it
//! is not an on-chain Pool event and must never be accepted from program logs.
//! The production boundary bypasses that record and derives the ASL2 event
//! directly from the exact successful, finalized, last top-level `ASQ8` Pool
//! instruction, its Pool-owned `ASR8` return data and the deployment-owned
//! finalized root page. The older batch adapter remains default-off for
//! fixtures and independently supplied scanner evidence.
//!
//! The existing relayer execution journal is a separate atomic file and this
//! consumer ABI has no authenticated relayer request identifier. Cross-file
//! atomic coordination is therefore not claimed: withdrawals are returned to
//! the caller for later correlation once the producer ABI supplies that link.

use aspis_pool::POOL_V1_PAIR_EMPTY_ROOTS;
use aspis_statement::{
    decode_digest_canonical, encode_digest_canonical,
    pool_v1::{
        decode_pool_v1_pair_forest_lane_state_v1, decode_pool_v1_pair_forest_terminal_request_v1,
        decode_pool_v1_pair_forest_terminal_result_v1, encode_pool_v1_pair_forest_lane_state_v1,
        root_history::{read_root_history_page_root_v1, validate_root_history_page_bytes_v1},
        PoolV1PairForestLaneStateV1, PoolV1PairForestTerminalPaymentV1, PoolV1PairLeafWitnessV1,
        PoolV1RootHistoryError, PoolV1TransitionKind, POOL_V1_PAIR_CAPACITY,
        POOL_V1_PAIR_FOREST_CHECKPOINT_ACCOUNT_BYTES, POOL_V1_PAIR_FOREST_LANE_ACCOUNT_BYTES,
        POOL_V1_PAIR_FOREST_MASTER_ACCOUNT_BYTES, POOL_V1_ROOT_HISTORY_PAGE_ACCOUNT_BYTES,
    },
};
use hpke::rand_core::CryptoRng;

use crate::{
    durable_state::SealedNoteAccessV1,
    finalized_indexer::SolanaRpcCommitmentV1,
    lane_forest_durable_v2::{
        canonical_lane_root_page_cursor_v2, DurableLaneForestWalletFileV2,
        ForestFinalizedAppendEventV2, ForestFinalizedAppendKindV2, ForestNoteAssociationV2,
        LaneForestDurableErrorV2, LaneForestDurableStateV2,
    },
    lane_forest_v2::{LaneIdV2, POOL_V1_LANE_COUNT_V2},
    lane_forest_wallet_txn_v2::{
