            Err(PairForestTransactionV1ErrorV2::ComputeBudgetInstructionForbidden)
        );

        let (program, master, lane, profile, request) = terminal_fixture(false, false);
        let instruction = build_pair_forest_terminal_instruction_v1_4k_v2(
            program,
            &master,
            &lane,
            profile,
            key(55),
            key(52),
            &request,
        )
        .unwrap();
        let lookup_table = AddressLookupTableAccount {
            key: key(53),
            addresses: vec![key(54)],
        };
        assert_eq!(
            build_exact_pair_forest_v1_transaction_v2(
                &instruction,
                key(55),
                [56; 32],
                config(),
                &[lookup_table],
            ),
            Err(PairForestTransactionV1ErrorV2::AddressLookupTableForbidden)
        );
        let mut invalid = config();
        invalid.compute_unit_limit = 0;
        assert_eq!(
            build_exact_pair_forest_v1_transaction_v2(
                &instruction,
                key(55),
                [56; 32],
                invalid,
                &[],
            ),
            Err(PairForestTransactionV1ErrorV2::InvalidComputeLimit)
        );

        let oversized = Instruction {
            program_id: key(57),
            accounts: vec![],
            data: vec![0u8; 4_000],
        };
        assert_eq!(
            build_exact_pair_forest_v1_transaction_v2(&oversized, key(58), [59; 32], config(), &[],),
            Err(PairForestTransactionV1ErrorV2::TransactionTooLarge)
        );
    }

    #[test]
    fn devnet_feature_account_parser_distinguishes_missing_pending_and_active() {
        assert_eq!(
            feature_activation_v2(&serde_json::Value::Null),
            Ok((false, None))
        );
        let pending = serde_json::json!({
            "owner": SOLANA_FEATURE_PROGRAM_ID_V2,
            "data": [BASE64_STANDARD.encode([0u8]), "base64"]
        });
        assert_eq!(feature_activation_v2(&pending), Ok((true, None)));
        let mut active = vec![1u8];
        active.extend_from_slice(&987_654u64.to_le_bytes());
        let active = serde_json::json!({
            "owner": SOLANA_FEATURE_PROGRAM_ID_V2,
            "data": [BASE64_STANDARD.encode(active), "base64"]
        });
        assert_eq!(feature_activation_v2(&active), Ok((true, Some(987_654))));
        let wrong_owner = serde_json::json!({
            "owner": "11111111111111111111111111111111",
            "data": [BASE64_STANDARD.encode([0u8]), "base64"]
        });
        assert_eq!(
            feature_activation_v2(&wrong_owner),
            Err(TxV1CapabilityProbeErrorV2::WrongFeatureOwner)
        );
    }
}

//! Zero-signature simulation envelope for the frozen V7 one-terminal TxV1.
//!
//! This module does not own or load keys, contact RPC, sign, or submit. It
//! converts one already-reviewed `ASQ8` Pool instruction into the exact TxV1
//! wire used by `simulateTransaction` and pins the release gates that are easy
//! to lose at a client boundary: one top-level instruction, the expected Pool
//! account shape, 320 request bytes, a strict 1.3M-CU limit, and a wire strictly
//! below 4,096 bytes.

use base64::{engine::general_purpose::STANDARD as BASE64_STANDARD, Engine as _};
use serde::Serialize;
use sha2::{Digest as _, Sha256};
use solana_address_v1::Address;
use solana_hash_v1::Hash as V1Hash;
use solana_message_v1::{v1, VersionedMessage as V1VersionedMessage};
use solana_program::{instruction::Instruction, pubkey::Pubkey};
use solana_sdk_ids::system_program;
use solana_signature_v1::Signature as V1Signature;
use solana_transaction_v1::versioned::VersionedTransaction as V1VersionedTransaction;

use crate::lane_forest_transaction_v1::{
    to_v1_instruction_v2, SOLANA_V1_TRANSACTION_MAX_BYTES_V2, SOLANA_V1_VERSION_PREFIX_V2,
};

pub const V7_TX_V1_TERMINAL_COMPUTE_UNIT_LIMIT_V2: u32 = 1_300_000;
pub const V7_TX_V1_TERMINAL_LOADED_ACCOUNT_BYTES_V2: u32 = 64 * 1024 * 1024;
pub const V7_TX_V1_TERMINAL_REQUEST_BYTES_V2: usize = 320;
/// Pool terminal instruction data: ASQ8 request || 4 B4 bump hints.
pub const V7_TX_V1_TERMINAL_INSTRUCTION_DATA_BYTES_V2: usize =
    V7_TX_V1_TERMINAL_REQUEST_BYTES_V2 + aspis_pool::POOL_V1_PAIR_FOREST_TERMINAL_BUMP_HINT_BYTES;
pub const V7_TX_V1_TERMINAL_RETURN_BYTES_V2: usize = 792;

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize)]
#[serde(rename_all = "kebab-case")]
pub enum PairForestTerminalOperationV2 {
    PrivateTransfer,
    Withdrawal,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize)]
#[serde(rename_all = "kebab-case")]
pub enum PairForestTerminalHistoryPathV2 {
    SamePage,
    Rollover,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize)]
pub struct PairForestTxV1CaseV2 {
    pub operation: PairForestTerminalOperationV2,
    pub history_path: PairForestTerminalHistoryPathV2,
}

impl PairForestTxV1CaseV2 {
    pub const fn expected_instruction_accounts_v2(self) -> usize {
        match (self.operation, self.history_path) {
            (
                PairForestTerminalOperationV2::PrivateTransfer,
                PairForestTerminalHistoryPathV2::SamePage,
            ) => 11,
            (
                PairForestTerminalOperationV2::PrivateTransfer,
                PairForestTerminalHistoryPathV2::Rollover,
            ) => 12,
            (
                PairForestTerminalOperationV2::Withdrawal,
                PairForestTerminalHistoryPathV2::SamePage,
            ) => 16,
            (
                PairForestTerminalOperationV2::Withdrawal,
                PairForestTerminalHistoryPathV2::Rollover,
            ) => 17,
        }
    }

    pub const fn marker_payer_index_v2(self) -> usize {
        match self.history_path {
            PairForestTerminalHistoryPathV2::SamePage => 5,
            PairForestTerminalHistoryPathV2::Rollover => 6,
        }
    }

    /// Includes the 4 B4 bump-hint bytes of the terminal instruction data.
    pub const fn expected_wire_bytes_v2(self) -> usize {
        match (self.operation, self.history_path) {
            (
                PairForestTerminalOperationV2::PrivateTransfer,
                PairForestTerminalHistoryPathV2::SamePage,
            ) => 837,
            (
                PairForestTerminalOperationV2::PrivateTransfer,
                PairForestTerminalHistoryPathV2::Rollover,
            ) => 870,
            (
                PairForestTerminalOperationV2::Withdrawal,
                PairForestTerminalHistoryPathV2::SamePage,
            ) => 1_002,
            (
                PairForestTerminalOperationV2::Withdrawal,
                PairForestTerminalHistoryPathV2::Rollover,
            ) => 1_035,
        }
    }
}

