fn sha256_hex_v2(bytes: &[u8]) -> String {
    Sha256::digest(bytes)
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect()
}

#[allow(clippy::too_many_arguments)]
pub fn build_pair_forest_tx_v1_simulation_preflight_v2(
    request_id: u64,
    min_context_slot: u64,
    fee_payer: Pubkey,
    recent_blockhash: [u8; 32],
    instruction: &Instruction,
    case: PairForestTxV1CaseV2,
    post_state_accounts: &[Pubkey],
) -> Result<PairForestTxV1SimulationPreflightV2, PairForestTxV1SimulationErrorV2> {
    if request_id == 0 {
        return Err(PairForestTxV1SimulationErrorV2::ZeroRequestId);
    }
    if min_context_slot == 0 {
        return Err(PairForestTxV1SimulationErrorV2::ZeroContextSlot);
    }
    if fee_payer == Pubkey::default() {
        return Err(PairForestTxV1SimulationErrorV2::ZeroFeePayer);
    }
    if instruction.program_id == Pubkey::default() {
        return Err(PairForestTxV1SimulationErrorV2::ZeroProgram);
    }
    if instruction.accounts.len() != case.expected_instruction_accounts_v2() {
        return Err(PairForestTxV1SimulationErrorV2::WrongInstructionAccountCount);
    }
    if instruction.data.len() != V7_TX_V1_TERMINAL_INSTRUCTION_DATA_BYTES_V2
        || instruction.data.get(..4) != Some(b"ASQ8")
    {
        return Err(PairForestTxV1SimulationErrorV2::WrongInstructionData);
    }
    let payer_index = case.marker_payer_index_v2();
    let payer = &instruction.accounts[payer_index];
    let system = &instruction.accounts[payer_index + 1];
    if payer.pubkey != fee_payer
        || !payer.is_signer
        || !payer.is_writable
        || system.pubkey != system_program::id()
        || system.is_signer
        || system.is_writable
        || instruction
            .accounts
            .iter()
            .enumerate()
            .any(|(index, meta)| index != payer_index && meta.is_signer)
    {
        return Err(PairForestTxV1SimulationErrorV2::UnexpectedInstructionSigner);
    }
    if post_state_accounts.len() > 64 {
        return Err(PairForestTxV1SimulationErrorV2::TooManyPostStateAccounts);
    }

    let config = v1::TransactionConfig::empty()
        .with_compute_unit_limit(V7_TX_V1_TERMINAL_COMPUTE_UNIT_LIMIT_V2)
        .with_loaded_accounts_data_size_limit(V7_TX_V1_TERMINAL_LOADED_ACCOUNT_BYTES_V2);
    let message = v1::Message::try_compile_with_config(
        &Address::from(fee_payer.to_bytes()),
        &[to_v1_instruction_v2(instruction)
            .map_err(|_| PairForestTxV1SimulationErrorV2::CompileFailed)?],
        V1Hash::new_from_array(recent_blockhash),
        config,
    )
    .map_err(|_| PairForestTxV1SimulationErrorV2::CompileFailed)?;
    let required_signatures = message.header.num_required_signatures;
    if required_signatures != 1 {
        return Err(PairForestTxV1SimulationErrorV2::WrongSignatureCount);
    }
    let inline_addresses = message.account_keys.len();
    let versioned_message = V1VersionedMessage::V1(message);
    versioned_message
        .sanitize()
        .map_err(|_| PairForestTxV1SimulationErrorV2::SanitizeFailed)?;
    let signable_message = versioned_message.serialize();
    let transaction = V1VersionedTransaction {
        signatures: vec![V1Signature::default()],
        message: versioned_message,
    };
    transaction
        .sanitize()
        .map_err(|_| PairForestTxV1SimulationErrorV2::SanitizeFailed)?;
    let placeholder_wire = wincode::serialize(&transaction)
        .map_err(|_| PairForestTxV1SimulationErrorV2::SerializationFailed)?;
    if placeholder_wire.first().copied() != Some(SOLANA_V1_VERSION_PREFIX_V2) {
        return Err(PairForestTxV1SimulationErrorV2::WrongVersion);
    }
    if placeholder_wire.len() >= SOLANA_V1_TRANSACTION_MAX_BYTES_V2 {
        return Err(PairForestTxV1SimulationErrorV2::TransactionTooLarge);
    }
    if placeholder_wire.len() != case.expected_wire_bytes_v2() {
        return Err(PairForestTxV1SimulationErrorV2::WrongWireSize);
    }

    let placeholder_signatures_are_zero = transaction
        .signatures
        .iter()
        .all(|signature| *signature == V1Signature::default());
    let summary = PairForestTxV1SimulationSummaryV2 {
        schema: "aspis.v7.txv1-simulation-summary.v1",
        case,
        pool_program: instruction.program_id.to_string(),
        fee_payer: fee_payer.to_string(),
        min_context_slot,
        compute_unit_limit: V7_TX_V1_TERMINAL_COMPUTE_UNIT_LIMIT_V2,
        loaded_accounts_data_size_limit: V7_TX_V1_TERMINAL_LOADED_ACCOUNT_BYTES_V2,
        priority_fee_present: false,
        heap_size_present: false,
        required_signatures,
        inline_addresses,
        instruction_accounts: instruction.accounts.len(),
        instruction_data_bytes: instruction.data.len(),
        serialized_transaction_bytes: placeholder_wire.len(),
        headroom_to_4096_bytes: SOLANA_V1_TRANSACTION_MAX_BYTES_V2 - placeholder_wire.len(),
        signable_message_sha256: sha256_hex_v2(&signable_message),
        placeholder_wire_sha256: sha256_hex_v2(&placeholder_wire),
        placeholder_signatures_are_zero,
        simulation_only: true,
    };
    let simulation_request_json = serde_json::to_vec(&SimulationRequestV2 {
        jsonrpc: "2.0",
        id: request_id,
        method: "simulateTransaction",
        params: (
            BASE64_STANDARD.encode(&placeholder_wire),
            SimulationConfigV2 {
                encoding: "base64",
                commitment: "finalized",
                sig_verify: false,
                replace_recent_blockhash: false,
                min_context_slot,
                inner_instructions: true,
                accounts: (!post_state_accounts.is_empty()).then(|| SimulationAccountsConfigV2 {
                    encoding: "base64",
                    addresses: post_state_accounts
                        .iter()
                        .map(ToString::to_string)
                        .collect(),
                }),
            },
        ),
    })
    .map_err(|_| PairForestTxV1SimulationErrorV2::SerializationFailed)?;
    Ok(PairForestTxV1SimulationPreflightV2 {
        summary,
        placeholder_wire,
        simulation_request_json,
    })
}

#[cfg(test)]
mod tests {
    use super::*;
    use solana_program::instruction::AccountMeta;

    fn key(seed: u8) -> Pubkey {
        Pubkey::new_from_array([seed; 32])
    }

    fn instruction(case: PairForestTxV1CaseV2, fee_payer: Pubkey) -> Instruction {
        let account_count = case.expected_instruction_accounts_v2();
        let payer_index = case.marker_payer_index_v2();
        let mut accounts = (0..account_count)
            .map(|index| AccountMeta::new(key(index as u8 + 1), false))
            .collect::<Vec<_>>();
        accounts[payer_index] = AccountMeta::new(fee_payer, true);
        accounts[payer_index + 1] = AccountMeta::new_readonly(system_program::id(), false);
        Instruction {
            program_id: key(200),
            accounts,
            data: {
                let mut data = vec![0u8; V7_TX_V1_TERMINAL_INSTRUCTION_DATA_BYTES_V2];
                data[..4].copy_from_slice(b"ASQ8");
                data
            },
        }
    }

    #[test]
    fn all_four_frozen_terminal_shapes_emit_strict_unsigned_simulation_requests() {
        let cases = [
            PairForestTxV1CaseV2 {
                operation: PairForestTerminalOperationV2::PrivateTransfer,
                history_path: PairForestTerminalHistoryPathV2::SamePage,
            },
            PairForestTxV1CaseV2 {
                operation: PairForestTerminalOperationV2::PrivateTransfer,
                history_path: PairForestTerminalHistoryPathV2::Rollover,
            },
            PairForestTxV1CaseV2 {
                operation: PairForestTerminalOperationV2::Withdrawal,
                history_path: PairForestTerminalHistoryPathV2::SamePage,
            },
            PairForestTxV1CaseV2 {
                operation: PairForestTerminalOperationV2::Withdrawal,
                history_path: PairForestTerminalHistoryPathV2::Rollover,
            },
        ];
        for case in cases {
            let fee_payer = key(201);
            let preflight = build_pair_forest_tx_v1_simulation_preflight_v2(
                7,
                9,
                fee_payer,
                [202; 32],
                &instruction(case, fee_payer),
                case,
                &[key(203)],
            )
            .unwrap();
            assert_eq!(
                preflight.summary_v2().compute_unit_limit,
                V7_TX_V1_TERMINAL_COMPUTE_UNIT_LIMIT_V2
            );
            assert_eq!(
                preflight.summary_v2().serialized_transaction_bytes,
                case.expected_wire_bytes_v2()
            );
            assert!(preflight.summary_v2().placeholder_signatures_are_zero);
            let request: serde_json::Value =
                serde_json::from_slice(preflight.simulation_request_json_v2()).unwrap();
            assert_eq!(request["method"], "simulateTransaction");
            assert_eq!(request["params"][1]["sigVerify"], false);
            assert_eq!(request["params"][1]["replaceRecentBlockhash"], false);
            assert_eq!(request["params"][1]["commitment"], "finalized");
            assert_eq!(request["params"][1]["minContextSlot"], 9);
        }
    }

    #[test]
    fn malformed_shape_never_reaches_simulation_json() {
        let case = PairForestTxV1CaseV2 {
            operation: PairForestTerminalOperationV2::PrivateTransfer,
            history_path: PairForestTerminalHistoryPathV2::SamePage,
        };
        let fee_payer = key(201);
        let mut wrong_magic = instruction(case, fee_payer);
        wrong_magic.data[..4].copy_from_slice(b"ASF8");
        assert_eq!(
            build_pair_forest_tx_v1_simulation_preflight_v2(
                1,
                2,
                fee_payer,
                [202; 32],
                &wrong_magic,
                case,
                &[],
            ),
            Err(PairForestTxV1SimulationErrorV2::WrongInstructionData)
        );
    }

    #[test]
    fn marker_payer_and_system_program_metas_are_pinned() {
        let case = PairForestTxV1CaseV2 {
            operation: PairForestTerminalOperationV2::PrivateTransfer,
            history_path: PairForestTerminalHistoryPathV2::SamePage,
        };
        let fee_payer = key(201);
        let payer_index = case.marker_payer_index_v2();
        for mutation in 0..4 {
            let mut malformed = instruction(case, fee_payer);
            match mutation {
                0 => malformed.accounts[payer_index].is_signer = false,
                1 => malformed.accounts[payer_index].pubkey = key(204),
                2 => malformed.accounts[payer_index + 1].pubkey = key(205),
                3 => malformed.accounts[0].is_signer = true,
                _ => unreachable!(),
            }
            assert_eq!(
                build_pair_forest_tx_v1_simulation_preflight_v2(
                    1,
                    2,
                    fee_payer,
                    [202; 32],
                    &malformed,
                    case,
                    &[],
                ),
                Err(PairForestTxV1SimulationErrorV2::UnexpectedInstructionSigner)
            );
        }
    }
}

//! Production-inactive eight-lane wallet/indexer plumbing.
//!
//! This module is compiled only with `eight-lane-plumbing-v2`. It does not
//! change Pool accounts, proof bytes, verifier dispatch, or the legacy
//! single-tree wallet APIs. Its types make the proposed forest invariants
//! explicit before any production integration:
//!
//! - root-history pages are identified by `(lane_id, page_number)`;
//! - each lane has an independent tree cursor, frontier and root sequence;
//! - a private transfer appends one pair leaf, never one leaf per output;
//! - a checkpoint authenticates a complete, alias-free set of eight lanes;
//! - checkpoint failure and rollback operate atomically across all lanes.

use aspis_statement::{
    decode_digest_canonical, encode_digest_canonical,
    pool_v1::{
        pool_v1_tree_parent, root_history_location, PoolV1PairLeafErrorV1, PoolV1PairLeafWitnessV1,
        POOL_V1_TREE_DEPTH,
    },
};

use crate::{
    scan_state::DepositEventIdV1,
    witness_state::{WalletWitnessStateV1, WitnessAppendReceiptV1, WitnessStateErrorV1},
};

pub const POOL_V1_LANE_FOREST_VERSION_V2: u8 = 2;
pub const POOL_V1_LANE_COUNT_V2: usize = 8;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum LaneForestErrorV2 {
    InvalidLane,
    NonCanonicalDigest,
    WrongRoutedLane,
    IncompleteLaneSet,
    LaneAlias,
    PageNumberMismatch,
    PageAddressAlias,
    LegacyPageZeroCollision,
    LegacyPerOutputAppend,
    OutputEventMismatch,
    DuplicateAppend,
    CheckpointSequenceMismatch,
    CheckpointLaneSequenceMismatch,
    CheckpointLaneRootMismatch,
    CheckpointGlobalRootMismatch,
    CheckpointNoProgress,
    UnknownCheckpoint,
    InvalidPairLeaf(PoolV1PairLeafErrorV1),
    Witness(WitnessStateErrorV1),
}

impl From<WitnessStateErrorV1> for LaneForestErrorV2 {
    fn from(error: WitnessStateErrorV1) -> Self {
        Self::Witness(error)
    }
}

impl From<PoolV1PairLeafErrorV1> for LaneForestErrorV2 {
    fn from(error: PoolV1PairLeafErrorV1) -> Self {
        Self::InvalidPairLeaf(error)
    }
}

/// Validated forest lane. Raw `u8` values cannot silently alias modulo eight.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct LaneIdV2(u8);

impl LaneIdV2 {
    pub fn new(value: u8) -> Result<Self, LaneForestErrorV2> {
        if value >= POOL_V1_LANE_COUNT_V2 as u8 {
            return Err(LaneForestErrorV2::InvalidLane);
        }
        Ok(Self(value))
    }

    pub const fn as_u8(self) -> u8 {
        self.0
    }

    pub const fn index(self) -> usize {
        self.0 as usize
    }
}

fn routed_lane_from_canonical_digest_v2(encoded: [u8; 32]) -> Result<LaneIdV2, LaneForestErrorV2> {
    let digest =
        decode_digest_canonical(&encoded).map_err(|_| LaneForestErrorV2::NonCanonicalDigest)?;
    let canonical = encode_digest_canonical(&digest);
    LaneIdV2::new(canonical[0] & 7)
}

/// Deposit routing is the low three bits of the canonical commitment digest.
pub fn deposit_lane_from_commitment_v2(
    commitment: [u8; 32],
) -> Result<LaneIdV2, LaneForestErrorV2> {
    routed_lane_from_canonical_digest_v2(commitment)
}

/// Private-transfer output routing is the low three bits of the canonical
/// public nullifier digest. It is intentionally independent of the input lane.
pub fn private_transfer_output_lane_v2(nullifier: [u8; 32]) -> Result<LaneIdV2, LaneForestErrorV2> {
    routed_lane_from_canonical_digest_v2(nullifier)
}

/// Compute the exact three-level forest root using the frozen Pool tree
/// parent. This reuses the existing typed hash and introduces no new hash
/// construction.
pub fn lane_forest_global_root_v2(
    lane_roots: &[[u8; 32]; POOL_V1_LANE_COUNT_V2],
) -> Result<[u8; 32], LaneForestErrorV2> {
    let decoded = lane_roots
        .each_ref()
        .map(|root| {
            decode_digest_canonical(root).map_err(|_| LaneForestErrorV2::NonCanonicalDigest)
        })
        .into_iter()
        .collect::<Result<Vec<_>, _>>()?;
    let level_one = core::array::from_fn::<_, 4, _>(|index| {
        pool_v1_tree_parent(&decoded[2 * index], &decoded[2 * index + 1])
    });
    let level_two = [
        pool_v1_tree_parent(&level_one[0], &level_one[1]),
        pool_v1_tree_parent(&level_one[2], &level_one[3]),
    ];
    Ok(encode_digest_canonical(&pool_v1_tree_parent(
        &level_two[0],
        &level_two[1],
    )))
}

