            Self::Event(intent) => formatter.debug_tuple("Event").field(intent).finish(),
            Self::EmptyFinalizedBlock(empty) => formatter
                .debug_tuple("EmptyFinalizedBlock")
                .field(empty)
                .finish(),
        }
    }
}

