        .unwrap();
        let mut runtime = Runtime {
            simulation,
            signed,
            observations: VecDeque::from([
                RelayerSignatureObservationV1::NotFound(
                    RelayerNotFoundObservationV1::from_agreed_status_v1(
                        450,
                        [0xa3; 32],
