                DurableRelayerExecutionJournalV1::open_or_create_v1(&journal_path).unwrap();
            assert!(journal.record_v1(request_id).unwrap().outcome.is_none());
        }

        for expected_step in [
            RelayerExecutionStepV1::FinalOutcomeRecorded,
            RelayerExecutionStepV1::QueueCompleted,
            RelayerExecutionStepV1::AlreadyCompleted,
        ] {
            assert_eq!(
                advance_after_restart(
                    &queue_path,
                    &journal_path,
                    policy,
                    context,
                    request_id,
                    &startup,
                    &mut runtime,
                )
                .unwrap(),
                expected_step
            );
        }
        assert_eq!(runtime.submitted_wires, vec![signed_wire]);
        assert_eq!(runtime.signed_messages, vec![exact_unsigned_message]);

        let journal = DurableRelayerExecutionJournalV1::open_or_create_v1(&journal_path).unwrap();
        assert_eq!(
            journal.record_v1(request_id).unwrap().outcome,
            Some(RelayerExecutionOutcomeV1::FinalizedFailure(expected))
        );
    }
}

//! Fail-closed operator startup manifest and multi-provider agreement gate.
//!
//! This is deliberately pure: network transport, provider authentication and
//! multisig custody remain outside the crate. The caller supplies observations
//! from every pinned provider plus an authenticated manifest envelope. No
//! signer, relayer queue or indexer loop should start unless this exact gate
//! returns a receipt.

use sha2::{Digest as _, Sha256};

use crate::scan_state::FinalizedChainPointV1;

pub const OPERATOR_RELEASE_MANIFEST_DOMAIN_V1: &[u8] =
    b"aspis:pool-v1:operator-release-manifest:sha256:v1";
pub const OPERATOR_STARTUP_RECEIPT_DOMAIN_V1: &[u8] =
    b"aspis:pool-v1:operator-startup-receipt:sha256:v1";

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
