        assert_eq!(prepared.transition_kind, PoolV1TransitionKind::Withdrawal);
        assert_eq!(prepared.source_root_sequence, 7);
        assert_eq!(prepared.core_plan, account_keys[6]);
        assert_eq!(prepared.rollover_page, None);
