            ),
            Err(RelayerFinalizedEvidenceErrorV1::ZeroBlockRequestBinding)
        );
        assert_eq!(
            derive_relayer_finalized_evidence_v1(
                &plan,
                execution,
                &result,
                1,
                [0x71; 32],
                [0x72; 32],
                [0x73; 32],
                Some([0u8; 32]),
            ),
            Err(RelayerFinalizedEvidenceErrorV1::ZeroRootRequestBinding)
        );
