        core::array::from_fn(|index| M31(seed + 17 * index as u32))
    }

    #[test]
    fn execution_port_unix_signer_frame_round_trips_exact_validated_wire() {
        const STARTUP_SLOT: u64 = 90;
        const SIMULATION_SLOT: u64 = 101;
        const COMPUTE_UNIT_LIMIT: u32 = 1_400_000;
        const COMPUTE_UNIT_PRICE: u64 = 7;
        const RECENT_BLOCKHASH: [u8; 32] = [0x39u8; 32];

        let fee_payer = Keypair::new();
        let source_authority = Keypair::new();
        let program_id = key(11);
        let mint = key(12);
        let pool = pool_v1_state_address(&program_id, &mint).0;
        let vault = aspis_pool::pool_v1_vault_token_account_address(&program_id, &pool).0;
        let instruction = build_deposit_instruction_v1(
            program_id,
            pool,
            mint,
            7,
            key(13),
            source_authority.pubkey(),
            None,
            &DepositRequestV1 {
                owner_key: digest(10),
                amount: 77,
                salt: digest(20),
                encrypted_note_payload: &[],
            },
        )
        .unwrap();
        let snapshot = RelayerSnapshotV1 {
            pinned_program_id: program_id,
            registry_program: key(14),
            current_root_sequence: 7,
            observed_slot: STARTUP_SLOT,
            pool_state_sha256: [0x90u8; 32],
        };
        let plan =
            prepare_permissionless_relayer_plan_v1(snapshot, fee_payer.pubkey(), &instruction)
                .unwrap();
        let point = FinalizedChainPointV1::new(STARTUP_SLOT, [0x91u8; 32]).unwrap();
        let root = encode_digest_canonical(&digest(30));
        let startup = OperatorStartupReceiptV1::test_only_v1(
            [0x93u8; 32],
            [0x94u8; 32],
            FinalizedReleaseCheckpointV1 {
                point,
                pool_state_sha256: snapshot.pool_state_sha256,
                root_sequence: snapshot.current_root_sequence,
                root,
            },
        );
        let pre_simulation = assemble_exact_pre_simulation_relayer_transaction_v1(
            &plan,
            &startup,
            SIMULATION_SLOT,
            RECENT_BLOCKHASH,
            500,
            COMPUTE_UNIT_LIMIT,
            COMPUTE_UNIT_PRICE,
            &[],
        )
        .unwrap();
        let simulation = RelayerSimulationEvidenceV1 {
            simulated_at_slot: SIMULATION_SLOT,
            recent_blockhash: RECENT_BLOCKHASH,
            last_valid_block_height: 500,
            fee_payer: plan.fee_payer.to_bytes(),
            unsigned_message_sha256: *pre_simulation.exact_message().message_sha256(),
            simulation_result_sha256: [0xa1u8; 32],
            simulation_accounts_sha256: *pre_simulation
                .exact_message()
                .simulation_accounts_sha256(),
            startup_receipt_digest: *startup.receipt_digest(),
            compute_unit_limit: COMPUTE_UNIT_LIMIT,
            compute_unit_price_micro_lamports: COMPUTE_UNIT_PRICE,
            compute_units_consumed: 1_200_000,
            estimated_fee_lamports: 10_000,
        };
        let exact =
            assemble_exact_unsigned_relayer_message_v1(&plan, &startup, simulation, &[]).unwrap();

        let directory = TestDirectory::new();
        let socket_path = directory.0.join("port-signer.sock");
        let listener = UnixListener::bind(&socket_path).unwrap();
        fs::set_permissions(&socket_path, fs::Permissions::from_mode(0o600)).unwrap();
        let signer = UnixSocketRelayerSignerV1::new(&socket_path, Duration::from_secs(2)).unwrap();

        let expected_request_id = plan.request_id;
        let expected_startup = *startup.receipt_digest();
        let expected_fee_payer = plan.fee_payer.to_bytes();
        let expected_message = exact.serialized_message().to_vec();
        let expected_simulation_result = *simulation.simulation_result_sha256();
        let expected_accounts = *simulation.simulation_accounts_sha256();
        let server = thread::spawn(move || {
            let (mut stream, _) = listener.accept().unwrap();
            let mut length = [0u8; 4];
            stream.read_exact(&mut length).unwrap();
            let mut frame = vec![0u8; u32::from_le_bytes(length) as usize];
            stream.read_exact(&mut frame).unwrap();

            assert_eq!(
                frame.len(),
                REQUEST_FIXED_BODY_BYTES_V1 + expected_message.len() + 32
            );
            assert_eq!(frame[..4], REQUEST_MAGIC_V1);
            assert_eq!(frame[4], VERSION_V1);
            assert_eq!(frame[5..8], [0u8; 3]);
            assert_eq!(frame[8..40], expected_request_id);
            assert_eq!(frame[40..72], expected_startup);
            assert_eq!(frame[72..104], expected_fee_payer);
            assert_eq!(frame[104..112], SIMULATION_SLOT.to_le_bytes());
            assert_eq!(frame[112..144], RECENT_BLOCKHASH);
            assert_eq!(frame[144..152], 500u64.to_le_bytes());
            assert_eq!(
                &frame[152..184],
                Sha256::digest(&expected_message).as_slice()
            );
            assert_eq!(frame[184..216], expected_simulation_result);
            assert_eq!(frame[216..248], expected_accounts);
            assert_eq!(frame[248..252], COMPUTE_UNIT_LIMIT.to_le_bytes());
            assert_eq!(frame[252..260], COMPUTE_UNIT_PRICE.to_le_bytes());
            assert_eq!(frame[260..268], 1_200_000u64.to_le_bytes());
            assert_eq!(frame[268..276], 10_000u64.to_le_bytes());
            assert_eq!(
                frame[276..280],
                u32::try_from(expected_message.len()).unwrap().to_le_bytes()
            );
            assert_eq!(frame[280..280 + expected_message.len()], expected_message);
            let body_length = frame.len() - CHECKSUM_BYTES_V1;
            let request_digest = checksum_v1(REQUEST_CHECKSUM_DOMAIN_V1, &frame[..body_length]);
            assert_eq!(frame[body_length..], request_digest);

            let message: VersionedMessage = bincode::deserialize(&expected_message).unwrap();
            let transaction =
                VersionedTransaction::try_new(message, &[&fee_payer, &source_authority]).unwrap();
            let signed_wire = bincode::serialize(&transaction).unwrap();
            let response = response_v1(request_digest, &signed_wire);
            stream
                .write_all(&(response.len() as u32).to_le_bytes())
                .unwrap();
            stream.write_all(&response).unwrap();
            signed_wire
        });

        let identity = DepositScanIdentityV1::new(
            pool.to_bytes(),
            [0x92u8; 32],
            mint.to_bytes(),
            vault.to_bytes(),
            9,
        )
        .unwrap();
        let mut scan_state = ScanStateV1::new(identity, point, 7, root).unwrap();
        let binding = DepositRpcBindingV1::new(program_id.to_bytes()).unwrap();
        let viewing_secret = derive_viewing_keypair_v1(&[0x51u8; 32]).unwrap().0;
        let local_keys = NoLocalKeysV1;
        let mut port = ExactHttpsRelayerExecutionPortV1::test_only_with_rpc_v1(
            SignerOnlyRpcV1(*startup.receipt_digest()),
            NeverRequestIdsV1,
            signer,
            RelayerExecutionRpcPolicyV1::new(
                COMPUTE_UNIT_LIMIT,
                COMPUTE_UNIT_PRICE,
                20_000,
                Vec::new(),
            )
            .unwrap(),
            &mut scan_state,
            &binding,
            &viewing_secret,
            &local_keys,
        );
        let signed_wire = port
            .sign_exact_unsigned_message_v1(&plan, simulation, exact.serialized_message())
            .unwrap();
        let server_wire = server.join().unwrap();
        assert_eq!(signed_wire, server_wire);
        let validated = validate_exact_relayer_transaction_v1(
            &plan,
            &startup,
            simulation,
            &RelayerSignedTransactionArtifactV1 {
                signed_wire,
                lookup_tables: Vec::new(),
            },
        )
        .unwrap();
        assert_eq!(validated.inspected.fee_payer, expected_fee_payer);
        assert_eq!(validated.lookup_table_count, 0);
    }

    #[test]
    fn framed_private_socket_exchange_binds_request_digest() {
        let directory = TestDirectory::new();
        let socket_path = directory.0.join("signer.sock");
        let listener = UnixListener::bind(&socket_path).unwrap();
        fs::set_permissions(&socket_path, fs::Permissions::from_mode(0o600)).unwrap();
        let request_frame = vec![0x41; 128];
        let request_digest = [0x51; 32];
        let signed_wire = vec![0x61; 512];
        let expected_request = request_frame.clone();
        let expected_wire = signed_wire.clone();
        let server = thread::spawn(move || {
            let (mut stream, _) = listener.accept().unwrap();
            let mut length = [0u8; 4];
            stream.read_exact(&mut length).unwrap();
            let mut request = vec![0u8; u32::from_le_bytes(length) as usize];
            stream.read_exact(&mut request).unwrap();
            assert_eq!(request, expected_request);
            let response = response_v1(request_digest, &expected_wire);
            stream
                .write_all(&(response.len() as u32).to_le_bytes())
                .unwrap();
            stream.write_all(&response).unwrap();
        });
        assert_eq!(
            exchange_signer_frame_v1(
                &socket_path,
                Duration::from_secs(1),
                &request_frame,
                request_digest,
            )
            .unwrap(),
            signed_wire
        );
        server.join().unwrap();
    }

    #[test]
    fn response_digest_checksum_and_socket_permissions_fail_closed() {
        let digest = [0x71; 32];
        let mut response = response_v1(digest, &[0x81; 64]);
        assert_eq!(
            decode_signer_response_v1(&response, [0x72; 32]),
            Err(UnixRelayerSignerErrorV1::WrongRequestDigest)
        );
        *response.last_mut().unwrap() ^= 1;
        assert_eq!(
            decode_signer_response_v1(&response, digest),
            Err(UnixRelayerSignerErrorV1::ChecksumMismatch)
        );

        let directory = TestDirectory::new();
        let socket_path = directory.0.join("signer.sock");
        let _listener = UnixListener::bind(&socket_path).unwrap();
        fs::set_permissions(&socket_path, fs::Permissions::from_mode(0o666)).unwrap();
        assert_eq!(
            UnixSocketRelayerSignerV1::new(&socket_path, Duration::from_secs(1)).err(),
            Some(UnixRelayerSignerErrorV1::InsecureSocketPermissions)
        );
    }
}

crates/aspis-pool-wallet-v1/src/rpc_adap:
//! Strict adapter from resolved Solana RPC transaction data to the Pool V1
//! scanner.
//!
//! Solana return data is one transaction-global value owned by its most recent
//! setter. This adapter therefore accepts a deposit only when the pinned Pool
//! program occurs exactly once as a top-level instruction, that instruction is
//! last, its complete V1 wire is canonical, the transaction succeeded, and
//! the return-data owner is the same pinned program. RPC base58/base64 decoding,
//! account-key resolution and finalized commitment are explicit caller
//! boundaries; this module consumes their exact decoded bytes.

use aspis_pool::{pool_v1_state_address, pool_v1_vault_token_account_address};
use aspis_statement::{
    decode_digest_canonical,
    pool_v1::{pool_v1_note_commitment, DepositEventV1, POOL_V1_ENCRYPTED_NOTE_PAYLOAD_MAX_BYTES},
    poseidon2::Digest,
    VALUE_LIMIT,
};
use solana_program::pubkey::Pubkey;

use crate::{
    scan_state::{
        decode_deposit_event_record_v1, DepositEventIdV1, DepositEventRecordErrorV1,
        DepositScanIdentityV1, DepositScanOutcomeV1, FinalizedChainPointV1,
        FinalizedDepositRecordV1, LocalOwnerKeyStoreV1, ScanStateErrorV1, ScanStateV1,
    },
    ViewingSecretKeyV1,
};

pub const POOL_V1_DEPOSIT_INSTRUCTION_MAGIC: [u8; 4] = *b"ASDI";
pub const POOL_V1_DEPOSIT_INSTRUCTION_VERSION: u8 = 1;
pub const POOL_V1_DEPOSIT_INSTRUCTION_HEADER_BYTES: usize = 80;
pub const POOL_V1_DEPOSIT_INSTRUCTION_MAX_BYTES: usize =
    match POOL_V1_DEPOSIT_INSTRUCTION_HEADER_BYTES
        .checked_add(POOL_V1_ENCRYPTED_NOTE_PAYLOAD_MAX_BYTES)
    {
        Some(length) => length,
        None => panic!("Pool V1 deposit instruction size overflow"),
    };

const INSTRUCTION_OWNER_KEY_OFFSET: usize = 8;
const INSTRUCTION_AMOUNT_OFFSET: usize = 40;
const INSTRUCTION_SALT_OFFSET: usize = 48;
const INSTRUCTION_PAYLOAD_OFFSET: usize = POOL_V1_DEPOSIT_INSTRUCTION_HEADER_BYTES;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum DepositInstructionFormatErrorV1 {
    WrongLength,
    WrongMagic,
    WrongVersion,
    NonZeroReserved,
    InvalidAmount,
    InvalidPayloadLength,
    NonCanonicalDigest,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct DecodedDepositInstructionV1<'a> {
    pub owner_key: Digest,
    pub amount: u32,
    pub salt: Digest,
    pub encrypted_note_payload: &'a [u8],
}

/// Decode the exact instruction wire accepted by the Pool deposit transport.
/// The declared payload length must consume the complete byte slice.
pub fn decode_deposit_instruction_v1(
    bytes: &[u8],
) -> Result<DecodedDepositInstructionV1<'_>, DepositInstructionFormatErrorV1> {
    if bytes.len() < POOL_V1_DEPOSIT_INSTRUCTION_HEADER_BYTES
        || bytes.len() > POOL_V1_DEPOSIT_INSTRUCTION_MAX_BYTES
    {
        return Err(DepositInstructionFormatErrorV1::WrongLength);
    }
    if bytes[..4] != POOL_V1_DEPOSIT_INSTRUCTION_MAGIC {
        return Err(DepositInstructionFormatErrorV1::WrongMagic);
    }
    if bytes[4] != POOL_V1_DEPOSIT_INSTRUCTION_VERSION {
        return Err(DepositInstructionFormatErrorV1::WrongVersion);
    }
    if bytes[5] != 0 || bytes[44..48] != [0u8; 4] {
        return Err(DepositInstructionFormatErrorV1::NonZeroReserved);
    }

    let declared_payload_length = usize::from(u16::from_le_bytes(
        bytes[6..8]
            .try_into()
            .map_err(|_| DepositInstructionFormatErrorV1::WrongLength)?,
    ));
    if declared_payload_length > POOL_V1_ENCRYPTED_NOTE_PAYLOAD_MAX_BYTES {
        return Err(DepositInstructionFormatErrorV1::InvalidPayloadLength);
    }
    let expected_length = INSTRUCTION_PAYLOAD_OFFSET
        .checked_add(declared_payload_length)
        .ok_or(DepositInstructionFormatErrorV1::WrongLength)?;
    if bytes.len() != expected_length {
        return Err(DepositInstructionFormatErrorV1::WrongLength);
    }

    let owner_key_bytes: &[u8; 32] = bytes[INSTRUCTION_OWNER_KEY_OFFSET..INSTRUCTION_AMOUNT_OFFSET]
        .try_into()
        .map_err(|_| DepositInstructionFormatErrorV1::WrongLength)?;
    let salt_bytes: &[u8; 32] = bytes[INSTRUCTION_SALT_OFFSET..INSTRUCTION_PAYLOAD_OFFSET]
        .try_into()
        .map_err(|_| DepositInstructionFormatErrorV1::WrongLength)?;
    let owner_key = decode_digest_canonical(owner_key_bytes)
        .map_err(|_| DepositInstructionFormatErrorV1::NonCanonicalDigest)?;
    let salt = decode_digest_canonical(salt_bytes)
        .map_err(|_| DepositInstructionFormatErrorV1::NonCanonicalDigest)?;
    let amount = u32::from_le_bytes(
        bytes[INSTRUCTION_AMOUNT_OFFSET..44]
            .try_into()
            .map_err(|_| DepositInstructionFormatErrorV1::WrongLength)?,
    );
    if amount == 0 || amount >= VALUE_LIMIT {
        return Err(DepositInstructionFormatErrorV1::InvalidAmount);
    }

    Ok(DecodedDepositInstructionV1 {
        owner_key,
        amount,
        salt,
        encrypted_note_payload: &bytes[INSTRUCTION_PAYLOAD_OFFSET..],
    })
}

/// Deployment-specific trust root. There is deliberately no default program
/// id: the caller must pin the deployed Pool executable explicitly.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct DepositRpcBindingV1 {
    program_id: [u8; 32],
}

impl DepositRpcBindingV1 {
    pub fn new(program_id: [u8; 32]) -> Result<Self, DepositRpcAdapterErrorV1> {
        if program_id == [0u8; 32] {
            return Err(DepositRpcAdapterErrorV1::InvalidProgramBinding);
        }
        Ok(Self { program_id })
    }

    pub fn program_id(&self) -> &[u8; 32] {
        &self.program_id
    }
}

/// One top-level compiled instruction after every RPC account-key index has
/// been resolved. Retaining the ordered account keys lets non-returning Pool
/// instructions authenticate deterministic plan PDAs instead of trusting only
/// their instruction bytes.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct ResolvedRpcInstructionV1<'a> {
    pub program_id: [u8; 32],
    pub account_keys: &'a [[u8; 32]],
    pub data: &'a [u8],
}

/// Solana transaction `meta.returnData` after base64 decoding.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct ResolvedRpcReturnDataV1<'a> {
    pub program_id: [u8; 32],
    pub data: &'a [u8],
}

/// Minimal finalized transaction view required by the adapter. `succeeded`
/// must be derived from `meta.err == null`; a failed transaction is rejected
/// before any scan-state mutation even when RPC also reports return data.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct FinalizedRpcTransactionV1<'a> {
    pub point: FinalizedChainPointV1,
    pub transaction_signature: [u8; 64],
    pub succeeded: bool,
    pub top_level_instructions: &'a [ResolvedRpcInstructionV1<'a>],
    pub return_data: Option<ResolvedRpcReturnDataV1<'a>>,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum DepositRpcAdapterErrorV1 {
    InvalidProgramBinding,
    TransactionFailed,
    MissingTopLevelInstruction,
    DepositInstructionNotFinal,
    AdditionalPoolInstruction,
    WrongInstructionProgram,
    InstructionIndexOverflow,
    DepositInstruction(DepositInstructionFormatErrorV1),
    MissingReturnData,
    WrongReturnDataProgram,
    DepositRecord(DepositEventRecordErrorV1),
    ReceiptIdentityMismatch,
    InstructionEventMismatch,
    EventIdentity(ScanStateErrorV1),
    ScanState(ScanStateErrorV1),
}

fn event_matches_instruction_and_identity_v1(
    instruction: &DecodedDepositInstructionV1<'_>,
    event: &DepositEventV1<'_>,
    identity: &DepositScanIdentityV1,
) -> bool {
    if event.receipt.pool != *identity.pool()
        || event.receipt.asset_mint != *identity.asset_mint()
        || event.receipt.vault_token_account != *identity.vault_token_account()
    {
        return false;
    }
    let expected_commitment = pool_v1_note_commitment(
        &instruction.owner_key,
        instruction.amount,
        aspis_core::field::M31(identity.asset_id()),
        &instruction.salt,
    );
    event.receipt.amount == instruction.amount
        && event.receipt.note_commitment == expected_commitment
        && event.encrypted_note_payload == instruction.encrypted_note_payload
}

/// Authenticate a resolved, externally-finalized RPC transaction and return
/// the exact record/id accepted by [`ScanStateV1`]. This function is read-only.
pub fn authenticate_finalized_rpc_deposit_v1<'a>(
    binding: &DepositRpcBindingV1,
    identity: &DepositScanIdentityV1,
    transaction: &'a FinalizedRpcTransactionV1<'a>,
) -> Result<FinalizedDepositRecordV1<'a>, DepositRpcAdapterErrorV1> {
    if !transaction.succeeded {
        return Err(DepositRpcAdapterErrorV1::TransactionFailed);
    }
    let program_id = Pubkey::new_from_array(*binding.program_id());
    let mint = Pubkey::new_from_array(*identity.asset_mint());
    let expected_pool = pool_v1_state_address(&program_id, &mint).0;
    let expected_vault = pool_v1_vault_token_account_address(&program_id, &expected_pool).0;
    if expected_pool.to_bytes() != *identity.pool()
        || expected_vault.to_bytes() != *identity.vault_token_account()
    {
        return Err(DepositRpcAdapterErrorV1::ReceiptIdentityMismatch);
    }
    let final_index = transaction
        .top_level_instructions
        .len()
        .checked_sub(1)
        .ok_or(DepositRpcAdapterErrorV1::MissingTopLevelInstruction)?;
    let final_instruction = &transaction.top_level_instructions[final_index];
    if final_instruction.program_id != binding.program_id {
        return Err(
            if transaction
                .top_level_instructions
                .iter()
                .any(|instruction| instruction.program_id == binding.program_id)
            {
                DepositRpcAdapterErrorV1::DepositInstructionNotFinal
            } else {
                DepositRpcAdapterErrorV1::WrongInstructionProgram
            },
        );
    }
    if transaction.top_level_instructions[..final_index]
        .iter()
        .any(|instruction| instruction.program_id == binding.program_id)
    {
        return Err(DepositRpcAdapterErrorV1::AdditionalPoolInstruction);
    }
    let instruction_index = u16::try_from(final_index)
        .map_err(|_| DepositRpcAdapterErrorV1::InstructionIndexOverflow)?;
    let decoded_instruction = decode_deposit_instruction_v1(final_instruction.data)
        .map_err(DepositRpcAdapterErrorV1::DepositInstruction)?;

    let return_data = transaction
        .return_data
        .ok_or(DepositRpcAdapterErrorV1::MissingReturnData)?;
    if return_data.program_id != binding.program_id {
        return Err(DepositRpcAdapterErrorV1::WrongReturnDataProgram);
    }
    let event = decode_deposit_event_record_v1(return_data.data)
        .map_err(DepositRpcAdapterErrorV1::DepositRecord)?;
    if event.receipt.pool != *identity.pool()
        || event.receipt.asset_mint != *identity.asset_mint()
        || event.receipt.vault_token_account != *identity.vault_token_account()
    {
        return Err(DepositRpcAdapterErrorV1::ReceiptIdentityMismatch);
    }
    if !event_matches_instruction_and_identity_v1(&decoded_instruction, &event, identity) {
        return Err(DepositRpcAdapterErrorV1::InstructionEventMismatch);
    }

    let id = DepositEventIdV1::new(
        transaction.point,
        transaction.transaction_signature,
        instruction_index,
        0,
    )
    .map_err(DepositRpcAdapterErrorV1::EventIdentity)?;
    Ok(FinalizedDepositRecordV1::new(id, return_data.data))
}

/// Authenticate and ingest exactly one successful finalized RPC deposit. All
/// transport failures occur before the mutable scan-state ingestion call.
pub fn ingest_finalized_rpc_deposit_v1(
    state: &mut ScanStateV1,
    binding: &DepositRpcBindingV1,
    transaction: &FinalizedRpcTransactionV1<'_>,
    viewing_secret: &ViewingSecretKeyV1,
    local_keys: &impl LocalOwnerKeyStoreV1,
) -> Result<DepositScanOutcomeV1, DepositRpcAdapterErrorV1> {
    let observation =
        authenticate_finalized_rpc_deposit_v1(binding, state.identity(), transaction)?;
    state
        .ingest_finalized_deposit_v1(observation, viewing_secret, local_keys)
        .map_err(DepositRpcAdapterErrorV1::ScanState)
}

#[cfg(test)]
mod tests {
    use super::*;
    use aspis_core::field::M31;
    use aspis_statement::{
        encode_digest_canonical,
        pool_v1::{DepositEventV1, DepositReceiptV1},
        poseidon2::Digest,
    };

    use crate::{
        derive_viewing_keypair_v1,
        scan_state::{
            encode_deposit_event_record_v1, DepositScanIdentityV1, FinalizedBlockV1,
            LocalOwnerKeyStoreV1, ScanStateV1,
        },
    };

    const PROGRAM_ID: [u8; 32] = [0x99; 32];

    struct EmptyKeyStore;

    impl LocalOwnerKeyStoreV1 for EmptyKeyStore {
        fn contains_owner_key_v1(&self, _: &[u8; 32]) -> bool {
            false
        }
    }

    fn digest(seed: u32) -> Digest {
        core::array::from_fn(|index| M31(seed + 17 * index as u32))
    }

    fn digest_bytes(seed: u32) -> [u8; 32] {
        encode_digest_canonical(&digest(seed))
    }

    fn identity() -> DepositScanIdentityV1 {
        let program_id = Pubkey::new_from_array(PROGRAM_ID);
        let mint = Pubkey::new_from_array([0x33; 32]);
        let pool = pool_v1_state_address(&program_id, &mint).0;
        let vault = pool_v1_vault_token_account_address(&program_id, &pool).0;
        DepositScanIdentityV1::new(
            pool.to_bytes(),
            [0x22; 32],
            mint.to_bytes(),
            vault.to_bytes(),
            9,
        )
        .unwrap()
    }

    fn point(slot: u64, byte: u8) -> FinalizedChainPointV1 {
        FinalizedChainPointV1::new(slot, [byte; 32]).unwrap()
    }

    fn instruction_bytes(payload: &[u8]) -> Vec<u8> {
        let owner_key = digest(10);
        let salt = digest(100);
        let mut bytes = vec![0u8; POOL_V1_DEPOSIT_INSTRUCTION_HEADER_BYTES + payload.len()];
        bytes[..4].copy_from_slice(&POOL_V1_DEPOSIT_INSTRUCTION_MAGIC);
        bytes[4] = POOL_V1_DEPOSIT_INSTRUCTION_VERSION;
        bytes[6..8].copy_from_slice(&(payload.len() as u16).to_le_bytes());
        bytes[8..40].copy_from_slice(&encode_digest_canonical(&owner_key));
        bytes[40..44].copy_from_slice(&77u32.to_le_bytes());
        bytes[48..80].copy_from_slice(&encode_digest_canonical(&salt));
        bytes[80..].copy_from_slice(payload);
        bytes
    }

    fn return_record(payload: &[u8]) -> Vec<u8> {
        let receipt = DepositReceiptV1 {
            pool: *identity().pool(),
            asset_mint: *identity().asset_mint(),
            source_token_account: [0x55; 32],
            vault_token_account: *identity().vault_token_account(),
            amount: 77,
            encrypted_note_payload_bytes: payload.len() as u16,
            note_commitment: pool_v1_note_commitment(&digest(10), 77, M31(9), &digest(100)),
            leaf_index: 7,
            root_sequence: 8,
            root: digest(700),
        };
        encode_deposit_event_record_v1(&DepositEventV1 {
            receipt,
            encrypted_note_payload: payload,
        })
        .unwrap()
    }

    fn anchored_state() -> ScanStateV1 {
        ScanStateV1::new(identity(), point(100, 0xa0), 7, digest_bytes(600)).unwrap()
    }

    #[test]
    fn strict_rpc_binding_rejects_wrong_program_instruction_and_trailing_data() {
        let binding = DepositRpcBindingV1::new(PROGRAM_ID).unwrap();
        let payload = [0xaa, 0xbb, 0xcc];
        let instruction_data = instruction_bytes(&payload);
        let record = return_record(&payload);
        let block_point = point(101, 0xa1);

        let wrong_program = [ResolvedRpcInstructionV1 {
            program_id: [0x98; 32],
            account_keys: &[],
            data: &instruction_data,
        }];
        let transaction = FinalizedRpcTransactionV1 {
            point: block_point,
            transaction_signature: [0x77; 64],
            succeeded: true,
            top_level_instructions: &wrong_program,
            return_data: Some(ResolvedRpcReturnDataV1 {
                program_id: PROGRAM_ID,
                data: &record,
            }),
        };
        assert_eq!(
            authenticate_finalized_rpc_deposit_v1(&binding, &identity(), &transaction),
            Err(DepositRpcAdapterErrorV1::WrongInstructionProgram)
        );

        let mut wrong_version_data = instruction_data.clone();
        wrong_version_data[4] = 2;
        let wrong_version = [ResolvedRpcInstructionV1 {
            program_id: PROGRAM_ID,
            account_keys: &[],
            data: &wrong_version_data,
        }];
        let transaction = FinalizedRpcTransactionV1 {
            top_level_instructions: &wrong_version,
            ..transaction
        };
        assert_eq!(
            authenticate_finalized_rpc_deposit_v1(&binding, &identity(), &transaction),
            Err(DepositRpcAdapterErrorV1::DepositInstruction(
                DepositInstructionFormatErrorV1::WrongVersion
            ))
        );

        let mut trailing_instruction_data = instruction_data.clone();
        trailing_instruction_data.push(0);
        let trailing_instruction = [ResolvedRpcInstructionV1 {
            program_id: PROGRAM_ID,
            account_keys: &[],
            data: &trailing_instruction_data,
        }];
        let transaction = FinalizedRpcTransactionV1 {
            top_level_instructions: &trailing_instruction,
            ..transaction
        };
        assert_eq!(
            authenticate_finalized_rpc_deposit_v1(&binding, &identity(), &transaction),
            Err(DepositRpcAdapterErrorV1::DepositInstruction(
                DepositInstructionFormatErrorV1::WrongLength
            ))
        );

        let canonical_instruction = [ResolvedRpcInstructionV1 {
            program_id: PROGRAM_ID,
            account_keys: &[],
            data: &instruction_data,
        }];
        let transaction = FinalizedRpcTransactionV1 {
            top_level_instructions: &canonical_instruction,
            return_data: Some(ResolvedRpcReturnDataV1 {
                program_id: [0x98; 32],
                data: &record,
            }),
            ..transaction
        };
        assert_eq!(
            authenticate_finalized_rpc_deposit_v1(&binding, &identity(), &transaction),
            Err(DepositRpcAdapterErrorV1::WrongReturnDataProgram)
        );

        let mut trailing_record = record.clone();
        trailing_record.push(0);
        let transaction = FinalizedRpcTransactionV1 {
            top_level_instructions: &canonical_instruction,
            return_data: Some(ResolvedRpcReturnDataV1 {
                program_id: PROGRAM_ID,
                data: &trailing_record,
            }),
            ..transaction
        };
        assert!(matches!(
            authenticate_finalized_rpc_deposit_v1(&binding, &identity(), &transaction),
            Err(DepositRpcAdapterErrorV1::DepositRecord(_))
        ));
    }

    #[test]
    fn pool_deposit_must_be_the_only_pool_instruction_and_final() {
        let binding = DepositRpcBindingV1::new(PROGRAM_ID).unwrap();
        let payload = [0xaa];
        let instruction_data = instruction_bytes(&payload);
        let record = return_record(&payload);
        let other_instruction_data = [7u8];
        let non_final = [
            ResolvedRpcInstructionV1 {
                program_id: PROGRAM_ID,
                account_keys: &[],
                data: &instruction_data,
            },
            ResolvedRpcInstructionV1 {
                program_id: [0x88; 32],
                account_keys: &[],
                data: &other_instruction_data,
            },
        ];
        let transaction = FinalizedRpcTransactionV1 {
            point: point(101, 0xa1),
            transaction_signature: [0x77; 64],
            succeeded: true,
            top_level_instructions: &non_final,
            return_data: Some(ResolvedRpcReturnDataV1 {
                program_id: PROGRAM_ID,
                data: &record,
            }),
        };
        assert_eq!(
            authenticate_finalized_rpc_deposit_v1(&binding, &identity(), &transaction),
            Err(DepositRpcAdapterErrorV1::DepositInstructionNotFinal)
        );

        let repeated_pool = [
            ResolvedRpcInstructionV1 {
                program_id: PROGRAM_ID,
                account_keys: &[],
                data: &instruction_data,
            },
            ResolvedRpcInstructionV1 {
                program_id: PROGRAM_ID,
                account_keys: &[],
                data: &instruction_data,
            },
        ];
        let transaction = FinalizedRpcTransactionV1 {
            top_level_instructions: &repeated_pool,
            ..transaction
        };
        assert_eq!(
            authenticate_finalized_rpc_deposit_v1(&binding, &identity(), &transaction),
            Err(DepositRpcAdapterErrorV1::AdditionalPoolInstruction)
        );
    }

    #[test]
    fn failed_transaction_never_ingests_and_success_can_be_rolled_back_exactly() {
        let binding = DepositRpcBindingV1::new(PROGRAM_ID).unwrap();
        let payload = [0xaa, 0xbb, 0xcc];
        let instruction_data = instruction_bytes(&payload);
        let record = return_record(&payload);
        let instructions = [ResolvedRpcInstructionV1 {
            program_id: PROGRAM_ID,
            account_keys: &[],
            data: &instruction_data,
        }];
        let anchor_state = anchored_state();
        let anchor = anchor_state.anchor();
        let child = FinalizedBlockV1::new(point(101, 0xa1), anchor).unwrap();
        let mut state = anchor_state.clone();
        state.advance_finalized_block_v1(child).unwrap();
        let before_failed_transaction = state.clone();
        let (viewing_secret, _) = derive_viewing_keypair_v1(&[0x42; 32]).unwrap();
        let keys = EmptyKeyStore;
        let failed_transaction = FinalizedRpcTransactionV1 {
            point: child.point(),
            transaction_signature: [0x77; 64],
            succeeded: false,
            top_level_instructions: &instructions,
            return_data: Some(ResolvedRpcReturnDataV1 {
                program_id: PROGRAM_ID,
                data: &record,
            }),
        };

        assert_eq!(
            ingest_finalized_rpc_deposit_v1(
                &mut state,
                &binding,
                &failed_transaction,
                &viewing_secret,
                &keys,
            )
            .unwrap_err(),
            DepositRpcAdapterErrorV1::TransactionFailed
        );
        assert_eq!(state, before_failed_transaction);

        let successful_transaction = FinalizedRpcTransactionV1 {
            succeeded: true,
            ..failed_transaction
        };
        let outcome = ingest_finalized_rpc_deposit_v1(
            &mut state,
            &binding,
            &successful_transaction,
            &viewing_secret,
            &keys,
        )
        .unwrap();
        assert!(matches!(
            outcome,
            DepositScanOutcomeV1::InvalidEncryptedPayload(_)
        ));
        assert_eq!(state.next_leaf_index(), 8);
        assert_eq!(state.retained_event_count(), 1);

        let rollback = state.rollback_to_v1(anchor).unwrap();
        assert_eq!(rollback.removed_events.len(), 1);
        assert_eq!(rollback.removed_events[0].instruction_index(), 0);
        assert_eq!(rollback.removed_events[0].event_index(), 0);
        assert_eq!(state, anchor_state);
    }
}

crates/aspis-pool-wallet-v1/src/rpc_http:
//! Hardened exact-byte HTTPS transport for Pool V1 JSON-RPC.
//!
//! Typed request construction and response decoding remain in `rpc_json` and
//! `relayer_rpc_json`. This layer only binds one manifest provider identity to
//! one canonical HTTPS endpoint and returns bounded response bytes. It never
//! logs or exposes endpoint paths/query strings, follows redirects, retries a
//! write, accepts plaintext HTTP, or relies on ambient proxy configuration.

use std::{fmt, io::Read as _, time::Duration};

use reqwest::{
    blocking::Client,
    header::{ACCEPT, CONTENT_LENGTH, CONTENT_TYPE, USER_AGENT},
    redirect::Policy,
    retry, Url,
};
use sha2::{Digest as _, Sha256};

use crate::relayer_rpc_quorum::{ExactProviderRpcExchangeV1, ExactTwoProviderRelayerRpcV1};

pub const RPC_HTTPS_PROVIDER_ID_DOMAIN_V1: &[u8] = b"aspis:pool-v1:rpc-https-provider:sha256:v1";
pub const RPC_HTTPS_MAX_RESPONSE_BYTES_V1: usize = 64 * 1024 * 1024;
const RPC_HTTPS_USER_AGENT_V1: &str = "aspis-pool-v1-operator/1";

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum RpcHttpsTransportErrorV1 {
    InvalidEndpoint,
    ProviderIdMismatch,
    InvalidTimeout,
    EmptyRequest,
    InvalidResponseLimit,
    ClientConstruction,
    TransportFailure,
    HttpStatus(u16),
    InvalidContentType,
    ResponseTooLarge,
    EmptyResponse,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum RpcHttpsQuorumTransportErrorV1 {
    ProviderOrderMismatch,
    Provider {
        provider_index: u8,
        error: RpcHttpsTransportErrorV1,
    },
    WorkerPanicked {
        provider_index: u8,
    },
}

/// Derive the manifest provider identity from the exact normalized HTTPS URL.
/// This binds TLS authentication to the otherwise opaque provider ID consumed
/// by the two-provider quorum. URL credentials and fragments are forbidden;
/// path/query API tokens remain private because only this digest is exposed.
pub fn rpc_https_provider_id_v1(endpoint: &str) -> Result<[u8; 32], RpcHttpsTransportErrorV1> {
    let endpoint = canonical_https_endpoint_v1(endpoint)?;
    let mut hasher = Sha256::new();
    hasher.update(RPC_HTTPS_PROVIDER_ID_DOMAIN_V1);
    hasher.update(
        u32::try_from(endpoint.as_str().len())
            .map_err(|_| RpcHttpsTransportErrorV1::InvalidEndpoint)?
            .to_le_bytes(),
    );
    hasher.update(endpoint.as_str().as_bytes());
    Ok(hasher.finalize().into())
}

/// One exact provider endpoint pinned by the authenticated release manifest.
pub struct ExactHttpsRpcProviderV1 {
    provider_id: [u8; 32],
    endpoint: Url,
    client: Client,
}

impl fmt::Debug for ExactHttpsRpcProviderV1 {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter
            .debug_struct("ExactHttpsRpcProviderV1")
            .field("provider_id", &self.provider_id)
            .field("endpoint", &"<redacted>")
            .finish_non_exhaustive()
    }
}

impl ExactHttpsRpcProviderV1 {
    pub fn new(
        provider_id: [u8; 32],
        endpoint: &str,
        timeout: Duration,
    ) -> Result<Self, RpcHttpsTransportErrorV1> {
        if timeout.is_zero() || timeout > Duration::from_secs(120) {
            return Err(RpcHttpsTransportErrorV1::InvalidTimeout);
        }
        let endpoint = canonical_https_endpoint_v1(endpoint)?;
        if provider_id == [0u8; 32] || provider_id != rpc_https_provider_id_v1(endpoint.as_str())? {
            return Err(RpcHttpsTransportErrorV1::ProviderIdMismatch);
        }
        let connect_timeout = timeout.min(Duration::from_secs(15));
        let client = Client::builder()
            .https_only(true)
            .no_proxy()
            .redirect(Policy::none())
            .retry(retry::never())
            .connect_timeout(connect_timeout)
            .timeout(timeout)
            .build()
            .map_err(|_| RpcHttpsTransportErrorV1::ClientConstruction)?;
        Ok(Self {
            provider_id,
            endpoint,
            client,
        })
    }

    pub fn provider_id(&self) -> &[u8; 32] {
        &self.provider_id
    }

    /// Submit the exact caller-supplied JSON bytes once and return the exact
    /// bounded response bytes. Retry policy belongs above this method so a
    /// sendTransaction request is never silently replayed by the HTTP client.
    pub fn post_exact_json_v1(
        &self,
        request_json: &[u8],
        max_response_bytes: usize,
    ) -> Result<Vec<u8>, RpcHttpsTransportErrorV1> {
        if request_json.is_empty() {
            return Err(RpcHttpsTransportErrorV1::EmptyRequest);
        }
        if max_response_bytes == 0 || max_response_bytes > RPC_HTTPS_MAX_RESPONSE_BYTES_V1 {
            return Err(RpcHttpsTransportErrorV1::InvalidResponseLimit);
        }
        let response = self
            .client
            .post(self.endpoint.clone())
            .header(CONTENT_TYPE, "application/json")
            .header(ACCEPT, "application/json")
            .header(USER_AGENT, RPC_HTTPS_USER_AGENT_V1)
            .body(request_json.to_vec())
            .send()
            .map_err(|_| RpcHttpsTransportErrorV1::TransportFailure)?;
        let status = response.status();
        if !status.is_success() {
            return Err(RpcHttpsTransportErrorV1::HttpStatus(status.as_u16()));
        }
        if let Some(length) = response
            .headers()
            .get(CONTENT_LENGTH)
            .and_then(|value| value.to_str().ok())
            .and_then(|value| value.parse::<u64>().ok())
        {
            if length > max_response_bytes as u64 {
                return Err(RpcHttpsTransportErrorV1::ResponseTooLarge);
            }
        }
        let content_type = response
            .headers()
            .get(CONTENT_TYPE)
            .and_then(|value| value.to_str().ok())
            .ok_or(RpcHttpsTransportErrorV1::InvalidContentType)?;
        if !content_type
            .split(';')
            .next()
            .is_some_and(|value| value.trim().eq_ignore_ascii_case("application/json"))
        {
            return Err(RpcHttpsTransportErrorV1::InvalidContentType);
        }

        let maximum_read = u64::try_from(max_response_bytes)
            .map_err(|_| RpcHttpsTransportErrorV1::InvalidResponseLimit)?
            .saturating_add(1);
        let mut body = Vec::with_capacity(max_response_bytes.min(64 * 1024));
        response
            .take(maximum_read)
            .read_to_end(&mut body)
            .map_err(|_| RpcHttpsTransportErrorV1::TransportFailure)?;
        if body.len() > max_response_bytes {
            return Err(RpcHttpsTransportErrorV1::ResponseTooLarge);
        }
        if body.is_empty() {
            return Err(RpcHttpsTransportErrorV1::EmptyResponse);
        }
        Ok(body)
    }
}

/// Exact request/response bytes from the startup-pinned provider pair. The
/// request is retained inside the sealed result so callers cannot associate
/// either response with different bytes before invoking a quorum decoder.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ExactTwoProviderRpcResponsesV1 {
    provider_ids: [[u8; 32]; 2],
    request_json: Vec<u8>,
    response_json: [Vec<u8>; 2],
}

impl ExactTwoProviderRpcResponsesV1 {
    pub fn provider_ids(&self) -> &[[u8; 32]; 2] {
        &self.provider_ids
    }

    pub fn request_json(&self) -> &[u8] {
        &self.request_json
    }

    pub fn response_json(&self, provider_index: usize) -> Option<&[u8]> {
        self.response_json.get(provider_index).map(Vec::as_slice)
    }

    pub fn exchanges_v1(&self) -> [ExactProviderRpcExchangeV1<'_>; 2] {
        [
            ExactProviderRpcExchangeV1::new(
                self.provider_ids[0],
                &self.request_json,
                &self.response_json[0],
            ),
            ExactProviderRpcExchangeV1::new(
                self.provider_ids[1],
                &self.request_json,
                &self.response_json[1],
            ),
        ]
    }
}

/// Parallel exact-byte transport for the same canonical provider pair pinned
/// by `ExactTwoProviderRelayerRpcV1` at successful operator startup.
pub struct ExactTwoProviderHttpsTransportV1 {
    providers: [ExactHttpsRpcProviderV1; 2],
}

impl fmt::Debug for ExactTwoProviderHttpsTransportV1 {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter
            .debug_struct("ExactTwoProviderHttpsTransportV1")
            .field(
                "provider_ids",
                &[
                    *self.providers[0].provider_id(),
                    *self.providers[1].provider_id(),
                ],
            )
            .finish_non_exhaustive()
    }
}

impl ExactTwoProviderHttpsTransportV1 {
    pub fn new(
        providers: [ExactHttpsRpcProviderV1; 2],
        quorum: &ExactTwoProviderRelayerRpcV1,
    ) -> Result<Self, RpcHttpsQuorumTransportErrorV1> {
        if providers[0].provider_id() != &quorum.provider_ids()[0]
            || providers[1].provider_id() != &quorum.provider_ids()[1]
        {
            return Err(RpcHttpsQuorumTransportErrorV1::ProviderOrderMismatch);
        }
        Ok(Self { providers })
    }

    pub fn provider_ids(&self) -> [[u8; 32]; 2] {
        [
            *self.providers[0].provider_id(),
            *self.providers[1].provider_id(),
        ]
    }

    /// Submit one immutable request to both providers concurrently. There is
    /// no hidden retry; disagreement and retry scheduling remain explicit at
    /// the operator layer.
    pub fn post_both_exact_json_v1(
        &self,
        request_json: &[u8],
        max_response_bytes: usize,
    ) -> Result<ExactTwoProviderRpcResponsesV1, RpcHttpsQuorumTransportErrorV1> {
        let (first, second) = std::thread::scope(|scope| {
            let first = scope
                .spawn(|| self.providers[0].post_exact_json_v1(request_json, max_response_bytes));
            let second = scope
                .spawn(|| self.providers[1].post_exact_json_v1(request_json, max_response_bytes));
            (first.join(), second.join())
        });
        let first = first
            .map_err(|_| RpcHttpsQuorumTransportErrorV1::WorkerPanicked { provider_index: 0 })?
            .map_err(|error| RpcHttpsQuorumTransportErrorV1::Provider {
                provider_index: 0,
                error,
            })?;
        let second = second
            .map_err(|_| RpcHttpsQuorumTransportErrorV1::WorkerPanicked { provider_index: 1 })?
            .map_err(|error| RpcHttpsQuorumTransportErrorV1::Provider {
                provider_index: 1,
                error,
            })?;
        Ok(ExactTwoProviderRpcResponsesV1 {
            provider_ids: self.provider_ids(),
            request_json: request_json.to_vec(),
            response_json: [first, second],
        })
    }
}

fn canonical_https_endpoint_v1(endpoint: &str) -> Result<Url, RpcHttpsTransportErrorV1> {
    let endpoint = Url::parse(endpoint).map_err(|_| RpcHttpsTransportErrorV1::InvalidEndpoint)?;
    if endpoint.scheme() != "https"
        || endpoint.host_str().is_none()
        || !endpoint.username().is_empty()
        || endpoint.password().is_some()
        || endpoint.fragment().is_some()
        || endpoint.cannot_be_a_base()
    {
        return Err(RpcHttpsTransportErrorV1::InvalidEndpoint);
    }
    Ok(endpoint)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::{
        operator_startup::{
            provider_set_digest_v1, FinalizedReleaseCheckpointV1, OperatorStartupReceiptV1,
        },
        scan_state::FinalizedChainPointV1,
