impl DepositScanIdentityV1 {
    pub fn new(
        pool: [u8; 32],
        deployment_domain: [u8; 32],
        asset_mint: [u8; 32],
        vault_token_account: [u8; 32],
        asset_id: u32,
    ) -> Result<Self, ScanStateErrorV1> {
        if pool == [0u8; 32]
            || deployment_domain == [0u8; 32]
            || asset_mint == [0u8; 32]
            || vault_token_account == [0u8; 32]
            || asset_id >= P
        {
            return Err(ScanStateErrorV1::InvalidIdentity);
        }
        Ok(Self {
            pool,
            deployment_domain,
            asset_mint,
            vault_token_account,
            asset_id,
        })
    }

