    TerminalOrder,
    WrongProgram,
    MissingCiphertextCarrier,
    InvalidCiphertextCarrier,
    InvalidSignature,
    InvalidEventId,
    InvalidRootRequest,
    RootContextTooOld,
    MissingRootAccount,
    WrongRootOwner,
    WrongRootSpace,
    WrongRootPage,
    RootBindingMismatch,
    LengthOverflow,
}

