    #[test]
    fn default_is_disabled_and_production_success_is_exact_and_idempotent() {
        let prerequisites = prerequisites();
        assert_eq!(
            evaluate_wallet_v2_activation(&WalletV2ActivationMode::default(), &prerequisites),
            Err(WalletV2ActivationError::Disabled)
        );
        let mode = WalletV2ActivationMode::Production(config());
        let first = evaluate_wallet_v2_activation(&mode, &prerequisites).unwrap();
        let replay = evaluate_wallet_v2_activation(&mode, &prerequisites).unwrap();
        assert!(first.activation_digest_v2() != &[0u8; 32]);
        assert_eq!(first, replay);
        assert_eq!(first.wallet_id_v2(), &digest(1));
        assert_eq!(first.migration_id_v2(), &digest(3));
        assert_eq!(first.ownership_id_v2(), &digest(4));
        assert_eq!(first.migration_target_digest_v2(), &digest(5));
        assert_eq!(first.migration_target_path_digest_v2(), &digest(6));
    }

    #[derive(Clone, Copy, Debug)]
    enum FailureCase {
        SchemaMagic,
        SchemaVersion,
        ActivationVersion,
        WalletZero,
        WalletMismatch,
        CipherZero,
        CipherMismatch,
        MigrationZero,
        MigrationMismatch,
        MigrationUncommitted,
        OwnershipZero,
        OwnershipMismatch,
        OwnershipUncommitted,
        LegacyRoleMissing,
        LegacyRoleAmbiguous,
        PendingTransaction,
        MonotonicMissing,
        MonotonicZero,
        MonotonicMismatch,
        MonotonicAmbiguous,
        TargetPathZero,
        TargetPathMismatch,
        ProtectionZero,
        ProtectionMismatch,
        MonotonicQualificationMissing,
        MonotonicQualificationZero,
        MonotonicQualificationMismatch,
        MonotonicQualificationAmbiguous,
        StartupMissing,
        StartupZero,
        StartupMismatch,
        StartupAmbiguous,
        ProviderMissing,
        ProviderZero,
        ProviderMismatch,
        ProviderAmbiguous,
        FinalityMissing,
        FinalityZero,
        FinalityMismatch,
        FinalityAmbiguous,
    }

    const FAILURE_CASES: &[FailureCase] = &[
        FailureCase::SchemaMagic,
        FailureCase::SchemaVersion,
        FailureCase::ActivationVersion,
        FailureCase::WalletZero,
        FailureCase::WalletMismatch,
        FailureCase::CipherZero,
        FailureCase::CipherMismatch,
        FailureCase::MigrationZero,
        FailureCase::MigrationMismatch,
        FailureCase::MigrationUncommitted,
        FailureCase::OwnershipZero,
        FailureCase::OwnershipMismatch,
        FailureCase::OwnershipUncommitted,
        FailureCase::LegacyRoleMissing,
        FailureCase::LegacyRoleAmbiguous,
        FailureCase::PendingTransaction,
        FailureCase::MonotonicMissing,
        FailureCase::MonotonicZero,
        FailureCase::MonotonicMismatch,
        FailureCase::MonotonicAmbiguous,
        FailureCase::TargetPathZero,
        FailureCase::TargetPathMismatch,
        FailureCase::ProtectionZero,
        FailureCase::ProtectionMismatch,
        FailureCase::MonotonicQualificationMissing,
        FailureCase::MonotonicQualificationZero,
        FailureCase::MonotonicQualificationMismatch,
        FailureCase::MonotonicQualificationAmbiguous,
        FailureCase::StartupMissing,
        FailureCase::StartupZero,
        FailureCase::StartupMismatch,
        FailureCase::StartupAmbiguous,
        FailureCase::ProviderMissing,
        FailureCase::ProviderZero,
        FailureCase::ProviderMismatch,
        FailureCase::ProviderAmbiguous,
        FailureCase::FinalityMissing,
        FailureCase::FinalityZero,
        FailureCase::FinalityMismatch,
        FailureCase::FinalityAmbiguous,
    ];

    fn break_prerequisite(case: FailureCase, value: &mut WalletV2ActivationPrerequisites) {
        match case {
            FailureCase::SchemaMagic => value.asl2_magic = *b"BAD!",
            FailureCase::SchemaVersion => value.asl2_schema_version ^= 1,
            FailureCase::ActivationVersion => value.activation_schema_version ^= 1,
            FailureCase::WalletZero => value.wallet_id = [0u8; 32],
            FailureCase::WalletMismatch => value.wallet_id = digest(21),
            FailureCase::CipherZero => value.note_cipher_id = [0u8; 32],
            FailureCase::CipherMismatch => value.note_cipher_id = digest(22),
            FailureCase::MigrationZero => value.migration_id = [0u8; 32],
            FailureCase::MigrationMismatch => value.migration_id = digest(23),
            FailureCase::MigrationUncommitted => value.migration_committed = false,
            FailureCase::OwnershipZero => value.ownership_id = [0u8; 32],
            FailureCase::OwnershipMismatch => value.ownership_id = digest(24),
            FailureCase::OwnershipUncommitted => value.asl2_ownership_committed = false,
            FailureCase::LegacyRoleMissing => {
                value.retired_legacy_roles.pop();
            }
            FailureCase::LegacyRoleAmbiguous => value
                .retired_legacy_roles
                .push(LegacyWalletStoreRoleV2::WalletAndScanner),
            FailureCase::PendingTransaction => value.has_pending_transaction = true,
            FailureCase::MonotonicMissing => value.migration_target_digests.clear(),
            FailureCase::MonotonicZero => value.migration_target_digests[0] = [0u8; 32],
            FailureCase::MonotonicMismatch => value.migration_target_digests[0] = digest(25),
            FailureCase::MonotonicAmbiguous => {
                value.migration_target_digests.push(digest(26));
            }
            FailureCase::TargetPathZero => value.migration_target_path_digest = [0u8; 32],
            FailureCase::TargetPathMismatch => value.migration_target_path_digest = digest(36),
            FailureCase::ProtectionZero => value.monotonic_protection_id = [0u8; 32],
            FailureCase::ProtectionMismatch => value.monotonic_protection_id = digest(27),
            FailureCase::MonotonicQualificationMissing => {
                value.monotonic_store_qualifications.clear();
            }
            FailureCase::MonotonicQualificationZero => {
                value.monotonic_store_qualifications[0] = [0u8; 32];
            }
            FailureCase::MonotonicQualificationMismatch => {
                value.monotonic_store_qualifications[0] = digest(34);
            }
            FailureCase::MonotonicQualificationAmbiguous => {
                value.monotonic_store_qualifications.push(digest(35));
            }
            FailureCase::StartupMissing => value.qualified_startup_digests.clear(),
            FailureCase::StartupZero => value.qualified_startup_digests[0] = [0u8; 32],
            FailureCase::StartupMismatch => value.qualified_startup_digests[0] = digest(28),
            FailureCase::StartupAmbiguous => value.qualified_startup_digests.push(digest(29)),
            FailureCase::ProviderMissing => value.qualified_provider_digests.clear(),
            FailureCase::ProviderZero => value.qualified_provider_digests[0] = [0u8; 32],
            FailureCase::ProviderMismatch => value.qualified_provider_digests[0] = digest(30),
            FailureCase::ProviderAmbiguous => value.qualified_provider_digests.push(digest(31)),
            FailureCase::FinalityMissing => value.qualified_finality_digests.clear(),
            FailureCase::FinalityZero => value.qualified_finality_digests[0] = [0u8; 32],
            FailureCase::FinalityMismatch => value.qualified_finality_digests[0] = digest(32),
            FailureCase::FinalityAmbiguous => value.qualified_finality_digests.push(digest(33)),
        }
    }

    fn expected_error(case: FailureCase) -> WalletV2ActivationError {
        match case {
            FailureCase::SchemaMagic
            | FailureCase::SchemaVersion
            | FailureCase::ActivationVersion => WalletV2ActivationError::SchemaMismatch,
            FailureCase::WalletZero
            | FailureCase::WalletMismatch
            | FailureCase::CipherZero
            | FailureCase::CipherMismatch
            | FailureCase::MigrationZero
            | FailureCase::MigrationMismatch
            | FailureCase::OwnershipZero
            | FailureCase::OwnershipMismatch
            | FailureCase::ProtectionZero => WalletV2ActivationError::IdentityMismatch,
            FailureCase::MigrationUncommitted => WalletV2ActivationError::MigrationNotCommitted,
            FailureCase::OwnershipUncommitted => WalletV2ActivationError::OwnershipNotCommitted,
            FailureCase::LegacyRoleMissing | FailureCase::LegacyRoleAmbiguous => {
                WalletV2ActivationError::LegacyWriterNotRetired
            }
            FailureCase::PendingTransaction => WalletV2ActivationError::PendingTransaction,
            FailureCase::MonotonicMissing
            | FailureCase::MonotonicZero
            | FailureCase::MonotonicQualificationMissing
            | FailureCase::MonotonicQualificationZero
            | FailureCase::StartupMissing
            | FailureCase::StartupZero
            | FailureCase::ProviderMissing
            | FailureCase::ProviderZero
            | FailureCase::FinalityMissing
            | FailureCase::FinalityZero => WalletV2ActivationError::MissingPrerequisite,
            FailureCase::MonotonicAmbiguous
            | FailureCase::MonotonicQualificationAmbiguous
            | FailureCase::StartupAmbiguous
            | FailureCase::ProviderAmbiguous
            | FailureCase::FinalityAmbiguous => WalletV2ActivationError::AmbiguousPrerequisite,
            FailureCase::MonotonicMismatch
            | FailureCase::TargetPathZero
            | FailureCase::TargetPathMismatch
            | FailureCase::ProtectionMismatch => WalletV2ActivationError::MonotonicMismatch,
            FailureCase::MonotonicQualificationMismatch
            | FailureCase::StartupMismatch
            | FailureCase::ProviderMismatch
            | FailureCase::FinalityMismatch => WalletV2ActivationError::QualificationMismatch,
        }
    }

    #[test]
    fn every_runtime_prerequisite_independently_fails_closed() {
        let mode = WalletV2ActivationMode::Production(config());
        for case in FAILURE_CASES {
            let mut broken = prerequisites();
            break_prerequisite(*case, &mut broken);
            assert_eq!(
                evaluate_wallet_v2_activation(&mode, &broken),
                Err(expected_error(*case)),
                "wrong fail-closed outcome for case: {case:?}"
            );
        }
    }

    #[test]
    fn activation_accepts_only_asl2_schema_v3_and_remains_default_off() {
        assert_eq!(LANE_FOREST_WALLET_TXN_VERSION_V3, 3);
        let mut runtime = prerequisites();
        runtime.asl2_schema_version = 2;
        assert_eq!(
            evaluate_wallet_v2_activation(&WalletV2ActivationMode::default(), &runtime),
            Err(WalletV2ActivationError::Disabled)
        );
        assert_eq!(
            evaluate_wallet_v2_activation(&WalletV2ActivationMode::Production(config()), &runtime,),
            Err(WalletV2ActivationError::SchemaMismatch)
        );

        runtime.asl2_schema_version = LANE_FOREST_WALLET_TXN_VERSION_V3;
        assert!(evaluate_wallet_v2_activation(
            &WalletV2ActivationMode::Production(config()),
            &runtime,
        )
        .is_ok());
    }

    #[test]
    fn zero_configuration_bindings_are_rejected() {
        for index in 0..11 {
            let mut bindings = [
                digest(1),
                digest(2),
                digest(3),
                digest(4),
                digest(5),
                digest(6),
                digest(7),
                digest(8),
                digest(9),
                digest(10),
                digest(11),
            ];
            bindings[index] = [0u8; 32];
            assert_eq!(
                WalletV2ProductionConfig::new_v2(
                    bindings[0],
                    bindings[1],
                    bindings[2],
                    bindings[3],
                    bindings[4],
                    bindings[5],
                    bindings[6],
                    bindings[7],
                    bindings[8],
                    bindings[9],
                    bindings[10],
                ),
                Err(WalletV2ActivationError::InvalidConfiguration)
            );
        }
    }

    #[test]
    fn permit_copied_between_wallets_is_rejected() {
        let mode = WalletV2ActivationMode::Production(config());
        let permit = evaluate_wallet_v2_activation(&mode, &prerequisites()).unwrap();
        let mut other_wallet = prerequisites();
        other_wallet.wallet_id = digest(0x91);
        assert_eq!(
            evaluate_wallet_v2_activation(&mode, &other_wallet),
            Err(WalletV2ActivationError::IdentityMismatch)
        );
        assert_ne!(permit.wallet_id_v2(), &other_wallet.wallet_id);
        let other_mode = WalletV2ActivationMode::Production(
            WalletV2ProductionConfig::new_v2(
                digest(0x91),
                digest(2),
                digest(3),
                digest(4),
                digest(5),
                digest(6),
                digest(7),
                digest(8),
                digest(9),
                digest(10),
                digest(11),
            )
            .unwrap(),
        );
        assert!(!permit_matches_mode_configuration_v2(&other_mode, &permit));
    }
}

//! Permit-gated authoritative V2 wallet runtime.
//!
//! This is the only runtime facade which exposes scanner/finality mutations
//! after production activation. Startup reconstructs every prerequisite from
//! the live ASL2 image, ASMG/ASRT ownership receipt and monotonic service, then
//! compares a newly evaluated permit with the caller-supplied permit. It never
//! falls back to V1 after a requested V2 startup fails.

use crate::{
    durable_state::LocalSpendAuthenticatorV1,
    lane_forest_durable_v2::ForestFinalizedAppendEventV2,
    lane_forest_rpc_v2::{
        derive_finalized_pair_forest_terminal_intent_v2,
        derive_finalized_pair_forest_terminal_intent_with_carrier_notes_v2,
        FinalizedPairForestTerminalObservationV2, LaneForestRpcErrorV2,
    },
    lane_forest_wallet_txn_v2::{
        EmptyV1LaneForestWalletActivationV2, LaneForestWalletCheckpointBindingV2,
        LaneForestWalletCommittedStateV2, LaneForestWalletEmptyFinalizedBlockV2,
        LaneForestWalletNoteBindingV2, LaneForestWalletSpendBindingV2,
        LaneForestWalletTentativeCommitmentV2, LaneForestWalletTentativeUpdateV2,
        LaneForestWalletTxnCoordinatorV2, LaneForestWalletTxnErrorV2, LaneForestWalletTxnIntentV2,
        LaneForestWalletTxnPrepareV2, LaneForestWalletTxnRecoveryV2,
    },
    note_store_crypto::{LocalNullifierKeyStoreV1, NoteStoreCipherV1},
    relayer_execution_journal::DurableRelayerExecutionJournalV1,
    tx_v1_finalized_rpc_v2::{
        AgreedFinalizedTxV1BlockV2, AgreedFinalizedTxV1RootPageV2, FinalizedTxV1RpcErrorV2,
    },
    wallet_monotonic_v2::WalletMonotonicStoreV2,
    wallet_store_migration_v2::WalletStoreMigrationReceiptV2,
    wallet_v2_activation::{
        evaluate_wallet_v2_activation, permit_matches_mode_configuration_v2,
        WalletV2ActivationClass, WalletV2ActivationError, WalletV2ActivationMode,
        WalletV2ActivationPermit, WalletV2ActivationPrerequisites,
    },
};
use hpke::rand_core::CryptoRng;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum WalletV2RuntimeError {
    MissingPermit,
    PermitMismatch,
    AmbiguousRuntimeMode,
    RuntimePolicyMismatch,
    Activation(WalletV2ActivationError),
    Transaction(LaneForestWalletTxnErrorV2),
    FinalizedSource(LaneForestRpcErrorV2),
    FinalizedTxV1Source(FinalizedTxV1RpcErrorV2),
}

impl From<LaneForestRpcErrorV2> for WalletV2RuntimeError {
    fn from(error: LaneForestRpcErrorV2) -> Self {
        Self::FinalizedSource(error)
    }
}

impl From<FinalizedTxV1RpcErrorV2> for WalletV2RuntimeError {
    fn from(error: FinalizedTxV1RpcErrorV2) -> Self {
        Self::FinalizedTxV1Source(error)
    }
}

impl From<WalletV2ActivationError> for WalletV2RuntimeError {
    fn from(error: WalletV2ActivationError) -> Self {
        Self::Activation(error)
    }
}

impl From<LaneForestWalletTxnErrorV2> for WalletV2RuntimeError {
    fn from(error: LaneForestWalletTxnErrorV2) -> Self {
        Self::Transaction(error)
    }
}

/// Runtime-observed provider/finality identities. These values are rechecked
/// against the activation permit on every startup and relevant scanner call.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct WalletV2RuntimePolicyBindings {
    startup_receipt_digest: [u8; 32],
    provider_set_digest: [u8; 32],
    finality_policy_digest: [u8; 32],
    reference_service_digest: Option<[u8; 32]>,
}

impl WalletV2RuntimePolicyBindings {
    pub fn production_v2(
        startup_receipt_digest: [u8; 32],
        provider_set_digest: [u8; 32],
        finality_policy_digest: [u8; 32],
    ) -> Result<Self, WalletV2RuntimeError> {
        Self::new_v2(
            startup_receipt_digest,
            provider_set_digest,
            finality_policy_digest,
            None,
        )
    }

    #[cfg(feature = "wallet-v2-reference-tests")]
    pub fn reference_only_v2(
        startup_receipt_digest: [u8; 32],
        provider_set_digest: [u8; 32],
        finality_policy_digest: [u8; 32],
        reference_service_digest: [u8; 32],
    ) -> Result<Self, WalletV2RuntimeError> {
        Self::new_v2(
            startup_receipt_digest,
            provider_set_digest,
            finality_policy_digest,
            Some(reference_service_digest),
        )
    }

    fn new_v2(
        startup_receipt_digest: [u8; 32],
        provider_set_digest: [u8; 32],
        finality_policy_digest: [u8; 32],
        reference_service_digest: Option<[u8; 32]>,
    ) -> Result<Self, WalletV2RuntimeError> {
        if [
            startup_receipt_digest,
            provider_set_digest,
            finality_policy_digest,
        ]
        .contains(&[0u8; 32])
            || reference_service_digest == Some([0u8; 32])
        {
            return Err(WalletV2RuntimeError::RuntimePolicyMismatch);
        }
        Ok(Self {
            startup_receipt_digest,
            provider_set_digest,
            finality_policy_digest,
            reference_service_digest,
        })
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct WalletV2FinalizedApply {
    pub prepare: LaneForestWalletTxnPrepareV2,
    pub recovery: LaneForestWalletTxnRecoveryV2,
}

/// Live authoritative runtime. The coordinator is intentionally private, so a
/// caller that selected V2 cannot bypass permit and provider checks through
/// this handle.
pub struct ActivatedWalletRuntimeV2 {
    coordinator: LaneForestWalletTxnCoordinatorV2,
    permit: WalletV2ActivationPermit,
    policy: WalletV2RuntimePolicyBindings,
}

impl core::fmt::Debug for ActivatedWalletRuntimeV2 {
    fn fmt(&self, formatter: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        formatter
            .debug_struct("ActivatedWalletRuntimeV2")
            .field("activation", &"[REDACTED]")
            .finish()
    }
}

impl ActivatedWalletRuntimeV2 {
    /// Open and recover ASL2, reconstruct the activation predicate from live
    /// state, and consume an exact permit. `None`, disabled mode, copied
    /// permits and stale provider bindings all fail without scanner mutation.
    #[allow(clippy::too_many_arguments)]
    pub fn start_v2(
        path: impl AsRef<std::path::Path>,
        activation: EmptyV1LaneForestWalletActivationV2,
        cipher: &NoteStoreCipherV1,
        protection_id: [u8; 32],
        monotonic_store: Box<dyn WalletMonotonicStoreV2>,
        ownership: WalletStoreMigrationReceiptV2,
        mode: &WalletV2ActivationMode,
        supplied_permit: Option<&WalletV2ActivationPermit>,
        policy: WalletV2RuntimePolicyBindings,
    ) -> Result<Self, WalletV2RuntimeError> {
        let supplied_permit = supplied_permit.ok_or(WalletV2RuntimeError::MissingPermit)?;
        let requested_migration = activation
            .migration_genesis()
            .ok_or(WalletV2RuntimeError::PermitMismatch)?;
        if !permit_matches_mode_configuration_v2(mode, supplied_permit)
            || supplied_permit.wallet_id_v2() != activation.wallet_identity_sha256()
            || supplied_permit.note_cipher_id_v2() != &cipher.cipher_id()
            || supplied_permit.migration_id_v2() != requested_migration.migration_id()
            || supplied_permit.ownership_id_v2() != ownership.migration_id()
            || supplied_permit.migration_target_digest_v2() != ownership.target_digest()
            || supplied_permit.migration_target_path_digest_v2() != ownership.target_path_digest()
            || supplied_permit.monotonic_protection_id_v2() != &protection_id
            || supplied_permit.qualified_startup_digest_v2() != &policy.startup_receipt_digest
            || supplied_permit.qualified_provider_digest_v2() != &policy.provider_set_digest
            || supplied_permit.qualified_finality_digest_v2() != &policy.finality_policy_digest
        {
            return Err(WalletV2RuntimeError::PermitMismatch);
        }
        let mut coordinator = LaneForestWalletTxnCoordinatorV2::open_or_create_protected_v2(
            path,
            activation,
            cipher,
            protection_id,
            monotonic_store,
        )?;
        coordinator.recover_to_committed_v2()?;
        let stored_activation = coordinator.activation_v2()?;
        let stored_migration = stored_activation
            .migration_genesis()
            .ok_or(WalletV2RuntimeError::PermitMismatch)?;
        if supplied_permit.wallet_id_v2() != stored_activation.wallet_identity_sha256()
            || supplied_permit.note_cipher_id_v2() != &cipher.cipher_id()
            || supplied_permit.migration_id_v2() != stored_migration.migration_id()
        {
            return Err(WalletV2RuntimeError::PermitMismatch);
        }
        let prerequisites = match mode {
            WalletV2ActivationMode::Disabled => {
                return Err(WalletV2ActivationError::Disabled.into())
            }
            WalletV2ActivationMode::Production(_) => {
                if policy.reference_service_digest.is_some() {
                    return Err(WalletV2RuntimeError::AmbiguousRuntimeMode);
                }
                WalletV2ActivationPrerequisites::from_authoritative_state_v2(
                    &coordinator,
                    ownership,
                    vec![policy.startup_receipt_digest],
                    vec![policy.provider_set_digest],
                    vec![policy.finality_policy_digest],
                )?
            }
            #[cfg(feature = "wallet-v2-reference-tests")]
            WalletV2ActivationMode::ReferenceOnly(_) => {
                let reference = policy
                    .reference_service_digest
                    .ok_or(WalletV2RuntimeError::AmbiguousRuntimeMode)?;
                WalletV2ActivationPrerequisites::from_authoritative_state_reference_only_v2(
                    &coordinator,
                    ownership,
                    reference,
                    vec![policy.startup_receipt_digest],
                    vec![policy.provider_set_digest],
                    vec![policy.finality_policy_digest],
                )?
            }
        };
        let fresh_permit = evaluate_wallet_v2_activation(mode, &prerequisites)?;
        if &fresh_permit != supplied_permit {
            return Err(WalletV2RuntimeError::PermitMismatch);
        }
        let expected_class = match mode {
            WalletV2ActivationMode::Disabled => unreachable!("disabled returned above"),
            WalletV2ActivationMode::Production(_) => WalletV2ActivationClass::Production,
            #[cfg(feature = "wallet-v2-reference-tests")]
            WalletV2ActivationMode::ReferenceOnly(_) => WalletV2ActivationClass::ReferenceOnly,
        };
        if fresh_permit.activation_class_v2() != expected_class
            || fresh_permit.wallet_id_v2() != coordinator.activation_v2()?.wallet_identity_sha256()
            || fresh_permit.note_cipher_id_v2() != &cipher.cipher_id()
            || fresh_permit.monotonic_protection_id_v2() != &protection_id
            || fresh_permit.qualified_startup_digest_v2() != &policy.startup_receipt_digest
            || fresh_permit.qualified_provider_digest_v2() != &policy.provider_set_digest
            || fresh_permit.qualified_finality_digest_v2() != &policy.finality_policy_digest
        {
            return Err(WalletV2RuntimeError::PermitMismatch);
        }
        Ok(Self {
            coordinator,
            permit: fresh_permit,
            policy,
        })
    }

    pub fn committed_state_v2(
        &self,
    ) -> Result<&LaneForestWalletCommittedStateV2, WalletV2RuntimeError> {
        Ok(self.coordinator.committed_state()?)
    }

    pub fn apply_finalized_event_v2<A: LocalSpendAuthenticatorV1>(
        &mut self,
        intent: LaneForestWalletTxnIntentV2,
        cipher: &NoteStoreCipherV1,
        authenticator: &A,
    ) -> Result<WalletV2FinalizedApply, WalletV2RuntimeError> {
        if intent.note_cipher_id() != self.permit.note_cipher_id_v2()
            || intent
                .finalized_relayer_observation()
                .is_some_and(|observation| {
                    observation.provider_set_digest() != &self.policy.provider_set_digest
                })
        {
            return Err(WalletV2RuntimeError::RuntimePolicyMismatch);
        }
        let prepare = self
            .coordinator
            .prepare_finalized_v2(intent, cipher, authenticator)?;
        let recovery = self.coordinator.recover_to_committed_v2()?;
        Ok(WalletV2FinalizedApply { prepare, recovery })
    }

    /// Consume one exact finalized-success ASRJ record and commit its Pool
    /// event, note/spend updates and relayer correlation through the same
    /// authoritative ASL2 transaction.
    ///
    /// This is the production handoff for relayed transactions. Unknown,
    /// pending, terminal-failure, finalized-failure, wrong-signature,
    /// wrong-point and wrong-provider records fail before an ASL2 mutation.
    /// A crash after ASL2 preparation is recovered by normal runtime startup;
    /// retrying the same immutable ASRJ record is idempotent.
    pub fn apply_finalized_journal_event_v2<A: LocalSpendAuthenticatorV1>(
        &mut self,
        intent: LaneForestWalletTxnIntentV2,
        journal: &DurableRelayerExecutionJournalV1,
        request_id: [u8; 32],
        cipher: &NoteStoreCipherV1,
        authenticator: &A,
    ) -> Result<WalletV2FinalizedApply, WalletV2RuntimeError> {
        let intent = intent.bind_finalized_relayer_journal_v2(journal, request_id)?;
        self.apply_finalized_event_v2(intent, cipher, authenticator)
    }

    /// Compatibility/reference Pool V2 scanner-to-wallet handoff. It derives
    /// the event from an already authenticated observation, but its caller
    /// supplies note bindings. Production finalized TxV1 ingestion must use
    /// `apply_agreed_finalized_tx_v1_terminal_journal_v2`, which derives notes
    /// only from the signed and quorum-agreed carrier.
    #[allow(clippy::too_many_arguments)]
    pub fn apply_finalized_pool_terminal_journal_v2<A: LocalSpendAuthenticatorV1>(
        &mut self,
        observation: &FinalizedPairForestTerminalObservationV2,
        notes: Vec<LaneForestWalletNoteBindingV2>,
        spends: Vec<LaneForestWalletSpendBindingV2>,
        checkpoint: Option<LaneForestWalletCheckpointBindingV2>,
        journal: &DurableRelayerExecutionJournalV1,
        request_id: [u8; 32],
        cipher: &NoteStoreCipherV1,
        authenticator: &A,
    ) -> Result<WalletV2FinalizedApply, WalletV2RuntimeError> {
        let intent = derive_finalized_pair_forest_terminal_intent_v2(
            self.committed_state_v2()?,
            observation,
            notes,
            spends,
            checkpoint,
        )?;
        self.apply_finalized_journal_event_v2(intent, journal, request_id, cipher, authenticator)
    }

    /// Production-owned RPC path. Only a constructor-sealed, two-provider
    /// finalized TxV1 block plus its independently agreed exact root-history
    /// entry can enter the ASQ8/ASR8-derived terminal path. Exact transaction-array
    /// order is committed into ASL2 and survives restart; signature ordering
    /// is never used as a ledger-order surrogate.
    #[allow(clippy::too_many_arguments)]
    pub fn apply_agreed_finalized_tx_v1_terminal_journal_v2<
        A: LocalSpendAuthenticatorV1,
        K: LocalNullifierKeyStoreV1,
        R: CryptoRng,
    >(
        &mut self,
        block: &AgreedFinalizedTxV1BlockV2,
        terminal_index: usize,
        root_page: &AgreedFinalizedTxV1RootPageV2,
        rng: &mut R,
        viewing_secret: &crate::ViewingSecretKeyV1,
        local_keys: &K,
        spends: Vec<LaneForestWalletSpendBindingV2>,
        checkpoint: Option<LaneForestWalletCheckpointBindingV2>,
        journal: &DurableRelayerExecutionJournalV1,
        request_id: [u8; 32],
        cipher: &NoteStoreCipherV1,
        authenticator: &A,
    ) -> Result<WalletV2FinalizedApply, WalletV2RuntimeError> {
        if block.provider_set_digest_v2() != &self.policy.provider_set_digest
            || block.startup_receipt_digest_v2() != &self.policy.startup_receipt_digest
        {
            return Err(WalletV2RuntimeError::RuntimePolicyMismatch);
        }
        let point = block.block_v2().point();
        let previous_transaction_index = if self.committed_state_v2()?.finalized_head() == point {
            let (previous_point, previous_position) = self
                .coordinator
                .last_finalized_ledger_position_v2()?
                .ok_or(FinalizedTxV1RpcErrorV2::TerminalOrder)?;
            if previous_point != point {
                return Err(FinalizedTxV1RpcErrorV2::TerminalOrder.into());
            }
            Some(previous_position.transaction_index_v2())
        } else {
            None
        };
        block.validate_terminal_progress_v2(terminal_index, previous_transaction_index)?;
        let observation = block.terminal_observation_v2(terminal_index, root_page)?;
        let intent = derive_finalized_pair_forest_terminal_intent_with_carrier_notes_v2(
            rng,
            self.committed_state_v2()?,
            &observation,
            viewing_secret,
            local_keys,
            cipher,
            spends,
            checkpoint,
        )?;
        self.apply_finalized_journal_event_v2(intent, journal, request_id, cipher, authenticator)
    }

    pub fn apply_empty_finalized_block_v2(
        &mut self,
        empty: LaneForestWalletEmptyFinalizedBlockV2,
    ) -> Result<WalletV2FinalizedApply, WalletV2RuntimeError> {
        if empty.startup_receipt_sha256() != &self.policy.startup_receipt_digest
            || empty.provider_set_sha256() != &self.policy.provider_set_digest
        {
            return Err(WalletV2RuntimeError::RuntimePolicyMismatch);
        }
        let prepare = self.coordinator.prepare_empty_finalized_block_v2(empty)?;
        let recovery = self.coordinator.recover_to_committed_v2()?;
        Ok(WalletV2FinalizedApply { prepare, recovery })
    }

    pub fn observe_tentative_v2(
        &mut self,
        event: ForestFinalizedAppendEventV2,
        commitment: LaneForestWalletTentativeCommitmentV2,
        provider_set_digest: [u8; 32],
    ) -> Result<LaneForestWalletTentativeUpdateV2, WalletV2RuntimeError> {
        if provider_set_digest != self.policy.provider_set_digest {
            return Err(WalletV2RuntimeError::RuntimePolicyMismatch);
        }
        Ok(self
            .coordinator
            .observe_tentative_v2(event, commitment, provider_set_digest)?)
    }

    pub fn reorg_tentative_v2(
        &mut self,
        event: &ForestFinalizedAppendEventV2,
        reorg_evidence_sha256: [u8; 32],
        provider_set_digest: [u8; 32],
    ) -> Result<LaneForestWalletTentativeUpdateV2, WalletV2RuntimeError> {
        if provider_set_digest != self.policy.provider_set_digest {
            return Err(WalletV2RuntimeError::RuntimePolicyMismatch);
        }
        Ok(self.coordinator.reorg_tentative_v2(
            event,
            reorg_evidence_sha256,
            provider_set_digest,
        )?)
    }

    pub fn recover_v2(&mut self) -> Result<LaneForestWalletTxnRecoveryV2, WalletV2RuntimeError> {
        Ok(self.coordinator.recover_to_committed_v2()?)
    }

    /// Clean shutdown completes any ASL2 phase and requires exact agreement
    /// with the external commitment before releasing the process lock.
    pub fn shutdown_v2(mut self) -> Result<(), WalletV2RuntimeError> {
        self.coordinator.recover_to_committed_v2()?;
        self.coordinator
            .externally_anchored_monotonic_commitment_v2()?;
        Ok(())
    }
}

crates/aspis-pool-wallet-v1/src/witness_:
//! Exact append-only Merkle witness maintenance for locally owned Pool notes.
//!
//! For an existing leaf `i` and a newly appended leaf `n`, exactly one sibling
//! in `i`'s authentication path changes: the level of the most significant set
//! bit of `i XOR n`.  The replacement is the partially padded subtree root
//! carried by the canonical append algorithm immediately before that level.
//! This module applies that update, then recomputes every tracked path against
//! the externally authenticated resulting root before committing the state.

use aspis_core::field::M31;
use aspis_statement::{
    decode_digest_canonical, encode_digest_canonical,
    pool_v1::{
        pool_v1_empty_roots, pool_v1_tree_parent, IncrementalMerkleTreeV1, PoolV1TreeError,
        POOL_V1_DIGEST_ENCODING_VERSION, POOL_V1_LEAF_CAPACITY, POOL_V1_TREE_DEPTH,
        POOL_V1_TREE_HASH_VERSION, POOL_V1_TREE_STATE_ACCOUNT_BYTES,
    },
    Digest,
};
use sha2::{Digest as _, Sha256};

use crate::{finalized_indexer::FinalizedAppendEvidenceV1, scan_state::DepositEventIdV1};

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum WitnessStateErrorV1 {
    Tree(PoolV1TreeError),
    NonCanonicalDigest,
    LeafIndexMismatch,
    RootSequenceMismatch,
    RootMismatch,
    DuplicateWitness,
    WitnessNotFound,
    InvalidWitness,
    WrongImageLength,
    WrongImageMagic,
    WrongImageVersion,
    WrongImageParameters,
    NonZeroReserved,
    ChecksumMismatch,
    CountOverflow,
    NonCanonicalOrder,
    InvalidEventIdentity,
}

pub const WALLET_WITNESS_STATE_MAGIC_V1: [u8; 4] = *b"ASWS";
pub const WALLET_WITNESS_STATE_VERSION_V1: u8 = 1;
pub const WALLET_WITNESS_STATE_HEADER_BYTES_V1: usize = 64;
pub const WALLET_WITNESS_RECORD_BYTES_V1: usize = 108 + 8 + 32 + 32 * POOL_V1_TREE_DEPTH;
const WALLET_WITNESS_CHECKSUM_OFFSET_V1: usize = 32;
const MAX_WALLET_WITNESS_IMAGE_BYTES_V1: usize = 64 * 1024 * 1024;
const WALLET_WITNESS_CHECKSUM_DOMAIN_V1: &[u8] = b"aspis:pool-v1:wallet-witness-state:sha256:v1";

impl From<PoolV1TreeError> for WitnessStateErrorV1 {
    fn from(error: PoolV1TreeError) -> Self {
        Self::Tree(error)
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct TrackedMerkleWitnessV1 {
    event_id: DepositEventIdV1,
    leaf_index: u64,
    leaf: Digest,
    siblings: [Digest; POOL_V1_TREE_DEPTH],
}

impl TrackedMerkleWitnessV1 {
    pub fn event_id(&self) -> DepositEventIdV1 {
        self.event_id
    }

    pub fn leaf_index(&self) -> u64 {
        self.leaf_index
    }

    pub fn leaf(&self) -> &Digest {
        &self.leaf
    }

    pub fn siblings(&self) -> &[Digest; POOL_V1_TREE_DEPTH] {
        &self.siblings
    }

    pub fn root(&self) -> Digest {
        witness_root_v1(self.leaf_index, self.leaf, &self.siblings)
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct WitnessAppendReceiptV1 {
    pub leaf_index: u64,
    pub root_sequence: u64,
    pub root: [u8; 32],
    pub tracked_event_id: Option<DepositEventIdV1>,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct WalletWitnessStateV1 {
    tree: IncrementalMerkleTreeV1,
    tracked: Vec<TrackedMerkleWitnessV1>,
}

impl WalletWitnessStateV1 {
    pub fn empty() -> Self {
        Self {
            tree: IncrementalMerkleTreeV1::empty(),
            tracked: Vec::new(),
        }
    }

    /// Start from an authenticated Pool tree account.  The caller must first
    /// validate account owner/PDA/finality and supply the same current root
    /// from authenticated history.  This explicit equality also closes the
    /// otherwise-unreconstructible terminal-root case for a full tree.
    pub fn from_authenticated_tree_v1(
        tree: IncrementalMerkleTreeV1,
        authenticated_root_bytes: [u8; 32],
    ) -> Result<Self, WitnessStateErrorV1> {
        tree.validate()?;
        let authenticated_root = decode_digest_canonical(&authenticated_root_bytes)
            .map_err(|_| WitnessStateErrorV1::NonCanonicalDigest)?;
        if tree.root != authenticated_root {
            return Err(WitnessStateErrorV1::RootMismatch);
        }
        Ok(Self {
            tree,
            tracked: Vec::new(),
        })
    }

    pub fn tree(&self) -> &IncrementalMerkleTreeV1 {
        &self.tree
    }

    pub fn tracked(&self) -> &[TrackedMerkleWitnessV1] {
        &self.tracked
    }

    pub fn witness_v1(
        &self,
        event_id: DepositEventIdV1,
    ) -> Result<&TrackedMerkleWitnessV1, WitnessStateErrorV1> {
        self.tracked
            .iter()
            .find(|witness| witness.event_id == event_id)
            .ok_or(WitnessStateErrorV1::WitnessNotFound)
    }

    pub fn remove_witness_v1(
        &mut self,
        event_id: DepositEventIdV1,
    ) -> Result<TrackedMerkleWitnessV1, WitnessStateErrorV1> {
        let index = self
            .tracked
            .iter()
            .position(|witness| witness.event_id == event_id)
            .ok_or(WitnessStateErrorV1::WitnessNotFound)?;
        Ok(self.tracked.remove(index))
    }

    /// Import a path supplied by an untrusted indexer only after recomputing it
    /// to the exact authenticated current root.  This permits wallet recovery
    /// from a later tree snapshot without retaining every historical leaf.
    pub fn import_current_witness_v1(
        &mut self,
        event_id: DepositEventIdV1,
        leaf_index: u64,
        leaf_bytes: [u8; 32],
        sibling_bytes: [[u8; 32]; POOL_V1_TREE_DEPTH],
    ) -> Result<(), WitnessStateErrorV1> {
        if leaf_index >= self.tree.next_leaf_index {
            return Err(WitnessStateErrorV1::LeafIndexMismatch);
        }
        if self
            .tracked
            .iter()
            .any(|witness| witness.event_id == event_id || witness.leaf_index == leaf_index)
        {
            return Err(WitnessStateErrorV1::DuplicateWitness);
        }
        let leaf = decode_digest_canonical(&leaf_bytes)
            .map_err(|_| WitnessStateErrorV1::NonCanonicalDigest)?;
        let mut siblings = [[M31::ZERO; 8]; POOL_V1_TREE_DEPTH];
        for (output, encoded) in siblings.iter_mut().zip(sibling_bytes) {
            *output = decode_digest_canonical(&encoded)
                .map_err(|_| WitnessStateErrorV1::NonCanonicalDigest)?;
        }
        let witness = TrackedMerkleWitnessV1 {
            event_id,
            leaf_index,
            leaf,
            siblings,
        };
        if witness.root() != self.tree.root {
            return Err(WitnessStateErrorV1::InvalidWitness);
        }
        self.tracked.push(witness);
        Ok(())
    }

    /// Apply one finalized append and optionally begin tracking the new leaf.
    /// The supplied index/sequence/root come from the authenticated Pool
    /// instruction and root-history evidence.  All work happens on clones;
    /// any mismatch leaves both the frontier and every witness unchanged.
    pub fn append_authenticated_leaf_v1(
        &mut self,
        leaf_index: u64,
        root_sequence: u64,
        leaf_bytes: [u8; 32],
        root_bytes: [u8; 32],
        tracked_event_id: Option<DepositEventIdV1>,
    ) -> Result<WitnessAppendReceiptV1, WitnessStateErrorV1> {
        if leaf_index != self.tree.next_leaf_index {
            return Err(WitnessStateErrorV1::LeafIndexMismatch);
        }
        if leaf_index.checked_add(1) != Some(root_sequence) {
            return Err(WitnessStateErrorV1::RootSequenceMismatch);
        }
        if tracked_event_id.is_some_and(|event_id| {
            self.tracked
                .iter()
                .any(|witness| witness.event_id == event_id)
        }) {
            return Err(WitnessStateErrorV1::DuplicateWitness);
        }
        let leaf = decode_digest_canonical(&leaf_bytes)
            .map_err(|_| WitnessStateErrorV1::NonCanonicalDigest)?;
        let expected_root = decode_digest_canonical(&root_bytes)
            .map_err(|_| WitnessStateErrorV1::NonCanonicalDigest)?;
        let empty = pool_v1_empty_roots();
        let (partial, terminal) = append_partial_roots_v1(&self.tree, leaf, &empty)?;
        let (next_tree, append) = self.tree.append_one(leaf)?;
        if append.leaf_index != leaf_index
            || append.root_sequence != root_sequence
            || append.root != expected_root
            || next_tree.root != expected_root
            || terminal != expected_root
        {
            return Err(WitnessStateErrorV1::RootMismatch);
        }

        let mut tracked = self.tracked.clone();
        for witness in &mut tracked {
            let differing = witness.leaf_index ^ leaf_index;
            if differing == 0 {
                return Err(WitnessStateErrorV1::DuplicateWitness);
            }
            let level = (u64::BITS - 1 - differing.leading_zeros()) as usize;
            if level >= POOL_V1_TREE_DEPTH {
                return Err(WitnessStateErrorV1::InvalidWitness);
            }
            witness.siblings[level] = partial[level];
        }

        if let Some(event_id) = tracked_event_id {
            let siblings = core::array::from_fn(|level| {
                if (leaf_index >> level) & 1 == 0 {
                    empty[level]
                } else {
                    self.tree.frontier[level]
                }
            });
            tracked.push(TrackedMerkleWitnessV1 {
                event_id,
                leaf_index,
                leaf,
                siblings,
            });
        }
        if tracked
            .iter()
            .any(|witness| witness.root() != expected_root)
        {
            return Err(WitnessStateErrorV1::InvalidWitness);
        }
        self.tree = next_tree;
        self.tracked = tracked;
        Ok(WitnessAppendReceiptV1 {
            leaf_index,
            root_sequence,
            root: root_bytes,
            tracked_event_id,
        })
    }

    /// Apply the complete append stream returned by finalized ingestion.  The
    /// selection contains only locally owned event IDs; every unselected leaf
    /// is still applied because it changes later authentication paths.
    pub fn apply_finalized_appends_v1(
        &mut self,
        appends: &[FinalizedAppendEvidenceV1],
        track_event_ids: &[DepositEventIdV1],
    ) -> Result<Vec<WitnessAppendReceiptV1>, WitnessStateErrorV1> {
        let mut unique_appends = std::collections::HashSet::with_capacity(appends.len());
        if !appends
            .iter()
            .all(|append| unique_appends.insert(append.event_id))
        {
            return Err(WitnessStateErrorV1::DuplicateWitness);
        }
        let mut unique_tracks = std::collections::HashSet::with_capacity(track_event_ids.len());
        if !track_event_ids
            .iter()
            .all(|event_id| unique_tracks.insert(*event_id) && unique_appends.contains(event_id))
        {
            return Err(WitnessStateErrorV1::WitnessNotFound);
        }
        let mut working = self.clone();
        let mut receipts = Vec::with_capacity(appends.len());
        for append in appends {
            receipts.push(
                working.append_authenticated_leaf_v1(
                    append.leaf_index,
                    append.root_sequence,
                    append.note_commitment,
                    append.root,
                    unique_tracks
                        .contains(&append.event_id)
                        .then_some(append.event_id),
                )?,
            );
        }
        *self = working;
        Ok(receipts)
    }
}

fn append_partial_roots_v1(
    tree: &IncrementalMerkleTreeV1,
    leaf: Digest,
    empty: &[Digest; POOL_V1_TREE_DEPTH + 1],
) -> Result<([Digest; POOL_V1_TREE_DEPTH], Digest), WitnessStateErrorV1> {
    if tree.next_leaf_index >= POOL_V1_LEAF_CAPACITY {
        return Err(WitnessStateErrorV1::Tree(PoolV1TreeError::TreeFull));
    }
    let mut partial = [[M31::ZERO; 8]; POOL_V1_TREE_DEPTH];
    let mut current = leaf;
    for level in 0..POOL_V1_TREE_DEPTH {
        partial[level] = current;
        current = if (tree.next_leaf_index >> level) & 1 == 0 {
            pool_v1_tree_parent(&current, &empty[level])
        } else {
            pool_v1_tree_parent(&tree.frontier[level], &current)
        };
    }
    Ok((partial, current))
}

fn witness_root_v1(
    leaf_index: u64,
    leaf: Digest,
    siblings: &[Digest; POOL_V1_TREE_DEPTH],
) -> Digest {
    let mut current = leaf;
    for (level, sibling) in siblings.iter().enumerate() {
        current = if (leaf_index >> level) & 1 == 0 {
            pool_v1_tree_parent(&current, sibling)
        } else {
            pool_v1_tree_parent(sibling, &current)
        };
    }
    current
}

/// Canonical fixed-record image for the authenticated frontier and every
/// locally tracked path. Records are sorted by leaf index, then event ID, so
/// logically identical state has one byte representation.
pub fn encode_wallet_witness_state_v1(
    state: &WalletWitnessStateV1,
) -> Result<Vec<u8>, WitnessStateErrorV1> {
    state.tree.validate()?;
    let count = state.tracked.len();
    let records_bytes = count
        .checked_mul(WALLET_WITNESS_RECORD_BYTES_V1)
        .ok_or(WitnessStateErrorV1::CountOverflow)?;
    let length = WALLET_WITNESS_STATE_HEADER_BYTES_V1
        .checked_add(POOL_V1_TREE_STATE_ACCOUNT_BYTES)
        .and_then(|value| value.checked_add(records_bytes))
        .ok_or(WitnessStateErrorV1::CountOverflow)?;
    if length > MAX_WALLET_WITNESS_IMAGE_BYTES_V1 {
        return Err(WitnessStateErrorV1::CountOverflow);
    }
    let count = u32::try_from(count).map_err(|_| WitnessStateErrorV1::CountOverflow)?;
    let mut ordered: Vec<_> = state.tracked.iter().collect();
    ordered.sort_by_key(|witness| (witness.leaf_index, encode_event_id_v1(witness.event_id)));
    if ordered.windows(2).any(|pair| {
        pair[0].leaf_index == pair[1].leaf_index || pair[0].event_id == pair[1].event_id
    }) {
        return Err(WitnessStateErrorV1::DuplicateWitness);
    }

    let mut output = vec![0u8; length];
    output[..4].copy_from_slice(&WALLET_WITNESS_STATE_MAGIC_V1);
    output[4] = WALLET_WITNESS_STATE_VERSION_V1;
    output[5] = POOL_V1_TREE_DEPTH as u8;
    output[6] = POOL_V1_TREE_HASH_VERSION;
    output[7] = POOL_V1_DIGEST_ENCODING_VERSION;
    output[8..12].copy_from_slice(&count.to_le_bytes());
    output[12..16].copy_from_slice(
        &u32::try_from(WALLET_WITNESS_RECORD_BYTES_V1)
            .map_err(|_| WitnessStateErrorV1::CountOverflow)?
            .to_le_bytes(),
    );
    output[16..20].copy_from_slice(
        &u32::try_from(POOL_V1_TREE_STATE_ACCOUNT_BYTES)
            .map_err(|_| WitnessStateErrorV1::CountOverflow)?
            .to_le_bytes(),
    );
    let tree = state.tree.encode()?;
    let tree_start = WALLET_WITNESS_STATE_HEADER_BYTES_V1;
    output[tree_start..tree_start + tree.len()].copy_from_slice(&tree);
    let mut offset = tree_start + tree.len();
    for witness in ordered {
        let record = &mut output[offset..offset + WALLET_WITNESS_RECORD_BYTES_V1];
        record[..108].copy_from_slice(&encode_event_id_v1(witness.event_id));
        record[108..116].copy_from_slice(&witness.leaf_index.to_le_bytes());
        record[116..148].copy_from_slice(&encode_digest_canonical(&witness.leaf));
        for (level, sibling) in witness.siblings.iter().enumerate() {
            let start = 148 + 32 * level;
            record[start..start + 32].copy_from_slice(&encode_digest_canonical(sibling));
        }
        offset += WALLET_WITNESS_RECORD_BYTES_V1;
    }
    let checksum = wallet_witness_checksum_v1(&output)?;
    output[WALLET_WITNESS_CHECKSUM_OFFSET_V1..WALLET_WITNESS_CHECKSUM_OFFSET_V1 + 32]
        .copy_from_slice(&checksum);
    Ok(output)
}

pub fn decode_wallet_witness_state_v1(
    bytes: &[u8],
) -> Result<WalletWitnessStateV1, WitnessStateErrorV1> {
    if bytes.len() < WALLET_WITNESS_STATE_HEADER_BYTES_V1 + POOL_V1_TREE_STATE_ACCOUNT_BYTES
        || bytes.len() > MAX_WALLET_WITNESS_IMAGE_BYTES_V1
    {
        return Err(WitnessStateErrorV1::WrongImageLength);
    }
    if bytes[..4] != WALLET_WITNESS_STATE_MAGIC_V1 {
        return Err(WitnessStateErrorV1::WrongImageMagic);
    }
    if bytes[4] != WALLET_WITNESS_STATE_VERSION_V1 {
        return Err(WitnessStateErrorV1::WrongImageVersion);
    }
    if bytes[5] != POOL_V1_TREE_DEPTH as u8
        || bytes[6] != POOL_V1_TREE_HASH_VERSION
        || bytes[7] != POOL_V1_DIGEST_ENCODING_VERSION
        || u32::from_le_bytes(bytes[12..16].try_into().unwrap()) as usize
            != WALLET_WITNESS_RECORD_BYTES_V1
        || u32::from_le_bytes(bytes[16..20].try_into().unwrap()) as usize
            != POOL_V1_TREE_STATE_ACCOUNT_BYTES
    {
        return Err(WitnessStateErrorV1::WrongImageParameters);
    }
    if bytes[20..32].iter().any(|byte| *byte != 0) {
        return Err(WitnessStateErrorV1::NonZeroReserved);
    }
    let encoded_checksum: [u8; 32] = bytes[32..64].try_into().unwrap();
    if encoded_checksum != wallet_witness_checksum_v1(bytes)? {
        return Err(WitnessStateErrorV1::ChecksumMismatch);
    }
    let count = u32::from_le_bytes(bytes[8..12].try_into().unwrap()) as usize;
    let expected_length = WALLET_WITNESS_STATE_HEADER_BYTES_V1
        .checked_add(POOL_V1_TREE_STATE_ACCOUNT_BYTES)
        .and_then(|value| {
            count
                .checked_mul(WALLET_WITNESS_RECORD_BYTES_V1)
                .and_then(|records| value.checked_add(records))
        })
        .ok_or(WitnessStateErrorV1::CountOverflow)?;
    if expected_length != bytes.len() {
        return Err(WitnessStateErrorV1::WrongImageLength);
    }
    let tree_start = WALLET_WITNESS_STATE_HEADER_BYTES_V1;
    let tree_end = tree_start + POOL_V1_TREE_STATE_ACCOUNT_BYTES;
    let tree = IncrementalMerkleTreeV1::decode(&bytes[tree_start..tree_end])?;
    let mut state = WalletWitnessStateV1::from_authenticated_tree_v1(
        tree,
        encode_digest_canonical(&tree.root),
    )?;
    let mut previous_key = None;
    let mut offset = tree_end;
    for _ in 0..count {
        let record = &bytes[offset..offset + WALLET_WITNESS_RECORD_BYTES_V1];
        let encoded_event: [u8; 108] = record[..108].try_into().unwrap();
        let event_id = decode_event_id_v1(&encoded_event)?;
        let leaf_index = u64::from_le_bytes(record[108..116].try_into().unwrap());
        let key = (leaf_index, encoded_event);
        if previous_key.is_some_and(|previous| previous >= key) {
            return Err(WitnessStateErrorV1::NonCanonicalOrder);
        }
        previous_key = Some(key);
        let leaf: [u8; 32] = record[116..148].try_into().unwrap();
        let mut siblings = [[0u8; 32]; POOL_V1_TREE_DEPTH];
        for (level, sibling) in siblings.iter_mut().enumerate() {
            let start = 148 + 32 * level;
            *sibling = record[start..start + 32].try_into().unwrap();
        }
        state.import_current_witness_v1(event_id, leaf_index, leaf, siblings)?;
        offset += WALLET_WITNESS_RECORD_BYTES_V1;
    }
    Ok(state)
}

fn wallet_witness_checksum_v1(bytes: &[u8]) -> Result<[u8; 32], WitnessStateErrorV1> {
    if bytes.len() < WALLET_WITNESS_STATE_HEADER_BYTES_V1 {
        return Err(WitnessStateErrorV1::WrongImageLength);
    }
    let length = u64::try_from(bytes.len()).map_err(|_| WitnessStateErrorV1::CountOverflow)?;
    let mut hasher = Sha256::new();
    hasher.update(WALLET_WITNESS_CHECKSUM_DOMAIN_V1);
    hasher.update(length.to_le_bytes());
    hasher.update(&bytes[..WALLET_WITNESS_CHECKSUM_OFFSET_V1]);
    hasher.update([0u8; 32]);
    hasher.update(&bytes[WALLET_WITNESS_CHECKSUM_OFFSET_V1 + 32..]);
    Ok(hasher.finalize().into())
}

fn encode_event_id_v1(event_id: DepositEventIdV1) -> [u8; 108] {
    let mut bytes = [0u8; 108];
    bytes[..8].copy_from_slice(&event_id.point().slot().to_le_bytes());
    bytes[8..40].copy_from_slice(event_id.point().block_hash());
    bytes[40..104].copy_from_slice(event_id.transaction_signature());
    bytes[104..106].copy_from_slice(&event_id.instruction_index().to_le_bytes());
    bytes[106..108].copy_from_slice(&event_id.event_index().to_le_bytes());
    bytes
}

fn decode_event_id_v1(bytes: &[u8; 108]) -> Result<DepositEventIdV1, WitnessStateErrorV1> {
    let point = crate::scan_state::FinalizedChainPointV1::new(
        u64::from_le_bytes(bytes[..8].try_into().unwrap()),
        bytes[8..40].try_into().unwrap(),
    )
    .map_err(|_| WitnessStateErrorV1::InvalidEventIdentity)?;
    DepositEventIdV1::new(
        point,
        bytes[40..104].try_into().unwrap(),
        u16::from_le_bytes(bytes[104..106].try_into().unwrap()),
        u16::from_le_bytes(bytes[106..108].try_into().unwrap()),
    )
    .map_err(|_| WitnessStateErrorV1::InvalidEventIdentity)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::scan_state::FinalizedChainPointV1;
    use aspis_core::field::P;

    fn digest(seed: u32) -> Digest {
        core::array::from_fn(|index| M31((seed + 101 * index as u32) % P))
    }

    fn event(index: u64) -> DepositEventIdV1 {
        DepositEventIdV1::new(
            FinalizedChainPointV1::new(index + 1, [(index as u8).wrapping_add(1); 32]).unwrap(),
            [(index as u8).wrapping_add(2); 64],
            0,
            0,
        )
        .unwrap()
    }

    fn reference_prefix_root(leaves: &[Digest]) -> Digest {
        let empty = pool_v1_empty_roots();
        let mut nodes = leaves.to_vec();
        if nodes.is_empty() {
            return empty[POOL_V1_TREE_DEPTH];
        }
        for level in 0..POOL_V1_TREE_DEPTH {
            if nodes.len() & 1 == 1 {
                nodes.push(empty[level]);
            }
            nodes = nodes
                .chunks_exact(2)
                .map(|pair| pool_v1_tree_parent(&pair[0], &pair[1]))
                .collect();
        }
        assert_eq!(nodes.len(), 1);
        nodes[0]
    }

    #[test]
    fn tracked_paths_follow_every_append_and_match_independent_roots() {
        let mut state = WalletWitnessStateV1::empty();
        let mut leaves = Vec::new();
        let tracked_indices = [0u64, 1, 2, 5, 31, 32, 63];
        for index in 0..64u64 {
            let leaf = digest(index as u32 + 1);
            leaves.push(leaf);
            let root = reference_prefix_root(&leaves);
            state
                .append_authenticated_leaf_v1(
                    index,
                    index + 1,
                    encode_digest_canonical(&leaf),
                    encode_digest_canonical(&root),
                    tracked_indices.contains(&index).then(|| event(index)),
                )
                .unwrap();
            assert_eq!(state.tree().root, root);
            assert!(state.tracked().iter().all(|witness| witness.root() == root));
        }
        assert_eq!(state.tracked().len(), tracked_indices.len());
        for index in tracked_indices {
            let witness = state.witness_v1(event(index)).unwrap();
            assert_eq!(witness.leaf_index(), index);
            assert_eq!(witness.leaf(), &leaves[index as usize]);
        }
    }

    #[test]
    fn finalized_append_stream_tracks_selected_notes_and_is_atomic() {
        let leaves: Vec<_> = (0..4).map(|index| digest(index + 1)).collect();
        let mut appends = Vec::new();
        for index in 0..leaves.len() {
            appends.push(FinalizedAppendEvidenceV1 {
                event_id: event(index as u64),
                leaf_index: index as u64,
                root_sequence: index as u64 + 1,
                note_commitment: encode_digest_canonical(&leaves[index]),
                root: encode_digest_canonical(&reference_prefix_root(&leaves[..=index])),
            });
        }

        let mut state = WalletWitnessStateV1::empty();
        let receipts = state
            .apply_finalized_appends_v1(&appends, &[event(1), event(3)])
            .unwrap();
        assert_eq!(receipts.len(), appends.len());
        assert_eq!(state.tracked().len(), 2);
        assert!(state
            .tracked()
            .iter()
            .all(|witness| witness.root() == state.tree().root));

        let before = state.clone();
        let mut bad = appends[3];
        bad.leaf_index = 4;
        assert_eq!(
            state.apply_finalized_appends_v1(&[bad], &[]),
            Err(WitnessStateErrorV1::RootSequenceMismatch)
        );
        assert_eq!(state, before);
    }

    #[test]
    fn canonical_witness_image_round_trips_and_rejects_corruption() {
        let leaves: Vec<_> = (0..4).map(|index| digest(index + 1)).collect();
        let mut state = WalletWitnessStateV1::empty();
        for index in 0..leaves.len() {
            state
                .append_authenticated_leaf_v1(
                    index as u64,
                    index as u64 + 1,
                    encode_digest_canonical(&leaves[index]),
                    encode_digest_canonical(&reference_prefix_root(&leaves[..=index])),
                    [1usize, 3].contains(&index).then(|| event(index as u64)),
                )
                .unwrap();
        }
        let encoded = encode_wallet_witness_state_v1(&state).unwrap();
        assert_eq!(
            encoded.len(),
            WALLET_WITNESS_STATE_HEADER_BYTES_V1
                + POOL_V1_TREE_STATE_ACCOUNT_BYTES
                + 2 * WALLET_WITNESS_RECORD_BYTES_V1
        );
        assert_eq!(decode_wallet_witness_state_v1(&encoded).unwrap(), state);
        assert_eq!(
            encode_wallet_witness_state_v1(&decode_wallet_witness_state_v1(&encoded).unwrap())
                .unwrap(),
            encoded
        );

        let mut corrupt = encoded;
        *corrupt.last_mut().unwrap() ^= 1;
        assert_eq!(
            decode_wallet_witness_state_v1(&corrupt),
            Err(WitnessStateErrorV1::ChecksumMismatch)
        );
    }

    #[test]
    fn imported_and_authenticated_updates_fail_atomically_on_any_mismatch() {
        let mut state = WalletWitnessStateV1::empty();
        let leaf = digest(1);
        let root = reference_prefix_root(&[leaf]);
        state
            .append_authenticated_leaf_v1(
                0,
                1,
                encode_digest_canonical(&leaf),
                encode_digest_canonical(&root),
                Some(event(0)),
            )
            .unwrap();
        let before = state.clone();
        assert_eq!(
            state.append_authenticated_leaf_v1(
                1,
                2,
                encode_digest_canonical(&digest(2)),
                encode_digest_canonical(&digest(999)),
                None,
            ),
            Err(WitnessStateErrorV1::RootMismatch)
        );
        assert_eq!(state, before);

        let witness = *state.witness_v1(event(0)).unwrap();
        let siblings = witness.siblings.map(|node| encode_digest_canonical(&node));
        assert_eq!(
            state.import_current_witness_v1(
                event(0),
                witness.leaf_index,
                encode_digest_canonical(&witness.leaf),
                siblings,
            ),
            Err(WitnessStateErrorV1::DuplicateWitness)
        );
        let mut corrupt = siblings;
        corrupt[0] = encode_digest_canonical(&digest(700));
        assert_eq!(
            WalletWitnessStateV1::from_authenticated_tree_v1(
                *state.tree(),
                encode_digest_canonical(&state.tree().root),
            )
            .unwrap()
            .import_current_witness_v1(
                event(9),
                witness.leaf_index,
                encode_digest_canonical(&witness.leaf),
                corrupt,
            ),
            Err(WitnessStateErrorV1::InvalidWitness)
        );
    }
}

