    );

    let mut image = fs::read(&path).unwrap();
    image[24] ^= 1;
    fs::write(&path, image).unwrap();
    assert_eq!(
        LaneForestWalletTxnCoordinatorV2::open_or_create_v2(&path, activation, &fixture.cipher,)
            .err(),
        Some(LaneForestWalletTxnErrorV2::ChecksumMismatch)
    );
}

