//! Reproduce the quarantined, unmined spend integration fixture.
//!
//! Fixed entropy and caller-selected query schedules are test-only. This
//! executable must never be enabled for production proof generation.

#[cfg(not(feature = "insecure-spend-fixture"))]
compile_error!(
    "spend_fixture requires --features insecure-spend-fixture; never enable it in production"
);

use std::{env, fs};

use aspis_core::field::M31;
use aspis_prover::state_only_candidate_prefix::StateOnlyPowMode;
use aspis_prover::state_only_entropy::StateOnlyAttemptSecrets;
use aspis_prover::state_only_hiding::InMemoryStateOnlyMaskNonceStore;
use aspis_prover::state_only_spend::build_hiding_atomic_state_only_spend_proof_v3;
use aspis_prover::HOST_HASH;
use aspis_statement::atomic_state_only_trace::atomic_merkle_root_v3;
use aspis_statement::state_only_spend::verify_atomic_state_only_spend_unmined_for_diagnostics_v4;
use aspis_statement::{
    derive_nullifier, derive_owner_key, note_commitment, output_commitment,
    AtomicPaymentStatementV4, Digest, MerklePath, SpendPublic, SpendWitness,
};

fn digest(seed: u32) -> Digest {
    core::array::from_fn(|index| M31(seed + 17 * index as u32))
}

fn fixture() -> (AtomicPaymentStatementV4, SpendWitness) {
    let nullifier_key = digest(101);
    let input_salt = digest(301);
    let output_salt = digest(501);
    let output_owner_key = digest(701);
    let asset_id = M31(17);
    let value = 1_000_000;
    let value_out = 999_999;
    let merkle_path = MerklePath {
        siblings: (0..20).map(|level| digest(1_000 + 31 * level)).collect(),
        index: 0x5_a5a5,
    };
    let witness = SpendWitness {
        nullifier_key,
        input_salt,
        output_salt,
        output_owner_key,
        input_asset_id: asset_id,
        value,
        value_out,
        merkle_path,
    };
    let input = note_commitment(
        &derive_owner_key(&nullifier_key),
        value,
        asset_id,
        &input_salt,
    );
    let output = output_commitment(&output_owner_key, value_out, asset_id, &output_salt);
    let statement = AtomicPaymentStatementV4 {
        pool: [0x5a; 32],
        sequence: 73,
        spend: SpendPublic {
            anchor: atomic_merkle_root_v3(input, &witness.merkle_path).unwrap(),
            nullifier: derive_nullifier(&nullifier_key, &input_salt),
            output_commitment: output,
            asset_id,
            fee: 1,
        },
        output_anchor: atomic_merkle_root_v3(output, &witness.merkle_path).unwrap(),
        deployment_domain: [0x5d; 32],
    };
    (statement, witness)
}

fn main() {
    let output = env::args().nth(1).unwrap_or_else(|| {
        "crates/aspis-prover/fixtures/atomic_state_only_spend_v4_unmined.bin".into()
    });
    let (statement, witness) = fixture();
    let attempt =
        StateOnlyAttemptSecrets::deterministic_spend_fixture([0x23; 32], [0x45; 32], [0x67; 32]);
    let mut nonces = InMemoryStateOnlyMaskNonceStore::default();
    let built = build_hiding_atomic_state_only_spend_proof_v3(
        &statement,
        &witness,
        attempt,
        &mut nonces,
        HOST_HASH,
        StateOnlyPowMode::UnminedZero,
        0,
    )
    .expect("build deterministic spend fixture");

    verify_atomic_state_only_spend_unmined_for_diagnostics_v4(
        &built.bytes,
        &statement,
        HOST_HASH,
        None,
    )
    .expect("verify deterministic spend fixture");

    let sha256 = HOST_HASH(&[&built.bytes])
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect::<String>();
    let statement_digest =
        aspis_statement::atomic_payment_statement_digest_v4(&statement, HOST_HASH)
            .expect("canonical fixture statement digest")
            .iter()
            .map(|byte| format!("{byte:02x}"))
            .collect::<String>();
    fs::write(&output, &built.bytes).expect("write spend fixture");
    println!("proof={output}");
    println!("bytes={}", built.bytes.len());
    println!("sha256={sha256}");
    println!("statement_digest={statement_digest}");
    assert_eq!(built.bytes.len(), 64_447);
    assert_eq!(
        sha256,
        "cf3ba127153e726e0e6eb5e4f546b6562a9c57d1ae6ee6a0df6b25aac0863b3b"
    );
    println!("section_bytes={:?}", built.openings.section_bytes);
    println!("frontier_nodes={:?}", built.openings.frontier_nodes);
}

crates/aspis-prover/examples/spend_produ:
//! Local production-path miner for the frozen Spend proof.
//!
//! This example uses fresh OS entropy, a durable burned-nonce ledger, the
//! exact cap-17 q3 GoodSpend worker, canonical minimum PoW, and the fixed public
//! release controller. It never exposes a partial attempt or retry detail.

use std::fs;
use std::io::Write;
use std::path::PathBuf;
use std::sync::atomic::{compiler_fence, Ordering};
use std::sync::mpsc;
use std::thread;
use std::time::{Duration, SystemTime};

use aspis_core::field::M31;
use aspis_prover::state_only_entropy::DurableStateOnlyMaskNonceStore;
use aspis_prover::state_only_spend::build_hiding_atomic_state_only_spend_first_good_v3;
use aspis_prover::state_only_spend_release::{
    SpendFixedReleaseController, SpendPublicRelease, SpendReleaseChannel, SpendSystemReleaseClock,
};
use aspis_prover::HOST_HASH;
use aspis_statement::atomic_state_only_trace::atomic_merkle_root_v3;
use aspis_statement::{
    derive_nullifier, derive_owner_key, encode_digest_canonical, note_commitment,
    output_commitment, AtomicPaymentStatementV4, Digest, MerklePath, SpendPublic, SpendWitness,
};

fn digest(seed: u32) -> Digest {
    core::array::from_fn(|index| M31(seed + 17 * index as u32))
}

fn fixture(
    pool: [u8; 32],
    sequence: u64,
    deployment_domain: [u8; 32],
    fixture_seed: u32,
) -> (AtomicPaymentStatementV4, SpendWitness) {
    let seeded_digest = |base: u32| {
        digest(
            base.checked_add(fixture_seed)
                .expect("ASPIS_SPEND_FIXTURE_SEED overflow"),
        )
    };
    let nullifier_key = seeded_digest(101);
    let input_salt = seeded_digest(301);
    let output_salt = seeded_digest(501);
    let output_owner_key = seeded_digest(701);
    let asset_id = M31(17);
    let value = 1_000_000;
    let value_out = 999_999;
    let merkle_path = MerklePath {
        siblings: (0..20)
            .map(|level| seeded_digest(1_000 + 31 * level))
            .collect(),
        index: 0x5_a5a5,
    };
    let witness = SpendWitness {
        nullifier_key,
        input_salt,
        output_salt,
        output_owner_key,
        input_asset_id: asset_id,
        value,
        value_out,
        merkle_path,
    };
    let input = note_commitment(
        &derive_owner_key(&nullifier_key),
        value,
        asset_id,
        &input_salt,
    );
    let output = output_commitment(&output_owner_key, value_out, asset_id, &output_salt);
    let statement = AtomicPaymentStatementV4 {
        pool,
        sequence,
        spend: SpendPublic {
            anchor: atomic_merkle_root_v3(input, &witness.merkle_path).unwrap(),
            nullifier: derive_nullifier(&nullifier_key, &input_salt),
            output_commitment: output,
            asset_id,
            fee: 1,
        },
        output_anchor: atomic_merkle_root_v3(output, &witness.merkle_path).unwrap(),
        deployment_domain,
    };
    (statement, witness)
}

/// Decode one base58 Solana public key into its 32 raw bytes.
fn decode_base58_32(role: &str, value: &str) -> [u8; 32] {
    const ALPHABET: &[u8] = b"123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz";
    let mut bytes: Vec<u8> = Vec::with_capacity(32);
    for symbol in value.bytes() {
        let mut carry = ALPHABET
            .iter()
            .position(|&candidate| candidate == symbol)
            .unwrap_or_else(|| panic!("{role} is not base58"));
        for byte in bytes.iter_mut() {
            carry += usize::from(*byte) * 58;
            *byte = (carry & 0xff) as u8;
            carry >>= 8;
        }
        while carry != 0 {
            bytes.push((carry & 0xff) as u8);
            carry >>= 8;
        }
    }
    for symbol in value.bytes() {
        if symbol == b'1' {
            bytes.push(0);
        } else {
            break;
        }
    }
    assert_eq!(bytes.len(), 32, "{role} must decode to exactly 32 bytes");
    bytes.reverse();
    bytes.try_into().unwrap()
}

#[derive(Default)]
struct OneReleaseChannel {
    release: Option<SpendPublicRelease>,
}

impl SpendReleaseChannel for OneReleaseChannel {
    fn publish(&mut self, release: SpendPublicRelease) {
        assert!(self.release.replace(release).is_none());
    }
}

fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|byte| format!("{byte:02x}")).collect()
}

fn scrub_witness(witness: &mut SpendWitness) {
    for value in witness
        .nullifier_key
        .iter_mut()
        .chain(&mut witness.input_salt)
        .chain(&mut witness.output_salt)
        .chain(&mut witness.output_owner_key)
    {
        // SAFETY: every pointer is a live, uniquely borrowed M31 cell. The
        // volatile write prevents the cleanup from being optimized away.
        unsafe { core::ptr::write_volatile(value, M31::ZERO) };
    }
    unsafe {
        core::ptr::write_volatile(&mut witness.input_asset_id, M31::ZERO);
        core::ptr::write_volatile(&mut witness.value, 0);
        core::ptr::write_volatile(&mut witness.value_out, 0);
        core::ptr::write_volatile(&mut witness.merkle_path.index, 0);
    }
    for sibling in &mut witness.merkle_path.siblings {
        for value in sibling {
            unsafe { core::ptr::write_volatile(value, M31::ZERO) };
        }
    }
    compiler_fence(Ordering::SeqCst);
}

fn main() {
    let mut args = std::env::args().skip(1);
    let cluster_tag = args
        .next()
        .expect("usage: spend_production_miner <cluster-tag> <program-id> <pool-pubkey> [output] [ledger] [boundary-seconds]");
    assert!(
        !cluster_tag.is_empty() && cluster_tag.len() <= 64,
        "cluster tag must be a short nonempty name such as mainnet-beta or devnet"
    );
    let program_id = decode_base58_32("program id", &args.next().expect("program id argument"));
    let pool = decode_base58_32("pool pubkey", &args.next().expect("pool pubkey argument"));
    let output = PathBuf::from(
        args.next()
            .unwrap_or_else(|| "artifact-output/spend-production-mined.bin".to_owned()),
    );
    let ledger = PathBuf::from(
        args.next()
            .unwrap_or_else(|| "artifact-output/spend-production-nonce-ledger".to_owned()),
    );
    let boundary_seconds = args
        .next()
        .map(|value| value.parse::<u64>().expect("boundary seconds"))
        .unwrap_or(3_600);
    assert!(args.next().is_none(), "too many arguments");

    // The production statement is always sequence 0 of a freshly initialized
    // pool, bound to the deployment domain the pool stores at init.
    let sequence = 0u64;
    let fixture_seed = std::env::var("ASPIS_SPEND_FIXTURE_SEED")
        .map(|value| value.parse::<u32>().expect("ASPIS_SPEND_FIXTURE_SEED"))
        .unwrap_or(0);
    let deployment_domain =
        aspis_statement::atomic_deployment_domain(HOST_HASH, &program_id, cluster_tag.as_bytes());
    let boundary = SystemTime::now()
        .checked_add(Duration::from_secs(boundary_seconds))
        .expect("release boundary overflow");
    let mut controller = SpendFixedReleaseController::new(boundary);
    let (statement, mut witness) = fixture(pool, sequence, deployment_domain, fixture_seed);
    let statement_sidecar = serde_json::json!({
        "artifact": "aspis_spend_production_statement",
        "pool_hex": hex(&statement.pool),
        "sequence": statement.sequence,
        "current_anchor_hex": hex(&encode_digest_canonical(&statement.spend.anchor)),
        "nullifier_hex": hex(&encode_digest_canonical(&statement.spend.nullifier)),
        "output_commitment_hex": hex(&encode_digest_canonical(&statement.spend.output_commitment)),
        "output_anchor_hex": hex(&encode_digest_canonical(&statement.output_anchor)),
        "asset_id": statement.spend.asset_id.0,
        "fee": statement.spend.fee,
        "deployment_domain_hex": hex(&statement.deployment_domain),
        "selection_rule": "least GoodSpend selector from three post-final branches",
        "witness_independent_public_metadata": true,
    });
    if let Some(parent) = ledger.parent() {
        fs::create_dir_all(parent).expect("create nonce-ledger directory");
    }
    let mut nonce_store =
        DurableStateOnlyMaskNonceStore::open(&ledger).expect("open durable nonce ledger");
    let (sender, receiver) = mpsc::sync_channel(1);
    let worker = thread::spawn(move || {
        let completion = build_hiding_atomic_state_only_spend_first_good_v3(
            &statement,
            &witness,
            &mut nonce_store,
        );
        scrub_witness(&mut witness);
        let _ = sender.send(completion);
    });

    // The boundary event remains live while the private worker mines. If the
    // worker has not delivered a complete result by the preselected instant,
    // the controller publishes Abort on time and the process exits without
    // waiting for a late result.
    let mut clock = SpendSystemReleaseClock;
    let completed = loop {
        let Ok(remaining) = boundary.duration_since(SystemTime::now()) else {
            break false;
        };
        if remaining.is_zero() {
            break false;
        }
        match receiver.recv_timeout(remaining.min(Duration::from_millis(250))) {
            Ok(completion) => {
                controller.record_first_good_completion(&clock, completion);
                break true;
            }
            Err(mpsc::RecvTimeoutError::Timeout) => {}
            Err(mpsc::RecvTimeoutError::Disconnected) => break false,
        }
    };
    let mut channel = OneReleaseChannel::default();
    controller.release(&mut clock, &mut channel);
    if completed {
        worker.join().expect("private Spend worker panicked");
    } else {
        drop(worker);
    }

    match channel.release.expect("one release event") {
        SpendPublicRelease::Proof(proof) => {
            if let Some(parent) = output.parent() {
                fs::create_dir_all(parent).expect("create proof directory");
            }
            let mut file = fs::OpenOptions::new()
                .write(true)
                .create_new(true)
                .open(&output)
                .expect("create fresh released proof");
            file.write_all(&proof).expect("write released proof");
            file.sync_all().expect("sync released proof");
            let statement_path = output.with_extension("statement.json");
            let statement_bytes = serde_json::to_vec_pretty(&statement_sidecar)
                .expect("serialize public statement sidecar");
            let mut statement_file = fs::OpenOptions::new()
                .write(true)
                .create_new(true)
                .open(&statement_path)
                .expect("create fresh public statement sidecar");
            statement_file
                .write_all(&statement_bytes)
                .expect("write public statement sidecar");
            statement_file
                .sync_all()
                .expect("sync public statement sidecar");
            println!("proof={}", output.display());
            println!("statement={}", statement_path.display());
            println!("bytes={}", proof.len());
            println!("sha256={}", hex(&HOST_HASH(&[&proof])));
            println!("cluster_tag={cluster_tag}");
            println!("deployment_domain={}", hex(&deployment_domain));
            println!("fixture_seed={fixture_seed}");
        }
        SpendPublicRelease::Abort => {
            println!("abort");
            std::process::exit(2);
        }
    }
}

crates/aspis-prover/examples/spend_sound:
//! Arithmetic and release guard for the spend D-after-G, q3 design.
//!
//! This executable pins the term-by-term Johnson soundness union, the
//! three-candidate rank-exhaustion/liveness bound, and the literal EPRO input
//! inventory. Normal mode also requires the fail-closed one-transaction
//! release certificate. `--calculation-only` evaluates the proof-independent
//! arithmetic without requiring that downstream certificate, breaking the
//! release-generation cycle without weakening the normal release guard. This
//! executable does not replace the separate root-neutral polynomial-kernel and
//! complete-view proofs.

use std::collections::HashSet;
use std::f64::consts::LN_2;
use std::path::Path;

use aspis_core::circle_hiding_prefix::PAYMENT_HIDING_QUERY_DRAW_LIMIT;
use aspis_core::field::{M31, P as M31_MODULUS};
use aspis_core::state_only_hiding::{
    STATE_ONLY_SPEND_D_GENERATOR_INDEX, STATE_ONLY_SPEND_G_GENERATOR_INDEX,
    STATE_ONLY_SPEND_QUERY_CANDIDATES, STATE_ONLY_SPEND_TOTAL_GENERATOR_WIDTH,
};
use aspis_core::state_only_prefix::{
    STATE_ONLY_LOG_ROWS, STATE_ONLY_SPEND_BATCH_GRINDING_BITS, STATE_ONLY_SPEND_D_CLAIM_COUNT,
    STATE_ONLY_SPEND_FOLD_GRINDING_BITS, STATE_ONLY_SPEND_GRINDING_BITS,
    STATE_ONLY_SPEND_QUERY_CANDIDATE_COUNT, STATE_ONLY_SPEND_QUERY_COUNT,
};
use aspis_core::transcript::label;
use aspis_prover::state_only_good_spend::{
    verify_spend_selector_scope_lemma, SPEND_GOOD_SCHEDULE_MAX_ATTEMPTS,
    SPEND_SELECTOR_SCOPE_PROPOSITIONAL_CASES,
};

const P: f64 = M31_MODULUS as f64;
const FIELD_SIZE: f64 = P * P * P * P;
const JOHNSON_MULTIPLICITY: f64 = 10.0;
const FOLD_WORK: [u8; 4] = STATE_ONLY_SPEND_FOLD_GRINDING_BITS;
const ROOT_CAPS: [u64; 4] = [1_024, 255, 63, 15];
const QUERY_FIBERS: f64 = 131_072.0;
const QUERY_COUNT: u64 = 18;
const SELECTORS: u64 = 3;
const ATTEMPTS: u64 = 17;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum SelectorScope {
    CommonPreselector,
    FinalQueryMiss,
}

/// Exact q18 complete-Good liveness pins from the optimized root-neutral minor.
/// Calculation-only mode does not need the downstream artifact or release;
/// normal release-guard mode cross-checks both and still fails closed on
/// accidental removal of these pins.
#[derive(Clone, Copy)]
struct SpendGoodLivenessPins {
    query_degree: f64,
    root_neutral_minor_z_degree: f64,
    complete_good_z_degree: f64,
    gamma_degree: f64,
    continuous_degree: f64,
    rho_query: f64,
    beta_attempt: f64,
    bits_per_attempt: f64,
    rank_exhaustion_cap17_bits: f64,
    public_abort_bits: f64,
    root_minor_fingerprint: u64,
    remaining_gd_minor_fingerprint: u64,
    h1_minor_fingerprint: u64,
    product_fingerprint: u64,
}

const SPEND_Q18_GOOD_LIVENESS_PINS: Option<SpendGoodLivenessPins> = Some(SpendGoodLivenessPins {
    query_degree: 31_320.0,
    root_neutral_minor_z_degree: 41_040.0,
    complete_good_z_degree: 41_280.0,
    gamma_degree: 80_688.0,
    continuous_degree: 121_968.0,
    rho_query: 0.238_983_632_825_912_78,
    beta_attempt: 0.013_705_910_239_932_412,
    bits_per_attempt: 6.189_058_045_848_226,
    rank_exhaustion_cap17_bits: 105.213_986_779_419_84,
    public_abort_bits: 105.213_986_779_419_83,
    root_minor_fingerprint: 0xc1e2_3e3a_cec5_5fc9,
    remaining_gd_minor_fingerprint: 0x7ca2_57ac_a211_584a,
    h1_minor_fingerprint: 0x2b09_c8e0_f643_b2bf,
    product_fingerprint: 0xb1af_7cc0_8b30_847d,
});

fn union_bits(bits: impl IntoIterator<Item = f64>) -> f64 {
    -bits
        .into_iter()
        .map(|bits| 2.0_f64.powf(-bits))
        .sum::<f64>()
        .log2()
}

fn local_bits(numerator: f64) -> f64 {
    FIELD_SIZE.log2() - numerator.log2()
}

fn local_nonzero_bits(numerator: f64) -> f64 {
    (FIELD_SIZE - 1.0).log2() - numerator.log2()
}

fn bcs_work_normalized_bits(round_bits: f64, random_oracle_queries: f64) -> f64 {
    const R: f64 = 32.0;
    const LAMBDA: f64 = 256.0;
    let epsilon_round = 2.0_f64.powf(-round_bits);
    let epsilon_bcs_per_query = (1.0 + R / random_oracle_queries) * epsilon_round
        + 3.0 * (random_oracle_queries + random_oracle_queries.recip()) * 2.0_f64.powf(-LAMBDA);
    -epsilon_bcs_per_query.log2()
}

fn close(actual: f64, expected: f64) {
    assert!(
        (actual - expected).abs() < 1e-9,
        "numeric repin: actual={actual:.15}, expected={expected:.15}"
    );
}

fn main() {
    let calculation_only = match std::env::args().skip(1).collect::<Vec<_>>().as_slice() {
        [] => false,
        [argument] if argument == "--calculation-only" => true,
        _ => panic!("usage: spend_soundness_epro_ledger [--calculation-only]"),
    };

    assert_eq!(STATE_ONLY_SPEND_TOTAL_GENERATOR_WIDTH, 29);
    assert_eq!(STATE_ONLY_SPEND_G_GENERATOR_INDEX, 27);
    assert_eq!(STATE_ONLY_SPEND_D_GENERATOR_INDEX, 28);
    assert_eq!(STATE_ONLY_SPEND_QUERY_CANDIDATES, 3);
    assert_eq!(STATE_ONLY_SPEND_QUERY_CANDIDATE_COUNT, 3);
    assert_eq!(STATE_ONLY_SPEND_D_CLAIM_COUNT, 3);
    assert_eq!(STATE_ONLY_SPEND_QUERY_COUNT, QUERY_COUNT as u16);
    assert_eq!(SPEND_GOOD_SCHEDULE_MAX_ATTEMPTS, ATTEMPTS as usize);
    assert_eq!(STATE_ONLY_SPEND_BATCH_GRINDING_BITS, 37);
    assert_eq!(STATE_ONLY_SPEND_FOLD_GRINDING_BITS, [34, 33, 30, 25]);
    assert_eq!(STATE_ONLY_SPEND_GRINDING_BITS, 32);
    assert_eq!(label::M31_STATE_ONLY_ZERO_FACTOR_D_CLAIMS, 43);
    assert_eq!(label::M31_STATE_ONLY_QUERY_CANDIDATE, 44);
    let selector_scope_cases = verify_spend_selector_scope_lemma();
    assert_eq!(
        selector_scope_cases,
        SPEND_SELECTOR_SCOPE_PROPOSITIONAL_CASES
    );

    // The q sampler selects distinct four-symbol fibers.  Exhaustively pin
    // that the implemented fiber->polynomial-root map is injective; this
    // discharges a separate root-collision event.  Root one is handled by the
    // exhaustive root-one count below; no degree-16 anchor is booked.
    let mut query_roots = HashSet::with_capacity(QUERY_FIBERS as usize);
    let mut root_one_count = 0usize;
    let mut line_root_one_count = 0usize;
    for query in 0..QUERY_FIBERS as usize {
        let point = aspis_core::circle_fri::circle_fiber_point_for_domain_log(
            STATE_ONLY_LOG_ROWS + 9,
            query,
        )
        .expect("spend query fiber point");
        let root = point.x.mul(point.x).double().sub(M31::ONE);
        let line_root =
            aspis_core::circle_fri::line_domain_x_for_circle(STATE_ONLY_LOG_ROWS + 9, 1, query)
                .expect("spend line-domain root");
        assert_eq!(root, line_root, "circle/line root mismatch at {query}");
        root_one_count += usize::from(root == M31::ONE);
        line_root_one_count += usize::from(line_root == M31::ONE);
        assert!(
            query_roots.insert(root.0),
            "fiber-root map collision at {query}"
        );
    }
    assert_eq!(query_roots.len(), QUERY_FIBERS as usize);
    assert_eq!(root_one_count, 0);
    assert_eq!(line_root_one_count, root_one_count);
    println!("spend_query_root_one_count={root_one_count}");

    // Johnson / MCA terms.  Only the final q18 miss term receives the
    // malicious-selector union.  D changes the polynomial batching degree
    // 27->28, gamma numerator 29->30, and inactive-copy numerator 27->28.
    let rho: f64 = 1.0 / 512.0;
    let agreement_fraction = (1.0 + 1.0 / (2.0 * JOHNSON_MULTIPLICITY)) * rho.sqrt();
    let query_fibers = 131_072u64;
    let agreement_fibers = (agreement_fraction * query_fibers as f64).floor() as u64;
    assert_eq!(agreement_fibers, 6_082);

    let ell = (JOHNSON_MULTIPLICITY + 0.5) / rho.sqrt();
    let batch_numerator = 28.0 * ell * ((2.0 * ell.powi(4) / 3.0) * rho + 1.0) * 524_288.0;
    let batch_bits =
        (FIELD_SIZE / batch_numerator).log2() + f64::from(STATE_ONLY_SPEND_BATCH_GRINDING_BITS);

    let raw_query_bits = (0..QUERY_COUNT)
        .map(|i| -((agreement_fibers - i) as f64 / (query_fibers - i) as f64).log2())
        .sum::<f64>()
        + f64::from(STATE_ONLY_SPEND_GRINDING_BITS);
    let selected_query_bits = raw_query_bits - (SELECTORS as f64).log2();

    let output_symbols = [131_072u64, 32_768, 8_192, 2_048];
    let output_dimensions = [256u64, 64, 16, 4];
    let fold_rows = (0..4)
        .map(|round| {
            let round_rho = (output_dimensions[round] - 1) as f64 / output_symbols[round] as f64;
            let sqrt_rho = round_rho.sqrt();
            let m = (sqrt_rho / (2.0 * (agreement_fraction - sqrt_rho)))
                .ceil()
                .max(3.0);
            let ell = (m + 0.5) / sqrt_rho;
            let numerator = 3.0
                * ell
                * ((2.0 * ell.powi(4) / 3.0) * round_rho + 1.0)
                * output_symbols[round] as f64;
            (FIELD_SIZE / numerator).log2() + f64::from(FOLD_WORK[round])
        })
        .collect::<Vec<_>>();
    let folds_bits = union_bits(fold_rows.iter().copied());

    let ood_space = FIELD_SIZE - P * P;
    let list_pairs = (240u64 * 239 / 2) as f64;
    let ood_probability = ROOT_CAPS
        .into_iter()
        .map(|root| list_pairs * (root as f64 / ood_space).powi(2))
        .sum::<f64>();
    let ood_bits = -ood_probability.log2();

    let terms = [
        (
            "polynomial_batch_width_29",
            batch_bits,
            SelectorScope::CommonPreselector,
        ),
        (
            "four_fold_union",
            folds_bits,
            SelectorScope::CommonPreselector,
        ),
        (
            "final_q18_miss_times_3",
            selected_query_bits,
            SelectorScope::FinalQueryMiss,
        ),
        (
            "two_sample_ood_list_union",
            ood_bits,
            SelectorScope::CommonPreselector,
        ),
        (
            "relation_ood_mixers_24",
            local_bits(24.0),
            SelectorScope::CommonPreselector,
        ),
        (
            "nonzero_gamma_and_three_point_batch_30",
            local_nonzero_bits(30.0),
            SelectorScope::CommonPreselector,
        ),
        (
            "copy_inactive_nonzero_gamma_28",
            local_nonzero_bits(28.0),
            SelectorScope::CommonPreselector,
        ),
        (
            "atomic_tuple_compression",
            local_bits(183.0 * 17.0),
            SelectorScope::CommonPreselector,
        ),
        (
            "atomic_copy_range_poles",
            local_bits(4.0 * (183.0 + 1_024.0)),
            SelectorScope::CommonPreselector,
        ),
        (
            "atomic_theta_collision",
            local_bits(24.0),
            SelectorScope::CommonPreselector,
        ),
        (
            "zerocheck_equality_point",
            local_bits(10.0),
            SelectorScope::CommonPreselector,
        ),
        (
            "zero_sum_h1_helper",
            local_bits(1.0),
            SelectorScope::CommonPreselector,
        ),
        (
            "mask_original_nonzero_eta",
            (FIELD_SIZE - 1.0).log2(),
            SelectorScope::CommonPreselector,
        ),
        (
            "ten_degree_27_zerocheck_rounds",
            local_bits(270.0),
            SelectorScope::CommonPreselector,
        ),
        (
            "poseidon2_assumption",
            124.0,
            SelectorScope::CommonPreselector,
        ),
        (
            "sha256_rom_assumption",
            128.0,
            SelectorScope::CommonPreselector,
        ),
    ];
    assert_eq!(
        terms
            .iter()
            .filter(|(_, _, scope)| *scope == SelectorScope::FinalQueryMiss)
            .map(|(name, _, _)| *name)
            .collect::<Vec<_>>(),
        ["final_q18_miss_times_3"]
    );
    let event_union_bits = union_bits(terms.iter().map(|(_, bits, _)| *bits));

    // Coarse sensitivity: start from Spend's own unselected ledger, apply
    // the Spend BCS boundary count, then pessimistically multiply the
    // entire ledger by the three selector branches.  It is intentionally
    // distinct from the refined ledger above, where only the final q18 miss
    // receives the selector union.
    let coarse_event_union_bits = union_bits(terms.iter().map(|(_, bits, scope)| {
        if *scope == SelectorScope::FinalQueryMiss {
            raw_query_bits
        } else {
            *bits
        }
    }));

    // Work-normalized BCS/Fiat-Shamir instantiation with R=32, lambda=256 and
    // 1 <= T <= 2^128 random-oracle queries.  The maximum error is checked at
    // both interval endpoints.  At T=1 the leading factor is 1+R=33, not 32.
    let bcs_t_min = 1.0_f64;
    let bcs_t_max = 2.0_f64.powi(128);
    let bcs_selected_t1_bits = bcs_work_normalized_bits(event_union_bits, bcs_t_min);
    let bcs_selected_tmax_bits = bcs_work_normalized_bits(event_union_bits, bcs_t_max);
    let after_bcs_work_normalized_bits = bcs_selected_t1_bits.min(bcs_selected_tmax_bits);
    let after_factor40_bits = event_union_bits - 40.0_f64.log2();
    let bcs_coarse_t1_bits = bcs_work_normalized_bits(coarse_event_union_bits, bcs_t_min);
    let bcs_coarse_tmax_bits = bcs_work_normalized_bits(coarse_event_union_bits, bcs_t_max);
    let coarse_after_bcs_work_normalized_bits = bcs_coarse_t1_bits.min(bcs_coarse_tmax_bits);
    let coarse_whole_ledger_times_three_bits =
        coarse_after_bcs_work_normalized_bits - (SELECTORS as f64).log2();

    // EPRO inventory.  D is one full 1,024-coefficient QM31 mask lane:
    // 4,096 new M31 outputs, booked at two SHA inputs per output.  The three
    // q18 branches add two extra eight-block squeeze+advance streams. The
    // 64-draw cap still bounds each branch by eight blocks, so q18 does not
    // increase this worst-case distinct-input inventory. The
    // literal transcript also has three candidate-label absorbs and the
    // separate label-43 D-claims absorb.
    let leaves = 305_152u64;
    let profile22_field_outputs_m31 = 22_850u64;
    let d_field_outputs_m31 = 1_024u64 * 4;
    let field_expander_inputs = 2 * (profile22_field_outputs_m31 + d_field_outputs_m31);
    let query_squeeze_blocks = (PAYMENT_HIDING_QUERY_DRAW_LIMIT as u64 + 7) / 8;
    assert_eq!(query_squeeze_blocks, 8);
    let programmed_squeeze_inputs = 67u64 * 4 + SELECTORS * query_squeeze_blocks;
    let literal_absorb_inputs = 43u64 + 1 + SELECTORS;
    let work_predicate_inputs = 2 + FOLD_WORK.len() as u64;
    let transcript_inputs =
        literal_absorb_inputs + 2 * programmed_squeeze_inputs + work_predicate_inputs;
    let epro_inventory = 3 * leaves + field_expander_inputs + 8 + transcript_inputs;
    let q_h_log2 = 128.0;
    let leading_epro_bits = 256.0 - q_h_log2 - (ATTEMPTS as f64 * epro_inventory as f64).log2();
    // The EPRO hybrid compares one real execution with the common
    // witness-independent simulator.  The published two-witness statement
    // is Real(w0) -> Sim -> Real(w1), hence the explicit factor two.
    let pairwise_hiding_bits = leading_epro_bits - 1.0;
    let programmed_inputs = ATTEMPTS as f64 * epro_inventory as f64;
    let collision_bits = 256.0 - (programmed_inputs * (programmed_inputs - 1.0) / 2.0).log2();
    let max_work_bits = FOLD_WORK
        .into_iter()
        .chain([
            STATE_ONLY_SPEND_BATCH_GRINDING_BITS,
            STATE_ONLY_SPEND_GRINDING_BITS,
        ])
        .max()
        .expect("nonempty Spend work schedule");
    assert_eq!(max_work_bits, 37);
    let work_nonce_expected_hits_exponent = 64 - i32::from(max_work_bits);
    let work_exhaustion_bits = 2.0_f64.powi(work_nonce_expected_hits_exponent) / LN_2
        - (work_predicate_inputs as f64 * ATTEMPTS as f64).log2();

    // If a 64-draw q18 sampler fails, at least 47 draws duplicated one of at
    // most 17 accepted indices. This is completeness, not soundness.
    let max_unique_on_failure = QUERY_COUNT - 1;
    let duplicate_draws = PAYMENT_HIDING_QUERY_DRAW_LIMIT as u64 - max_unique_on_failure;
    assert_eq!((max_unique_on_failure, duplicate_draws), (17, 47));
    let log2_binomial_64_47 = (1..=duplicate_draws)
        .map(|i| {
            ((PAYMENT_HIDING_QUERY_DRAW_LIMIT as u64 - duplicate_draws + i) as f64 / i as f64)
                .log2()
        })
        .sum::<f64>();
    let sampler_one_bits = -(log2_binomial_64_47
        + duplicate_draws as f64 * (max_unique_on_failure as f64 / QUERY_FIBERS).log2());
    let sampler_cap17_m3_bits = sampler_one_bits - ((ATTEMPTS * SELECTORS) as f64).log2();

    // Initial exact pins are printed below; close calls make every subsequent
    // protocol/count change an explicit repin rather than a silent drift.
    close(batch_bits, 107.316_020_114_355_38);
    close(raw_query_bits, 111.768_701_634_364_65);
    close(selected_query_bits, 110.183_739_133_643_48);
    for (actual, expected) in fold_rows.iter().copied().zip([
        109.529_942_692_338_42,
        111.226_281_804_531_75,
        112.858_135_080_222_61,
        113.840_648_013_834_85,
    ]) {
        close(actual, expected);
    }
    close(folds_bits, 108.985_432_265_750_69);
    close(event_union_bits, 106.702_033_487_302_9);
    close(bcs_selected_t1_bits, 101.657_639_367_944_44);
    close(bcs_selected_tmax_bits, 106.702_031_808_619_58);
    close(after_bcs_work_normalized_bits, 101.657_639_367_944_44);
    close(after_factor40_bits, 101.380_105_392_415_53);
    close(coarse_event_union_bits, 106.790_806_002_954_17);
    close(bcs_coarse_t1_bits, 101.746_411_883_595_71);
    close(bcs_coarse_tmax_bits, 106.790_804_217_733_32);
    close(coarse_whole_ledger_times_three_bits, 100.161_449_382_874_55);
    assert_eq!(field_expander_inputs, 53_892);
    assert_eq!(programmed_squeeze_inputs, 292);
    assert_eq!(literal_absorb_inputs, 47);
    assert_eq!(transcript_inputs, 637);
    assert_eq!(epro_inventory, 969_993);
    close(leading_epro_bits, 104.024_922_348_251_98);
    close(pairwise_hiding_bits, 103.024_922_348_251_98);
    close(collision_bits, 209.049_844_783_993_68);
    close(work_exhaustion_bits, 193_635_243.912_558_44);
    close(sampler_one_bits, 556.596_315_359_622);
    close(sampler_cap17_m3_bits, 550.923_890_017_650_6);

    println!("spend_candidate_query_count={QUERY_COUNT}");
    println!("spend_candidate_batch_work_bits={STATE_ONLY_SPEND_BATCH_GRINDING_BITS}");
    println!("spend_candidate_fold_work_bits={FOLD_WORK:?}");
    println!("spend_candidate_final_work_bits={STATE_ONLY_SPEND_GRINDING_BITS}");
    println!("spend_candidate_attempt_cap={ATTEMPTS}");
    println!("spend_selector_scope_propositional_cases={selector_scope_cases}");
    for (name, bits, _) in terms {
        println!("spend_soundness_term_{name}={bits:.13}");
    }
    println!("spend_soundness_event_union_bits={event_union_bits:.13}");
    println!("spend_soundness_bcs_t1_bits={bcs_selected_t1_bits:.13}");
    println!("spend_soundness_bcs_t2p128_bits={bcs_selected_tmax_bits:.13}");
    println!("spend_soundness_after_bcs_work_normalized_bits={after_bcs_work_normalized_bits:.13}");
    println!("spend_soundness_after_factor40_bits={after_factor40_bits:.13}");
    println!(
        "spend_soundness_coarse_whole_ledger_times_three_bits={coarse_whole_ledger_times_three_bits:.13}"
    );
    println!("spend_epro_field_expander_inputs={field_expander_inputs}");
    println!("spend_epro_transcript_inputs={transcript_inputs}");
    println!("spend_epro_inventory={epro_inventory}");
    println!("spend_epro_leading_bits={leading_epro_bits:.13}");
    println!("spend_epro_pairwise_witness_bits={pairwise_hiding_bits:.13}");
    println!("spend_epro_collision_bits={collision_bits:.13}");
    println!("spend_epro_work_exhaustion_bits={work_exhaustion_bits:.8}");
    println!("spend_sampler_cap17_m3_union_bits={sampler_cap17_m3_bits:.13}");

    let independent_arithmetic_bookable =
        coarse_whole_ledger_times_three_bits >= 100.0 && pairwise_hiding_bits >= 100.0;
    assert!(
        independent_arithmetic_bookable,
        "Spend q18 independent arithmetic is below the release floor"
    );
    println!("spend_independent_arithmetic_bookable={independent_arithmetic_bookable}");

    let liveness = SPEND_Q18_GOOD_LIVENESS_PINS.expect(
        "Spend q18 complete-Good liveness pins are missing; normal release mode is fail-closed",
    );
    // The complete Good predicate additionally retains two independent raw
    // 12-M31 terminal certificates: the remaining G/D direction and H1
    // inactive padding. Each contributes 12*10=120 degrees.
    let complete_good_z_degree = liveness.root_neutral_minor_z_degree + 120.0 + 120.0;
    let continuous_degree = complete_good_z_degree + liveness.gamma_degree;
    let query_sampling_denominator = QUERY_FIBERS - (QUERY_COUNT - 1) as f64;
    close(query_sampling_denominator, 131_055.0);
    let rho_query = liveness.query_degree / query_sampling_denominator;
    let beta_attempt = continuous_degree / P + rho_query.powi(SELECTORS as i32);
    let bits_per_attempt = -beta_attempt.log2();
    let rank_exhaustion_cap17_bits = ATTEMPTS as f64 * bits_per_attempt;
    let build_abort = 128.0 / P.powi(6);
    let public_abort_probability =
        ATTEMPTS as f64 * build_abort + beta_attempt.powf(ATTEMPTS as f64);
    let public_abort_bits = -public_abort_probability.log2();
    close(complete_good_z_degree, liveness.complete_good_z_degree);
    close(continuous_degree, liveness.continuous_degree);
    close(rho_query, liveness.rho_query);
    close(beta_attempt, liveness.beta_attempt);
    close(bits_per_attempt, liveness.bits_per_attempt);
    close(
        rank_exhaustion_cap17_bits,
        liveness.rank_exhaustion_cap17_bits,
    );
    close(public_abort_bits, liveness.public_abort_bits);
    println!("spend_rho_query={rho_query:.16}");
    println!("spend_beta_attempt={beta_attempt:.16}");
