    #[test]
    fn public_fold_and_layer_root_keep_valid_boundary_behavior() {
        let evaluations = [QM31::ZERO; FIBER_SLOTS];
        assert_eq!(
            fold_candidate_codeword_round_for_domain_log(&evaluations, QM31::ONE, 3, 8,).unwrap(),
            vec![QM31::ZERO]
