            for row in [0usize, 1, 2, 3, 17, 511, 1023] {
                let mut message = vec![M31::ZERO; TRACE_LEN];
                message[row] = M31::ONE;
                let encoded = encoder.encode_c1_message(&message).unwrap();
                for index in [
