    let value: [u8;128] = kani::any();
    let salt: [u8;32] = kani::any();
    let actual = aspis_core::state_only_private_merkle::private_leaf_hash(
        crate::HOST_HASH, 0xf1, &value, &salt);
    let mut bytes = [0u8;162];
