    let active:Vec<_>=(0..1024).filter(|&r|!transport().inactive[r]).collect();assert_eq!(active.len(),214);
    let mut hm=vec![vec![];218];let mut gm=vec![vec![];281];
    let mut active_direct=vec![vec![];214];
