#[derive(Clone, Copy)]
enum StateOnlyFrontMode<'a> {
    Base(&'a SpendPublic),
    Atomic(&'a AtomicPaymentStatementV4),
}

#[allow(clippy::too_many_arguments)]
fn build_state_only_prefix_front_selected_with_h1_padding_mode(
    mode: StateOnlyFrontMode<'_>,
    trace: &StateOnlyTraceFoundation,
    mask_only_c1: &[Vec<M31>; STATE_ONLY_HIDING_MASK_ONLY_C1_COLUMNS],
    g: &[QM31],
    h1_padding: &[QM31],
    statement_digest: [u8; 32],
    mask_nonce: [u8; 32],
    shape: StateOnlyProfileShape,
    hash: HashFn,
    pow_mode: StateOnlyPowMode,
) -> Result<BuiltStateOnlyPrefixFront, StateOnlyPrefixBuildError> {
    if trace.c1.len() != 16
        || trace.c1.iter().any(|column| column.len() != 1024)
        || g.len() != 1024
        || h1_padding.len() != 1024
        || mask_only_c1.iter().any(|column| column.len() != 1024)
    {
        return Err(StateOnlyPrefixBuildError::Shape);
    }
    let domain_log = STATE_ONLY_LOG_ROWS + shape.log_blowup;
    let encoder = CircleEncoder::new_for_domain_log(domain_log);
    let selected_c1 = trace
        .c1
        .iter()
        .cloned()
        .chain(mask_only_c1.iter().cloned())
        .collect::<Vec<_>>();
    let encoded_c1 = encode_state_only_c1_columns(&encoder, &selected_c1)?;
    let c1_leaves = state_only_c1_layer0_leaves(&encoded_c1, encoder.codeword_len())?;
    let mut header_bytes = [0u8; HEADER_LEN];
    state_only_header(shape).write(&mut header_bytes);
    let mut transcript = Transcript::new(hash);
    transcript.absorb(label::PROFILE, &header_bytes);
    transcript.absorb(label::M31_CIRCLE_BASIS, M31_CIRCLE_BASIS_DISCRIMINATOR);
    transcript.absorb(label::STATEMENT, &statement_digest);
    let precommit_binding = begin_state_only_hiding_precommit(
        &mut transcript,
        match mode {
            StateOnlyFrontMode::Base(_) => {
                StateOnlyHidingContext::pinned(statement_digest, mask_nonce)
            }
            StateOnlyFrontMode::Atomic(_) => {
                StateOnlyHidingContext::atomic_v3(statement_digest, mask_nonce)
            }
        },
    )?;
    let (_, temporary_c2_root) = state_only_layer0_roots(
        &c1_leaves,
        &state_only_c2_layer0_leaves(
            &encode_state_only_c2_columns(&encoder, &[vec![QM31::ZERO; 1024], g.to_vec()])?,
            encoder.codeword_len(),
        )?,
        hash,
    )?;
    // C1 and C2 use separate roots; the temporary C2 root is deliberately
    // discarded after obtaining the C1 root without another root helper.
    let (c1_root, _) = state_only_layer0_roots(
        &c1_leaves,
        &state_only_c2_layer0_leaves(
            &encode_state_only_c2_columns(&encoder, &[vec![QM31::ZERO; 1024], g.to_vec()])?,
            encoder.codeword_len(),
        )?,
        hash,
    )?;
    let _ = temporary_c2_root;
    let mut c1_record = [0u8; 33];
    c1_record[1..].copy_from_slice(&c1_root);
    transcript.absorb(label::M31_CIRCLE_ROUND_ROOT, &c1_record);
    let lambda = transcript.challenge_qm31()?;
    let chi = transcript.challenge_qm31()?;
    let mut h1 = match mode {
        StateOnlyFrontMode::Base(_) => build_state_only_copy_helper_v4(trace, lambda, chi)?,
        StateOnlyFrontMode::Atomic(_) => build_atomic_state_only_copy_helper_v3(trace, lambda, chi)
            .map_err(|_| StateOnlyPrefixBuildError::Shape)?,
    };
    match mode {
        StateOnlyFrontMode::Base(_) => apply_state_only_h1_padding_mask(&mut h1, h1_padding)?,
        StateOnlyFrontMode::Atomic(_) => {
            apply_atomic_state_only_h1_padding_mask_v3(&mut h1, h1_padding)?
        }
    }
    if state_only_copy_helper_sum(&h1) != Some(QM31::ZERO) {
        return Err(StateOnlyPrefixBuildError::Shape);
    }
    let c2_messages = [h1.clone(), g.to_vec()];
    let encoded_c2 = encode_state_only_c2_columns(&encoder, &c2_messages)?;
    let c2_leaves = state_only_c2_layer0_leaves(&encoded_c2, encoder.codeword_len())?;
    let (_, c2_root) = state_only_layer0_roots(&c1_leaves, &c2_leaves, hash)?;
    transcript.absorb(label::M31_CIRCLE_C2_ROOT, &c2_root);
    let batching = begin_state_only_zerocheck(&mut transcript)?;
    let masked = prove_masked_state_only_zerocheck(
        &mut transcript,
        precommit_binding,
        trace,
        mask_only_c1,
        g,
        |point| match mode {
            StateOnlyFrontMode::Base(public) => {
                let openings = state_only_point_openings(trace, &h1, g, point)?;
                state_only_unmasked_terminal_value(public, &openings, point, &batching, lambda, chi)
            }
            StateOnlyFrontMode::Atomic(statement) => {
                let claims = statement_evaluations(trace, mask_only_c1, &h1, g, point)
                    .map_err(|_| StateOnlyConstraintError::Shape)?;
                atomic_state_only_selected_unmasked_terminal_value_compiled_v3(
                    statement,
                    &claims,
                    point,
                    lambda,
                    chi,
                    batching.theta,
                    &batching.zerocheck_point,
                    batching.mu,
                )
                .map_err(|_| StateOnlyConstraintError::Shape)
            }
        },
    )?;
    let initial_mask_claim = masked.initial_mask_claim;
    let eta = masked.eta;
    let zerocheck = masked.sumcheck;
    let evaluations = statement_evaluations(trace, mask_only_c1, &h1, g, &zerocheck.challenges)?;
    let mut material = StateOnlyPrefixMaterial::front(
        shape,
        mask_nonce,
        c1_root,
        c2_root,
        initial_mask_claim,
        &zerocheck,
        evaluations,
    );
    let mut bytes = serialize_state_only_prefix(&material);
    transcript.absorb(label::M31_CIRCLE_STATEMENT_POINTS, &{
        let points = [
            zerocheck.challenges,
            successor_point(&zerocheck.challenges),
            xor12_point(&zerocheck.challenges),
        ];
        let mut encoded = [0u8; 480];
        for (point, coordinates) in points.iter().enumerate() {
            for (coordinate, value) in coordinates.iter().enumerate() {
                value.write_le_bytes(&mut encoded[(point * 10 + coordinate) * 16..][..16]);
            }
        }
        encoded
    });
    transcript.absorb(
        label::M31_CIRCLE_STATEMENT_EVALUATIONS,
        &bytes[STATE_ONLY_PREFIX_OFFSETS.statement_evaluations_start
            ..STATE_ONLY_PREFIX_OFFSETS.statement_evaluations_start
                + STATE_ONLY_STATEMENT_VALUE_COUNT * 16],
    );
    material.batch_nonce = match pow_mode {
        StateOnlyPowMode::UnminedZero => 0,
        StateOnlyPowMode::Mine => {
            crate::find_grinding_nonce(&transcript, shape.batch_grinding_bits)
        }
    };
    let batch_pow_valid = transcript.grinding_ok(material.batch_nonce, shape.batch_grinding_bits);
    transcript.absorb(
        label::M31_PAYMENT_BATCH_POW_NONCE,
        &material.batch_nonce.to_le_bytes(),
    );
    let _gamma = transcript.challenge_qm31()?;
    let _point_scale = transcript.challenge_qm31()?;
    bytes = serialize_state_only_prefix(&material);
    let parsed = StateOnlyCandidatePrefix::parse_exact(&bytes)?;
    let schedule = match mode {
        StateOnlyFrontMode::Base(_) => {
            run_state_only_prefix_schedule_host(hash, &parsed, &statement_digest)?
        }
        StateOnlyFrontMode::Atomic(_) => {
            run_atomic_state_only_prefix_schedule_host_v3(hash, &parsed, &statement_digest)?
        }
    };
    if schedule.lambda != lambda
        || schedule.chi != chi
        || schedule.batching != batching
        || schedule.eta != eta
        || schedule.z != zerocheck.challenges
        || schedule.masked_terminal_claim != zerocheck.terminal_claim
    {
        return Err(StateOnlyPrefixBuildError::Shape);
    }
    Ok(BuiltStateOnlyPrefixFront {
        bytes,
        material,
        schedule,
        trace: trace.clone(),
        h1,
        g: g.to_vec(),
        mask_only_c1: mask_only_c1.clone(),
        encoded_c1,
        encoded_c2,
        c1_leaves,
        c2_leaves,
        zerocheck,
        transcript_after_gamma: transcript,
        batch_pow_valid,
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    fn q(seed: u32) -> QM31 {
        QM31 {
            c0: CM31::new(M31(seed * 17 + 1), M31(seed * 19 + 3)),
            c1: CM31::new(M31(seed * 23 + 5), M31(seed * 29 + 7)),
        }
    }

    #[test]
    fn direct_statement_evaluations_match_the_previous_nested_opening_path() {
        let trace = StateOnlyTraceFoundation {
            c1: core::array::from_fn(|column| {
                (0..1024)
                    .map(|row| M31((row * 131 + column * 17 + 1) as u32))
                    .collect()
            }),
        };
        let mask_only_c1 = core::array::from_fn(|column| {
            (0..1024)
                .map(|row| M31((row * 43 + column * 211 + 9) as u32))
                .collect()
        });
        let h1 = (0..1024)
            .map(|row| q(row as u32 + 1_000))
            .collect::<Vec<_>>();
        let g = (0..1024)
            .map(|row| q(row as u32 + 3_000))
            .collect::<Vec<_>>();

        let points = [
            core::array::from_fn(|coordinate| q(coordinate as u32 + 11)),
            core::array::from_fn(|coordinate| {
                if coordinate == 0 {
                    q(101)
                } else if coordinate & 1 == 0 {
                    QM31::ZERO
                } else {
                    QM31::ONE
                }
            }),
            core::array::from_fn(|coordinate| {
                if coordinate < 5 {
                    q(coordinate as u32 + 211)
                } else if coordinate & 1 == 0 {
                    QM31::ONE
                } else {
                    QM31::ZERO
                }
            }),
            core::array::from_fn(|coordinate| {
                if coordinate & 1 == 0 {
                    QM31::ZERO
                } else {
                    QM31::ONE
                }
            }),
        ];

        for point in points {
            assert_eq!(
                statement_evaluations(&trace, &mask_only_c1, &h1, &g, &point).unwrap(),
                statement_evaluations_reference(&trace, &mask_only_c1, &h1, &g, &point).unwrap(),
            );
        }
    }
}

/// R0's semantic builder, ending before R-D's opening row 27. It accepts a
/// commitment backend because SPEC §9 leaves the R552 authentication format
/// to the opening owner. The backend is handed exactly the frozen ordered
/// C1/C2 lane sets; it must commit their natural-code words without R16.
#[cfg(feature = "r0")]
pub mod r0 {
    use super::*;
    use aspis_core::field::{WideExact, P};
    use aspis_core::r0::{domain::Point, encoder::eval_message};
    use aspis_core::state_only_prefix::r0::{self as wire, Challenges, Error, SemanticTranscript};
    use aspis_statement::pool_v1::{
        pair_forest_semantic_oracle::build_pool_v1_pair_forest_copy_helper_v1,
        pair_forest_semantic_terminal::r0::Public,
        pair_forest_trace::PoolV1PairForestMergedC1CompilationV1,
    };

    #[derive(Clone, Copy)]
    pub enum Column<'a> {
        Base(&'a [M31; 1024]),
        Extension(&'a [QM31; 1024]),
    }
    /// Backend errors cause an abort, never a retry or a challenge filter.
    pub trait Commitments {
        fn c1(&mut self, columns: [Column<'_>; 27]) -> Result<[u8; 32], Error>;
        fn c2(&mut self, columns: [&[QM31; 1024]; 2]) -> Result<[u8; 32], Error>;
    }
    pub struct BuiltSemantics {
        pub bytes: Vec<u8>,
        pub transcript: SemanticTranscript,
        pub challenges: Challenges,
        pub alpha: [QM31; 10],
        /// Opening integration starts with this row-25 state, bound roots,
        /// and the 25 challenges (not the later diagnostic row-27 state).
        pub state_before_z0: [u8; 32],
        pub roots: [[u8; 32]; 2],
        pub columns: [Vec<QM31>; 29],
        pub z: [aspis_core::circle::SecureCirclePoint; 2],
    }
    fn lift(x: M31) -> QM31 {
        QM31::from_cm31(aspis_core::field::CM31::from_m31(x))
    }
    pub fn point_claims(
        columns: &[Vec<QM31>; 29],
        point: &[QM31; 10],
    ) -> Result<[[QM31; 29]; 3], Error> {
        let mut claims = [[QM31::ZERO; 29]; 3];
        for (p, at) in wire::statement_points(point).iter().enumerate() {
            for (lane, column) in columns.iter().enumerate() {
                claims[p][lane] = multilinear_evaluate_qm31(column, at).ok_or(Error::Public)?;
            }
        }
        Ok(claims)
    }

    /// The H1 closure is invoked only after the C1 root and lambda/chi. It
    /// lets a prepared/masked PF trace retain its existing ZR1 pole abort.
    /// The actual sumcheck oracle is always Public::terminal_qm31 (PF).
    #[allow(clippy::too_many_arguments)]
    pub fn build_with_helper(
        public: Public<'_>,
        c1: &[Vec<M31>; 26],
        d: &[QM31; 1024],
        g: &[QM31; 1024],
        helper: impl FnOnce(QM31, QM31) -> Result<Vec<QM31>, Error>,
        commitments: &mut impl Commitments,
        hash: HashFn,
    ) -> Result<BuiltSemantics, Error> {
        build_with_helper_mode(public, c1, d, g, helper, commitments, hash, false)
    }

    #[allow(clippy::too_many_arguments)]
    fn build_with_helper_mode(
        public: Public<'_>,
        c1: &[Vec<M31>; 26],
        d: &[QM31; 1024],
        g: &[QM31; 1024],
        helper: impl FnOnce(QM31, QM31) -> Result<Vec<QM31>, Error>,
        commitments: &mut impl Commitments,
        hash: HashFn,
        transported_endpoints: bool,
    ) -> Result<BuiltSemantics, Error> {
        // Reject raw noncanonical constructors rather than normalize their
        // commitment representation. D is supplied before any challenge.
        if c1
            .iter()
            .any(|v| v.len() != 1024 || v.iter().any(|x| x.0 >= P))
            || d.iter().chain(g).any(|x| {
                QM31::from_le_bytes(&{
                    let mut b = [0; 16];
                    x.write_le_bytes(&mut b);
                    b
                })
                .is_none()
            })
        {
            return Err(Error::Public);
        }
        let base: [&[M31; 1024]; 26] =
            core::array::from_fn(|i| c1[i].as_slice().try_into().unwrap());
        let first = core::array::from_fn(|i| {
            if i < 26 {
                Column::Base(base[i])
            } else {
                Column::Extension(d)
            }
        });
        let c1_root = commitments.c1(first)?;
        let mut transcript = SemanticTranscript::new(hash, &public.public_bytes()?, &c1_root)?;
        let mut bytes = c1_root.to_vec();
        let mut scalar = |row, payload: &[u8], transcript: &mut SemanticTranscript| {
            let framed = wire::record(row, payload)?;
            let value = transcript.semantic(row, &framed)?;
            bytes.extend_from_slice(&framed);
            Ok::<QM31, Error>(value)
        };
        let lambda = scalar(0, &[], &mut transcript)?;
        let chi = scalar(1, &[], &mut transcript)?;
        let h1 = helper(lambda, chi)?;
        let h1: &[QM31; 1024] = h1.as_slice().try_into().map_err(|_| Error::Public)?;
        if state_only_copy_helper_sum(h1) != Some(QM31::ZERO) {
            return Err(Error::Public);
        }
        let c2_root = commitments.c2([h1, g])?;
        let theta = scalar(2, &c2_root, &mut transcript)?;
        let mut zc = [QM31::ZERO; 10];
        for (i, value) in zc.iter_mut().enumerate() {
            *value = scalar(3 + i as u8, &[], &mut transcript)?;
        }
        let mu = scalar(13, &[], &mut transcript)?;
        let columns: [Vec<QM31>; 29] = core::array::from_fn(|lane| match lane {
            0..=25 => c1[lane].iter().copied().map(lift).collect(),
            26 => h1.to_vec(),
            27 => g.to_vec(),
            _ => d.to_vec(),
        });
        let mut mask_sum = QM31::ZERO;
        for row in 0..1024 {
            let point = core::array::from_fn(|i| {
                if (row >> (9 - i)) & 1 == 0 {
                    QM31::ZERO
                } else {
                    QM31::ONE
                }
            });
            mask_sum = mask_sum.add(
                aspis_core::state_only_hiding::state_only_selected_mask_value(
                    &core::array::from_fn(|i| columns[i][row]),
                    &core::array::from_fn(|i| columns[16 + i][row]),
                    columns[27][row],
                    &point,
                ),
            );
        }
        let eta = scalar(
            14,
            &WideExact::from_qm31(mask_sum).to_le_bytes(),
            &mut transcript,
        )?;
        let challenges = Challenges {
            lambda,
            chi,
            theta,
            zc,
            mu,
            eta,
        };
        let (alpha, _) = crate::state_only_hiding::r0::prove_sumcheck(
            &mut transcript,
            &mut bytes,
            mask_sum,
            |point| {
                let claims = point_claims(&columns, point)?;
                let terminal = public.terminal_qm31(&claims, point, &challenges)?;
                let mask = aspis_core::state_only_hiding::state_only_selected_mask_value(
                    &core::array::from_fn(|i| claims[0][i]),
                    &core::array::from_fn(|i| claims[0][16 + i]),
                    claims[0][27],
                    point,
                );
                Ok(mask.add(eta.mul(terminal)))
            },
        )?;
        let claims = point_claims(&columns, &alpha)?;
        let state_before_z0 = transcript.state();
        let before_z0 = wire::record(
            25,
            &wire::encode_values(claims.into_iter().flatten().map(WideExact::from_qm31)),
        )?;
        let z0 = transcript.challenge_reference_circle_point(25, &before_z0)?;
        bytes.extend_from_slice(&before_z0);
        let endpoint = columns.iter().map(|col| {
            let message: &[QM31; 1024] = col.as_slice().try_into().unwrap();
            let coefficients;
            let message = if transported_endpoints {
                coefficients = aspis_core::r0::transport::to_coefficients(message);
                &coefficients
            } else {
                message
            };
            WideExact::from_qm31(eval_message(message, Point { x: z0.x, y: z0.y }))
        });
        let before_z1 = wire::record(26, &wire::encode_values(endpoint))?;
        let z1 = transcript.challenge_reference_circle_point(26, &before_z1)?;
        bytes.extend_from_slice(&before_z1);
        if z0 == z1 {
            return Err(Error::EqualCirclePoints);
        }
        Ok(BuiltSemantics {
            bytes,
            transcript,
            challenges,
            alpha,
            state_before_z0,
            roots: [c1_root, c2_root],
            columns,
            z: [z0, z1],
        })
    }

    /// Ordinary PF helper construction, retaining the existing active-pole
    /// abort. No chi retry and no nonzero filtering of eta is introduced.
    #[allow(clippy::too_many_arguments)]
    pub fn build_pair_forest(
        public: Public<'_>,
        compiled: &PoolV1PairForestMergedC1CompilationV1,
        mask_only: &[Vec<M31>; 10],
        d: &[QM31; 1024],
        g: &[QM31; 1024],
        commitments: &mut impl Commitments,
        hash: HashFn,
    ) -> Result<BuiltSemantics, Error> {
        build_pair_forest_mode(public, compiled, mask_only, d, g, commitments, hash, false)
    }

    /// R-E continuation: row 26 evaluates the committed D13 coefficients.
    /// This avoids an unused raw-row z1 (and its possible equality abort)
    /// before the actual opening transcript. Historical semantic KATs retain
    /// the original diagnostic builder above.
    #[allow(clippy::too_many_arguments)]
    pub fn build_pair_forest_transported(
        public: Public<'_>,
        compiled: &PoolV1PairForestMergedC1CompilationV1,
        mask_only: &[Vec<M31>; 10],
        d: &[QM31; 1024],
        g: &[QM31; 1024],
        commitments: &mut impl Commitments,
        hash: HashFn,
    ) -> Result<BuiltSemantics, Error> {
        build_pair_forest_mode(public, compiled, mask_only, d, g, commitments, hash, true)
    }

    #[allow(clippy::too_many_arguments)]
    fn build_pair_forest_mode(
        public: Public<'_>,
        compiled: &PoolV1PairForestMergedC1CompilationV1,
        mask_only: &[Vec<M31>; 10],
        d: &[QM31; 1024],
        g: &[QM31; 1024],
        commitments: &mut impl Commitments,
        hash: HashFn,
        transported_endpoints: bool,
    ) -> Result<BuiltSemantics, Error> {
        if compiled.semantic_c1.c1.len() != 16 || &compiled.public_statement != public.transition()
        {
            return Err(Error::Public);
        }
        let c1 = core::array::from_fn(|i| {
            if i < 16 {
                compiled.semantic_c1.c1[i].clone()
            } else {
                mask_only[i - 16].clone()
            }
        });
        build_with_helper_mode(
            public,
            &c1,
            d,
            g,
            |lambda, chi| {
                build_pool_v1_pair_forest_copy_helper_v1(
                    &compiled.trace,
                    public.transition().live_snapshot.next_pair_index,
                    lambda,
                    chi,
                )
                .map_err(|_| Error::Public)
            },
            commitments,
            hash,
            transported_endpoints,
        )
    }
}

crates/aspis-prover/src/state_only_circl:
//! Sequential three-point OOD/fold relation for the state-only profile.

use aspis_core::circle::SecureCirclePoint;
use aspis_core::circle_fri::FIXED_TRACE_LOG_SIZE;
use aspis_core::circle_prefix::{
    CANDIDATE_FINAL_POLY_LEN, CANDIDATE_OOD_SAMPLES, CANDIDATE_ROUND_COUNT,
};
use aspis_core::field::QM31;
use aspis_core::state_only_masked_switch_basis::{
    masked_switch_logical_to_natural, MASKED_SWITCH_UNIVERSAL_DIMENSION,
};
use aspis_core::sumcheck::{
    boundary_sum, evaluate, polynomial_for_extension, SumcheckPolynomial, WeightAccumulator,
};
use aspis_statement::state_only_copy_inactive_row_masks_v4;
#[cfg(test)]
use aspis_statement::{state_only_copy_active_rows_v4, state_only_copy_inactive_indicator_v4};

use crate::circle_candidate::CandidatePrefixBuildError;
use crate::circle_candidate::{fold_adjacent_natural_arity4, TRACE_LEN};

pub const STATE_ONLY_RELATION_POINT_COUNT: usize = 3;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct StateOnlyCircleRelationTrace {
    pub point_claims: [QM31; STATE_ONLY_RELATION_POINT_COUNT],
    pub ood_values: [[QM31; CANDIDATE_OOD_SAMPLES]; CANDIDATE_ROUND_COUNT],
    pub boundary_claims: [QM31; CANDIDATE_ROUND_COUNT],
    pub sumchecks: [SumcheckPolynomial; CANDIDATE_ROUND_COUNT],
    pub running_claims: [QM31; CANDIDATE_ROUND_COUNT + 1],
    pub final_coefficients: [QM31; CANDIDATE_FINAL_POLY_LEN],
    pub terminal_claim: QM31,
}

pub struct StateOnlyIncrementalRelation {
    coefficients: Vec<QM31>,
    weights: WeightAccumulator,
    point_claims: [QM31; STATE_ONLY_RELATION_POINT_COUNT],
    ood_values: [[QM31; CANDIDATE_OOD_SAMPLES]; CANDIDATE_ROUND_COUNT],
    boundary_claims: [QM31; CANDIDATE_ROUND_COUNT],
    sumchecks: [SumcheckPolynomial; CANDIDATE_ROUND_COUNT],
    running_claims: [QM31; CANDIDATE_ROUND_COUNT + 1],
    running_claim: QM31,
    round: usize,
    samples: usize,
}

fn volatile_clear_qm31(values: &mut [QM31]) {
    for value in values {
        // SAFETY: relation storage is uniquely borrowed during drop.
        unsafe { core::ptr::write_volatile(value, QM31::ZERO) };
    }
    core::sync::atomic::compiler_fence(core::sync::atomic::Ordering::SeqCst);
}

impl Drop for StateOnlyIncrementalRelation {
    fn drop(&mut self) {
        volatile_clear_qm31(&mut self.coefficients);
        volatile_clear_qm31(&mut self.point_claims);
        for values in &mut self.ood_values {
            volatile_clear_qm31(values);
        }
        volatile_clear_qm31(&mut self.boundary_claims);
        for polynomial in &mut self.sumchecks {
            volatile_clear_qm31(polynomial);
        }
        volatile_clear_qm31(&mut self.running_claims);
        volatile_clear_qm31(core::slice::from_mut(&mut self.running_claim));
        self.round = 0;
        self.samples = 0;
    }
}

impl StateOnlyIncrementalRelation {
    pub fn new(
        coefficients: Vec<QM31>,
        points: &[[QM31; FIXED_TRACE_LOG_SIZE as usize]; STATE_ONLY_RELATION_POINT_COUNT],
        point_scales: [QM31; STATE_ONLY_RELATION_POINT_COUNT],
    ) -> Result<Self, CandidatePrefixBuildError> {
        Self::new_with_inactive_masks(
            coefficients,
            points,
            point_scales,
            state_only_copy_inactive_row_masks_v4(),
        )
    }

    pub fn new_with_inactive_masks(
        coefficients: Vec<QM31>,
        points: &[[QM31; FIXED_TRACE_LOG_SIZE as usize]; STATE_ONLY_RELATION_POINT_COUNT],
        point_scales: [QM31; STATE_ONLY_RELATION_POINT_COUNT],
        inactive_masks: [u16; 64],
    ) -> Result<Self, CandidatePrefixBuildError> {
        Self::new_with_inactive_masks_and_claim(
            coefficients,
            points,
            point_scales,
            inactive_masks,
            QM31::ZERO,
        )
    }

    /// Construct the same relation with an explicitly carried copy-inactive
    /// target. Production trace masks use target zero; physically bound
    /// unbalanced auxiliary words instead serialize this target before their
    /// PCS group separator is sampled.
    pub fn new_with_inactive_masks_and_claim(
        coefficients: Vec<QM31>,
        points: &[[QM31; FIXED_TRACE_LOG_SIZE as usize]; STATE_ONLY_RELATION_POINT_COUNT],
        point_scales: [QM31; STATE_ONLY_RELATION_POINT_COUNT],
        inactive_masks: [u16; 64],
        inactive_claim: QM31,
    ) -> Result<Self, CandidatePrefixBuildError> {
        if coefficients.len() != TRACE_LEN {
            return Err(CandidatePrefixBuildError::Consistency(
                "state-only combined message has the wrong length",
            ));
        }
        let actual_inactive_claim =
            coefficients
                .iter()
                .copied()
                .enumerate()
                .fold(QM31::ZERO, |sum, (row, value)| {
                    if inactive_masks[row >> 4] & (1 << (row & 15)) == 0 {
                        sum
                    } else {
                        sum.add(value)
                    }
                });
        if actual_inactive_claim != inactive_claim {
            return Err(CandidatePrefixBuildError::Consistency(
                "state-only combined copy-inactive claim mismatches its carried target",
            ));
        }
        let mut weights = WeightAccumulator::empty(FIXED_TRACE_LOG_SIZE);
        let mut point_claims = [QM31::ZERO; STATE_ONLY_RELATION_POINT_COUNT];
        let mut running_claim = inactive_claim;
        for index in 0..STATE_ONLY_RELATION_POINT_COUNT {
            let mut evaluation = WeightAccumulator::empty(FIXED_TRACE_LOG_SIZE);
            evaluation.add_multilinear(QM31::ONE, points[index].to_vec())?;
            point_claims[index] = evaluation.dot(&coefficients);
            weights.add_multilinear(point_scales[index], points[index].to_vec())?;
            running_claim = running_claim.add(point_scales[index].mul(point_claims[index]));
        }
        weights.add_grouped_64x16_binary_masks(inactive_masks)?;
        let mut running_claims = [QM31::ZERO; CANDIDATE_ROUND_COUNT + 1];
        running_claims[0] = running_claim;
        Ok(Self {
            coefficients,
            weights,
            point_claims,
            ood_values: [[QM31::ZERO; CANDIDATE_OOD_SAMPLES]; CANDIDATE_ROUND_COUNT],
            boundary_claims: [QM31::ZERO; CANDIDATE_ROUND_COUNT],
            sumchecks: [[QM31::ZERO; 7]; CANDIDATE_ROUND_COUNT],
            running_claims,
            running_claim,
            round: 0,
            samples: 0,
        })
    }

    pub fn evaluate_circle_ood(
        &self,
        point: SecureCirclePoint,
    ) -> Result<QM31, CandidatePrefixBuildError> {
        if self.round != 0 || self.samples >= CANDIDATE_OOD_SAMPLES {
            return Err(CandidatePrefixBuildError::Consistency(
                "state-only circle OOD requested out of order",
            ));
        }
        let mut evaluation = WeightAccumulator::empty(FIXED_TRACE_LOG_SIZE);
        evaluation.add_circle_tensor(QM31::ONE, point)?;
        Ok(evaluation.dot(&self.coefficients))
    }

    pub fn add_circle_ood(
        &mut self,
        point: SecureCirclePoint,
        value: QM31,
        mix: QM31,
    ) -> Result<(), CandidatePrefixBuildError> {
        self.weights.add_circle_tensor(mix, point)?;
        self.ood_values[0][self.samples] = value;
        self.running_claim = self.running_claim.add(mix.mul(value));
        self.samples += 1;
        Ok(())
    }

    pub fn evaluate_line_ood(&self, x: QM31) -> Result<QM31, CandidatePrefixBuildError> {
        if self.round == 0
            || self.round >= CANDIDATE_ROUND_COUNT
            || self.samples >= CANDIDATE_OOD_SAMPLES
        {
            return Err(CandidatePrefixBuildError::Consistency(
                "state-only line OOD requested out of order",
            ));
        }
        let mut evaluation = WeightAccumulator::empty(FIXED_TRACE_LOG_SIZE - 2 * self.round as u32);
        evaluation.add_line_tensor(QM31::ONE, x)?;
        Ok(evaluation.dot(&self.coefficients))
    }

    pub fn add_line_ood(
        &mut self,
        x: QM31,
        value: QM31,
        mix: QM31,
    ) -> Result<(), CandidatePrefixBuildError> {
        self.weights.add_line_tensor(mix, x)?;
        self.ood_values[self.round][self.samples] = value;
        self.running_claim = self.running_claim.add(mix.mul(value));
        self.samples += 1;
        Ok(())
    }

    pub fn polynomial(&mut self) -> Result<SumcheckPolynomial, CandidatePrefixBuildError> {
        if self.samples != CANDIDATE_OOD_SAMPLES {
            return Err(CandidatePrefixBuildError::Consistency(
                "state-only relation sumcheck built before both OOD samples",
            ));
        }
        let polynomial = polynomial_for_extension(&self.coefficients, &self.weights);
        if boundary_sum(&polynomial) != self.running_claim {
            return Err(CandidatePrefixBuildError::Consistency(
                "state-only relation boundary mismatch",
            ));
        }
        self.boundary_claims[self.round] = self.running_claim;
        self.sumchecks[self.round] = polynomial;
        Ok(polynomial)
    }

    pub fn fold(&mut self, alpha: QM31) -> Result<(), CandidatePrefixBuildError> {
        if self.samples != CANDIDATE_OOD_SAMPLES || self.round >= CANDIDATE_ROUND_COUNT {
            return Err(CandidatePrefixBuildError::Consistency(
                "state-only relation fold requested out of order",
            ));
        }
        self.running_claim = evaluate(&self.sumchecks[self.round], alpha);
        self.running_claims[self.round + 1] = self.running_claim;
        self.weights.fold(alpha);
        self.coefficients = fold_adjacent_natural_arity4(&self.coefficients, alpha);
        if self.weights.dot(&self.coefficients) != self.running_claim {
            return Err(CandidatePrefixBuildError::Consistency(
                "state-only folded relation dot mismatch",
            ));
        }
        self.round += 1;
        self.samples = 0;
        Ok(())
    }

    /// Exact profile-21 seam immediately after the circle-to-line fold.
    /// Injects the disclosed natural U polynomial into the committed root-one
    /// word and returns its complete folded-relation target, including all
    /// sixteen randomness coordinates.
    pub fn inject_profile21_first_later_u(
        &mut self,
        logical_u: &[QM31; MASKED_SWITCH_UNIVERSAL_DIMENSION],
    ) -> Result<QM31, CandidatePrefixBuildError> {
        if self.round != 1 || self.samples != 0 || self.coefficients.len() != TRACE_LEN / 4 {
            return Err(CandidatePrefixBuildError::Consistency(
                "profile21 U injection requested outside the first later seam",
            ));
        }
        let natural_u = masked_switch_logical_to_natural(logical_u);
        let target = natural_u
            .iter()
            .copied()
            .enumerate()
            .fold(QM31::ZERO, |sum, (index, value)| {
                sum.add(self.weights.weight_at(index as u32).mul(value))
            });
        for (coefficient, value) in self.coefficients.iter_mut().zip(natural_u) {
            *coefficient = coefficient.add(value);
        }
        self.running_claim = self.running_claim.add(target);
        self.running_claims[self.round] = self.running_claim;
        if self.weights.dot(&self.coefficients) != self.running_claim {
            return Err(CandidatePrefixBuildError::Consistency(
                "profile21 U injection changed the folded relation target",
            ));
        }
        Ok(target)
    }

    /// Evaluate the complete post-alpha relation target of one logical source
    /// word without mutating the relation. This is used before delta to bind
    /// the two scalar claims `tX` and `muF`.
    pub fn profile21_first_later_full_target(
        &self,
        logical: &[QM31; MASKED_SWITCH_UNIVERSAL_DIMENSION],
    ) -> Result<QM31, CandidatePrefixBuildError> {
        if self.round != 1 || self.samples != 0 || self.coefficients.len() != TRACE_LEN / 4 {
            return Err(CandidatePrefixBuildError::Consistency(
                "profile21 full target requested outside the first later seam",
            ));
        }
        Ok(masked_switch_logical_to_natural(logical)
            .iter()
            .copied()
            .enumerate()
            .fold(QM31::ZERO, |sum, (index, value)| {
                sum.add(self.weights.weight_at(index as u32).mul(value))
            }))
    }

    pub fn finish(self) -> Result<StateOnlyCircleRelationTrace, CandidatePrefixBuildError> {
        if self.round != CANDIDATE_ROUND_COUNT
            || self.coefficients.len() != CANDIDATE_FINAL_POLY_LEN
        {
            return Err(CandidatePrefixBuildError::Consistency(
                "state-only relation did not reach terminal",
            ));
        }
        let final_coefficients: [QM31; CANDIDATE_FINAL_POLY_LEN] =
            self.coefficients.as_slice().try_into().map_err(|_| {
                CandidatePrefixBuildError::Consistency("terminal conversion failed")
            })?;
        let terminal_claim = self.weights.dot(&final_coefficients);
        if terminal_claim != self.running_claim {
            return Err(CandidatePrefixBuildError::Consistency(
                "state-only terminal relation dot mismatch",
            ));
        }
        Ok(StateOnlyCircleRelationTrace {
            point_claims: self.point_claims,
            ood_values: self.ood_values,
            boundary_claims: self.boundary_claims,
            sumchecks: self.sumchecks,
            running_claims: self.running_claims,
            final_coefficients,
            terminal_claim,
        })
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use aspis_core::field::{CM31, M31};

    fn q(seed: u32) -> QM31 {
        QM31 {
            c0: CM31::new(M31(seed), M31(seed + 1)),
            c1: CM31::new(M31(seed + 2), M31(seed + 3)),
        }
    }

    #[test]
    fn copy_inactive_registry_is_a_mandatory_zero_claim() {
        let points = [[QM31::ZERO; FIXED_TRACE_LOG_SIZE as usize]; STATE_ONLY_RELATION_POINT_COUNT];
        let scales = [QM31::ONE; STATE_ONLY_RELATION_POINT_COUNT];
        let mut balanced = vec![QM31::ZERO; TRACE_LEN];
        let inactive_indicator = state_only_copy_inactive_indicator_v4();
        let mut inactive_rows = inactive_indicator
            .iter()
            .enumerate()
            .filter_map(|(row, weight)| (*weight == QM31::ONE).then_some(row));
        let first_inactive = inactive_rows.next().unwrap();
        let second_inactive = inactive_rows.next().unwrap();
        balanced[first_inactive] = QM31::ONE;
        balanced[second_inactive] = QM31::ZERO.sub(QM31::ONE);
        assert!(StateOnlyIncrementalRelation::new(balanced, &points, scales).is_ok());

        let mut unbalanced = vec![QM31::ZERO; TRACE_LEN];
        unbalanced[first_inactive] = QM31::ONE;
        assert!(matches!(
            StateOnlyIncrementalRelation::new(unbalanced, &points, scales),
            Err(CandidatePrefixBuildError::Consistency(
                "state-only combined copy-inactive claim mismatches its carried target"
            ))
        ));

        // A malicious active-row discrepancy cannot be hidden by an equal
        // and opposite inactive helper value. The global helper sum would
        // still be zero, but the exact generated inactive-row claim rejects
        // it.
        let mut cancelled = vec![QM31::ZERO; TRACE_LEN];
        let active = usize::from(state_only_copy_active_rows_v4()[0]);
        let inactive_prefix = inactive_indicator
            .iter()
            .position(|weight| *weight == QM31::ONE)
            .unwrap();
        cancelled[active] = QM31::ONE;
        cancelled[inactive_prefix] = QM31::ZERO.sub(QM31::ONE);
        assert_eq!(
            cancelled.iter().copied().fold(QM31::ZERO, QM31::add),
            QM31::ZERO
        );
        assert!(matches!(
            StateOnlyIncrementalRelation::new(cancelled, &points, scales),
            Err(CandidatePrefixBuildError::Consistency(
                "state-only combined copy-inactive claim mismatches its carried target"
            ))
        ));
    }

    #[test]
    fn profile21_prover_injection_matches_full_relation_target_and_finishes() {
        let points: [[QM31; FIXED_TRACE_LOG_SIZE as usize]; STATE_ONLY_RELATION_POINT_COUNT] =
            core::array::from_fn(|point| {
                core::array::from_fn(|coordinate| q(101 + 41 * point as u32 + coordinate as u32))
            });
        let scales = [QM31::ONE, q(401), q(401).square()];
        let inactive_masks =
            aspis_statement::atomic_state_only_terminal::atomic_state_only_copy_inactive_row_masks_v3();
        let mut relation = StateOnlyIncrementalRelation::new_with_inactive_masks(
            vec![QM31::ZERO; TRACE_LEN],
            &points,
            scales,
            inactive_masks,
        )
        .unwrap();

        let circle_points = [
            SecureCirclePoint {
                x: q(701),
                y: q(709),
            },
            SecureCirclePoint {
                x: q(719),
                y: q(727),
            },
        ];
        let circle_mixes = [q(733), q(739)];
        for sample in 0..CANDIDATE_OOD_SAMPLES {
            let value = relation.evaluate_circle_ood(circle_points[sample]).unwrap();
            relation
                .add_circle_ood(circle_points[sample], value, circle_mixes[sample])
                .unwrap();
        }
        relation.polynomial().unwrap();
        let alpha0 = q(751);
        relation.fold(alpha0).unwrap();

        let logical_u = core::array::from_fn(|index| q(809 + 11 * index as u32));
        let precomputed_target = relation
            .profile21_first_later_full_target(&logical_u)
            .unwrap();
        let injected_target = relation.inject_profile21_first_later_u(&logical_u).unwrap();
        assert_eq!(injected_target, precomputed_target);

        // Independent verifier construction: deferred masks, same exact OOD
        // components, then the circle-to-line fold.
        let mut verifier_weights = WeightAccumulator::empty(FIXED_TRACE_LOG_SIZE);
        for point in 0..STATE_ONLY_RELATION_POINT_COUNT {
            verifier_weights
                .add_multilinear(scales[point], points[point].to_vec())
                .unwrap();
        }
        verifier_weights
            .add_grouped_64x16_binary_masks_deferred(inactive_masks)
            .unwrap();
        for sample in 0..CANDIDATE_OOD_SAMPLES {
            verifier_weights
                .add_circle_tensor(circle_mixes[sample], circle_points[sample])
                .unwrap();
        }
        verifier_weights.fold(alpha0);
        let natural_u = masked_switch_logical_to_natural(&logical_u);
        assert_eq!(
            injected_target,
            natural_u
                .iter()
                .copied()
                .enumerate()
                .fold(QM31::ZERO, |sum, (index, value)| {
                    sum.add(verifier_weights.weight_at(index as u32).mul(value))
                })
        );

        // The injected full natural polynomial survives every remaining
        // prover fold and reaches the exact terminal dot relation.
        for round in 1..CANDIDATE_ROUND_COUNT {
            for sample in 0..CANDIDATE_OOD_SAMPLES {
                let x = q(1_301 + 31 * round as u32 + sample as u32);
                let mix = q(1_701 + 37 * round as u32 + sample as u32);
                let value = relation.evaluate_line_ood(x).unwrap();
                relation.add_line_ood(x, value, mix).unwrap();
            }
            relation.polynomial().unwrap();
            relation.fold(q(2_003 + 43 * round as u32)).unwrap();
        }
        relation.finish().unwrap();
    }
}

