}

//! Production-neutral affine conditioning for one native full root-zero X lane.
//!
//! This helper deliberately models the literal public X block before its PCS
//! image is admitted into a hiding rank:
//!
//! - all four authenticated layer-zero symbols for each selected query; and
//! - the complete three-point-plus-inactive relation target `tX`.
//!
//! The three X point evaluations are inputs to `tX`, but are not separately
//! serialized by the minimal wire.  `expose_point_evaluations` exists only to
//! compare the strictly wider diagnostic wire which does serialize them.
//!
//! The returned echelon is therefore the image of `epsilon * P(X)` restricted
//! to the kernel of every independently visible X field.  It is a host rank
//! diagnostic only; it does not alter a proof or verifier wire.

use super::*;

pub(super) struct NativeFullXAffineConditioning {
    pub observation_rank_qm31: usize,
    pub conditioned_pcs: ColumnEchelon,
}

#[allow(clippy::too_many_arguments)]
pub(super) fn condition_native_full_x_affine_pcs(
    schedule: &StateOnlyTranscriptScheduleResult,
    layout: RankLayout,
    rows: &[RowPublicMaps],
    full_tails: &[Vec<QM31>],
    epsilon: QM31,
    h_raw_qm31: usize,
    baseline_pcs: &ColumnEchelon,
    expose_target: bool,
    expose_point_evaluations: bool,
) -> Result<NativeFullXAffineConditioning, StateOnlyHidingRankGateError> {
    if epsilon == QM31::ZERO
        || rows.len() != TRACE_ROWS
        || full_tails.len() != TRACE_ROWS
        || rows
            .iter()
            .any(|row| row.layer0_m31.len() != FIBER_SLOTS * schedule.query_count)
    {
        return Err(StateOnlyHidingRankGateError::Shape);
    }

    let relation_weights = initial_relation_weights(schedule, layout)?;
    let inactive_masks = rank_inactive_masks(layout);
    let kappa = schedule.prefix.point_scale;

    // R_q(X) and tX are the minimal public fields. The tX identity is
    // independently reconstructed rather than trusting the
    // accumulated relation covector: this catches omission or inversion of an
    // inactive row in the diagnostic itself.  The optional three point rows
    // are a labelled conservative comparison, not part of the selected wire.
    let observation_qm31 = FIBER_SLOTS * schedule.query_count
        + usize::from(expose_target)
        + 3 * usize::from(expose_point_evaluations);
    let observation_columns = (0..TRACE_ROWS)
        .map(|row| {
            let inactive = if inactive_masks[row >> 4] & (1 << (row & 15)) == 0 {
                QM31::ZERO
            } else {
                QM31::ONE
            };
            let independently_reconstructed_target = rows[row].terminal[0]
                .add(kappa.mul(rows[row].terminal[1]))
                .add(kappa.square().mul(rows[row].terminal[2]))
                .add(inactive);
            let target = relation_weights.weight_at(row as u32);
            if independently_reconstructed_target != target {
                return Err(StateOnlyHidingRankGateError::Relation);
            }

            let mut column = rows[row]
                .layer0_m31
                .iter()
                .copied()
                .map(|value| QM31::from_cm31(CM31::from_m31(value)))
                .collect::<Vec<_>>();
            if expose_point_evaluations {
                column.extend(rows[row].terminal);
            }
            if expose_target {
                column.push(target);
            }
            Ok(column)
        })
        .collect::<Result<Vec<_>, StateOnlyHidingRankGateError>>()?;

    let observation_rank_qm31 = qm31_column_rank(&observation_columns, observation_qm31);
    if observation_rank_qm31 != observation_qm31 {
        return Err(StateOnlyHidingRankGateError::Layout);
    }

    let mut observation = CarryEchelon::new(4 * observation_qm31);
    let mut conditioned_pcs = baseline_pcs.clone();
    for message_row in 0..TRACE_ROWS {
        for tower_coordinate in 0..4 {
            let basis = state_only_mask_tower_basis(tower_coordinate);
            let mut public = Vec::with_capacity(4 * observation_qm31);
            append_qm31_coordinates(
                &mut public,
                observation_columns[message_row]
                    .iter()
                    .copied()
                    .map(|value| value.mul(basis)),
            );
            let pcs =
                first_later_pcs_image(&full_tails[message_row], epsilon.mul(basis), h_raw_qm31);
            if let CarryReduction::Kernel(kernel) = observation.reduce_with_pivot(public, pcs) {
                conditioned_pcs.insert(kernel);
            }
        }
    }
    if observation.rank != 4 * observation_rank_qm31 {
        return Err(StateOnlyHidingRankGateError::Layout);
    }

    Ok(NativeFullXAffineConditioning {
        observation_rank_qm31,
        conditioned_pcs,
    })
}

//! Exact affine conditioning for the reduced, bound natural-B18 switch.
//!
//! The authenticated source code is
//!
//! `V = span{B_18} (+) (x^2+1) P_<16`,
//!
//! in the natural line basis.  X and F are opened through the full four-slot
//! shared-C2 fibers, while `U = F + delta X` is disclosed in this same
//! 17-coordinate basis.  Only the B18 coordinate carries into the old PCS
//! view.  This is a host-only rank object and changes no production wire.

use super::*;

pub(super) struct ReducedNatural18SwitchConditioning {
    pub observation_rank_qm31: usize,
    pub conditioned_pcs: ColumnEchelon,
}

#[allow(clippy::too_many_arguments)]
pub(super) fn condition_reduced_natural18_shared_c2_pcs(
    encoder: &CircleEncoder,
    domain_log: u32,
    schedule: &StateOnlyTranscriptScheduleResult,
    delta: QM31,
    rows: &[RowPublicMaps],
    h_raw_qm31: usize,
    pcs_tail_qm31: usize,
    baseline_pcs: &ColumnEchelon,
) -> Result<ReducedNatural18SwitchConditioning, StateOnlyHidingRankGateError> {
    const RANDOMNESS: usize = 16;
    const DIMENSION: usize = 17;
    const NATURAL_DIMENSION: usize = 19;
    const HIGH: usize = 18;
    if schedule.query_count != RANDOMNESS
        || domain_log != STATE_ONLY_LOG_ROWS + 9
        || delta == QM31::ZERO
        || rows.len() != TRACE_ROWS
    {
        return Err(StateOnlyHidingRankGateError::Shape);
    }
    let queries = &schedule.queries[..schedule.query_count];
    let certificate = profile21_high_switch_carry_certificate(queries)?;
    if certificate.evaluation_plus_leading_rank_qm31 != 17 {
        return Err(StateOnlyHidingRankGateError::Layout);
    }

    let conversion = ordinary_monomials_in_natural_line_basis(NATURAL_DIMENSION);
    let mut code_basis = Vec::with_capacity(DIMENSION);
    let mut b18 = vec![M31::ZERO; NATURAL_DIMENSION];
    b18[HIGH] = M31::ONE;
    code_basis.push(b18);
    for degree in 0..RANDOMNESS {
        code_basis.push(
            conversion[degree]
                .iter()
                .copied()
                .zip(conversion[degree + 2].iter().copied())
                .map(|(low, high)| low.add(high))
                .collect(),
        );
    }
    let mut basis_rank = ColumnEchelon::new(NATURAL_DIMENSION);
    for column in &code_basis {
        basis_rank.insert(column.clone());
    }
    if basis_rank.rank != DIMENSION {
        return Err(StateOnlyHidingRankGateError::Layout);
    }

    let raw_natural = (0..NATURAL_DIMENSION)
        .map(|coefficient| first_layer0_coefficient_query_fibers(encoder, coefficient, queries))
        .collect::<Result<Vec<_>, _>>()?;
    let raw_code = code_basis
        .iter()
        .map(|coefficients| combine_natural_qm31_columns(&raw_natural, coefficients))
        .collect::<Result<Vec<_>, _>>()?;
    if qm31_column_rank(&raw_code, FIBER_SLOTS * RANDOMNESS) != RANDOMNESS {
        return Err(StateOnlyHidingRankGateError::Layout);
    }

    // Column order is X[0..17], F[0..17].  The independently public block is
    // U[17], raw-X[64], raw-F[64].  Keeping both raw blocks in the matrix pins
    // the exact shared-leaf byte View; their linear dependence through U is
    // discovered by elimination rather than pre-deleted.
    let observation_qm31 = DIMENSION + 2 * FIBER_SLOTS * RANDOMNESS;
    let columns = (0..2 * DIMENSION)
        .map(|variable| {
            let is_f = variable >= DIMENSION;
            let coordinate = variable % DIMENSION;
            let mut column = vec![QM31::ZERO; observation_qm31];
            column[coordinate] = if is_f { QM31::ONE } else { delta };
            let raw_start = DIMENSION + usize::from(is_f) * FIBER_SLOTS * RANDOMNESS;
            column[raw_start..raw_start + FIBER_SLOTS * RANDOMNESS]
                .copy_from_slice(&raw_code[coordinate]);
            column
        })
        .collect::<Vec<_>>();
    let observation_rank_qm31 = qm31_column_rank(&columns, observation_qm31);
    if observation_rank_qm31 != DIMENSION + RANDOMNESS {
        return Err(StateOnlyHidingRankGateError::Layout);
    }

    let mut observation = CarryEchelon::new(4 * observation_qm31);
    let mut conditioned_pcs = baseline_pcs.clone();
    for variable in 0..2 * DIMENSION {
        for tower_coordinate in 0..4 {
            let basis = state_only_mask_tower_basis(tower_coordinate);
            let mut public = Vec::with_capacity(4 * observation_qm31);
            append_qm31_coordinates(
                &mut public,
                columns[variable]
                    .iter()
                    .copied()
                    .map(|value| value.mul(basis)),
            );
            let carry = if variable == 0 {
                combined_pcs_image(rows, FIBER_SLOTS * HIGH, basis, h_raw_qm31, pcs_tail_qm31)
            } else {
                vec![M31::ZERO; 4 * (h_raw_qm31 + pcs_tail_qm31)]
            };
            if let CarryReduction::Kernel(kernel) = observation.reduce_with_pivot(public, carry) {
                conditioned_pcs.insert(kernel);
            }
        }
    }
    if observation.rank != 4 * observation_rank_qm31 {
        return Err(StateOnlyHidingRankGateError::Layout);
    }

    Ok(ReducedNatural18SwitchConditioning {
        observation_rank_qm31,
        conditioned_pcs,
    })
}

//! Exact, production-neutral two-variable restriction-kernel rank probe.
//!
//! Every ten-variable word is lifted to twelve variables by duplicating it
//! across the two new most-significant Boolean coordinates `(s,t)`.  Public
//! evaluation is restricted to `(s,t)=(c,d)`.  A promotable construction must
//! take `c,d` in M31: otherwise a malicious M31 physical word can restrict to
//! an extension-valued logical trace unless a separate subcode check is added.
//! Extension-valued slices are therefore diagnostic only.  The existing `G` oracle gets
//! three independent full-QM31 masks
//!
//! ```text
//! (s-c) R1 + (t-d) R2 + (s-c)(t-d) R3.
//! ```
//!
//! The masks vanish identically on the statement slice.  This file only
//! measures the exact linear transcript image; it does not alter the prover,
//! verifier, transcript, or accepted proof format.

use super::*;

const TWO_VARIABLE_LOG_ROWS: u32 = STATE_ONLY_LOG_ROWS + 2;
const TWO_VARIABLE_TRACE_ROWS: usize = 1 << TWO_VARIABLE_LOG_ROWS;
const TWO_VARIABLE_FINAL_COEFFICIENTS: usize =
    TWO_VARIABLE_TRACE_ROWS / FIBER_SLOTS.pow(CANDIDATE_ROUND_COUNT as u32);
const RESTRICTION_KERNEL_MASKS: usize = 3;

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct AtomicProfile21TwoVariableSliceLiftRankReport {
    pub query_count: usize,
    pub message_log: u32,
    pub codeword_domain_log: u32,
    pub codeword_len: usize,
    pub rate_denominator: usize,
    pub final_coefficients_qm31: usize,
    pub slice_c_coordinates_m31: [u32; 4],
    pub slice_d_coordinates_m31: [u32; 4],
    pub initial_restriction_guard: bool,
    pub terminal_zero_guard: bool,
    pub sparse_dense_differential_guard: bool,
    pub sparse_dense_differential_rows: Vec<usize>,
    pub masked_sumcheck_rank_m31: usize,
    pub g_raw_rank_m31: usize,
    pub restriction_raw_kernel_m31: [usize; RESTRICTION_KERNEL_MASKS],
    pub baseline_pcs_rank_m31: usize,
    pub restriction_incremental_pcs_rank_m31: [usize; RESTRICTION_KERNEL_MASKS],
    pub restriction_incremental_new_pivots_m31: [Vec<usize>; RESTRICTION_KERNEL_MASKS],
    pub restriction_pcs_rank_m31: usize,
    pub semantic_augmented_rank_m31: usize,
    pub semantic_new_pivots_m31: Vec<usize>,
    pub legal_sumcheck_augmented_rank_m31: usize,
    pub legal_sumcheck_new_pivots_m31: Vec<usize>,
    pub contains_conservative_semantic_and_legal_sumcheck: bool,
    pub restriction_minor: RankMinorProvenance,
    pub semantic_minor: RankMinorProvenance,
    pub legal_sumcheck_minor: RankMinorProvenance,
    pub elapsed_millis: u128,
}

#[derive(Clone)]
struct Qm31RowPublicMaps {
    layer0: Vec<QM31>,
    terminal: [QM31; 3],
    pcs_tail: Vec<QM31>,
}

impl Qm31RowPublicMaps {
    fn zero(layer0: usize, pcs_tail: usize) -> Self {
        Self {
            layer0: vec![QM31::ZERO; layer0],
            terminal: [QM31::ZERO; 3],
            pcs_tail: vec![QM31::ZERO; pcs_tail],
        }
    }

    fn add_scaled_physical(&mut self, physical: &RowPublicMaps, scale: QM31) {
        for (output, &value) in self.layer0.iter_mut().zip(&physical.layer0_m31) {
            *output = output.add(scale.mul_m31(value));
        }
        for (output, &value) in self.terminal.iter_mut().zip(&physical.terminal) {
            *output = output.add(scale.mul(value));
        }
        for (output, &value) in self.pcs_tail.iter_mut().zip(&physical.pcs_tail) {
            *output = output.add(scale.mul(value));
        }
    }
}

struct SparseRelationSchedule {
    before_round: Vec<Vec<QM31>>,
    polynomial_weights: Vec<Vec<QM31>>,
    evaluations: Vec<[Vec<QM31>; CANDIDATE_OOD_SAMPLES]>,
    final_weights: Vec<QM31>,
}

fn two_variable_point(
    point: &[QM31; STATE_ONLY_HIDING_SUMCHECK_ROUNDS],
    c: QM31,
    d: QM31,
) -> [QM31; STATE_ONLY_HIDING_SUMCHECK_ROUNDS + 2] {
    core::array::from_fn(|coordinate| match coordinate {
        0 => c,
        1 => d,
        _ => point[coordinate - 2],
    })
}

#[inline]
fn physical_row(logical_row: usize, s: usize, t: usize) -> usize {
    debug_assert!(logical_row < TRACE_ROWS && s <= 1 && t <= 1);
    (s << (STATE_ONLY_HIDING_SUMCHECK_ROUNDS + 1))
        | (t << STATE_ONLY_HIDING_SUMCHECK_ROUNDS)
        | logical_row
}

#[inline]
fn slice_bit_weight(bit: usize, value: QM31) -> QM31 {
    if bit == 0 {
        QM31::ONE.sub(value)
    } else {
        value
    }
}

#[inline]
fn restriction_factor(bit: usize, value: QM31) -> QM31 {
    if bit == 0 {
        QM31::ZERO.sub(value)
    } else {
        QM31::ONE.sub(value)
    }
}

fn two_variable_initial_weights(
    schedule: &StateOnlyTranscriptScheduleResult,
    c: QM31,
    d: QM31,
) -> Result<WeightAccumulator, StateOnlyHidingRankGateError> {
    let points = [
        two_variable_point(&schedule.prefix.z, c, d),
        two_variable_point(&binary_successor_point(&schedule.prefix.z), c, d),
        two_variable_point(&xor12_point(&schedule.prefix.z), c, d),
    ];
    let kappa = schedule.prefix.point_scale;
    let mut weights = WeightAccumulator::empty(TWO_VARIABLE_LOG_ROWS);
    for (point, scale) in points.into_iter().zip([QM31::ONE, kappa, kappa.square()]) {
        weights
            .add_multilinear(scale, point.to_vec())
            .map_err(|_| StateOnlyHidingRankGateError::Relation)?;
    }

    let inactive = rank_inactive_masks(RankLayout::AtomicV3);
    let mut dense = vec![QM31::ZERO; TWO_VARIABLE_TRACE_ROWS];
    for logical_row in 0..TRACE_ROWS {
        if ((inactive[logical_row >> 4] >> (logical_row & 15)) & 1) == 0 {
            continue;
        }
        for s in 0..2 {
            for t in 0..2 {
                dense[physical_row(logical_row, s, t)] =
                    slice_bit_weight(s, c).mul(slice_bit_weight(t, d));
            }
        }
    }
    weights
        .add_dense(dense)
        .map_err(|_| StateOnlyHidingRankGateError::Relation)?;
    Ok(weights)
}

fn materialize_weights(weights: &WeightAccumulator, len: usize) -> Vec<QM31> {
    (0..len)
        .map(|index| weights.weight_at(index as u32))
        .collect()
}

fn build_sparse_relation_schedule(
    schedule: &StateOnlyTranscriptScheduleResult,
    c: QM31,
    d: QM31,
) -> Result<SparseRelationSchedule, StateOnlyHidingRankGateError> {
    let mut weights = two_variable_initial_weights(schedule, c, d)?;
    let mut before_round = Vec::with_capacity(CANDIDATE_ROUND_COUNT);
    let mut polynomial_weights = Vec::with_capacity(CANDIDATE_ROUND_COUNT);
    let mut evaluations = Vec::with_capacity(CANDIDATE_ROUND_COUNT);
    let mut len = TWO_VARIABLE_TRACE_ROWS;

    for round in 0..CANDIDATE_ROUND_COUNT {
        before_round.push(materialize_weights(&weights, len));
        let round_evaluations = core::array::from_fn(|sample| {
            let mut evaluation = WeightAccumulator::empty(TWO_VARIABLE_LOG_ROWS - 2 * round as u32);
            let added = if round == 0 {
                evaluation.add_circle_tensor(QM31::ONE, schedule.circle_ood_points[sample])
            } else {
                evaluation.add_line_tensor(QM31::ONE, schedule.line_ood_points[round - 1][sample])
            };
            added.expect("two-variable OOD tensor has the exact round length");
            materialize_weights(&evaluation, len)
        });
        for sample in 0..CANDIDATE_OOD_SAMPLES {
            if round == 0 {
                weights
                    .add_circle_tensor(
                        schedule.mu[round][sample],
                        schedule.circle_ood_points[sample],
                    )
                    .map_err(|_| StateOnlyHidingRankGateError::Relation)?;
            } else {
                weights
                    .add_line_tensor(
                        schedule.mu[round][sample],
                        schedule.line_ood_points[round - 1][sample],
                    )
                    .map_err(|_| StateOnlyHidingRankGateError::Relation)?;
            }
        }
        evaluations.push(round_evaluations);
        polynomial_weights.push(materialize_weights(&weights, len));
        weights.fold(schedule.alpha[round]);
        len /= FIBER_SLOTS;
    }
    let final_weights = materialize_weights(&weights, len);
    if len != TWO_VARIABLE_FINAL_COEFFICIENTS {
        return Err(StateOnlyHidingRankGateError::Shape);
    }
    Ok(SparseRelationSchedule {
        before_round,
        polynomial_weights,
        evaluations,
        final_weights,
    })
}

fn sparse_two_variable_folded_row_value(
    encoder: &CircleEncoder,
    domain_log: u32,
    row: usize,
    schedule: &StateOnlyTranscriptScheduleResult,
    layer: usize,
    index: usize,
    memo: &mut BTreeMap<(usize, usize), QM31>,
) -> Result<QM31, StateOnlyHidingRankGateError> {
    if let Some(value) = memo.get(&(layer, index)) {
        return Ok(*value);
    }
    let value = if layer == 0 {
        QM31::from_cm31(CM31::from_m31(encoder.encode_prefix_basis_value(
            TWO_VARIABLE_LOG_ROWS,
            row,
            index,
        )?))
    } else {
        let mut values = [QM31::ZERO; FIBER_SLOTS];
        for (slot, value) in values.iter_mut().enumerate() {
            *value = sparse_two_variable_folded_row_value(
                encoder,
                domain_log,
                row,
                schedule,
                layer - 1,
                FIBER_SLOTS * index + slot,
                memo,
            )?;
        }
        if layer == 1 {
            aspis_core::circle_fri::normalized_circle_to_line_arity4_at_fiber_for_domain_log(
                values,
                schedule.alpha[0],
                domain_log,
                index,
            )
            .map_err(|_| StateOnlyHidingRankGateError::Encoding)?
        } else {
            normalized_line_arity4_at_fiber_for_domain_log(
                values,
                schedule.alpha[layer - 1],
                domain_log,
                (layer - 1) as u8,
                index,
            )
            .map_err(|_| StateOnlyHidingRankGateError::Encoding)?
        }
    };
    memo.insert((layer, index), value);
    Ok(value)
}

fn sparse_basis_polynomial(scale: QM31, index: usize, weights: &[QM31]) -> [QM31; 7] {
    let slot = index & (FIBER_SLOTS - 1);
    let base = index - slot;
    let dual = [
        weights[base],
        weights[base + 3],
        weights[base + 2],
        weights[base + 1],
    ];
    let mut polynomial = [QM31::ZERO; 7];
    for (degree, weight) in dual.into_iter().enumerate() {
        polynomial[slot + degree] = scale.mul(weight).half().half();
    }
    polynomial
}

fn sparse_basis_fold(scale: QM31, index: usize, alpha: QM31) -> QM31 {
    let alpha2 = alpha.square();
    let alpha3 = alpha2.mul(alpha);
    // This is the primal coefficient fold.  The dual weight accumulator and
    // the relation polynomial carry the 1/4 normalization; coefficients use
    // `[1, alpha, alpha^2, alpha^3]` with no division.
    scale.mul([QM31::ONE, alpha, alpha2, alpha3][index & (FIBER_SLOTS - 1)])
}

fn two_variable_row_pcs_tail(
    encoder: &CircleEncoder,
    domain_log: u32,
    row: usize,
    schedule: &StateOnlyTranscriptScheduleResult,
    later_indices: &[Vec<u32>; CANDIDATE_ROUND_COUNT - 1],
    relation: &SparseRelationSchedule,
) -> Result<Vec<QM31>, StateOnlyHidingRankGateError> {
    let mut index = row;
    let mut scale = QM31::ONE;
    let mut running_claim = relation.before_round[0][index];
    let mut later = Vec::new();
    let mut ood_values = [[QM31::ZERO; CANDIDATE_OOD_SAMPLES]; CANDIDATE_ROUND_COUNT];
    let mut polynomials = [[QM31::ZERO; 7]; CANDIDATE_ROUND_COUNT];
    let mut memo = BTreeMap::new();

    for round in 0..CANDIDATE_ROUND_COUNT {
        if scale.mul(relation.before_round[round][index]) != running_claim {
            return Err(StateOnlyHidingRankGateError::Relation);
        }
        for sample in 0..CANDIDATE_OOD_SAMPLES {
            let value = scale.mul(relation.evaluations[round][sample][index]);
            ood_values[round][sample] = value;
            running_claim = running_claim.add(schedule.mu[round][sample].mul(value));
        }
        let polynomial = sparse_basis_polynomial(scale, index, &relation.polynomial_weights[round]);
        if boundary_sum(&polynomial) != running_claim {
            return Err(StateOnlyHidingRankGateError::Relation);
        }
        polynomials[round] = polynomial;
        running_claim = evaluate_relation(&polynomial, schedule.alpha[round]);
        scale = sparse_basis_fold(scale, index, schedule.alpha[round]);
        index /= FIBER_SLOTS;

        if round + 1 < CANDIDATE_ROUND_COUNT {
            if scale.mul(relation.before_round[round + 1][index]) != running_claim {
                return Err(StateOnlyHidingRankGateError::Relation);
            }
            for &leaf in &later_indices[round] {
                for slot in 0..FIBER_SLOTS {
                    later.push(sparse_two_variable_folded_row_value(
                        encoder,
                        domain_log,
                        row,
                        schedule,
                        round + 1,
                        FIBER_SLOTS * leaf as usize + slot,
                        &mut memo,
                    )?);
                }
            }
        }
    }
    if scale.mul(relation.final_weights[index]) != running_claim {
        return Err(StateOnlyHidingRankGateError::Relation);
    }

    let mut tail = later;
    for values in ood_values {
        tail.extend_from_slice(&values);
    }
    for polynomial in polynomials {
        tail.extend_from_slice(&polynomial);
    }
    let mut final_coefficients = vec![QM31::ZERO; TWO_VARIABLE_FINAL_COEFFICIENTS];
    final_coefficients[index] = scale;
    tail.extend_from_slice(&final_coefficients);
    Ok(tail)
}

fn physical_basis_public_maps(
    encoder: &CircleEncoder,
    domain_log: u32,
    row: usize,
    schedule: &StateOnlyTranscriptScheduleResult,
    indices: &aspis_core::circle_line_merkle::CircleLineQueryIndices,
    terminal_points: &[[QM31; STATE_ONLY_HIDING_SUMCHECK_ROUNDS + 2]; 3],
    relation: &SparseRelationSchedule,
) -> Result<RowPublicMaps, StateOnlyHidingRankGateError> {
    let mut layer0_m31 = Vec::with_capacity(indices.layer0.len() * FIBER_SLOTS);
    for &query in &indices.layer0 {
        for slot in 0..FIBER_SLOTS {
            layer0_m31.push(encoder.encode_prefix_basis_value(
                TWO_VARIABLE_LOG_ROWS,
                row,
                FIBER_SLOTS * query as usize + slot,
            )?);
        }
    }
    Ok(RowPublicMaps {
        layer0_m31,
        terminal: core::array::from_fn(|point| eq_weight_slice(&terminal_points[point], row)),
        pcs_tail: two_variable_row_pcs_tail(
            encoder,
            domain_log,
            row,
            schedule,
            &indices.later,
            relation,
        )?,
    })
}

fn dense_physical_basis_public_maps(
    encoder: &CircleEncoder,
    domain_log: u32,
    row: usize,
    schedule: &StateOnlyTranscriptScheduleResult,
    indices: &aspis_core::circle_line_merkle::CircleLineQueryIndices,
    terminal_points: &[[QM31; STATE_ONLY_HIDING_SUMCHECK_ROUNDS + 2]; 3],
    c: QM31,
    d: QM31,
) -> Result<RowPublicMaps, StateOnlyHidingRankGateError> {
    let mut coefficients = vec![QM31::ZERO; TWO_VARIABLE_TRACE_ROWS];
    coefficients[row] = QM31::ONE;
    let mut codeword = encoder.encode_c2_message_prefix(&coefficients)?;
    let mut layer0_m31 = Vec::with_capacity(indices.layer0.len() * FIBER_SLOTS);
    for &query in &indices.layer0 {
        let start = FIBER_SLOTS * query as usize;
        for &value in &codeword[start..start + FIBER_SLOTS] {
            if value.c0.b != M31::ZERO || value.c1 != CM31::ZERO {
                return Err(StateOnlyHidingRankGateError::Encoding);
            }
            layer0_m31.push(value.c0.a);
        }
    }

    let mut weights = two_variable_initial_weights(schedule, c, d)?;
    let mut running_claim = weights.dot(&coefficients);
    let mut later = Vec::new();
    let mut ood_values = [[QM31::ZERO; CANDIDATE_OOD_SAMPLES]; CANDIDATE_ROUND_COUNT];
    let mut polynomials = [[QM31::ZERO; 7]; CANDIDATE_ROUND_COUNT];
    for round in 0..CANDIDATE_ROUND_COUNT {
        for sample in 0..CANDIDATE_OOD_SAMPLES {
            let mut evaluation = WeightAccumulator::empty(TWO_VARIABLE_LOG_ROWS - 2 * round as u32);
            if round == 0 {
                evaluation
                    .add_circle_tensor(QM31::ONE, schedule.circle_ood_points[sample])
                    .map_err(|_| StateOnlyHidingRankGateError::Relation)?;
                weights
                    .add_circle_tensor(
                        schedule.mu[round][sample],
                        schedule.circle_ood_points[sample],
                    )
                    .map_err(|_| StateOnlyHidingRankGateError::Relation)?;
            } else {
                evaluation
                    .add_line_tensor(QM31::ONE, schedule.line_ood_points[round - 1][sample])
                    .map_err(|_| StateOnlyHidingRankGateError::Relation)?;
                weights
                    .add_line_tensor(
                        schedule.mu[round][sample],
                        schedule.line_ood_points[round - 1][sample],
                    )
                    .map_err(|_| StateOnlyHidingRankGateError::Relation)?;
            }
            let value = evaluation.dot(&coefficients);
            ood_values[round][sample] = value;
            running_claim = running_claim.add(schedule.mu[round][sample].mul(value));
        }
        let polynomial = polynomial_for_extension(&coefficients, &weights);
        if boundary_sum(&polynomial) != running_claim {
            return Err(StateOnlyHidingRankGateError::Relation);
        }
        polynomials[round] = polynomial;
        running_claim = evaluate_relation(&polynomial, schedule.alpha[round]);
        weights.fold(schedule.alpha[round]);
        coefficients = fold_adjacent_natural_arity4(&coefficients, schedule.alpha[round]);
        if weights.dot(&coefficients) != running_claim {
            return Err(StateOnlyHidingRankGateError::Relation);
        }
        codeword = fold_candidate_codeword_round_for_domain_log(
            &codeword,
            schedule.alpha[round],
            round,
            domain_log,
        )?;
        if round + 1 < CANDIDATE_ROUND_COUNT {
            for &leaf in &indices.later[round] {
                let start = FIBER_SLOTS * leaf as usize;
                later.extend_from_slice(&codeword[start..start + FIBER_SLOTS]);
            }
        }
    }
    if coefficients.len() != TWO_VARIABLE_FINAL_COEFFICIENTS {
        return Err(StateOnlyHidingRankGateError::Shape);
    }
    let mut pcs_tail = later;
    for values in ood_values {
        pcs_tail.extend_from_slice(&values);
    }
    for polynomial in polynomials {
        pcs_tail.extend_from_slice(&polynomial);
    }
    pcs_tail.extend_from_slice(&coefficients);
    Ok(RowPublicMaps {
        layer0_m31,
        terminal: core::array::from_fn(|point| eq_weight_slice(&terminal_points[point], row)),
        pcs_tail,
    })
}

fn sparse_dense_differential_guard(
    encoder: &CircleEncoder,
    domain_log: u32,
    schedule: &StateOnlyTranscriptScheduleResult,
    indices: &aspis_core::circle_line_merkle::CircleLineQueryIndices,
    terminal_points: &[[QM31; STATE_ONLY_HIDING_SUMCHECK_ROUNDS + 2]; 3],
    relation: &SparseRelationSchedule,
    c: QM31,
    d: QM31,
) -> Result<Vec<usize>, StateOnlyHidingRankGateError> {
    // Both endpoints plus logical rows `85 = 1111_base4` and
    // `170 = 2222_base4` in every physical `(s,t)` slice exercise all four
    // primal coefficient slots at every one of the four folds.
    let rows = vec![
        0, 85, 170, 1023, 1024, 1109, 1194, 2047, 2048, 2133, 2218, 3071, 3072, 3157, 3242, 4095,
    ];
    for &row in &rows {
        let sparse = physical_basis_public_maps(
            encoder,
            domain_log,
            row,
            schedule,
            indices,
            terminal_points,
            relation,
        )?;
        let dense = dense_physical_basis_public_maps(
            encoder,
            domain_log,
            row,
            schedule,
            indices,
            terminal_points,
            c,
            d,
        )?;
        if sparse.layer0_m31 != dense.layer0_m31
            || sparse.terminal != dense.terminal
            || sparse.pcs_tail != dense.pcs_tail
        {
            return Err(StateOnlyHidingRankGateError::Layout);
        }
    }
    Ok(rows)
}

fn two_variable_logical_maps(
    encoder: &CircleEncoder,
    domain_log: u32,
    schedule: &StateOnlyTranscriptScheduleResult,
    c: QM31,
    d: QM31,
) -> Result<
    (
        Vec<RowPublicMaps>,
        [Vec<Qm31RowPublicMaps>; RESTRICTION_KERNEL_MASKS],
        [Vec<u32>; CANDIDATE_ROUND_COUNT - 1],
    ),
    StateOnlyHidingRankGateError,
> {
    let indices = derive_circle_line_query_indices_for_count(
        &schedule.queries[..schedule.query_count],
        encoder.codeword_len() / FIBER_SLOTS,
    )
    .map_err(|_| StateOnlyHidingRankGateError::Shape)?;
    let terminal_points = [
        two_variable_point(&schedule.prefix.z, c, d),
        two_variable_point(&binary_successor_point(&schedule.prefix.z), c, d),
        two_variable_point(&xor12_point(&schedule.prefix.z), c, d),
    ];
    let relation = build_sparse_relation_schedule(schedule, c, d)?;
    let _differential_rows = sparse_dense_differential_guard(
        encoder,
        domain_log,
        schedule,
        &indices,
        &terminal_points,
        &relation,
        c,
        d,
    )?;
    let layer0 = indices.layer0.len() * FIBER_SLOTS;
    let later_opened_symbols = indices
        .later
        .iter()
        .map(|round| round.len() * FIBER_SLOTS)
        .sum::<usize>();
    let pcs_tail = later_opened_symbols
        + CANDIDATE_ROUND_COUNT * CANDIDATE_OOD_SAMPLES
        + CANDIDATE_ROUND_COUNT * 7
        + TWO_VARIABLE_FINAL_COEFFICIENTS;
    let mut independent = Vec::with_capacity(TRACE_ROWS);
    let mut kernels: [Vec<Qm31RowPublicMaps>; RESTRICTION_KERNEL_MASKS] =
        core::array::from_fn(|_| Vec::with_capacity(TRACE_ROWS));

    for logical_row in 0..TRACE_ROWS {
        let mut base = RowPublicMaps {
            layer0_m31: vec![M31::ZERO; layer0],
            terminal: [QM31::ZERO; 3],
            pcs_tail: vec![QM31::ZERO; pcs_tail],
        };
        let mut mask_rows: [Qm31RowPublicMaps; RESTRICTION_KERNEL_MASKS] =
            core::array::from_fn(|_| Qm31RowPublicMaps::zero(layer0, pcs_tail));
        for s in 0..2 {
            for t in 0..2 {
                let physical = physical_basis_public_maps(
                    encoder,
                    domain_log,
                    physical_row(logical_row, s, t),
                    schedule,
                    &indices,
                    &terminal_points,
                    &relation,
                )?;
                for (output, &value) in base.layer0_m31.iter_mut().zip(&physical.layer0_m31) {
                    *output = output.add(value);
                }
                for (output, &value) in base.terminal.iter_mut().zip(&physical.terminal) {
                    *output = output.add(value);
                }
                for (output, &value) in base.pcs_tail.iter_mut().zip(&physical.pcs_tail) {
                    *output = output.add(value);
                }
                let s_factor = restriction_factor(s, c);
                let t_factor = restriction_factor(t, d);
                mask_rows[0].add_scaled_physical(&physical, s_factor);
                mask_rows[1].add_scaled_physical(&physical, t_factor);
                mask_rows[2].add_scaled_physical(&physical, s_factor.mul(t_factor));
            }
        }
        independent.push(base);
        for (destination, row) in kernels.iter_mut().zip(mask_rows) {
            destination.push(row);
        }
    }
    Ok((independent, kernels, indices.later))
}

fn qm31_kernel_raw_image(rows: &[Qm31RowPublicMaps], row: usize, basis: QM31) -> Vec<M31> {
    let mut raw = Vec::with_capacity(4 * (rows[row].layer0.len() + 3));
    for value in &rows[row].layer0 {
        raw.extend_from_slice(&qm31_coordinates(basis.mul(*value)));
    }
    for value in rows[row].terminal {
        raw.extend_from_slice(&qm31_coordinates(basis.mul(value)));
    }
    raw
}

fn qm31_kernel_aux(
    rows: &[Qm31RowPublicMaps],
    row: usize,
    basis: QM31,
    pcs_scale: QM31,
    sc_m31: usize,
    h_raw_qm31: usize,
    joint_pcs_m31: usize,
) -> Vec<M31> {
    let mut aux = vec![M31::ZERO; sc_m31 + joint_pcs_m31];
    let pcs = scaled_qm31_difference(&rows[row].pcs_tail, None, basis.mul(pcs_scale));
    let start = sc_m31 + 4 * h_raw_qm31;
    aux[start..start + pcs.len()].copy_from_slice(&pcs);
    aux
}

/// Run the exact rank gate for two inserted MSB coordinates.  The currently
/// frozen fixture supplies q16.  q20 is accepted as well so a sampler-derived
/// diagnostic schedule can be replayed without changing this linear map.
pub fn probe_atomic_state_only_profile21_two_variable_slice_lift_rank(
    schedule: &StateOnlyProfile21TranscriptScheduleResult,
    c: QM31,
    d: QM31,
) -> Result<AtomicProfile21TwoVariableSliceLiftRankReport, StateOnlyHidingRankGateError> {
    let started = Instant::now();
    let schedule = &schedule.base;
    if !matches!(schedule.query_count, 16 | 20)
        || schedule.prefix.z.len() != STATE_ONLY_HIDING_SUMCHECK_ROUNDS
    {
        return Err(StateOnlyHidingRankGateError::Shape);
    }
    let domain_log = STATE_ONLY_LOG_ROWS + 9;
    let encoder = CircleEncoder::new_for_domain_log(domain_log);

    // Exact restriction guard against the literal ten-variable initial
    // relation.  All three fresh directions must lie in its kernel, row by
    // row, before any rank result is considered.
    let lifted_initial = two_variable_initial_weights(schedule, c, d)?;
    let old_initial = initial_relation_weights(schedule, RankLayout::AtomicV3)?;
    for logical_row in 0..TRACE_ROWS {
        let mut base = QM31::ZERO;
        let mut fresh = [QM31::ZERO; RESTRICTION_KERNEL_MASKS];
        for s in 0..2 {
            for t in 0..2 {
                let weight = lifted_initial.weight_at(physical_row(logical_row, s, t) as u32);
                let s_factor = restriction_factor(s, c);
                let t_factor = restriction_factor(t, d);
                base = base.add(weight);
                fresh[0] = fresh[0].add(weight.mul(s_factor));
                fresh[1] = fresh[1].add(weight.mul(t_factor));
                fresh[2] = fresh[2].add(weight.mul(s_factor.mul(t_factor)));
            }
        }
        if base != old_initial.weight_at(logical_row as u32)
            || fresh.into_iter().any(|value| value != QM31::ZERO)
        {
            return Err(StateOnlyHidingRankGateError::Layout);
        }
    }

    let (independent, kernels, later_indices) =
        two_variable_logical_maps(&encoder, domain_log, schedule, c, d)?;
    if kernels
        .iter()
        .flat_map(|rows| rows.iter())
        .flat_map(|row| row.terminal)
        .any(|value| value != QM31::ZERO)
    {
        return Err(StateOnlyHidingRankGateError::Layout);
    }

    let layer0_m31 = independent[0].layer0_m31.len();
    let c1_raw_m31 = layer0_m31 + 12;
    let g_raw_m31 = 4 * (layer0_m31 + 3);
    let pcs_tail_qm31 = independent[0].pcs_tail.len();
    let later_opened_symbols = later_indices
        .iter()
        .map(|indices| FIBER_SLOTS * indices.len())
        .sum::<usize>();
    let expected_tail = later_opened_symbols
        + CANDIDATE_ROUND_COUNT * CANDIDATE_OOD_SAMPLES
        + CANDIDATE_ROUND_COUNT * 7
        + TWO_VARIABLE_FINAL_COEFFICIENTS;
    if independent
        .iter()
        .any(|row| row.layer0_m31.len() != layer0_m31 || row.pcs_tail.len() != pcs_tail_qm31)
        || kernels
            .iter()
            .flat_map(|rows| rows.iter())
            .any(|row| row.layer0.len() != layer0_m31 || row.pcs_tail.len() != pcs_tail_qm31)
        || pcs_tail_qm31 != expected_tail
    {
        return Err(StateOnlyHidingRankGateError::Shape);
    }
    let h_raw_qm31 = layer0_m31 + 3;
    let joint_pcs_m31 = 4 * (h_raw_qm31 + pcs_tail_qm31);
    let sc_m31 = 4 * STATE_ONLY_HIDING_SUMCHECK_QM31_OBSERVATIONS;
    let aux_m31 = sc_m31 + joint_pcs_m31;
    let lagrange = lagrange_basis();
    let active_rows = rank_active_rows(RankLayout::AtomicV3);
    let mut active = [false; TRACE_ROWS];
    for &row in &active_rows {
        active[usize::from(row)] = true;
    }
    let inactive = (0..TRACE_ROWS)
        .filter(|row| !active[*row])
        .collect::<Vec<_>>();
    let global_dependent = inactive[0];
    let h_generator_index = STATE_ONLY_HIDING_C1_COLUMNS + STATE_ONLY_HIDING_MASK_ONLY_C1_COLUMNS;
    let g_generator_index = h_generator_index + 1;
    let powers = (0..=g_generator_index)
        .map(|column| gamma_power(schedule.prefix.gamma, column))
        .collect::<Vec<_>>();

    let mut base_sumcheck_kernel_images = Vec::new();
    let mut semantic_raw_echelons = Vec::with_capacity(STATE_ONLY_HIDING_C1_COLUMNS);
    let cells = atomic_state_only_relation_free_mask_cells_v3()
        .map_err(|_| StateOnlyHidingRankGateError::Layout)?;
    let mut cells_by_column = vec![Vec::new(); STATE_ONLY_HIDING_C1_COLUMNS];
    for cell in cells {
        cells_by_column[usize::from(cell.column)].push(usize::from(cell.row));
    }
    for (column, cells) in cells_by_column.iter().enumerate() {
        let dependent = cells
            .iter()
            .copied()
            .filter(|row| !active[*row])
            .last()
            .ok_or(StateOnlyHidingRankGateError::Layout)?;
        let observations = (0..TRACE_ROWS)
            .map(|row| {
                mask_sumcheck_observations(
                    row,
                    &schedule.prefix.z,
                    &lagrange,
                    MaskFactor::Semantic(column),
                    FactorSchedule::FullSharedLinear,
                    None,
                )
            })
            .collect::<Vec<_>>();
        let mut raw = CarryEchelon::new(c1_raw_m31);
        for &row in cells {
            if row == dependent {
                continue;
            }
            let subtract = (!active[row]).then_some(dependent);
            let aux = scaled_aux_difference(
                &independent,
                row,
                subtract,
                &observations,
                QM31::ONE,
                powers[column],
                4 * h_raw_qm31,
                joint_pcs_m31,
            );
            if let Some(kernel) = raw.reduce(c1_raw_difference(&independent, row, subtract), aux) {
                base_sumcheck_kernel_images.push(kernel);
            }
        }
        if raw.rank != c1_raw_m31 {
            return Err(StateOnlyHidingRankGateError::RawC1Rank {
                column,
                got: raw.rank,
                want: c1_raw_m31,
            });
        }
        semantic_raw_echelons.push(raw);
    }

    for mask_column in 0..STATE_ONLY_HIDING_MASK_ONLY_C1_COLUMNS {
        let observations = (0..TRACE_ROWS)
            .map(|row| {
                mask_sumcheck_observations(
                    row,
                    &schedule.prefix.z,
                    &lagrange,
                    MaskFactor::MaskOnly(mask_column),
                    FactorSchedule::FullSharedLinear,
                    None,
                )
            })
            .collect::<Vec<_>>();
        let generator = STATE_ONLY_HIDING_C1_COLUMNS + mask_column;
        let mut raw = CarryEchelon::new(c1_raw_m31);
        for row in 0..TRACE_ROWS {
            if row == global_dependent {
                continue;
            }
            let subtract = (!active[row]).then_some(global_dependent);
            let aux = scaled_aux_difference(
                &independent,
                row,
                subtract,
                &observations,
                QM31::ONE,
                powers[generator],
                4 * h_raw_qm31,
                joint_pcs_m31,
            );
            if let Some(kernel) = raw.reduce(c1_raw_difference(&independent, row, subtract), aux) {
                base_sumcheck_kernel_images.push(kernel);
            }
        }
        if raw.rank != c1_raw_m31 {
            return Err(StateOnlyHidingRankGateError::RawC1Rank {
                column: generator,
                got: raw.rank,
                want: c1_raw_m31,
            });
        }
    }

    let base_g_observations = (0..TRACE_ROWS)
        .map(|row| {
            mask_sumcheck_observations(
                row,
                &schedule.prefix.z,
                &lagrange,
                MaskFactor::ExplicitG,
                FactorSchedule::FullSharedLinear,
                None,
            )
        })
        .collect::<Vec<_>>();
    let mut g_raw = CarryEchelon::new(g_raw_m31);
    for coordinate in 0..4 {
        let basis = state_only_mask_tower_basis(coordinate);
        for row in 0..TRACE_ROWS {
            if row == global_dependent {
                continue;
            }
            let subtract = (!active[row]).then_some(global_dependent);
            let aux = scaled_aux_difference(
                &independent,
                row,
                subtract,
                &base_g_observations,
                basis,
                basis.mul(powers[g_generator_index]),
                4 * h_raw_qm31,
                joint_pcs_m31,
            );
            if let Some(kernel) =
                g_raw.reduce(qm31_raw_difference(&independent, row, subtract, basis), aux)
            {
                base_sumcheck_kernel_images.push(kernel);
            }
        }
    }
    if g_raw.rank != g_raw_m31 {
        return Err(StateOnlyHidingRankGateError::RawGRank {
            got: g_raw.rank,
            want: g_raw_m31,
        });
    }

    let mut sumcheck = CarryEchelon::new(sc_m31);
    let mut base_pcs_kernel_images = Vec::new();
    for image in base_sumcheck_kernel_images {
        let (sc, pcs) = image.split_at(sc_m31);
        if let Some(kernel) = sumcheck.reduce(sc.to_vec(), pcs.to_vec()) {
            base_pcs_kernel_images.push(kernel);
        }
    }
    if sumcheck.rank != MASK_SUMCHECK_QUOTIENT_M31 {
        return Err(StateOnlyHidingRankGateError::MaskedSumcheckRank {
            got: sumcheck.rank,
            want: MASK_SUMCHECK_QUOTIENT_M31,
        });
    }

    let mut baseline = ColumnEchelon::new(joint_pcs_m31);
    for image in base_pcs_kernel_images {
        baseline.insert(image);
    }
    let h_scale = powers[h_generator_index];
    for coordinate in 0..4 {
        let basis = state_only_mask_tower_basis(coordinate);
        for &row in &inactive {
            if row != global_dependent {
                baseline.insert(h_pcs_image(
                    &independent,
                    row,
                    global_dependent,
                    basis,
                    h_scale,
                    h_raw_qm31,
                    pcs_tail_qm31,
                ));
            }
        }
    }
    let baseline_pcs_rank_m31 = baseline.rank;

    // Condition the three literal restriction-kernel masks on the already
    // complete raw-G and masked-sumcheck views, then insert only their exact
    // PCS quotient images.  This streaming form avoids retaining ~12k large
    // intermediate carry vectors.
    let mut selected = baseline.clone();
    let mut raw_kernel_counts = [0usize; RESTRICTION_KERNEL_MASKS];
    let mut incremental_ranks = [baseline_pcs_rank_m31; RESTRICTION_KERNEL_MASKS];
    let mut incremental_pivots: [Vec<usize>; RESTRICTION_KERNEL_MASKS] =
        core::array::from_fn(|_| Vec::new());
    let mut restriction_sources = Vec::new();
    let mut restriction_rows = Vec::new();
    let mut restriction_values = Vec::new();
    for mask in 0..RESTRICTION_KERNEL_MASKS {
        // Quotienting against frozen echelons is read-only and dominates the
        // host diagnostic.  Compute the four tower coordinates in parallel,
        // then insert in stable coordinate/row order so rank provenance is
        // deterministic.
        let coordinate_images = std::thread::scope(|scope| {
            let handles = (0..4)
                .map(|coordinate| {
                    let rows = &kernels[mask];
                    let g_raw = &g_raw;
                    let sumcheck = &sumcheck;
                    let pcs_scale = powers[g_generator_index];
                    scope.spawn(move || {
                        let basis = state_only_mask_tower_basis(coordinate);
                        let mut images = Vec::with_capacity(TRACE_ROWS);
                        for row in 0..TRACE_ROWS {
                            let source = mask * 4 * TRACE_ROWS + 4 * row + coordinate;
                            let aux = qm31_kernel_aux(
                                rows,
                                row,
                                basis,
                                pcs_scale,
                                sc_m31,
                                h_raw_qm31,
                                joint_pcs_m31,
                            );
                            let raw_kernel = g_raw
                                .quotient_existing(qm31_kernel_raw_image(rows, row, basis), aux)
                                .ok_or(StateOnlyHidingRankGateError::Layout)?;
                            let (sc, pcs) = raw_kernel.split_at(sc_m31);
                            let pcs = sumcheck
                                .quotient_existing(sc.to_vec(), pcs.to_vec())
                                .ok_or(StateOnlyHidingRankGateError::Layout)?;
                            images.push((source, pcs));
                        }
                        Ok::<_, StateOnlyHidingRankGateError>(images)
                    })
                })
                .collect::<Vec<_>>();
            handles
                .into_iter()
                .map(|handle| {
                    handle
                        .join()
                        .map_err(|_| StateOnlyHidingRankGateError::Layout)?
                })
                .collect::<Result<Vec<_>, _>>()
        })?;
        for images in coordinate_images {
            raw_kernel_counts[mask] += images.len();
            for (source, pcs) in images {
                if let Some((pivot, value)) = selected.insert_with_pivot_value(pcs) {
                    incremental_pivots[mask].push(pivot);
                    restriction_sources.push(source);
                    restriction_rows.push(pivot);
                    restriction_values.push(value);
                }
            }
        }
        incremental_ranks[mask] = selected.rank;
    }
    let restriction_pcs_rank_m31 = selected.rank;
    let restriction_minor = RankMinorProvenance::from_parts(
        "atomic_profile21_two_variable_restriction_kernel",
        restriction_sources,
        restriction_rows,
        restriction_values,
    );

    // Conservative semantic and legal-sumcheck closure is the same exact
    // quotient construction as the one-variable gate.  Semantic rows remain
    // ten-bit logical rows; no physical twelve-bit index enters sumcheck.
    let mut compatibility = CarryEchelon::new(sc_m31);
    let mut semantic_images = Vec::new();
    let mut semantic_sources = Vec::new();
    let mut semantic_rows = Vec::new();
    let mut semantic_values = Vec::new();
    let pcs_start = sc_m31 + 4 * h_raw_qm31;
    let mut semantic_reference = baseline.clone();
    for column in 0..STATE_ONLY_HIDING_C1_COLUMNS {
        for row in 1..TRACE_ROWS {
            let source_id = column * TRACE_ROWS + row;
            let raw = c1_raw_difference(&independent, row, None);
            let mut carry = vec![M31::ZERO; aux_m31];
            let pcs = scaled_qm31_difference(&independent[row].pcs_tail, None, powers[column]);
            carry[pcs_start..pcs_start + pcs.len()].copy_from_slice(&pcs);
            let post_raw = semantic_raw_echelons[column]
                .quotient_existing(raw, carry)
                .ok_or(StateOnlyHidingRankGateError::WitnessRawQuotient { source: source_id })?;
            let (sc, pcs) = post_raw.split_at(sc_m31);
            let (sc_remainder, mut pcs_remainder) =
                sumcheck.remainder_existing(sc.to_vec(), pcs.to_vec());
            let next_pivot = compatibility.rank;
            pcs_remainder.extend((0..4).map(|index| {
                if next_pivot < 4 && index == next_pivot {
                    M31::ONE
                } else {
                    M31::ZERO
                }
            }));
            if let CarryReduction::Kernel(mut post_sumcheck) =
                compatibility.reduce_with_pivot(sc_remainder, pcs_remainder)
            {
                post_sumcheck.truncate(joint_pcs_m31);
                if let Some((pivot, value)) =
                    semantic_reference.insert_with_pivot_value(post_sumcheck.clone())
                {
                    semantic_images.push(post_sumcheck);
                    semantic_sources.push(source_id);
                    semantic_rows.push(pivot);
                    semantic_values.push(value);
                }
            }
        }
    }
    if compatibility.rank != 4 {
        return Err(StateOnlyHidingRankGateError::Layout);
    }
    let semantic_minor = RankMinorProvenance::from_parts(
        "atomic_profile21_two_variable_semantic",
        semantic_sources,
        semantic_rows,
        semantic_values,
    );

    let mut legal_images = Vec::new();
    let mut legal_sources = Vec::new();
    let mut legal_rows = Vec::new();
    let mut legal_values = Vec::new();
    for sc_row in 4..sc_m31 {
        let mut sc = vec![M31::ZERO; sc_m31];
        sc[sc_row] = M31::ONE;
        let pcs = vec![M31::ZERO; joint_pcs_m31];
        let (sc_remainder, mut pcs_remainder) = sumcheck.remainder_existing(sc, pcs);
        pcs_remainder.extend([M31::ZERO; 4]);
        if let CarryReduction::Kernel(mut post_sumcheck) =
            compatibility.reduce_with_pivot(sc_remainder, pcs_remainder)
        {
            post_sumcheck.truncate(joint_pcs_m31);
            if let Some((pivot, value)) =
                semantic_reference.insert_with_pivot_value(post_sumcheck.clone())
            {
                legal_images.push(post_sumcheck);
                legal_sources.push(sc_row - 4);
                legal_rows.push(pivot);
                legal_values.push(value);
            }
        }
    }
    let legal_sumcheck_minor = RankMinorProvenance::from_parts(
        "atomic_profile21_two_variable_legal_sumcheck",
        legal_sources,
        legal_rows,
        legal_values,
    );

    let mut augmented = selected;
    let mut semantic_new_pivots_m31 = Vec::new();
    for image in &semantic_images {
        if let Some(pivot) = augmented.insert_with_pivot(image.clone()) {
            semantic_new_pivots_m31.push(pivot);
        }
    }
    let semantic_augmented_rank_m31 = augmented.rank;
    let mut legal_sumcheck_new_pivots_m31 = Vec::new();
    for image in &legal_images {
        if let Some(pivot) = augmented.insert_with_pivot(image.clone()) {
            legal_sumcheck_new_pivots_m31.push(pivot);
        }
    }
    let legal_sumcheck_augmented_rank_m31 = augmented.rank;

    let codeword_len = encoder.codeword_len();
    Ok(AtomicProfile21TwoVariableSliceLiftRankReport {
        query_count: schedule.query_count,
        message_log: TWO_VARIABLE_LOG_ROWS,
        codeword_domain_log: domain_log,
        codeword_len,
        rate_denominator: codeword_len / TWO_VARIABLE_TRACE_ROWS,
        final_coefficients_qm31: TWO_VARIABLE_FINAL_COEFFICIENTS,
        slice_c_coordinates_m31: qm31_coordinates(c).map(|coordinate| coordinate.0),
        slice_d_coordinates_m31: qm31_coordinates(d).map(|coordinate| coordinate.0),
        initial_restriction_guard: true,
        terminal_zero_guard: true,
        sparse_dense_differential_guard: true,
        sparse_dense_differential_rows: vec![
            0, 85, 170, 1023, 1024, 1109, 1194, 2047, 2048, 2133, 2218, 3071, 3072, 3157, 3242,
            4095,
        ],
        masked_sumcheck_rank_m31: sumcheck.rank,
        g_raw_rank_m31: g_raw.rank,
        restriction_raw_kernel_m31: raw_kernel_counts,
        baseline_pcs_rank_m31,
        restriction_incremental_pcs_rank_m31: incremental_ranks,
        restriction_incremental_new_pivots_m31: incremental_pivots,
        restriction_pcs_rank_m31,
        semantic_augmented_rank_m31,
        semantic_new_pivots_m31,
        legal_sumcheck_augmented_rank_m31,
        legal_sumcheck_new_pivots_m31,
        contains_conservative_semantic_and_legal_sumcheck: restriction_pcs_rank_m31
            == legal_sumcheck_augmented_rank_m31,
        restriction_minor,
        semantic_minor,
        legal_sumcheck_minor,
        elapsed_millis: started.elapsed().as_millis(),
    })
}

//! Exact, production-neutral row-bit permutation screen for the early-p0
//! hiding quotient.
//!
//! For first variable `b`, the physical coefficient coordinates are ordered
//! `pi_b = [b, 0, ..., b-1, b+1, ..., 9]`.  The successor and xor points are
//! conjugated by this permutation.  Applying successor/xor directly to the
//! reordered point would change the statement map and is deliberately not
//! modelled here.

use std::collections::BTreeSet;
use std::time::Instant;

use aspis_core::sumcheck::SUMCHECK_COEFFICIENTS;

use super::*;

const P0_QM31: usize = SUMCHECK_COEFFICIENTS;

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct AtomicProfile21VariablePermutationP0RankReport {
    pub first_logical_variable: usize,
    pub physical_to_logical_coordinates: [usize; STATE_ONLY_HIDING_SUMCHECK_ROUNDS],
    pub conjugation_guard_run: bool,
    pub conjugation_guard_passed: bool,
    pub inactive_low_mask_groups: usize,
    pub baseline_inactive_low_mask_groups: usize,
    pub preserves_grouped_inactive_shape: bool,
    pub raw_c1_rank_m31: usize,
    pub raw_g_rank_m31: usize,
    pub masked_sumcheck_rank_m31: usize,
    pub p0_view_m31: usize,
    pub p0_mask_rank_m31: usize,
    pub p0_semantic_augmented_rank_m31: usize,
    pub p0_legal_sumcheck_augmented_rank_m31: usize,
    pub p0_semantic_new_pivots_m31: Vec<usize>,
    pub p0_legal_sumcheck_new_pivots_m31: Vec<usize>,
    pub p0_contains_conservative_semantic_and_legal_sumcheck: bool,
    pub elapsed_millis: u128,
}

#[derive(Clone, Copy)]
struct BitPermutation {
    physical_to_logical: [usize; STATE_ONLY_HIDING_SUMCHECK_ROUNDS],
    logical_to_physical: [usize; STATE_ONLY_HIDING_SUMCHECK_ROUNDS],
}

impl BitPermutation {
    fn stable_first(first: usize) -> Option<Self> {
        if first >= STATE_ONLY_HIDING_SUMCHECK_ROUNDS {
            return None;
        }
        let mut physical_to_logical = [0usize; STATE_ONLY_HIDING_SUMCHECK_ROUNDS];
        physical_to_logical[0] = first;
        let mut cursor = 1usize;
        for logical in 0..STATE_ONLY_HIDING_SUMCHECK_ROUNDS {
            if logical != first {
                physical_to_logical[cursor] = logical;
                cursor += 1;
            }
        }
        let mut logical_to_physical = [0usize; STATE_ONLY_HIDING_SUMCHECK_ROUNDS];
        for (physical, logical) in physical_to_logical.iter().copied().enumerate() {
            logical_to_physical[logical] = physical;
        }
        Some(Self {
            physical_to_logical,
            logical_to_physical,
        })
    }

    fn logical_row_to_physical(self, logical_row: usize) -> usize {
        debug_assert!(logical_row < TRACE_ROWS);
        let mut physical_row = 0usize;
        for physical in 0..STATE_ONLY_HIDING_SUMCHECK_ROUNDS {
            let logical = self.physical_to_logical[physical];
            let bit = (logical_row >> (STATE_ONLY_HIDING_SUMCHECK_ROUNDS - 1 - logical)) & 1;
            physical_row |= bit << (STATE_ONLY_HIDING_SUMCHECK_ROUNDS - 1 - physical);
        }
        physical_row
    }

    fn physical_point_to_logical(
        self,
        physical: &[QM31; STATE_ONLY_HIDING_SUMCHECK_ROUNDS],
    ) -> [QM31; STATE_ONLY_HIDING_SUMCHECK_ROUNDS] {
        core::array::from_fn(|logical| physical[self.logical_to_physical[logical]])
    }

    fn logical_point_to_physical(
        self,
        logical: &[QM31; STATE_ONLY_HIDING_SUMCHECK_ROUNDS],
    ) -> [QM31; STATE_ONLY_HIDING_SUMCHECK_ROUNDS] {
        core::array::from_fn(|physical| logical[self.physical_to_logical[physical]])
    }
}

fn permuted_active(permutation: BitPermutation) -> [bool; TRACE_ROWS] {
    let mut active = [false; TRACE_ROWS];
    for logical in rank_active_rows(RankLayout::AtomicV3) {
        active[permutation.logical_row_to_physical(usize::from(logical))] = true;
    }
    active
}

fn permuted_inactive_masks(permutation: BitPermutation) -> [u16; 64] {
    let logical = rank_inactive_masks(RankLayout::AtomicV3);
    let mut physical = [0u16; 64];
    for logical_row in 0..TRACE_ROWS {
        if ((logical[logical_row >> 4] >> (logical_row & 15)) & 1) == 0 {
            continue;
        }
        let physical_row = permutation.logical_row_to_physical(logical_row);
        physical[physical_row >> 4] |= 1 << (physical_row & 15);
    }
    physical
}

fn low_mask_group_count(masks: &[u16; 64]) -> usize {
    masks.iter().copied().collect::<BTreeSet<_>>().len()
}

fn conjugated_terminal_points(
    schedule: &StateOnlyTranscriptScheduleResult,
    permutation: BitPermutation,
) -> [[QM31; STATE_ONLY_HIDING_SUMCHECK_ROUNDS]; 3] {
    let logical_z = permutation.physical_point_to_logical(&schedule.prefix.z);
    [
        schedule.prefix.z,
        permutation.logical_point_to_physical(&binary_successor_point(&logical_z)),
        permutation.logical_point_to_physical(&xor12_point(&logical_z)),
    ]
}

fn initial_weights_for_points(
    schedule: &StateOnlyTranscriptScheduleResult,
    points: &[[QM31; STATE_ONLY_HIDING_SUMCHECK_ROUNDS]; 3],
    inactive_masks: [u16; 64],
) -> Result<WeightAccumulator, StateOnlyHidingRankGateError> {
    let mut weights = WeightAccumulator::empty(STATE_ONLY_LOG_ROWS);
    let kappa = schedule.prefix.point_scale;
    for (point, scale) in points.iter().zip([QM31::ONE, kappa, kappa.square()]) {
        weights
            .add_multilinear(scale, point.to_vec())
            .map_err(|_| StateOnlyHidingRankGateError::Relation)?;
    }
    weights
        .add_grouped_64x16_binary_masks(inactive_masks)
        .map_err(|_| StateOnlyHidingRankGateError::Relation)?;
    Ok(weights)
}

/// All seven coefficients of the round-zero relation polynomial for every
/// physical unit message.  This is the literal arity-four dual polynomial,
/// not a synthetic projection onto the currently observed coefficient-zero
/// pivot.
fn p0_unit_rows(weights: &WeightAccumulator) -> Vec<[QM31; P0_QM31]> {
    let quarter = M31(4).inv();
    let mut rows = vec![[QM31::ZERO; P0_QM31]; TRACE_ROWS];
    for chunk in 0..TRACE_ROWS / FIBER_SLOTS {
        let base = FIBER_SLOTS * chunk;
        let values = core::array::from_fn::<_, FIBER_SLOTS, _>(|slot| {
            weights.weight_at((base + slot) as u32)
        });
        let dual = [values[0], values[3], values[2], values[1]].map(|value| value.mul_m31(quarter));
        for slot in 0..FIBER_SLOTS {
            for (degree, value) in dual.iter().copied().enumerate() {
                rows[base + slot][slot + degree] = value;
            }
        }
    }
    rows
}

fn deterministic_guard_coefficients() -> Vec<QM31> {
    (0..TRACE_ROWS)
        .map(|row| {
            QM31::from_cm31(CM31::from_m31(M31(
                ((17usize.wrapping_mul(row) + 29) % 2_147_483_647) as u32,
            )))
        })
        .collect()
}

fn dense_conjugation_guard(
    schedule: &StateOnlyTranscriptScheduleResult,
    permutation: BitPermutation,
    points: &[[QM31; STATE_ONLY_HIDING_SUMCHECK_ROUNDS]; 3],
    inactive_masks: [u16; 64],
    structured_weights: &WeightAccumulator,
    p0_rows: &[[QM31; P0_QM31]],
) -> Result<bool, StateOnlyHidingRankGateError> {
    let kappa = schedule.prefix.point_scale;
    let scales = [QM31::ONE, kappa, kappa.square()];
    let dense_weights = (0..TRACE_ROWS)
        .map(|row| {
            let evaluation = points
                .iter()
                .zip(scales)
                .fold(QM31::ZERO, |sum, (point, scale)| {
                    sum.add(scale.mul(eq_weight(point, row)))
                });
            if ((inactive_masks[row >> 4] >> (row & 15)) & 1) != 0 {
                evaluation.add(QM31::ONE)
            } else {
                evaluation
            }
        })
        .collect::<Vec<_>>();
    if dense_weights
        .iter()
        .copied()
        .enumerate()
        .any(|(row, value)| structured_weights.weight_at(row as u32) != value)
    {
        return Ok(false);
    }

    let coefficients = deterministic_guard_coefficients();
    let fast = coefficients.iter().copied().zip(p0_rows).fold(
        [QM31::ZERO; P0_QM31],
        |mut sum, (coefficient, row)| {
            for (target, value) in sum.iter_mut().zip(row) {
                *target = target.add(coefficient.mul(*value));
            }
            sum
        },
    );
    let structured = polynomial_for_extension(&coefficients, structured_weights);
    let mut dense_accumulator = WeightAccumulator::empty(STATE_ONLY_LOG_ROWS);
    dense_accumulator
        .add_dense(dense_weights)
        .map_err(|_| StateOnlyHidingRankGateError::Relation)?;
    let dense = polynomial_for_extension(&coefficients, &dense_accumulator);
    if fast != structured || structured != dense {
        return Ok(false);
    }

    // Independently guard the conjugated statement points.  A logical word
    // reindexed into physical coefficient order must retain all three values.
    let logical_coefficients = deterministic_guard_coefficients();
    let mut physical_coefficients = vec![QM31::ZERO; TRACE_ROWS];
    for (logical_row, value) in logical_coefficients.iter().copied().enumerate() {
        physical_coefficients[permutation.logical_row_to_physical(logical_row)] = value;
    }
    let logical_z = permutation.physical_point_to_logical(&schedule.prefix.z);
    let logical_points = [
        logical_z,
        binary_successor_point(&logical_z),
        xor12_point(&logical_z),
    ];
    for point in 0..3 {
        let logical_value = logical_coefficients
            .iter()
            .copied()
            .enumerate()
            .fold(QM31::ZERO, |sum, (row, value)| {
                sum.add(value.mul(eq_weight(&logical_points[point], row)))
            });
        let physical_value = physical_coefficients
            .iter()
            .copied()
            .enumerate()
            .fold(QM31::ZERO, |sum, (row, value)| {
                sum.add(value.mul(eq_weight(&points[point], row)))
            });
        if logical_value != physical_value {
            return Ok(false);
        }
    }
    Ok(true)
}

/// Cache shared by all ten first-variable screens.  Layer-zero circle
/// openings and masked-sumcheck row maps are independent of the row-bit
/// interpretation; only terminal maps and p0 are rebuilt per permutation.
pub struct AtomicProfile21VariablePermutationP0Probe {
    layer0_rows: Vec<Vec<M31>>,
    semantic_observations: Vec<Vec<Vec<QM31>>>,
    mask_only_observations: Vec<Vec<Vec<QM31>>>,
    g_observations: Vec<Vec<QM31>>,
    baseline_inactive_low_mask_groups: usize,
}

impl AtomicProfile21VariablePermutationP0Probe {
    pub fn new(
        schedule: &StateOnlyTranscriptScheduleResult,
    ) -> Result<Self, StateOnlyHidingRankGateError> {
        if schedule.query_count != 16
            || schedule.prefix.z.len() != STATE_ONLY_HIDING_SUMCHECK_ROUNDS
        {
            return Err(StateOnlyHidingRankGateError::Shape);
        }
        let domain_log = STATE_ONLY_LOG_ROWS + 9;
        let encoder = CircleEncoder::new_for_domain_log(domain_log);
        let indices = derive_circle_line_query_indices_for_count(
            &schedule.queries[..schedule.query_count],
            encoder.codeword_len() / FIBER_SLOTS,
        )
        .map_err(|_| StateOnlyHidingRankGateError::Shape)?;
        let mut layer0_rows = Vec::with_capacity(TRACE_ROWS);
        for row in 0..TRACE_ROWS {
            let mut layer0 = Vec::with_capacity(indices.layer0.len() * FIBER_SLOTS);
            for &query in &indices.layer0 {
                for slot in 0..FIBER_SLOTS {
                    layer0.push(
                        encoder.encode_c1_basis_value(row, FIBER_SLOTS * query as usize + slot)?,
                    );
                }
            }
            layer0_rows.push(layer0);
        }

        let lagrange = lagrange_basis();
        let semantic_observations = (0..STATE_ONLY_HIDING_C1_COLUMNS)
            .map(|column| {
                (0..TRACE_ROWS)
                    .map(|row| {
                        mask_sumcheck_observations(
                            row,
                            &schedule.prefix.z,
                            &lagrange,
                            MaskFactor::Semantic(column),
                            FactorSchedule::FullSharedLinear,
                            None,
                        )
                    })
                    .collect::<Vec<_>>()
            })
            .collect::<Vec<_>>();
        let mask_only_observations = (0..STATE_ONLY_HIDING_MASK_ONLY_C1_COLUMNS)
            .map(|column| {
                (0..TRACE_ROWS)
                    .map(|row| {
                        mask_sumcheck_observations(
                            row,
                            &schedule.prefix.z,
                            &lagrange,
                            MaskFactor::MaskOnly(column),
                            FactorSchedule::FullSharedLinear,
                            None,
                        )
                    })
                    .collect::<Vec<_>>()
            })
            .collect::<Vec<_>>();
        let g_observations = (0..TRACE_ROWS)
            .map(|row| {
                mask_sumcheck_observations(
                    row,
                    &schedule.prefix.z,
                    &lagrange,
                    MaskFactor::ExplicitG,
                    FactorSchedule::FullSharedLinear,
                    None,
                )
            })
            .collect::<Vec<_>>();
        let baseline_inactive_low_mask_groups =
            low_mask_group_count(&rank_inactive_masks(RankLayout::AtomicV3));
        Ok(Self {
            layer0_rows,
            semantic_observations,
            mask_only_observations,
            g_observations,
            baseline_inactive_low_mask_groups,
        })
    }

    pub fn probe_first_variable(
        &self,
        schedule: &StateOnlyTranscriptScheduleResult,
        first_logical_variable: usize,
    ) -> Result<AtomicProfile21VariablePermutationP0RankReport, StateOnlyHidingRankGateError> {
        let started = Instant::now();
        let permutation = BitPermutation::stable_first(first_logical_variable)
            .ok_or(StateOnlyHidingRankGateError::Shape)?;
        let active = permuted_active(permutation);
        let inactive = (0..TRACE_ROWS)
            .filter(|row| !active[*row])
            .collect::<Vec<_>>();
        let global_dependent = inactive[0];
        let inactive_masks = permuted_inactive_masks(permutation);
        let inactive_low_mask_groups = low_mask_group_count(&inactive_masks);
        let points = conjugated_terminal_points(schedule, permutation);
        let weights = initial_weights_for_points(schedule, &points, inactive_masks)?;
        let p0_units = p0_unit_rows(&weights);
        let conjugation_guard_run = first_logical_variable == 0 || first_logical_variable == 7;
        let conjugation_guard_passed = !conjugation_guard_run
            || dense_conjugation_guard(
                schedule,
                permutation,
                &points,
                inactive_masks,
                &weights,
                &p0_units,
            )?;
        if !conjugation_guard_passed {
            return Err(StateOnlyHidingRankGateError::Relation);
        }

        let rows = (0..TRACE_ROWS)
            .map(|row| {
                let pcs_tail = if row == global_dependent {
                    vec![QM31::ZERO; P0_QM31]
                } else if active[row] {
                    p0_units[row].to_vec()
                } else {
                    p0_units[row]
                        .iter()
                        .copied()
                        .zip(p0_units[global_dependent])
                        .map(|(value, dependent)| value.sub(dependent))
                        .collect()
                };
                RowPublicMaps {
                    layer0_m31: self.layer0_rows[row].clone(),
                    terminal: core::array::from_fn(|point| eq_weight(&points[point], row)),
                    pcs_tail,
                }
            })
            .collect::<Vec<_>>();
        let layer0_m31 = rows[0].layer0_m31.len();
        let c1_raw_m31 = layer0_m31 + 12;
        let g_raw_m31 = 4 * (layer0_m31 + 3);
        let h_raw_qm31 = layer0_m31 + 3;
        let p0_view_m31 = 4 * (h_raw_qm31 + P0_QM31);
        let sc_m31 = 4 * STATE_ONLY_HIDING_SUMCHECK_QM31_OBSERVATIONS;
        let aux_m31 = sc_m31 + p0_view_m31;
        let h_generator_index =
            STATE_ONLY_HIDING_C1_COLUMNS + STATE_ONLY_HIDING_MASK_ONLY_C1_COLUMNS;
        let g_generator_index = h_generator_index + 1;
        let powers = (0..=g_generator_index)
            .map(|column| gamma_power(schedule.prefix.gamma, column))
            .collect::<Vec<_>>();

        let cells = atomic_state_only_relation_free_mask_cells_v3()
            .map_err(|_| StateOnlyHidingRankGateError::Layout)?;
        let mut cells_by_column = vec![Vec::new(); STATE_ONLY_HIDING_C1_COLUMNS];
        for cell in cells {
            let logical = usize::from(cell.row);
            cells_by_column[usize::from(cell.column)]
                .push(permutation.logical_row_to_physical(logical));
        }

        let mut sumcheck_kernel_images = Vec::new();
        let mut semantic_raw_echelons = Vec::with_capacity(STATE_ONLY_HIDING_C1_COLUMNS);
        let mut raw_c1_rank_m31 = 0usize;
        for (column, cells) in cells_by_column.iter().enumerate() {
            let dependent = cells
                .iter()
                .copied()
                .filter(|row| !active[*row])
                .last()
                .ok_or(StateOnlyHidingRankGateError::Layout)?;
            let observations = &self.semantic_observations[column];
            let mut raw = CarryEchelon::new(c1_raw_m31);
            for &row in cells {
                if row == dependent {
                    continue;
                }
                let subtract = (!active[row]).then_some(dependent);
                let raw_image = c1_raw_difference(&rows, row, subtract);
                let aux = scaled_aux_difference(
                    &rows,
                    row,
                    subtract,
                    observations,
                    QM31::ONE,
                    powers[column],
                    4 * h_raw_qm31,
                    p0_view_m31,
                );
                if let Some(kernel) = raw.reduce(raw_image, aux) {
                    sumcheck_kernel_images.push(kernel);
                }
            }
            if raw.rank != c1_raw_m31 {
                return Err(StateOnlyHidingRankGateError::RawC1Rank {
                    column,
                    got: raw.rank,
                    want: c1_raw_m31,
                });
            }
            raw_c1_rank_m31 += raw.rank;
            semantic_raw_echelons.push(raw);
        }

        for mask_column in 0..STATE_ONLY_HIDING_MASK_ONLY_C1_COLUMNS {
            let observations = &self.mask_only_observations[mask_column];
            let generator = STATE_ONLY_HIDING_C1_COLUMNS + mask_column;
            let mut raw = CarryEchelon::new(c1_raw_m31);
            for row in 0..TRACE_ROWS {
                if row == global_dependent {
                    continue;
                }
                let subtract = (!active[row]).then_some(global_dependent);
                let raw_image = c1_raw_difference(&rows, row, subtract);
                let aux = scaled_aux_difference(
                    &rows,
                    row,
                    subtract,
                    observations,
                    QM31::ONE,
                    powers[generator],
                    4 * h_raw_qm31,
                    p0_view_m31,
                );
                if let Some(kernel) = raw.reduce(raw_image, aux) {
                    sumcheck_kernel_images.push(kernel);
                }
            }
            if raw.rank != c1_raw_m31 {
                return Err(StateOnlyHidingRankGateError::RawC1Rank {
                    column: generator,
                    got: raw.rank,
                    want: c1_raw_m31,
                });
            }
            raw_c1_rank_m31 += raw.rank;
        }

        let mut g_raw = CarryEchelon::new(g_raw_m31);
        for coordinate in 0..4 {
            let basis = state_only_mask_tower_basis(coordinate);
            for row in 0..TRACE_ROWS {
                if row == global_dependent {
                    continue;
                }
                let subtract = (!active[row]).then_some(global_dependent);
                let raw_image = qm31_raw_difference(&rows, row, subtract, basis);
                let aux = scaled_aux_difference(
                    &rows,
                    row,
                    subtract,
                    &self.g_observations,
                    basis,
                    basis.mul(powers[g_generator_index]),
                    4 * h_raw_qm31,
                    p0_view_m31,
                );
                if let Some(kernel) = g_raw.reduce(raw_image, aux) {
                    sumcheck_kernel_images.push(kernel);
                }
            }
        }
        if g_raw.rank != g_raw_m31 {
            return Err(StateOnlyHidingRankGateError::RawGRank {
                got: g_raw.rank,
                want: g_raw_m31,
            });
        }

        let mut sumcheck = CarryEchelon::new(sc_m31);
        let mut p0_kernel_images = Vec::new();
        for image in sumcheck_kernel_images {
            let (sc, p0) = image.split_at(sc_m31);
            if let Some(kernel) = sumcheck.reduce(sc.to_vec(), p0.to_vec()) {
                p0_kernel_images.push(kernel);
            }
        }
        if sumcheck.rank != MASK_SUMCHECK_QUOTIENT_M31 {
            return Err(StateOnlyHidingRankGateError::MaskedSumcheckRank {
                got: sumcheck.rank,
                want: MASK_SUMCHECK_QUOTIENT_M31,
            });
        }

        let mut p0_rank = ColumnEchelon::new(p0_view_m31);
        for image in p0_kernel_images {
            p0_rank.insert(image);
        }
        let h_scale = powers[h_generator_index];
        for coordinate in 0..4 {
            let basis = state_only_mask_tower_basis(coordinate);
            for &row in &inactive {
                if row != global_dependent {
                    p0_rank.insert(h_pcs_image(
                        &rows,
                        row,
                        global_dependent,
                        basis,
                        h_scale,
                        h_raw_qm31,
                        P0_QM31,
                    ));
                }
            }
        }
        let p0_mask_rank_m31 = p0_rank.rank;

        let mut semantic_augmented = p0_rank.clone();
        let mut compatibility = CarryEchelon::new(sc_m31);
        let mut p0_semantic_new_pivots_m31 = Vec::new();
        for column in 0..STATE_ONLY_HIDING_C1_COLUMNS {
            for logical_row in 1..TRACE_ROWS {
                let row = permutation.logical_row_to_physical(logical_row);
                let raw = c1_raw_difference(&rows, row, None);
                let mut carry = vec![M31::ZERO; aux_m31];
                let pcs = scaled_qm31_difference(&rows[row].pcs_tail, None, powers[column]);
                let pcs_start = sc_m31 + 4 * h_raw_qm31;
                carry[pcs_start..pcs_start + pcs.len()].copy_from_slice(&pcs);
                let post_raw = semantic_raw_echelons[column]
                    .quotient_existing(raw, carry)
                    .ok_or(StateOnlyHidingRankGateError::WitnessRawQuotient {
                        source: column * TRACE_ROWS + logical_row,
                    })?;
                let (sc, p0) = post_raw.split_at(sc_m31);
                let (sc_remainder, mut p0_remainder) =
                    sumcheck.remainder_existing(sc.to_vec(), p0.to_vec());
                let next_pivot = compatibility.rank;
                p0_remainder.extend((0..4).map(|index| {
                    if next_pivot < 4 && index == next_pivot {
                        M31::ONE
                    } else {
                        M31::ZERO
                    }
                }));
                if let CarryReduction::Kernel(mut post_sumcheck) =
                    compatibility.reduce_with_pivot(sc_remainder, p0_remainder)
                {
                    post_sumcheck.truncate(p0_view_m31);
                    if let Some(pivot) = semantic_augmented.insert_with_pivot(post_sumcheck) {
                        p0_semantic_new_pivots_m31.push(pivot);
                    }
                }
            }
        }
        let p0_semantic_augmented_rank_m31 = semantic_augmented.rank;

        let mut legal_augmented = semantic_augmented;
        let mut p0_legal_sumcheck_new_pivots_m31 = Vec::new();
        for sc_row in 4..sc_m31 {
            let mut sc = vec![M31::ZERO; sc_m31];
            sc[sc_row] = M31::ONE;
            let p0 = vec![M31::ZERO; p0_view_m31];
            let (sc_remainder, mut p0_remainder) = sumcheck.remainder_existing(sc, p0);
            p0_remainder.extend([M31::ZERO; 4]);
            if let CarryReduction::Kernel(mut post_sumcheck) =
                compatibility.reduce_with_pivot(sc_remainder, p0_remainder)
            {
                post_sumcheck.truncate(p0_view_m31);
                if let Some(pivot) = legal_augmented.insert_with_pivot(post_sumcheck) {
                    p0_legal_sumcheck_new_pivots_m31.push(pivot);
                }
            }
        }
        let p0_legal_sumcheck_augmented_rank_m31 = legal_augmented.rank;
        Ok(AtomicProfile21VariablePermutationP0RankReport {
            first_logical_variable,
            physical_to_logical_coordinates: permutation.physical_to_logical,
            conjugation_guard_run,
            conjugation_guard_passed,
            inactive_low_mask_groups,
            baseline_inactive_low_mask_groups: self.baseline_inactive_low_mask_groups,
            preserves_grouped_inactive_shape: inactive_low_mask_groups
                == self.baseline_inactive_low_mask_groups,
            raw_c1_rank_m31,
            raw_g_rank_m31: g_raw.rank,
            masked_sumcheck_rank_m31: sumcheck.rank,
            p0_view_m31,
            p0_mask_rank_m31,
            p0_semantic_augmented_rank_m31,
            p0_legal_sumcheck_augmented_rank_m31,
            p0_semantic_new_pivots_m31,
            p0_legal_sumcheck_new_pivots_m31,
            p0_contains_conservative_semantic_and_legal_sumcheck: p0_mask_rank_m31
                == p0_legal_sumcheck_augmented_rank_m31,
            elapsed_millis: started.elapsed().as_millis(),
        })
    }
}

crates/aspis-prover/src/state_only_priva:
//! Host builder for canonical state-only private Merkle openings.

use aspis_core::merkle::{node_hash, node_hash4};
use aspis_core::state_only_private_merkle::{
    private_leaf_hash, STATE_ONLY_PRIVATE_LEAF_SALT_BYTES,
};
use aspis_core::HashFn;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum StateOnlyPrivateOpeningBuildError {
    InvalidDepth { depth: u32 },
    InvalidValueWidth { width: usize },
    ValuesLengthMismatch { expected: usize, actual: usize },
    SaltCountMismatch { expected: usize, actual: usize },
    EmptyOpening,
    CountOutOfRange { count: usize },
    IndicesNotStrictlyIncreasing,
    LeafIndexOutOfRange { index: u32 },
    LengthOverflow,
    OpenedLeafDoesNotMatchTree { index: u32 },
}

pub struct StateOnlyPrivateMerkleTree {
    hash: HashFn,
    binary_depth: u32,
    tree_tag: u8,
    value_width: usize,
    levels: Vec<Vec<[u8; 32]>>,
}

impl Drop for StateOnlyPrivateMerkleTree {
    fn drop(&mut self) {
        for level in &mut self.levels {
            for node in level {
                for byte in node {
                    // SAFETY: the node is uniquely borrowed during drop.
                    unsafe { core::ptr::write_volatile(byte, 0) };
                }
            }
        }
        core::sync::atomic::compiler_fence(core::sync::atomic::Ordering::SeqCst);
    }
}

impl StateOnlyPrivateMerkleTree {
    pub fn binary_depth(&self) -> u32 {
        self.binary_depth
    }

    pub fn tree_tag(&self) -> u8 {
        self.tree_tag
    }

    pub fn value_width(&self) -> usize {
        self.value_width
    }

    pub fn leaf_count(&self) -> usize {
        self.levels[0].len()
    }

    pub fn root(&self) -> [u8; 32] {
        self.levels.last().unwrap()[0]
    }

    /// Canonical frontier order consumed by the in-core
    /// radix-4/binary-cap verifier.
    pub fn frontier(
        &self,
        expected_sorted_indices: &[u32],
    ) -> Result<Vec<[u8; 32]>, StateOnlyPrivateOpeningBuildError> {
        validate_indices(self.binary_depth, expected_sorted_indices)?;
        let mut frontier = Vec::new();
        let mut current = expected_sorted_indices.to_vec();
        for level in &self.levels[..self.levels.len() - 1] {
            if level.len() == 2 {
                if current.len() == 1 {
                    frontier.push(level[(current[0] ^ 1) as usize]);
                }
                current.clear();
                current.push(0);
                continue;
            }
            let mut next = Vec::new();
            let mut position = 0usize;
            while position < current.len() {
                let parent = current[position] >> 2;
                let mut present = 0u8;
                while position < current.len() && current[position] >> 2 == parent {
                    present |= 1u8 << (current[position] & 3);
                    position += 1;
                }
                for slot in 0..4u32 {
                    if present & (1u8 << slot) == 0 {
                        frontier.push(level[(4 * parent + slot) as usize]);
                    }
                }
                next.push(parent);
            }
            current = next;
        }
        Ok(frontier)
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct BuiltStateOnlyPrivateOpening {
    pub bytes: Vec<u8>,
    pub frontier_nodes: usize,
}

fn checked_leaf_count(binary_depth: u32) -> Result<usize, StateOnlyPrivateOpeningBuildError> {
    if binary_depth >= 32 || binary_depth >= usize::BITS {
        return Err(StateOnlyPrivateOpeningBuildError::InvalidDepth {
            depth: binary_depth,
        });
    }
    Ok(1usize << binary_depth)
}

fn validate_indices(
    binary_depth: u32,
    indices: &[u32],
) -> Result<(), StateOnlyPrivateOpeningBuildError> {
    let leaf_count = checked_leaf_count(binary_depth)?;
    if indices.is_empty() {
        return Err(StateOnlyPrivateOpeningBuildError::EmptyOpening);
    }
    if indices.len() > u16::MAX as usize {
        return Err(StateOnlyPrivateOpeningBuildError::CountOutOfRange {
            count: indices.len(),
        });
    }
    for pair in indices.windows(2) {
        if pair[0] >= pair[1] {
            return Err(StateOnlyPrivateOpeningBuildError::IndicesNotStrictlyIncreasing);
        }
    }
    if let Some(&index) = indices.iter().find(|&&index| index as usize >= leaf_count) {
        return Err(StateOnlyPrivateOpeningBuildError::LeafIndexOutOfRange { index });
    }
    Ok(())
}

fn value_at<'a>(values: &'a [u8], value_width: usize, index: usize) -> Option<&'a [u8]> {
    let start = index.checked_mul(value_width)?;
    values.get(start..start.checked_add(value_width)?)
}

/// Build a canonical `2^binary_depth` radix-4 tree with an optional binary
/// cap. Leaf nodes are salted once with `private_leaf_hash`; there is no
/// second leaf-hash layer.
pub fn build_state_only_private_merkle_tree(
    hash: HashFn,
    binary_depth: u32,
    tree_tag: u8,
    value_width: usize,
    values: &[u8],
    salts: &[[u8; STATE_ONLY_PRIVATE_LEAF_SALT_BYTES]],
) -> Result<StateOnlyPrivateMerkleTree, StateOnlyPrivateOpeningBuildError> {
    let leaf_count = checked_leaf_count(binary_depth)?;
    if value_width == 0 {
        return Err(StateOnlyPrivateOpeningBuildError::InvalidValueWidth { width: value_width });
    }
    let expected_values = leaf_count
        .checked_mul(value_width)
        .ok_or(StateOnlyPrivateOpeningBuildError::LengthOverflow)?;
    if values.len() != expected_values {
        return Err(StateOnlyPrivateOpeningBuildError::ValuesLengthMismatch {
            expected: expected_values,
            actual: values.len(),
        });
    }
    if salts.len() != leaf_count {
        return Err(StateOnlyPrivateOpeningBuildError::SaltCountMismatch {
            expected: leaf_count,
            actual: salts.len(),
        });
    }

    let mut levels = vec![(0..leaf_count)
        .map(|index| {
            private_leaf_hash(
                hash,
                tree_tag,
                value_at(values, value_width, index).unwrap(),
                &salts[index],
            )
        })
        .collect::<Vec<_>>()];
    while levels.last().unwrap().len() > 1 {
        let previous = levels.last().unwrap();
        let next = if previous.len() == 2 {
            vec![node_hash(hash, &previous[0], &previous[1])]
        } else {
            previous
                .chunks_exact(4)
                .map(|children| node_hash4(hash, children.try_into().unwrap()))
                .collect()
        };
        levels.push(next);
    }
    Ok(StateOnlyPrivateMerkleTree {
        hash,
        binary_depth,
        tree_tag,
        value_width,
        levels,
    })
}

/// Serialize one opening as
/// `count_u16 || (value || salt32)^count || frontier_count_u32 || frontier`.
/// Indices are supplied by the transcript and are not proof bytes.
pub fn serialize_state_only_private_opening(
    tree: &StateOnlyPrivateMerkleTree,
    values: &[u8],
    salts: &[[u8; STATE_ONLY_PRIVATE_LEAF_SALT_BYTES]],
    expected_sorted_indices: &[u32],
) -> Result<BuiltStateOnlyPrivateOpening, StateOnlyPrivateOpeningBuildError> {
    validate_indices(tree.binary_depth, expected_sorted_indices)?;
    let expected_values = tree
        .leaf_count()
        .checked_mul(tree.value_width)
        .ok_or(StateOnlyPrivateOpeningBuildError::LengthOverflow)?;
    if values.len() != expected_values {
        return Err(StateOnlyPrivateOpeningBuildError::ValuesLengthMismatch {
            expected: expected_values,
            actual: values.len(),
        });
    }
    if salts.len() != tree.leaf_count() {
        return Err(StateOnlyPrivateOpeningBuildError::SaltCountMismatch {
            expected: tree.leaf_count(),
            actual: salts.len(),
        });
    }

    for &index in expected_sorted_indices {
        let index = index as usize;
        let digest = private_leaf_hash(
            tree.hash,
            tree.tree_tag,
            value_at(values, tree.value_width, index).unwrap(),
            &salts[index],
        );
        if digest != tree.levels[0][index] {
            return Err(
                StateOnlyPrivateOpeningBuildError::OpenedLeafDoesNotMatchTree {
                    index: index as u32,
                },
            );
        }
    }

    let frontier = tree.frontier(expected_sorted_indices)?;
    let record_width = tree
        .value_width
        .checked_add(STATE_ONLY_PRIVATE_LEAF_SALT_BYTES)
        .ok_or(StateOnlyPrivateOpeningBuildError::LengthOverflow)?;
    let records_len = expected_sorted_indices
        .len()
        .checked_mul(record_width)
        .ok_or(StateOnlyPrivateOpeningBuildError::LengthOverflow)?;
    let frontier_len = frontier
        .len()
        .checked_mul(32)
        .ok_or(StateOnlyPrivateOpeningBuildError::LengthOverflow)?;
    let capacity = 2usize
        .checked_add(records_len)
        .and_then(|value| value.checked_add(4))
        .and_then(|value| value.checked_add(frontier_len))
        .ok_or(StateOnlyPrivateOpeningBuildError::LengthOverflow)?;
    let mut bytes = Vec::with_capacity(capacity);
    bytes.extend_from_slice(&(expected_sorted_indices.len() as u16).to_le_bytes());
    for &index in expected_sorted_indices {
        let index = index as usize;
        bytes.extend_from_slice(value_at(values, tree.value_width, index).unwrap());
        bytes.extend_from_slice(&salts[index]);
    }
    bytes.extend_from_slice(&(frontier.len() as u32).to_le_bytes());
    for node in &frontier {
        bytes.extend_from_slice(node);
    }
    Ok(BuiltStateOnlyPrivateOpening {
        bytes,
        frontier_nodes: frontier.len(),
    })
}

#[cfg(test)]
mod tests {
    use aspis_core::state_only_private_openings::{
        verify_state_only_private_opening, verify_state_only_private_opening_from_proof,
        StateOnlyPrivateOpeningError,
    };

    use super::*;
    use crate::HOST_HASH;

    const DEPTH: u32 = 5;
    const WIDTH: usize = 64;
    const TAG: u8 = 0x71;
    const INDICES: [u32; 3] = [1, 7, 30];

    fn fixture() -> (
        Vec<u8>,
        Vec<[u8; STATE_ONLY_PRIVATE_LEAF_SALT_BYTES]>,
        StateOnlyPrivateMerkleTree,
        BuiltStateOnlyPrivateOpening,
    ) {
        let leaves = 1usize << DEPTH;
        let values = (0..leaves * WIDTH)
            .map(|offset| {
                let leaf = offset / WIDTH;
                let byte = offset % WIDTH;
                (leaf as u8)
                    .wrapping_mul(13)
                    .wrapping_add((byte as u8).wrapping_mul(7))
                    .wrapping_add(3)
            })
            .collect::<Vec<_>>();
        let salts = (0..leaves)
            .map(|leaf| {
                core::array::from_fn(|byte| {
                    (leaf as u8)
                        .wrapping_mul(17)
                        .wrapping_add((byte as u8).wrapping_mul(11))
                        .wrapping_add(5)
                })
            })
            .collect::<Vec<_>>();
        let tree =
            build_state_only_private_merkle_tree(HOST_HASH, DEPTH, TAG, WIDTH, &values, &salts)
                .unwrap();
        let opening =
            serialize_state_only_private_opening(&tree, &values, &salts, &INDICES).unwrap();
        (values, salts, tree, opening)
    }

    #[test]
    fn private_opening_roundtrip_zero_copy_and_kat() {
        let (values, salts, tree, opening) = fixture();
        let parsed = verify_state_only_private_opening(
            HOST_HASH,
            &tree.root(),
            DEPTH,
            TAG,
            WIDTH,
            &INDICES,
            &opening.bytes,
        )
        .unwrap();
        assert_eq!(parsed.count, INDICES.len());
        for (ordinal, &index) in INDICES.iter().enumerate() {
            assert_eq!(
                parsed.value(ordinal).unwrap(),
                value_at(&values, WIDTH, index as usize).unwrap()
            );
            assert_eq!(parsed.salt(ordinal).unwrap(), &salts[index as usize]);
        }
        assert_eq!(parsed.records.as_ptr(), opening.bytes[2..].as_ptr());
        assert_eq!(opening.frontier_nodes, 14);
        assert_eq!(
            tree.root(),
            [
                0x62, 0x21, 0x1c, 0x74, 0x11, 0x21, 0x67, 0x11, 0x1f, 0xab, 0x10, 0x10, 0xaa, 0x01,
                0x8d, 0xb1, 0x7e, 0xd8, 0x5a, 0xb3, 0x03, 0xa6, 0xe4, 0x33, 0xe2, 0x4e, 0x57, 0x7f,
                0xf5, 0xe7, 0xa3, 0x23,
            ]
        );
    }

    #[test]
    fn private_opening_tag_value_salt_frontier_and_framing_teeth() {
        let (_values, _salts, tree, opening) = fixture();
        let verify = |bytes: &[u8], tag: u8, indices: &[u32]| {
            verify_state_only_private_opening(
                HOST_HASH,
                &tree.root(),
                DEPTH,
                tag,
                WIDTH,
                indices,
                bytes,
            )
            .map(|_| ())
        };

        assert_eq!(
            verify(&opening.bytes, TAG ^ 1, &INDICES),
            Err(StateOnlyPrivateOpeningError::MerkleMismatch)
        );

        let mut wrong_value = opening.bytes.clone();
        wrong_value[2 + 19] ^= 1;
        assert_eq!(
            verify(&wrong_value, TAG, &INDICES),
            Err(StateOnlyPrivateOpeningError::MerkleMismatch)
        );

        let mut wrong_salt = opening.bytes.clone();
        wrong_salt[2 + WIDTH + 23] ^= 1;
        assert_eq!(
            verify(&wrong_salt, TAG, &INDICES),
            Err(StateOnlyPrivateOpeningError::MerkleMismatch)
        );

        let mut wrong_frontier = opening.bytes.clone();
        *wrong_frontier.last_mut().unwrap() ^= 1;
        assert_eq!(
            verify(&wrong_frontier, TAG, &INDICES),
            Err(StateOnlyPrivateOpeningError::MerkleMismatch)
        );

        let mut wrong_count = opening.bytes.clone();
        wrong_count[..2].copy_from_slice(&2u16.to_le_bytes());
        assert_eq!(
            verify(&wrong_count, TAG, &INDICES),
            Err(StateOnlyPrivateOpeningError::CountMismatch {
                expected: 3,
                actual: 2,
            })
        );

        assert_eq!(
            verify(&opening.bytes, TAG, &[7, 1, 30]),
            Err(StateOnlyPrivateOpeningError::IndicesNotStrictlyIncreasing)
        );

        let mut trailing = opening.bytes.clone();
        trailing.push(0xa5);
        assert_eq!(
            verify(&trailing, TAG, &INDICES),
            Err(StateOnlyPrivateOpeningError::TrailingBytes {
                offset: opening.bytes.len(),
                remaining: 1,
            })
        );
        let (_, remainder) = verify_state_only_private_opening_from_proof(
            HOST_HASH,
            &tree.root(),
            DEPTH,
            TAG,
            WIDTH,
            &INDICES,
            &trailing,
        )
        .unwrap();
        assert_eq!(remainder, &[0xa5]);
    }
}

