//! Fixed-boundary publication for the production Spend Good worker.
//!
//! Complete proof attempts and every controlled failure stay on the private
//! side of this state machine. At the caller-selected public boundary the
//! controller invokes exactly one channel operation with either proof bytes
//! or one undifferentiated abort symbol: timing, exact-boundary tie
//! handling, single-publication, generic abort, and drop-time scrubbing all
//! live in one generic core. The candidate type is opaque: only the mined
//! cap-17 Good worker can construct it.
//!
//! The wallet is responsible for making this channel the *only* externally
//! observable interface of the worker and for invoking `release` at the
//! selected boundary. The clock prevents early publication; it cannot make
//! a late caller run in the past, so late invocation belongs in the caller's
//! `epsilon_side` timing model. This module neither claims nor provides
//! protection against local hardware, scheduler, filesystem, power, or
//! process side channels.

use std::thread;
use std::time::{Duration, SystemTime};

use crate::state_only_good_spend::SpendAttemptsExhausted;
use crate::state_only_spend::SpendFirstGoodCandidate;

#[derive(Debug, PartialEq, Eq)]
pub enum SpendPublicRelease {
    Proof(Vec<u8>),
    Abort,
}

pub trait SpendReleaseClock {
    type Instant: Copy + Ord;

    fn now(&self) -> Self::Instant;
    fn wait_until(&mut self, target: Self::Instant);
}

pub trait SpendReleaseChannel {
    fn publish(&mut self, release: SpendPublicRelease);
}

#[derive(Clone, Copy, Debug, Default)]
pub struct SpendSystemReleaseClock;

impl SpendReleaseClock for SpendSystemReleaseClock {
    type Instant = SystemTime;

    fn now(&self) -> Self::Instant {
        SystemTime::now()
    }

    fn wait_until(&mut self, target: Self::Instant) {
        const MAX_SLEEP: Duration = Duration::from_millis(250);
        loop {
            let Ok(remaining) = target.duration_since(SystemTime::now()) else {
                break;
            };
            if remaining.is_zero() {
                break;
            }
            thread::sleep(remaining.min(MAX_SLEEP));
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct SpendReleaseComplete(());

pub(crate) trait FixedReleaseCandidate: Sized {
    fn production_ready(&self) -> bool;
    fn scrub(&mut self);
    fn into_public_bytes(self) -> Vec<u8>;
}

pub(crate) enum FixedReleaseState<C> {
    Waiting,
    Proof(C),
    Abort,
    Released,
}

pub(crate) struct FixedReleaseCore<I, C>
where
    I: Copy + Ord,
    C: FixedReleaseCandidate,
{
    boundary: I,
    state: FixedReleaseState<C>,
}

impl<I, C> FixedReleaseCore<I, C>
where
    I: Copy + Ord,
    C: FixedReleaseCandidate,
{
    pub(crate) fn new(boundary: I) -> Self {
        Self {
            boundary,
            state: FixedReleaseState::Waiting,
        }
    }

    /// Record one private worker completion.  The public-boundary timer wins
    /// an exact timestamp tie: only `completed_at < boundary` is eligible.
    /// A completion at/after the boundary, a duplicate completion, or a
    /// non-production candidate is scrubbed and can only produce the same
    /// abort.
    pub(crate) fn record_completion<E>(&mut self, completed_at: I, completion: Result<C, E>) {
        let before_boundary = completed_at < self.boundary;
        match completion {
            Ok(candidate)
                if before_boundary
                    && matches!(self.state, FixedReleaseState::Waiting)
                    && candidate.production_ready() =>
            {
                self.state = FixedReleaseState::Proof(candidate);
            }
            Ok(mut candidate) => {
                candidate.scrub();
                if before_boundary && matches!(self.state, FixedReleaseState::Waiting) {
                    self.state = FixedReleaseState::Abort;
                }
            }
            Err(_) => {
                if before_boundary && matches!(self.state, FixedReleaseState::Waiting) {
                    self.state = FixedReleaseState::Abort;
                }
            }
        }
    }

    pub(crate) fn release<CLOCK, CHANNEL>(mut self, clock: &mut CLOCK, channel: &mut CHANNEL)
    where
        CLOCK: SpendReleaseClock<Instant = I>,
        CHANNEL: SpendReleaseChannel,
    {
        clock.wait_until(self.boundary);
        assert!(
            clock.now() >= self.boundary,
            "SpendReleaseClock violated wait_until contract"
        );

        // Mark the controller released before entering caller channel code.
        // Consuming `self` also makes a second publication impossible through
        // the safe API, even if the channel retains the payload.
        let state = core::mem::replace(&mut self.state, FixedReleaseState::Released);
        let release = match state {
            FixedReleaseState::Proof(candidate) => {
                SpendPublicRelease::Proof(candidate.into_public_bytes())
            }
            FixedReleaseState::Waiting | FixedReleaseState::Abort => SpendPublicRelease::Abort,
            FixedReleaseState::Released => unreachable!("consumed controller released twice"),
        };
        channel.publish(release);
    }
}

impl<I, C> Drop for FixedReleaseCore<I, C>
where
    I: Copy + Ord,
    C: FixedReleaseCandidate,
{
    fn drop(&mut self) {
        if let FixedReleaseState::Proof(candidate) = &mut self.state {
            candidate.scrub();
        }
    }
}

impl FixedReleaseCandidate for SpendFirstGoodCandidate {
    fn production_ready(&self) -> bool {
        SpendFirstGoodCandidate::production_ready(self)
    }

    fn scrub(&mut self) {
        SpendFirstGoodCandidate::scrub(self);
    }

    fn into_public_bytes(self) -> Vec<u8> {
        self.into_released_bytes()
    }
}

/// Sealed controller whose only public edge is one proof-or-abort event at
/// the caller-selected boundary. Attempt counts, selectors, Good failures,
/// PoW failures, roots, and partial proofs never cross this boundary.
pub struct SpendFixedReleaseController<I>
where
    I: Copy + Ord,
{
    core: FixedReleaseCore<I, SpendFirstGoodCandidate>,
}

impl<I> SpendFixedReleaseController<I>
where
    I: Copy + Ord,
{
    pub fn new(boundary: I) -> Self {
        Self {
            core: FixedReleaseCore::new(boundary),
        }
    }

    pub fn record_first_good_completion<CLOCK>(
        &mut self,
        clock: &CLOCK,
        completion: Result<SpendFirstGoodCandidate, SpendAttemptsExhausted>,
    ) where
        CLOCK: SpendReleaseClock<Instant = I>,
    {
        self.core.record_completion(clock.now(), completion);
    }

    pub fn release<CLOCK, CHANNEL>(
        self,
        clock: &mut CLOCK,
        channel: &mut CHANNEL,
    ) -> SpendReleaseComplete
    where
        CLOCK: SpendReleaseClock<Instant = I>,
        CHANNEL: SpendReleaseChannel,
    {
        self.core.release(clock, channel);
        SpendReleaseComplete(())
    }
}

#[cfg(test)]
mod tests {
    use std::cell::{Cell, RefCell};
    use std::rc::Rc;

    use super::*;

    #[derive(Clone)]
    struct TestClock {
        now: Rc<Cell<u64>>,
        waits: Rc<RefCell<Vec<u64>>>,
    }

    impl TestClock {
        fn new(now: u64) -> Self {
            Self {
                now: Rc::new(Cell::new(now)),
                waits: Rc::new(RefCell::new(Vec::new())),
            }
        }

        fn set(&self, now: u64) {
            self.now.set(now);
        }
    }

    impl SpendReleaseClock for TestClock {
        type Instant = u64;

        fn now(&self) -> Self::Instant {
            self.now.get()
        }

        fn wait_until(&mut self, target: Self::Instant) {
            self.waits.borrow_mut().push(target);
            self.now.set(self.now.get().max(target));
        }
    }

    #[derive(Debug, PartialEq, Eq)]
    enum PublicTraceEntry {
        Proof { at: u64, bytes: Vec<u8> },
        Abort { at: u64 },
    }

    struct TestChannel {
        now: Rc<Cell<u64>>,
        trace: Vec<PublicTraceEntry>,
    }

    impl TestChannel {
        fn for_clock(clock: &TestClock) -> Self {
            Self {
                now: Rc::clone(&clock.now),
                trace: Vec::new(),
            }
        }
    }

    impl SpendReleaseChannel for TestChannel {
        fn publish(&mut self, release: SpendPublicRelease) {
            assert!(self.trace.is_empty(), "Spend adapter published twice");
            let at = self.now.get();
            self.trace.push(match release {
                SpendPublicRelease::Proof(bytes) => PublicTraceEntry::Proof { at, bytes },
                SpendPublicRelease::Abort => PublicTraceEntry::Abort { at },
            });
        }
    }

    fn candidate(
        bytes: &[u8],
        ready: bool,
        scrub_count: &Rc<Cell<usize>>,
    ) -> SpendFirstGoodCandidate {
        SpendFirstGoodCandidate::synthetic_release_test(
            bytes.to_vec(),
            ready,
            Rc::clone(scrub_count),
        )
    }

    #[test]
    fn early_ready_completion_releases_one_proof_at_the_boundary_and_scrubs() {
        let scrub_count = Rc::new(Cell::new(0));
        let mut controller = SpendFixedReleaseController::new(1_000);
        let mut clock = TestClock::new(100);
        let mut channel = TestChannel::for_clock(&clock);

        controller
            .record_first_good_completion(&clock, Ok(candidate(&[0x23, 0x16], true, &scrub_count)));
        assert!(channel.trace.is_empty());
        assert_eq!(scrub_count.get(), 0);
        let _ = controller.release(&mut clock, &mut channel);

        assert_eq!(&*clock.waits.borrow(), &[1_000]);
        assert_eq!(
            channel.trace,
            vec![PublicTraceEntry::Proof {
                at: 1_000,
                bytes: vec![0x23, 0x16],
            }]
        );
        assert_eq!(scrub_count.get(), 1);
    }

    #[test]
    fn exact_boundary_and_late_completions_abort_and_scrub_candidates() {
        for completed_at in [1_000, 1_001] {
            let scrub_count = Rc::new(Cell::new(0));
            let mut controller = SpendFixedReleaseController::new(1_000);
            let mut clock = TestClock::new(completed_at);
            let mut channel = TestChannel::for_clock(&clock);

            controller
                .record_first_good_completion(&clock, Ok(candidate(&[0x23], true, &scrub_count)));
            assert_eq!(scrub_count.get(), 1);
            let _ = controller.release(&mut clock, &mut channel);

            assert_eq!(
                channel.trace,
                vec![PublicTraceEntry::Abort { at: completed_at }]
            );
            assert_eq!(scrub_count.get(), 1);
        }
    }

    #[test]
    fn no_completion_and_opaque_worker_failure_each_release_one_abort() {
        let empty = SpendFixedReleaseController::new(1_000);
        let mut empty_clock = TestClock::new(0);
        let mut empty_channel = TestChannel::for_clock(&empty_clock);
        let _ = empty.release(&mut empty_clock, &mut empty_channel);
        assert_eq!(
            empty_channel.trace,
            vec![PublicTraceEntry::Abort { at: 1_000 }]
        );

        let mut failed = SpendFixedReleaseController::new(1_000);
        let mut failed_clock = TestClock::new(100);
        let mut failed_channel = TestChannel::for_clock(&failed_clock);
        failed.record_first_good_completion(&failed_clock, Err(SpendAttemptsExhausted));
        let _ = failed.release(&mut failed_clock, &mut failed_channel);
        assert_eq!(
            failed_channel.trace,
            vec![PublicTraceEntry::Abort { at: 1_000 }]
        );
    }

    #[test]
    fn nonproduction_candidate_is_scrubbed_and_can_only_release_abort() {
        let scrub_count = Rc::new(Cell::new(0));
        let mut controller = SpendFixedReleaseController::new(1_000);
        let mut clock = TestClock::new(100);
        let mut channel = TestChannel::for_clock(&clock);

        controller.record_first_good_completion(
            &clock,
            Ok(candidate(&[0xde, 0xad], false, &scrub_count)),
        );
        assert_eq!(scrub_count.get(), 1);
        let _ = controller.release(&mut clock, &mut channel);

        assert_eq!(channel.trace, vec![PublicTraceEntry::Abort { at: 1_000 }]);
        assert_eq!(scrub_count.get(), 1);
    }

    #[test]
    fn duplicate_completion_scrubs_the_loser_and_publishes_the_first_once() {
        let first_scrubs = Rc::new(Cell::new(0));
        let second_scrubs = Rc::new(Cell::new(0));
        let mut controller = SpendFixedReleaseController::new(1_000);
        let mut clock = TestClock::new(100);
        let mut channel = TestChannel::for_clock(&clock);

        controller
            .record_first_good_completion(&clock, Ok(candidate(&[0x01], true, &first_scrubs)));
        clock.set(200);
        controller
            .record_first_good_completion(&clock, Ok(candidate(&[0x02], true, &second_scrubs)));
        assert_eq!(first_scrubs.get(), 0);
        assert_eq!(second_scrubs.get(), 1);

        let _ = controller.release(&mut clock, &mut channel);
        assert_eq!(
            channel.trace,
            vec![PublicTraceEntry::Proof {
                at: 1_000,
                bytes: vec![0x01],
            }]
        );
        assert_eq!(first_scrubs.get(), 1);
        assert_eq!(second_scrubs.get(), 1);
    }

    #[test]
    fn dropping_a_buffered_controller_scrubs_without_publishing() {
        let scrub_count = Rc::new(Cell::new(0));
        let clock = TestClock::new(100);
        let mut controller = SpendFixedReleaseController::new(1_000);
        controller.record_first_good_completion(&clock, Ok(candidate(&[0x23], true, &scrub_count)));
        assert_eq!(scrub_count.get(), 0);
        drop(controller);
        assert_eq!(scrub_count.get(), 1);
    }
}

crates/aspis-prover/src/state_only_zeroc:
//! Host prover scaffold for the ten-round degree-27 state-only zerocheck.
//!
//! This module is deliberately not wired into any payment profile.  It emits
//! the isolated 4,480-byte state-only sumcheck field consumed by
//! `aspis_core::state_only_sumcheck` and uses its distinct transcript label.

use aspis_core::field::{CM31, M31, QM31};
use aspis_core::state_only_sumcheck::{
    absorb_state_only_sumcheck_round, encode_state_only_polynomial, evaluate_state_only_polynomial,
    state_only_boundary_sum, StateOnlySumcheckPolynomial, STATE_ONLY_SUMCHECK_BYTES,
    STATE_ONLY_SUMCHECK_COEFFICIENTS, STATE_ONLY_SUMCHECK_DEGREE, STATE_ONLY_SUMCHECK_ROUNDS,
    STATE_ONLY_SUMCHECK_ROUND_BYTES,
};
use aspis_core::transcript::{ChallengeSampleExhausted, Transcript};

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct StateOnlyZerocheckTrace {
    pub proof: [u8; STATE_ONLY_SUMCHECK_BYTES],
    pub challenges: [QM31; STATE_ONLY_SUMCHECK_ROUNDS],
    pub terminal_claim: QM31,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum StateOnlyZerocheckProveError<E> {
    Oracle(E),
    BoundaryMismatch { round: usize },
    TerminalMismatch,
    ChallengeSampleExhausted,
}

impl<E> From<ChallengeSampleExhausted> for StateOnlyZerocheckProveError<E> {
    fn from(_: ChallengeSampleExhausted) -> Self {
        Self::ChallengeSampleExhausted
    }
}

/// Interpolate the unique degree-at-most-27 polynomial through values at the
/// base-field points `0..=27`.  This is host prover work, so the candidate
/// verifier's CU ledger contains none of it.
fn interpolate_state_only(
    values: &[QM31; STATE_ONLY_SUMCHECK_COEFFICIENTS],
) -> StateOnlySumcheckPolynomial {
    let mut output = [QM31::ZERO; STATE_ONLY_SUMCHECK_COEFFICIENTS];
    for i in 0..=STATE_ONLY_SUMCHECK_DEGREE {
        let mut basis = [QM31::ZERO; STATE_ONLY_SUMCHECK_COEFFICIENTS];
        basis[0] = QM31::ONE;
        let mut basis_degree = 0usize;
        let mut denominator = M31::ONE;
        for j in 0..=STATE_ONLY_SUMCHECK_DEGREE {
            if i == j {
                continue;
            }
            let root = M31(j as u32);
            let previous = basis;
            for coefficient in 0..=basis_degree + 1 {
                let shifted = if coefficient == 0 {
                    QM31::ZERO
                } else {
                    previous[coefficient - 1]
                };
                let constant = if coefficient <= basis_degree {
                    previous[coefficient].mul_m31(root)
                } else {
                    QM31::ZERO
                };
                basis[coefficient] = shifted.sub(constant);
            }
            basis_degree += 1;
            denominator = denominator.mul(M31(i as u32).sub(root));
        }
        let scale = values[i].mul_m31(denominator.inv());
        for coefficient in 0..=STATE_ONLY_SUMCHECK_DEGREE {
            output[coefficient] = output[coefficient].add(scale.mul(basis[coefficient]));
        }
    }
    output
}

/// Prove a degree-at-most-27-in-each-variable oracle from a supplied Boolean
/// hypercube sum.  The caller is responsible for binding the initial claim
/// before invoking this production-neutral scaffold.
pub fn prove_state_only_sumcheck_from_claim<F, E>(
    transcript: &mut Transcript,
    mut oracle: F,
    initial_claim: QM31,
) -> Result<StateOnlyZerocheckTrace, StateOnlyZerocheckProveError<E>>
where
    F: FnMut(&[QM31; STATE_ONLY_SUMCHECK_ROUNDS]) -> Result<QM31, E>,
{
    let mut proof = [0u8; STATE_ONLY_SUMCHECK_BYTES];
    let mut challenges = [QM31::ZERO; STATE_ONLY_SUMCHECK_ROUNDS];
    let mut running_claim = initial_claim;
    let mut prefix = [QM31::ZERO; STATE_ONLY_SUMCHECK_ROUNDS];

    for round in 0..STATE_ONLY_SUMCHECK_ROUNDS {
        let mut samples = [QM31::ZERO; STATE_ONLY_SUMCHECK_COEFFICIENTS];
        let remaining = STATE_ONLY_SUMCHECK_ROUNDS - round - 1;
        for (sample_index, sample) in samples.iter_mut().enumerate() {
            prefix[round] = QM31::from_cm31(CM31::from_m31(M31(sample_index as u32)));
            let mut total = QM31::ZERO;
            for assignment in 0..(1usize << remaining) {
                for offset in 0..remaining {
                    let bit = (assignment >> (remaining - 1 - offset)) & 1;
                    prefix[round + 1 + offset] = if bit == 0 { QM31::ZERO } else { QM31::ONE };
                }
                total = total.add(oracle(&prefix).map_err(StateOnlyZerocheckProveError::Oracle)?);
            }
            *sample = total;
        }

        let polynomial = interpolate_state_only(&samples);
        if state_only_boundary_sum(&polynomial) != running_claim {
            return Err(StateOnlyZerocheckProveError::BoundaryMismatch { round });
        }
        let encoded = encode_state_only_polynomial(&polynomial);
        let start = round * STATE_ONLY_SUMCHECK_ROUND_BYTES;
        proof[start..start + STATE_ONLY_SUMCHECK_ROUND_BYTES].copy_from_slice(&encoded);
        let challenge = absorb_state_only_sumcheck_round(transcript, round, &encoded)?;
        prefix[round] = challenge;
        challenges[round] = challenge;
        running_claim = evaluate_state_only_polynomial(&polynomial, challenge);
    }

    if oracle(&challenges).map_err(StateOnlyZerocheckProveError::Oracle)? != running_claim {
        return Err(StateOnlyZerocheckProveError::TerminalMismatch);
    }
    Ok(StateOnlyZerocheckTrace {
        proof,
        challenges,
        terminal_claim: running_claim,
    })
}

/// Ordinary zerocheck wrapper: the claimed Boolean-cube sum is zero.
pub fn prove_state_only_zerocheck<F, E>(
    transcript: &mut Transcript,
    oracle: F,
) -> Result<StateOnlyZerocheckTrace, StateOnlyZerocheckProveError<E>>
where
    F: FnMut(&[QM31; STATE_ONLY_SUMCHECK_ROUNDS]) -> Result<QM31, E>,
{
    prove_state_only_sumcheck_from_claim(transcript, oracle, QM31::ZERO)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::HOST_HASH;
    use aspis_core::state_only_sumcheck::{
        verify_state_only_sumcheck_streaming, STATE_ONLY_VERIFY_M31_MULS,
        STATE_ONLY_VERIFY_QM31_ADDS, STATE_ONLY_VERIFY_QM31_MULS,
    };
    use aspis_core::transcript::label;

    fn q(seed: u32) -> QM31 {
        QM31 {
            c0: CM31::new(M31(seed * 1_003 + 1), M31(seed * 1_009 + 3)),
            c1: CM31::new(M31(seed * 1_021 + 5), M31(seed * 1_031 + 7)),
        }
    }

    fn pow(mut base: QM31, mut exponent: usize) -> QM31 {
        let mut result = QM31::ONE;
        while exponent != 0 {
            if exponent & 1 == 1 {
                result = result.mul(base);
            }
            base = base.square();
            exponent >>= 1;
        }
        result
    }

    fn degree_27_oracle(seed: u32, point: &[QM31; STATE_ONLY_SUMCHECK_ROUNDS]) -> QM31 {
        point
            .iter()
            .enumerate()
            .fold(q(seed + 1), |value, (coordinate, x)| {
                let high =
                    pow(*x, STATE_ONLY_SUMCHECK_DEGREE).mul(q(seed + 101 + coordinate as u32));
                value.mul(
                    q(seed + 211 + coordinate as u32)
                        .add(x.mul(q(seed + 307 + coordinate as u32)))
                        .add(high),
                )
            })
    }

    fn boolean_sum(seed: u32) -> QM31 {
        (0..1usize << STATE_ONLY_SUMCHECK_ROUNDS).fold(QM31::ZERO, |sum, assignment| {
            let point = core::array::from_fn(|coordinate| {
                if (assignment >> (STATE_ONLY_SUMCHECK_ROUNDS - 1 - coordinate)) & 1 == 0 {
                    QM31::ZERO
                } else {
                    QM31::ONE
                }
            });
            sum.add(degree_27_oracle(seed, &point))
        })
    }

    #[test]
    fn degree_27_prover_matches_streaming_verifier_and_terminal_oracle() {
        for seed in [7u32, 29, 83] {
            let initial_claim = boolean_sum(seed);
            let mut prover_transcript = Transcript::new(HOST_HASH);
            prover_transcript.absorb(label::STATEMENT, &seed.to_le_bytes());
            let proof = prove_state_only_sumcheck_from_claim(
                &mut prover_transcript,
                |point| Ok::<_, ()>(degree_27_oracle(seed, point)),
                initial_claim,
            )
            .unwrap();

            assert_eq!(proof.proof.len(), 4_480);
            assert_eq!(
                proof.terminal_claim,
                degree_27_oracle(seed, &proof.challenges)
            );
            let mut verifier_transcript = Transcript::new(HOST_HASH);
            verifier_transcript.absorb(label::STATEMENT, &seed.to_le_bytes());
            let verified = verify_state_only_sumcheck_streaming(
                &mut verifier_transcript,
                &proof.proof,
                initial_claim,
            )
            .unwrap();
            assert_eq!(verified.point, proof.challenges);
            assert_eq!(verified.terminal_claim, proof.terminal_claim);
            assert_eq!(
                verifier_transcript.diagnostic_state(),
                prover_transcript.diagnostic_state()
            );
        }
    }

    #[test]
    fn wrong_initial_claim_is_rejected_by_the_prover_boundary() {
        let seed = 41u32;
        let mut transcript = Transcript::new(HOST_HASH);
        transcript.absorb(label::STATEMENT, &seed.to_le_bytes());
        assert_eq!(
            prove_state_only_sumcheck_from_claim(
                &mut transcript,
                |point| Ok::<_, ()>(degree_27_oracle(seed, point)),
                boolean_sum(seed).add(QM31::ONE),
            ),
            Err(StateOnlyZerocheckProveError::BoundaryMismatch { round: 0 })
        );
    }

    #[test]
    fn production_neutral_inventory_matches_core() {
        assert_eq!(STATE_ONLY_SUMCHECK_BYTES, 4_480);
        assert_eq!(STATE_ONLY_VERIFY_QM31_MULS, 300);
        assert_eq!(STATE_ONLY_VERIFY_QM31_ADDS, 130);
        assert_eq!(STATE_ONLY_VERIFY_M31_MULS, 2_660);
    }
}

crates/aspis-prover/src/v5_a_full_view_r:
//! Exact test support for Component-A and structured Component-B rank checks.
//!
//! This is deliberately test-only.  It supplies the exact inactive-kernel
//! basis and rank helpers used by the current structured-layout probes, plus a
//! Boolean-MLE counterexample showing why fibre injectivity alone cannot imply
//! deterministic rank for arbitrary Fiat--Shamir schedules.

use aspis_core::field::{M31, QM31};
use aspis_statement::atomic_state_only_terminal::atomic_state_only_copy_inactive_row_masks_v3;
use aspis_statement::{
    binary_successor_point, decode_asset_id_canonical, decode_digest_canonical, xor12_point,
    AtomicPaymentStatementV4, SpendPublic,
};

use super::{mask_m31_column, M31BlockMask, V5_MASK_B, V5_MASK_M, V5_TRACE_ROWS};
use crate::multilinear_eval;

fn decode_hex_32(value: &str) -> [u8; 32] {
    assert_eq!(value.len(), 64);
    let mut decoded = [0u8; 32];
    for (index, output) in decoded.iter_mut().enumerate() {
        *output = u8::from_str_radix(&value[index * 2..index * 2 + 2], 16).unwrap();
    }
    decoded
}

pub(super) fn release_statement() -> AtomicPaymentStatementV4 {
    let digest = |value: &str| decode_digest_canonical(&decode_hex_32(value)).unwrap();
    AtomicPaymentStatementV4 {
        pool: decode_hex_32("2605b65c88655a479c2bd504ae207556acd0d42c49a8eeaed8cdbca5a256ca70"),
        sequence: 0,
        spend: SpendPublic {
            anchor: digest("90bc3005a8029b06072f386dc6b1ee4e9b4ba513b126d033a96ecc49829cab5a"),
            nullifier: digest("890266278df8f3073cab562c6c7d89471363c46841748a1ef3b0432acd0afd5f"),
            output_commitment: digest(
                "69517012bd98fe78bef9b076069520614ef27f2fc7a0854f72e65055a2edc319",
            ),
            asset_id: decode_asset_id_canonical(17).unwrap(),
            fee: 1,
        },
        output_anchor: digest("9f5b8c2dc991e401f3538941af35fd29e00aa319edca8013c7260c61c2e7486e"),
        deployment_domain: decode_hex_32(
            "ba43feb01d7d7f5ee3f57a6481b202066c83c6c3e76020a619c1611abbd08c8f",
        ),
    }
}

fn coordinate_mask(coordinate: usize, scale: M31) -> M31BlockMask {
    let mut mask = M31BlockMask {
        p: [M31::ZERO; V5_MASK_M],
        q: [M31::ZERO; V5_MASK_M],
    };
    if coordinate < V5_MASK_M {
        mask.p[coordinate] = scale;
    } else {
        mask.q[coordinate - V5_MASK_M] = scale;
    }
    mask
}

fn add_coordinate(mask: &mut M31BlockMask, coordinate: usize, value: M31) {
    if coordinate < V5_MASK_M {
        mask.p[coordinate] = mask.p[coordinate].add(value);
    } else {
        let coordinate = coordinate - V5_MASK_M;
        mask.q[coordinate] = mask.q[coordinate].add(value);
    }
}

fn inactive_sum(message: &[M31]) -> M31 {
    let masks = atomic_state_only_copy_inactive_row_masks_v3();
    message
        .iter()
        .copied()
        .enumerate()
        .filter(|(row, _)| masks[row >> 4] & (1 << (row & 15)) != 0)
        .fold(M31::ZERO, |sum, (_, value)| sum.add(value))
}

/// A basis of the 95-dimensional slice where component A preserves the
/// current copy-inactive zero claim.  Coordinates are the ordinary p/q
/// coefficients; `mask_m31_column` performs the real natural-basis change.
pub(super) fn inactive_kernel_messages() -> Vec<Vec<M31>> {
    let zero = [M31::ZERO; V5_TRACE_ROWS];
    let relation = core::array::from_fn::<_, V5_MASK_B, _>(|coordinate| {
        let message = mask_m31_column(&zero, &coordinate_mask(coordinate, M31::ONE)).unwrap();
        inactive_sum(&message)
    });
    let pivot = relation
        .iter()
        .position(|value| !value.is_zero())
        .expect("component A meets the nonzero inactive functional");
    let pivot_inverse = relation[pivot].inv();

    (0..V5_MASK_B)
        .filter(|&coordinate| coordinate != pivot)
        .map(|coordinate| {
            let mut mask = coordinate_mask(coordinate, M31::ONE);
            add_coordinate(
                &mut mask,
                pivot,
                relation[coordinate].neg().mul(pivot_inverse),
            );
            let message = mask_m31_column(&zero, &mask).unwrap();
            assert_eq!(inactive_sum(&message), M31::ZERO);
            message
        })
        .collect()
}

pub(super) fn qm31_coordinates(value: QM31) -> [M31; 4] {
    [value.c0.a, value.c0.b, value.c1.a, value.c1.b]
}

pub(super) fn m31_rank(matrix: &[Vec<M31>]) -> usize {
    let rows = matrix.len();
    let columns = matrix.first().map_or(0, Vec::len);
    let mut work = matrix.to_vec();
    let mut rank = 0;
    for column in 0..columns {
        let Some(pivot) = (rank..rows).find(|&row| !work[row][column].is_zero()) else {
            continue;
        };
        work.swap(rank, pivot);
        let pivot_row = work[rank].clone();
        let inverse = pivot_row[column].inv();
        for (row, values) in work.iter_mut().enumerate() {
            if row == rank {
                continue;
            }
            let scale = values[column].mul(inverse);
            if scale.is_zero() {
                continue;
            }
            for (value, pivot_value) in values[column..].iter_mut().zip(&pivot_row[column..]) {
                *value = value.sub(scale.mul(*pivot_value));
            }
        }
        rank += 1;
        if rank == rows {
            break;
        }
    }
    rank
}

#[test]
fn boolean_mle_schedule_is_a_rank_zero_counterexample_for_reserved_support() {
    let basis = inactive_kernel_messages();
    let z = [QM31::ZERO; 10];
    let points = [z, binary_successor_point(&z), xor12_point(&z)];
    let mut observations = vec![vec![M31::ZERO; basis.len()]; 12];
    for (column, message) in basis.iter().enumerate() {
        let mut output = 0;
        for point in &points {
            for coordinate in qm31_coordinates(multilinear_eval(message, point)) {
                observations[output][column] = coordinate;
                output += 1;
            }
        }
        assert_eq!(output, 12);
    }

    // All three Boolean points select active message rows.  A mask confined to
    // rows 896..991 is therefore zero at every one of them.  Boolean challenges
    // are rare under Fiat--Shamir, but they are not excluded by the wire, so the
    // twelve-row MLE rank cannot be a deterministic consequence of fibre
    // injectivity.
    assert!(observations
        .iter()
        .all(|row| row.iter().all(|value| value.is_zero())));
    assert_eq!(m31_rank(&observations), 0);
}

//! Host-only prototype for binding the v5 component-B sumcheck mask.
//!
//! The prototype embeds the 271 independent coordinates of
//! [`V5SumcheckMask`] and exactly 752 independent QM31 pads into one 1024-row
//! lane. The first row selected by the current copy-inactive functional is a
//! pivot. Every other row carries one input coordinate, in row order, and the
//! pivot is fixed so that the copy-inactive functional is zero. This is a
//! linear bijection from 1023 QM31 coordinates onto that functional's kernel.
//!
//! [`v5_b_terminal_covector`] returns the public, dense row-basis covector for
//! evaluating the chained mask at a ten-coordinate point. Its pivot and pad
//! entries are zero, so the terminal value depends only on the 271 mask
//! coordinates.
//!
//! # Deliberate boundary
//!
//! Nothing here is wired into a Merkle tree, transcript, verifier, proof
//! envelope, or the v4 prover. The hiding rank of the complete committed view
//! is still open. So is a kernel-checked correspondence between this Rust row
//! encoding and `AspisFormal/SumcheckMasking.lean`; the Lean file currently
//! proves the chained-mask algebra, not this 1024-row representation.

use aspis_core::field::QM31;
use aspis_core::state_only_sumcheck::{STATE_ONLY_SUMCHECK_DEGREE, STATE_ONLY_SUMCHECK_ROUNDS};
use aspis_statement::state_only_copy_inactive_row_masks_v4;

use crate::v5_sumcheck_mask::{V5SumcheckMask, V5_SUMCHECK_MASK_RANDOMNESS};

/// Number of QM31 rows in the provisional component-B lane.
pub const V5_B_LANE_ROWS: usize = 1024;
/// Chained-mask coordinates placed in the lane.
pub const V5_B_MASK_COORDINATES: usize = V5_SUMCHECK_MASK_RANDOMNESS;
/// Independent padding coordinates placed in the lane.
pub const V5_B_PAD_COORDINATES: usize = 752;
/// Dimension of the kernel of one nonzero functional on 1024 rows.
pub const V5_B_KERNEL_DIMENSION: usize = V5_B_LANE_ROWS - 1;

const _: () = assert!(V5_B_MASK_COORDINATES == 271);
const _: () = assert!(V5_B_PAD_COORDINATES == 752);
const _: () = assert!(V5_B_MASK_COORDINATES + V5_B_PAD_COORDINATES == V5_B_KERNEL_DIMENSION);
const _: () = assert!(STATE_ONLY_SUMCHECK_ROUNDS == 10);
const _: () = assert!(STATE_ONLY_SUMCHECK_DEGREE == 27);

/// One component-B lane in the current copy-inactive functional's kernel.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct V5BCommitmentLane {
    values: [QM31; V5_B_LANE_ROWS],
}

impl V5BCommitmentLane {
    /// Encode a chained mask and exactly 752 independent pad coordinates.
    pub fn encode(mask: &V5SumcheckMask, pads: &[QM31; V5_B_PAD_COORDINATES]) -> Self {
        let pivot = v5_b_pivot_row();
        let mask_coordinates = mask.commitment_coordinates();
        let mut values = [QM31::ZERO; V5_B_LANE_ROWS];

        for (coordinate, value) in mask_coordinates.into_iter().enumerate() {
            values[free_coordinate_row(coordinate, pivot)] = value;
        }
        for (coordinate, value) in pads.iter().copied().enumerate() {
            let free_coordinate = V5_B_MASK_COORDINATES + coordinate;
            values[free_coordinate_row(free_coordinate, pivot)] = value;
        }

        values[pivot] = v5_b_copy_inactive_functional(&values).neg();
        debug_assert_eq!(v5_b_copy_inactive_functional(&values), QM31::ZERO);
        Self { values }
    }

    /// Borrow the complete 1024-row lane.
    pub const fn values(&self) -> &[QM31; V5_B_LANE_ROWS] {
        &self.values
    }

    /// Consume the wrapper and return the complete 1024-row lane.
    pub fn into_values(self) -> [QM31; V5_B_LANE_ROWS] {
        self.values
    }
}

/// The first row selected by the current copy-inactive functional.
pub fn v5_b_pivot_row() -> usize {
    let masks = state_only_copy_inactive_row_masks_v4();
    (0..V5_B_LANE_ROWS)
        .find(|&row| copy_inactive_row(&masks, row))
        .expect("the pinned copy-inactive functional is nonzero")
}

/// Apply the current copy-inactive functional to a 1024-row lane.
pub fn v5_b_copy_inactive_functional(values: &[QM31; V5_B_LANE_ROWS]) -> QM31 {
    let masks = state_only_copy_inactive_row_masks_v4();
    values
        .iter()
        .copied()
        .enumerate()
        .filter(|(row, _)| copy_inactive_row(&masks, *row))
        .fold(QM31::ZERO, |sum, (_, value)| sum.add(value))
}

/// Public row-basis covector for the chained mask's terminal evaluation.
///
/// If round `i` has free coefficients `a[i,1]..a[i,27]`, its recurrence is
///
/// ```text
/// s[i+1] = s[i]/2 + sum_k a[i,k] * (z[i]^k - 1/2).
/// ```
///
/// Unrolling the ten rounds gives the weights placed here. Pad and pivot rows
/// have weight zero.
pub fn v5_b_terminal_covector(
    point: &[QM31; STATE_ONLY_SUMCHECK_ROUNDS],
) -> [QM31; V5_B_LANE_ROWS] {
    let pivot = v5_b_pivot_row();
    let half = QM31::ONE.half();
    let mut coordinate_weights = [QM31::ZERO; V5_B_MASK_COORDINATES];
    coordinate_weights[0] = half.pow(STATE_ONLY_SUMCHECK_ROUNDS as u64);

    for (round, challenge) in point.iter().copied().enumerate() {
        let later_round_scale = half.pow((STATE_ONLY_SUMCHECK_ROUNDS - 1 - round) as u64);
        let mut challenge_power = challenge;
        for degree in 1..=STATE_ONLY_SUMCHECK_DEGREE {
            let coordinate = 1 + round * STATE_ONLY_SUMCHECK_DEGREE + degree - 1;
            coordinate_weights[coordinate] = later_round_scale.mul(challenge_power.sub(half));
            challenge_power = challenge_power.mul(challenge);
        }
    }

    let mut covector = [QM31::ZERO; V5_B_LANE_ROWS];
    for (coordinate, weight) in coordinate_weights.into_iter().enumerate() {
        covector[free_coordinate_row(coordinate, pivot)] = weight;
    }
    covector
}

/// Dense QM31 inner product used by the host-only prototype.
pub fn v5_b_dense_dot(left: &[QM31; V5_B_LANE_ROWS], right: &[QM31; V5_B_LANE_ROWS]) -> QM31 {
    left.iter()
        .copied()
        .zip(right.iter().copied())
        .fold(QM31::ZERO, |sum, (left, right)| sum.add(left.mul(right)))
}

fn copy_inactive_row(masks: &[u16; 64], row: usize) -> bool {
    masks[row >> 4] & (1 << (row & 15)) != 0
}

fn free_coordinate_row(coordinate: usize, pivot: usize) -> usize {
    debug_assert!(coordinate < V5_B_KERNEL_DIMENSION);
    if coordinate < pivot {
        coordinate
    } else {
        coordinate + 1
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use aspis_core::field::{CM31, M31};

    use crate::v5_mask::Qm31WordSource;

    struct XorShift(u64);

    impl Qm31WordSource for XorShift {
        fn next_word(&mut self) -> u32 {
            let mut x = self.0;
            x ^= x << 13;
            x ^= x >> 7;
            x ^= x << 17;
            self.0 = x;
            (x >> 21) as u32
        }
    }

    fn sample(seed: u64) -> V5SumcheckMask {
        V5SumcheckMask::sample(&mut XorShift(seed)).expect("test source remains canonical")
    }

    fn q(seed: u32) -> QM31 {
        QM31 {
            c0: CM31::new(M31(seed * 1_003 + 1), M31(seed * 1_009 + 3)),
            c1: CM31::new(M31(seed * 1_021 + 5), M31(seed * 1_031 + 7)),
        }
    }

    fn pads(seed: u32) -> [QM31; V5_B_PAD_COORDINATES] {
        core::array::from_fn(|coordinate| q(seed + coordinate as u32))
    }

    #[test]
    fn encoded_lane_lies_in_current_copy_inactive_kernel() {
        let lane = V5BCommitmentLane::encode(&sample(0xa1c5_5eed_91b7_3201), &pads(20_000));
        assert_eq!(v5_b_copy_inactive_functional(lane.values()), QM31::ZERO);

        let masks = state_only_copy_inactive_row_masks_v4();
        assert!(copy_inactive_row(&masks, v5_b_pivot_row()));
    }

    #[test]
    fn dense_terminal_covector_matches_chained_mask_evaluation() {
        let mask = sample(0x61d0_8c35_27a9_44ef);
        let point = core::array::from_fn(|coordinate| q(100 + coordinate as u32));
        let lane = V5BCommitmentLane::encode(&mask, &pads(30_000));
        let covector = v5_b_terminal_covector(&point);

        assert_eq!(
            v5_b_dense_dot(lane.values(), &covector),
            mask.evaluate(&point)
        );
    }

    #[test]
    fn pad_changes_do_not_change_the_terminal_functional() {
        let mask = sample(0x8b23_d4f0_5ea1_7719);
        let point = core::array::from_fn(|coordinate| q(400 + coordinate as u32));
        let first = V5BCommitmentLane::encode(&mask, &pads(40_000));
        let second = V5BCommitmentLane::encode(&mask, &pads(50_000));
        let covector = v5_b_terminal_covector(&point);
        let pivot = v5_b_pivot_row();

        assert_ne!(first, second);
        assert_eq!(covector[pivot], QM31::ZERO);
        for coordinate in 0..V5_B_PAD_COORDINATES {
            let free_coordinate = V5_B_MASK_COORDINATES + coordinate;
            assert_eq!(
                covector[free_coordinate_row(free_coordinate, pivot)],
                QM31::ZERO
            );
        }
        assert_eq!(
            v5_b_dense_dot(first.values(), &covector),
            mask.evaluate(&point)
        );
        assert_eq!(
            v5_b_dense_dot(second.values(), &covector),
            mask.evaluate(&point)
        );
    }

    #[test]
    fn dimensions_constants_and_coordinate_order_are_exact() {
        assert_eq!(V5_B_LANE_ROWS, 1024);
        assert_eq!(V5_B_MASK_COORDINATES, 271);
        assert_eq!(V5_B_PAD_COORDINATES, 752);
        assert_eq!(V5_B_KERNEL_DIMENSION, 1023);

        let mask = sample(0x09f3_c4a2_d8e1_675b);
        let pad_coordinates = pads(60_000);
        let lane = V5BCommitmentLane::encode(&mask, &pad_coordinates);
        let mask_coordinates = mask.commitment_coordinates();
        let pivot = v5_b_pivot_row();
        let mut seen_rows = [false; V5_B_LANE_ROWS];

        assert_eq!(mask_coordinates[0], mask.initial_claim());
        for round in 0..STATE_ONLY_SUMCHECK_ROUNDS {
            let polynomial = mask.zero_boundary_round(round).unwrap();
            for degree in 1..=STATE_ONLY_SUMCHECK_DEGREE {
                let coordinate = 1 + round * STATE_ONLY_SUMCHECK_DEGREE + degree - 1;
                assert_eq!(mask_coordinates[coordinate], polynomial[degree]);
            }
        }

        for (coordinate, expected) in mask_coordinates.into_iter().enumerate() {
            let row = free_coordinate_row(coordinate, pivot);
            assert!(!seen_rows[row]);
            seen_rows[row] = true;
            assert_eq!(lane.values()[row], expected);
        }
        for (coordinate, expected) in pad_coordinates.into_iter().enumerate() {
            let free_coordinate = V5_B_MASK_COORDINATES + coordinate;
            let row = free_coordinate_row(free_coordinate, pivot);
            assert!(!seen_rows[row]);
            seen_rows[row] = true;
            assert_eq!(lane.values()[row], expected);
        }

        assert!(!seen_rows[pivot]);
        assert_eq!(seen_rows.into_iter().filter(|seen| *seen).count(), 1023);
    }
}

