const PAD_START: usize = 224;
const PAD_COUNT: usize = 255;
const STATE_DIMENSION: usize = 1 + 10 * ROUND_FREE_COEFFICIENTS;
const PHYSICAL_FREE_DIMENSION: usize = STATE_DIMENSION + PAD_COUNT;
const AFFINE_FREE_DIMENSION: usize = PHYSICAL_FREE_DIMENSION + 1;

const _: () = assert!(STATE_DIMENSION == 271);
const _: () = assert!(PHYSICAL_FREE_DIMENSION == 526);
const _: () = assert!(AFFINE_FREE_DIMENSION == 527);
const _: () = assert!(PAD_START + PAD_COUNT == 479);

fn block_row(round: usize, offset: usize) -> usize {
    ROUND_BLOCKS[round] * ROUND_BLOCK_ROWS + offset
}

fn atomic_inactive(row: usize) -> bool {
    let masks = atomic_state_only_copy_inactive_row_masks_v3();
    masks[row >> 4] & (1 << (row & 15)) != 0
}

/// The public terminal functional for the candidate row layout.
///
/// Round `i` occupies one 32-row aligned block. Only the degree-27
/// coefficients at offsets 0..27 receive weights. Offsets 28..31 are zero in
/// both the component-B message and this functional, so soundness does not
/// assume that unauthenticated slack is zero. The same 28 weights act on the
/// corresponding C1 semantic-lane rows after relation batching.
fn structured_terminal_covector(point: &[QM31; 10]) -> [QM31; V5_TRACE_ROWS] {
    let half = QM31::ONE.half();
    let mut covector = [QM31::ZERO; V5_TRACE_ROWS];
    covector[INITIAL_CLAIM_ROW] = half.pow(10);
    for (round, challenge) in point.iter().copied().enumerate() {
        let scale = half.pow((9 - round) as u64);
        let mut power = QM31::ONE;
        for offset in 0..ROUND_COEFFICIENTS {
            covector[block_row(round, offset)] = scale.mul(power);
            power = power.mul(challenge);
        }
    }
    covector
}

fn frozen_schedule() -> ([QM31; 10], Vec<usize>) {
    let statement = release_statement();
    let statement_digest = atomic_payment_statement_digest_v4(&statement, HOST_HASH).unwrap();
    let (prefix, suffix) = StateOnlySpendPrefix::parse_from_proof(RELEASE_PROOF).unwrap();
    assert!(!suffix.is_empty());
    let schedule = run_atomic_state_only_spend_transcript_schedule_host_v3(
        HOST_HASH,
        &prefix,
        &statement_digest,
    )
    .unwrap();
    assert_eq!(
        schedule.query_count,
        usize::from(STATE_ONLY_SPEND_QUERY_COUNT)
    );

    let encoder = v5_encoder();
    let indices = derive_circle_line_query_indices_for_count(
        &schedule.queries[..schedule.query_count],
        encoder.codeword_len() / V5_FIBRE_SIZE,
    )
    .unwrap();
    let positions = indices
        .layer0
        .iter()
        .flat_map(|query| {
            (0..V5_FIBRE_SIZE).map(move |slot| *query as usize * V5_FIBRE_SIZE + slot)
        })
        .collect::<Vec<_>>();
    assert_eq!(positions.len(), 72);
    (schedule.prefix.z, positions)
}

fn c1_view_matrix(point: &[QM31; 10], positions: &[usize]) -> Vec<Vec<M31>> {
    let basis = inactive_kernel_messages();
    assert_eq!(basis.len(), 95);
    let encoder = v5_encoder();
    let mle_points = [*point, binary_successor_point(point), xor12_point(point)];
    let dense = structured_terminal_covector(point);
    let mut observations = vec![vec![M31::ZERO; basis.len()]; 88];

    for (column, message) in basis.iter().enumerate() {
        let mut output = 0;
        for &position in positions {
            let value = (896..=991).fold(M31::ZERO, |sum, row| {
                sum.add(
                    message[row].mul(
                        encoder
                            .encode_c1_basis_value(row, position)
                            .expect("real encoder basis position"),
                    ),
                )
            });
            observations[output][column] = value;
            output += 1;
        }
        for mle_point in &mle_points {
            for coordinate in qm31_coordinates(multilinear_eval(message, mle_point)) {
                observations[output][column] = coordinate;
                output += 1;
            }
        }
        let dense_value = message
            .iter()
            .copied()
            .zip(dense.iter().copied())
            .fold(QM31::ZERO, |sum, (value, weight)| {
                sum.add(weight.mul_m31(value))
            });
        for coordinate in qm31_coordinates(dense_value) {
            observations[output][column] = coordinate;
            output += 1;
        }
        assert_eq!(output, 88);
    }
    observations
}

fn inactive_sum(values: &[QM31; V5_TRACE_ROWS]) -> QM31 {
    values
        .iter()
        .copied()
        .enumerate()
        .filter(|(row, _)| atomic_inactive(*row))
        .fold(QM31::ZERO, |sum, (_, value)| sum.add(value))
}

/// Linear test fixture for the component-B physical message map.
fn encode_b_message(
    state: &[QM31; STATE_DIMENSION],
    pads: &[QM31; PAD_COUNT],
    pivot_pad: QM31,
) -> [QM31; V5_TRACE_ROWS] {
    let mut values = [QM31::ZERO; V5_TRACE_ROWS];
    let half = QM31::ONE.half();
    values[INITIAL_CLAIM_ROW] = state[0];

    for round in 0..10 {
        let state_start = 1 + round * ROUND_FREE_COEFFICIENTS;
        let mut tail_sum = QM31::ZERO;
        for offset in 1..ROUND_COEFFICIENTS {
            let value = state[state_start + offset - 1];
            values[block_row(round, offset)] = value;
            tail_sum = tail_sum.add(value);
        }
        values[block_row(round, 0)] = tail_sum.neg().mul(half);
    }

    for (offset, pad) in pads.iter().copied().enumerate() {
        values[PAD_START + offset] = pad;
    }
    values[INACTIVE_PIVOT_ROW] = pivot_pad.add(inactive_sum(&values).neg());
    assert_eq!(inactive_sum(&values), pivot_pad);
    values
}

fn encode_pad_basis(pad: usize) -> [QM31; V5_TRACE_ROWS] {
    let mut values = [QM31::ZERO; V5_TRACE_ROWS];
    let row = PAD_START + pad;
    values[row] = QM31::ONE;
    if atomic_inactive(row) {
        values[INACTIVE_PIVOT_ROW] = QM31::ONE.neg();
    }
    assert_eq!(inactive_sum(&values), QM31::ZERO);
    values
}

fn terminal_from_state(state: &[QM31; STATE_DIMENSION], point: &[QM31; 10]) -> QM31 {
    let half = QM31::ONE.half();
    let mut terminal = half.pow(10).mul(state[0]);
    for (round, challenge) in point.iter().copied().enumerate() {
        let scale = half.pow((9 - round) as u64);
        let state_start = 1 + round * ROUND_FREE_COEFFICIENTS;
        let mut tail_sum = QM31::ZERO;
        for offset in 1..ROUND_COEFFICIENTS {
            tail_sum = tail_sum.add(state[state_start + offset - 1]);
        }
        let mut polynomial = tail_sum.neg().mul(half);
        let mut power = challenge;
        for offset in 1..ROUND_COEFFICIENTS {
            polynomial = polynomial.add(state[state_start + offset - 1].mul(power));
            power = power.mul(challenge);
        }
        terminal = terminal.add(scale.mul(polynomial));
    }
    terminal
}

fn q(seed: u32) -> QM31 {
    use aspis_core::field::CM31;
    QM31 {
        c0: CM31::new(M31(seed * 1_003 + 1), M31(seed * 1_009 + 3)),
        c1: CM31::new(M31(seed * 1_021 + 5), M31(seed * 1_031 + 7)),
    }
}

#[test]
fn structured_claim_reaches_rank_88_on_the_frozen_schedule() {
    let (point, positions) = frozen_schedule();
    let observations = c1_view_matrix(&point, &positions);
    assert_eq!(m31_rank(&observations[..72]), 72);
    assert_eq!(m31_rank(&observations[..84]), 84);
    assert_eq!(m31_rank(&observations), 88);

    let dense = structured_terminal_covector(&point);
    assert!(dense[..224].iter().any(|value| !value.is_zero()));
    assert!(dense[224..896].iter().all(|value| value.is_zero()));
    for round in 7..10 {
        assert!((0..ROUND_COEFFICIENTS).all(|offset| !dense[block_row(round, offset)].is_zero()));
        assert!((ROUND_COEFFICIENTS..ROUND_BLOCK_ROWS)
            .all(|offset| dense[block_row(round, offset)].is_zero()));
    }
    assert!(!dense[INITIAL_CLAIM_ROW].is_zero());
    assert!(dense[993..].iter().all(|value| value.is_zero()));
}

#[test]
fn boolean_challenge_is_a_counterexample_to_universal_rank_88() {
    let (_, positions) = frozen_schedule();
    let point = [QM31::ZERO; 10];
    let observations = c1_view_matrix(&point, &positions);
    assert_eq!(m31_rank(&observations[..72]), 72);
    assert_eq!(m31_rank(&observations[..84]), 72);
    assert_eq!(m31_rank(&observations), 73);

    // At a base-field Boolean point the four M31 coordinate rows of the dense
    // QM31 claim collapse to at most one row. Hence the rank-88 result above is
    // schedule-specific and cannot be promoted to deterministic availability.
    assert!(observations[85..88]
        .iter()
        .all(|row| row.iter().all(|value| value.is_zero())));
}

#[test]
fn structured_b_physical_map_has_271_state_and_255_pad_dimensions() {
    assert_eq!(ROUND_BLOCKS, [0, 1, 2, 3, 4, 5, 6, 28, 29, 30]);
    assert!(atomic_inactive(INACTIVE_PIVOT_ROW));
    assert!((896..=991).all(atomic_inactive));

    let state = core::array::from_fn::<_, STATE_DIMENSION, _>(|index| q(index as u32 + 1));
    let pads = core::array::from_fn::<_, PAD_COUNT, _>(|index| q(index as u32 + 10_000));
    let pivot_pad = q(19_999);
    let message = encode_b_message(&state, &pads, pivot_pad);

    assert_eq!(message[INITIAL_CLAIM_ROW], state[0]);
    for round in 0..10 {
        let state_start = 1 + round * ROUND_FREE_COEFFICIENTS;
        for offset in 1..ROUND_COEFFICIENTS {
            assert_eq!(
                message[block_row(round, offset)],
                state[state_start + offset - 1]
            );
        }
        assert!((ROUND_COEFFICIENTS..ROUND_BLOCK_ROWS)
            .all(|offset| message[block_row(round, offset)].is_zero()));
    }
    for (offset, expected) in pads.iter().copied().enumerate() {
        assert_eq!(message[PAD_START + offset], expected);
    }
    assert_eq!(inactive_sum(&message), pivot_pad);

    let point = core::array::from_fn(|index| q(index as u32 + 20_000));
    let covector = structured_terminal_covector(&point);
    let opening = message
        .iter()
        .copied()
        .zip(covector)
        .fold(QM31::ZERO, |sum, (value, weight)| {
            sum.add(value.mul(weight))
        });
    assert_eq!(opening, terminal_from_state(&state, &point));

    // The first 526 independent inputs occur unchanged at distinct coordinate
    // rows: s0, every c1..c27, and every pad. The ten c0 values are dependent.
    // The caller-owned pivot pad is the 527th affine input and is recovered by
    // the inactive functional even though row 993 also cancels the other
    // inactive rows. This certifies the physical map only.
    assert_eq!(STATE_DIMENSION, 271);
    assert_eq!(PAD_COUNT, 255);
    assert_eq!(PHYSICAL_FREE_DIMENSION, 526);
    assert_eq!(AFFINE_FREE_DIMENSION, 527);
}

#[test]
fn frozen_pad_map_covers_72_raw_and_three_mle_values_but_not_dense() {
    let (point, positions) = frozen_schedule();
    let mle_points = [point, binary_successor_point(&point), xor12_point(&point)];
    let dense = structured_terminal_covector(&point);
    let encoder = v5_encoder();
    let mut observations = vec![vec![QM31::ZERO; PAD_COUNT]; 76];

    // Pin the sparse basis calculation below to the actual C2 encoder, rather
    // than relying only on the fact that C1 and C2 use the same M31 twiddles.
    let first_pad_message = encode_pad_basis(0);
    let first_pad_codeword = encoder.encode_c2_message(&first_pad_message).unwrap();
    for &position in &positions {
        let sparse = first_pad_message
            .iter()
            .copied()
            .enumerate()
            .filter(|(_, value)| !value.is_zero())
            .fold(QM31::ZERO, |sum, (row, value)| {
                sum.add(
                    value.mul_m31(
                        encoder
                            .encode_c1_basis_value(row, position)
                            .expect("real encoder basis position"),
                    ),
                )
            });
        assert_eq!(sparse, first_pad_codeword[position]);
    }

    for pad in 0..PAD_COUNT {
        let message = encode_pad_basis(pad);
        let mut output = 0;
        for &position in &positions {
            observations[output][pad] = message
                .iter()
                .copied()
                .enumerate()
                .filter(|(_, value)| !value.is_zero())
                .fold(QM31::ZERO, |sum, (row, value)| {
                    sum.add(
                        value.mul_m31(
                            encoder
                                .encode_c1_basis_value(row, position)
                                .expect("C1 and C2 share the row-basis transform"),
                        ),
                    )
                });
            output += 1;
        }
        for mle_point in &mle_points {
            observations[output][pad] = multilinear_eval_extension(&message, mle_point);
            output += 1;
        }
        observations[output][pad] = message
            .iter()
            .copied()
            .zip(dense)
            .fold(QM31::ZERO, |sum, (value, weight)| {
                sum.add(value.mul(weight))
            });
        output += 1;
        assert_eq!(output, 76);
    }

    assert_eq!(qm31_rank(&observations[..72]), 72);
    assert_eq!(qm31_rank(&observations[..75]), 75);
    assert!(observations[75].iter().all(|value| value.is_zero()));
    assert_eq!(qm31_rank(&observations), 75);
}

/// Re-run Component A's complete 88-coordinate rank check on the exact
/// frozen-v5 schedule used by the Component-C E artifact.  This keeps the
/// current structured terminal covector separate from the rejected older
/// dense-covector probe in `v5_a_full_view_rank`.
#[test]
#[ignore = "offline diagnostic; generate the current salted+p Emat artifact first"]
fn current_v5_emat_component_a_view_has_rank_88() {
    use std::path::Path;

    use super::component_c::v5_c_pivot_row;
    use super::component_c_emat::{
        validate_component_c_emat_artifact, V5ComponentCEmat, V5_C_EMAT_COLUMNS,
        V5_C_EMAT_LAYER_ZERO_ROWS, V5_C_EMAT_ROWS,
    };

    let artifact_path = Path::new(env!("CARGO_MANIFEST_DIR")).join(CURRENT_V5_EMAT_ARTIFACT);
    let artifact = std::fs::read(&artifact_path)
        .unwrap_or_else(|error| panic!("read {}: {error}", artifact_path.display()));
    let view = validate_component_c_emat_artifact(&artifact).expect("canonical current E artifact");
    let entries = view
        .matrix_bytes
        .chunks_exact(16)
        .map(|bytes| QM31::from_le_bytes(bytes).expect("canonical E entry"))
        .collect::<Vec<_>>();
    let emat = V5ComponentCEmat::from_entries(entries).expect("76x1023 E matrix");

    let basis = inactive_kernel_messages();
    assert_eq!(basis.len(), 95);
    let pivot = v5_c_pivot_row();
    let mut observations = vec![vec![M31::ZERO; basis.len()]; 88];
    for (column, message) in basis.iter().enumerate() {
        let free: [QM31; V5_C_EMAT_COLUMNS] = core::array::from_fn(|coordinate| {
            let row = if coordinate < pivot {
                coordinate
            } else {
                coordinate + 1
            };
            QM31::from_cm31(CM31::from_m31(message[row]))
        });
        let output = emat.mul_vec(&free);

        for row in 0..V5_C_EMAT_LAYER_ZERO_ROWS {
            let coordinates = qm31_coordinates(output[row]);
            assert_eq!(coordinates[1..], [M31::ZERO; 3]);
            observations[row][column] = coordinates[0];
        }
        let mut row = V5_C_EMAT_LAYER_ZERO_ROWS;
        for value in &output[V5_C_EMAT_LAYER_ZERO_ROWS..V5_C_EMAT_ROWS] {
            for coordinate in qm31_coordinates(*value) {
                observations[row][column] = coordinate;
                row += 1;
            }
        }
        assert_eq!(row, 88);
    }

    assert_eq!(m31_rank(&observations[..72]), 72);
    assert_eq!(m31_rank(&observations[..84]), 84);
    assert_eq!(m31_rank(&observations), 88);
}

/// The same exact frozen-v5 E artifact sees all 76 Component-B released
/// coordinates from the actual 271 state plus 255 pad directions.  Pads alone
/// cover 75 rows; the structured state supplies the remaining terminal row.
#[test]
#[ignore = "offline diagnostic; generate the current salted+p Emat artifact first"]
fn current_v5_emat_component_b_physical_view_has_rank_76() {
    use std::path::Path;

    use super::component_c::{v5_c_pivot_row, V5ComponentCLane};
    use super::component_c_emat::{
        validate_component_c_emat_artifact, V5ComponentCEmat, V5_C_EMAT_COLUMNS, V5_C_EMAT_ROWS,
    };

    let artifact_path = Path::new(env!("CARGO_MANIFEST_DIR")).join(CURRENT_V5_EMAT_ARTIFACT);
    let artifact = std::fs::read(&artifact_path)
        .unwrap_or_else(|error| panic!("read {}: {error}", artifact_path.display()));
    let view = validate_component_c_emat_artifact(&artifact).expect("canonical current E artifact");
    let entries = view
        .matrix_bytes
        .chunks_exact(16)
        .map(|bytes| QM31::from_le_bytes(bytes).expect("canonical E entry"))
        .collect::<Vec<_>>();
    let emat = V5ComponentCEmat::from_entries(entries).expect("76x1023 E matrix");
    let pivot = v5_c_pivot_row();

    let mut physical = Vec::with_capacity(PHYSICAL_FREE_DIMENSION);
    for coordinate in 0..STATE_DIMENSION {
        let mut state = [QM31::ZERO; STATE_DIMENSION];
        state[coordinate] = QM31::ONE;
        physical.push(encode_b_message(
            &state,
            &[QM31::ZERO; PAD_COUNT],
            QM31::ZERO,
        ));
    }
    for coordinate in 0..PAD_COUNT {
        physical.push(encode_pad_basis(coordinate));
    }
    assert_eq!(physical.len(), PHYSICAL_FREE_DIMENSION);

    let mut observations = vec![vec![QM31::ZERO; physical.len()]; V5_C_EMAT_ROWS];
    for (column, message) in physical.iter().enumerate() {
        let free: [QM31; V5_C_EMAT_COLUMNS] = core::array::from_fn(|coordinate| {
            let row = if coordinate < pivot {
                coordinate
            } else {
                coordinate + 1
            };
            message[row]
        });
        assert_eq!(
            V5ComponentCLane::encode_free_coordinates(&free).values(),
            message
        );
        for (row, value) in emat.mul_vec(&free).into_iter().enumerate() {
            observations[row][column] = value;
        }
    }

    let pad_start = STATE_DIMENSION;
    let pad_only = observations
        .iter()
        .map(|row| row[pad_start..].to_vec())
        .collect::<Vec<_>>();
    assert_eq!(qm31_rank(&pad_only), 75);
    assert_eq!(qm31_rank(&observations), 76);
}

/// Return `(old released, old joint, affine released, affine joint,
/// state block, pads+p restricted, independent triangular)` ranks for one
/// exact transcript schedule. This is shared with the real-host fixture so the
/// salted+p transcript, not only the older frozen release schedule, is checked
/// against the same 527 sampler directions.
pub(super) fn component_b_affine_joint_ranks(
    point: &[QM31; 10],
    positions: &[usize],
) -> [usize; 7] {
    assert_eq!(positions.len(), 72);
    let mle_points = [*point, binary_successor_point(point), xor12_point(point)];
    let terminal = structured_terminal_covector(point);
    let encoder = v5_encoder();

    let mut directions = Vec::with_capacity(AFFINE_FREE_DIMENSION);
    for coordinate in 0..STATE_DIMENSION {
        let mut state = [QM31::ZERO; STATE_DIMENSION];
        state[coordinate] = QM31::ONE;
        directions.push(encode_b_message(
            &state,
            &[QM31::ZERO; PAD_COUNT],
            QM31::ZERO,
        ));
    }
    for coordinate in 0..PAD_COUNT {
        directions.push(encode_pad_basis(coordinate));
    }
    let mut pivot_direction = [QM31::ZERO; V5_TRACE_ROWS];
    pivot_direction[INACTIVE_PIVOT_ROW] = QM31::ONE;
    directions.push(pivot_direction);
    assert_eq!(directions.len(), AFFINE_FREE_DIMENSION);

    // Row zero is ell(B); rows 1..=76 are the supplied schedule's complete B view:
    // 72 q18 layer-zero positions, three MLE claims, and the structured
    // terminal claim.
    let mut joint = vec![vec![QM31::ZERO; directions.len()]; 77];
    for (column, message) in directions.iter().enumerate() {
        joint[0][column] = inactive_sum(message);
        let mut output = 1;
        for &position in positions {
            joint[output][column] = message
                .iter()
                .copied()
                .enumerate()
                .filter(|(_, value)| !value.is_zero())
                .fold(QM31::ZERO, |sum, (row, value)| {
                    sum.add(
                        value.mul_m31(
                            encoder
                                .encode_c1_basis_value(row, position)
                                .expect("C1 and C2 share the row-basis transform"),
                        ),
                    )
                });
            output += 1;
        }
        for mle_point in &mle_points {
            joint[output][column] = multilinear_eval_extension(message, mle_point);
            output += 1;
        }
        joint[output][column] = message
            .iter()
            .copied()
            .zip(terminal)
            .fold(QM31::ZERO, |sum, (value, weight)| {
                sum.add(value.mul(weight))
            });
        output += 1;
        assert_eq!(output, 77);
    }

    let old_joint = joint
        .iter()
        .map(|row| row[..PHYSICAL_FREE_DIMENSION].to_vec())
        .collect::<Vec<_>>();
    let old_released = old_joint[1..].to_vec();
    let full_released = joint[1..].to_vec();

    // The 271 pre-challenge sumcheck-mask coordinates are released in their
    // own block and occur literally at row 992 and offsets 1..27 of each
    // selected block. Once those are conditioned, only the 255 pads plus p
    // remain available to couple ell, 72 raw openings, and three MLE claims.
    // The structured terminal is omitted from that second target because it is
    // a deterministic functional of the already-fixed 271 state values.
    let mut state_block = vec![vec![QM31::ZERO; AFFINE_FREE_DIMENSION]; STATE_DIMENSION];
    for (column, message) in directions.iter().enumerate() {
        let mut row = 0;
        state_block[row][column] = message[INITIAL_CLAIM_ROW];
        row += 1;
        for round in 0..10 {
            for offset in 1..ROUND_COEFFICIENTS {
                state_block[row][column] = message[block_row(round, offset)];
                row += 1;
            }
        }
        assert_eq!(row, STATE_DIMENSION);
    }
    let state_left = state_block
        .iter()
        .map(|row| row[..STATE_DIMENSION].to_vec())
        .collect::<Vec<_>>();
    assert!(state_block
        .iter()
        .all(|row| row[STATE_DIMENSION..].iter().all(|value| value.is_zero())));
    let pads_and_p = joint[..76]
        .iter()
        .map(|row| row[STATE_DIMENSION..].to_vec())
        .collect::<Vec<_>>();
    assert!(joint[76][STATE_DIMENSION..]
        .iter()
        .all(|value| value.is_zero()));

    let state_rank = qm31_rank(&state_left);
    let pads_and_p_rank = qm31_rank(&pads_and_p);
    let ranks = [
        qm31_rank(&old_released),
        qm31_rank(&old_joint),
        qm31_rank(&full_released),
        qm31_rank(&joint),
        state_rank,
        pads_and_p_rank,
        state_rank + pads_and_p_rank,
    ];
    assert_eq!(joint[0][PHYSICAL_FREE_DIMENSION], QM31::ONE);
    assert_eq!(joint[76][PHYSICAL_FREE_DIMENSION], QM31::ZERO);
    ranks
}

/// Algebraic regression on the older frozen release schedule. The distinct
/// real-host salted+p schedule is checked in `v5_real_host_proof`.
#[test]
fn frozen_release_component_b_affine_joint_map_has_rank_77() {
    let (point, positions) = frozen_schedule();
    assert_eq!(
        component_b_affine_joint_ranks(&point, &positions),
        [76, 76, 76, 77, 271, 76, 347]
    );
}

/// Hcopy's independent inactive-row, zero-sum padding alone can match every
/// one of the 76 released Hcopy coordinates on the current frozen-v5
/// schedule.  This isolates the linear padding from the witness-dependent,
/// post-A derivation of the unpadded Hcopy word.
#[test]
#[ignore = "offline diagnostic; generate the current salted+p Emat artifact first"]
fn current_v5_emat_hcopy_padding_view_has_rank_76() {
    use std::path::Path;

    use super::component_c::{v5_c_pivot_row, V5ComponentCLane};
    use super::component_c_emat::{
        validate_component_c_emat_artifact, V5ComponentCEmat, V5_C_EMAT_COLUMNS, V5_C_EMAT_ROWS,
    };

    let artifact_path = Path::new(env!("CARGO_MANIFEST_DIR")).join(CURRENT_V5_EMAT_ARTIFACT);
    let artifact = std::fs::read(&artifact_path)
        .unwrap_or_else(|error| panic!("read {}: {error}", artifact_path.display()));
    let view = validate_component_c_emat_artifact(&artifact).expect("canonical current E artifact");
    let entries = view
        .matrix_bytes
        .chunks_exact(16)
        .map(|bytes| QM31::from_le_bytes(bytes).expect("canonical E entry"))
        .collect::<Vec<_>>();
    let emat = V5ComponentCEmat::from_entries(entries).expect("76x1023 E matrix");

    let inactive_rows = (0..V5_TRACE_ROWS)
        .filter(|row| atomic_inactive(*row))
        .collect::<Vec<_>>();
    let dependent = inactive_rows[0];
    let padding = inactive_rows[1..]
        .iter()
        .copied()
        .map(|row| {
            let mut message = [QM31::ZERO; V5_TRACE_ROWS];
            message[row] = QM31::ONE;
            message[dependent] = QM31::ONE.neg();
            assert_eq!(inactive_sum(&message), QM31::ZERO);
            message
        })
        .collect::<Vec<_>>();
    assert_eq!(padding.len(), inactive_rows.len() - 1);

    let pivot = v5_c_pivot_row();
    let mut observations = vec![vec![QM31::ZERO; padding.len()]; V5_C_EMAT_ROWS];
    for (column, message) in padding.iter().enumerate() {
        let free: [QM31; V5_C_EMAT_COLUMNS] = core::array::from_fn(|coordinate| {
            let row = if coordinate < pivot {
                coordinate
            } else {
                coordinate + 1
            };
            message[row]
        });
        assert_eq!(
            V5ComponentCLane::encode_free_coordinates(&free).values(),
            message
        );
        for (row, value) in emat.mul_vec(&free).into_iter().enumerate() {
            observations[row][column] = value;
        }
    }

    assert_eq!(qm31_rank(&observations), 76);
}

crates/aspis-prover/src/v5_c_mask.rs:
//! V5 Component C: a full-kernel PCS masking lane.
//!
//! V5 uses the third already-budgeted QM31 helper lane. Its
//! message is uniform in the kernel of the exact atomic-v3 copy-inactive
//! functional: 1,023 coordinates are sampled independently and the first
//! selected row is derived so the functional is zero.  Consequently it does
//! not change the root claim enforced by the existing PCS relation.
//!
//! This module owns the row encoding and its four public linear claims. The
//! complete runtime path and Rust-to-Lean correspondence are joined in the V5
//! release proofs.

use aspis_core::field::QM31;
use aspis_statement::atomic_state_only_terminal::atomic_state_only_copy_inactive_row_masks_v3;
use aspis_statement::{binary_successor_point, xor12_point};

use super::{sample_qm31, MaskSampleExhausted, Qm31WordSource};

pub const V5_C_ROWS: usize = 1024;
pub const V5_C_FREE_COORDINATES: usize = V5_C_ROWS - 1;
pub const V5_C_POINT_CLAIMS: usize = 3;
pub const V5_C_TOTAL_CLAIMS: usize = 4;

const _: () = assert!(V5_C_FREE_COORDINATES == 1023);

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct V5ComponentCLane {
    values: [QM31; V5_C_ROWS],
}

enum V5CEncodeCorrespondence {
    MissingPivot,
    Encoded([QM31; V5_C_ROWS], [u16; 64]),
}

enum V5CDecodeCorrespondence {
    MissingPivot,
    Decoded([QM31; V5_C_FREE_COORDINATES]),
}

impl V5ComponentCLane {
    /// Sample the 1,023 free coordinates in row order and derive the pivot.
    pub fn sample<S: Qm31WordSource>(source: &mut S) -> Result<Self, MaskSampleExhausted> {
        let mut free = [QM31::ZERO; V5_C_FREE_COORDINATES];
        for value in &mut free {
            *value = sample_qm31(source)?;
        }
        Ok(Self::encode_free_coordinates(&free))
    }

    /// Linear bijection from `K^1023` to the kernel of the inactive
    /// functional.  The pivot coefficient is one, so no inversion is needed.
    pub fn encode_free_coordinates(free: &[QM31; V5_C_FREE_COORDINATES]) -> Self {
        let (values, masks) = match v5_c_encode_free_coordinates_checked(free) {
            V5CEncodeCorrespondence::Encoded(values, masks) => (values, masks),
            V5CEncodeCorrespondence::MissingPivot => {
                panic!("atomic-v3 inactive functional is nonzero")
            }
        };
        debug_assert_eq!(
            v5_c_inactive_functional_with_masks(&values, &masks),
            QM31::ZERO
        );
        Self { values }
    }

    pub const fn values(&self) -> &[QM31; V5_C_ROWS] {
        &self.values
    }

    pub fn into_values(self) -> [QM31; V5_C_ROWS] {
        self.values
    }

    /// Recover the independent coordinates.  Together with
    /// `encode_free_coordinates`, this makes the kernel bijection executable.
    pub fn free_coordinates(&self) -> [QM31; V5_C_FREE_COORDINATES] {
        match v5_c_free_coordinates_checked(&self.values) {
            V5CDecodeCorrespondence::Decoded(free) => free,
            V5CDecodeCorrespondence::MissingPivot => {
                panic!("atomic-v3 inactive functional is nonzero")
            }
        }
    }

    /// The three ordinary MLE claims plus the fourth structured terminal
    /// functional already budgeted by the v5 relation.
    pub fn relation_claims(
        &self,
        point: &[QM31; 10],
        terminal_covector: &[QM31; V5_C_ROWS],
    ) -> [QM31; V5_C_TOTAL_CLAIMS] {
        let points = [*point, binary_successor_point(point), xor12_point(point)];
        let mut claims = [QM31::ZERO; V5_C_TOTAL_CLAIMS];
        for (index, evaluation_point) in points.iter().enumerate() {
            claims[index] = crate::multilinear_eval_extension(&self.values, evaluation_point);
        }
        claims[V5_C_POINT_CLAIMS] = v5_c_dot(&self.values, terminal_covector);
        claims
    }
}

fn v5_c_encode_free_coordinates_checked(
    free: &[QM31; V5_C_FREE_COORDINATES],
) -> V5CEncodeCorrespondence {
    let masks = atomic_state_only_copy_inactive_row_masks_v3();
    v5_c_encode_free_coordinates_checked_with_masks(free, masks)
}

fn v5_c_encode_free_coordinates_checked_with_masks(
    free: &[QM31; V5_C_FREE_COORDINATES],
    masks: [u16; 64],
) -> V5CEncodeCorrespondence {
    let pivot = v5_c_pivot_row_with_masks(&masks);
    if pivot == V5_C_ROWS {
        return V5CEncodeCorrespondence::MissingPivot;
    }
    let values = v5_c_encode_free_coordinates_with_pivot_and_masks(free, pivot, &masks);
    V5CEncodeCorrespondence::Encoded(values, masks)
}

fn v5_c_free_coordinates_checked(values: &[QM31; V5_C_ROWS]) -> V5CDecodeCorrespondence {
    let masks = atomic_state_only_copy_inactive_row_masks_v3();
    v5_c_free_coordinates_checked_with_masks(values, &masks)
}

fn v5_c_free_coordinates_checked_with_masks(
    values: &[QM31; V5_C_ROWS],
    masks: &[u16; 64],
) -> V5CDecodeCorrespondence {
    let pivot = v5_c_pivot_row_with_masks(masks);
    if pivot == V5_C_ROWS {
        return V5CDecodeCorrespondence::MissingPivot;
    }
    V5CDecodeCorrespondence::Decoded(v5_c_free_coordinates_with_pivot(values, pivot))
}

fn v5_c_encode_free_coordinates_correspondence(
    free: &[QM31; V5_C_FREE_COORDINATES],
) -> V5CEncodeCorrespondence {
    v5_c_encode_free_coordinates_checked(free)
}

fn v5_c_free_coordinates_correspondence(values: &[QM31; V5_C_ROWS]) -> V5CDecodeCorrespondence {
    v5_c_free_coordinates_checked(values)
}

fn v5_c_encode_free_coordinates_with_pivot_and_masks(
    free: &[QM31; V5_C_FREE_COORDINATES],
    pivot: usize,
    masks: &[u16; 64],
) -> [QM31; V5_C_ROWS] {
    let mut values = [QM31::ZERO; V5_C_ROWS];
    let mut coordinate = 0;
    while coordinate < V5_C_FREE_COORDINATES {
        values[free_coordinate_row(coordinate, pivot)] = free[coordinate];
        coordinate += 1;
    }
    values[pivot] = v5_c_inactive_functional_with_masks(&values, masks).neg();
    values
}

fn v5_c_free_coordinates_with_pivot(
    values: &[QM31; V5_C_ROWS],
    pivot: usize,
) -> [QM31; V5_C_FREE_COORDINATES] {
    let mut free = [QM31::ZERO; V5_C_FREE_COORDINATES];
    let mut coordinate = 0;
    while coordinate < V5_C_FREE_COORDINATES {
        free[coordinate] = values[free_coordinate_row(coordinate, pivot)];
        coordinate += 1;
    }
    free
}

/// First coefficient-one row of the exact atomic-v3 inactive functional.
pub fn v5_c_pivot_row() -> usize {
    let masks = atomic_state_only_copy_inactive_row_masks_v3();
    let pivot = v5_c_pivot_row_with_masks(&masks);
    if pivot == V5_C_ROWS {
        panic!("atomic-v3 inactive functional is nonzero");
    }
    pivot
}

fn v5_c_pivot_row_with_masks(masks: &[u16; 64]) -> usize {
    let mut row = 0;
    while row < V5_C_ROWS {
        if inactive_row(masks, row) {
            return row;
        }
        row += 1;
    }
    V5_C_ROWS
}

/// Exact functional installed by the atomic-v3 PCS relation.
pub fn v5_c_inactive_functional(values: &[QM31; V5_C_ROWS]) -> QM31 {
    let masks = atomic_state_only_copy_inactive_row_masks_v3();
    v5_c_inactive_functional_with_masks(values, &masks)
}

fn v5_c_inactive_functional_with_masks(values: &[QM31; V5_C_ROWS], masks: &[u16; 64]) -> QM31 {
    let mut sum = QM31::ZERO;
    let mut row = 0;
    while row < V5_C_ROWS {
        if inactive_row(masks, row) {
            sum = sum.add(values[row]);
        }
        row += 1;
    }
    sum
}

pub fn v5_c_dot(left: &[QM31; V5_C_ROWS], right: &[QM31; V5_C_ROWS]) -> QM31 {
    left.iter()
        .copied()
        .zip(right.iter().copied())
        .fold(QM31::ZERO, |sum, (left, right)| sum.add(left.mul(right)))
}

fn inactive_row(masks: &[u16; 64], row: usize) -> bool {
    masks[row >> 4u32] & (1u16 << ((row & 15usize) as u32)) != 0
}

fn free_coordinate_row(coordinate: usize, pivot: usize) -> usize {
    debug_assert!(coordinate < V5_C_FREE_COORDINATES);
    if coordinate < pivot {
        coordinate
    } else {
        coordinate + 1
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use aspis_core::field::{CM31, M31};

    struct XorShift(u64);

    impl Qm31WordSource for XorShift {
        fn next_word(&mut self) -> u32 {
            let mut x = self.0;
            x ^= x << 13;
            x ^= x >> 7;
            x ^= x << 17;
            self.0 = x;
            (x >> 21) as u32
        }
    }

    fn q(seed: u32) -> QM31 {
        QM31 {
            c0: CM31::new(M31(seed * 1_003 + 1), M31(seed * 1_009 + 3)),
            c1: CM31::new(M31(seed * 1_021 + 5), M31(seed * 1_031 + 7)),
        }
    }

    fn free(seed: u32) -> [QM31; V5_C_FREE_COORDINATES] {
        core::array::from_fn(|coordinate| q(seed + coordinate as u32))
    }

    #[test]
    fn full_kernel_encoding_is_bijective_and_atomic_v3_exact() {
        let coordinates = free(10_000);
        let lane = V5ComponentCLane::encode_free_coordinates(&coordinates);
        let pivot = v5_c_pivot_row();
        let masks = atomic_state_only_copy_inactive_row_masks_v3();

        assert!(inactive_row(&masks, pivot));
        assert_eq!(v5_c_inactive_functional(lane.values()), QM31::ZERO);
        assert_eq!(lane.free_coordinates(), coordinates);
        assert_eq!(V5_C_FREE_COORDINATES, 1023);
    }

    #[test]
    fn sampler_is_nontrivial_and_stays_in_the_kernel() {
        let lane = V5ComponentCLane::sample(&mut XorShift(0xc031_5eed_71a4_902d)).unwrap();
        assert!(lane.values().iter().any(|value| *value != QM31::ZERO));
        assert_eq!(v5_c_inactive_functional(lane.values()), QM31::ZERO);
    }

    #[test]
    fn four_claims_match_literal_linear_functionals() {
        let lane = V5ComponentCLane::encode_free_coordinates(&free(20_000));
        let point = core::array::from_fn(|coordinate| q(30_000 + coordinate as u32));
        let terminal = core::array::from_fn(|row| q(40_000 + row as u32));
        let claims = lane.relation_claims(&point, &terminal);
        let points = [point, binary_successor_point(&point), xor12_point(&point)];

        for index in 0..V5_C_POINT_CLAIMS {
            assert_eq!(
                claims[index],
                crate::multilinear_eval_extension(lane.values(), &points[index])
            );
        }
        assert_eq!(claims[3], v5_c_dot(lane.values(), &terminal));
    }

    #[test]
    fn every_free_coordinate_survives_round_trip() {
        let pivot = v5_c_pivot_row();
        for coordinate in 0..V5_C_FREE_COORDINATES {
            let mut basis = [QM31::ZERO; V5_C_FREE_COORDINATES];
            basis[coordinate] = QM31::ONE;
            let lane = V5ComponentCLane::encode_free_coordinates(&basis);
            assert_eq!(lane.free_coordinates(), basis);
            assert_eq!(v5_c_inactive_functional(lane.values()), QM31::ZERO);
            assert_eq!(
                lane.values()[free_coordinate_row(coordinate, pivot)],
                QM31::ONE
            );
        }
    }

    #[test]
    fn correspondence_entrypoints_match_public_entrypoints_and_fail_closed() {
        for seed in 0..32 {
            let coordinates = free(50_000 + seed * 2_000);
            let lane = V5ComponentCLane::encode_free_coordinates(&coordinates);
            let V5CEncodeCorrespondence::Encoded(values, masks) =
                v5_c_encode_free_coordinates_correspondence(&coordinates)
            else {
                panic!("production atomic-v3 table has no Component-C pivot")
            };
            assert_eq!(values, *lane.values());
            assert_eq!(masks, atomic_state_only_copy_inactive_row_masks_v3());
            let V5CDecodeCorrespondence::Decoded(decoded) =
                v5_c_free_coordinates_correspondence(lane.values())
            else {
                panic!("production atomic-v3 table has no Component-C pivot")
            };
            assert_eq!(decoded, lane.free_coordinates());
        }

        let no_inactive_rows = [0u16; 64];
        let coordinates = free(120_000);
        let values = [QM31::ZERO; V5_C_ROWS];
        assert!(matches!(
            v5_c_encode_free_coordinates_checked_with_masks(&coordinates, no_inactive_rows),
            V5CEncodeCorrespondence::MissingPivot
        ));
        assert!(matches!(
            v5_c_free_coordinates_checked_with_masks(&values, &no_inactive_rows),
            V5CDecodeCorrespondence::MissingPivot
        ));
    }
}

crates/aspis-prover/src/v5_component_c_e:
//! Offline frozen-q18 Component-C conditioned-view matrix generator.
//!
//! This host-only module emits the `76 x 1023` matrix for the four public
//! Component-C claims on one deterministic CU fixture schedule:
//! 18 authenticated layer-zero fibres times four slots, three MLE claims,
//! and one structured terminal claim.  It deliberately contains no `F` map,
//! legal-difference space, C-DEC certificate, verifier wire, or production
//! integration.

use core::fmt;

use aspis_core::circle_line_merkle::{
    derive_circle_line_query_indices_for_count, CircleLineQueryIndices,
};
use aspis_core::field::{CM31, M31, P, QM31};
use aspis_statement::atomic_state_only_terminal::{
    atomic_state_only_copy_inactive_row_masks_v3,
    PINNED_ATOMIC_STATE_ONLY_COPY_ACTIVE_ROWS_FINGERPRINT_V3,
};
use aspis_statement::{binary_successor_point, xor12_point};

use super::component_c::{
    v5_c_inactive_functional, v5_c_pivot_row, V5ComponentCLane, V5_C_FREE_COORDINATES, V5_C_ROWS,
};
use super::real_host_proof::{
    V5RealHostArtifact, V5_REAL_HOST_QUERY_COUNT, V5_REAL_HOST_TRANSCRIPT_DOMAIN,
};
use super::spend_messages::{V5_C2_LANES, V5_FIBRE_SLOTS, V5_LAYER_ZERO_LEAVES};
use super::split_layer_zero::{v5_structured_terminal_covector, V5_RELATION_LANES};
use super::{V5_DOMAIN_LOG, V5_TRACE_ROWS};
use crate::circle_candidate::{CircleCandidateError, CircleEncoder};

pub const V5_C_EMAT_LAYER_ZERO_ROWS: usize = V5_REAL_HOST_QUERY_COUNT * V5_FIBRE_SLOTS;
pub const V5_C_EMAT_POINT_ROWS: usize = 3;
pub const V5_C_EMAT_TERMINAL_ROWS: usize = 1;
pub const V5_C_EMAT_ROWS: usize =
    V5_C_EMAT_LAYER_ZERO_ROWS + V5_C_EMAT_POINT_ROWS + V5_C_EMAT_TERMINAL_ROWS;
pub const V5_C_EMAT_COLUMNS: usize = V5_C_FREE_COORDINATES;
pub const V5_C_EMAT_QM31_BYTES: usize = 16;
pub const V5_C_EMAT_MATRIX_BYTES: usize = V5_C_EMAT_ROWS * V5_C_EMAT_COLUMNS * V5_C_EMAT_QM31_BYTES;
pub const V5_C_EMAT_SCHEDULE_BYTES: usize = 17_618 + V5_REAL_HOST_TRANSCRIPT_DOMAIN.len();

pub const V5_C_EMAT_ARTIFACT_MAGIC: [u8; 8] = *b"AV5EMT01";
pub const V5_C_EMAT_ARTIFACT_VERSION: u16 = 1;
pub const V5_C_EMAT_ARTIFACT_FLAGS: u16 = 0;
pub const V5_C_EMAT_ARTIFACT_HEADER_BYTES: usize = 128;

pub const V5_C_EMAT_KAT_BASIS_COLUMNS: [usize; 8] =
    [0, 1, 10, 137, 511, 683, 947, V5_C_EMAT_COLUMNS - 1];

const SCHEDULE_HASH_DOMAIN: &[u8] = b"aspis-v5-component-c-emat-schedule-v1";
const MATRIX_HASH_DOMAIN: &[u8] = b"aspis-v5-component-c-emat-matrix-v1";
const VECTOR_HASH_DOMAIN: &[u8] = b"aspis-v5-component-c-emat-vector-v1";

const _: () = assert!(V5_C_EMAT_LAYER_ZERO_ROWS == 72);
const _: () = assert!(V5_C_EMAT_ROWS == 76);
const _: () = assert!(V5_C_EMAT_COLUMNS == 1023);
const _: () = assert!(V5_C_EMAT_MATRIX_BYTES == 1_243_968);
const _: () = assert!(V5_C_EMAT_SCHEDULE_BYTES == 17_645);
const _: () = assert!(V5_C2_LANES == 3);
const _: () = assert!(V5_RELATION_LANES == 19);
const _: () = assert!(V5_TRACE_ROWS == V5_C_ROWS);

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum V5ComponentCEmatError {
    OpeningIndexDrift,
    CollisionShape {
        layer: u8,
        expected: usize,
        actual: usize,
    },
    PointScheduleDrift,
    TerminalCovectorShape {
        expected: usize,
        actual: usize,
    },
    TerminalCovectorDrift,
    PivotOutOfRange {
        pivot: usize,
    },
    PivotNotInactive {
        pivot: usize,
    },
    FreeCoordinateRoundTrip {
        column: usize,
    },
    InactiveFunctional {
        column: usize,
    },
    MatrixShape {
        expected: usize,
        actual: usize,
    },
    ReferenceParity {
        case: &'static str,
        index: usize,
    },
    Linearity {
        case: &'static str,
    },
    ArtifactShape,
    ArtifactHash {
        section: &'static str,
    },
    Circle(CircleCandidateError),
}

impl fmt::Display for V5ComponentCEmatError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::OpeningIndexDrift => write!(formatter, "frozen opening-index derivation drift"),
            Self::CollisionShape {
                layer,
                expected,
                actual,
            } => write!(
                formatter,
                "frozen q18 layer {layer} expected {expected} distinct leaves, got {actual}"
            ),
            Self::PointScheduleDrift => write!(formatter, "frozen relation-point schedule drift"),
            Self::TerminalCovectorShape { expected, actual } => write!(
                formatter,
                "terminal covector expected {expected} rows, got {actual}"
            ),
            Self::TerminalCovectorDrift => {
                write!(formatter, "frozen structured terminal covector drift")
            }
            Self::PivotOutOfRange { pivot } => {
                write!(formatter, "Component-C pivot row {pivot} is out of range")
            }
            Self::PivotNotInactive { pivot } => {
                write!(formatter, "Component-C pivot row {pivot} is not inactive")
            }
            Self::FreeCoordinateRoundTrip { column } => {
                write!(
                    formatter,
                    "free-coordinate basis column {column} did not round-trip"
                )
            }
            Self::InactiveFunctional { column } => write!(
                formatter,
                "free-coordinate basis column {column} left the inactive kernel"
            ),
            Self::MatrixShape { expected, actual } => {
                write!(
                    formatter,
                    "matrix expected {expected} entries, got {actual}"
                )
            }
            Self::ReferenceParity { case, index } => {
                write!(formatter, "{case} reference parity failed at index {index}")
            }
            Self::Linearity { case } => write!(formatter, "linearity check failed: {case}"),
            Self::ArtifactShape => write!(formatter, "non-canonical Emat artifact shape"),
            Self::ArtifactHash { section } => {
                write!(formatter, "Emat artifact {section} hash mismatch")
            }
            Self::Circle(error) => write!(formatter, "circle encoder error: {error}"),
        }
    }
}

impl std::error::Error for V5ComponentCEmatError {}

impl From<CircleCandidateError> for V5ComponentCEmatError {
    fn from(error: CircleCandidateError) -> Self {
        Self::Circle(error)
    }
}

/// Exact inputs on which the frozen conditioned-view matrix depends.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct V5ComponentCFrozenESchedule {
    pub statement_digest: [u8; 32],
    pub transcript_state_after_queries: [u8; 32],
    pub roots: [[u8; 32]; 5],
    pub query_selector: u8,
    pub queries: [u32; V5_REAL_HOST_QUERY_COUNT],
    pub layer0_fibres: [u32; V5_REAL_HOST_QUERY_COUNT],
    pub later_fibres: [[u32; V5_REAL_HOST_QUERY_COUNT]; 3],
    pub points: [[QM31; 10]; 3],
    pub terminal_covector: [QM31; V5_C_ROWS],
    pub inactive_masks: [u16; 64],
    pub pivot_row: usize,
}

fn fixed_array<const N: usize>(
    values: &[u32],
    layer: u8,
) -> Result<[u32; N], V5ComponentCEmatError> {
    values
        .try_into()
        .map_err(|_| V5ComponentCEmatError::CollisionShape {
            layer,
            expected: N,
            actual: values.len(),
        })
}

fn validate_query_shape(
    queries: &[u32; V5_REAL_HOST_QUERY_COUNT],
    expected: &CircleLineQueryIndices,
) -> Result<CircleLineQueryIndices, V5ComponentCEmatError> {
    let derived = derive_circle_line_query_indices_for_count(queries, V5_LAYER_ZERO_LEAVES)
        .map_err(|_| V5ComponentCEmatError::OpeningIndexDrift)?;
    if &derived != expected {
        return Err(V5ComponentCEmatError::OpeningIndexDrift);
    }
    if derived.layer0.len() != V5_REAL_HOST_QUERY_COUNT {
        return Err(V5ComponentCEmatError::CollisionShape {
            layer: 0,
            expected: V5_REAL_HOST_QUERY_COUNT,
            actual: derived.layer0.len(),
        });
    }
    for (layer, indices) in derived.later.iter().enumerate() {
        if indices.len() != V5_REAL_HOST_QUERY_COUNT {
            return Err(V5ComponentCEmatError::CollisionShape {
                layer: layer as u8 + 1,
                expected: V5_REAL_HOST_QUERY_COUNT,
                actual: indices.len(),
            });
        }
    }
    Ok(derived)
}

impl V5ComponentCFrozenESchedule {
    /// Extract the exact E-map schedule from the deterministic real-host CU
    /// artifact. Every index is rederived; collision-free q18 shape is a hard
    /// requirement rather than an assumed fixture property.
    pub fn from_real_host_artifact(
        artifact: &V5RealHostArtifact,
    ) -> Result<Self, V5ComponentCEmatError> {
        let indices = validate_query_shape(&artifact.queries, &artifact.opening_indices)?;
        let z = artifact.semantic_sumcheck.challenges;
        let points = [z, binary_successor_point(&z), xor12_point(&z)];
        if artifact.relation_claims.points != points {
            return Err(V5ComponentCEmatError::PointScheduleDrift);
        }
        let expected_terminal = v5_structured_terminal_covector(&z);
        if artifact.relation_claims.terminal_covector.len() != V5_C_ROWS {
            return Err(V5ComponentCEmatError::TerminalCovectorShape {
                expected: V5_C_ROWS,
                actual: artifact.relation_claims.terminal_covector.len(),
            });
        }
        if artifact.relation_claims.terminal_covector != expected_terminal {
            return Err(V5ComponentCEmatError::TerminalCovectorDrift);
        }
        let terminal_covector: [QM31; V5_C_ROWS] =
            expected_terminal.try_into().map_err(|values: Vec<QM31>| {
                V5ComponentCEmatError::TerminalCovectorShape {
                    expected: V5_C_ROWS,
                    actual: values.len(),
                }
            })?;

        let inactive_masks = atomic_state_only_copy_inactive_row_masks_v3();
        let pivot_row = v5_c_pivot_row();
        if pivot_row >= V5_C_ROWS {
            return Err(V5ComponentCEmatError::PivotOutOfRange { pivot: pivot_row });
        }
        if inactive_masks[pivot_row >> 4] & (1 << (pivot_row & 15)) == 0 {
            return Err(V5ComponentCEmatError::PivotNotInactive { pivot: pivot_row });
        }

        Ok(Self {
            statement_digest: artifact.statement_digest,
            transcript_state_after_queries: artifact.transcript_state_after_queries,
            roots: [
                artifact.roots.c1,
                artifact.roots.c2,
                artifact.roots.later[0],
                artifact.roots.later[1],
                artifact.roots.later[2],
            ],
            query_selector: artifact.query_selector,
            queries: artifact.queries,
            layer0_fibres: fixed_array(&indices.layer0, 0)?,
            later_fibres: [
                fixed_array(&indices.later[0], 1)?,
                fixed_array(&indices.later[1], 2)?,
                fixed_array(&indices.later[2], 3)?,
            ],
            points,
            terminal_covector,
            inactive_masks,
            pivot_row,
        })
    }

    /// Canonical schedule encoding used by the artifact hash. Redundant
    /// derived data is intentional: a reader can detect row-order or layout
    /// drift without rerunning the transcript.
    pub fn canonical_bytes(&self) -> Vec<u8> {
        let mut bytes = Vec::new();
        bytes.extend_from_slice(&(V5_REAL_HOST_TRANSCRIPT_DOMAIN.len() as u16).to_le_bytes());
        bytes.extend_from_slice(V5_REAL_HOST_TRANSCRIPT_DOMAIN);
        bytes.extend_from_slice(&V5_DOMAIN_LOG.to_le_bytes());
        bytes.extend_from_slice(&(V5_LAYER_ZERO_LEAVES as u32).to_le_bytes());
        bytes.extend_from_slice(&(V5_FIBRE_SLOTS as u32).to_le_bytes());
        bytes.extend_from_slice(&(V5_C2_LANES as u32).to_le_bytes());
        bytes.extend_from_slice(&(V5_RELATION_LANES as u32).to_le_bytes());
        bytes.extend_from_slice(&P.to_le_bytes());
        bytes.extend_from_slice(
            &PINNED_ATOMIC_STATE_ONLY_COPY_ACTIVE_ROWS_FINGERPRINT_V3.to_le_bytes(),
        );
        bytes.extend_from_slice(&self.statement_digest);
        bytes.extend_from_slice(&self.transcript_state_after_queries);
        for root in self.roots {
            bytes.extend_from_slice(&root);
        }
        bytes.push(self.query_selector);
        bytes.extend_from_slice(&[0u8; 3]);
        for query in self.queries {
            bytes.extend_from_slice(&query.to_le_bytes());
        }
        for index in self.layer0_fibres {
            bytes.extend_from_slice(&index.to_le_bytes());
        }
        for layer in self.later_fibres {
            for index in layer {
                bytes.extend_from_slice(&index.to_le_bytes());
            }
        }
        for point in self.points {
            for value in point {
                let start = bytes.len();
                bytes.resize(start + V5_C_EMAT_QM31_BYTES, 0);
                value.write_le_bytes(&mut bytes[start..]);
            }
        }
        for value in self.terminal_covector {
            let start = bytes.len();
            bytes.resize(start + V5_C_EMAT_QM31_BYTES, 0);
            value.write_le_bytes(&mut bytes[start..]);
        }
        for mask in self.inactive_masks {
            bytes.extend_from_slice(&mask.to_le_bytes());
        }
        bytes.extend_from_slice(&(self.pivot_row as u32).to_le_bytes());
        bytes
    }

    pub fn sha256(&self) -> [u8; 32] {
        crate::host_hashv(&[SCHEDULE_HASH_DOMAIN, &self.canonical_bytes()])
    }
}

fn free_basis(column: usize) -> [QM31; V5_C_EMAT_COLUMNS] {
    let mut free = [QM31::ZERO; V5_C_EMAT_COLUMNS];
    free[column] = QM31::ONE;
    free
}

fn nonzero_lane_terms(lane: &V5ComponentCLane) -> Vec<(usize, QM31)> {
    lane.values()
        .iter()
        .copied()
        .enumerate()
        .filter(|(_, value)| *value != QM31::ZERO)
        .collect()
}

fn encode_sparse_value(
    encoder: &CircleEncoder,
    terms: &[(usize, QM31)],
    codeword_index: usize,
) -> Result<QM31, V5ComponentCEmatError> {
    terms
        .iter()
        .copied()
        .try_fold(QM31::ZERO, |sum, (row, coefficient)| {
            let basis = encoder.encode_c1_basis_value(row, codeword_index)?;
            Ok(sum.add(coefficient.mul_m31(basis)))
        })
}

fn evaluate_sparse_with_encoder(
    schedule: &V5ComponentCFrozenESchedule,
    encoder: &CircleEncoder,
    free: &[QM31; V5_C_EMAT_COLUMNS],
) -> Result<[QM31; V5_C_EMAT_ROWS], V5ComponentCEmatError> {
    let lane = V5ComponentCLane::encode_free_coordinates(free);
    let terms = nonzero_lane_terms(&lane);
    let mut output = [QM31::ZERO; V5_C_EMAT_ROWS];
    for (fibre_ordinal, fibre) in schedule.layer0_fibres.iter().copied().enumerate() {
        for slot in 0..V5_FIBRE_SLOTS {
            let codeword_index = V5_FIBRE_SLOTS * fibre as usize + slot;
            output[V5_FIBRE_SLOTS * fibre_ordinal + slot] =
                encode_sparse_value(encoder, &terms, codeword_index)?;
        }
    }
    let claims = lane.relation_claims(&schedule.points[0], &schedule.terminal_covector);
    output[V5_C_EMAT_LAYER_ZERO_ROWS..].copy_from_slice(&claims);
    Ok(output)
}

fn evaluate_reference_with_encoder(
    schedule: &V5ComponentCFrozenESchedule,
    encoder: &CircleEncoder,
    free: &[QM31; V5_C_EMAT_COLUMNS],
) -> Result<[QM31; V5_C_EMAT_ROWS], V5ComponentCEmatError> {
    let lane = V5ComponentCLane::encode_free_coordinates(free);
    let codeword = encoder.encode_c2_message(lane.values())?;
    let mut output = [QM31::ZERO; V5_C_EMAT_ROWS];
    for (fibre_ordinal, fibre) in schedule.layer0_fibres.iter().copied().enumerate() {
        for slot in 0..V5_FIBRE_SLOTS {
            output[V5_FIBRE_SLOTS * fibre_ordinal + slot] =
                codeword[V5_FIBRE_SLOTS * fibre as usize + slot];
        }
    }
    let claims = lane.relation_claims(&schedule.points[0], &schedule.terminal_covector);
    output[V5_C_EMAT_LAYER_ZERO_ROWS..].copy_from_slice(&claims);
    Ok(output)
}

/// Evaluate all 76 conditioned rows without materialising the rate-1/512
/// codeword. This is exact encoder-matrix arithmetic, not an approximation.
pub fn evaluate_component_c_e_sparse(
    schedule: &V5ComponentCFrozenESchedule,
    free: &[QM31; V5_C_EMAT_COLUMNS],
) -> Result<[QM31; V5_C_EMAT_ROWS], V5ComponentCEmatError> {
    let encoder = CircleEncoder::new_for_domain_log(V5_DOMAIN_LOG);
    evaluate_sparse_with_encoder(schedule, &encoder, free)
}

/// Slow reference path through the complete deployed C2 circle encoder.
pub fn evaluate_component_c_e_reference(
    schedule: &V5ComponentCFrozenESchedule,
    free: &[QM31; V5_C_EMAT_COLUMNS],
) -> Result<[QM31; V5_C_EMAT_ROWS], V5ComponentCEmatError> {
    let encoder = CircleEncoder::new_for_domain_log(V5_DOMAIN_LOG);
    evaluate_reference_with_encoder(schedule, &encoder, free)
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct V5ComponentCEmat {
    entries: Vec<QM31>,
}

impl V5ComponentCEmat {
    /// Generate every column from the actual free-coordinate encoder. The
    /// layer-zero rows use sparse entries of the real circle encoding matrix;
    /// the four claims use the same literal Rust evaluators as the prover.
    pub fn generate(schedule: &V5ComponentCFrozenESchedule) -> Result<Self, V5ComponentCEmatError> {
        let encoder = CircleEncoder::new_for_domain_log(V5_DOMAIN_LOG);
        let mut entries = vec![QM31::ZERO; V5_C_EMAT_ROWS * V5_C_EMAT_COLUMNS];
        for column in 0..V5_C_EMAT_COLUMNS {
            let free = free_basis(column);
            let lane = V5ComponentCLane::encode_free_coordinates(&free);
            if lane.free_coordinates() != free {
                return Err(V5ComponentCEmatError::FreeCoordinateRoundTrip { column });
            }
            if v5_c_inactive_functional(lane.values()) != QM31::ZERO {
                return Err(V5ComponentCEmatError::InactiveFunctional { column });
            }
            let values = evaluate_sparse_with_encoder(schedule, &encoder, &free)?;
            for (row, value) in values.into_iter().enumerate() {
                entries[row * V5_C_EMAT_COLUMNS + column] = value;
            }
        }
        Ok(Self { entries })
    }

    pub fn from_entries(entries: Vec<QM31>) -> Result<Self, V5ComponentCEmatError> {
        let expected = V5_C_EMAT_ROWS * V5_C_EMAT_COLUMNS;
        if entries.len() != expected {
            return Err(V5ComponentCEmatError::MatrixShape {
                expected,
                actual: entries.len(),
            });
        }
        Ok(Self { entries })
    }

    pub fn entry(&self, row: usize, column: usize) -> QM31 {
        self.entries[row * V5_C_EMAT_COLUMNS + column]
    }

    pub fn column(&self, column: usize) -> [QM31; V5_C_EMAT_ROWS] {
        core::array::from_fn(|row| self.entry(row, column))
    }

    pub fn mul_vec(&self, vector: &[QM31; V5_C_EMAT_COLUMNS]) -> [QM31; V5_C_EMAT_ROWS] {
        core::array::from_fn(|row| {
            (0..V5_C_EMAT_COLUMNS).fold(QM31::ZERO, |sum, column| {
                sum.add(self.entry(row, column).mul(vector[column]))
            })
        })
    }

    pub fn canonical_bytes(&self) -> Vec<u8> {
        let mut bytes = vec![0u8; V5_C_EMAT_MATRIX_BYTES];
        for (index, value) in self.entries.iter().copied().enumerate() {
            value.write_le_bytes(
                &mut bytes[index * V5_C_EMAT_QM31_BYTES..(index + 1) * V5_C_EMAT_QM31_BYTES],
            );
        }
        bytes
    }

    pub fn sha256(&self) -> [u8; 32] {
        crate::host_hashv(&[MATRIX_HASH_DOMAIN, &self.canonical_bytes()])
    }

    pub fn encode_artifact(&self, schedule: &V5ComponentCFrozenESchedule) -> Vec<u8> {
        let schedule_bytes = schedule.canonical_bytes();
        debug_assert_eq!(schedule_bytes.len(), V5_C_EMAT_SCHEDULE_BYTES);
        let matrix_bytes = self.canonical_bytes();
        let schedule_hash = crate::host_hashv(&[SCHEDULE_HASH_DOMAIN, &schedule_bytes]);
        let matrix_hash = crate::host_hashv(&[MATRIX_HASH_DOMAIN, &matrix_bytes]);
        let mut output = vec![0u8; V5_C_EMAT_ARTIFACT_HEADER_BYTES];
        output[0..8].copy_from_slice(&V5_C_EMAT_ARTIFACT_MAGIC);
        output[8..10].copy_from_slice(&V5_C_EMAT_ARTIFACT_VERSION.to_le_bytes());
        output[10..12].copy_from_slice(&V5_C_EMAT_ARTIFACT_FLAGS.to_le_bytes());
        output[12..16].copy_from_slice(&(V5_C_EMAT_ARTIFACT_HEADER_BYTES as u32).to_le_bytes());
        output[16..20].copy_from_slice(&(V5_C_EMAT_ROWS as u32).to_le_bytes());
        output[20..24].copy_from_slice(&(V5_C_EMAT_COLUMNS as u32).to_le_bytes());
        output[24..28].copy_from_slice(&(V5_C_EMAT_LAYER_ZERO_ROWS as u32).to_le_bytes());
        output[28..32].copy_from_slice(&4u32.to_le_bytes());
        output[32..36].copy_from_slice(&(V5_REAL_HOST_QUERY_COUNT as u32).to_le_bytes());
        output[36..40].copy_from_slice(&V5_DOMAIN_LOG.to_le_bytes());
        output[40..44].copy_from_slice(&(schedule.pivot_row as u32).to_le_bytes());
        output[44..48].copy_from_slice(&P.to_le_bytes());
        output[48..52].copy_from_slice(&(V5_C_EMAT_QM31_BYTES as u32).to_le_bytes());
        output[52..56].copy_from_slice(&(schedule_bytes.len() as u32).to_le_bytes());
        output[56..64].copy_from_slice(&(matrix_bytes.len() as u64).to_le_bytes());
        output[64..96].copy_from_slice(&schedule_hash);
        output[96..128].copy_from_slice(&matrix_hash);
        output.extend_from_slice(&schedule_bytes);
        output.extend_from_slice(&matrix_bytes);
        output
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct V5ComponentCEmatArtifactView<'a> {
    pub schedule_bytes: &'a [u8],
    pub matrix_bytes: &'a [u8],
    pub schedule_sha256: [u8; 32],
    pub matrix_sha256: [u8; 32],
}

fn read_u16(bytes: &[u8], start: usize) -> Result<u16, V5ComponentCEmatError> {
    Ok(u16::from_le_bytes(
        bytes
            .get(start..start + 2)
            .ok_or(V5ComponentCEmatError::ArtifactShape)?
            .try_into()
            .unwrap(),
    ))
}

fn read_u32(bytes: &[u8], start: usize) -> Result<u32, V5ComponentCEmatError> {
    Ok(u32::from_le_bytes(
        bytes
            .get(start..start + 4)
            .ok_or(V5ComponentCEmatError::ArtifactShape)?
            .try_into()
            .unwrap(),
    ))
}

fn read_u64(bytes: &[u8], start: usize) -> Result<u64, V5ComponentCEmatError> {
    Ok(u64::from_le_bytes(
        bytes
            .get(start..start + 8)
            .ok_or(V5ComponentCEmatError::ArtifactShape)?
            .try_into()
            .unwrap(),
    ))
}

/// Parse and hash-check the maps-only artifact. Exact length is enforced, so
/// neither truncation nor hidden trailing sections are accepted.
pub fn validate_component_c_emat_artifact(
    bytes: &[u8],
) -> Result<V5ComponentCEmatArtifactView<'_>, V5ComponentCEmatError> {
    if bytes.len() < V5_C_EMAT_ARTIFACT_HEADER_BYTES
        || bytes.get(0..8) != Some(V5_C_EMAT_ARTIFACT_MAGIC.as_slice())
        || read_u16(bytes, 8)? != V5_C_EMAT_ARTIFACT_VERSION
        || read_u16(bytes, 10)? != V5_C_EMAT_ARTIFACT_FLAGS
        || read_u32(bytes, 12)? as usize != V5_C_EMAT_ARTIFACT_HEADER_BYTES
        || read_u32(bytes, 16)? as usize != V5_C_EMAT_ROWS
        || read_u32(bytes, 20)? as usize != V5_C_EMAT_COLUMNS
        || read_u32(bytes, 24)? as usize != V5_C_EMAT_LAYER_ZERO_ROWS
        || read_u32(bytes, 28)? != 4
        || read_u32(bytes, 32)? as usize != V5_REAL_HOST_QUERY_COUNT
        || read_u32(bytes, 36)? != V5_DOMAIN_LOG
        || read_u32(bytes, 44)? != P
        || read_u32(bytes, 48)? as usize != V5_C_EMAT_QM31_BYTES
        || read_u32(bytes, 52)? as usize != V5_C_EMAT_SCHEDULE_BYTES
        || read_u64(bytes, 56)? as usize != V5_C_EMAT_MATRIX_BYTES
    {
        return Err(V5ComponentCEmatError::ArtifactShape);
    }
    let schedule_len = read_u32(bytes, 52)? as usize;
    let schedule_start = V5_C_EMAT_ARTIFACT_HEADER_BYTES;
    let matrix_start = schedule_start
        .checked_add(schedule_len)
        .ok_or(V5ComponentCEmatError::ArtifactShape)?;
    let end = matrix_start
        .checked_add(V5_C_EMAT_MATRIX_BYTES)
        .ok_or(V5ComponentCEmatError::ArtifactShape)?;
    if end != bytes.len() {
        return Err(V5ComponentCEmatError::ArtifactShape);
    }
    let schedule_bytes = &bytes[schedule_start..matrix_start];
    let matrix_bytes = &bytes[matrix_start..end];
    let schedule_pivot = u32::from_le_bytes(
        schedule_bytes[schedule_bytes.len() - 4..]
            .try_into()
            .unwrap(),
    );
    if read_u32(bytes, 40)? != schedule_pivot || schedule_pivot as usize >= V5_C_ROWS {
        return Err(V5ComponentCEmatError::ArtifactShape);
    }
    let schedule_sha256: [u8; 32] = bytes[64..96].try_into().unwrap();
    let matrix_sha256: [u8; 32] = bytes[96..128].try_into().unwrap();
    if crate::host_hashv(&[SCHEDULE_HASH_DOMAIN, schedule_bytes]) != schedule_sha256 {
        return Err(V5ComponentCEmatError::ArtifactHash {
            section: "schedule",
        });
    }
    if crate::host_hashv(&[MATRIX_HASH_DOMAIN, matrix_bytes]) != matrix_sha256 {
        return Err(V5ComponentCEmatError::ArtifactHash { section: "matrix" });
    }
    if matrix_bytes
        .chunks_exact(V5_C_EMAT_QM31_BYTES)
        .any(|entry| QM31::from_le_bytes(entry).is_none())
    {
        return Err(V5ComponentCEmatError::ArtifactShape);
    }
    Ok(V5ComponentCEmatArtifactView {
        schedule_bytes,
        matrix_bytes,
        schedule_sha256,
        matrix_sha256,
    })
}

fn encode_qm31_vector(values: &[QM31]) -> Vec<u8> {
    let mut bytes = vec![0u8; values.len() * V5_C_EMAT_QM31_BYTES];
    for (index, value) in values.iter().copied().enumerate() {
        value.write_le_bytes(
            &mut bytes[index * V5_C_EMAT_QM31_BYTES..(index + 1) * V5_C_EMAT_QM31_BYTES],
        );
    }
    bytes
}

fn hash_qm31_vector(values: &[QM31]) -> [u8; 32] {
    crate::host_hashv(&[VECTOR_HASH_DOMAIN, &encode_qm31_vector(values)])
}

fn kat_word(seed: u32) -> [QM31; V5_C_EMAT_COLUMNS] {
    core::array::from_fn(|index| {
        let index = index as u64 + 1;
        let limb = |factor: u64, add: u64| {
            M31(((u64::from(seed) + factor * index + add) % u64::from(P)) as u32)
        };
        QM31 {
            c0: CM31::new(limb(1_003, 1), limb(1_009, 3)),
            c1: CM31::new(limb(1_021, 5), limb(1_031, 7)),
        }
    })
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct V5ComponentCEmatKatMetadata {
    pub basis_columns: [usize; V5_C_EMAT_KAT_BASIS_COLUMNS.len()],
    pub basis_column_sha256: [[u8; 32]; V5_C_EMAT_KAT_BASIS_COLUMNS.len()],
    pub dense_input_sha256: [u8; 32],
    pub dense_output_sha256: [u8; 32],
    pub reference_parity_cases: usize,
    pub linearity_checks: usize,
}

/// Run deterministic teeth and return their hashes for the JSON manifest.
/// Selected basis columns and one dense vector use the complete C2 encoder;
/// matrix multiplication and sparse evaluation must match them exactly.
pub fn build_component_c_emat_kats(
    schedule: &V5ComponentCFrozenESchedule,
    matrix: &V5ComponentCEmat,
) -> Result<V5ComponentCEmatKatMetadata, V5ComponentCEmatError> {
    let encoder = CircleEncoder::new_for_domain_log(V5_DOMAIN_LOG);
    let mut basis_hashes = [[0u8; 32]; V5_C_EMAT_KAT_BASIS_COLUMNS.len()];
    for (kat, column) in V5_C_EMAT_KAT_BASIS_COLUMNS.iter().copied().enumerate() {
        let free = free_basis(column);
        let sparse = evaluate_sparse_with_encoder(schedule, &encoder, &free)?;
        let reference = evaluate_reference_with_encoder(schedule, &encoder, &free)?;
        let emitted = matrix.column(column);
        if sparse != reference || sparse != emitted {
            return Err(V5ComponentCEmatError::ReferenceParity {
                case: "basis",
                index: column,
            });
        }
        basis_hashes[kat] = hash_qm31_vector(&emitted);
    }

    let dense = kat_word(0xc031_5eed);
    let dense_sparse = evaluate_sparse_with_encoder(schedule, &encoder, &dense)?;
    let dense_reference = evaluate_reference_with_encoder(schedule, &encoder, &dense)?;
    let dense_emitted = matrix.mul_vec(&dense);
    if dense_sparse != dense_reference || dense_sparse != dense_emitted {
        return Err(V5ComponentCEmatError::ReferenceParity {
            case: "dense",
            index: 0,
        });
    }

    let left = kat_word(0x51a7_1001);
    let right = kat_word(0x51a7_2002);
    let scalar = QM31 {
        c0: CM31::new(M31(17), M31(19)),
        c1: CM31::new(M31(23), M31(29)),
    };
    let sum = core::array::from_fn(|index| left[index].add(right[index]));
    let scaled = core::array::from_fn(|index| scalar.mul(left[index]));
    let e_left = evaluate_sparse_with_encoder(schedule, &encoder, &left)?;
    let e_right = evaluate_sparse_with_encoder(schedule, &encoder, &right)?;
    let e_sum = evaluate_sparse_with_encoder(schedule, &encoder, &sum)?;
    let expected_sum = core::array::from_fn(|row| e_left[row].add(e_right[row]));
    if e_sum != expected_sum || matrix.mul_vec(&sum) != expected_sum {
        return Err(V5ComponentCEmatError::Linearity { case: "additivity" });
    }
    let e_scaled = evaluate_sparse_with_encoder(schedule, &encoder, &scaled)?;
    let expected_scaled = core::array::from_fn(|row| scalar.mul(e_left[row]));
    if e_scaled != expected_scaled || matrix.mul_vec(&scaled) != expected_scaled {
        return Err(V5ComponentCEmatError::Linearity {
            case: "homogeneity",
        });
    }

    Ok(V5ComponentCEmatKatMetadata {
        basis_columns: V5_C_EMAT_KAT_BASIS_COLUMNS,
        basis_column_sha256: basis_hashes,
        dense_input_sha256: hash_qm31_vector(&dense),
        dense_output_sha256: hash_qm31_vector(&dense_emitted),
        reference_parity_cases: V5_C_EMAT_KAT_BASIS_COLUMNS.len() + 1,
        linearity_checks: 2,
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    fn q(seed: u32) -> QM31 {
        QM31 {
            c0: CM31::new(M31(seed * 1_003 + 1), M31(seed * 1_009 + 3)),
            c1: CM31::new(M31(seed * 1_021 + 5), M31(seed * 1_031 + 7)),
        }
    }

    fn synthetic_schedule() -> V5ComponentCFrozenESchedule {
        let queries = core::array::from_fn(|index| 123 + 4_096 * index as u32);
        let indices =
            derive_circle_line_query_indices_for_count(&queries, V5_LAYER_ZERO_LEAVES).unwrap();
        assert_eq!(indices.layer0.len(), V5_REAL_HOST_QUERY_COUNT);
        assert!(indices
            .later
            .iter()
            .all(|layer| layer.len() == V5_REAL_HOST_QUERY_COUNT));
        let z = core::array::from_fn(|coordinate| q(100 + coordinate as u32));
        let points = [z, binary_successor_point(&z), xor12_point(&z)];
        let terminal_covector: [QM31; V5_C_ROWS] =
            v5_structured_terminal_covector(&z).try_into().unwrap();
        V5ComponentCFrozenESchedule {
            statement_digest: [0x51; 32],
            transcript_state_after_queries: [0xa7; 32],
            roots: core::array::from_fn(|root| [root as u8 + 1; 32]),
            query_selector: 0,
            queries,
            layer0_fibres: indices.layer0.try_into().unwrap(),
            later_fibres: [
                indices.later[0].clone().try_into().unwrap(),
                indices.later[1].clone().try_into().unwrap(),
                indices.later[2].clone().try_into().unwrap(),
            ],
            points,
            terminal_covector,
            inactive_masks: atomic_state_only_copy_inactive_row_masks_v3(),
            pivot_row: v5_c_pivot_row(),
        }
    }

    #[test]
    fn collision_shape_is_rejected_before_matrix_generation() {
        let queries = core::array::from_fn(|index| index as u32);
        let indices =
            derive_circle_line_query_indices_for_count(&queries, V5_LAYER_ZERO_LEAVES).unwrap();
        assert_eq!(
            validate_query_shape(&queries, &indices),
            Err(V5ComponentCEmatError::CollisionShape {
                layer: 1,
                expected: V5_REAL_HOST_QUERY_COUNT,
                actual: 5,
            })
        );

        let mut drift = indices;
        drift.layer0.swap(0, 1);
        assert_eq!(
            validate_query_shape(&queries, &drift),
            Err(V5ComponentCEmatError::OpeningIndexDrift)
        );
    }

    #[test]
    fn sparse_matrix_reference_linearity_and_artifact_teeth_are_exact() {
        let schedule = synthetic_schedule();
        let matrix = V5ComponentCEmat::generate(&schedule).unwrap();
        assert_eq!(matrix.canonical_bytes().len(), V5_C_EMAT_MATRIX_BYTES);
        assert_eq!(schedule.pivot_row, 0);

        let kats = build_component_c_emat_kats(&schedule, &matrix).unwrap();
        assert_eq!(kats.reference_parity_cases, 9);
        assert_eq!(kats.linearity_checks, 2);

        let matrix_bytes = matrix.canonical_bytes();
        for (index, bytes) in matrix_bytes.chunks_exact(16).enumerate() {
            let decoded = QM31::from_le_bytes(bytes).unwrap();
            assert_eq!(decoded, matrix.entries[index]);
        }
        for row in 0..V5_C_EMAT_ROWS {
            for column in [0, 137, V5_C_EMAT_COLUMNS - 1] {
                let start = (row * V5_C_EMAT_COLUMNS + column) * 16;
                assert_eq!(
                    QM31::from_le_bytes(&matrix_bytes[start..start + 16]).unwrap(),
                    matrix.entry(row, column)
                );
            }
        }

        let artifact = matrix.encode_artifact(&schedule);
        assert_eq!(artifact, matrix.encode_artifact(&schedule));
        let view = validate_component_c_emat_artifact(&artifact).unwrap();
        assert_eq!(view.schedule_sha256, schedule.sha256());
        assert_eq!(view.matrix_sha256, matrix.sha256());
        assert_eq!(view.matrix_bytes.len(), V5_C_EMAT_MATRIX_BYTES);

        let mut schedule_mutation = artifact.clone();
        schedule_mutation[V5_C_EMAT_ARTIFACT_HEADER_BYTES] ^= 1;
        assert!(matches!(
            validate_component_c_emat_artifact(&schedule_mutation),
            Err(V5ComponentCEmatError::ArtifactHash {
                section: "schedule"
            })
        ));

        let mut matrix_mutation = artifact.clone();
        *matrix_mutation.last_mut().unwrap() ^= 1;
        assert!(matches!(
            validate_component_c_emat_artifact(&matrix_mutation),
            Err(V5ComponentCEmatError::ArtifactHash { section: "matrix" })
        ));

        // A recomputed section hash must not launder a non-canonical field
        // limb into an otherwise well-shaped artifact.
        let mut noncanonical_matrix = artifact.clone();
        let matrix_start = V5_C_EMAT_ARTIFACT_HEADER_BYTES + V5_C_EMAT_SCHEDULE_BYTES;
        noncanonical_matrix[matrix_start..matrix_start + 4].copy_from_slice(&P.to_le_bytes());
        let matrix_hash = crate::host_hashv(&[
            MATRIX_HASH_DOMAIN,
            &noncanonical_matrix[matrix_start..matrix_start + V5_C_EMAT_MATRIX_BYTES],
        ]);
        noncanonical_matrix[96..128].copy_from_slice(&matrix_hash);
        assert_eq!(
            validate_component_c_emat_artifact(&noncanonical_matrix),
            Err(V5ComponentCEmatError::ArtifactShape)
        );

        let mut shape_mutation = artifact.clone();
        shape_mutation[16..20].copy_from_slice(&75u32.to_le_bytes());
        assert_eq!(
            validate_component_c_emat_artifact(&shape_mutation),
            Err(V5ComponentCEmatError::ArtifactShape)
        );

        let mut pivot_header_mutation = artifact.clone();
        pivot_header_mutation[40] ^= 1;
        assert_eq!(
            validate_component_c_emat_artifact(&pivot_header_mutation),
            Err(V5ComponentCEmatError::ArtifactShape)
        );

        let mut trailing = artifact;
        trailing.push(0);
        assert_eq!(
            validate_component_c_emat_artifact(&trailing),
            Err(V5ComponentCEmatError::ArtifactShape)
        );
    }
}

crates/aspis-prover/src/v5_component_c_f:
//! Offline frozen-q18 Component-C private-view matrix generator.
//!
//! This host-only module emits the intrinsic, unscaled `256 x 1023` map
//! `F_sigma`. Its rows are the four relation rounds (two OOD values and seven
//! sumcheck coefficients each), three authenticated later layers (18 fibres
//! by four slots each), and the four final coefficients. The deployed lane
//! coefficient `gamma^18` is deliberately not included in the matrix.
//!
//! This file defines no legal-difference space, `Delta`, C-DEC certificate,
//! verifier wire, proof bytes, or production integration.

use std::collections::BTreeMap;
use std::fmt;

use aspis_core::circle::SecureCirclePoint;
use aspis_core::circle_fri::{
    normalized_circle_to_line_arity4_at_fiber_for_domain_log,
    normalized_line_arity4_at_fiber_for_domain_log,
};
use aspis_core::circle_prefix::{
    CANDIDATE_FINAL_POLY_LEN, CANDIDATE_OOD_SAMPLES, CANDIDATE_ROUND_COUNT,
};
use aspis_core::field::{CM31, M31, P, QM31};
use aspis_core::sumcheck::{
    boundary_sum, evaluate, SumcheckPolynomial, TensorWeightError, WeightAccumulator,
};

use super::component_c::{
    v5_c_inactive_functional, V5ComponentCLane, V5_C_FREE_COORDINATES, V5_C_ROWS,
};
use super::component_c_emat::{
    V5ComponentCFrozenESchedule, V5_C_EMAT_KAT_BASIS_COLUMNS, V5_C_EMAT_QM31_BYTES,
    V5_C_EMAT_SCHEDULE_BYTES,
};
use super::component_c_runtime::{
    evaluate_component_c_runtime_private_view, V5ComponentCRuntimeError,
    V5ComponentCRuntimeSchedule,
};
use super::real_host_proof::V5RealHostArtifact;
use super::relation_prover::{V5RelationProverError, V5RelationTrace};
use super::spend_messages::{V5_FIBRE_SLOTS, V5_LATER_LAYERS};
use super::V5_DOMAIN_LOG;
use crate::circle_candidate::{CircleCandidateError, CircleEncoder};

pub const V5_C_FMAT_RELATION_ROWS: usize = CANDIDATE_ROUND_COUNT * (CANDIDATE_OOD_SAMPLES + 7);
pub const V5_C_FMAT_LATER_ROWS: usize = V5_LATER_LAYERS * 18 * V5_FIBRE_SLOTS;
pub const V5_C_FMAT_FINAL_ROWS: usize = CANDIDATE_FINAL_POLY_LEN;
pub const V5_C_FMAT_ROWS: usize =
    V5_C_FMAT_RELATION_ROWS + V5_C_FMAT_LATER_ROWS + V5_C_FMAT_FINAL_ROWS;
pub const V5_C_FMAT_COLUMNS: usize = V5_C_FREE_COORDINATES;
pub const V5_C_FMAT_MATRIX_BYTES: usize = V5_C_FMAT_ROWS * V5_C_FMAT_COLUMNS * V5_C_EMAT_QM31_BYTES;
pub const V5_C_FMAT_GAMMA18_INCLUDED: bool = false;

pub const V5_C_FMAT_ARTIFACT_MAGIC: [u8; 8] = *b"AV5FMT01";
pub const V5_C_FMAT_ARTIFACT_VERSION: u16 = 1;
/// Bit zero would mean the matrix entries already include `gamma^18`. It is
/// pinned clear for the intrinsic `F_sigma` convention.
pub const V5_C_FMAT_ARTIFACT_FLAGS: u16 = 0;
pub const V5_C_FMAT_ARTIFACT_HEADER_BYTES: usize = 128;

/// The F schedule embeds the exact v1 E schedule, then an eight-byte
/// convention record, gamma/kappa, OOD points, OOD mixes, and fold alphas.
pub const V5_C_FMAT_SCHEDULE_BYTES: usize = V5_C_EMAT_SCHEDULE_BYTES
    + 8
    + 2 * V5_C_EMAT_QM31_BYTES
    + 2 * 2 * V5_C_EMAT_QM31_BYTES
    + 3 * 2 * V5_C_EMAT_QM31_BYTES
    + 4 * 2 * V5_C_EMAT_QM31_BYTES
    + 4 * V5_C_EMAT_QM31_BYTES;

const SCHEDULE_HASH_DOMAIN: &[u8] = b"aspis-v5-component-c-fmat-schedule-v1";
const MATRIX_HASH_DOMAIN: &[u8] = b"aspis-v5-component-c-fmat-matrix-v1";
const VECTOR_HASH_DOMAIN: &[u8] = b"aspis-v5-component-c-fmat-vector-v1";

const _: () = assert!(V5_C_FMAT_RELATION_ROWS == 36);
const _: () = assert!(V5_C_FMAT_LATER_ROWS == 216);
const _: () = assert!(V5_C_FMAT_FINAL_ROWS == 4);
const _: () = assert!(V5_C_FMAT_ROWS == 256);
const _: () = assert!(V5_C_FMAT_COLUMNS == 1023);
const _: () = assert!(V5_C_FMAT_MATRIX_BYTES == 4_190_208);
const _: () = assert!(V5_C_FMAT_SCHEDULE_BYTES == 18_037);
const _: () = assert!(V5_LATER_LAYERS == CANDIDATE_ROUND_COUNT - 1);
const _: () = assert!(!V5_C_FMAT_GAMMA18_INCLUDED);

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum V5ComponentCFmatError {
    BaseSchedule(super::component_c_emat::V5ComponentCEmatError),
    ChallengeZero { name: &'static str },
    MessageShape { expected: usize, actual: usize },
    CodewordShape { expected: usize, actual: usize },
    MatrixShape { expected: usize, actual: usize },
    FreeCoordinateRoundTrip { column: usize },
    InactiveFunctional { column: usize },
    SparseRelation { stage: &'static str },
    ReferenceParity { case: &'static str, index: usize },
    Linearity { case: &'static str },
    Gamma18Correspondence { row: usize },
    ArtifactShape,
    ArtifactHash { section: &'static str },
    Circle(CircleCandidateError),
    Relation(V5RelationProverError),
    Runtime(V5ComponentCRuntimeError),
    Weight(TensorWeightError),
}

impl fmt::Display for V5ComponentCFmatError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::BaseSchedule(error) => write!(formatter, "frozen E schedule: {error}"),
            Self::ChallengeZero { name } => write!(formatter, "frozen {name} challenge is zero"),
            Self::MessageShape { expected, actual } => {
                write!(
                    formatter,
                    "message expected {expected} values, got {actual}"
                )
            }
            Self::CodewordShape { expected, actual } => {
                write!(
                    formatter,
                    "codeword expected {expected} values, got {actual}"
                )
            }
            Self::MatrixShape { expected, actual } => {
                write!(
                    formatter,
                    "matrix expected {expected} entries, got {actual}"
                )
            }
            Self::FreeCoordinateRoundTrip { column } => {
                write!(
                    formatter,
                    "free-coordinate basis {column} did not round-trip"
                )
            }
            Self::InactiveFunctional { column } => write!(
                formatter,
                "free-coordinate basis {column} left the inactive kernel"
            ),
            Self::SparseRelation { stage } => {
                write!(formatter, "sparse relation invariant failed at {stage}")
            }
            Self::ReferenceParity { case, index } => {
                write!(formatter, "{case} reference parity failed at {index}")
            }
            Self::Linearity { case } => write!(formatter, "linearity failed: {case}"),
            Self::Gamma18Correspondence { row } => {
                write!(formatter, "gamma^18 correspondence failed at row {row}")
            }
            Self::ArtifactShape => write!(formatter, "non-canonical Fmat artifact shape"),
            Self::ArtifactHash { section } => {
                write!(formatter, "Fmat artifact {section} hash mismatch")
            }
            Self::Circle(error) => write!(formatter, "circle arithmetic: {error}"),
            Self::Relation(error) => write!(formatter, "incremental relation: {error:?}"),
            Self::Runtime(error) => write!(formatter, "runtime downstream evaluator: {error:?}"),
            Self::Weight(error) => write!(formatter, "relation weight: {error:?}"),
        }
    }
}

impl std::error::Error for V5ComponentCFmatError {}

impl From<CircleCandidateError> for V5ComponentCFmatError {
    fn from(error: CircleCandidateError) -> Self {
        Self::Circle(error)
    }
}

impl From<V5RelationProverError> for V5ComponentCFmatError {
    fn from(error: V5RelationProverError) -> Self {
        Self::Relation(error)
    }
}

impl From<V5ComponentCRuntimeError> for V5ComponentCFmatError {
    fn from(error: V5ComponentCRuntimeError) -> Self {
        Self::Runtime(error)
    }
}

impl From<TensorWeightError> for V5ComponentCFmatError {
    fn from(error: TensorWeightError) -> Self {
