        }
    }

    fn boolean_point(assignment: usize) -> [QM31; STATE_ONLY_SUMCHECK_ROUNDS] {
        core::array::from_fn(|coordinate| {
            if (assignment >> (STATE_ONLY_SUMCHECK_ROUNDS - 1 - coordinate)) & 1 == 0 {
                QM31::ZERO
