        .map_err(|_| V6ProverError::Stage("V6 shared leaf salt"))
}

fn derive_v7_leaf_salt(
    reserved: &ReservedStateOnlyAttemptSecrets,
    hash: HashFn,
    hiding_context: StateOnlyHidingContext,
    fiber: usize,
) -> Result<[u8; 32], V6ProverError> {
