    let mut queries = [0u32; STATE_ONLY_MAX_QUERY_COUNT];
    queries[..16].copy_from_slice(&[
        152_742, 172_436, 140_755, 112_262, 203_944, 205_890, 96_695, 220_077, 230_153, 141_221,
