//! Fixed-C1 final-round obstruction, tested against literal mask factors.
//! Arbitrary opening values are permitted in this algebra test; NOT a witness.
#![cfg(feature = "insecure-spend-fixture")]
use aspis_core::{
    field::{CM31, M31, QM31},
    state_only_hiding::state_only_selected_mask_value,
};
fn q(n: u32) -> QM31 {
    QM31::from_cm31(CM31::from_m31(M31(n)))
}
fn interpolate(values: &[QM31]) -> Vec<QM31> {
    let n = values.len();
    let mut out = vec![QM31::ZERO; n];
    for i in 0..n {
        let mut basis = vec![QM31::ONE];
        for j in 0..n {
            if i == j {
                continue;
            }
            let mut next = vec![QM31::ZERO; basis.len() + 1];
            let scale = q(i as u32).sub(q(j as u32)).inv();
            for k in 0..basis.len() {
                next[k] = next[k].sub(basis[k].mul(q(j as u32)));
                next[k + 1] = next[k + 1].add(basis[k]);
            }
            basis = next.into_iter().map(|x| x.mul(scale)).collect();
        }
        for k in 0..n {
            out[k] = out[k].add(values[i].mul(basis[k]));
        }
    }
    out
}
fn check_high(poly: &[QM31], a: QM31) {
    let alpha = a.mul(q(1625).inv());
    for (j, m, n, power) in [
        (23usize, 2600u32, 52650u32, 3u64),
        (24, 325, 5850, 2),
        (25, 26, 351, 1),
    ] {
        let value = poly[j]
            .sub(q(m).mul(alpha.pow(power)).mul(poly[26]))
            .add(q(n).mul(alpha.pow(power + 1)).mul(poly[27]));
        assert_eq!(value, QM31::ZERO, "high invariant c{j}");
    }
}
