crates/aspis-prover/tests/r14_public_pre:
//! R14 source Transcript KAT. Research-only deterministic public data.
//! Does NOT prove a random-oracle law or instantiate a full q22 prover.
#![cfg(feature = "insecure-spend-fixture")]
use aspis_core::{
    field::QM31,
    state_only_hiding::begin_state_only_masked_sumcheck,
    transcript::{label, Transcript},
};
use sha2::{Digest, Sha256};
use std::cell::RefCell;
thread_local! {static CALLS:RefCell<Vec<Vec<u8>>>=RefCell::new(Vec::new());}
fn hash(parts: &[&[u8]]) -> [u8; 32] {
    let bytes = parts.concat();
    CALLS.with(|c| c.borrow_mut().push(bytes.clone()));
    Sha256::digest(bytes).into()
}
fn read_q(bytes: &[u8], cursor: &mut usize) -> QM31 {
    let end = cursor.checked_add(16).expect("cursor overflow");
    let q =
        QM31::from_le_bytes(bytes.get(*cursor..end).expect("short KAT")).expect("noncanonical KAT");
    *cursor = end;
    q
}
#[test]
fn r14_literal_initial_eta_and_three_compact_rounds_match_python() {
    let data = include_bytes!("support/r14_public_prefix.bin");
    assert_eq!(&data[..8], b"R14PUB01");
    let root = &data[8..34];
    let mut cursor = 34;
    let view: Vec<_> = (0..82).map(|_| read_q(data, &mut cursor)).collect();
    let eta_expected = read_q(data, &mut cursor);
    let challenges: Vec<_> = (0..3).map(|_| read_q(data, &mut cursor)).collect();
    let final_state: [u8; 32] = data[cursor..cursor + 32].try_into().unwrap();
    cursor += 32;
    assert_eq!(cursor, data.len());
    CALLS.with(|c| c.borrow_mut().clear());
    let mut t = Transcript::new(hash);
    let entry = [&b"R14-public-post-C2-entry-v1"[..], root].concat();
    t.absorb(label::STATEMENT, &entry);
    assert_eq!(
        begin_state_only_masked_sumcheck(&mut t, view[0]).unwrap(),
        eta_expected
    );
    for round in 0..3 {
        let mut framed = [0u8; 433];
        framed[0] = round as u8;
        for (sent, q) in view[1 + 27 * round..28 + 27 * round].iter().enumerate() {
            q.write_le_bytes(&mut framed[1 + 16 * sent..17 + 16 * sent]);
        }
        t.absorb(label::V6_COMPACT_SEMANTIC_ROUND, &framed);
        assert_eq!(t.challenge_qm31().unwrap(), challenges[round]);
    }
    assert_eq!(t.diagnostic_state(), final_state);
    CALLS.with(|calls| {
        let calls = calls.borrow();
        assert_eq!(calls.len(), 13);
        // Pin every full input and full 32-byte answer, including discarded
        // challenge bits; checking only returned field elements is weaker.
        let mut all = Sha256::new();
        for key in calls.iter() {
            all.update((key.len() as u32).to_le_bytes());
            all.update(key);
            all.update(Sha256::digest(key));
        }
        let got: [u8; 32] = all.finalize().into();
        assert_eq!(
            got,
            [
                101, 242, 188, 163, 231, 79, 147, 129, 122, 150, 7, 137, 221, 193, 69, 217, 38, 91,
                176, 103, 20, 145, 23, 83, 162, 99, 125, 1, 13, 218, 179, 230
            ]
        );
        assert_eq!(calls[1].len(), 52);
        assert_eq!(&calls[1][32..36], &[0, 31, 27, 10]);
        for start in [4usize, 7, 10] {
            assert_eq!(calls[start].len(), 467);
            assert_eq!(calls[start][33], 48);
            assert_eq!(calls[start + 1].len(), 33);
            assert_eq!(calls[start + 2].len(), 33);
        }
    });
}

//! Research-only, in-memory trace of the pinned source salt/leaf prefix.
//! This is a base V7 helper instantiation, not the unavailable generated q22
//! producer and not a universal call-graph or query-cap certificate.

use std::cell::RefCell;

use aspis_core::state_only_hiding::StateOnlyHidingContext;
use aspis_core::v7_merkle208::{private_leaf_hash_v7, V7_C1_TREE_TAG, V7_C2_TREE_TAG};
use aspis_prover::state_only_entropy::StateOnlyAttemptSecrets;
use aspis_prover::state_only_hiding::InMemoryStateOnlyMaskNonceStore;
use sha2::{Digest, Sha256};
use zeroize::Zeroize;

type HashFn = fn(&[&[u8]]) -> [u8; 32];

struct HashEvent {
    phase: u32,
    input: Vec<u8>,
    answer: [u8; 32],
}

impl Drop for HashEvent {
    fn drop(&mut self) {
        self.input.zeroize();
        self.answer.zeroize();
    }
}

struct Capture {
    events: Vec<HashEvent>,
    total_calls: u64,
    truncated: bool,
    stored_bytes: usize,
    max_bytes: usize,
    max_events: usize,
    phase: u32,
}

impl Capture {
    fn complete(&self) -> bool {
        !self.truncated && self.total_calls == self.events.len() as u64
    }
}

struct Session {
    backend: HashFn,
    capture: Capture,
}

thread_local! {
    static SESSION: RefCell<Option<Session>> = const { RefCell::new(None) };
}

struct ClearOnDrop;

impl Drop for ClearOnDrop {
    fn drop(&mut self) {
        SESSION.with(|cell| {
            cell.borrow_mut().take();
        });
    }
}

fn capture<T>(
    backend: HashFn,
    max_bytes: usize,
    max_events: usize,
    run: impl FnOnce(HashFn) -> T,
) -> (T, Capture) {
    SESSION.with(|cell| {
        assert!(cell.borrow().is_none(), "nested capture unsupported");
        *cell.borrow_mut() = Some(Session {
            backend,
            capture: Capture {
                events: Vec::new(),
                total_calls: 0,
                truncated: false,
                stored_bytes: 0,
                max_bytes,
                max_events,
                phase: 0,
            },
        });
    });
    let _cleanup = ClearOnDrop;
    let output = run(recording_hash);
    let session = SESSION.with(|cell| cell.borrow_mut().take().expect("active capture"));
    (output, session.capture)
}

fn phase(id: u32) {
    SESSION.with(|cell| {
        cell.borrow_mut()
            .as_mut()
            .expect("active capture")
            .capture
            .phase = id;
    });
}

fn recording_hash(parts: &[&[u8]]) -> [u8; 32] {
    let backend = SESSION.with(|cell| cell.borrow().as_ref().expect("capture thread").backend);
    let answer = backend(parts);
    SESSION.with(|cell| {
        let mut session = cell.borrow_mut();
        let capture = &mut session.as_mut().expect("active capture").capture;
        capture.total_calls = capture.total_calls.saturating_add(1);
        let Some(input_len) = parts
            .iter()
            .try_fold(0usize, |n, part| n.checked_add(part.len()))
        else {
            capture.truncated = true;
            return;
        };
        let cost = input_len.checked_add(32);
        if capture.events.len() >= capture.max_events
            || cost
                .and_then(|value| capture.stored_bytes.checked_add(value))
                .is_none_or(|value| value > capture.max_bytes)
        {
            capture.truncated = true;
            return;
        }
        let mut input = Vec::with_capacity(input_len);
        for part in parts {
            input.extend_from_slice(part);
        }
        capture.stored_bytes += cost.expect("checked above");
        capture.events.push(HashEvent {
            phase: capture.phase,
            input,
            answer,
        });
    });
    answer
}

fn sha256(parts: &[&[u8]]) -> [u8; 32] {
    let mut hasher = Sha256::new();
    for part in parts {
        hasher.update(part);
    }
    hasher.finalize().into()
}

#[test]
fn pinned_pool_helper_retains_salt_through_typed_c2_leaf() {
    const PHASE_RESERVE: u32 = 1;
    const PHASE_C1: u32 = 2;
    const PHASE_C2: u32 = 3;
    let ((salt, other, c1_digest, c2_digest), trace) =
        capture(sha256, 4 * 1024 * 1024, 20_000, |hash| {
            phase(PHASE_RESERVE);
            let nonce = [0x23; 32];
            let context = StateOnlyHidingContext::pool_v1_pair_forest_v1([0x45; 32], nonce);
            let attempt =
                StateOnlyAttemptSecrets::deterministic_spend_fixture(nonce, [0x67; 32], [0x89; 32]);
            let mut nonces = InMemoryStateOnlyMaskNonceStore::default();
            let (reserved, _material) = attempt
                .reserve_and_build_pool_v1_pair_forest_mask_material_v1(
                    hash,
                    [0xab; 32],
                    context,
                    &mut nonces,
                )
                .expect("pinned source reservation");

            phase(PHASE_C1);
            let salt = reserved
                .derive_pool_v1_leaf_salt(hash, context, 0x77, 7)
                .expect("C1 salt");
            let c1_digest = private_leaf_hash_v7(hash, V7_C1_TREE_TAG, &[0x11; 403], &salt);

            phase(PHASE_C2);
            // The selected generated prefix retains `salts[i]` from the C1
            // loop and passes that same value into the C2 typed leaf.
            let c2_digest = private_leaf_hash_v7(hash, V7_C2_TREE_TAG, &[0x22; 186], &salt);
            let other = reserved
                .derive_pool_v1_leaf_salt(hash, context, 0x77, 8)
                .expect("next logical address");
            (salt, other, c1_digest, c2_digest)
        });

    assert!(trace.complete());
    assert_ne!(salt, other);
    assert_eq!(c1_digest.len(), 26);
    assert_eq!(c2_digest.len(), 26);

    let c1_leaf = trace
        .events
        .iter()
        .find(|event| {
            event.phase == PHASE_C1
                && event.input.len() == 437
                && event.input.starts_with(&[0x10, V7_C1_TREE_TAG])
        })
        .expect("complete C1 typed-leaf call");
    let c2_leaf = trace
        .events
        .iter()
        .find(|event| {
            event.phase == PHASE_C2
                && event.input.len() == 220
                && event.input.starts_with(&[0x10, V7_C2_TREE_TAG])
        })
        .expect("complete C2 typed-leaf call");
    assert_eq!(&c1_leaf.input[c1_leaf.input.len() - 32..], salt);
    assert_eq!(&c2_leaf.input[c2_leaf.input.len() - 32..], salt);

    let address7_derivations: Vec<_> = trace
        .events
        .iter()
        .filter(|event| {
            event
                .input
                .starts_with(b"aspis:state-only:private-leaf-salt:v1")
                && event.input.ends_with(&[0x89; 32])
                && event.input[event.input.len() - 37] == 0x77
                && &event.input[event.input.len() - 36..event.input.len() - 32]
                    == 7u32.to_le_bytes().as_slice()
        })
        .collect();
    assert_eq!(address7_derivations.len(), 1);
    assert_eq!(address7_derivations[0].answer, salt);
    let salt_derivation_calls = trace
        .events
        .iter()
        .filter(|event| {
            event
                .input
                .starts_with(b"aspis:state-only:private-leaf-salt:v1")
        })
        .count();
    assert_eq!(salt_derivation_calls, 2);
    eprintln!(
        "R9_SELECTED_HELPER_PREFIX complete=true total_calls={} salt_derivations={} address7_calls={} retained_salt_leaf_uses=2 typed_c1=1 typed_c2=1",
        trace.total_calls,
        salt_derivation_calls,
        address7_derivations.len(),
    );
}

crates/aspis-prover/tests/rate32_hvzk_ge:
//! Geometry-only probe for mapping Plonky3's prefix-interleaved HVZK-WHIR
//! pipeline to the frozen Aspis rate-1/32, q29, arity-four circle profile.
//!
//! This test deliberately performs no encoding and makes no circle-HVZK
//! theorem claim.  It pins the dimensions that an implementation and an
//! eventual commutative-diagram proof must realize.

const TRACE_VARIABLES: usize = 10;
const FOLD_VARIABLES: usize = 2;
const FOLD_WIDTH: usize = 1 << FOLD_VARIABLES;
const FOLD_BATCHES: usize = 4;
const CODE_SWITCH_ROUNDS: usize = FOLD_BATCHES - 1;
const LOG_INV_RATE: usize = 5;
const ORACLE_QUERIES: usize = 29;
const OOD_SAMPLES: usize = 2;

const TARGET_BITS: usize = 100;
const MASK_UNION_BITS: usize = 3; // ceil(log2(2 * 3 + 2)).
const MASK_LOG_INV_RATE: usize = 5;

// Plonky3's implemented WHIR source claim is quadratic, so ell_zk = 3 is
// sufficient there.  Aspis has two different objects and they must not be
// conflated:
// - four internal arity-four PCS relation sumcheck batches of degree six;
// - one external ten-round statement zerocheck of degree 27.
// A generalized Construction-6.3-style mask would need degree-covering
// message lengths seven and 28 respectively.  Geometry is not that lemma.
const UPSTREAM_PCS_ELL_ZK: usize = 3;
const ASPIS_PCS_DEGREE_6_ELL_ZK: usize = 7;
const ASPIS_EXTERNAL_DEGREE_27_ELL_ZK: usize = 28;
const EXTERNAL_ZEROCHECK_MASK_WIDTH: usize = 10;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct OracleGeometry {
    stage: usize,
    source_message: usize,
    limb_message: usize,
    randomness_per_limb: usize,
    randomness_total: usize,
    leaf_rows: usize,
    padded_dimension: usize,
    limb_degree: usize,
    folded_message: usize,
}

fn oracle_geometry(stage: usize) -> OracleGeometry {
    let source_message = 1usize << (TRACE_VARIABLES - FOLD_VARIABLES * stage);
    let limb_message = source_message / FOLD_WIDTH;
    let leaf_rows = limb_message << LOG_INV_RATE;
    OracleGeometry {
        stage,
        source_message,
        limb_message,
        randomness_per_limb: ORACLE_QUERIES,
        randomness_total: ORACLE_QUERIES * FOLD_WIDTH,
        leaf_rows,
        padded_dimension: limb_message + ORACLE_QUERIES,
        limb_degree: limb_message + ORACLE_QUERIES - 1,
        folded_message: limb_message,
    }
}

fn johnson_bits_per_query(log_inv_rate: usize) -> f64 {
    // Upstream SecurityAssumption::JohnsonBound uses
    //   1 - delta = sqrt(rho) + sqrt(rho)/20.
    let rho = 2f64.powi(-(log_inv_rate as i32));
    -(rho.sqrt() * 1.05).log2()
}

fn johnson_bits_per_query_from_rate(rate: f64) -> f64 {
    -(rate.sqrt() * 1.05).log2()
}

fn johnson_queries(bits: usize, log_inv_rate: usize) -> usize {
    (bits as f64 / johnson_bits_per_query(log_inv_rate)).ceil() as usize
}

fn next_power_of_two(value: usize) -> usize {
    value.next_power_of_two()
}

fn mask_domain(message_len: usize, queries: usize, log_inv_rate: usize) -> usize {
    next_power_of_two(message_len + queries) << log_inv_rate
}

fn min_self_consistent_source_queries(
    message_len: usize,
    domain_size: usize,
    target_bits: f64,
    work_bits: f64,
) -> Option<(usize, f64)> {
    (1..domain_size - message_len).find_map(|queries| {
        let rate = (message_len + queries) as f64 / domain_size as f64;
        let per_query = johnson_bits_per_query_from_rate(rate);
        let bits = queries as f64 * per_query + work_bits;
        (per_query > 0.0 && bits >= target_bits).then_some((queries, bits))
    })
}

#[test]
fn rate32_q29_hvzk_geometry_is_pinned() {
    let oracles = (0..FOLD_BATCHES).map(oracle_geometry).collect::<Vec<_>>();

    assert_eq!(
        oracles,
        vec![
            OracleGeometry {
                stage: 0,
                source_message: 1024,
                limb_message: 256,
                randomness_per_limb: 29,
                randomness_total: 116,
                leaf_rows: 8192,
                padded_dimension: 285,
                limb_degree: 284,
                folded_message: 256,
            },
            OracleGeometry {
                stage: 1,
                source_message: 256,
                limb_message: 64,
                randomness_per_limb: 29,
                randomness_total: 116,
                leaf_rows: 2048,
                padded_dimension: 93,
                limb_degree: 92,
                folded_message: 64,
            },
            OracleGeometry {
                stage: 2,
                source_message: 64,
                limb_message: 16,
                randomness_per_limb: 29,
                randomness_total: 116,
                leaf_rows: 512,
                padded_dimension: 45,
                limb_degree: 44,
                folded_message: 16,
            },
            OracleGeometry {
                stage: 3,
                source_message: 16,
                limb_message: 4,
                randomness_per_limb: 29,
                randomness_total: 116,
                leaf_rows: 128,
                padded_dimension: 33,
                limb_degree: 32,
                folded_message: 4,
            },
        ]
    );

    // The final virtual source is [four message coefficients || 29 random
    // coefficients] evaluated on the last 128-row folded domain.
    assert_eq!(oracles.last().unwrap().folded_message, 4);
    assert_eq!(oracles.last().unwrap().limb_degree, 32);
    assert!(4 + ORACLE_QUERIES < 128);

    // "Rate 1/32" describes the unmasked message rows.  Appending q29
    // randomness raises the actual source-code rates, especially at the
    // terminal.  A soundness ledger must use these padded dimensions.
    assert_eq!(
        oracles
            .iter()
            .map(|oracle| (oracle.padded_dimension, oracle.leaf_rows))
            .collect::<Vec<_>>(),
        vec![(285, 8192), (93, 2048), (45, 512), (33, 128)]
    );
    let final_bits = johnson_bits_per_query_from_rate(33.0 / 128.0) * 29.0;
    assert!((final_bits - 26.314_994_760_451_885).abs() < 1e-12);

    let mask_target = TARGET_BITS + MASK_UNION_BITS;
    let mask_queries = johnson_queries(mask_target, MASK_LOG_INV_RATE);
    assert_eq!(mask_target, 103);
    assert_eq!(mask_queries, 43);

    let switch_message = ORACLE_QUERIES + OOD_SAMPLES;
    assert_eq!(switch_message, 31);

    // Exact upstream PCS-only shape (quadratic source claim).
    assert_eq!(
        mask_domain(UPSTREAM_PCS_ELL_ZK, mask_queries, MASK_LOG_INV_RATE),
        2048
    );
    assert_eq!(
        mask_domain(switch_message, mask_queries, MASK_LOG_INV_RATE),
        4096
    );

    // Aspis internal PCS relation batches are degree six, not degree 27.
    assert_eq!(
        mask_domain(ASPIS_PCS_DEGREE_6_ELL_ZK, mask_queries, MASK_LOG_INV_RATE),
        2048
    );

    // The external ten-round statement zerocheck is a separate width-ten
    // mask group.  It is not one of the seven Hiding-WHIR PCS groups.
    assert_eq!(
        mask_domain(
            ASPIS_EXTERNAL_DEGREE_27_ELL_ZK,
            mask_queries,
            MASK_LOG_INV_RATE
        ),
        4096
    );

    // Four sumcheck groups of width two and three switch groups of width one.
    let group_widths = [2usize, 1, 2, 1, 2, 1, 2];
    assert_eq!(group_widths.len(), 2 * CODE_SWITCH_ROUNDS + 1);
    assert_eq!(group_widths.iter().sum::<usize>(), 11);

    // Hiding-WHIR PCS base-case cleartext OTP reveals: source (4+29), eight
    // internal degree-six sumcheck masks (7+43), and three switch masks
    // (31+43).
    let source_reveal = 4 + ORACLE_QUERIES;
    let pcs_mask_reveals =
        8 * (ASPIS_PCS_DEGREE_6_ELL_ZK + mask_queries) + 3 * (switch_message + mask_queries);
    assert_eq!(source_reveal, 33);
    assert_eq!(pcs_mask_reveals, 622);
    assert_eq!(source_reveal + pcs_mask_reveals, 655);

    // If the external statement zerocheck mask is composed into the same
    // terminal relation, it contributes ten more OTP reveals and one more
    // carried/fresh group pair.  This is a candidate cost, not a theorem.
    let external_mask_reveals =
        EXTERNAL_ZEROCHECK_MASK_WIDTH * (ASPIS_EXTERNAL_DEGREE_27_ELL_ZK + mask_queries);
    assert_eq!(external_mask_reveals, 710);
    assert_eq!(
        source_reveal + pcs_mask_reveals + external_mask_reveals,
        1365
    );

    // Authentication objects in the exact upstream topology:
    // - three code-switch openings of the active source;
    // - source plus fresh-main openings at the base case;
    // - carried plus fresh openings for each of seven mask groups.
    let source_multiproofs = CODE_SWITCH_ROUNDS + 2;
    let mask_multiproofs = 2 * group_widths.len();
    assert_eq!(source_multiproofs, 5);
    assert_eq!(mask_multiproofs, 14);
    assert_eq!(source_multiproofs + mask_multiproofs, 19);

    // Whole-system candidate with the separate external width-ten group.
    assert_eq!(source_multiproofs + mask_multiproofs + 2, 21);

    println!(
        "rate32 HVZK geometry: oracles={oracles:?}; mask_queries={mask_queries}; \
         groups={group_widths:?}; pcs_base_reveals={}; with_external={}; \
         pcs_multiproofs=19; with_external=21",
        source_reveal + pcs_mask_reveals,
        source_reveal + pcs_mask_reveals + external_mask_reveals
    );
}

#[test]
fn mask_rate_tradeoff_is_explicit() {
    let target = TARGET_BITS + MASK_UNION_BITS;
    let switch_message = ORACLE_QUERIES + OOD_SAMPLES;
    let expected = [
        // log inverse rate, Johnson queries, external ell=28 domain, switch domain
        (1usize, 240usize, 1024usize, 1024usize),
        (2, 111, 1024, 1024),
        (3, 73, 1024, 1024),
        (4, 54, 2048, 2048),
        (5, 43, 4096, 4096),
        (6, 36, 4096, 8192),
    ];
    for (log_rate, queries, sumcheck_domain, switch_domain) in expected {
        assert_eq!(johnson_queries(target, log_rate), queries);
        assert_eq!(
            mask_domain(ASPIS_EXTERNAL_DEGREE_27_ELL_ZK, queries, log_rate),
            sumcheck_domain
        );
        assert_eq!(
            mask_domain(switch_message, queries, log_rate),
            switch_domain
        );
    }
}

#[test]
fn source_query_budget_is_self_consistent_or_rejected() {
    let sources = [(256usize, 8192usize), (64, 2048), (16, 512), (4, 128)];

    // The query budget is also the number of appended private coefficients.
    // Re-solving that fixed point (rather than holding randomness at 29)
    // gives the first passing counts below with one 36-bit query grind.
    let at_103 = sources
        .into_iter()
        .map(|(message, domain)| {
            min_self_consistent_source_queries(message, domain, 103.0, 36.0)
                .map(|(queries, _)| queries)
        })
        .collect::<Vec<_>>();
    assert_eq!(at_103, vec![Some(29), Some(32), Some(47), None]);

    let at_104 = sources
        .into_iter()
        .map(|(message, domain)| {
            min_self_consistent_source_queries(message, domain, 104.0, 36.0)
                .map(|(queries, _)| queries)
        })
        .collect::<Vec<_>>();
    assert_eq!(at_104, vec![Some(29), Some(32), Some(48), None]);

    // A 128-point final source cannot reach either target for any legal q:
    // increasing q also raises the code dimension.  Expanding only that
    // source to 512 points yields q40/q41 fixed points.
    assert_eq!(
        min_self_consistent_source_queries(4, 512, 103.0, 36.0).map(|(queries, _)| queries),
        Some(40)
    );
    assert_eq!(
        min_self_consistent_source_queries(4, 512, 104.0, 36.0).map(|(queries, _)| queries),
        Some(41)
    );

    // If 104 bits is desired *after* unioning four source stages, allocate
    // 106 bits per branch.  The first three need q30/q33/q50 and a 512-point
    // final needs q42.
    let branch_106 = [(256usize, 8192usize), (64, 2048), (16, 512), (4, 512)]
        .into_iter()
        .map(|(message, domain)| {
            min_self_consistent_source_queries(message, domain, 106.0, 36.0)
                .map(|(queries, _)| queries)
        })
        .collect::<Vec<_>>();
    assert_eq!(branch_106, vec![Some(30), Some(33), Some(50), Some(42)]);
}

#[test]
fn padded_rate_preserving_code_switch_schedule_restores_q29_bound() {
    let dimensions = [285usize, 93, 45, 33];
    let leaf_domains = [16384usize, 4096, 2048, 2048];
    let unpadded_leaf_domains = [8192usize, 2048, 512, 128];

    for (&dimension, &domain) in dimensions.iter().zip(&leaf_domains) {
        assert!(domain.is_power_of_two());
        assert!(domain >= 32 * dimension);
        let rate = dimension as f64 / domain as f64;
        let bits = ORACLE_QUERIES as f64 * johnson_bits_per_query_from_rate(rate) + 36.0;
        assert!(bits >= 106.0);
    }

    let exact_bits = dimensions
        .iter()
        .zip(&leaf_domains)
        .map(|(&dimension, &domain)| {
            ORACLE_QUERIES as f64
                * johnson_bits_per_query_from_rate(dimension as f64 / domain as f64)
                + 36.0
        })
        .collect::<Vec<_>>();
    let expected = [
        118.713_846_909_893_95,
        113.140_906_730_083,
        113.826_839_594_369_18,
        120.314_994_760_451_88,
    ];
    for (actual, expected) in exact_bits.iter().zip(expected) {
        assert!((*actual - expected).abs() < 1e-12);
    }

    // Four correctly positioned upstream-style grinds can allocate a
    // 106-bit branch target without reusing one nonce across rounds.
    let no_work = exact_bits.iter().map(|bits| bits - 36.0);
    let work = [24.0f64, 29.0, 29.0, 22.0];
    let branch_bits = no_work
        .zip(work)
        .map(|(bits, work)| bits + work)
        .collect::<Vec<_>>();
    assert!(branch_bits.iter().all(|bits| *bits >= 106.0));
    assert!(branch_bits.iter().copied().fold(f64::INFINITY, f64::min) - 2.0 >= 104.0);

    // One four-word interleaved source leaf per row.  The initial genuine
    // circle word and the later line words therefore contain 4*N symbols.
    assert_eq!(
        leaf_domains.map(|domain| FOLD_WIDTH * domain),
        [65536, 16384, 8192, 8192]
    );

    // Binary log-depth deltas of the source leaf trees.  The production
    // radix-four verifier has corresponding level/sibling deltas, but those
    // are measured separately because multiproofs share branches.
    assert_eq!(
        leaf_domains
            .iter()
            .zip(&unpadded_leaf_domains)
            .map(|(&new, &old)| new.ilog2() as i32 - old.ilog2() as i32)
            .collect::<Vec<_>>(),
        vec![1, 1, 2, 4]
    );
}

crates/aspis-prover/tests/spend_release_:
//! Frozen release-proof known-answer tests.
//!
//! The fixture pair `spend_q18_g37_release.{bin,statement.json}` is the exact
//! deployment payload: the finalized production proof and its public v4
//! statement sidecar, ground for the mainnet-target deployment domain. The
//! deployment reuses these bytes without a re-grind, so every transcript
//! label, domain separator, Merkle tag, Poseidon2 constant, params table,
//! statement encoding, proof grammar, and grinding predicate must keep
//! verifying these exact bytes. These tests are the consensus gate for that
//! property: they pin the fixture bytes by SHA-256 and run them through the
//! full production host verifier.

use aspis_prover::HOST_HASH;
use aspis_statement::{AtomicPaymentStatementV4, SpendPublic};
use serde_json::Value;
use sha2::{Digest as _, Sha256};

const RELEASE_PROOF: &[u8] = include_bytes!(concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/fixtures/spend_q18_g37_release.bin"
));
const RELEASE_STATEMENT_SIDECAR: &[u8] = include_bytes!(concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/fixtures/spend_q18_g37_release.statement.json"
));

const RELEASE_PROOF_LEN: usize = 65_407;
const RELEASE_PROOF_SHA256: &str =
    "32eb419e0c5c3ef4fa2db0d32579e88f1207547d8fb010279efeb6c05981b529";
const RELEASE_STATEMENT_SHA256: &str =
    "c35f6152ce4ffbfa6edeba68b4a6d2738e19b1420181c9500ba73f0c717c8699";

// Frozen sidecar schema values for the aspis-spend release epoch.
const RELEASE_STATEMENT_ARTIFACT: &str = "aspis_spend_production_statement";
const RELEASE_STATEMENT_SELECTION_RULE: &str =
    "least GoodSpend selector from three post-final branches";

fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|byte| format!("{byte:02x}")).collect()
}

fn decode_hex_32(value: &str) -> [u8; 32] {
    assert_eq!(value.len(), 64, "expected 64 hex characters");
    let mut decoded = [0u8; 32];
    for (index, output) in decoded.iter_mut().enumerate() {
        *output = u8::from_str_radix(&value[index * 2..index * 2 + 2], 16).unwrap();
    }
    decoded
}

fn release_statement() -> AtomicPaymentStatementV4 {
    let sidecar: Value = serde_json::from_slice(RELEASE_STATEMENT_SIDECAR).unwrap();
    assert_eq!(
        sidecar["artifact"].as_str().unwrap(),
        RELEASE_STATEMENT_ARTIFACT
    );
    assert_eq!(
        sidecar["selection_rule"].as_str().unwrap(),
        RELEASE_STATEMENT_SELECTION_RULE
    );
    assert!(sidecar["witness_independent_public_metadata"]
        .as_bool()
        .unwrap());
    let digest_field = |field: &str| {
        let bytes = decode_hex_32(sidecar[field].as_str().unwrap());
        aspis_statement::decode_digest_canonical(&bytes).unwrap()
    };
    AtomicPaymentStatementV4 {
        pool: decode_hex_32(sidecar["pool_hex"].as_str().unwrap()),
        sequence: sidecar["sequence"].as_u64().unwrap(),
        spend: SpendPublic {
            anchor: digest_field("current_anchor_hex"),
            nullifier: digest_field("nullifier_hex"),
            output_commitment: digest_field("output_commitment_hex"),
            asset_id: aspis_statement::decode_asset_id_canonical(
                u32::try_from(sidecar["asset_id"].as_u64().unwrap()).unwrap(),
            )
            .unwrap(),
            fee: u32::try_from(sidecar["fee"].as_u64().unwrap()).unwrap(),
        },
        output_anchor: digest_field("output_anchor_hex"),
        deployment_domain: decode_hex_32(sidecar["deployment_domain_hex"].as_str().unwrap()),
    }
}

/// The consensus gate: the frozen production proof must verify end-to-end
/// through the full mined-path host verifier against its frozen statement.
#[test]
fn frozen_spend_release_fixture_verifies_end_to_end() {
    assert_eq!(RELEASE_PROOF.len(), RELEASE_PROOF_LEN);
    assert_eq!(hex(&Sha256::digest(RELEASE_PROOF)), RELEASE_PROOF_SHA256);
    assert_eq!(
        hex(&Sha256::digest(RELEASE_STATEMENT_SIDECAR)),
        RELEASE_STATEMENT_SHA256
    );

    let statement = release_statement();
    aspis_statement::state_only_spend::verify_atomic_state_only_spend_v4(
        RELEASE_PROOF,
        &statement,
        HOST_HASH,
        None,
    )
    .expect("frozen release proof must verify through the production host verifier");
}

/// Full release-grade replay: the frozen proof's serialized query selector
/// must equal the least Good selector recomputed from the proof's own prefix
/// under the production (PoW-checked) transcript schedule.
#[test]
#[ignore = "slow exact q3 complete-product replay; run in --release"]
fn frozen_spend_release_fixture_replays_least_good_selector_with_pow() {
    let statement = release_statement();
    let statement_digest =
        aspis_statement::atomic_payment_statement_digest_v4(&statement, HOST_HASH).unwrap();
    let (prefix, suffix) =
        aspis_core::state_only_prefix::StateOnlySpendPrefix::parse_from_proof(RELEASE_PROOF)
            .unwrap();
    assert!(!suffix.is_empty(), "release proof must carry openings");
    let serialized_selector = prefix.query_selector;

    let evaluation = aspis_prover::state_only_good_spend::evaluate_spend_query_candidates_host(
        HOST_HASH,
        &prefix,
        &statement_digest,
    )
    .unwrap();
    println!("{evaluation:#?}");
    assert_eq!(evaluation.selected_selector, Some(serialized_selector));
}

