use aspis_core::field::{M31, QM31};
use aspis_core::state_only_prefix::{
    StateOnlySpendPrefix, STATE_ONLY_PREFIX_LEN, STATE_ONLY_SPEND_D_CLAIMS_LEN,
    STATE_ONLY_SPEND_PREFIX_LEN,
};
use aspis_prover::state_only_candidate_prefix::StateOnlyPowMode;
use aspis_prover::state_only_entropy::StateOnlyAttemptSecrets;
use aspis_prover::state_only_hiding::InMemoryStateOnlyMaskNonceStore;
use aspis_prover::state_only_spend::build_hiding_atomic_state_only_spend_proof_v3;
use aspis_prover::HOST_HASH;
use aspis_statement::atomic_state_only_terminal::{
    atomic_state_only_copy_active_rows_v3, atomic_state_only_copy_inactive_row_masks_v3,
};
use aspis_statement::atomic_state_only_trace::atomic_merkle_root_v3;
use aspis_statement::state_only_spend::{
    verify_atomic_state_only_spend_unmined_for_diagnostics_v4, SpendVerifyError,
};
use aspis_statement::{
    derive_nullifier, derive_owner_key, note_commitment, output_commitment,
    AtomicPaymentStatementV4, Digest, MerklePath, SpendPublic, SpendWitness,
};

fn digest(seed: u32) -> Digest {
    core::array::from_fn(|index| M31(seed + 17 * index as u32))
}

fn fixture() -> (AtomicPaymentStatementV4, SpendWitness) {
    let nullifier_key = digest(101);
    let input_salt = digest(301);
    let output_salt = digest(501);
    let output_owner_key = digest(701);
    let asset_id = M31(17);
    let value = 1_000_000;
    let value_out = 999_999;
    let merkle_path = MerklePath {
        siblings: (0..20).map(|level| digest(1_000 + 31 * level)).collect(),
        index: 0x5_a5a5,
    };
    let witness = SpendWitness {
        nullifier_key,
        input_salt,
        output_salt,
        output_owner_key,
        input_asset_id: asset_id,
        value,
        value_out,
        merkle_path,
    };
    let input = note_commitment(
        &derive_owner_key(&nullifier_key),
        value,
        asset_id,
        &input_salt,
    );
    let output = output_commitment(&output_owner_key, value_out, asset_id, &output_salt);
    let statement = AtomicPaymentStatementV4 {
        pool: [0x5a; 32],
        sequence: 73,
        spend: SpendPublic {
            anchor: atomic_merkle_root_v3(input, &witness.merkle_path).unwrap(),
            nullifier: derive_nullifier(&nullifier_key, &input_salt),
            output_commitment: output,
            asset_id,
            fee: 1,
        },
        output_anchor: atomic_merkle_root_v3(output, &witness.merkle_path).unwrap(),
        deployment_domain: [0x5d; 32],
    };
    (statement, witness)
}

fn rejects(proof: &[u8], statement: &AtomicPaymentStatementV4) {
    assert!(verify_atomic_state_only_spend_unmined_for_diagnostics_v4(
        proof, statement, HOST_HASH, None,
    )
    .is_err());
}

#[test]
fn spend_d_tail_roundtrip_and_corruption_teeth() {
    let (statement, witness) = fixture();
    let attempt =
        StateOnlyAttemptSecrets::deterministic_spend_fixture([0x23; 32], [0x45; 32], [0x67; 32]);
    let mut nonces = InMemoryStateOnlyMaskNonceStore::default();
    let built = build_hiding_atomic_state_only_spend_proof_v3(
        &statement,
        &witness,
        attempt,
        &mut nonces,
        HOST_HASH,
        StateOnlyPowMode::UnminedZero,
        0,
    )
    .unwrap();
    assert!(!built.pow_valid);
    assert_eq!(built.query_selector, 0);
    assert_eq!(built.d.len(), 1024);
    assert_eq!(
        built.bytes.len(),
        STATE_ONLY_SPEND_PREFIX_LEN + built.openings.bytes.len()
    );

    let parsed = StateOnlySpendPrefix::parse_from_proof(&built.bytes)
        .unwrap()
        .0;
    assert_eq!(parsed.d_claims_bytes.len(), STATE_ONLY_SPEND_D_CLAIMS_LEN);
    assert_eq!(parsed.query_selector, 0);
    let verified = verify_atomic_state_only_spend_unmined_for_diagnostics_v4(
        &built.bytes,
        &statement,
        HOST_HASH,
        None,
    )
    .unwrap();
    assert_eq!(verified.relation.d_claims, built.d_claims);
    assert_eq!(verified.schedule.queries, built.schedule.queries);

    let mut active = [false; 1024];
    for &row in atomic_state_only_copy_active_rows_v3() {
        active[usize::from(row)] = true;
    }
    let inactive_sum = built
        .d
        .iter()
        .copied()
        .enumerate()
        .filter(|(row, _)| !active[*row])
        .fold(QM31::ZERO, |sum, value| sum.add(value.1));
    assert_eq!(inactive_sum, QM31::ZERO);
    // D is not one of the 64 deferred binary-copy masks used by H.
    assert_eq!(atomic_state_only_copy_inactive_row_masks_v3().len(), 64);

    let mut changed_d_claim = built.bytes.clone();
    changed_d_claim[STATE_ONLY_PREFIX_LEN] ^= 1;
    rejects(&changed_d_claim, &statement);

    let selector_offset = STATE_ONLY_PREFIX_LEN + STATE_ONLY_SPEND_D_CLAIMS_LEN;
    let mut changed_selector = built.bytes.clone();
    changed_selector[selector_offset] = 1;
    rejects(&changed_selector, &statement);
    let mut invalid_selector = built.bytes.clone();
    invalid_selector[selector_offset] = 3;
    assert!(matches!(
        verify_atomic_state_only_spend_unmined_for_diagnostics_v4(
            &invalid_selector,
            &statement,
            HOST_HASH,
            None,
        ),
        Err(SpendVerifyError::Prefix(_))
    ));

    // First C2 record: u16 count, then the 192-byte value. Mutate D's first
    // symbol at byte 128 without touching H/G.
    let c2_start = STATE_ONLY_SPEND_PREFIX_LEN + built.openings.section_bytes[0];
    let mut changed_d_opening = built.bytes.clone();
    changed_d_opening[c2_start + 2 + 128] ^= 1;
    rejects(&changed_d_opening, &statement);

    let mut trailing = built.bytes.clone();
    trailing.push(0xa5);
    rejects(&trailing, &statement);

    let sha256 = HOST_HASH(&[&built.bytes])
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect::<String>();
    assert_eq!(built.bytes.len(), 64_447);
    assert_eq!(
        sha256,
        "cf3ba127153e726e0e6eb5e4f546b6562a9c57d1ae6ee6a0df6b25aac0863b3b"
    );
    assert_eq!(
        built.openings.section_bytes,
        [18_214, 14_182, 10_150, 8_422, 6_694]
    );
    assert_eq!(built.openings.frontier_nodes, [317, 317, 263, 209, 155]);
    eprintln!("spend_len={} sha256={sha256}", built.bytes.len());
}

#[test]
#[ignore = "slow: builds and verifies one complete unmined proof for each q3 selector"]
fn spend_all_three_selectors_build_and_verify() {
    let (statement, witness) = fixture();
    for selector in 0..3u8 {
        let attempt = StateOnlyAttemptSecrets::deterministic_spend_fixture(
            [0x23; 32], [0x45; 32], [0x67; 32],
        );
        let mut nonces = InMemoryStateOnlyMaskNonceStore::default();
        let built = build_hiding_atomic_state_only_spend_proof_v3(
            &statement,
            &witness,
            attempt,
            &mut nonces,
            HOST_HASH,
            StateOnlyPowMode::UnminedZero,
            selector,
        )
        .unwrap();
        assert_eq!(built.query_selector, selector);

        let (parsed, _) = StateOnlySpendPrefix::parse_from_proof(&built.bytes).unwrap();
        assert_eq!(parsed.query_selector, selector);
        let verified = verify_atomic_state_only_spend_unmined_for_diagnostics_v4(
            &built.bytes,
            &statement,
            HOST_HASH,
            None,
        )
        .unwrap();
        assert_eq!(verified.schedule.queries, built.schedule.queries);
        assert_eq!(verified.schedule.query_count, 18);
    }
}

crates/aspis-prover/tests/stage0.rs:
//! Stage 0 gate tests: prove/verify parity, the four corruption classes,
//! statement binding, framing, and cross-mode behavior.
//!
//! The verifier code exercised here is the identical no_std path the SBF
//! program runs (hash backend swapped), so host acceptance here is the host
//! half of the accept/reject parity gate item.

use aspis_core::params::{PROFILE_CAPACITY, PROFILE_CAPACITY_LR14, PROFILE_JOHNSON};
use aspis_core::proof::{HEADER_LEN, ROUND_COMMITMENT_LEN};
use aspis_core::{verify, FoldPayload, MerkleMode, Profile, VerifyError};
use aspis_prover::{prove, seeded_coeffs, ProveOptions, HOST_HASH};

fn digest(seed: u64) -> [u8; 32] {
    use sha2::Digest;
    let mut h = sha2::Sha256::new();
    h.update(b"aspis-stage0-test");
    h.update(seed.to_le_bytes());
    h.finalize().into()
}

fn prove_one(
    profile: &Profile,
    seed: u64,
    payload: FoldPayload,
    mode: MerkleMode,
) -> (Vec<u8>, [u8; 32]) {
    let coeffs = seeded_coeffs(profile.log_rows, seed + 1);
    let d = digest(seed);
    let proof = prove(
        profile,
        &coeffs,
        &d,
        &ProveOptions {
            fold_payload: payload,
            merkle_mode: mode,
        },
        HOST_HASH,
    );
    (proof, d)
}

#[test]
fn parity_10_of_10_all_variants() {
    for profile in [&PROFILE_CAPACITY, &PROFILE_JOHNSON] {
        for payload in [FoldPayload::RawFibers, FoldPayload::ProofCarriedRoundLocal] {
            for mode in [MerkleMode::MinimalSubtree, MerkleMode::SinglePaths] {
                for seed in 0..10 {
                    let (proof, d) = prove_one(profile, seed, payload, mode);
                    assert_eq!(
                        verify(&proof, &d, HOST_HASH),
                        Ok(()),
                        "profile {} payload {:?} mode {:?} seed {}",
                        profile.name,
                        payload,
                        mode,
                        seed
                    );
                }
            }
        }
    }
}

#[test]
fn statement_sized_profile_lr14() {
    let (proof, d) = prove_one(
        &PROFILE_CAPACITY_LR14,
        7,
        FoldPayload::RawFibers,
        MerkleMode::MinimalSubtree,
    );
    assert_eq!(verify(&proof, &d, HOST_HASH), Ok(()));
}

#[test]
fn radix4_minimal_subtree_roundtrip_and_frontier_corruption() {
    let profile = &PROFILE_CAPACITY;
    let (radix4_proof, d) = prove_one(
        profile,
        11,
        FoldPayload::RawFibers,
        MerkleMode::Radix4MinimalSubtree,
    );
    assert_eq!(verify(&radix4_proof, &d, HOST_HASH), Ok(()));

    let (binary_proof, _) = prove_one(
        profile,
        11,
        FoldPayload::RawFibers,
        MerkleMode::MinimalSubtree,
    );
    assert_ne!(
        &radix4_proof[HEADER_LEN..HEADER_LEN + 32],
        &binary_proof[HEADER_LEN..HEADER_LEN + 32],
        "radix-4 commitment must be domain-separated from the binary tree"
    );

    let body = HEADER_LEN
        + profile.num_rounds() as usize * ROUND_COMMITMENT_LEN
        + profile.final_poly_len() as usize * 16
        + 8;
    let unique_count = u16::from_le_bytes(radix4_proof[body..body + 2].try_into().unwrap());
    let node_count_offset = body + 2 + usize::from(unique_count) * 32;
    let node_count = u32::from_le_bytes(
        radix4_proof[node_count_offset..node_count_offset + 4]
            .try_into()
            .unwrap(),
    );
    assert!(node_count > 0);
    let corrupted = corrupt_at(&radix4_proof, node_count_offset + 4);
    assert!(matches!(
        verify(&corrupted, &d, HOST_HASH),
        Err(VerifyError::MerkleMismatch { layer: 0 })
    ));
}

fn corrupt_at(proof: &[u8], offset: usize) -> Vec<u8> {
    let mut v = proof.to_vec();
    v[offset] ^= 1;
    v
}

#[test]
fn corruption_class_1_root() {
    let (proof, d) = prove_one(
        &PROFILE_CAPACITY,
        0,
        FoldPayload::RawFibers,
        MerkleMode::MinimalSubtree,
    );
    let bad = corrupt_at(&proof, HEADER_LEN + 5);
    assert!(verify(&bad, &d, HOST_HASH).is_err());
}

#[test]
fn corruption_class_2_fold_payload() {
    let profile = &PROFILE_CAPACITY;
    let (proof, d) = prove_one(
        profile,
        0,
        FoldPayload::RawFibers,
        MerkleMode::MinimalSubtree,
    );
    let body = HEADER_LEN
        + profile.num_rounds() as usize * ROUND_COMMITMENT_LEN
        + profile.final_poly_len() as usize * 16
        + 8;
    // inside layer 0's first opened fiber (skip the u16 unique count)
    let bad = corrupt_at(&proof, body + 2 + 3);
    assert!(verify(&bad, &d, HOST_HASH).is_err());
}

#[test]
fn corruption_class_3_final_poly() {
    let profile = &PROFILE_CAPACITY;
    let (proof, d) = prove_one(
        profile,
        0,
        FoldPayload::RawFibers,
        MerkleMode::MinimalSubtree,
    );
    let final_off = HEADER_LEN + profile.num_rounds() as usize * ROUND_COMMITMENT_LEN;
    let bad = corrupt_at(&proof, final_off + 1);
    assert!(verify(&bad, &d, HOST_HASH).is_err());
}

#[test]
fn corruption_class_4_grinding() {
    let profile = &PROFILE_CAPACITY;
    let (proof, d) = prove_one(
        profile,
        0,
        FoldPayload::RawFibers,
        MerkleMode::MinimalSubtree,
    );
    let nonce_off = HEADER_LEN
        + profile.num_rounds() as usize * ROUND_COMMITMENT_LEN
        + profile.final_poly_len() as usize * 16;
    let bad = corrupt_at(&proof, nonce_off);
    let outcome = verify(&bad, &d, HOST_HASH);
    assert!(matches!(
        outcome,
        Err(VerifyError::GrindingFailed) | Err(VerifyError::BadLength)
    ));
}

#[test]
fn statement_digest_binding() {
    let (proof, _) = prove_one(
        &PROFILE_CAPACITY,
        0,
        FoldPayload::RawFibers,
        MerkleMode::MinimalSubtree,
    );
    assert!(verify(&proof, &digest(999), HOST_HASH).is_err());
}

#[test]
fn framing_rejects() {
    let (proof, d) = prove_one(
        &PROFILE_CAPACITY,
        0,
        FoldPayload::RawFibers,
        MerkleMode::MinimalSubtree,
    );
    let mut extended = proof.clone();
    extended.push(0);
    assert_eq!(
        verify(&extended, &d, HOST_HASH),
        Err(VerifyError::TrailingBytes)
    );
    assert!(verify(&proof[..proof.len() - 1], &d, HOST_HASH).is_err());
    assert!(verify(&[], &d, HOST_HASH).is_err());
}

#[test]
fn mode_flag_replay_rejects() {
    // A proof built for one packaging must not verify under a flipped header
    // flag: the header is transcript-absorbed, so all challenges shift.
    let (proof, d) = prove_one(
        &PROFILE_CAPACITY,
        0,
        FoldPayload::RawFibers,
        MerkleMode::MinimalSubtree,
    );
    let mut flipped = proof.clone();
    flipped[12] = MerkleMode::SinglePaths as u8; // merkle_mode header byte
    assert!(verify(&flipped, &d, HOST_HASH).is_err());
    let mut flipped = proof;
    flipped[11] = FoldPayload::ProofCarriedRoundLocal as u8;
    assert!(verify(&flipped, &d, HOST_HASH).is_err());
}

#[test]
fn profile_swap_rejects() {
    // capacity proof presented under the johnson profile id
    let (proof, d) = prove_one(
        &PROFILE_CAPACITY,
        0,
        FoldPayload::RawFibers,
        MerkleMode::MinimalSubtree,
    );
    let mut swapped = proof;
    swapped[5] = PROFILE_JOHNSON.id;
    assert!(verify(&swapped, &d, HOST_HASH).is_err());
}

#[test]
fn degree_overflow_rejects() {
    // Commit a polynomial of degree >= 2^log_rows by evaluating with one
    // extra coefficient folded into the honest pipeline: simplest honest
    // check at this stage is that a final-poly with the wrong length framing
    // rejects; the full false-statement adversarial corpus is a Stage 1
    // deliverable (design section 8.2).
    let profile = &PROFILE_CAPACITY;
    let (proof, d) = prove_one(
        profile,
        3,
        FoldPayload::RawFibers,
        MerkleMode::MinimalSubtree,
    );
    // strip the last final-poly coefficient and splice the sections back
    let final_off = HEADER_LEN + profile.num_rounds() as usize * ROUND_COMMITMENT_LEN;
    let final_len = profile.final_poly_len() as usize * 16;
    let mut shortened = Vec::new();
    shortened.extend_from_slice(&proof[..final_off]);
    shortened.extend_from_slice(&proof[final_off..final_off + final_len - 16]);
    shortened.extend_from_slice(&proof[final_off + final_len..]);
    assert!(verify(&shortened, &d, HOST_HASH).is_err());
}

crates/aspis-prover/tests/stage1_claim.r:
//! Stage 1 queue item 2: (z, v) evaluation-claim binding + challenge-order
//! tests (soundness-note §2 and appendix).
//!
//! What these tests DO establish at this revision: the claim is a
//! transcript-absorbed public input, so claim mix-and-match, flag mismatch,
//! and absorption-order attacks all reject.
//!
//! The interleaved relation sumcheck now also enforces w(z) = v against the
//! explicit final polynomial; false claims reject at the first boundary.

use aspis_core::params::PROFILE_CAPACITY_LR10_Q36_G16 as PROFILE;
use aspis_core::{verify_with_claim, EvaluationClaim, VerifyError};
use aspis_prover::{
    multilinear_eval, prove, prove_with_claim, prove_with_gamma_before_claims_for_tests,
    seeded_coeffs,
};

fn digest(seed: u64) -> [u8; 32] {
    use sha2::Digest;
    let mut h = sha2::Sha256::new();
    h.update(b"aspis-stage1-claim-test");
    h.update(seed.to_le_bytes());
    h.finalize().into()
}

fn options() -> aspis_prover::ProveOptions {
    aspis_prover::ProveOptions {
        fold_payload: aspis_core::FoldPayload::RawFibers,
        merkle_mode: aspis_core::MerkleMode::MinimalSubtree,
    }
}

fn honest_claim(coeffs: &[aspis_core::field::M31], seed: u64) -> EvaluationClaim {
    // deterministic pseudo-random point
    let z: Vec<aspis_core::field::QM31> = (0..PROFILE.log_rows as u64)
        .map(|i| {
            let x = seed
                .wrapping_mul(31)
                .wrapping_add(i)
                .wrapping_mul(0x9E37_79B9) as u32;
            aspis_core::field::QM31::from_cm31(aspis_core::field::CM31::from_m31(
                aspis_core::field::M31(x & 0x7fff_fffe),
            ))
        })
        .collect();
    let v = multilinear_eval(coeffs, &z);
    EvaluationClaim { z, v }
}

#[test]
fn claim_roundtrip_accepts() {
    let coeffs = seeded_coeffs(PROFILE.log_rows, 42);
    let d = digest(0);
    let claim = honest_claim(&coeffs, 7);
    let proof = prove_with_claim(
        &PROFILE,
        &coeffs,
        &d,
        &claim,
        &options(),
        aspis_prover::HOST_HASH,
    );
    assert_eq!(
        verify_with_claim(&proof, &d, Some(&claim), aspis_prover::HOST_HASH),
        Ok(())
    );
}

#[test]
fn claim_mix_and_match_rejects() {
    let coeffs = seeded_coeffs(PROFILE.log_rows, 42);
    let d = digest(0);
    let claim = honest_claim(&coeffs, 7);
    let proof = prove_with_claim(
        &PROFILE,
        &coeffs,
        &d,
        &claim,
        &options(),
        aspis_prover::HOST_HASH,
    );

    // different point
    let other = honest_claim(&coeffs, 8);
    assert!(verify_with_claim(&proof, &d, Some(&other), aspis_prover::HOST_HASH).is_err());

    // same point, perturbed value
    let mut wrong_v = claim.clone();
    wrong_v.v = wrong_v.v.add(aspis_core::field::QM31::ONE);
    assert!(verify_with_claim(&proof, &d, Some(&wrong_v), aspis_prover::HOST_HASH).is_err());
}

#[test]
fn claim_flag_mismatch_rejects() {
    let coeffs = seeded_coeffs(PROFILE.log_rows, 42);
    let d = digest(0);
    let claim = honest_claim(&coeffs, 7);

    // claim-carrying proof verified without a claim
    let proof = prove_with_claim(
        &PROFILE,
        &coeffs,
        &d,
        &claim,
        &options(),
        aspis_prover::HOST_HASH,
    );
    assert_eq!(
        verify_with_claim(&proof, &d, None, aspis_prover::HOST_HASH),
        Err(VerifyError::ClaimMissing)
    );

    // claim-less proof verified with a claim
    let plain = prove(&PROFILE, &coeffs, &d, &options(), aspis_prover::HOST_HASH);
    assert_eq!(
        verify_with_claim(&plain, &d, Some(&claim), aspis_prover::HOST_HASH),
        Err(VerifyError::ClaimUnexpected)
    );
}

#[test]
fn claim_shape_rejects() {
    let coeffs = seeded_coeffs(PROFILE.log_rows, 42);
    let d = digest(0);
    let claim = honest_claim(&coeffs, 7);
    let proof = prove_with_claim(
        &PROFILE,
        &coeffs,
        &d,
        &claim,
        &options(),
        aspis_prover::HOST_HASH,
    );
    let mut short = claim.clone();
    short.z.pop();
    assert_eq!(
        verify_with_claim(&proof, &d, Some(&short), aspis_prover::HOST_HASH),
        Err(VerifyError::ClaimShape)
    );
}

#[test]
fn gamma_before_claims_attack_rejects() {
    // A prover that squeezes gamma after C2 but before absorbing the main and
    // helper evaluations derives a self-consistent broken transcript. The
    // canonical verifier must reject it; stage1_ordering additionally proves
    // this vector's teeth against the matching weakened verifier.
    let coeffs = seeded_coeffs(PROFILE.log_rows, 42);
    let d = digest(0);
    let claim = honest_claim(&coeffs, 7);
    let misordered = prove_with_gamma_before_claims_for_tests(
        &PROFILE,
        &coeffs,
        &d,
        &claim,
        &options(),
        aspis_prover::HOST_HASH,
    );
    assert!(verify_with_claim(&misordered, &d, Some(&claim), aspis_prover::HOST_HASH).is_err());
}

#[test]
fn false_claim_rejects() {
