#[test]
fn coordinate_factored_qm31_packing_is_a_terminal_binding_negative_tooth() {
    for (_, qm31_ranks) in diagonal_ranks::<36>(14, 1, 0x514d_3331_5231_365a, true)
        .into_iter()
        .chain(diagonal_ranks::<29>(15, 1, 0x514d_3331_5233_325a, true))
