                );
            }
            let delta_values = terminal_values(&delta, &prefix[..cut]);
            let difference = delta_values
                .iter()
                .zip(&zero_values[cut])
                .map(|(left, right)| left.sub(*right))
                .collect::<Vec<_>>();
            assert_eq!(
                r15_compact(&r15_interpolate(&difference)),
                target,
                "cut {cut}, target {target_index}"
            );
        }
    }
}

