crates/aspis-r1-cost-probe/examples/proo:
//! UNPROVED CANDIDATE. Proof-size test S1: exact stored bytes of three
//! layouts on the saved fixtures' actual query sets, plus the worst-case
//! node-count bound. usage: proof_size_s1 <fixture-dir>... (each holding
//! r1-s2-proof.bin and r1-s2-public-asf8.bin)
use aspis_core::{digest::LegacyHashFn, r0::merkle, state_only_private_merkle::private_leaf_hash_with_digest};
use aspis_prover::HOST_HASH;
use aspis_r1_cost_probe::{
    compact,
    multiproof::{self, Arity},
    r1_semantic,
    verifier::{self, Prepared, View, INITIAL_QUERY_BYTES},
};
use std::collections::HashMap;

type D = [u8; 32];

fn sha(parts: &[&[u8]]) -> D {
    HOST_HASH(parts)
}

/// Shipped per-query layout offsets (private-leaf-salts).
const C1_PATH: usize = 672;
const C2_PATH: usize = 672 + 1344;
const F_VALUES: usize = INITIAL_QUERY_BYTES;
const F_SALT: usize = F_VALUES + 128;
const F_PATH: usize = F_SALT + 32;

struct TreeOpen {
    leaves: Vec<(u32, D)>,
    nodes: HashMap<(u32, u32), D>,
}
impl TreeOpen {
    fn new() -> Self {
        Self { leaves: Vec::new(), nodes: HashMap::new() }
    }
    /// Record one shipped eight-way path for leaf `u`.
    fn add(&mut self, u: u32, leaf: D, path: &[u8]) {
        self.leaves.push((u, leaf));
        let mut index = u;
        for d in 0..6u32 {
            let slot = index % 8;
            let mut j = 0;
            for s in 0..8u32 {
                if s == slot {
                    continue;
                }
                let at = (d as usize) * 224 + j * 32;
                let digest: D = path[at..at + 32].try_into().unwrap();
                self.nodes.insert((d, index / 8 * 8 + s), digest);
                j += 1;
            }
            index /= 8;
        }
    }
}

/// Distinct sorted (index, leaf) of one batch; panics on inconsistent duplicates.
fn batch(leaves: &[(u32, D)]) -> (Vec<u32>, Vec<D>) {
    let mut idx: Vec<u32> = leaves.iter().map(|x| x.0).collect();
    let mut val: Vec<D> = leaves.iter().map(|x| x.1).collect();
    let n = multiproof::sort_dedup(&mut idx, &mut val).expect("consistent batch");
    idx.truncate(n);
    val.truncate(n);
    (idx, val)
}

fn main() {
    assert!(!cfg!(debug_assertions), "release build required");
    let hash = LegacyHashFn(HOST_HASH);
    let args: Vec<String> = std::env::args().skip(1).collect();
    // Synthetic binary tree, used only to exercise the binary encoder/verifier
    // walk on each fixture's index sets (node counts depend on indices only).
    let synthetic_leaves: Vec<D> = (0..1u32 << 18).map(|i| sha(&[b"s1-synthetic-leaf", &i.to_le_bytes()])).collect();
    let synthetic = multiproof::BinaryTree::new(hash, synthetic_leaves.clone()).unwrap();
    let mut fixtures = Vec::new();
    for dir in &args {
        let proof = std::fs::read(format!("{dir}/r1-s2-proof.bin")).unwrap();
        let public_bytes = std::fs::read(format!("{dir}/r1-s2-public-asf8.bin")).unwrap();
        let statement = aspis_statement::pool_v1::decode_pool_v1_pair_forest_terminal_statement_v1(&public_bytes).unwrap();
        let public = statement.semantic_public();
        // Shipped verifier accepts the fixture (control).
        let checkpoint = verifier::tx1(public, &public_bytes, &proof, compact::SPLIT, hash, None).unwrap();
        verifier::tx2(&public_bytes, &proof, &checkpoint, hash, None).unwrap();
        let v = View::parse(&proof).unwrap();
        let sem = r1_semantic::verify(public, v.semantic, hash).unwrap();
        let mut g = [aspis_core::field::WideExact::ZERO; 29];
        let p = Prepared::new(&sem, &v, hash, &mut g).unwrap();
        let queries = p.queries;

        // Layout A: compact only (shipped per-query paths kept).
        let mut a = proof[..verifier::HEADER].to_vec();
        compact::compact_semantic(v.semantic, &mut a).unwrap();
        compact::compact_values(v.y1, &mut a).unwrap();
        let tail_start = verifier::HEADER + verifier::SEMANTIC_BYTES + 29 * 32;
        a.extend_from_slice(&proof[tail_start..]);
        // Decoder round trip back to the shipped bytes.
        let mut back = proof[..verifier::HEADER].to_vec();
        let mut sem_l = vec![0u8; compact::LOGICAL_SEMANTIC];
        compact::expand_semantic(&a[compact::OFF_SEMANTIC..compact::OFF_Y1], &mut sem_l).unwrap();
        let mut y1_l = vec![0u8; compact::LOGICAL_Y1];
        compact::expand_values(&a[compact::OFF_Y1..compact::OFF_INACTIVE], &mut y1_l).unwrap();
        back.extend_from_slice(&sem_l);
        back.extend_from_slice(&y1_l);
        back.extend_from_slice(&a[compact::OFF_INACTIVE..]);
        assert_eq!(back, proof, "compact codec round trip");

        // Per-tree leaves and shipped paths.
        let mut trees = [TreeOpen::new(), TreeOpen::new(), TreeOpen::new()];
        for (i, &u) in queries.iter().enumerate() {
            let q = v.query(i);
            let c1 = private_leaf_hash_with_digest(hash, merkle::C1_TAG, &q[..480], q[608..640].try_into().unwrap());
            let c2 = private_leaf_hash_with_digest(hash, merkle::C2_TAG, &q[480..608], q[640..672].try_into().unwrap());
            let f = private_leaf_hash_with_digest(hash, 0x72, &q[F_VALUES..F_SALT], q[F_SALT..F_PATH].try_into().unwrap());
            trees[0].add(u, c1, &q[C1_PATH..C2_PATH]);
            trees[1].add(u, c2, &q[C2_PATH..INITIAL_QUERY_BYTES]);
            trees[2].add(u / 4, f, &q[F_PATH..]);
        }
        let roots = [p.roots[0], p.roots[1], *v.folded_root.unwrap()];
        // Layout B (eight-way multiproofs, real nodes from the shipped paths)
        // and layout C (binary counts, walk checked on the synthetic tree).
        let mut eight = [[0usize; 3]; 2];
        let mut two = [[0usize; 3]; 2];
        let mut distinct = [[0usize; 3]; 2];
        let mut b_nodes = Vec::new();
        for (bi, range) in [(0usize, 0..compact::SPLIT), (1, compact::SPLIT..22)] {
            for t in 0..3 {
                let (idx, val) = batch(&trees[t].leaves[range.clone()]);
                distinct[bi][t] = idx.len();
                let nodes = multiproof::generate(Arity::Eight, &idx, |l, i| trees[t].nodes[&(l, i)]).unwrap();
                assert!(multiproof::verify(hash, Arity::Eight, &roots[t], &idx, &val, &nodes), "eight-way multiproof");
                eight[bi][t] = nodes.len() / 32;
                b_nodes.extend_from_slice(&nodes);
                let bin = synthetic.multiproof(&idx).unwrap();
                let syn: Vec<D> = idx.iter().map(|&i| synthetic_leaves[i as usize]).collect();
                assert!(multiproof::verify(hash, Arity::Two, &synthetic.root(), &idx, &syn, &bin));
                two[bi][t] = bin.len() / 32;
                assert_eq!(two[bi][t], multiproof::node_count(Arity::Two, &idx).unwrap());
                assert!(two[bi][t] <= compact::SLOT_NODES[3 * bi + t]);
            }
        }
        let b_len = compact::FIXED + b_nodes.len();
        let e: usize = eight.iter().flatten().sum();
        let n2: usize = two.iter().flatten().sum();
        let c_len = compact::FIXED + 32 * n2;
        let folded_duplicates = 22 - distinct[0][2] - distinct[1][2];
        fixtures.push(serde_json::json!({
            "fixture": dir,
            "shipped_bytes": proof.len(),
            "queries": queries.to_vec(),
            "folded_duplicate_indices": folded_duplicates,
            "layout_compact_only_bytes": a.len(),
            "layout_eight_way_multiproof_compact_bytes": b_len,
            "eight_way_nodes": {"batchA_c1_c2_folded": eight[0], "batchB_c1_c2_folded": eight[1], "total": e},
            "layout_binary_multiproof_compact_variable_bytes": c_len,
            "layout_binary_multiproof_compact_padded_bytes": compact::PROOF_BYTES,
            "binary_nodes": {"batchA_c1_c2_folded": two[0], "batchB_c1_c2_folded": two[1], "total": n2},
        }));
    }

    // Worst case. Bound: nodes(I) = sum_{l=1}^{L-1} n_l + w*n_L - n_0 for the
    // binary/eight-way walk (w = arity, L levels), with n_l <= min(n_0,
    // capacity_l); maximal at n_0 = |batch| distinct leaves. Exhibited by
    // bit-reversed index sets, and checked against random sets.
    let spread = |k: u32, bits: u32| -> Vec<u32> {
        let mut v: Vec<u32> = (0..k).map(|j| j.reverse_bits() >> (32 - bits)).collect();
        v.sort();
        v
    };
    let bound = |a: Arity, k: usize, bits: u32| -> usize {
        // capacity of level l (in arity-steps) inside the first 2^bits leaves
        let levels = a.levels();
        let mut n = vec![0usize; levels as usize + 1];
        for l in 0..=levels {
            let cap_bits = bits as i64 - (l * a.bits()) as i64;
            n[l as usize] = if cap_bits <= 0 { 1 } else { k.min(1 << cap_bits) };
        }
        let mut s = 0;
        for l in 0..levels as usize {
            s += a.width() * n[l + 1] - n[l];
        }
        s
    };
    let mut worst = serde_json::Map::new();
    for (name, a) in [("binary", Arity::Two), ("eight_way", Arity::Eight)] {
        let mut total = 0;
        let mut rows = Vec::new();
        for (k, bits, tree) in [(10, 18, "C1 A"), (10, 18, "C2 A"), (10, 16, "folded A"), (12, 18, "C1 B"), (12, 18, "C2 B"), (12, 16, "folded B")] {
            let b = bound(a, k as usize, bits);
            assert_eq!(multiproof::node_count(a, &spread(k, bits)), Some(b), "{name} {tree} attained");
            total += b;
            rows.push(serde_json::json!({"slot": tree, "leaves": k, "domain_bits": bits, "bound_nodes": b}));
        }
        // Random index sets never exceed the bound.
        let mut ctr = 0u64;
        let mut max_seen = 0;
        for _ in 0..20000 {
            let mut sum = 0;
            for (k, bits) in [(10u32, 18u32), (10, 18), (10, 16), (12, 18), (12, 18), (12, 16)] {
                let mut set = Vec::new();
                while set.len() < k as usize {
                    let r = sha(&[b"s1-random", &ctr.to_le_bytes()]);
                    ctr += 1;
                    let x = u32::from_le_bytes(r[..4].try_into().unwrap()) >> (32 - bits);
                    set.push(x);
                }
                set.sort();
                set.dedup();
                sum += multiproof::node_count(a, &set).unwrap();
            }
            max_seen = max_seen.max(sum);
        }
        assert!(max_seen <= total);
        worst.insert(name.into(), serde_json::json!({
            "slots": rows, "bound_nodes": total, "bound_bytes": compact::FIXED + 32 * total,
            "random_sets_checked": 20000, "random_max_nodes": max_seen,
        }));
    }
    let out = serde_json::json!({
        "fixed_bytes_before_nodes": compact::FIXED,
        "candidate_padded_fixed_length_bytes": compact::PROOF_BYTES,
        "slot_nodes": compact::SLOT_NODES,
        "fixtures": fixtures,
        "worst_case": worst,
    });
    println!("{}", serde_json::to_string_pretty(&out).unwrap());
}

//! UNPROVED. Proof-size teeth (S2 measurement 5), re-pointed at the adopted
//! build (PREREG-PROOF-SIZE-2): the default prover's output on the
//! deterministic R0 fixture is accepted by the default verifier (and the
//! dense verifier), and every pre-registered mutation is rejected. The
//! eight-way control is a saved eight-way fixture (no eight-way prover exists
//! in a prover build any more).
use aspis_core::{digest::LegacyHashFn, Digest32, HashFn};
use aspis_prover::HOST_HASH;
use aspis_r1_cost_probe::{
    compact, prover,
    transport::Variant,
    verifier::{self, candidate, Error},
};

fn main() {
    assert!(!cfg!(debug_assertions), "release build required");
    let raw: HashFn = HOST_HASH;
    let hash = LegacyHashFn(raw);
    let fixture = aspis_prover::r0_fixture::prepare(false);
    let public = aspis_statement::pool_v1::encode_pool_v1_pair_forest_terminal_statement_v1(&fixture.statement).unwrap();
    let seed = raw(&[b"UNPROVED:R1:proof-size-s2", &public]);
    let start = std::time::Instant::now();
    let (proof, _) = prover::prove_masked_fixture(fixture.public(), &fixture.compiled, Variant::S2, raw, &seed).unwrap();
    let prove_seconds = start.elapsed().as_secs_f64();
    assert_eq!(proof.len(), compact::PROOF_BYTES);
    assert_eq!(proof.len(), verifier::PROOF_BYTES);
    aspis_r1_cost_probe::dense::verify(fixture.public(), &proof, raw).expect("dense verifier accepts");
    // Eight-way control: a saved retired-format S2 proof (124,343 bytes).
    let shipped: &[u8] = include_bytes!(concat!(env!("CARGO_MANIFEST_DIR"),
        "/../../docs/research/100bit-spend-path-20261013/evidence/p3-private-leaf-salts-20261013/p3-pool-13/transfer-1023-os-task/r1-s2-proof.bin"));
    assert_eq!(shipped.len(), 124_343);

    // `candidate::*` are the default `verifier::*` entrypoints (re-exports).
    let tx1 = |p: &[u8]| candidate::tx1(fixture.public(), &public, p, compact::SPLIT, hash, None);
    let ck = tx1(&proof).expect("candidate stage 1 accepts");
    assert_eq!(ck.len(), verifier::checkpoint_size(Variant::S2));
    candidate::tx2_authenticated(&public, &proof, &ck, hash, None).expect("candidate stage 2 accepts");
    candidate::tx2(&public, &proof, &ck, hash, None).expect("candidate strict stage 2 accepts");
    // Both stages, on a proof mutated so that stage 1 still passes.
    let both = |p: &[u8]| -> Result<(), Error> {
        let c = tx1(p)?;
        candidate::tx2_authenticated(&public, p, &c, hash, None)
    };
    let used = |s: usize| -> usize {
        // real nodes in slot s = slot size minus trailing zero 32-byte words
        let slot = &proof[compact::slot_offset(s)..compact::slot_offset(s + 1)];
        slot.chunks(32).rposition(|c| c.iter().any(|&b| b != 0)).map_or(0, |i| i + 1)
    };
    let counts: Vec<usize> = (0..6).map(used).collect();
    let mut results = Vec::new();
    let mut expect_any = |name: &str, got: Result<(), Error>, want: Option<Error>| {
        match want {
            Some(w) => assert_eq!(got, Err(w), "{name}"),
            None => assert!(got.is_err(), "{name}"),
        }
        results.push(serde_json::json!({"mutation": name, "result": format!("{:?}", got)}));
    };
    macro_rules! expect {
        ($n:expr, $g:expr, $w:expr) => { expect_any(&$n, $g, Some($w)) };
    }
    let flip = |at: usize| {
        let mut p = proof.clone();
        p[at] ^= 1;
        p
    };
    // 1. Wrong sibling hash, batch A (stage 1) and batch B (stage 2).
    for s in 0..6 {
        let at = compact::slot_offset(s) + 32 * (counts[s] / 2) + 7;
        expect!(&format!("wrong sibling, slot {s}"), both(&flip(at)), Error::Merkle);
    }
    // 2. Missing node: last real node of a slot removed (the slot then holds
    // one node fewer, the rest is padding).
    for s in [0, 2, 3, 5] {
        let mut p = proof.clone();
        let at = compact::slot_offset(s) + 32 * (counts[s] - 1);
        p[at..at + 32].fill(0);
        expect!(&format!("missing node, slot {s}"), both(&p), Error::Merkle);
    }
    // 3. Extra node: a non-zero word right after the real nodes.
    for s in [0, 4] {
        let mut p = proof.clone();
        let at = compact::slot_offset(s) + 32 * counts[s];
        p[at..at + 32].fill(0xa5);
        expect!(&format!("extra node, slot {s}"), both(&p), Error::Parse);
    }
    // Any non-zero padding byte, last byte of the last slot.
    expect!("non-zero padding byte", both(&flip(compact::PROOF_BYTES - 1)), Error::Parse);
    // 4. Duplicated / misordered leaf index: openings swapped between two
    // queries of one batch (each leaf then sits at another index), and one
    // opening duplicated over another.
    let open = |i: usize| compact::OFF_OPENINGS + i * compact::OPENING;
    for (i, j, batch) in [(0, 1, "A"), (11, 20, "B")] {
        let mut p = proof.clone();
        let (a, b) = (open(i), open(j));
        let qi = proof[a..a + compact::OPENING].to_vec();
        let qj = proof[b..b + compact::OPENING].to_vec();
        p[a..a + compact::OPENING].copy_from_slice(&qj);
        p[b..b + compact::OPENING].copy_from_slice(&qi);
        expect!(&format!("misordered leaves {i}<->{j}, batch {batch}"), both(&p), Error::Merkle);
        let mut d = proof.clone();
        d[b..b + compact::OPENING].copy_from_slice(&qi);
        expect!(&format!("duplicated leaf {i}->{j}, batch {batch}"), both(&d), Error::Merkle);
    }
    // 5. Non-zero byte where a compact field's zero half is implied.
    // (a) The stored form has no high half: a proof that carries a semantic
    // value in its 32-byte form with a non-zero high byte has the wrong
    // length and fails the strict parse.
    let mut wide = proof[..compact::OFF_SEMANTIC + 32 + 5 * 15 + 32].to_vec();
    let rest = &proof[wide.len()..];
    wide.extend_from_slice(&rest[..16]);
    wide.extend_from_slice(&[1u8; 16]);
    wide.extend_from_slice(&rest[16..]);
    expect!("semantic value stored wide with non-zero high half", tx1(&wide).map(|_| ()), Error::Parse);
    // (b) Same for y1, keeping the total length (last padding word dropped).
    let mut y = proof[..compact::OFF_Y1 + 16].to_vec();
    y.extend_from_slice(&[1u8; 16]);
    y.extend_from_slice(&proof[compact::OFF_Y1 + 16..compact::PROOF_BYTES - 16]);
    assert_eq!(y.len(), compact::PROOF_BYTES);
    expect_any("y1 value with injected high half (length kept)", tx1(&y).map(|_| ()), None);
    // (c) The decoder rebuilds zero halves: a logical record with a non-zero
    // high byte has no compact encoding (encoder refuses).
    let mut logical = vec![0u8; compact::LOGICAL_SEMANTIC];
    compact::expand_semantic(&proof[compact::OFF_SEMANTIC..compact::OFF_Y1], &mut logical).unwrap();
    let last_value = compact::LOGICAL_SEMANTIC - 32;
    let mut forged = logical.clone();
    forged[last_value + 20] = 1;
    assert_eq!(compact::compact_semantic(&forged, &mut Vec::new()), Err(compact::CodecError::NonZeroHigh));
    let encoder_refusal = serde_json::json!({"mutation": "encoder: logical semantic value with non-zero high half", "result": "Err(NonZeroHigh)"});
    // (d) Non-canonical compact limb (2^31-1) in a semantic row and in y1.
    // The semantic value is rejected by the shipped Prefix::parse after the
    // rebuild (Semantic); the y1 value by the strict scan (Parse).
    for (name, at, want) in [("non-canonical compact semantic limb", compact::OFF_SEMANTIC + 32 + 5 * 15 + 32, Error::Semantic), ("non-canonical compact y1 limb", compact::OFF_Y1, Error::Parse)] {
        let mut p = proof.clone();
        p[at..at + 4].copy_from_slice(&0x7fff_ffffu32.to_le_bytes());
        expect!(name, tx1(&p).map(|_| ()), want);
    }
    // 6. Checkpoint over the expanded rather than the compact bytes.
    let mut expanded = proof[..compact::HEADER].to_vec();
    expanded.extend_from_slice(&logical);
    let mut y1l = vec![0u8; compact::LOGICAL_Y1];
    compact::expand_values(&proof[compact::OFF_Y1..compact::OFF_INACTIVE], &mut y1l).unwrap();
    expanded.extend_from_slice(&y1l);
    expanded.extend_from_slice(&proof[compact::OFF_INACTIVE..]);
    let mut bad_ck = ck.clone();
    bad_ck[16..48].copy_from_slice(&hash.digest(&[&expanded]));
    let end = bad_ck.len() - 32;
    let sum = hash.digest(&[b"UNPROVED:R1:checkpoint", &bad_ck[..end]]);
    bad_ck[end..].copy_from_slice(&sum);
    expect!("checkpoint over expanded bytes", candidate::tx2_authenticated(&public, &proof, &bad_ck, hash, None), Error::Checkpoint);
    expect!("expanded bytes presented as the proof", candidate::tx2_authenticated(&public, &expanded, &bad_ck, hash, None), Error::Parse);
    // Other strictness: wrong split, shipped proof to candidate, candidate to
    // shipped, a semantic byte changed after stage 1.
    expect!("stage 1 split 11", candidate::tx1(fixture.public(), &public, &proof, 11, hash, None).map(|_| ()), Error::Parse);
    expect!("eight-way proof to adopted verifier", tx1(shipped).map(|_| ()), Error::Parse);
    expect!("eight-way proof to adopted verifier, split 11", verifier::tx1(fixture.public(), &public, shipped, 11, hash, None).map(|_| ()), Error::Parse);
    expect!("proof changed after stage 1", candidate::tx2_authenticated(&public, &flip(compact::OFF_SEMANTIC + 40), &ck, hash, None), Error::Checkpoint);
    results.push(encoder_refusal);
    let out = serde_json::json!({
        "candidate_bytes": proof.len(), "shipped_bytes": shipped.len(),
        "slot_real_nodes": counts, "slot_capacity": compact::SLOT_NODES,
        "candidate_prove_seconds": prove_seconds,
        "accepted": ["default tx1", "default tx2_authenticated", "default tx2 strict", "dense"],
        "rejections": results,
    });
    println!("{}", serde_json::to_string_pretty(&out).unwrap());
}

crates/aspis-r1-cost-probe/examples/r1p_:
//! LOG D38.3 measurement gate (optimized build only): the prover-side P_R1
//! check on fresh OS-entropy attempts, and the capped retry loop end to end.
//!
//! Part 1: `attempts` independent single attempts (`prove_masked_attempt`,
//! fresh OS secrets, one durable ledger). Each records its wall time, the
//! check's duration split and the one-bit verdict; accepted proofs are
//! verified (strict tx1+tx2 and dense). No challenge, root or failing
//! conjunct is recorded or printed.
//! Part 2: one `prove_masked_retrying` call, timed, then verified.
use aspis_core::digest::LegacyHashFn;
use aspis_prover::{state_only_entropy::{DurableStateOnlyMaskNonceStore, StateOnlyAttemptSecrets}, HOST_HASH};
use aspis_r1_cost_probe::{prover, transport::Variant, verifier, dense};
use serde_json::json;
use std::{path::Path, time::Instant};

fn statement_bytes(fixture: &aspis_prover::r0_fixture::Fixture) -> Vec<u8> {
    aspis_statement::pool_v1::encode_pool_v1_pair_forest_terminal_statement_v1(&fixture.statement).unwrap().to_vec()
}

fn verify(fixture: &aspis_prover::r0_fixture::Fixture, public_bytes: &[u8], proof: &[u8]) -> bool {
    let Ok(cp) = verifier::tx1(fixture.public(), public_bytes, proof, verifier::SPLIT, LegacyHashFn(HOST_HASH), None) else { return false };
    verifier::tx2(public_bytes, proof, &cp, LegacyHashFn(HOST_HASH), None).is_ok()
        && dense::verify(fixture.public(), proof, HOST_HASH).is_ok()
}

fn stats(v: &[f64]) -> serde_json::Value {
    let mut s = v.to_vec();
    s.sort_by(|a, b| a.partial_cmp(b).unwrap());
    let n = s.len().max(1) as f64;
    json!({"n": s.len(), "mean": s.iter().sum::<f64>() / n, "min": s.first(), "median": s.get(s.len() / 2), "max": s.last()})
}

fn main() {
    assert!(!cfg!(debug_assertions), "run this gate with an optimized profile");
    let args: Vec<_> = std::env::args().collect();
    assert_eq!(args.len(), 4, "usage: r1p_retry_gate <attempts> <fresh-ledger-dir> <out.json>");
    let attempts: usize = args[1].parse().unwrap();
    let ledger_path = Path::new(&args[2]);
    assert!(!ledger_path.exists(), "nonce ledger must be fresh");
    let out = Path::new(&args[3]);
    assert!(!out.exists(), "refusing to overwrite {}", out.display());
    let fixture = aspis_prover::r0_fixture::prepare(false);
    let public_bytes = statement_bytes(&fixture);
    let mut ledger = DurableStateOnlyMaskNonceStore::open(ledger_path).unwrap();
    let _ = prover::take_check_times();

    let mut rows = vec![];
    let (mut wall, mut wall_acc, mut check, mut emit, mut build, mut public_data, mut extracted) = (vec![], vec![], vec![], vec![], vec![], vec![], vec![]);
    let mut accepted = 0usize;
    let mut verified = 0usize;
    for i in 0..attempts {
        let secrets = StateOnlyAttemptSecrets::generate().expect("OS attempt entropy");
        let t = Instant::now();
        let result = prover::prove_masked_attempt(fixture.public(), &fixture.compiled, Variant::S2, HOST_HASH, secrets, &mut ledger);
        let w = t.elapsed().as_secs_f64();
        let times = prover::take_check_times();
        assert_eq!(times.len(), 1, "exactly one P_R1 check per attempt");
        let tm = times[0];
        let total_check = tm.public_data + tm.emit + tm.builders + tm.check;
        let ok = match &result {
            Ok(_) => true,
            Err(verifier::Error::Rejected) => false,
            Err(e) => panic!("attempt {i}: unexpected error {e:?}"),
        };
        let ver = if let Ok((proof, _)) = &result { verify(&fixture, &public_bytes, proof) } else { false };
        if ok {
            accepted += 1;
            wall_acc.push(w);
        }
        if ver {
            verified += 1;
        }
        wall.push(w);
        check.push(total_check);
        public_data.push(tm.public_data);
        emit.push(tm.emit);
        build.push(tm.builders);
        extracted.push(tm.check);
        rows.push(json!({"attempt": i, "accepted": ok, "verified": ver, "attempt_wall_seconds": w,
            "check_seconds": total_check, "check_public_data_seconds": tm.public_data, "check_emit_seconds": tm.emit,
            "check_convert_and_extracted_builders_seconds": tm.builders, "check_extracted_checker_seconds": tm.check,
            "attempt_wall_without_check_seconds": w - total_check}));
        println!("R1P_ATTEMPT {i} accepted={ok} verified={ver} wall={w:.3} check={total_check:.3}");
    }
    let no_check: Vec<f64> = wall.iter().zip(&check).map(|(w, c)| w - c).collect();

    let _ = prover::take_check_times();
    let t = Instant::now();
    let retried = prover::prove_masked_retrying(fixture.public(), &fixture.compiled, Variant::S2, HOST_HASH, &mut ledger).expect("retry loop publishes");
    let retry_wall = t.elapsed().as_secs_f64();
    let retry_checks = prover::take_check_times().len();
    let retry_verified = verify(&fixture, &public_bytes, &retried.proof);
    drop(ledger);
    let reservations = std::fs::read_dir(ledger_path).unwrap().count();
    let report = json!({
        "label": "UNPROVED R1 cost probe: D38.3 prover-side P_R1 check (extracted C3 checker) and retry loop",
        "variant": "S2 (R1)",
        "fixture": "transfer (r0_fixture::prepare(false))",
        "entropy_source": "OS-generated StateOnlyAttemptSecrets, one per attempt",
        "attempts": attempts,
        "accepted": accepted,
        "accept_rate": accepted as f64 / attempts as f64,
        "accepted_proofs_verified_strict_and_dense": verified,
        "attempt_wall_seconds": stats(&wall),
        "accepted_attempt_wall_seconds": stats(&wall_acc),
        "attempt_wall_without_check_seconds": stats(&no_check),
        "check_seconds": stats(&check),
        "check_public_data_seconds": stats(&public_data),
        "check_emit_seconds": stats(&emit),
        "check_convert_and_extracted_builders_seconds": stats(&build),
        "check_extracted_checker_seconds": stats(&extracted),
        "retry_loop": {"wall_seconds": retry_wall, "attempts": retried.attempts, "checks": retry_checks, "verified_strict_and_dense": retry_verified},
        "durable_nonce_reservations": reservations,
        "logged": "verdict bits and durations only; no challenge, root, certificate or failing conjunct",
        "per_attempt": rows,
    });
    std::fs::write(out, serde_json::to_vec_pretty(&report).unwrap()).unwrap();
    println!("R1P_DONE accepted={accepted}/{attempts} verified={verified} retry_attempts={} retry_wall={retry_wall:.3}", retried.attempts);
}

//! G-sim gate (LOG D44.3; optimized build only): the explicit simulator simE
//! from the public statement alone, timed per step, and each simulated proof
//! verified (strict tx1+tx2 and dense) under its programmed oracle. Seeds come
//! from the OS; nothing from the simulated transcripts is recorded.
use aspis_r1_cost_probe::sim;
use serde_json::json;
use std::path::Path;

fn main() {
    assert!(!cfg!(debug_assertions), "run this gate with an optimized profile");
    let args: Vec<_> = std::env::args().collect();
    assert_eq!(args.len(), 3, "usage: r1p_sim_gate <runs> <out.json>");
    let runs: usize = args[1].parse().unwrap();
    let out = Path::new(&args[2]);
    assert!(!out.exists(), "refusing to overwrite {}", out.display());
    let fixture = aspis_prover::r0_fixture::prepare(false);
    let public = fixture.public();
    let mut rows = vec![];
    for i in 0..runs {
        let mut seed = [0u8; 32];
        getrandom::fill(&mut seed).expect("OS entropy");
        let t = std::time::Instant::now();
        let s = sim::sim_e(public, seed).expect("simulated view");
        let wall = t.elapsed().as_secs_f64();
        let v = std::time::Instant::now();
        let (ok, programmed, read) = sim::verify_programmed(public, &s.proof, s.table.clone());
        let verify_seconds = v.elapsed().as_secs_f64();
        let public_bytes=public.public_bytes().unwrap();
        let real_strict_rejected=aspis_r1_cost_probe::verifier::tx1(public,&public_bytes,&s.proof,
            aspis_r1_cost_probe::verifier::SPLIT,aspis_core::digest::LegacyHashFn(aspis_prover::HOST_HASH),None).is_err();
        let real_dense_rejected=aspis_r1_cost_probe::dense::verify(public,&s.proof,aspis_prover::HOST_HASH).is_err();
        let tm = s.times;
        rows.push(json!({"run": i, "attempts": s.attempts, "wall_seconds": wall,
            "draw_seconds": tm.draw, "p_r1_seconds": tm.p_r1, "tape_seconds": tm.tape,
            "semantic_seconds": tm.semantic, "opening_seconds": tm.opening, "program_and_serialise_seconds": tm.program,
            "simulation_without_p_r1_seconds": wall - tm.p_r1,
            "real_hash_strict_rejected":real_strict_rejected,"real_hash_dense_rejected":real_dense_rejected,
            "proof_bytes": s.proof.len(), "transcript_reads": s.transcript_reads, "commitment_reads": s.commitment_reads,
            "programmed_addresses": programmed, "programmed_addresses_read_by_verifier": read,
            "verified_strict_and_dense_under_programmed_oracle": ok.is_ok(), "verify_seconds": verify_seconds}));
        println!("R1SIM_RUN {i} attempts={} wall={wall:.3} p_r1={:.3} semantic={:.3} opening={:.3} program={:.3} verified={} programmed={programmed} read={read}",
            s.attempts, tm.p_r1, tm.semantic, tm.opening, tm.program, ok.is_ok());
        assert!(real_strict_rejected && real_dense_rejected,"real hash must reject");
        assert_eq!(programmed,read,"all programmed addresses must be read");
        assert_eq!(programmed,s.transcript_reads+s.commitment_reads);
        assert_eq!(s.proof.len(),aspis_r1_cost_probe::compact::PROOF_BYTES);
        assert!(ok.is_ok(), "simulated proof must verify under its programmed oracle");
    }
    let report = json!({
        "label": "UNPROVED R1 cost probe: G-sim, explicit simulator simE (R0Z/RefPayload) in the ideal game fsR1.ideal (R1Z/GamesR1)",
        "variant": "S2 (R1)", "statement": "transfer fixture public statement (r0_fixture::prepare(false)); no compiled trace or witness is passed to simE",
        "seed_source": "OS entropy, one 32-byte seed per run", "runs": rows,
    });
    std::fs::write(out, serde_json::to_vec_pretty(&report).unwrap()).unwrap();
}

crates/aspis-r1-cost-probe/examples/read:
//! R1 privacy read budget (r1p-readbudget, 2026-10-19): instrumented count of
//! the hash calls of one prover attempt, eight-way (shipped) and binary
//! (compact-binary candidate), on the deterministic R0 fixture. Each call is
//! classified by its first input slice (domain string, or the one/two-byte
//! node/leaf tag) and counted twice: calls, and distinct digests (= distinct
//! addresses, SHA-256 being collision-free in practice). Prints JSON.
use aspis_core::HashFn;
use aspis_prover::HOST_HASH;
use aspis_r1_cost_probe::{prover, transport::Variant};
use std::collections::{BTreeMap, HashSet};
use std::sync::Mutex;

struct Class {
    calls: u64,
    distinct: HashSet<[u8; 32]>,
}
static LOG: Mutex<BTreeMap<String, Class>> = Mutex::new(BTreeMap::new());

fn class_of(parts: &[&[u8]]) -> String {
    let first = parts.first().copied().unwrap_or(&[]);
    let printable = !first.is_empty() && first.iter().all(|&b| (0x20..0x7f).contains(&b));
    if printable {
        return String::from_utf8_lossy(first).into_owned();
    }
    if first.len() <= 2 {
        return format!("tag:{}", first.iter().map(|b| format!("{b:02x}")).collect::<String>());
    }
    // Transcript sponge steps: 32-byte state followed by a short opcode.
    match parts.get(1) {
        Some(op) if op.len() <= 2 => format!(
            "state{}+op:{}",
            first.len(),
            op.iter().map(|b| format!("{b:02x}")).next().unwrap_or_default()
        ),
        _ => format!("raw{}", first.len()),
    }
}

fn counting(parts: &[&[u8]]) -> [u8; 32] {
    let out = HOST_HASH(parts);
    let key = class_of(parts);
    let mut log = LOG.lock().unwrap();
    let c = log.entry(key).or_insert_with(|| Class { calls: 0, distinct: HashSet::new() });
    c.calls += 1;
    c.distinct.insert(out);
    out
}

fn take() -> serde_json::Value {
    let mut log = LOG.lock().unwrap();
    let mut classes = serde_json::Map::new();
    let (mut calls, mut distinct) = (0u64, 0u64);
    for (k, c) in log.iter() {
        calls += c.calls;
        distinct += c.distinct.len() as u64;
        classes.insert(k.clone(), serde_json::json!({"calls": c.calls, "distinct": c.distinct.len()}));
    }
    log.clear();
    serde_json::json!({"total_calls": calls, "total_distinct": distinct, "classes": classes})
}

fn main() {
    assert!(!cfg!(debug_assertions), "release build required");
    let raw: HashFn = HOST_HASH;
    let hash: HashFn = counting;
    let fixture = aspis_prover::r0_fixture::prepare(false);
    let public = aspis_statement::pool_v1::encode_pool_v1_pair_forest_terminal_statement_v1(&fixture.statement).unwrap();
    let seed = raw(&[b"UNPROVED:R1:r1p-readbudget-count", &public]);
    take();
    let (eight, _) = prover::prove_masked_fixture(fixture.public(), &fixture.compiled, Variant::S2, hash, &seed).unwrap();
    let e = take();
    let (binary, _) = prover::prove_masked_fixture_candidate(fixture.public(), &fixture.compiled, hash, &seed).unwrap();
    let b = take();
    println!(
        "{}",
        serde_json::to_string_pretty(&serde_json::json!({
            "fixture": "aspis_prover::r0_fixture::prepare(false), Variant::S2",
            "eight_way": {"proof_bytes": eight.len(), "count": e},
            "binary": {"proof_bytes": binary.len(), "count": b},
        }))
        .unwrap()
    );
}

crates/aspis-r1-cost-probe/examples/seco:
//! UNPROVED finite source-correspondence gate for the second-fold lift.
//!
//! This example checks exact finite-domain identities and two dense E-valued
//! messages. It is a measurement of the implementation's finite-domain
//! correspondence, not a universal decoder theorem or a security argument.

use aspis_core::{
    field::{CM31, M31, QM31, WideExact as E},
    r0::{basis, domain::FibreIndex, encoder, CodeField, FinalMessage},
};
use aspis_r1_cost_probe::{fast_domain, verifier};

const PARENTS: usize = 1 << 16;
const QUARTER: M31 = M31(536_870_912);

fn double(x: M31) -> M31 {
    x.mul(x).double().sub(M31::ONE)
}

fn wide(limbs: [u32; 8]) -> E {
    let cm = |a, b| CM31::new(M31(a), M31(b));
    E::new(
        QM31 { c0: cm(limbs[0], limbs[1]), c1: cm(limbs[2], limbs[3]) },
        QM31 { c0: cm(limbs[4], limbs[5]), c1: cm(limbs[6], limbs[7]) },
    )
}

fn dense_message(which: u32) -> FinalMessage<E> {
    core::array::from_fn(|i| {
        let b = which * 4096 + i as u32 * 8;
        wide([b + 1, b + 2, b + 3, b + 4, b + 5, b + 6, b + 7, b + 8])
    })
}

fn linear_folded_coefficients(q: &FinalMessage<E>, alpha: E) -> [E; 64] {
    let a2 = alpha.mul(alpha);
    let a3 = a2.mul(alpha);
    core::array::from_fn(|d| {
        q[4 * d]
            .add(alpha.mul(q[4 * d + 1]))
            .add(a2.mul(q[4 * d + 2]))
            .add(a3.mul(q[4 * d + 3]))
    })
}

fn dense_source_and_fold_checks() -> (usize, usize, usize) {
    let alpha_zero = E::ZERO;
    let alpha_wide = wide([7, 11, 13, 17, 19, 23, 29, 31]);
    let mut source_eval_count = 0usize;
    let mut lift_count = 0usize;
    let mut fold_count = 0usize;

    for which in 0..2 {
        let q = dense_message(which);

        // The four depth-2 stride messages each have 64 nonzero coefficients.
        // Evaluate them with the public R0 final encoder at T4(x_v), then
        // compare their four-channel reconstruction with the public source
        // exact final encoder at every one of the four child indices.
        let strides: [[E; 64]; 4] = core::array::from_fn(|s| {
            core::array::from_fn(|d| q[4 * d + s])
        });
        for v in 0..PARENTS {
            let u0 = FibreIndex::new(4 * v).expect("checked domain index");
            let x = fast_domain::line_node(u0);
            let t2x = double(x);
            let t4x = double(t2x);
            let hs: [E; 4] = core::array::from_fn(|s| {
                strides[s]
                    .iter()
                    .enumerate()
                    .fold(E::ZERO, |sum, (d, coefficient)| {
                        sum.add(coefficient.mul(E::from_m31(basis::natural(d, t4x))))
                    })
            });
            let child_x = [
                x,
                x.neg(),
                fast_domain::line_node(FibreIndex::new(4 * v + 2).unwrap()),
                fast_domain::line_node(FibreIndex::new(4 * v + 3).unwrap()),
            ];
            let child_values = [
                hs[0].add(E::from_m31(child_x[0]).mul(hs[1]))
                    .add(E::from_m31(double(child_x[0])).mul(hs[2]))
                    .add(E::from_m31(child_x[0].mul(double(child_x[0]))).mul(hs[3])),
                hs[0].add(E::from_m31(child_x[1]).mul(hs[1]))
                    .add(E::from_m31(double(child_x[1])).mul(hs[2]))
                    .add(E::from_m31(child_x[1].mul(double(child_x[1]))).mul(hs[3])),
                hs[0].add(E::from_m31(child_x[2]).mul(hs[1]))
                    .add(E::from_m31(double(child_x[2])).mul(hs[2]))
                    .add(E::from_m31(child_x[2].mul(double(child_x[2]))).mul(hs[3])),
                hs[0].add(E::from_m31(child_x[3]).mul(hs[1]))
                    .add(E::from_m31(double(child_x[3])).mul(hs[2]))
                    .add(E::from_m31(child_x[3].mul(double(child_x[3]))).mul(hs[3])),
            ];

            let mut actual = [E::ZERO; 4];
            for s in 0..4 {
                actual[s] = encoder::exact_final_encoder(
                    &q,
                    FibreIndex::new(4 * v + s).expect("checked child index"),
                );
                source_eval_count += 1;
                assert_eq!(actual[s], child_values[s], "stride lift mismatch at q={which}, parent={v}, slot={s}");
                lift_count += 1;
            }

            for alpha in [alpha_zero, alpha_wide] {
                let folded = linear_folded_coefficients(&q, alpha);
                let mut native = E::ZERO;
                for (d, coefficient) in folded.iter().enumerate() {
                    native = native.add(coefficient.mul(E::from_m31(basis::natural(d, t4x))));
                }
                let projected = verifier::line_fold(alpha, v, actual);
                assert_eq!(projected, native, "line fold mismatch at q={which}, parent={v}");
                fold_count += 1;
            }
        }
    }
    (source_eval_count, lift_count, fold_count)
}

fn domain_identities() -> (usize, usize, usize) {
    let mut geometry_count = 0usize;
    let mut basis_count = 0usize;
    let mut projection_count = 0usize;
    for v in 0..PARENTS {
        let p = 4 * v;
        let nodes = core::array::from_fn::<_, 4, _>(|s| {
            fast_domain::line_node(FibreIndex::new(p + s).expect("checked domain index"))
        });
        let [x, nx, ny, y] = nodes;
        assert_eq!(nx, x.neg(), "second child is not -x at parent {v}");
        assert_eq!(ny, y.neg(), "third child is not -y at parent {v}");
        assert_ne!(x.mul(y).mul(double(x)), M31::ZERO, "x*y*T2(x) is zero at {v}");
        let z = double(x);
        assert_eq!(double(y), z.neg(), "T2(y) != -T2(x) at parent {v}");
        let t4x = double(z);
        for node in nodes {
            assert_eq!(double(double(node)), t4x, "shared T4 node mismatch at parent {v}");
        }
        geometry_count += 1;

        for d in 0..64 {
            let target = basis::natural(d, t4x);
            for node in nodes {
                assert_eq!(basis::natural(4 * d, node), target, "4d lift mismatch at v={v}, d={d}");
                basis_count += 1;
            }
        }

        for j in 0..256 {
            let sum = nodes.iter().fold(M31::ZERO, |acc, node| {
                acc.add(basis::natural(j, *node))
            });
            let projected = sum.mul(QUARTER);
            let expected = if j & 3 == 0 { basis::natural(j, x) } else { M31::ZERO };
            assert_eq!(projected, expected, "four-child projection mismatch at v={v}, j={j}");
            projection_count += 1;
        }
    }
    (geometry_count, basis_count, projection_count)
}

fn main() {
    assert!(!cfg!(debug_assertions), "this gate must run optimized");
    let domain = domain_identities();
    let dense = dense_source_and_fold_checks();
    println!(
        "{{\"label\":\"UNPROVED SECOND-FOLD LIFT GATE\",\"geometry_parents\":{},\"basis_lift_checks\":{},\"projection_checks\":{},\"source_evaluations\":{},\"lift_checks\":{},\"fold_checks\":{},\"all_passed\":true}}",
        domain.0, domain.1, domain.2, dense.0, dense.1, dense.2
    );
}

