//! UNPROVED COST PROBE. Byte-equivalence experiment for the R0 K sampler.
use aspis_core::circle::{secure_ood_circle_point_from_parameter, SecureCirclePoint};
use aspis_core::field::{WideExact, CM31, M31, P, QM31};
pub use aspis_core::r0_transcript::CircleRow;

/// Divide a little-endian word array by P, retaining every quotient word.
/// Dividends are below P * 2^32, so every division fits in u64.
fn qm31_div_pass(mut rank: [u32; 8]) -> ([u32; 8], u32) {
    let mut remainder = 0u64;
    let mut j = 8usize;
    while j > 0 {
        j -= 1;
        let dividend = (remainder << 32) | u64::from(rank[j]);
        rank[j] = (dividend / u64::from(P)) as u32;
        remainder = dividend % u64::from(P);
    }
    (rank, remainder as u32)
}

/// The low four base-P digits already represent rank modulo P^4.
fn qm31_digits(block: &[u8; 32]) -> [u32; 4] {
    let mut rank = [0u32; 8];
    let mut i = 0usize;
    while i < 8 {
        let start = 4 * i;
        rank[i] = u32::from_le_bytes([
            block[start],
            block[start + 1],
            block[start + 2],
            block[start + 3],
        ]);
        i += 1;
    }
    let mut digits = [0u32; 4];
    let mut i = 0usize;
    while i < 4 {
        let (quotient, digit) = qm31_div_pass(rank);
        rank = quotient;
        digits[i] = digit;
        i += 1;
    }
    digits
}

pub fn qm31_sample(block: &[u8; 32]) -> QM31 {
    let digits = qm31_digits(block);
    QM31 {
        c0: CM31::new(M31(digits[0]), M31(digits[1])),
        c1: CM31::new(M31(digits[2]), M31(digits[3])),
    }
}

/// Return the low eight base-P digits of the 256-bit little-endian block and
/// the remaining quotient. This uses eight long divisions by P rather than
/// first reducing the full block with 256 binary steps.
fn low_base_p_digits(block: &[u8; 32]) -> ([u32; 8], u32) {
    let mut quotient: [u32; 8] =
        core::array::from_fn(|i| u32::from_le_bytes(block[4 * i..4 * i + 4].try_into().unwrap()));
    let digits = core::array::from_fn(|_| {
        let mut remainder = 0u64;
        for limb in quotient.iter_mut().rev() {
            let dividend = (remainder << 32) | u64::from(*limb);
            *limb = (dividend / u64::from(P)) as u32;
            remainder = dividend % u64::from(P);
        }
        remainder as u32
    });

    // After eight divisions, the quotient is at most 256 and fits in u32.
    debug_assert!(quotient[1..].iter().all(|&limb| limb == 0));
    debug_assert!(quotient[0] <= 256);
    (digits, quotient[0])
}

fn decode8(digits: [u32; 8]) -> WideExact {
    WideExact::new(
        QM31 {
            c0: CM31::new(M31(digits[0]), M31(digits[1])),
            c1: CM31::new(M31(digits[2]), M31(digits[3])),
        },
        QM31 {
            c0: CM31::new(M31(digits[4]), M31(digits[5])),
            c1: CM31::new(M31(digits[6]), M31(digits[7])),
        },
    )
}

/// Add a small integer to a base-P digit vector. Returns the carry beyond
/// the final digit, which is at most one for the values used by the sampler.
fn add_small_base_p(digits: &mut [u32; 8], mut addend: u32) -> bool {
    for digit in digits {
        let sum = u64::from(*digit) + u64::from(addend);
        *digit = (sum % u64::from(P)) as u32;
        addend = (sum / u64::from(P)) as u32;
    }
    debug_assert!(addend <= 1);
    addend != 0
}

/// `decode8(rank(block) mod P^8)`, byte-for-byte equivalent to the frozen
/// R0 sampler. The repeated divisions directly produce the low eight digits.
pub fn ordinary_sample(block: &[u8; 32]) -> WideExact {
    let (digits, _) = low_base_p_digits(block);
    decode8(digits)
}

/// `decode8((rank(block) mod (P^8 - 1)) + 1)`, byte-for-byte equivalent to
/// the frozen R0 sampler. Since `P^8 ≡ 1 (mod P^8 - 1)`, the high quotient can
/// be added to the low digits before the final increment. A carry past digit
/// seven contributes one more modulo `P^8 - 1`.
pub fn gamma_sample(block: &[u8; 32]) -> WideExact {
    let (mut digits, quotient) = low_base_p_digits(block);
    let wrapped = add_small_base_p(&mut digits, quotient + 1);
    if wrapped {
        let wrapped_again = add_small_base_p(&mut digits, 1);
        debug_assert!(!wrapped_again);
    }
    decode8(digits)
}

pub fn circle_sample(block: &[u8; 32], row: CircleRow) -> SecureCirclePoint {
    secure_ood_circle_point_from_parameter(qm31_sample(block)).unwrap_or_else(|_| {
        aspis_core::transcript::circle_fallback_point(match row {
            CircleRow::First => 0,
            CircleRow::Second => 1,
        })
    })
}

#[cfg(test)]
mod qm31_index_tests {
    use super::*;

    // Preserve the complete pre-refactor implementation as a differential oracle.
    fn old_sample(block: &[u8; 32]) -> QM31 {
        let mut rank: [u32; 8] =
            core::array::from_fn(|i| u32::from_le_bytes(block[4 * i..4 * i + 4].try_into().unwrap()));
        let digits: [u32; 4] = core::array::from_fn(|_| {
            let mut remainder = 0u64;
            for limb in rank.iter_mut().rev() {
                let dividend = (remainder << 32) | u64::from(*limb);
                *limb = (dividend / u64::from(P)) as u32;
                remainder = dividend % u64::from(P);
            }
            remainder as u32
        });
        QM31 {
            c0: CM31::new(M31(digits[0]), M31(digits[1])),
            c1: CM31::new(M31(digits[2]), M31(digits[3])),
        }
    }

    fn old_pass(mut rank: [u32; 8]) -> ([u32; 8], u32) {
        let mut remainder = 0u64;
        for limb in rank.iter_mut().rev() {
            let dividend = (remainder << 32) | u64::from(*limb);
            *limb = (dividend / u64::from(P)) as u32;
            remainder = dividend % u64::from(P);
        }
        (rank, remainder as u32)
    }

    fn check(block: &[u8; 32]) {
        assert_eq!(qm31_sample(block), old_sample(block));
        let digits = qm31_digits(block);
        assert!(digits.iter().all(|&d| d < P));
        let q = qm31_sample(block);
        assert_eq!([q.c0.a.0, q.c0.b.0, q.c1.a.0, q.c1.b.0], digits);
        let mut rank = core::array::from_fn(|i| {
            u32::from_le_bytes(block[4 * i..4 * i + 4].try_into().unwrap())
        });
        for _ in 0..4 {
            let actual = qm31_div_pass(rank);
            assert_eq!(actual, old_pass(rank), "complete quotient and remainder");
            rank = actual.0;
        }
    }

    #[test]
    fn quotient_writeback_and_sampler_match_at_word_boundaries() {
        check(&[0; 32]);
        check(&[0xff; 32]);
        for i in 0..8 {
            for word in [0, 1, P - 1, P, P + 1, u32::MAX] {
                let mut block = [0; 32];
                block[4 * i..4 * i + 4].copy_from_slice(&word.to_le_bytes());
                check(&block);
            }
        }
        for bit in 0..256 {
            let mut block = [0; 32];
            block[bit / 8] = 1 << (bit % 8);
            check(&block);
        }
    }

    #[test]
    fn sampler_matches_independent_u128_base_p_digits() {
        let p = u128::from(P);
        for rank in [0, 1, p - 1, p, p + 1, p * p - 1, p * p, p.pow(4) - 1, p.pow(4)] {
            let mut block = [0; 32];
            block[..16].copy_from_slice(&rank.to_le_bytes());
            let mut remainder = rank;
            let expected = core::array::from_fn(|_| {
                let digit = (remainder % p) as u32;
                remainder /= p;
                digit
            });
            assert_eq!(qm31_digits(&block), expected);
            check(&block);
        }
    }

    #[test]
    fn quotient_writeback_and_sampler_match_deterministic_blocks() {
        let mut state = 0x9e37_79b9_7f4a_7c15u64;
        for _ in 0..4096 {
            let mut block = [0; 32];
            for chunk in block.chunks_exact_mut(8) {
                state = state.wrapping_add(0x9e37_79b9_7f4a_7c15);
                let mut z = state;
                z = (z ^ (z >> 30)).wrapping_mul(0xbf58_476d_1ce4_e5b9);
                z = (z ^ (z >> 27)).wrapping_mul(0x94d0_49bb_1331_11eb);
                z ^= z >> 31;
                chunk.copy_from_slice(&z.to_le_bytes());
            }
            check(&block);
        }
    }
}

//! UNPROVED COST PROBE. S4 semantic equations evaluated in K.
use alloc::boxed::Box;
use aspis_core::{circle::SecureCirclePoint, field::QM31, HashFn};
use aspis_statement::pool_v1::pair_forest_semantic_terminal::r0::Public;
use crate::semantic_wire::{self as wire, Challenges, Error, Prefix, SemanticTranscript};

pub struct Verified {
    pub roots: [[u8; 32]; 2],
    pub challenges: Challenges,
    pub alpha: [QM31; 10],
    pub claims: Box<[[QM31; 29]; 3]>,
    pub before_z1: [QM31; 29],
    pub state_before_z0: [u8; 32],
    pub z: [SecureCirclePoint; 2],
    pub transcript: SemanticTranscript,
    pub round_checks: [[QM31; 3]; 10],
    pub terminal: QM31,
    pub masked_terminal: QM31,
}

pub fn decode<const N: usize>(row: u8, bytes: &[u8]) -> Result<[QM31; N], Error> {
    if bytes.len() != N * 32 { return Err(Error::Length { row }); }
    let mut out = [QM31::ZERO; N];
    for (value, part) in bytes.chunks_exact(32).enumerate() {
        // Parse has already asserted c1 == 0. Retain the assertion in this
        // public helper as well, so callers cannot accidentally truncate E.
        if part[16..].iter().any(|&b| b != 0) { return Err(Error::NonCanonical { row, value }); }
        out[value] = QM31::from_le_bytes(&part[..16]).ok_or(Error::NonCanonical { row, value })?;
    }
    Ok(out)
}

#[inline(never)]
fn claims(prefix: &Prefix<'_>) -> Result<Box<[[QM31; 29]; 3]>, Error> {
    let bytes = prefix.payload(25)?;
    let mut out = aspis_core::r0::heap::uninit::<[[QM31; 29]; 3]>().map_err(|_| Error::Allocation)?;
    unsafe {
        for p in 0..3 {
            out.as_mut_ptr().cast::<[QM31; 29]>().add(p)
                .write(decode::<29>(25, &bytes[p*29*32..(p+1)*29*32])?);
        }
        Ok(out.assume_init())
    }
}

#[inline(never)]
pub fn verify(public: Public<'_>, bytes: &[u8], hash: HashFn) -> Result<Verified, Error> {
    let prefix = Prefix::parse(bytes)?;
    let mut transcript = SemanticTranscript::new(hash, &public.public_bytes().map_err(|_| Error::Public)?, prefix.c1_root)?;
    let challenges = wire::begin(&prefix, &mut transcript)?;
    let mut running = decode::<1>(14, prefix.payload(14)?)?[0];
    let mut alpha = [QM31::ZERO; 10];
    let mut round_checks = [[QM31::ZERO; 3]; 10];
    for round in 0..10 {
        let row = 15 + round as u8;
        let polynomial = decode::<28>(row, prefix.payload(row)?)?;
        let boundary = polynomial.iter().copied().fold(polynomial[0], QM31::add);
        if boundary != running { return Err(Error::Boundary { round }); }
        alpha[round] = transcript.semantic(row, prefix.record(row)?)?;
        let value = polynomial.iter().rev().fold(QM31::ZERO, |a, &c| a.mul(alpha[round]).add(c));
        round_checks[round] = [running, boundary, value];
        running = value;
    }
    let claims = claims(&prefix)?;
    let original_challenges = aspis_core::state_only_prefix::r0::Challenges {
        lambda: challenges.lambda, chi: challenges.chi, theta: challenges.theta,
        zc: challenges.zc, mu: challenges.mu, eta: challenges.eta,
    };
    let terminal = public.terminal_qm31(&claims, &alpha, &original_challenges).map_err(|_| Error::Public)?;
    let mask = aspis_core::state_only_hiding::state_only_selected_mask_value(
        &core::array::from_fn(|i| claims[0][i]),
        &core::array::from_fn(|i| claims[0][16+i]), claims[0][27], &alpha,
    );
    let masked_terminal = mask.add(challenges.eta.mul(terminal));
    if running != masked_terminal { return Err(Error::Terminal); }
    let state_before_z0 = transcript.state();
    let z0 = transcript.challenge_reference_circle_point(25, prefix.record(25)?)?;
    let before_z1 = decode::<29>(26, prefix.payload(26)?)?;
    let z1 = transcript.challenge_reference_circle_point(26, prefix.record(26)?)?;
    if z0 == z1 { return Err(Error::EqualCirclePoints); }
    Ok(Verified { roots: [*prefix.c1_root, prefix.payload(2)?.try_into().unwrap()],
        challenges, alpha, claims, before_z1, state_before_z0, z: [z0,z1], transcript,
        round_checks, terminal, masked_terminal })
}

