crates/aspis-statement/examples/r0_trans:
//! Generate D13's fixed permutation from the authoritative PF inventories.
//! Run with --check to audit the checked-in core pads and full-table KAT.
use aspis_statement::pool_v1::{
    pool_v1_pair_forest_copy_active_rows_v1, pool_v1_pair_forest_relation_free_mask_cells_v1,
};
use sha2::{Digest, Sha256};
use std::{fmt::Write, path::PathBuf};

fn main() {
    let active = pool_v1_pair_forest_copy_active_rows_v1().unwrap();
    let cells = pool_v1_pair_forest_relation_free_mask_cells_v1().unwrap();
    let legal = |r| (0..16).all(|c| cells.iter().any(|x| x.row == r && x.column == c));
    assert!(!active.contains(&1023) && legal(1023));
    // Exact order rule: v8-full-view-zk-20260912/tools/r16_basis_transport.rs:10–63.
    let pads: Vec<u16> = (0..1023)
        .filter(|r| !active.contains(r) && *r != 1014 && legal(*r))
        .take(89)
        .collect();
    assert_eq!(pads.len(), 89);
    let mut inverse = pads.clone();
    inverse.extend((0..1023).filter(|r| !pads.contains(r)));
    inverse.push(1023);
    let mut pi = [0u16; 1024];
    for (coefficient, &row) in inverse.iter().enumerate() {
        pi[usize::from(row)] = coefficient as u16;
    }
    let bytes: Vec<_> = pi.iter().flat_map(|r| r.to_le_bytes()).collect();
    let digest = format!("{:x}", Sha256::digest(&bytes));
    let mut source = String::from(
        "// Generated by aspis-statement/examples/r0_transport_inventory.rs; --check audits it.\n",
    );
    writeln!(source, "pub const PAD_ROWS: [u16; 89] = {pads:?};").unwrap();
    let kat = format!("{{\n  \"rule\": \"D13; historical r16_basis_transport.rs:10-63 order only\",\n  \"encoding\": \"pi[row], 1024 u16 little-endian entries\",\n  \"sha256\": \"{digest}\",\n  \"pads\": {pads:?},\n  \"pi\": {pi:?},\n  \"inverse\": {inverse:?}\n}}\n");
    let root = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../..");
    for (path, expected) in [
        ("crates/aspis-core/src/r0/transport_pads.rs", source),
        ("results/r0-opening-20261009/transport-kat.json", kat),
    ] {
        let path = root.join(path);
        if std::env::args().any(|x| x == "--check") {
            assert_eq!(
                std::fs::read_to_string(&path).unwrap(),
                expected,
                "{}",
                path.display()
            );
        } else {
            std::fs::write(path, expected).unwrap();
        }
    }
    println!("D13: 89 inactive pads legal in all 16 columns; pivot 1023 last; pi sha256={digest}");
}

crates/aspis-statement/examples/search_a:
//! Exhaustively search row-bit bipartitions for the atomic-v3 routing tensor.
//!
//! This is a derivation tool, not verifier code.  A chosen partition must be
//! regenerated into constants and protected by compiled/reference identity
//! tests before it can affect an SBF measurement.

use std::collections::BTreeSet;

use aspis_core::field::M31;
use aspis_statement::atomic_state_only_registry::{
    build_atomic_state_only_registry_v3, AtomicCopyTupleV3, AtomicTupleLimbV3,
};

#[derive(Clone, PartialEq, Eq)]
struct Pattern {
    kinds: [u8; 16],
    columns: [u8; 16],
    scales: [u32; 16],
    offsets: [u32; 16],
}

fn pattern(tuple: AtomicCopyTupleV3) -> Pattern {
    let mut output = Pattern {
        kinds: [0; 16],
        columns: [0; 16],
        scales: [0; 16],
        offsets: [0; 16],
    };
    for (index, limb) in tuple.limbs.into_iter().enumerate() {
        match limb {
            AtomicTupleLimbV3::Zero => {}
            AtomicTupleLimbV3::Constant(value) => {
                output.kinds[index] = 1;
                output.offsets[index] = value.0;
            }
            AtomicTupleLimbV3::AffineCell {
                cell,
                scale,
                offset,
            } => {
                output.kinds[index] = 2;
                output.columns[index] = cell.column;
                output.scales[index] = scale.0;
                output.offsets[index] = offset.0;
            }
        }
    }
    output
}

fn projected_index(row: usize, bit_mask: u16) -> usize {
    let mut output = 0usize;
    for bit in (0..10).rev() {
        if bit_mask & (1 << bit) != 0 {
            output = (output << 1) | ((row >> bit) & 1);
        }
    }
    output
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
struct Score {
    shared_pairs: usize,
    total_rank: usize,
    factor_entries: usize,
    left_factors: usize,
    right_factors: usize,
    low_mask: u16,
}

#[derive(Clone, Copy)]
struct Endpoint {
    row: usize,
    slot: usize,
    pattern: usize,
    tag: M31,
}

fn endpoints() -> (usize, Vec<Endpoint>) {
    let registry = build_atomic_state_only_registry_v3().unwrap();
    let mut patterns = Vec::new();
    for link in &registry.links {
        for tuple in [link.producer, link.consumer] {
            let candidate = pattern(tuple);
            if !patterns.contains(&candidate) {
                patterns.push(candidate);
            }
        }
    }
    let mut producer_arity = [0u8; 1024];
    let mut consumer_arity = [0u8; 1024];
    let mut endpoints = Vec::with_capacity(2 * registry.links.len());
    for link in &registry.links {
        for (tuple, side, arity) in [
            (link.producer, 0usize, &mut producer_arity),
            (link.consumer, 2usize, &mut consumer_arity),
        ] {
            let row = usize::from(tuple.row);
            let slot = side + usize::from(arity[row]);
            arity[row] += 1;
            let pattern = patterns
                .iter()
                .position(|value| *value == pattern(tuple))
                .unwrap();
            endpoints.push(Endpoint {
                row,
                slot,
                pattern,
                tag: link.tag,
            });
        }
    }
    (patterns.len(), endpoints)
}

fn score_partition(pattern_count: usize, endpoints: &[Endpoint], low_mask: u16) -> Score {
    let high_mask = (!low_mask) & 0x03ff;
    let high_len = 1usize << high_mask.count_ones();
    let low_len = 1usize << low_mask.count_ones();
    let matrix_count = 4 * (2 + pattern_count);
    let mut matrices = vec![vec![vec![M31::ZERO; low_len]; high_len]; matrix_count];
    for endpoint in endpoints {
        let high = projected_index(endpoint.row, high_mask);
        let low = projected_index(endpoint.row, low_mask);
        let base = endpoint.slot * (2 + pattern_count);
        matrices[base][high][low] = matrices[base][high][low].add(M31::ONE);
        matrices[base + 1][high][low] = matrices[base + 1][high][low].add(endpoint.tag);
        matrices[base + 2 + endpoint.pattern][high][low] =
            matrices[base + 2 + endpoint.pattern][high][low].add(M31::ONE);
    }

    let mut unique_left = Vec::<Vec<M31>>::new();
    let mut unique_right = Vec::<Vec<M31>>::new();
    let mut pairs = BTreeSet::new();
    let mut total_rank = 0usize;
    for matrix in &mut matrices {
        loop {
            let pivot = (0..high_len).find_map(|row| {
                (0..low_len)
                    .find(|&column| matrix[row][column] != M31::ZERO)
                    .map(|column| (row, column))
            });
            let Some((pivot_row, pivot_column)) = pivot else {
                break;
            };
            let inverse = matrix[pivot_row][pivot_column].inv();
            let left = (0..high_len)
                .map(|row| matrix[row][pivot_column])
                .collect::<Vec<_>>();
            let right = (0..low_len)
                .map(|column| matrix[pivot_row][column].mul(inverse))
                .collect::<Vec<_>>();
            let left_id = unique_left
                .iter()
                .position(|factor| *factor == left)
                .unwrap_or_else(|| {
                    unique_left.push(left.clone());
                    unique_left.len() - 1
                });
            let right_id = unique_right
                .iter()
                .position(|factor| *factor == right)
                .unwrap_or_else(|| {
                    unique_right.push(right.clone());
                    unique_right.len() - 1
                });
            pairs.insert((left_id, right_id));
            total_rank += 1;
            for row in 0..high_len {
                for column in 0..low_len {
                    matrix[row][column] = matrix[row][column].sub(left[row].mul(right[column]));
                }
            }
        }
    }
    let factor_entries = unique_left
        .iter()
        .chain(&unique_right)
        .map(|factor| factor.iter().filter(|&&value| value != M31::ZERO).count())
        .sum();
    Score {
        shared_pairs: pairs.len(),
        total_rank,
        factor_entries,
        left_factors: unique_left.len(),
        right_factors: unique_right.len(),
        low_mask,
    }
}

fn main() {
    let (pattern_count, endpoints) = endpoints();
    let mut scores = Vec::new();
    // Keep both selector tables reasonably small.  The current compiler uses
    // four low bits; five/five and six/four are both viable SBF shapes.
    for low_bits in 3..=7 {
        for low_mask in 1u16..0x03ff {
            if low_mask.count_ones() == low_bits {
                scores.push(score_partition(pattern_count, &endpoints, low_mask));
            }
        }
    }
    scores.sort_unstable();
    println!("best partitions by (shared pairs, rank, entries):");
    for score in scores.iter().take(20) {
        println!("{score:?}");
    }
    for bits in 3..=7 {
        let best_pairs = scores
            .iter()
            .filter(|score| score.low_mask.count_ones() == bits)
            .min()
            .unwrap();
        let best_entries = scores
            .iter()
            .filter(|score| score.low_mask.count_ones() == bits)
            .min_by_key(|score| (score.factor_entries, score.shared_pairs, score.total_rank))
            .unwrap();
        println!("low_bits={bits} best_pairs={best_pairs:?} best_entries={best_entries:?}");
    }
    let current = score_partition(pattern_count, &endpoints, 0x000f);
    println!("current: {current:?}");
}

crates/aspis-statement/examples/v8_intri:
//! Focused V8 gate for the intrinsic per-variable degree of the exact
//! production atomic-v3 unmasked terminal.
//!
//! This is not a new prover or arithmetization. It supplies a concrete family
//! of committed affine column MLEs to the production terminal, restricts each
//! sumcheck variable to `t = 0, 1, ...`, and computes exact forward
//! differences in QM31. Together with the source upper bound of 27, a nonzero
//! 27th difference is an executable lower-bound witness.

use aspis_core::field::{CM31, M31, QM31};
use aspis_statement::atomic_state_only_terminal::{
    atomic_state_only_selected_constraint_composition_compiled_v3,
    atomic_state_only_selected_unmasked_terminal_value_compiled_v3,
};
use aspis_statement::state_only_poseidon::{successor_point, xor12_point};
use aspis_statement::{AtomicPaymentStatementV4, SpendPublic};

const VARIABLES: usize = 10;
const TERMINAL_COLUMNS: usize = 28;
const TERMINAL_POINTS: usize = 3;
const TERMINAL_CLAIMS: usize = TERMINAL_COLUMNS * TERMINAL_POINTS;
const SAMPLES: usize = 31;

fn lift(value: u32) -> QM31 {
    QM31::from_cm31(CM31::from_m31(M31(value)))
}

fn q(seed: u32) -> QM31 {
    QM31 {
        c0: CM31::new(M31(seed * 17 + 1), M31(seed * 17 + 3)),
        c1: CM31::new(M31(seed * 17 + 5), M31(seed * 17 + 7)),
    }
}

/// A literal multilinear committed column. Affine columns are sufficient to
/// expose the degree-25 two-round Poseidon term while keeping the witness
/// construction auditable.
fn affine_column(point: &[QM31; VARIABLES], column: usize, family: u32) -> QM31 {
    point.iter().copied().enumerate().fold(
        q(family + 101 * column as u32 + 1),
        |value, (variable, x)| {
            value.add(x.mul(q(family + 103 * column as u32 + 29 * variable as u32 + 7)))
        },
    )
}

fn claims_at(point: &[QM31; VARIABLES], family: u32) -> [QM31; TERMINAL_CLAIMS] {
    let points = [*point, successor_point(point), xor12_point(point)];
    let mut claims = [QM31::ZERO; TERMINAL_CLAIMS];
    for (point_index, opening_point) in points.iter().enumerate() {
        for column in 0..16 {
            claims[point_index * TERMINAL_COLUMNS + column] =
                affine_column(opening_point, column, family);
        }
    }
    // The unmasked terminal consumes H1 only at z (selected column 26).
    claims[26] = affine_column(point, 31, family + 10_000);
    claims
}

fn statement(family: u32) -> AtomicPaymentStatementV4 {
    let digest = |offset: u32| core::array::from_fn(|lane| M31(offset + lane as u32 + 1));
    AtomicPaymentStatementV4 {
        pool: [0x51; 32],
        sequence: 73,
        spend: SpendPublic {
            anchor: digest(family + 100),
            nullifier: digest(family + 200),
            output_commitment: digest(family + 300),
            asset_id: M31(family + 401),
            fee: 17,
        },
        output_anchor: digest(family + 500),
        deployment_domain: [0x71; 32],
    }
}

fn terminal_at(variable: usize, t: u32, family: u32) -> QM31 {
    let mut point: [QM31; VARIABLES] =
        core::array::from_fn(|coordinate| q(family + 701 + 37 * coordinate as u32));
    point[variable] = lift(t);
    let claims = claims_at(&point, family);
    let zerocheck_point =
        core::array::from_fn(|coordinate| q(family + 2_003 + 41 * coordinate as u32));
    atomic_state_only_selected_unmasked_terminal_value_compiled_v3(
        &statement(family),
        &claims,
        &point,
        q(family + 3_001),
        q(family + 3_101),
        q(family + 3_201),
        &zerocheck_point,
        q(family + 3_301),
    )
    .expect("valid focused degree-audit fixture")
}

fn composition_at(variable: usize, t: u32, family: u32) -> QM31 {
    let mut point: [QM31; VARIABLES] =
        core::array::from_fn(|coordinate| q(family + 701 + 37 * coordinate as u32));
    point[variable] = lift(t);
    atomic_state_only_selected_constraint_composition_compiled_v3(
        &statement(family),
        &claims_at(&point, family),
        &point,
        q(family + 3_001),
        q(family + 3_101),
        q(family + 3_201),
    )
    .expect("valid focused composition degree-audit fixture")
}

fn forward_difference(mut values: Vec<QM31>, order: usize) -> Vec<QM31> {
    for _ in 0..order {
        values = values.windows(2).map(|pair| pair[1].sub(pair[0])).collect();
    }
    values
}

fn measured_degree(values: &[QM31]) -> usize {
    (0..values.len())
        .rev()
        .find(|&order| {
            forward_difference(values.to_vec(), order)
                .iter()
                .any(|value| !value.is_zero())
        })
        .unwrap_or(0)
}

fn hex(value: QM31) -> String {
    let mut bytes = [0u8; 16];
    value.write_le_bytes(&mut bytes);
    bytes.iter().map(|byte| format!("{byte:02x}")).collect()
}

fn main() {
    let families = [11u32, 97, 211];
    let mut maximum_composition = 0usize;
    let mut maximum_terminal = 0usize;
    println!("fixture=exact-production-atomic-v3-unmasked-terminal");
    println!("algorithm=exact-QM31-forward-differences-over-t=0..30");
    for family in families {
        for variable in 0..VARIABLES {
            let composition_values = (0..SAMPLES as u32)
                .map(|t| composition_at(variable, t, family))
                .collect::<Vec<_>>();
            let composition_degree = measured_degree(&composition_values);
            maximum_composition = maximum_composition.max(composition_degree);
            let composition_delta26 = forward_difference(composition_values.clone(), 26)[0];
            let composition_delta27 = forward_difference(composition_values, 27)[0];
            let values = (0..SAMPLES as u32)
                .map(|t| terminal_at(variable, t, family))
                .collect::<Vec<_>>();
            let degree = measured_degree(&values);
            maximum_terminal = maximum_terminal.max(degree);
            let delta27 = forward_difference(values.clone(), 27)[0];
            let delta28 = forward_difference(values, 28)[0];
            assert_eq!(
                composition_degree, 26,
                "composition degree changed for family {family}, variable {variable}"
            );
            assert!(!composition_delta26.is_zero());
            assert!(composition_delta27.is_zero());
            assert_eq!(
                degree, 27,
                "terminal degree changed for family {family}, variable {variable}"
            );
            assert!(!delta27.is_zero());
            assert!(delta28.is_zero());
            println!(
                "family={family} variable={variable} composition_degree={composition_degree} composition_delta26={} composition_delta27={} terminal_degree={degree} terminal_delta27={} terminal_delta28={}",
                hex(composition_delta26),
                hex(composition_delta27),
                hex(delta27),
                hex(delta28),
            );
        }
    }
    println!("maximum_composition_individual_degree={maximum_composition}");
    println!("maximum_terminal_individual_degree={maximum_terminal}");
    assert_eq!(
        maximum_composition, 26,
        "production constraint composition did not attain degree 26"
    );
    assert_eq!(
        maximum_terminal, 27,
        "production terminal did not attain degree 27"
    );
}

