fn legacy_copy_active_scanning_reference(selectors: &LegacyAtomicSelectors) -> QM31 {
    legacy_partition_constants::COMPILED_ATOMIC_COPY_ACTIVE_FACTORS
        .iter()
        .copied()
        .fold(QM31::ZERO, |sum, (high_mask, low_mask)| {
