            let mu = rng.qm31();
            let eta = rng.qm31();
            assert_eq!(
                atomic_state_only_selected_masked_terminal_value_compiled_v3(
                    &statement,
                    &claims,
                    &point,
                    lambda,
                    chi,
                    theta,
                    &zerocheck_point,
                    mu,
                    eta,
                )
                .unwrap(),
