                claims,
                &point,
                QM31::ONE,
                QM31::ONE,
                QM31::ONE,
                &zerocheck_point,
                QM31::ZERO,
                QM31::ZERO,
            )
            .unwrap()
        };
        let original = evaluate(&claims);
        let corrupted_value = evaluate(&corrupted);
        assert_eq!(corrupted_value, original.add(QM31::ONE));
        assert_eq!(
            corrupted_value,
            reference(
                &corrupted,
                &point,
                QM31::ONE,
                QM31::ONE,
                QM31::ONE,
                &zerocheck_point,
                QM31::ZERO,
                QM31::ZERO,
            ),
        );
    }

