    /// Soundness-grade Schwartz-Zippel equivalence checker.
    ///
    /// Every existing equivalence test in this module fixes ~64 random QM31
    /// draws and asserts the compiled point-form evaluator equals an
    /// independent row-form reference.  This test upgrades that regression
    /// witness into a machine-verified polynomial-identity check.
    ///
    /// The soundness statement the on-chain verifier relies on quantifies over
    /// ADVERSARIAL openings: the prover's claimed statement evaluations (the
    /// `claims`/`openings`/`h1` cells) may be any element of QM31, not the
    /// values an honest trace would produce.  We therefore fill the entire
    /// opening space with independent uniform-random QM31 (never an honest
    /// fixture) and independently randomize every challenge (lambda, chi,
    /// theta, mu, eta) and both evaluation points (`point`, `zerocheck_point`),
    /// then assert
    ///
    ///     point_form(random_openings, random_challenges)
    ///         == row_form_MLE(random_openings, random_challenges)
    ///
    /// for each evaluator family.  Both sides are polynomials of bounded total
    /// degree `D` over K = QM31 with |K| = P^4 ~ 2^124.  By Schwartz-Zippel, if
    /// the two sides were NOT the identical polynomial they would agree at a
    /// single uniform-random point except with probability <= D/|K|; over `T`
    /// independent points the escape probability is <= (D/|K|)^T.
    ///
    /// The evaluators are fixed, frozen production code chosen independently of
    /// the PRNG seed, so the deterministic xorshift stream (pinned constants,
    /// per the workspace no-entropy rule) is an adequate stand-in for uniform
    /// QM31: a fixed discrepancy cannot be crafted to dodge a seed it never
    /// saw, and the per-point margin (2^-116 or better) dwarfs any bias in the
    /// stream.  `T` distinct points give defense-in-depth on top of that.
    #[test]
    fn point_form_equals_row_form_at_soundness_grade_over_adversarial_openings() {
        // Trials per family.  A single trial already drives every family's
        // escape probability below 2^-100 (see per-family D below); T = 1024
        // independent points is generous margin, not necessity.
        const T: u32 = 1024;

        // |K| = |QM31| = P^4, with P = 2^31 - 1.
        let p = u128::from(P);
        let field_size = p * p * p * p; // ~2.1268e37 ~ 2^123.9999999.
        let log2_k = 4.0 * f64::from(P).log2();

        // Report one family's Schwartz-Zippel accounting and return the final
        // (D/|K|)^T escape bound as a base-2 exponent.
        let report = |name: &str, degree: u128| -> f64 {
            let per_trial_log2 = (degree as f64).log2() - log2_k;
            let final_log2 = per_trial_log2 * f64::from(T);
            std::println!(
                "  [{name}] D = {degree}, D/|K| = {degree}/{field_size} <= 2^{per_trial_log2:.2}, \
                 T = {T}, (D/|K|)^T <= 2^{final_log2:.1}",
            );
            // Guard the headline claim: one trial must already beat 2^-100.
            assert!(
                per_trial_log2 <= -100.0,
                "family {name}: single-trial bound 2^{per_trial_log2:.2} does not reach 2^-100",
            );
            assert!(
                final_log2 <= -100.0,
                "family {name}: T-trial bound 2^{final_log2:.1} does not reach 2^-100",
            );
            final_log2
        };

        std::println!(
            "Schwartz-Zippel equivalence over K = QM31, |K| = P^4 = {field_size} (~2^{log2_k:.4}); \
             {T} independent adversarial-opening trials per family:"
        );

        // --- Family A: rank-74 routing point-form == 183-link direct row walk.
        // Variables: point (10 QM31 coords).  Both sides are linear
        // combinations of the multilinear selector tensor, whose monomials have
        // total degree <= 10 in the point coordinates.  D_A = 10.
        {
            const D: u128 = 10;
            let mut rng = Rng(0x5344_5f52_4f55_5441); // "SD_ROUTA"
            let mut first: Option<Vec<QM31>> = None;
            let mut saw_variation = false;
            for _ in 0..T {
                let point = core::array::from_fn(|_| rng.qm31());
                let selectors = AtomicSelectors::at_point(&point);
                let point_form = evaluate_atomic_copy_routing(&selectors);
                let row_form = evaluate_routing_direct(&selectors);
                assert_eq!(point_form, row_form.to_vec());
                match &first {
                    None => first = Some(point_form.clone()),
                    Some(f) => saw_variation |= *f != point_form,
                }
            }
            assert!(
                saw_variation,
                "family A appears constant; identity is vacuous"
            );
            report("A rank-74 routing == 183-link direct walk", D);
        }

        // --- Family B: copy/LogUp lane point-form == direct registry row-walk.
        // This is the central point-form == row-form-MLE identity with FREE
        // adversarial openings.  `copy_lane_direct` rebuilds the host registry
        // and sums selector(row) * per-link residual over all 183 links, then
        // forms the cleared LogUp rational; `atomic_copy_lane_from_routing`
        // evaluates the compiled rank-74 factoring of the same object.
        // Variables: openings (16), h1, point (10), lambda, chi.
        // Degree bound: pattern values are deg 1 in openings times lambda^<=16
        // (deg <= 17); routing/selector factors are deg <= 10 in point; the
        // cleared LogUp numerator multiplies two degree-(<=54) denominators
        // against a degree-(<=55) factor, times the degree-<=10 active
        // selector, giving total degree <= 119.  D_B = 119.
        {
            const D: u128 = 119;
            let mut rng = Rng(0x5344_5f43_4f50_594c); // "SD_COPYL"
            let mut first: Option<QM31> = None;
            let mut saw_variation = false;
            for _ in 0..T {
                let openings = core::array::from_fn(|_| rng.qm31());
                let h1 = rng.qm31();
                let point = core::array::from_fn(|_| rng.qm31());
                let lambda = rng.qm31();
                let chi = rng.qm31();
                let selectors = AtomicSelectors::at_point(&point);
                let point_form =
                    atomic_copy_lane_from_routing(&openings, h1, &selectors, lambda, chi);
                let row_form = copy_lane_direct(&openings, h1, &selectors, lambda, chi);
                assert_eq!(point_form, row_form);
                match first {
                    None => first = Some(point_form),
                    Some(f) => saw_variation |= f != point_form,
                }
            }
            assert!(
                saw_variation,
                "family B appears constant; identity is vacuous"
            );
            report("B copy/LogUp lane point-form == registry row-walk MLE", D);
        }

        // --- Family C: rank-74 partition == rank-103 legacy partition.
        // Same copy polynomial evaluated through two independent selector
        // partitions of the 1024 rows.  Same variables and degree as family B.
        {
            const D: u128 = 119;
            let mut rng = Rng(0x5344_5f50_4152_5449); // "SD_PARTI"
            let mut first: Option<QM31> = None;
            let mut saw_variation = false;
            for _ in 0..T {
                let openings = core::array::from_fn(|_| rng.qm31());
                let h1 = rng.qm31();
                let point = core::array::from_fn(|_| rng.qm31());
                let lambda = rng.qm31();
                let chi = rng.qm31();
                let compiled = atomic_state_only_copy_terminal_lane_compiled_v3(
                    &openings, h1, &point, lambda, chi,
                );
                let legacy = atomic_state_only_copy_terminal_lane_legacy_partition_v3(
                    &openings, h1, &point, lambda, chi,
                );
                assert_eq!(compiled, legacy);
                match first {
                    None => first = Some(compiled),
                    Some(f) => saw_variation |= f != compiled,
                }
            }
            assert!(
                saw_variation,
                "family C appears constant; identity is vacuous"
            );
            report("C rank-74 partition == rank-103 legacy partition", D);
        }

        // --- Family D: five-dot pattern compression == 15 generated affine
        // shapes.  Variables: openings (16), lambda.  Openings appear linearly;
        // powers span lambda^1..lambda^16, and the highest shape multiplies a
        // lambda^8 factor into a term already carrying lambda^8 * opening, so
        // total degree <= 17.  D_D = 17.
        {
            const D: u128 = 17;
            let mut rng = Rng(0x5344_5f50_4154_5442); // "SD_PATTB"
            let mut first: Option<[QM31; ATOMIC_STATE_ONLY_COMPILED_COPY_PATTERNS]> = None;
            let mut saw_variation = false;
            for _ in 0..T {
                let openings = core::array::from_fn(|_| rng.qm31());
                let lambda = rng.qm31();
                let mut powers = [QM31::ZERO; 16];
                powers[0] = lambda;
                for index in 1..powers.len() {
                    powers[index] = powers[index - 1].mul(lambda);
                }
                let point_form = atomic_copy_pattern_values(&openings, &powers);
                let row_form = atomic_copy_pattern_values_generated_reference(&openings, &powers);
                assert_eq!(point_form, row_form);
                match &first {
                    None => first = Some(point_form),
                    Some(f) => saw_variation |= *f != point_form,
                }
            }
            assert!(
                saw_variation,
                "family D appears constant; identity is vacuous"
            );
            report("D five-dot pattern == 15 generated affine shapes", D);
        }

        // --- Family E: shared semantic selector tensor == legacy routing
        // selector tensor.  Variables: point (10).  Both are the multilinear
        // selector tensor, total degree <= 10.  D_E = 10.
        {
            const D: u128 = 10;
            let mut rng = Rng(0x5344_5f54_454e_534f); // "SD_TENSO"
            let mut first: Option<([QM31; 64], [QM31; 16])> = None;
            let mut saw_variation = false;
            for _ in 0..T {
                let point = core::array::from_fn(|_| rng.qm31());
                let semantic = AtomicSemanticSelectors::at_point(&point);
                let routing = LegacyAtomicSelectors::at_point(&point);
                assert_eq!(semantic.high, routing.high);
                assert_eq!(semantic.low, routing.low);
                match &first {
                    None => first = Some((semantic.high, semantic.low)),
                    Some((h, l)) => {
                        saw_variation |= *h != semantic.high || *l != semantic.low;
                    }
                }
            }
            assert!(
                saw_variation,
                "family E appears constant; identity is vacuous"
            );
            report("E semantic tensor == legacy routing tensor", D);
        }

        // --- Family F: full masked terminal == diagnostic-trace duplicate.
        // This is the EXACT composition the on-chain verifier evaluates
        // (state_only_spend.rs::verify_terminal calls
        // atomic_state_only_selected_masked_terminal_value_compiled_v3).  We
        // drive it with 84 free adversarial claim cells plus fully random
        // challenges/points and a random statement.  Both callees are point-
        // form; this is a refactor identity (production == its line-by-line
        // diagnostic-traced duplicate), NOT an independent row-form derivation
        // for the poseidon/semantic lanes (see the report caveats).
        //
        // Degree bound: the copy lane (<=119) is folded through 24 theta lanes
        // (theta^24 * copy => <=143); the outer zerocheck equality is degree
        // <=20 (10 in point, 10 in zerocheck_point), giving original <=163;
        // eta * original plus the mask keeps the whole terminal <=164.  We use
        // a conservative D_F = 200 (>= 164).  Even at 200, D/|K| <= 2^-116.
        {
            const D: u128 = 200;
            let mut rng = Rng(0x5344_5f54_4552_4d46); // "SD_TERMF"
            let mut first: Option<QM31> = None;
            let mut saw_variation = false;
            for _ in 0..T {
                let statement = AtomicPaymentStatementV4 {
                    pool: [0x5a; 32],
                    sequence: 73,
                    spend: SpendPublic {
                        anchor: core::array::from_fn(|_| rng.m31()),
                        nullifier: core::array::from_fn(|_| rng.m31()),
                        output_commitment: core::array::from_fn(|_| rng.m31()),
                        asset_id: rng.m31(),
                        // fee is a public constant in the residuals; keep it in
                        // the valid range so the evaluator does not early-return.
                        fee: (rng.next() % u64::from(crate::spend::VALUE_LIMIT)) as u32,
                    },
                    output_anchor: core::array::from_fn(|_| rng.m31()),
                    deployment_domain: [0x5d; 32],
                };
                let claims = core::array::from_fn(|_| rng.qm31());
                let point = core::array::from_fn(|_| rng.qm31());
                let zerocheck_point = core::array::from_fn(|_| rng.qm31());
                let lambda = rng.qm31();
                let chi = rng.qm31();
                let theta = rng.qm31();
                let mu = rng.qm31();
                let eta = rng.qm31();
                let production = atomic_state_only_selected_masked_terminal_value_compiled_v3(
                    &statement,
                    &claims,
                    &point,
                    lambda,
                    chi,
                    theta,
                    &zerocheck_point,
                    mu,
                    eta,
                )
                .unwrap();
                let diagnostic =
                    atomic_state_only_selected_masked_terminal_value_compiled_with_diagnostic_trace_v3(
                        &statement,
                        &claims,
                        &point,
                        lambda,
                        chi,
                        theta,
                        &zerocheck_point,
                        mu,
                        eta,
                        |_| {},
                    )
                    .unwrap();
                assert_eq!(production, diagnostic);
                match first {
                    None => first = Some(production),
                    Some(f) => saw_variation |= f != production,
                }
            }
            assert!(
                saw_variation,
                "family F appears constant; identity is vacuous"
            );
            report(
                "F masked terminal == diagnostic-trace duplicate (full verifier composition)",
                D,
            );
        }
    }
}

//! Production-neutral state-only trace foundation for atomic statement v3.
//!
//! This module deliberately does not alter the frozen v4/state-only copy,
//! semantic, terminal, or hiding registries. It materializes the selected
//! 49-block schedule and exposes the exact same-path sources which a later
//! registry generator must bind.

use alloc::vec::Vec;

use aspis_core::field::M31;

use crate::atomic_state_only_registry::atomic_state_only_path_aux_layout_v3;
use crate::atomic_statement::{AtomicPaymentStatementV4, ATOMIC_PAYMENT_TREE_DEPTH};
use crate::poseidon2::{
    merkle_node_compress_v3, permute_optimized_with_trace, Digest, DIGEST_ELEMS,
    MERKLE_NODE_COMPRESSION_V3_TWEAK, POSEIDON2_ROUNDS, POSEIDON2_WIDTH, RATE,
};
use crate::spend::{
    derive_owner_key, merkle_root, note_commitment, output_commitment, MerklePath, SpendPublic,
    SpendWitness,
};
use crate::state_only_trace::{
    project_state_only_trace_v4, StateOnlyTraceFoundation, STATE_ONLY_ABSORPTION_ROW_IN_BLOCK,
    STATE_ONLY_C1_COLUMNS, STATE_ONLY_FINAL_ROW_IN_BLOCK,
};
use crate::trace_v4::{build_spend_trace_v4, TraceCell, BLOCK_ROWS, PERMUTATION_COUNT, TRACE_ROWS};

pub const ATOMIC_STATE_ONLY_INPUT_PATH_BLOCK_START: usize = 4;
pub const ATOMIC_STATE_ONLY_OUTPUT_PATH_BLOCK_START: usize = 24;
pub const ATOMIC_STATE_ONLY_INPUT_ROOT_BLOCK: usize = 23;
pub const ATOMIC_STATE_ONLY_OUTPUT_ROOT_BLOCK: usize = 43;
pub const ATOMIC_STATE_ONLY_NULLIFIER_BLOCKS: core::ops::RangeInclusive<usize> = 44..=45;
pub const ATOMIC_STATE_ONLY_OUTPUT_NOTE_BLOCKS: core::ops::RangeInclusive<usize> = 46..=48;

const _: () = assert!(ATOMIC_PAYMENT_TREE_DEPTH == 20);
const _: () = assert!(PERMUTATION_COUNT == 49);
const _: () = assert!(STATE_ONLY_C1_COLUMNS == POSEIDON2_WIDTH);
const _: () = assert!(STATE_ONLY_FINAL_ROW_IN_BLOCK == 11);
const _: () = assert!(STATE_ONLY_ABSORPTION_ROW_IN_BLOCK == 12);

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum AtomicStateOnlyBlockV3 {
    OwnerKey,
    InputNote(u8),
    InputPath(u8),
    OutputPath(u8),
    Nullifier(u8),
    OutputNote(u8),
}

pub const fn atomic_state_only_block_schedule_v3(block: usize) -> Option<AtomicStateOnlyBlockV3> {
    match block {
        0 => Some(AtomicStateOnlyBlockV3::OwnerKey),
        1..=3 => Some(AtomicStateOnlyBlockV3::InputNote((block - 1) as u8)),
        4..=23 => Some(AtomicStateOnlyBlockV3::InputPath((block - 4) as u8)),
        24..=43 => Some(AtomicStateOnlyBlockV3::OutputPath((block - 24) as u8)),
        44..=45 => Some(AtomicStateOnlyBlockV3::Nullifier((block - 44) as u8)),
        46..=48 => Some(AtomicStateOnlyBlockV3::OutputNote((block - 46) as u8)),
        _ => None,
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct AtomicStateOnlyPathLevelV3 {
    pub level: u8,
    pub bit: u8,
    pub sibling: Digest,
    pub sibling_source: [TraceCell; DIGEST_ELEMS],
    pub bit_source: TraceCell,
    pub input_block: u8,
    pub output_block: u8,
    pub input_current: Digest,
    pub output_current: Digest,
    pub input_left: Digest,
    pub input_right: Digest,
    pub output_left: Digest,
    pub output_right: Digest,
    pub input_parent: Digest,
    pub output_parent: Digest,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct AtomicStateOnlyTraceV3 {
    pub trace: StateOnlyTraceFoundation,
    pub input_leaf: Digest,
    pub output_leaf: Digest,
    pub current_anchor: Digest,
    pub output_anchor: Digest,
    /// Both paths name the same source cells in each entry. There is no
    /// second sibling or direction-bit witness namespace.
    pub path: [AtomicStateOnlyPathLevelV3; ATOMIC_PAYMENT_TREE_DEPTH],
}

fn volatile_clear_digest(digest: &mut Digest) {
    for value in digest {
        // SAFETY: all metadata is uniquely borrowed during drop.
        unsafe { core::ptr::write_volatile(value, M31::ZERO) };
    }
}

impl Drop for AtomicStateOnlyTraceV3 {
    fn drop(&mut self) {
        volatile_clear_digest(&mut self.input_leaf);
        volatile_clear_digest(&mut self.output_leaf);
        volatile_clear_digest(&mut self.current_anchor);
        volatile_clear_digest(&mut self.output_anchor);
        for level in &mut self.path {
            volatile_clear_digest(&mut level.sibling);
            volatile_clear_digest(&mut level.input_current);
            volatile_clear_digest(&mut level.output_current);
            volatile_clear_digest(&mut level.input_left);
            volatile_clear_digest(&mut level.input_right);
            volatile_clear_digest(&mut level.output_left);
            volatile_clear_digest(&mut level.output_right);
            volatile_clear_digest(&mut level.input_parent);
            volatile_clear_digest(&mut level.output_parent);
            // The direction bit is witness-derived even though it is also
            // represented inside the trace.
            unsafe { core::ptr::write_volatile(&mut level.bit, 0) };
        }
        core::sync::atomic::compiler_fence(core::sync::atomic::Ordering::SeqCst);
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum AtomicStateOnlyTraceV3Error {
    PathDepth,
    PathIndexOutOfRange,
    CurrentAnchorMismatch,
    OutputAnchorMismatch,
    SpendBinding,
    SurrogateTrace,
    Projection,
    Layout,
    TraceMismatch { row: u16, column: u8 },
    PathMetadataMismatch { level: u8 },
}

fn ordered_children(current: Digest, sibling: Digest, bit: u8) -> (Digest, Digest) {
    if bit == 0 {
        (current, sibling)
    } else {
        (sibling, current)
    }
}

pub fn atomic_merkle_root_v3(
    leaf: Digest,
    path: &MerklePath,
) -> Result<Digest, AtomicStateOnlyTraceV3Error> {
    if path.siblings.len() != ATOMIC_PAYMENT_TREE_DEPTH {
        return Err(AtomicStateOnlyTraceV3Error::PathDepth);
    }
    if u64::from(path.index) >= (1u64 << ATOMIC_PAYMENT_TREE_DEPTH) {
        return Err(AtomicStateOnlyTraceV3Error::PathIndexOutOfRange);
    }
    let mut current = leaf;
    for (level, sibling) in path.siblings.iter().copied().enumerate() {
        let bit = ((path.index >> level) & 1) as u8;
        let (left, right) = ordered_children(current, sibling, bit);
        current = merkle_node_compress_v3(&left, &right);
    }
    Ok(current)
}

fn clear_block(trace: &mut StateOnlyTraceFoundation, block: usize) {
    let base = block * BLOCK_ROWS;
    for column in &mut trace.c1 {
        column[base..base + BLOCK_ROWS].fill(M31::ZERO);
    }
}

fn write_node_block(
    trace: &mut StateOnlyTraceFoundation,
    block: usize,
    left: &Digest,
    right: &Digest,
) -> Digest {
    clear_block(trace, block);
    let base = block * BLOCK_ROWS;

    // The state-only leading transition adds row 12 into the first eight
    // lanes of row 0. Keep the full-state tweak in row 0 lane 15.
    for lane in 0..DIGEST_ELEMS {
        trace.c1[RATE + lane][base] = right[lane];
        trace.c1[lane][base + STATE_ONLY_ABSORPTION_ROW_IN_BLOCK] = left[lane];
    }
    trace.c1[POSEIDON2_WIDTH - 1][base] =
        trace.c1[POSEIDON2_WIDTH - 1][base].add(MERKLE_NODE_COMPRESSION_V3_TWEAK);

    let mut state = [M31::ZERO; POSEIDON2_WIDTH];
    state[..DIGEST_ELEMS].copy_from_slice(left);
    state[DIGEST_ELEMS..].copy_from_slice(right);
    state[POSEIDON2_WIDTH - 1] = state[POSEIDON2_WIDTH - 1].add(MERKLE_NODE_COMPRESSION_V3_TWEAK);
    let mut transitions = Vec::with_capacity(POSEIDON2_ROUNDS);
    permute_optimized_with_trace(&mut state, |transition| transitions.push(transition));
    debug_assert_eq!(transitions.len(), POSEIDON2_ROUNDS);

    for local_row in 1..STATE_ONLY_FINAL_ROW_IN_BLOCK {
        let input = transitions[2 * local_row - 1].output;
        for lane in 0..POSEIDON2_WIDTH {
            trace.c1[lane][base + local_row] = input[lane];
        }
    }
    for lane in 0..POSEIDON2_WIDTH {
        trace.c1[lane][base + STATE_ONLY_FINAL_ROW_IN_BLOCK] = state[lane];
    }
    core::array::from_fn(|lane| state[lane])
}

fn digest_at(trace: &StateOnlyTraceFoundation, block: usize, local_row: usize) -> Digest {
    let row = block * BLOCK_ROWS + local_row;
    core::array::from_fn(|lane| trace.c1[lane][row])
}

fn read_cell(trace: &StateOnlyTraceFoundation, cell: TraceCell) -> M31 {
    trace.c1[usize::from(cell.column)][usize::from(cell.row)]
}

fn write_cell(trace: &mut StateOnlyTraceFoundation, cell: TraceCell, value: M31) {
    trace.c1[usize::from(cell.column)][usize::from(cell.row)] = value;
}

fn build_unvalidated(
    statement: &AtomicPaymentStatementV4,
    witness: &SpendWitness,
) -> Result<AtomicStateOnlyTraceV3, AtomicStateOnlyTraceV3Error> {
    if witness.merkle_path.siblings.len() != ATOMIC_PAYMENT_TREE_DEPTH {
        return Err(AtomicStateOnlyTraceV3Error::PathDepth);
    }
    if u64::from(witness.merkle_path.index) >= (1u64 << ATOMIC_PAYMENT_TREE_DEPTH) {
        return Err(AtomicStateOnlyTraceV3Error::PathIndexOutOfRange);
    }

    let owner_key = derive_owner_key(&witness.nullifier_key);
    let input_leaf = note_commitment(
        &owner_key,
        witness.value,
        witness.input_asset_id,
        &witness.input_salt,
    );
    let output_leaf = output_commitment(
        &witness.output_owner_key,
        witness.value_out,
        witness.input_asset_id,
        &witness.output_salt,
    );
    if output_leaf != statement.spend.output_commitment {
        return Err(AtomicStateOnlyTraceV3Error::SpendBinding);
    }
    let current_anchor = atomic_merkle_root_v3(input_leaf, &witness.merkle_path)?;
    if current_anchor != statement.spend.anchor {
        return Err(AtomicStateOnlyTraceV3Error::CurrentAnchorMismatch);
    }
    let output_anchor = atomic_merkle_root_v3(output_leaf, &witness.merkle_path)?;
    if output_anchor != statement.output_anchor {
        return Err(AtomicStateOnlyTraceV3Error::OutputAnchorMismatch);
    }

    // The unchanged blocks are produced by the already hardened v2 SpendV0
    // recorder under a surrogate v2 anchor. Blocks 4..43 are replaced below.
    let surrogate_anchor = merkle_root(input_leaf, &witness.merkle_path)
        .map_err(|_| AtomicStateOnlyTraceV3Error::SurrogateTrace)?;
    let surrogate_public = SpendPublic {
        anchor: surrogate_anchor,
        nullifier: statement.spend.nullifier,
        output_commitment: statement.spend.output_commitment,
        asset_id: statement.spend.asset_id,
        fee: statement.spend.fee,
    };
    let source = build_spend_trace_v4(&surrogate_public, witness)
        .map_err(|_| AtomicStateOnlyTraceV3Error::SurrogateTrace)?;
    let mut trace = project_state_only_trace_v4(&source)
        .map_err(|_| AtomicStateOnlyTraceV3Error::Projection)?;
    let atomic_aux =
        atomic_state_only_path_aux_layout_v3().map_err(|_| AtomicStateOnlyTraceV3Error::Layout)?;

    let mut input_current = input_leaf;
    let mut output_current = output_leaf;
    let mut path = Vec::with_capacity(ATOMIC_PAYMENT_TREE_DEPTH);
    for level in 0..ATOMIC_PAYMENT_TREE_DEPTH {
        let sibling = witness.merkle_path.siblings[level];
        let bit = ((witness.merkle_path.index >> level) & 1) as u8;
        let (input_left, input_right) = ordered_children(input_current, sibling, bit);
        let (output_left, output_right) = ordered_children(output_current, sibling, bit);
        let path_aux = atomic_aux[level];
        write_cell(&mut trace, path_aux.input_bit, M31(u32::from(bit)));
        write_cell(&mut trace, path_aux.output_bit, M31(u32::from(bit)));
        write_cell(&mut trace, path_aux.sibling_bit, M31(u32::from(bit)));
        for limb in 0..DIGEST_ELEMS {
            write_cell(
                &mut trace,
                path_aux.input_current[limb],
                input_current[limb],
            );
            write_cell(
                &mut trace,
                path_aux.output_current[limb],
                output_current[limb],
            );
            write_cell(&mut trace, path_aux.sibling[limb], sibling[limb]);
        }
        let input_block = ATOMIC_STATE_ONLY_INPUT_PATH_BLOCK_START + level;
        let output_block = ATOMIC_STATE_ONLY_OUTPUT_PATH_BLOCK_START + level;
        let input_parent = write_node_block(&mut trace, input_block, &input_left, &input_right);
        let output_parent = write_node_block(&mut trace, output_block, &output_left, &output_right);
        debug_assert_eq!(
            input_parent,
            merkle_node_compress_v3(&input_left, &input_right)
        );
        debug_assert_eq!(
            output_parent,
            merkle_node_compress_v3(&output_left, &output_right)
        );
        path.push(AtomicStateOnlyPathLevelV3 {
            level: level as u8,
            bit,
            sibling,
            sibling_source: path_aux.sibling,
            bit_source: path_aux.input_bit,
            input_block: input_block as u8,
            output_block: output_block as u8,
            input_current,
            output_current,
            input_left,
            input_right,
            output_left,
            output_right,
            input_parent,
            output_parent,
        });
        input_current = input_parent;
        output_current = output_parent;
    }
    debug_assert_eq!(input_current, current_anchor);
    debug_assert_eq!(output_current, output_anchor);
    debug_assert_eq!(
        digest_at(
            &trace,
            ATOMIC_STATE_ONLY_INPUT_ROOT_BLOCK,
            STATE_ONLY_FINAL_ROW_IN_BLOCK,
        ),
        current_anchor
    );
    debug_assert_eq!(
        digest_at(
            &trace,
            ATOMIC_STATE_ONLY_OUTPUT_ROOT_BLOCK,
            STATE_ONLY_FINAL_ROW_IN_BLOCK,
        ),
        output_anchor
    );

    let path: [AtomicStateOnlyPathLevelV3; ATOMIC_PAYMENT_TREE_DEPTH] = path
        .try_into()
        .map_err(|_| AtomicStateOnlyTraceV3Error::PathDepth)?;
    Ok(AtomicStateOnlyTraceV3 {
        trace,
        input_leaf,
        output_leaf,
        current_anchor,
        output_anchor,
        path,
    })
}

pub fn build_atomic_state_only_trace_v3(
    statement: &AtomicPaymentStatementV4,
    witness: &SpendWitness,
) -> Result<AtomicStateOnlyTraceV3, AtomicStateOnlyTraceV3Error> {
    let foundation = build_unvalidated(statement, witness)?;
    validate_atomic_state_only_trace_v3(statement, witness, &foundation)?;
    Ok(foundation)
}

/// Exact host reference guard. This is intentionally independent of future
/// compiled copy/terminal constants: it rebuilds from the public statement
/// and the one private path, then compares every cell and alias descriptor.
pub fn validate_atomic_state_only_trace_v3(
    statement: &AtomicPaymentStatementV4,
    witness: &SpendWitness,
    candidate: &AtomicStateOnlyTraceV3,
) -> Result<(), AtomicStateOnlyTraceV3Error> {
    let expected = build_unvalidated(statement, witness)?;
    if candidate
        .trace
        .c1
        .iter()
        .any(|column| column.len() != TRACE_ROWS)
    {
        return Err(AtomicStateOnlyTraceV3Error::Projection);
    }
    for row in 0..TRACE_ROWS {
        for column in 0..STATE_ONLY_C1_COLUMNS {
            if candidate.trace.c1[column][row] != expected.trace.c1[column][row] {
                return Err(AtomicStateOnlyTraceV3Error::TraceMismatch {
                    row: row as u16,
                    column: column as u8,
                });
            }
        }
    }
    if candidate.input_leaf != expected.input_leaf
        || candidate.output_leaf != expected.output_leaf
        || candidate.current_anchor != expected.current_anchor
        || candidate.output_anchor != expected.output_anchor
    {
        return Err(AtomicStateOnlyTraceV3Error::SpendBinding);
    }
    for level in 0..ATOMIC_PAYMENT_TREE_DEPTH {
        if candidate.path[level] != expected.path[level] {
            return Err(AtomicStateOnlyTraceV3Error::PathMetadataMismatch { level: level as u8 });
        }
        for limb in 0..DIGEST_ELEMS {
            if read_cell(&candidate.trace, candidate.path[level].sibling_source[limb])
                != witness.merkle_path.siblings[level][limb]
            {
                return Err(AtomicStateOnlyTraceV3Error::PathMetadataMismatch {
                    level: level as u8,
                });
            }
        }
        if read_cell(&candidate.trace, candidate.path[level].bit_source)
            != M31(candidate.path[level].bit as u32)
        {
            return Err(AtomicStateOnlyTraceV3Error::PathMetadataMismatch { level: level as u8 });
        }
    }
    Ok(())
}

/// Public-root parity helper used by the future semantic binding generator.
pub fn atomic_state_only_bound_roots_v3(trace: &AtomicStateOnlyTraceV3) -> (Digest, Digest) {
    (
        digest_at(
            &trace.trace,
            ATOMIC_STATE_ONLY_INPUT_ROOT_BLOCK,
            STATE_ONLY_FINAL_ROW_IN_BLOCK,
        ),
        digest_at(
            &trace.trace,
            ATOMIC_STATE_ONLY_OUTPUT_ROOT_BLOCK,
            STATE_ONLY_FINAL_ROW_IN_BLOCK,
        ),
    )
}

/// Extract the exact ordered node input represented by row 0 plus row 12.
pub fn atomic_state_only_node_input_v3(
    trace: &AtomicStateOnlyTraceV3,
    block: usize,
) -> Option<[M31; POSEIDON2_WIDTH]> {
    match atomic_state_only_block_schedule_v3(block)? {
        AtomicStateOnlyBlockV3::InputPath(_) | AtomicStateOnlyBlockV3::OutputPath(_) => {}
        _ => return None,
    }
    let base = block * BLOCK_ROWS;
    let mut state = core::array::from_fn(|lane| trace.trace.c1[lane][base]);
    for lane in 0..RATE {
        state[lane] =
            state[lane].add(trace.trace.c1[lane][base + STATE_ONLY_ABSORPTION_ROW_IN_BLOCK]);
    }
    Some(state)
}

crates/aspis-statement/src/atomic_statem:
//! Canonical public binding for the atomic same-private-path SpendV0 state
//! transition.
//!
//! Atomic-v4 proves that the spent input leaf and the output commitment use
//! one private Merkle path, taking `spend.anchor` to `output_anchor`. `sequence`
//! is the public pool-account revision checked by the eventual mutation path;
//! it is not the private leaf index. The public append-index construction
//! below is retained only as a separately rejected capacity candidate.

use aspis_core::{
    field::{M31, P},
    transcript::HashFn,
};

use crate::{
    poseidon2::{hash_merkle_node_sponge, Digest, DIGEST_ELEMS},
    spend::{SpendPublic, VALUE_LIMIT},
};

pub const ATOMIC_PAYMENT_TREE_DEPTH: usize = 20;
pub const ATOMIC_PAYMENT_STATEMENT_VERSION: u8 = 4;
pub const ATOMIC_PAYMENT_STATEMENT_PAYLOAD_BYTES: usize = 216;
pub const ATOMIC_PAYMENT_STATEMENT_DOMAIN: &[u8] = b"aspis/atomic-payment-statement/v4";
pub const ATOMIC_PAYMENT_EMPTY_LEAF: Digest = [M31::ZERO; DIGEST_ELEMS];
pub const ATOMIC_PAYMENT_STATEMENT_V4_KAT_EXPECTED: [u8; 32] = [
    0x47, 0x61, 0x3b, 0xf7, 0x1c, 0xb5, 0x3e, 0x9d, 0x99, 0xbf, 0x56, 0x48, 0x72, 0xde, 0xd5, 0xeb,
    0x38, 0x5b, 0x99, 0x59, 0x95, 0xde, 0xf6, 0x69, 0xfd, 0x5b, 0xe1, 0x29, 0x8e, 0x68, 0x90, 0x4f,
];
pub const ATOMIC_APPEND_CHAIN_DOMAIN: &[u8] = b"aspis/atomic-append-chain/v1";

/// Domain separator for the pool deployment-domain derivation:
/// `deployment_domain = sha256(DOMAIN || runtime_program_id || domain_tag)`.
pub const ATOMIC_DEPLOYMENT_DOMAIN_SEPARATOR: &[u8] = b"aspis-spend-deployment-domain-v1";

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct AtomicPaymentStatementV4 {
    pub pool: [u8; 32],
    pub sequence: u64,
    pub spend: SpendPublic,
    pub output_anchor: Digest,
    /// The pool's deployment domain, `sha256(separator || runtime_program_id
    /// || domain_tag)`. Binding it into the statement digest makes every
    /// proof specific to one program deployment on one named cluster.
    pub deployment_domain: [u8; 32],
}

/// Compute the deployment domain bound by both the pool account and every
/// v4 statement: `sha256(separator || runtime_program_id || domain_tag)`.
pub fn atomic_deployment_domain(
    hash: HashFn,
    runtime_program_id: &[u8; 32],
    domain_tag: &[u8],
) -> [u8; 32] {
    hash(&[
        ATOMIC_DEPLOYMENT_DOMAIN_SEPARATOR,
        runtime_program_id,
        domain_tag,
    ])
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum AtomicStatementError {
    NonCanonicalDigest,
    NonCanonicalAssetId,
    FeeOutOfRange,
    PathDepthMismatch,
    InsertionIndexOutOfRange,
    CurrentAnchorMismatch,
    OutputAnchorMismatch,
}

#[inline]
pub fn encode_digest_canonical(digest: &Digest) -> [u8; 32] {
    let mut bytes = [0u8; 32];
    for (index, value) in digest.iter().enumerate() {
        bytes[index * 4..index * 4 + 4].copy_from_slice(&value.to_le_bytes());
    }
    bytes
}

/// Unwrap a fixed-width slice conversion after its enclosing length guard.
/// Both payloads are Copy, so extraction needs no formatting or drop machinery.
#[inline]
pub(crate) fn unwrap_fixed_slice<T: Copy>(value: Result<T, core::array::TryFromSliceError>) -> T {
    match value {
        Ok(value) => value,
        Err(_) => panic!("fixed-size slice conversion failed"),
    }
}

pub fn decode_digest_canonical(bytes: &[u8; 32]) -> Result<Digest, AtomicStatementError> {
    Ok([
        M31::from_le_bytes([bytes[0], bytes[1], bytes[2], bytes[3]])
            .ok_or(AtomicStatementError::NonCanonicalDigest)?,
        M31::from_le_bytes([bytes[4], bytes[5], bytes[6], bytes[7]])
            .ok_or(AtomicStatementError::NonCanonicalDigest)?,
        M31::from_le_bytes([bytes[8], bytes[9], bytes[10], bytes[11]])
            .ok_or(AtomicStatementError::NonCanonicalDigest)?,
        M31::from_le_bytes([bytes[12], bytes[13], bytes[14], bytes[15]])
            .ok_or(AtomicStatementError::NonCanonicalDigest)?,
        M31::from_le_bytes([bytes[16], bytes[17], bytes[18], bytes[19]])
            .ok_or(AtomicStatementError::NonCanonicalDigest)?,
        M31::from_le_bytes([bytes[20], bytes[21], bytes[22], bytes[23]])
            .ok_or(AtomicStatementError::NonCanonicalDigest)?,
        M31::from_le_bytes([bytes[24], bytes[25], bytes[26], bytes[27]])
            .ok_or(AtomicStatementError::NonCanonicalDigest)?,
        M31::from_le_bytes([bytes[28], bytes[29], bytes[30], bytes[31]])
            .ok_or(AtomicStatementError::NonCanonicalDigest)?,
    ])
}

pub fn decode_asset_id_canonical(value: u32) -> Result<M31, AtomicStatementError> {
    if value >= P {
        return Err(AtomicStatementError::NonCanonicalAssetId);
    }
    Ok(M31(value))
}

#[inline]
fn merkle_parent(left: &Digest, right: &Digest) -> Digest {
    let mut input = [M31::ZERO; DIGEST_ELEMS * 2];
    input[..DIGEST_ELEMS].copy_from_slice(left);
    input[DIGEST_ELEMS..].copy_from_slice(right);
    hash_merkle_node_sponge(&input)
}

pub fn insertion_root(
    leaf: Digest,
    sequence: u64,
    siblings: &[Digest],
) -> Result<Digest, AtomicStatementError> {
    if siblings.len() != ATOMIC_PAYMENT_TREE_DEPTH {
        return Err(AtomicStatementError::PathDepthMismatch);
    }
    if sequence >= (1u64 << ATOMIC_PAYMENT_TREE_DEPTH) {
        return Err(AtomicStatementError::InsertionIndexOutOfRange);
    }
    let mut current = leaf;
    for (level, sibling) in siblings.iter().enumerate() {
        current = if (sequence >> level) & 1 == 0 {
            merkle_parent(&current, sibling)
        } else {
            merkle_parent(sibling, &current)
        };
    }
    Ok(current)
}

/// Rejected public-append candidate: check that `sequence` addresses an empty
/// leaf and replace it with `output_commitment`. Atomic-v4 does not call this;
/// its proof constrains a private same-path replacement instead.
pub fn verify_output_insertion(
    current_anchor: &Digest,
    output_commitment: &Digest,
    output_anchor: &Digest,
    sequence: u64,
    siblings: &[Digest],
) -> Result<(), AtomicStatementError> {
    if insertion_root(ATOMIC_PAYMENT_EMPTY_LEAF, sequence, siblings)? != *current_anchor {
        return Err(AtomicStatementError::CurrentAnchorMismatch);
    }
    if insertion_root(*output_commitment, sequence, siblings)? != *output_anchor {
        return Err(AtomicStatementError::OutputAnchorMismatch);
    }
    Ok(())
}

/// Fixed-width, canonical encoding hashed into the proof transcript.
///
/// Layout: `version || depth || zero[6] || pool || sequence_le || anchor ||
/// nullifier || output_commitment || output_anchor || asset_id_le || fee_le
/// || deployment_domain`.
pub fn encode_atomic_payment_statement_v4(
    statement: &AtomicPaymentStatementV4,
) -> Result<[u8; ATOMIC_PAYMENT_STATEMENT_PAYLOAD_BYTES], AtomicStatementError> {
    if statement.spend.asset_id.0 >= P {
        return Err(AtomicStatementError::NonCanonicalAssetId);
    }
    if statement.spend.fee >= VALUE_LIMIT {
        return Err(AtomicStatementError::FeeOutOfRange);
    }
    let mut output = [0u8; ATOMIC_PAYMENT_STATEMENT_PAYLOAD_BYTES];
    output[0] = ATOMIC_PAYMENT_STATEMENT_VERSION;
    output[1] = ATOMIC_PAYMENT_TREE_DEPTH as u8;
    output[8..40].copy_from_slice(&statement.pool);
    output[40..48].copy_from_slice(&statement.sequence.to_le_bytes());
    output[48..80].copy_from_slice(&encode_digest_canonical(&statement.spend.anchor));
    output[80..112].copy_from_slice(&encode_digest_canonical(&statement.spend.nullifier));
    output[112..144].copy_from_slice(&encode_digest_canonical(&statement.spend.output_commitment));
    output[144..176].copy_from_slice(&encode_digest_canonical(&statement.output_anchor));
    output[176..180].copy_from_slice(&statement.spend.asset_id.to_le_bytes());
    output[180..184].copy_from_slice(&statement.spend.fee.to_le_bytes());
    output[184..216].copy_from_slice(&statement.deployment_domain);
    Ok(output)
}

pub fn atomic_payment_statement_digest_v4(
    statement: &AtomicPaymentStatementV4,
    hash: HashFn,
) -> Result<[u8; 32], AtomicStatementError> {
    let payload = encode_atomic_payment_statement_v4(statement)?;
    Ok(hash(&[ATOMIC_PAYMENT_STATEMENT_DOMAIN, &payload]))
}

/// Constant-time append-chain control used only as a priced negative model.
///
/// It binds an append exactly, but by itself does not provide a logarithmic
/// membership witness for old leaves. It is therefore not a replacement for
/// the payment tree unless another hiding-preserving membership accumulator
/// is added.
pub fn atomic_append_chain_anchor(
    old_anchor: &[u8; 32],
    output_leaf: &Digest,
    index: u64,
    hash: HashFn,
) -> [u8; 32] {
    let leaf = encode_digest_canonical(output_leaf);
    let index = index.to_le_bytes();
    hash(&[ATOMIC_APPEND_CHAIN_DOMAIN, old_anchor, &leaf, &index])
}

#[cfg(test)]
mod tests {
    use sha2::{Digest as _, Sha256};

    use super::*;

    fn sha256(inputs: &[&[u8]]) -> [u8; 32] {
        let mut hash = Sha256::new();
        for input in inputs {
            hash.update(input);
        }
        hash.finalize().into()
    }

    fn digest(seed: u32) -> Digest {
        core::array::from_fn(|index| M31(seed + index as u32 * 17))
    }

    fn statement() -> AtomicPaymentStatementV4 {
        AtomicPaymentStatementV4 {
            pool: [9u8; 32],
            sequence: 7,
            spend: SpendPublic {
                anchor: digest(10),
                nullifier: digest(20),
                output_commitment: digest(30),
                asset_id: M31(40),
                fee: 50,
            },
            output_anchor: digest(60),
            deployment_domain: [70u8; 32],
        }
    }

    #[test]
    fn canonical_digest_roundtrip_and_rejection() {
        let value = digest(123);
        assert_eq!(
            decode_digest_canonical(&encode_digest_canonical(&value)),
            Ok(value)
        );
        let mut bad = encode_digest_canonical(&value);
        bad[..4].copy_from_slice(&P.to_le_bytes());
        assert_eq!(
            decode_digest_canonical(&bad),
            Err(AtomicStatementError::NonCanonicalDigest)
        );
    }

    #[test]
    fn every_public_field_changes_the_statement_digest() {
        let original = statement();
        let expected = atomic_payment_statement_digest_v4(&original, sha256).unwrap();
        assert_eq!(expected, ATOMIC_PAYMENT_STATEMENT_V4_KAT_EXPECTED);
        let mut variants = alloc::vec::Vec::new();

        let mut changed = original.clone();
        changed.pool[0] ^= 1;
        variants.push(changed);
        let mut changed = original.clone();
        changed.sequence += 1;
        variants.push(changed);
        for selector in 0..4 {
            let mut changed = original.clone();
            let digest = match selector {
                0 => &mut changed.spend.anchor,
                1 => &mut changed.spend.nullifier,
                2 => &mut changed.spend.output_commitment,
                _ => &mut changed.output_anchor,
            };
            digest[0] = digest[0].add(M31::ONE);
            variants.push(changed);
        }
        let mut changed = original.clone();
        changed.spend.asset_id = changed.spend.asset_id.add(M31::ONE);
        variants.push(changed);
        let mut changed = original.clone();
        changed.spend.fee += 1;
        variants.push(changed);
        let mut changed = original;
        changed.deployment_domain[0] ^= 1;
        variants.push(changed);

        for variant in variants {
            assert_ne!(
                atomic_payment_statement_digest_v4(&variant, sha256).unwrap(),
                expected
            );
        }
    }

    #[test]
    fn empty_leaf_update_binds_both_roots() {
        let siblings: [Digest; ATOMIC_PAYMENT_TREE_DEPTH] =
            core::array::from_fn(|index| digest(1_000 + index as u32 * 31));
        let output = digest(777);
        let current = insertion_root(ATOMIC_PAYMENT_EMPTY_LEAF, 19, &siblings).unwrap();
        let next = insertion_root(output, 19, &siblings).unwrap();
        assert_eq!(
            verify_output_insertion(&current, &output, &next, 19, &siblings),
            Ok(())
        );
        let mut wrong = next;
        wrong[0] = wrong[0].add(M31::ONE);
        assert_eq!(
            verify_output_insertion(&current, &output, &wrong, 19, &siblings),
            Err(AtomicStatementError::OutputAnchorMismatch)
        );
    }

    #[test]
    fn output_is_a_future_input_leaf() {
        let owner = digest(2_001);
        let salt = digest(3_001);
        let value = 99;
        let asset = M31(7);
        assert_eq!(
            crate::note_commitment(&owner, value, asset, &salt),
            crate::output_commitment(&owner, value, asset, &salt),
            "atomic output leaves must be accepted by future input membership"
        );
    }

    #[test]
    fn append_chain_binds_old_root_leaf_and_index_but_not_membership() {
        let old = [0x42u8; 32];
        let leaf = digest(5_001);
        let anchor = atomic_append_chain_anchor(&old, &leaf, 9, sha256);
        let mut changed_old = old;
        changed_old[0] ^= 1;
        assert_ne!(
            atomic_append_chain_anchor(&changed_old, &leaf, 9, sha256),
            anchor
        );
        let mut changed_leaf = leaf;
        changed_leaf[0] = changed_leaf[0].add(M31::ONE);
        assert_ne!(
            atomic_append_chain_anchor(&old, &changed_leaf, 9, sha256),
            anchor
        );
        assert_ne!(atomic_append_chain_anchor(&old, &leaf, 10, sha256), anchor);

        // Recovering the final root for the first leaf requires replaying all
        // later leaves: the witness grows with the chain suffix, not log(n).
        let second = atomic_append_chain_anchor(&anchor, &digest(6_001), 10, sha256);
        let third = atomic_append_chain_anchor(&second, &digest(7_001), 11, sha256);
        assert_ne!(anchor, third);
        assert_eq!(
            atomic_append_chain_anchor(
                &atomic_append_chain_anchor(&anchor, &digest(6_001), 10, sha256),
                &digest(7_001),
                11,
                sha256,
            ),
            third
        );
    }
}

crates/aspis-statement/src/constraints_v:
//! Frozen payment constraint registry for the lr10/rate-1/16 SpendV0 trace.
//!
//! The registry contains 252 source constraints. The first 250 are
//! base-field-valued and are injectively packed four-at-a-time into 63 QM31
//! polynomials; the two LogUp constraints remain separate. Together with the
//! two independent helper-sum claims, the generic randomized ledger contains
//! 67 claims. The selected direct-range profile replaces the range LogUp with
//! nine packed lanes and has 73 constraint lanes plus one helper claim.

use alloc::boxed::Box;
use alloc::vec;
use alloc::vec::Vec;

use aspis_core::field::{
    qm31_dot, qm31_evaluate_degree72_radix8, qm31_m31_dot, qm31_pack_base4, qm31_sum_products2,
    qm31_sum_products3, qm31_sum_products4, PreparedQm31Multiplier, CM31, M31, P, QM31,
};
use aspis_core::statement_sumcheck::PaymentConstraintChallenges;

use crate::logup::{
    build_copy_logup_helper, build_range_logup_helper, copy_logup_residual, range_logup_residual,
    verify_copy_logup_constraints, verify_range_logup_constraints, CopyLogUpRow, LogUpError,
    RangeLogUpRow,
};
use crate::poseidon2::{
    evaluate_trace_round, trace_round_constant, DIGEST_ELEMS, POSEIDON2_WIDTH, RATE,
};
use crate::spend::{SpendPublic, VALUE_LIMIT};
use crate::trace_v4::{
    copy_terminal_pattern, has_carry_payload, is_poseidon_active_row, is_poseidon_padding_row,
    merkle_boundary_layout, permutation_block_schedule, source_relation_layout,
    visit_copy_exceptional_terminal_links, visit_copy_links, visit_copy_terminal_links,
    witness_aux_layout, CopyTuple, SpendTraceV4, TraceCell, TupleLimb, ABSORPTION_ROW_IN_BLOCK,
    ACTIVE_ROWS_PER_BLOCK, AUX_ABSORPTION_PRODUCER_ROW_START, BLOCK_ROWS, COPY_LINK_COUNT,
    COPY_TERMINAL_PATTERN_COUNT, EXCEPTIONAL_COPY_TERMINAL_LINKS, FIRST_ROUND_OUTPUT_COLUMN_START,
    INPUT_VALUE_RANGE_ROW, INTERFACE_COLUMN_START, MULTIPLICITY_COLUMN, OUTPUT_VALUE_RANGE_ROW,
    PERMUTATION_COUNT, SECOND_ROUND_OUTPUT_COLUMN_START, STATE_AND_INTERFACE_COLUMNS, TRACE_ROWS,
    VALUE_RECONSTRUCTION_COLUMN,
};

pub const POSEIDON_FIRST_START: usize = 0;
pub const POSEIDON_SECOND_START: usize = POSEIDON_FIRST_START + POSEIDON2_WIDTH;
pub const INITIAL_STATE_START: usize = POSEIDON_SECOND_START + POSEIDON2_WIDTH;
pub const PADDING_ZERO_START: usize = INITIAL_STATE_START + POSEIDON2_WIDTH;
pub const ABSORPTION_TAIL_START: usize = PADDING_ZERO_START + STATE_AND_INTERFACE_COLUMNS;
pub const SOURCE_EQUALITY_START: usize = ABSORPTION_TAIL_START + STATE_AND_INTERFACE_COLUMNS;
pub const SOURCE_EQUALITY_COUNT: usize = 60;
pub const MERKLE_BIT_BOOLEAN_ID: usize = SOURCE_EQUALITY_START + SOURCE_EQUALITY_COUNT;
pub const MERKLE_LEFT_START: usize = MERKLE_BIT_BOOLEAN_ID + 1;
pub const MERKLE_RIGHT_START: usize = MERKLE_LEFT_START + DIGEST_ELEMS;
pub const INPUT_VALUE_RECONSTRUCTION_ID: usize = MERKLE_RIGHT_START + DIGEST_ELEMS;
pub const OUTPUT_VALUE_RECONSTRUCTION_ID: usize = INPUT_VALUE_RECONSTRUCTION_ID + 1;
pub const BALANCE_ID: usize = OUTPUT_VALUE_RECONSTRUCTION_ID + 1;
pub const PUBLIC_ANCHOR_START: usize = BALANCE_ID + 1;
pub const PUBLIC_NULLIFIER_START: usize = PUBLIC_ANCHOR_START + DIGEST_ELEMS;
pub const PUBLIC_OUTPUT_START: usize = PUBLIC_NULLIFIER_START + DIGEST_ELEMS;
pub const PUBLIC_INPUT_ASSET_ID: usize = PUBLIC_OUTPUT_START + DIGEST_ELEMS;
pub const PUBLIC_OUTPUT_ASSET_ID: usize = PUBLIC_INPUT_ASSET_ID + 1;
pub const COPY_LOGUP_ID: usize = PUBLIC_OUTPUT_ASSET_ID + 1;
pub const RANGE_LOGUP_ID: usize = COPY_LOGUP_ID + 1;
pub const CONSTRAINT_COUNT: usize = RANGE_LOGUP_ID + 1;
pub const GLOBAL_HELPER_SUM_CLAIMS: usize = 2;
pub const BASE_FIELD_CONSTRAINT_COUNT: usize = COPY_LOGUP_ID;
pub const PACKED_BASE_CONSTRAINT_COUNT: usize = (BASE_FIELD_CONSTRAINT_COUNT + 3) / 4;
pub const RANDOMIZED_CONSTRAINT_COUNT: usize = PACKED_BASE_CONSTRAINT_COUNT + 2;
pub const RANDOMIZED_CLAIM_COUNT: usize = RANDOMIZED_CONSTRAINT_COUNT + GLOBAL_HELPER_SUM_CLAIMS;
pub const DIRECT_RANGE_SOURCE_RESIDUAL_COUNT: usize =
    crate::direct_range_hiding_v4::DIRECT_RANGE_BITS_PER_ROW
        + crate::direct_range_hiding_v4::DIRECT_RANGE_LIMBS_PER_ROW;
pub const DIRECT_RANGE_CONSTRAINT_SOURCE_COUNT: usize =
    BASE_FIELD_CONSTRAINT_COUNT + 1 + DIRECT_RANGE_SOURCE_RESIDUAL_COUNT;
pub const DIRECT_RANGE_PACKED_LANE_COUNT: usize = (DIRECT_RANGE_SOURCE_RESIDUAL_COUNT + 3) / 4;
pub const DIRECT_RANGE_RANDOMIZED_CONSTRAINT_COUNT: usize =
    PACKED_BASE_CONSTRAINT_COUNT + 1 + DIRECT_RANGE_PACKED_LANE_COUNT;
pub const DIRECT_RANGE_GLOBAL_HELPER_SUM_CLAIMS: usize = 1;
pub const DIRECT_RANGE_RANDOMIZED_CLAIM_COUNT: usize =
    DIRECT_RANGE_RANDOMIZED_CONSTRAINT_COUNT + DIRECT_RANGE_GLOBAL_HELPER_SUM_CLAIMS;
pub const DIRECT_RANGE_THETA_COLLISION_DEGREE: usize = DIRECT_RANGE_RANDOMIZED_CONSTRAINT_COUNT - 1;

const _: () = assert!(CONSTRAINT_COUNT == 252);
const _: () = assert!(BASE_FIELD_CONSTRAINT_COUNT == 250);
const _: () = assert!(PACKED_BASE_CONSTRAINT_COUNT == 63);
const _: () = assert!(RANDOMIZED_CONSTRAINT_COUNT == 65);
const _: () = assert!(RANDOMIZED_CLAIM_COUNT == 67);
const _: () = assert!(DIRECT_RANGE_SOURCE_RESIDUAL_COUNT == 33);
const _: () = assert!(DIRECT_RANGE_CONSTRAINT_SOURCE_COUNT == 284);
const _: () = assert!(DIRECT_RANGE_PACKED_LANE_COUNT == 9);
const _: () = assert!(DIRECT_RANGE_GLOBAL_HELPER_SUM_CLAIMS == 1);
const _: () = assert!(DIRECT_RANGE_RANDOMIZED_CONSTRAINT_COUNT == 73);
const _: () = assert!(DIRECT_RANGE_RANDOMIZED_CLAIM_COUNT == 74);
const _: () = assert!(DIRECT_RANGE_THETA_COLLISION_DEGREE == 72);

#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub struct ConstraintId(u16);

impl ConstraintId {
    pub const fn new(index: usize) -> Option<Self> {
        if index < CONSTRAINT_COUNT {
            Some(Self(index as u16))
        } else {
            None
        }
    }

    pub const fn index(self) -> usize {
        self.0 as usize
    }

    pub const fn wire_value(self) -> u16 {
        self.0
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ConstraintKind {
    PoseidonFirst { lane: u8 },
    PoseidonSecond { lane: u8 },
    InitialSpongeState { lane: u8 },
    PaddingZero { column: u8 },
    AbsorptionTailZero { column: u8 },
    SourceEquality { binding: u8 },
    MerklePathBitBoolean,
    MerkleLeftSelection { limb: u8 },
    MerkleRightSelection { limb: u8 },
    InputValueReconstruction,
    OutputValueReconstruction,
    Balance,
    PublicAnchor { limb: u8 },
    PublicNullifier { limb: u8 },
    PublicOutputCommitment { limb: u8 },
    PublicInputAsset,
    PublicOutputAsset,
    CopyLogUp,
    RangeLogUp,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct ConstraintDescriptor {
    pub id: ConstraintId,
    pub kind: ConstraintKind,
}

pub fn constraint_registry() -> Vec<ConstraintDescriptor> {
    (0..CONSTRAINT_COUNT)
        .map(|index| {
            let id = ConstraintId::new(index).expect("registry index is in range");
            let kind = if index < POSEIDON_SECOND_START {
                ConstraintKind::PoseidonFirst {
                    lane: (index - POSEIDON_FIRST_START) as u8,
                }
            } else if index < INITIAL_STATE_START {
                ConstraintKind::PoseidonSecond {
                    lane: (index - POSEIDON_SECOND_START) as u8,
                }
            } else if index < PADDING_ZERO_START {
                ConstraintKind::InitialSpongeState {
                    lane: (index - INITIAL_STATE_START) as u8,
                }
            } else if index < ABSORPTION_TAIL_START {
                ConstraintKind::PaddingZero {
                    column: (index - PADDING_ZERO_START) as u8,
                }
            } else if index < SOURCE_EQUALITY_START {
                ConstraintKind::AbsorptionTailZero {
                    column: (index - ABSORPTION_TAIL_START) as u8,
                }
            } else if index < MERKLE_BIT_BOOLEAN_ID {
                ConstraintKind::SourceEquality {
                    binding: (index - SOURCE_EQUALITY_START) as u8,
                }
            } else if index == MERKLE_BIT_BOOLEAN_ID {
                ConstraintKind::MerklePathBitBoolean
            } else if index < MERKLE_RIGHT_START {
                ConstraintKind::MerkleLeftSelection {
                    limb: (index - MERKLE_LEFT_START) as u8,
                }
            } else if index < INPUT_VALUE_RECONSTRUCTION_ID {
                ConstraintKind::MerkleRightSelection {
                    limb: (index - MERKLE_RIGHT_START) as u8,
                }
            } else if index == INPUT_VALUE_RECONSTRUCTION_ID {
                ConstraintKind::InputValueReconstruction
            } else if index == OUTPUT_VALUE_RECONSTRUCTION_ID {
                ConstraintKind::OutputValueReconstruction
            } else if index == BALANCE_ID {
                ConstraintKind::Balance
            } else if index < PUBLIC_NULLIFIER_START {
                ConstraintKind::PublicAnchor {
                    limb: (index - PUBLIC_ANCHOR_START) as u8,
                }
            } else if index < PUBLIC_OUTPUT_START {
                ConstraintKind::PublicNullifier {
                    limb: (index - PUBLIC_NULLIFIER_START) as u8,
                }
            } else if index < PUBLIC_INPUT_ASSET_ID {
                ConstraintKind::PublicOutputCommitment {
                    limb: (index - PUBLIC_OUTPUT_START) as u8,
                }
            } else if index == PUBLIC_INPUT_ASSET_ID {
                ConstraintKind::PublicInputAsset
            } else if index == PUBLIC_OUTPUT_ASSET_ID {
                ConstraintKind::PublicOutputAsset
            } else if index == COPY_LOGUP_ID {
                ConstraintKind::CopyLogUp
            } else {
                ConstraintKind::RangeLogUp
            };
            ConstraintDescriptor { id, kind }
        })
        .collect()
}

