    fn random_m31(random: &mut impl std::io::Read) -> M31 {
        loop {
            let mut bytes = [0u8; 4];
            random.read_exact(&mut bytes).expect("OS random source");
            let candidate = u32::from_le_bytes(bytes);
            if candidate < P {
                return M31(candidate);
            }
        }
    }

