                compose_direct_range_terminal_packed_residuals(
                    &direct_packed,
                    copy,
                    &direct_range,
                    theta,
                ),
            );
            assert_eq!(
                radix8_coefficients.len(),
                DIRECT_RANGE_RANDOMIZED_CONSTRAINT_COUNT
            );
        }
    }

    #[test]
    fn honest_payment_trace_zeroes_every_registered_polynomial() {
        let (public, witness) = fixture();
