        let mut bad_bit = trace.clone();
        apply_direct_range_witness_v4(&mut bad_bit).unwrap();
        bad_bit.c1[0][DIRECT_RANGE_BIT_ROW_START] = M31(2);
        assert!(matches!(
            verify_direct_range_witness_v4(&bad_bit),
            Err(DirectRangeHidingError::Bitness { .. })
