#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum PoolV1PairForestAccountErrorV1 {
    WrongLength,
    WrongMagic,
    WrongVersion,
    WrongLaneCount,
    WrongDigestEncoding,
    WrongDepth,
    WrongFormatBinding,
    NonZeroReserved,
    ZeroRequiredBinding,
    InvalidBoolean,
    InvalidMasterState,
    InvalidLane,
