    Identity,
    Policy,
    Tree(PoolV1TreeError),
}

impl From<PoolV1TreeError> for PoolV1PairForestAccountErrorV1 {
    fn from(error: PoolV1TreeError) -> Self {
        Self::Tree(error)
    }
}

