    #[test]
    fn boolean_extraction_is_exact_and_fail_closed() {
        let mut rng = Rng(0x626f_6f6c_6561_6e31);
        for (variant_byte, variant) in [
            (0, PoolV1PairForestCompiledVariantV1::PrivateTransfer),
            (1, PoolV1PairForestCompiledVariantV1::Withdrawal),
        ] {
            for row in [0u16, 11, 412, 912, 1008, 1023] {
                let openings = core::array::from_fn(|_| rng.qm31());
                let h1_z = rng.qm31();
                let lambda = rng.qm31();
                let chi = rng.qm31();
                let append_index = rng.next() & ((1 << 20) - 1);
                let point = core::array::from_fn(|coordinate| {
                    if (usize::from(row) >> (9 - coordinate)) & 1 == 0 {
                        QM31::ZERO
                    } else {
                        QM31::ONE
                    }
                });
                let expected = evaluate_pool_v1_pair_forest_copy_terminal_compiled_v1(
                    &openings,
                    h1_z,
                    &point,
                    lambda,
                    chi,
                    append_index,
                    variant,
                );
                assert_eq!(
                    pool_v1_pair_forest_copy_lane_boolean_extraction_v1(
                        variant_byte,
                        row,
                        &openings,
                        h1_z,
                        lambda,
                        chi,
                        append_index,
                    ),
                    Some(expected),
                );
            }
        }
        let zero = [QM31::ZERO; 16];
        assert_eq!(
            pool_v1_pair_forest_copy_lane_boolean_extraction_v1(
                2,
                0,
                &zero,
                QM31::ZERO,
                QM31::ZERO,
                QM31::ZERO,
                0,
            ),
            None,
        );
        assert_eq!(
            pool_v1_pair_forest_copy_lane_boolean_extraction_v1(
                0,
                1024,
                &zero,
                QM31::ZERO,
                QM31::ZERO,
                QM31::ZERO,
                0,
            ),
            None,
        );
    }
}

//! Production-inactive row/masking inventory for the eight-lane pair forest.
//!
//! The existing pair profile uses blocks `0..=53` for Poseidon, blocks
//! `54..=59` for 21 private path directions, and block `60` for value and
//! occupancy auxiliaries.  A literal use of blocks `61..=63` for the three
//! new parents is raw-opening-rank deficient.  The forest therefore permutes
//! the same ten-block tail: blocks `54..=56` are the three historical
//! lane-to-super-root parents, blocks `57..=62` carry all 24 private
//! directions, and block `63` carries value and occupancy auxiliaries.  Each
//! direction uses a subset of the frozen three-opening geometry: current/bit
//! at `r` and ordered children at `successor(r)`. Boolean gating binds the
//! selected child to the current digest; the other child is the sibling
//! witness itself, avoiding a redundant sibling copy. Four paths occupy local
//! base rows `1,5,9,13` in every auxiliary block.
//!
//! This is a layout gate only.  It does not activate a profile, change the
//! prover, or claim that the resulting mask map has full rank.  The prover
//! rank gate consumes this exact inventory separately.

use alloc::vec::Vec;

use crate::trace_v4::TraceCell;

use super::{
    pair_tree_hiding::{
        build_pool_v1_pair_copy_row_schedule_v1, pool_v1_pair_aux_cell_is_relation_used_v1,
        PoolV1PairCopyRowLinkKindV1, PoolV1PairCopyRowLinkV1, PoolV1PairHidingLayoutErrorV1,
        POOL_V1_PAIR_RELATION_FREE_PADDING_LOCAL_ROW_START_V1,
    },
    pair_tree_profile::{
        POOL_V1_PAIR_DIRECTIONS_PER_AUX_BLOCK, POOL_V1_PAIR_TRACE_BLOCK_ROWS,
        POOL_V1_PAIR_TRACE_COLUMNS, POOL_V1_PAIR_TRACE_ROWS,
    },
};

pub const POOL_V1_PAIR_FOREST_LANES_V1: usize = 8;
pub const POOL_V1_PAIR_FOREST_SUPER_ROOT_DEPTH_V1: usize = 3;
pub const POOL_V1_PAIR_FOREST_PRIVATE_DIRECTIONS_V1: usize = 24;
pub const POOL_V1_PAIR_FOREST_FIRST_SUPER_ROOT_BLOCK_V1: usize = 54;
pub const POOL_V1_PAIR_FOREST_POSEIDON_BLOCKS_V1: usize = 57;
pub const POOL_V1_PAIR_FOREST_PATH_AUX_ROW_START_V1: usize = 57 * 16;
pub const POOL_V1_PAIR_FOREST_PATH_AUX_ROW_END_V1: usize = 63 * 16;
pub const POOL_V1_PAIR_FOREST_VALUE_AUX_ROW_START_V1: usize = 63 * 16;
pub const POOL_V1_PAIR_FOREST_INPUT_OCCUPANCY_AUX_ROW_V1: usize = 63 * 16 + 9;
pub const POOL_V1_PAIR_FOREST_OUTPUT_OCCUPANCY_AUX_ROW_V1: usize = 63 * 16 + 10;
pub const POOL_V1_PAIR_FOREST_SEMANTIC_ROW_END_V1: usize = 64 * 16;
pub const POOL_V1_PAIR_FOREST_COPY_ROW_LINKS_V1: usize = 136;
pub const POOL_V1_PAIR_FOREST_COPY_ACTIVE_ROWS_V1: usize = 214;
pub const POOL_V1_PAIR_FOREST_RELATION_FREE_MASK_CELLS_V1: usize = 3_803;
pub const PINNED_POOL_V1_PAIR_FOREST_COPY_ROW_SCHEDULE_FINGERPRINT_V1: u64 = 0x4808_09b8_3677_8dc6;
pub const PINNED_POOL_V1_PAIR_FOREST_COPY_ACTIVE_ROWS_FINGERPRINT_V1: u64 = 0xdf39_4a5a_8554_d09c;
pub const PINNED_POOL_V1_PAIR_FOREST_RELATION_FREE_MASK_FINGERPRINT_V1: u64 = 0xf9da_f3d5_4f42_85d1;

const POOL_V1_PAIR_FOREST_PATH_BASE_LOCAL_ROWS_V1: [[usize; 4]; 6] = [
    [1, 5, 9, 13],
    [1, 5, 9, 13],
    [1, 5, 9, 13],
    [1, 5, 9, 13],
    [1, 5, 9, 13],
    [1, 5, 9, 13],
];

#[inline]
pub const fn pool_v1_pair_forest_path_base_row_v1(level: usize) -> Option<usize> {
    if level >= POOL_V1_PAIR_FOREST_PRIVATE_DIRECTIONS_V1 {
        return None;
    }
    Some(
        POOL_V1_PAIR_FOREST_PATH_AUX_ROW_START_V1
            + (level / POOL_V1_PAIR_DIRECTIONS_PER_AUX_BLOCK) * POOL_V1_PAIR_TRACE_BLOCK_ROWS
            + POOL_V1_PAIR_FOREST_PATH_BASE_LOCAL_ROWS_V1
                [level / POOL_V1_PAIR_DIRECTIONS_PER_AUX_BLOCK]
                [level % POOL_V1_PAIR_DIRECTIONS_PER_AUX_BLOCK],
    )
}

#[inline]
pub const fn pool_v1_pair_forest_membership_hash_block_v1(level: usize) -> Option<usize> {
    if level >= POOL_V1_PAIR_FOREST_PRIVATE_DIRECTIONS_V1 {
        None
    } else if level <= 20 {
        Some(4 + level)
    } else {
        Some(33 + level)
    }
}

#[inline]
fn link(
    kind: PoolV1PairCopyRowLinkKindV1,
    producer_row: usize,
    consumer_row: usize,
) -> PoolV1PairCopyRowLinkV1 {
    PoolV1PairCopyRowLinkV1 {
        kind,
        producer_row: producer_row as u16,
        consumer_row: consumer_row as u16,
    }
}

fn endpoint_counts(
    links: &[PoolV1PairCopyRowLinkV1],
) -> Result<([u8; 1024], [u8; 1024]), PoolV1PairHidingLayoutErrorV1> {
    let mut producers = [0u8; 1024];
    let mut consumers = [0u8; 1024];
    for link in links {
        for (row, counts) in [
            (usize::from(link.producer_row), &mut producers),
            (usize::from(link.consumer_row), &mut consumers),
        ] {
            if row >= POOL_V1_PAIR_TRACE_ROWS || counts[row] >= 2 {
                return Err(PoolV1PairHidingLayoutErrorV1::EndpointCapacity { row: row as u16 });
            }
            counts[row] += 1;
        }
    }
    Ok((producers, consumers))
}

pub fn build_pool_v1_pair_forest_copy_row_schedule_v1(
) -> Result<Vec<PoolV1PairCopyRowLinkV1>, PoolV1PairHidingLayoutErrorV1> {
    let mut links = build_pool_v1_pair_copy_row_schedule_v1()?
        .into_iter()
        .filter(|scheduled| {
            !matches!(
                scheduled.kind,
                PoolV1PairCopyRowLinkKindV1::PrivatePathCurrent { .. }
                    | PoolV1PairCopyRowLinkKindV1::PrivatePathLeft { .. }
                    | PoolV1PairCopyRowLinkKindV1::PrivatePathRight { .. }
            )
        })
        .collect::<Vec<_>>();
    // The existing schedule's auxiliary endpoints live in rows 864..975.
    // Move that complete seven-block region forward by three blocks while
    // leaving every existing Poseidon endpoint unchanged.
    for scheduled in &mut links {
        if usize::from(scheduled.producer_row) >= 54 * POOL_V1_PAIR_TRACE_BLOCK_ROWS {
            scheduled.producer_row += 3 * POOL_V1_PAIR_TRACE_BLOCK_ROWS as u16;
        }
        if usize::from(scheduled.consumer_row) >= 54 * POOL_V1_PAIR_TRACE_BLOCK_ROWS {
            scheduled.consumer_row += 3 * POOL_V1_PAIR_TRACE_BLOCK_ROWS as u16;
        }
    }
    links.reserve(3 * POOL_V1_PAIR_FOREST_PRIVATE_DIRECTIONS_V1);
    for level in 0..POOL_V1_PAIR_FOREST_PRIVATE_DIRECTIONS_V1 {
        let auxiliary = pool_v1_pair_forest_path_base_row_v1(level)
            .ok_or(PoolV1PairHidingLayoutErrorV1::Shape)?;
        let target_block = pool_v1_pair_forest_membership_hash_block_v1(level)
            .ok_or(PoolV1PairHidingLayoutErrorV1::Shape)?;
        let previous_block = if level == 0 {
            3
        } else {
            pool_v1_pair_forest_membership_hash_block_v1(level - 1)
                .ok_or(PoolV1PairHidingLayoutErrorV1::Shape)?
        };
        links.push(link(
            PoolV1PairCopyRowLinkKindV1::PrivatePathCurrent { level: level as u8 },
            previous_block * POOL_V1_PAIR_TRACE_BLOCK_ROWS + 11,
            auxiliary,
        ));
        links.push(link(
            PoolV1PairCopyRowLinkKindV1::PrivatePathLeft { level: level as u8 },
            auxiliary + 1,
            target_block * POOL_V1_PAIR_TRACE_BLOCK_ROWS + 12,
        ));
        links.push(link(
            PoolV1PairCopyRowLinkKindV1::PrivatePathRight { level: level as u8 },
            auxiliary + 1,
            target_block * POOL_V1_PAIR_TRACE_BLOCK_ROWS,
        ));
    }
    if links.len() != POOL_V1_PAIR_FOREST_COPY_ROW_LINKS_V1 {
        return Err(PoolV1PairHidingLayoutErrorV1::Shape);
    }
    endpoint_counts(&links)?;
    Ok(links)
}

pub fn pool_v1_pair_forest_copy_active_rows_v1() -> Result<Vec<u16>, PoolV1PairHidingLayoutErrorV1>
{
    let mut rows = build_pool_v1_pair_forest_copy_row_schedule_v1()?
        .into_iter()
        .flat_map(|link| [link.producer_row, link.consumer_row])
        .collect::<Vec<_>>();
    rows.sort_unstable();
    rows.dedup();
    Ok(rows)
}

pub fn pool_v1_pair_forest_copy_active_row_masks_v1(
) -> Result<[u16; 64], PoolV1PairHidingLayoutErrorV1> {
    let mut masks = [0u16; 64];
    for row in pool_v1_pair_forest_copy_active_rows_v1()? {
        masks[usize::from(row) >> 4] |= 1 << (usize::from(row) & 15);
    }
    Ok(masks)
}

pub fn pool_v1_pair_forest_copy_inactive_row_masks_v1(
) -> Result<[u16; 64], PoolV1PairHidingLayoutErrorV1> {
    Ok(pool_v1_pair_forest_copy_active_row_masks_v1()?.map(|mask| !mask))
}

fn forest_path_aux_cell_is_used(row: usize, column: usize) -> bool {
    for level in 0..POOL_V1_PAIR_FOREST_PRIVATE_DIRECTIONS_V1 {
        let Some(base) = pool_v1_pair_forest_path_base_row_v1(level) else {
            return false;
        };
        if (row == base && column <= 8) || row == base + 1 {
            return true;
        }
    }
    false
}

#[inline]
fn forest_poseidon_row(row: usize) -> bool {
    row < POOL_V1_PAIR_FOREST_POSEIDON_BLOCKS_V1 * POOL_V1_PAIR_TRACE_BLOCK_ROWS
}

fn forest_aux_cell_is_used(row: usize, column: usize) -> bool {
    if row < POOL_V1_PAIR_FOREST_PATH_AUX_ROW_START_V1 {
        return false;
    }
    if row < POOL_V1_PAIR_FOREST_VALUE_AUX_ROW_START_V1 {
        forest_path_aux_cell_is_used(row, column)
    } else {
        let translated = row - 3 * POOL_V1_PAIR_TRACE_BLOCK_ROWS;
        pool_v1_pair_aux_cell_is_relation_used_v1(translated, column)
    }
}

pub fn pool_v1_pair_forest_relation_free_mask_cells_v1(
) -> Result<Vec<TraceCell>, PoolV1PairHidingLayoutErrorV1> {
    let _ = build_pool_v1_pair_forest_copy_row_schedule_v1()?;
    let mut cells = Vec::new();
    for column in 0..POOL_V1_PAIR_TRACE_COLUMNS {
        for row in 0..POOL_V1_PAIR_TRACE_ROWS {
            let poseidon = forest_poseidon_row(row);
            let padding = poseidon
                && row % POOL_V1_PAIR_TRACE_BLOCK_ROWS
                    >= POOL_V1_PAIR_RELATION_FREE_PADDING_LOCAL_ROW_START_V1;
            let auxiliary = !poseidon && !forest_aux_cell_is_used(row, column);
            if padding || auxiliary {
                cells.push(TraceCell {
                    row: row as u16,
                    column: column as u8,
                });
            }
        }
    }
    Ok(cells)
}

fn fingerprint_bytes<'a>(bytes: impl IntoIterator<Item = &'a u8>) -> u64 {
    let mut hash = 0xcbf2_9ce4_8422_2325u64;
    for byte in bytes {
        hash ^= u64::from(*byte);
        hash = hash.wrapping_mul(0x0000_0100_0000_01b3);
    }
    hash
}

fn copy_kind_code(kind: PoolV1PairCopyRowLinkKindV1) -> [u8; 3] {
    match kind {
        PoolV1PairCopyRowLinkKindV1::SpongeCarry { from, to } => [0, from, to],
        PoolV1PairCopyRowLinkKindV1::OwnerOutput => [1, 0, 0],
        PoolV1PairCopyRowLinkKindV1::NullifierKey => [2, 0, 0],
        PoolV1PairCopyRowLinkKindV1::InputSaltHead => [3, 0, 0],
        PoolV1PairCopyRowLinkKindV1::InputSaltTail => [4, 0, 0],
        PoolV1PairCopyRowLinkKindV1::PrivatePathCurrent { level } => [5, level, 0],
        PoolV1PairCopyRowLinkKindV1::PrivatePathLeft { level } => [6, level, 0],
        PoolV1PairCopyRowLinkKindV1::PrivatePathRight { level } => [7, level, 0],
        PoolV1PairCopyRowLinkKindV1::ValueSource { value } => [8, value, 0],
        PoolV1PairCopyRowLinkKindV1::ConservationInput => [9, 0, 0],
        PoolV1PairCopyRowLinkKindV1::ConservationRecipient => [10, 0, 0],
        PoolV1PairCopyRowLinkKindV1::ConservationChange => [11, 0, 0],
        PoolV1PairCopyRowLinkKindV1::ConservationPartial => [12, 0, 0],
        PoolV1PairCopyRowLinkKindV1::InputSecondCommitment => [13, 0, 0],
        PoolV1PairCopyRowLinkKindV1::InputSelectedSide => [14, 0, 0],
        PoolV1PairCopyRowLinkKindV1::OutputSecondCommitment => [15, 0, 0],
        PoolV1PairCopyRowLinkKindV1::OutputPairFirst => [16, 0, 0],
        PoolV1PairCopyRowLinkKindV1::OutputPairFirstWithdrawal => [17, 0, 0],
        PoolV1PairCopyRowLinkKindV1::OutputPairSecond => [18, 0, 0],
        PoolV1PairCopyRowLinkKindV1::AppendCurrentLeft { level } => [19, level, 0],
        PoolV1PairCopyRowLinkKindV1::AppendCurrentRight { level } => [20, level, 0],
    }
}

pub fn pool_v1_pair_forest_copy_row_schedule_fingerprint_v1(
) -> Result<u64, PoolV1PairHidingLayoutErrorV1> {
    let bytes = build_pool_v1_pair_forest_copy_row_schedule_v1()?
        .into_iter()
        .flat_map(|link| {
            let kind = copy_kind_code(link.kind);
            let producer = link.producer_row.to_le_bytes();
            let consumer = link.consumer_row.to_le_bytes();
            [
                kind[0],
                kind[1],
                kind[2],
                producer[0],
                producer[1],
                consumer[0],
                consumer[1],
            ]
        })
        .collect::<Vec<_>>();
    Ok(fingerprint_bytes(bytes.iter()))
}

pub fn pool_v1_pair_forest_copy_active_rows_fingerprint_v1(
) -> Result<u64, PoolV1PairHidingLayoutErrorV1> {
    let bytes = pool_v1_pair_forest_copy_active_rows_v1()?
        .into_iter()
        .flat_map(u16::to_le_bytes)
        .collect::<Vec<_>>();
    Ok(fingerprint_bytes(bytes.iter()))
}

pub fn pool_v1_pair_forest_relation_free_mask_fingerprint_v1(
) -> Result<u64, PoolV1PairHidingLayoutErrorV1> {
    let bytes = pool_v1_pair_forest_relation_free_mask_cells_v1()?
        .into_iter()
        .flat_map(|cell| {
            let row = cell.row.to_le_bytes();
            [row[0], row[1], cell.column]
        })
        .collect::<Vec<_>>();
    Ok(fingerprint_bytes(bytes.iter()))
}

const _: () = assert!(POOL_V1_PAIR_FOREST_LANES_V1 == 1 << 3);
const _: () = assert!(POOL_V1_PAIR_FOREST_PRIVATE_DIRECTIONS_V1 == 6 * 4);
const _: () = assert!(POOL_V1_PAIR_FOREST_FIRST_SUPER_ROOT_BLOCK_V1 * 16 == 864);
const _: () = assert!(POOL_V1_PAIR_FOREST_POSEIDON_BLOCKS_V1 == 54 + 3);
const _: () = assert!(POOL_V1_PAIR_FOREST_SEMANTIC_ROW_END_V1 == POOL_V1_PAIR_TRACE_ROWS);

#[cfg(test)]
mod tests {
    use super::*;
    use std::println;

    fn contains(cells: &[TraceCell], row: usize, column: usize) -> bool {
        cells
            .binary_search_by_key(&(column as u8, row as u16), |cell| (cell.column, cell.row))
            .is_ok()
    }

    #[test]
    fn every_private_path_uses_distinct_frozen_z_and_successor_rows() {
        let mut occupied = [false; POOL_V1_PAIR_TRACE_ROWS];
        for level in 0..POOL_V1_PAIR_FOREST_PRIVATE_DIRECTIONS_V1 {
            let base = pool_v1_pair_forest_path_base_row_v1(level).unwrap();
            for row in [base, base + 1] {
                assert_eq!(base >> 4, row >> 4);
                assert!(!occupied[row], "path row collision at {row}");
                occupied[row] = true;
            }
        }
    }

    #[test]
    fn exact_forest_layout_inventory() {
        let schedule = build_pool_v1_pair_forest_copy_row_schedule_v1().unwrap();
        let active = pool_v1_pair_forest_copy_active_rows_v1().unwrap();
        let masks = pool_v1_pair_forest_relation_free_mask_cells_v1().unwrap();
        assert_eq!(schedule.len(), 136);
        assert_eq!(active.len(), POOL_V1_PAIR_FOREST_COPY_ACTIVE_ROWS_V1);
        assert_eq!(masks.len(), POOL_V1_PAIR_FOREST_RELATION_FREE_MASK_CELLS_V1);
        assert_eq!(pool_v1_pair_forest_path_base_row_v1(21), Some(997));
        assert_eq!(pool_v1_pair_forest_path_base_row_v1(22), Some(1001));
        assert_eq!(pool_v1_pair_forest_path_base_row_v1(23), Some(1005));
        assert_eq!(pool_v1_pair_forest_membership_hash_block_v1(21), Some(54));
        assert_eq!(pool_v1_pair_forest_membership_hash_block_v1(22), Some(55));
        assert_eq!(pool_v1_pair_forest_membership_hash_block_v1(23), Some(56));
        assert!(!contains(&masks, 864, 0));
        assert!(!contains(&masks, 876, 0));
        assert!(contains(&masks, 877, 0));
        assert!(!contains(&masks, 997, 0));
        assert_eq!(
            pool_v1_pair_forest_copy_row_schedule_fingerprint_v1().unwrap(),
            PINNED_POOL_V1_PAIR_FOREST_COPY_ROW_SCHEDULE_FINGERPRINT_V1
        );
        assert_eq!(
            pool_v1_pair_forest_copy_active_rows_fingerprint_v1().unwrap(),
            PINNED_POOL_V1_PAIR_FOREST_COPY_ACTIVE_ROWS_FINGERPRINT_V1
        );
        assert_eq!(
            pool_v1_pair_forest_relation_free_mask_fingerprint_v1().unwrap(),
            PINNED_POOL_V1_PAIR_FOREST_RELATION_FREE_MASK_FINGERPRINT_V1
        );
        println!(
            "forest links={} active={} masks={} copy_fp={:#018x} active_fp={:#018x} mask_fp={:#018x}",
            schedule.len(),
            active.len(),
            masks.len(),
            pool_v1_pair_forest_copy_row_schedule_fingerprint_v1().unwrap(),
            pool_v1_pair_forest_copy_active_rows_fingerprint_v1().unwrap(),
            pool_v1_pair_forest_relation_free_mask_fingerprint_v1().unwrap(),
        );
    }
}

//! Exact copy-helper foundation for the eight-lane pair-forest oracle.
//!
//! This module deliberately does not activate a verifier profile.  It gives
//! the honest prover and the eventual compiled terminal one shared source of
//! truth for the forest copy table, helper, and active-row polynomial.

use alloc::{vec, vec::Vec};

use aspis_core::field::{M31, QM31};

use crate::state_only_poseidon::StateOnlyPoseidonOpenings;
use crate::{constraints_v4::multilinear_evaluate, logup::build_copy_logup_helper};

use super::{
    pair_forest_hiding::pool_v1_pair_forest_copy_active_rows_v1,
    pair_forest_hiding::{
        pool_v1_pair_forest_path_base_row_v1, POOL_V1_PAIR_FOREST_PRIVATE_DIRECTIONS_V1,
    },
    pair_forest_trace::{
        build_pool_v1_pair_forest_copy_registry_v1, pool_v1_pair_forest_copy_rows_v1,
        PoolV1PairForestTraceV1,
    },
    pair_trace::{
        PoolV1PairCopyTupleV1, PoolV1PairCopyWeightV1, PoolV1PairTraceErrorV1,
        PoolV1PairTraceVariantV1, PoolV1PairTupleLimbV1,
    },
    pair_tree_profile::POOL_V1_PAIR_TRACE_ROWS,
};

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct PoolV1PairForestCopyTerminalV1 {
    pub residual: QM31,
    pub active: QM31,
}

/// The 17 non-Poseidon lanes for all 24 private membership directions.  The
/// row selector aggregates the same equation over every path slot, matching
/// the legacy payment terminal without adding a claim.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct PoolV1PairForestPathTerminalV1 {
    pub direction_booleanity: QM31,
    pub ordered_children: [QM31; 16],
}

#[derive(Clone, Copy)]
struct CopyRowExtensionV1 {
    producer_values: [QM31; 2],
    producer_weights: [QM31; 2],
    consumer_values: [QM31; 2],
    consumer_weights: [QM31; 2],
}

#[inline]
fn lift(value: M31) -> QM31 {
    QM31::from_cm31(aspis_core::field::CM31::from_m31(value))
}

#[inline]
fn eq_row(point: &[QM31; 10], row: usize) -> QM31 {
    point
        .iter()
        .enumerate()
        .fold(QM31::ONE, |weight, (coordinate, value)| {
            let bit = (row >> (point.len() - 1 - coordinate)) & 1;
            weight.mul(if bit == 0 {
                QM31::ONE.sub(*value)
            } else {
                *value
            })
        })
}

/// Evaluate all 24 private path ordering equations from the frozen
/// `(z, successor(z))` subset of the frozen three-opening geometry. This is
/// intentionally a separate cheap source-layout gate as well as a component
/// of the compiled forest terminal: the unselected child is the sibling
/// witness itself, so no redundant sibling copy or extra PCS opening is
/// required.
pub fn evaluate_pool_v1_pair_forest_path_terminal_v1(
    openings: &StateOnlyPoseidonOpenings,
    point: &[QM31; 10],
) -> Result<PoolV1PairForestPathTerminalV1, PoolV1PairTraceErrorV1> {
    let selector =
        (0..POOL_V1_PAIR_FOREST_PRIVATE_DIRECTIONS_V1).try_fold(QM31::ZERO, |sum, level| {
            pool_v1_pair_forest_path_base_row_v1(level)
                .map(|row| sum.add(eq_row(point, row)))
                .ok_or(PoolV1PairTraceErrorV1::Shape)
        })?;
    let bit = openings.z[0];
    let mut ordered_children = [QM31::ZERO; 16];
    for lane in 0..8 {
        let current = openings.z[1 + lane];
        ordered_children[lane] = selector
            .mul(QM31::ONE.sub(bit))
            .mul(openings.succ_z[lane].sub(current));
        ordered_children[8 + lane] = selector
            .mul(bit)
            .mul(openings.succ_z[8 + lane].sub(current));
    }
    Ok(PoolV1PairForestPathTerminalV1 {
        direction_booleanity: selector.mul(bit.mul(bit.sub(QM31::ONE))),
        ordered_children,
    })
}

fn copy_weight(
    weight: PoolV1PairCopyWeightV1,
    append_index: u64,
    variant: PoolV1PairTraceVariantV1,
) -> M31 {
    match weight {
        PoolV1PairCopyWeightV1::One => M31::ONE,
        PoolV1PairCopyWeightV1::PrivateTransferOnly => M31(u32::from(
            variant == PoolV1PairTraceVariantV1::PrivateTransfer,
        )),
        PoolV1PairCopyWeightV1::WithdrawalOnly => {
            M31(u32::from(variant == PoolV1PairTraceVariantV1::Withdrawal))
        }
        PoolV1PairCopyWeightV1::AppendCurrentLeft { level } => {
            M31(1 - ((append_index >> level) & 1) as u32)
        }
        PoolV1PairCopyWeightV1::AppendCurrentRight { level } => {
            M31(((append_index >> level) & 1) as u32)
        }
    }
}

fn compressed_opened_tuple(
    tuple: PoolV1PairCopyTupleV1,
    tag: M31,
    selector: QM31,
    openings: &[QM31; 16],
    powers: &[QM31; 16],
) -> QM31 {
    let mut value = selector.mul_m31(tag);
    for (limb, power) in tuple.limbs.into_iter().zip(powers) {
        let opened = match limb {
            PoolV1PairTupleLimbV1::Zero => QM31::ZERO,
            PoolV1PairTupleLimbV1::Cell { source, offset } => {
                openings[usize::from(source.cell.column)].add(lift(offset))
            }
        };
        value = value.add(selector.mul(opened).mul(*power));
    }
    value
}

fn copy_residual(row: CopyRowExtensionV1, helper: QM31, chi: QM31) -> QM31 {
    let denominator = [
        chi.sub(row.producer_values[0]),
        chi.sub(row.producer_values[1]),
        chi.sub(row.consumer_values[0]),
        chi.sub(row.consumer_values[1]),
    ];
    let producer_denominator = denominator[0].mul(denominator[1]);
    let consumer_denominator = denominator[2].mul(denominator[3]);
    let producer_numerator = row.producer_weights[0]
        .mul(denominator[1])
        .add(row.producer_weights[1].mul(denominator[0]));
    let consumer_numerator = row.consumer_weights[0]
        .mul(denominator[3])
        .add(row.consumer_weights[1].mul(denominator[2]));
    producer_denominator
        .mul(helper.mul(consumer_denominator).add(consumer_numerator))
        .sub(consumer_denominator.mul(producer_numerator))
}

/// Construct the unique forest LogUp helper from the literal typed copy
/// registry.  The append index remains an explicit input because append-side
/// links are selected by its live lane-path bits.
pub fn build_pool_v1_pair_forest_copy_helper_v1(
    trace: &PoolV1PairForestTraceV1,
    append_index: u64,
    lambda: QM31,
    chi: QM31,
) -> Result<Vec<QM31>, PoolV1PairTraceErrorV1> {
    let rows = pool_v1_pair_forest_copy_rows_v1(trace, append_index, lambda)?;
    build_copy_logup_helper(&rows, chi).map_err(|_| PoolV1PairTraceErrorV1::CopyImbalance)
}

/// Evaluate the exact forest copy lane from the sixteen merged-C1 openings
/// and one H1 opening used by the selected Tag-73 terminal.  Stable and late
/// banks intentionally share the same opening vector: bank disjointness is
/// checked before C1 commitment by the merged-trace compiler.
pub fn evaluate_pool_v1_pair_forest_copy_terminal_v1(
    openings: &[QM31; 16],
    h1_z: QM31,
    point: &[QM31; 10],
    lambda: QM31,
    chi: QM31,
    append_index: u64,
    variant: PoolV1PairTraceVariantV1,
) -> Result<PoolV1PairForestCopyTerminalV1, PoolV1PairTraceErrorV1> {
    let registry = build_pool_v1_pair_forest_copy_registry_v1()?;
    let mut powers = [QM31::ZERO; 16];
    let mut power = lambda;
    for output in &mut powers {
        *output = power;
        power = power.mul(lambda);
    }
    let mut row = CopyRowExtensionV1 {
        producer_values: [QM31::ZERO; 2],
        producer_weights: [QM31::ZERO; 2],
        consumer_values: [QM31::ZERO; 2],
        consumer_weights: [QM31::ZERO; 2],
    };
    let mut producer_arity = [0u8; POOL_V1_PAIR_TRACE_ROWS];
    let mut consumer_arity = [0u8; POOL_V1_PAIR_TRACE_ROWS];
    let mut active_rows = [false; POOL_V1_PAIR_TRACE_ROWS];
    for link in registry {
        let weight = copy_weight(link.weight, append_index, variant);
        for (tuple, arity, values, weights) in [
            (
                link.producer,
                &mut producer_arity,
                &mut row.producer_values,
                &mut row.producer_weights,
            ),
            (
                link.consumer,
                &mut consumer_arity,
                &mut row.consumer_values,
                &mut row.consumer_weights,
            ),
        ] {
            let endpoint_row = usize::from(tuple.row);
            let slot = usize::from(arity[endpoint_row]);
            if slot >= 2 {
                return Err(PoolV1PairTraceErrorV1::CopyLayout);
            }
            arity[endpoint_row] += 1;
            active_rows[endpoint_row] = true;
            let selector = eq_row(point, endpoint_row);
            weights[slot] = weights[slot].add(selector.mul_m31(weight));
            values[slot] = values[slot].add(compressed_opened_tuple(
                tuple, link.tag, selector, openings, &powers,
            ));
        }
    }
    let active = active_rows
        .into_iter()
        .enumerate()
        .filter(|(_, active)| *active)
        .fold(QM31::ZERO, |sum, (row, _)| sum.add(eq_row(point, row)));
    Ok(PoolV1PairForestCopyTerminalV1 {
        residual: active.mul(copy_residual(row, h1_z, chi)),
        active,
    })
}

/// Evaluate the exact multilinear indicator of rows carrying at least one
/// endpoint in the forest copy registry.  The same row inventory is used by
/// mask balancing, so inactive helper padding cannot be confused with a
/// constrained LogUp row.
pub fn pool_v1_pair_forest_copy_active_at_point_v1(
    point: &[QM31; 10],
) -> Result<QM31, PoolV1PairTraceErrorV1> {
    let mut active = vec![M31::ZERO; POOL_V1_PAIR_TRACE_ROWS];
    for row in
        pool_v1_pair_forest_copy_active_rows_v1().map_err(|_| PoolV1PairTraceErrorV1::CopyLayout)?
    {
        active[usize::from(row)] = M31::ONE;
    }
    multilinear_evaluate(&active, point).ok_or(PoolV1PairTraceErrorV1::Shape)
}

pub fn pool_v1_pair_forest_copy_helper_sum_v1(h1: &[QM31]) -> Option<QM31> {
    (h1.len() == POOL_V1_PAIR_TRACE_ROWS).then(|| h1.iter().copied().fold(QM31::ZERO, QM31::add))
}

#[cfg(test)]
mod tests {
    use super::*;

    fn q(value: u32) -> QM31 {
        lift(M31(value))
    }

    fn boolean_point(row: usize) -> [QM31; 10] {
        core::array::from_fn(|coordinate| q(((row >> (9 - coordinate)) & 1) as u32))
    }

    #[test]
    fn path_terminal_is_exact_on_each_authenticated_path_slot() {
        for level in 0..POOL_V1_PAIR_FOREST_PRIVATE_DIRECTIONS_V1 {
            let base = pool_v1_pair_forest_path_base_row_v1(level).unwrap();
            let current: [QM31; 8] = core::array::from_fn(|lane| q(10 + lane as u32));
            let sibling: [QM31; 8] = core::array::from_fn(|lane| q(30 + lane as u32));
            for bit in [QM31::ZERO, QM31::ONE] {
                let mut openings = StateOnlyPoseidonOpenings {
                    z: [QM31::ZERO; 16],
                    succ_z: [QM31::ZERO; 16],
                    xor12_z: [QM31::ZERO; 16],
                };
                openings.z[0] = bit;
                openings.z[1..9].copy_from_slice(&current);
                openings.xor12_z[..8].copy_from_slice(&sibling);
                for lane in 0..8 {
                    if bit == QM31::ZERO {
                        openings.succ_z[lane] = current[lane];
                        openings.succ_z[8 + lane] = sibling[lane];
                    } else {
                        openings.succ_z[lane] = sibling[lane];
                        openings.succ_z[8 + lane] = current[lane];
                    }
                }
                let terminal =
                    evaluate_pool_v1_pair_forest_path_terminal_v1(&openings, &boolean_point(base))
                        .unwrap();
                assert_eq!(terminal.direction_booleanity, QM31::ZERO);
                assert!(terminal
                    .ordered_children
                    .into_iter()
                    .all(|residual| residual == QM31::ZERO));
                let selected_lane = if bit == QM31::ZERO { 0 } else { 8 };
                openings.succ_z[selected_lane] = openings.succ_z[selected_lane].add(QM31::ONE);
                assert_ne!(
                    evaluate_pool_v1_pair_forest_path_terminal_v1(&openings, &boolean_point(base),)
                        .unwrap()
                        .ordered_children[selected_lane],
                    QM31::ZERO
                );
            }
        }
    }

    #[test]
    fn forest_active_indicator_is_boolean_on_every_domain_row() {
        let active = pool_v1_pair_forest_copy_active_rows_v1().unwrap();
        assert_eq!(active.len(), 214);
        let mut seen = [false; POOL_V1_PAIR_TRACE_ROWS];
        for row in active {
            assert!(!seen[usize::from(row)]);
            seen[usize::from(row)] = true;
        }
        assert_eq!(seen.into_iter().filter(|value| *value).count(), 214);
    }

    #[test]
    fn helper_sum_rejects_every_noncanonical_length() {
        assert_eq!(
            pool_v1_pair_forest_copy_helper_sum_v1(&vec![QM31::ZERO; 1024]),
            Some(QM31::ZERO)
        );
        assert_eq!(
            pool_v1_pair_forest_copy_helper_sum_v1(&vec![QM31::ZERO; 1023]),
            None
        );
        assert_eq!(
            pool_v1_pair_forest_copy_helper_sum_v1(&vec![QM31::ZERO; 1025]),
            None
        );
    }

    #[test]
    fn compiled_copy_terminal_uses_the_exact_active_polynomial_and_append_bits() {
        let point: [QM31; 10] = core::array::from_fn(|index| q(2 + index as u32));
        let openings: [QM31; 16] = core::array::from_fn(|index| q(100 + index as u32));
        let active = pool_v1_pair_forest_copy_active_at_point_v1(&point).unwrap();
        let even = evaluate_pool_v1_pair_forest_copy_terminal_v1(
            &openings,
            q(313),
            &point,
            q(17),
            q(29),
            0,
            PoolV1PairTraceVariantV1::PrivateTransfer,
        )
        .unwrap();
        let odd = evaluate_pool_v1_pair_forest_copy_terminal_v1(
            &openings,
            q(313),
            &point,
            q(17),
            q(29),
            1,
            PoolV1PairTraceVariantV1::PrivateTransfer,
        )
        .unwrap();
        assert_eq!(even.active, active);
        assert_eq!(odd.active, active);
        assert_ne!(even.residual, odd.residual);
    }

    #[test]
    fn active_polynomial_is_exact_on_boolean_rows() {
        let active = pool_v1_pair_forest_copy_active_rows_v1().unwrap();
        for row in [0usize, 11, 864, 876, 997, 1023] {
            let point: [QM31; 10] =
                core::array::from_fn(|coordinate| q(((row >> (9 - coordinate)) & 1) as u32));
            let expected = QM31::from_cm31(aspis_core::field::CM31::from_m31(M31(u32::from(
                active.binary_search(&(row as u16)).is_ok(),
            ))));
            assert_eq!(
                pool_v1_pair_forest_copy_active_at_point_v1(&point).unwrap(),
                expected,
                "row {row}"
            );
        }
    }
}

