    let trace = relocate_and_extend(legacy, &witness.input, public.anchor_root)?;
    let semantic_c1 = merge_pool_v1_pair_forest_trace_banks_v1(&trace)?;
    Ok(PoolV1PairForestMergedC1CompilationV1 {
