#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum PoolV1PairTraceBankV1 {
    Stable,
    Late,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct PoolV1PairTraceCellV1 {
    pub bank: PoolV1PairTraceBankV1,
    pub cell: TraceCell,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum PoolV1PairCopyWeightV1 {
    One,
    PrivateTransferOnly,
    WithdrawalOnly,
    AppendCurrentLeft { level: u8 },
    AppendCurrentRight { level: u8 },
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum PoolV1PairTupleLimbV1 {
    Zero,
    Cell {
        source: PoolV1PairTraceCellV1,
        offset: M31,
    },
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct PoolV1PairCopyTupleV1 {
    pub row: u16,
    pub limbs: [PoolV1PairTupleLimbV1; 16],
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct PoolV1PairCopyLinkV1 {
    pub id: u16,
    pub tag: M31,
    pub kind: PoolV1PairCopyRowLinkKindV1,
    pub weight: PoolV1PairCopyWeightV1,
    pub producer: PoolV1PairCopyTupleV1,
    pub consumer: PoolV1PairCopyTupleV1,
}

#[inline]
fn bank_for_row(row: usize) -> PoolV1PairTraceBankV1 {
    if (544..864).contains(&row) {
        PoolV1PairTraceBankV1::Late
    } else {
        PoolV1PairTraceBankV1::Stable
    }
}

fn tuple_cells(row: usize, start: usize, count: usize, tweak_right: bool) -> PoolV1PairCopyTupleV1 {
    let bank = bank_for_row(row);
    let mut limbs = [PoolV1PairTupleLimbV1::Zero; 16];
    for lane in 0..count {
        let column = start + lane;
        let offset = if tweak_right && lane + 1 == count {
            M31::ZERO.sub(MERKLE_NODE_COMPRESSION_V3_TWEAK)
        } else {
            M31::ZERO
        };
        limbs[lane] = PoolV1PairTupleLimbV1::Cell {
            source: PoolV1PairTraceCellV1 {
                bank,
                cell: TraceCell {
                    row: row as u16,
                    column: column as u8,
                },
            },
            offset,
        };
    }
    PoolV1PairCopyTupleV1 {
        row: row as u16,
        limbs,
    }
}

fn aux_tuple(row: usize, start: usize, count: usize) -> PoolV1PairCopyTupleV1 {
    tuple_cells(row, start, count, false)
}

pub fn build_pool_v1_pair_copy_registry_v1(
) -> Result<Vec<PoolV1PairCopyLinkV1>, PoolV1PairTraceErrorV1> {
    let rows = build_pool_v1_pair_copy_row_schedule_v1()
        .map_err(|_| PoolV1PairTraceErrorV1::CopyLayout)?;
    let mut output = Vec::with_capacity(rows.len());
    for scheduled in rows {
        let (producer, consumer, weight) = match scheduled.kind {
            PoolV1PairCopyRowLinkKindV1::SpongeCarry { from, .. } => (
                tuple_cells(scheduled.producer_row as usize, 0, 16, false),
                tuple_cells(scheduled.consumer_row as usize, 0, 16, false),
                if from == 27 || from == 28 {
                    PoolV1PairCopyWeightV1::PrivateTransferOnly
                } else {
                    PoolV1PairCopyWeightV1::One
                },
            ),
            PoolV1PairCopyRowLinkKindV1::OwnerOutput => (
                tuple_cells(11, 0, 8, false),
                tuple_cells(28, 0, 8, false),
                PoolV1PairCopyWeightV1::One,
            ),
            PoolV1PairCopyRowLinkKindV1::NullifierKey => (
                tuple_cells(12, 0, 8, false),
                tuple_cells(412, 0, 8, false),
                PoolV1PairCopyWeightV1::One,
            ),
            PoolV1PairCopyRowLinkKindV1::InputSaltHead => (
                tuple_cells(44, 2, 6, false),
                tuple_cells(428, 0, 6, false),
                PoolV1PairCopyWeightV1::One,
            ),
            PoolV1PairCopyRowLinkKindV1::InputSaltTail => (
                tuple_cells(60, 0, 2, false),
                tuple_cells(428, 6, 2, false),
                PoolV1PairCopyWeightV1::One,
            ),
            PoolV1PairCopyRowLinkKindV1::PrivatePathCurrent { .. } => (
                tuple_cells(scheduled.producer_row as usize, 0, 8, false),
                aux_tuple(scheduled.consumer_row as usize, 1, 8),
                PoolV1PairCopyWeightV1::One,
            ),
            PoolV1PairCopyRowLinkKindV1::PrivatePathLeft { .. } => (
                aux_tuple(scheduled.producer_row as usize, 0, 8),
                tuple_cells(scheduled.consumer_row as usize, 0, 8, false),
                PoolV1PairCopyWeightV1::One,
            ),
            PoolV1PairCopyRowLinkKindV1::PrivatePathRight { .. } => (
                aux_tuple(scheduled.producer_row as usize, 8, 8),
                tuple_cells(scheduled.consumer_row as usize, 8, 8, true),
                PoolV1PairCopyWeightV1::One,
            ),
            PoolV1PairCopyRowLinkKindV1::ValueSource { value } => (
                tuple_cells(scheduled.producer_row as usize, 0, 1, false),
                aux_tuple(scheduled.consumer_row as usize, 10, 1),
                if value == 1 {
                    PoolV1PairCopyWeightV1::PrivateTransferOnly
                } else {
                    PoolV1PairCopyWeightV1::One
                },
            ),
            PoolV1PairCopyRowLinkKindV1::ConservationInput => (
                aux_tuple(960, 10, 1),
                aux_tuple(966, 0, 1),
                PoolV1PairCopyWeightV1::One,
            ),
            PoolV1PairCopyRowLinkKindV1::ConservationRecipient => (
                aux_tuple(962, 10, 1),
                aux_tuple(966, 1, 1),
                PoolV1PairCopyWeightV1::One,
            ),
            PoolV1PairCopyRowLinkKindV1::ConservationChange => (
                aux_tuple(964, 10, 1),
                aux_tuple(967, 1, 1),
                PoolV1PairCopyWeightV1::One,
            ),
            PoolV1PairCopyRowLinkKindV1::ConservationPartial => (
                aux_tuple(966, 2, 1),
                aux_tuple(967, 0, 1),
                PoolV1PairCopyWeightV1::One,
            ),
            PoolV1PairCopyRowLinkKindV1::InputSecondCommitment => (
                tuple_cells(64, 8, 8, true),
                aux_tuple(969, 2, 8),
                PoolV1PairCopyWeightV1::One,
            ),
            PoolV1PairCopyRowLinkKindV1::InputSelectedSide => (
                aux_tuple(scheduled.producer_row as usize, 0, 1),
                aux_tuple(969, 10, 1),
                PoolV1PairCopyWeightV1::One,
            ),
            PoolV1PairCopyRowLinkKindV1::OutputSecondCommitment => (
                tuple_cells(523, 0, 8, false),
                aux_tuple(970, 2, 8),
                PoolV1PairCopyWeightV1::PrivateTransferOnly,
            ),
            PoolV1PairCopyRowLinkKindV1::OutputPairFirst => (
                tuple_cells(475, 0, 8, false),
                tuple_cells(540, 0, 8, false),
                PoolV1PairCopyWeightV1::PrivateTransferOnly,
            ),
            PoolV1PairCopyRowLinkKindV1::OutputPairFirstWithdrawal => (
                tuple_cells(523, 0, 8, false),
                tuple_cells(540, 0, 8, false),
                PoolV1PairCopyWeightV1::WithdrawalOnly,
            ),
            PoolV1PairCopyRowLinkKindV1::OutputPairSecond => (
                aux_tuple(970, 2, 8),
                tuple_cells(528, 8, 8, true),
                PoolV1PairCopyWeightV1::One,
            ),
            PoolV1PairCopyRowLinkKindV1::AppendCurrentLeft { level } => (
                tuple_cells(scheduled.producer_row as usize, 0, 8, false),
                tuple_cells(scheduled.consumer_row as usize, 0, 8, false),
                PoolV1PairCopyWeightV1::AppendCurrentLeft { level },
            ),
            PoolV1PairCopyRowLinkKindV1::AppendCurrentRight { level } => (
                tuple_cells(scheduled.producer_row as usize, 0, 8, false),
                tuple_cells(scheduled.consumer_row as usize, 8, 8, true),
                PoolV1PairCopyWeightV1::AppendCurrentRight { level },
            ),
        };
        let id = output.len() as u16;
        output.push(PoolV1PairCopyLinkV1 {
            id,
            tag: M31(POOL_V1_PAIR_COPY_TAG_BASE_V1 + u32::from(id)),
            kind: scheduled.kind,
            weight,
            producer,
            consumer,
        });
    }
    if output.len() != POOL_V1_PAIR_COPY_ROW_LINKS_V1 {
        return Err(PoolV1PairTraceErrorV1::CopyLayout);
    }
    Ok(output)
}

fn tuple_value(trace: &PoolV1PairTraceV1, tuple: PoolV1PairCopyTupleV1) -> [M31; 16] {
    tuple.limbs.map(|limb| match limb {
        PoolV1PairTupleLimbV1::Zero => M31::ZERO,
        PoolV1PairTupleLimbV1::Cell { source, offset } => {
            let columns = match source.bank {
                PoolV1PairTraceBankV1::Stable => &trace.stable.c1,
                PoolV1PairTraceBankV1::Late => &trace.late,
            };
            columns[source.cell.column as usize][source.cell.row as usize].add(offset)
        }
    })
}

fn copy_weight(
    weight: PoolV1PairCopyWeightV1,
    append_index: u64,
    variant: PoolV1PairTraceVariantV1,
) -> M31 {
    match weight {
        PoolV1PairCopyWeightV1::One => M31::ONE,
        PoolV1PairCopyWeightV1::PrivateTransferOnly => M31(u32::from(
            variant == PoolV1PairTraceVariantV1::PrivateTransfer,
        )),
        PoolV1PairCopyWeightV1::WithdrawalOnly => {
            M31(u32::from(variant == PoolV1PairTraceVariantV1::Withdrawal))
        }
        PoolV1PairCopyWeightV1::AppendCurrentLeft { level } => {
            M31(1 - ((append_index >> level) & 1) as u32)
        }
        PoolV1PairCopyWeightV1::AppendCurrentRight { level } => {
            M31(((append_index >> level) & 1) as u32)
        }
    }
}

pub fn pool_v1_pair_copy_rows_v1(
    trace: &PoolV1PairTraceV1,
    append_index: u64,
    lambda: QM31,
) -> Result<Vec<CopyLogUpRow>, PoolV1PairTraceErrorV1> {
    let empty = CopyLogUpRow {
        producer_values: [QM31::ZERO; 2],
        producer_weights: [M31::ZERO; 2],
        consumer_values: [QM31::ZERO; 2],
        consumer_weights: [M31::ZERO; 2],
    };
    let mut rows = vec![empty; 1024];
    for link in build_pool_v1_pair_copy_registry_v1()? {
        let weight = copy_weight(link.weight, append_index, trace.variant);
        for (tuple, producer) in [(link.producer, true), (link.consumer, false)] {
            let row = &mut rows[tuple.row as usize];
            let (values, weights) = if producer {
                (&mut row.producer_values, &mut row.producer_weights)
            } else {
                (&mut row.consumer_values, &mut row.consumer_weights)
            };
            let slot = weights
                .iter()
                .position(|value| *value == M31::ZERO)
                .ok_or(PoolV1PairTraceErrorV1::CopyLayout)?;
            values[slot] = compress_tagged_tuple(link.tag, &tuple_value(trace, tuple), lambda);
            weights[slot] = weight;
        }
    }
    Ok(rows)
}

pub fn verify_pool_v1_pair_copy_registry_v1(
    trace: &PoolV1PairTraceV1,
    append_index: u64,
    lambda: QM31,
    chi: QM31,
) -> Result<(), PoolV1PairTraceErrorV1> {
    let rows = pool_v1_pair_copy_rows_v1(trace, append_index, lambda)?;
    let helper =
        build_copy_logup_helper(&rows, chi).map_err(|_| PoolV1PairTraceErrorV1::CopyImbalance)?;
    verify_copy_logup_constraints(&rows, &helper, chi)
        .map_err(|_| PoolV1PairTraceErrorV1::CopyImbalance)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::derive_owner_key;
    use aspis_core::field::CM31;

    fn digest(seed: u32) -> Digest {
        core::array::from_fn(|lane| M31(seed + lane as u32 + 1))
    }

    fn fixture() -> (
        PoolV1PrivateTransferPublicV1,
        PoolV1PairPrivateTransferWitnessV1,
        PoolV1PaymentRelationContextV1<'static>,
        PoolV1PairLiveSnapshotV1,
    ) {
        let nullifier_key = digest(10);
        let salt = digest(100);
        let asset = M31(77);
        let owner = derive_owner_key(&nullifier_key);
        let input_commitment = pool_v1_note_commitment(&owner, 1_000, asset, &salt);
        let pair_leaf =
            PoolV1PairLeafWitnessV1::two_outputs(input_commitment, digest(900)).unwrap();
        let membership = PoolV1MembershipWitnessV1 {
            siblings: core::array::from_fn(|level| digest(2_000 + 20 * level as u32)),
            index: 0x54321,
        };
        let mut anchor = pair_leaf.leaf_digest().unwrap();
        for level in 0..20 {
            let bit = M31((membership.index >> level) & 1);
            let (left, right) = ordered(anchor, membership.siblings[level], bit);
            anchor = pool_v1_tree_parent(&left, &right);
        }
        let recipient = PoolV1OutputNoteWitnessV1 {
            owner_key: digest(300),
            salt: digest(400),
            value: 600,
        };
        let change = PoolV1OutputNoteWitnessV1 {
            owner_key: digest(500),
            salt: digest(600),
            value: 400,
        };
        let public = PoolV1PrivateTransferPublicV1 {
            pool: [1; 32],
            deployment_domain: [2; 32],
            anchor_sequence: 42,
            anchor_root: anchor,
            nullifier: pool_v1_nullifier(&nullifier_key, &salt),
            asset_id: asset,
            recipient_commitment: pool_v1_note_commitment(
                &recipient.owner_key,
                recipient.value,
                asset,
                &recipient.salt,
            ),
            change_commitment: pool_v1_note_commitment(
                &change.owner_key,
                change.value,
                asset,
                &change.salt,
            ),
        };
        let witness = PoolV1PairPrivateTransferWitnessV1 {
            input: PoolV1PairInputNoteWitnessV1 {
                nullifier_key,
                salt,
                value: 1_000,
                pair_leaf,
                selected_second: false,
                membership,
            },
            recipient,
            change,
        };
        let context = PoolV1PaymentRelationContextV1 {
            runtime_binding: super::super::payment_relation::PoolV1PaymentRuntimeBindingV1 {
                pool: public.pool,
                deployment_domain: public.deployment_domain,
                anchor_sequence: public.anchor_sequence,
                anchor_root: public.anchor_root,
                asset_id: public.asset_id,
            },
            spent_nullifiers: &[],
        };
        let snapshot = snapshot_at(public.pool, public.deployment_domain, 0);
        (public, witness, context, snapshot)
    }

    fn snapshot_at(
        pool: [u8; 32],
        deployment_domain: [u8; 32],
        index: u64,
    ) -> PoolV1PairLiveSnapshotV1 {
        let empty = pair_empty_roots();
        let mut tree = IncrementalMerkleTreeV1::from_parts_with_empty_roots(
            0,
            empty[20],
            core::array::from_fn(|level| empty[level]),
            &empty,
        )
        .unwrap();
        for leaf in 0..index {
            tree = tree
                .append_one_with_empty_roots(digest(10_000 + 32 * leaf as u32), &empty)
                .unwrap()
                .0;
        }
        PoolV1PairLiveSnapshotV1 {
            pool,
            deployment_domain,
            sequence: index,
            next_pair_index: index,
            current_root: tree.root,
            frontier: tree.frontier,
        }
    }

    #[test]
    fn honest_pair_trace_has_exact_two_bank_geometry_and_copy_balance() {
        let (public, witness, context, snapshot) = fixture();
        let trace =
            build_pool_v1_pair_private_transfer_trace_v1(&public, &witness, context, snapshot)
                .unwrap();
        assert!(trace
            .stable
            .c1
            .iter()
            .all(|column| column[544..864].iter().all(|value| *value == M31::ZERO)));
        assert!(trace.late.iter().all(|column| column[..544]
            .iter()
            .chain(&column[864..])
            .all(|value| *value == M31::ZERO)));
        assert_eq!(trace.afterstate.next_pair_index, 1);
        assert_eq!(
            build_pool_v1_pair_copy_registry_v1().unwrap().len(),
            POOL_V1_PAIR_COPY_ROW_LINKS_V1
        );
        verify_pool_v1_pair_copy_registry_v1(
            &trace,
            snapshot.next_pair_index,
            QM31::from_cm31(CM31::from_m31(M31(19))),
            QM31::from_cm31(CM31::from_m31(M31(23))),
        )
        .unwrap();
    }

    #[test]
    fn checked_merge_overlays_only_the_disjoint_late_rows() {
        let (public, witness, context, snapshot) = fixture();
        let compiled = compile_pool_v1_pair_private_transfer_merged_c1_v1(
            &public, &witness, context, snapshot,
        )
        .unwrap();
        let trace = compiled.trace;
        let merged = compiled.semantic_c1;
        assert_eq!(compiled.public_statement.live_snapshot, snapshot);
        assert_eq!(
            compiled.public_statement.candidate_afterstate,
            trace.afterstate
        );
        for column in 0..16 {
            assert_eq!(&merged.c1[column][..544], &trace.stable.c1[column][..544]);
            assert_eq!(&merged.c1[column][544..864], &trace.late[column][544..864]);
            assert_eq!(&merged.c1[column][864..], &trace.stable.c1[column][864..]);
        }

        let mut stable_overlap = trace.clone();
        stable_overlap.stable.c1[0][544] = M31::ONE;
        assert_eq!(
            merge_pool_v1_pair_trace_banks_v1(&stable_overlap).err(),
            Some(PoolV1PairTraceErrorV1::Shape)
        );
        let mut late_escape = trace;
        late_escape.late[0][543] = M31::ONE;
        assert_eq!(
            merge_pool_v1_pair_trace_banks_v1(&late_escape).err(),
            Some(PoolV1PairTraceErrorV1::Shape)
        );
    }

    #[test]
    fn stable_and_late_mutations_fail_closed() {
        let (public, witness, context, snapshot) = fixture();
        let trace =
            build_pool_v1_pair_private_transfer_trace_v1(&public, &witness, context, snapshot)
                .unwrap();
        let mut stable_bad = trace.clone();
        stable_bad.stable.c1[7][100] = stable_bad.stable.c1[7][100].add(M31::ONE);
        assert!(validate_pool_v1_pair_private_transfer_trace_v1(
            &public,
            &witness,
            context,
            snapshot,
            &stable_bad
        )
        .is_err());
        let mut late_bad = trace;
        late_bad.late[4][700] = late_bad.late[4][700].add(M31::ONE);
        assert!(validate_pool_v1_pair_private_transfer_trace_v1(
            &public, &witness, context, snapshot, &late_bad
        )
        .is_err());
    }

    #[test]
    fn populated_live_frontier_uses_the_exact_twenty_late_blocks() {
        let (public, witness, context, _) = fixture();
        let snapshot = snapshot_at(public.pool, public.deployment_domain, 13);
        let trace =
            build_pool_v1_pair_private_transfer_trace_v1(&public, &witness, context, snapshot)
                .unwrap();
        assert_eq!(trace.afterstate.next_pair_index, 14);
        verify_pool_v1_pair_copy_registry_v1(
            &trace,
            snapshot.next_pair_index,
            QM31::from_cm31(CM31::from_m31(M31(29))),
            QM31::from_cm31(CM31::from_m31(M31(31))),
        )
        .unwrap();
    }
}

//! Host-side row and masking inventory for the production-inactive Pool pair
//! profile.
//!
//! This freezes the exact row-level contract which the eventual tuple
//! registry and generated terminal must reproduce.  It is deliberately not a
//! verifier dispatch surface: tuple values, conditional append weights and
//! public-account bindings still have to be compiled and source-bridged
//! before this profile can be enabled.

use alloc::vec::Vec;

use crate::trace_v4::TraceCell;

use super::pair_tree_profile::{
    pool_v1_pair_path_base_row_v1, POOL_V1_PAIR_INPUT_OCCUPANCY_AUX_ROW,
    POOL_V1_PAIR_INPUT_SELECTED_SIDE_COLUMN, POOL_V1_PAIR_OCCUPANCY_COMMITMENT_COLUMN_END,
    POOL_V1_PAIR_OUTPUT_OCCUPANCY_AUX_ROW, POOL_V1_PAIR_PATH_LOCAL_ROW_OFFSET,
    POOL_V1_PAIR_POSEIDON_BLOCKS, POOL_V1_PAIR_POSEIDON_ROW_END, POOL_V1_PAIR_PRIVATE_DIRECTIONS,
    POOL_V1_PAIR_TRACE_BLOCK_ROWS, POOL_V1_PAIR_TRACE_COLUMNS, POOL_V1_PAIR_TRACE_ROWS,
    POOL_V1_PAIR_VALUE_AUX_ROW_START,
};

pub const POOL_V1_PAIR_RELATION_FREE_PADDING_LOCAL_ROW_START_V1: usize = 13;
pub const POOL_V1_PAIR_COPY_ROW_LINKS_V1: usize = 127;
pub const POOL_V1_PAIR_COPY_ACTIVE_ROWS_V1: usize = 199;
pub const POOL_V1_PAIR_RELATION_FREE_MASK_CELLS_V1: usize = 4_334;
pub const PINNED_POOL_V1_PAIR_COPY_ROW_SCHEDULE_FINGERPRINT_V1: u64 = 0x5b01_a440_7ba9_4fce;
pub const PINNED_POOL_V1_PAIR_COPY_ACTIVE_ROWS_FINGERPRINT_V1: u64 = 0x56e6_c3e3_f386_f273;
pub const PINNED_POOL_V1_PAIR_RELATION_FREE_MASK_FINGERPRINT_V1: u64 = 0x6a86_249a_2d85_591f;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum PoolV1PairCopyRowLinkKindV1 {
    SpongeCarry {
        from: u8,
        to: u8,
    },
    OwnerOutput,
    NullifierKey,
    InputSaltHead,
    InputSaltTail,
    PrivatePathCurrent {
        level: u8,
    },
    PrivatePathLeft {
        level: u8,
    },
    PrivatePathRight {
        level: u8,
    },
    ValueSource {
        value: u8,
    },
    ConservationInput,
    ConservationRecipient,
    ConservationChange,
    ConservationPartial,
    InputSecondCommitment,
    InputSelectedSide,
    OutputSecondCommitment,
    OutputPairFirst,
    OutputPairFirstWithdrawal,
    OutputPairSecond,
    /// The two links at each level have complementary public weights
    /// `(1-bit, bit)`. Both rows remain in the fixed active-row inventory.
    AppendCurrentLeft {
        level: u8,
    },
    AppendCurrentRight {
        level: u8,
    },
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct PoolV1PairCopyRowLinkV1 {
    pub kind: PoolV1PairCopyRowLinkKindV1,
    pub producer_row: u16,
    pub consumer_row: u16,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum PoolV1PairHidingLayoutErrorV1 {
    Shape,
    EndpointCapacity { row: u16 },
}

#[inline]
fn link(
    kind: PoolV1PairCopyRowLinkKindV1,
    producer_row: usize,
    consumer_row: usize,
) -> PoolV1PairCopyRowLinkV1 {
    PoolV1PairCopyRowLinkV1 {
        kind,
        producer_row: producer_row as u16,
        consumer_row: consumer_row as u16,
    }
}

/// Exact row endpoints planned for the pair-tree tuple registry.
///
/// In particular, the append path is not represented by a private auxiliary
/// path.  Each level has two fixed row links with complementary public
/// direction weights.  This makes the active-row mask independent of the
/// current append index while preserving the exact late-bound direction.
pub fn build_pool_v1_pair_copy_row_schedule_v1(
) -> Result<Vec<PoolV1PairCopyRowLinkV1>, PoolV1PairHidingLayoutErrorV1> {
    let mut links = Vec::with_capacity(POOL_V1_PAIR_COPY_ROW_LINKS_V1);

    for (from, to) in [
        (1usize, 2usize),
        (2, 3),
        (25, 26),
        (27, 28),
        (28, 29),
        (30, 31),
        (31, 32),
    ] {
        links.push(link(
            PoolV1PairCopyRowLinkKindV1::SpongeCarry {
                from: from as u8,
                to: to as u8,
            },
            from * 16 + 11,
            to * 16,
        ));
    }

    links.push(link(PoolV1PairCopyRowLinkKindV1::OwnerOutput, 11, 28));
    links.push(link(PoolV1PairCopyRowLinkKindV1::NullifierKey, 12, 412));
    links.push(link(PoolV1PairCopyRowLinkKindV1::InputSaltHead, 44, 428));
    links.push(link(PoolV1PairCopyRowLinkKindV1::InputSaltTail, 60, 428));

    for level in 0..POOL_V1_PAIR_PRIVATE_DIRECTIONS {
        let aux =
            pool_v1_pair_path_base_row_v1(level).ok_or(PoolV1PairHidingLayoutErrorV1::Shape)?;
        let previous_output = (3 + level) * 16 + 11;
        let target_block = 4 + level;
        links.push(link(
            PoolV1PairCopyRowLinkKindV1::PrivatePathCurrent { level: level as u8 },
            previous_output,
            aux,
        ));
        links.push(link(
            PoolV1PairCopyRowLinkKindV1::PrivatePathLeft { level: level as u8 },
            aux + 1,
            target_block * 16 + 12,
        ));
        links.push(link(
            PoolV1PairCopyRowLinkKindV1::PrivatePathRight { level: level as u8 },
            aux + 1,
            target_block * 16,
        ));
    }

    for (value, source_row, destination_row) in
        [(0u8, 44usize, 960usize), (1, 460, 962), (2, 508, 964)]
    {
        links.push(link(
            PoolV1PairCopyRowLinkKindV1::ValueSource { value },
            source_row,
            destination_row,
        ));
    }
    links.push(link(
        PoolV1PairCopyRowLinkKindV1::ConservationInput,
        960,
        966,
    ));
    links.push(link(
        PoolV1PairCopyRowLinkKindV1::ConservationRecipient,
        962,
        966,
    ));
    links.push(link(
        PoolV1PairCopyRowLinkKindV1::ConservationChange,
        964,
        967,
    ));
    links.push(link(
        PoolV1PairCopyRowLinkKindV1::ConservationPartial,
        966,
        967,
    ));

    // Historical input-pair occupancy: duplicate the committed right child
    // and private selected-side bit into one row-local certificate.
    links.push(link(
        PoolV1PairCopyRowLinkKindV1::InputSecondCommitment,
        64,
        POOL_V1_PAIR_INPUT_OCCUPANCY_AUX_ROW,
    ));
    let input_selected_side_row =
        pool_v1_pair_path_base_row_v1(0).ok_or(PoolV1PairHidingLayoutErrorV1::Shape)?;
    links.push(link(
        PoolV1PairCopyRowLinkKindV1::InputSelectedSide,
        input_selected_side_row,
        POOL_V1_PAIR_INPUT_OCCUPANCY_AUX_ROW,
    ));

    // Newly appended output pair: the change commitment is certified in its
    // own occupancy row before that same complete digest enters the right
    // child of block 33. The recipient is the always-occupied left child.
    links.push(link(
        PoolV1PairCopyRowLinkKindV1::OutputSecondCommitment,
        32 * 16 + 11,
        POOL_V1_PAIR_OUTPUT_OCCUPANCY_AUX_ROW,
    ));
    links.push(link(
        PoolV1PairCopyRowLinkKindV1::OutputPairFirst,
        29 * 16 + 11,
        33 * 16 + 12,
    ));
    links.push(link(
        PoolV1PairCopyRowLinkKindV1::OutputPairFirstWithdrawal,
        32 * 16 + 11,
        33 * 16 + 12,
    ));
    links.push(link(
        PoolV1PairCopyRowLinkKindV1::OutputPairSecond,
        POOL_V1_PAIR_OUTPUT_OCCUPANCY_AUX_ROW,
        33 * 16,
    ));

    for level in 0..20usize {
        let previous_output = (33 + level) * 16 + 11;
        let target_block = 34 + level;
        links.push(link(
            PoolV1PairCopyRowLinkKindV1::AppendCurrentLeft { level: level as u8 },
            previous_output,
            target_block * 16 + 12,
        ));
        links.push(link(
            PoolV1PairCopyRowLinkKindV1::AppendCurrentRight { level: level as u8 },
            previous_output,
            target_block * 16,
        ));
    }

    if links.len() != POOL_V1_PAIR_COPY_ROW_LINKS_V1 {
        return Err(PoolV1PairHidingLayoutErrorV1::Shape);
    }
    endpoint_counts(&links)?;
    Ok(links)
}

fn endpoint_counts(
    links: &[PoolV1PairCopyRowLinkV1],
) -> Result<([u8; 1024], [u8; 1024]), PoolV1PairHidingLayoutErrorV1> {
    let mut producers = [0u8; 1024];
    let mut consumers = [0u8; 1024];
    for link in links {
        for (row, counts) in [
            (usize::from(link.producer_row), &mut producers),
            (usize::from(link.consumer_row), &mut consumers),
        ] {
            if row >= POOL_V1_PAIR_TRACE_ROWS || counts[row] >= 2 {
                return Err(PoolV1PairHidingLayoutErrorV1::EndpointCapacity { row: row as u16 });
            }
            counts[row] += 1;
        }
    }
    Ok((producers, consumers))
}

pub fn pool_v1_pair_copy_active_rows_v1() -> Result<Vec<u16>, PoolV1PairHidingLayoutErrorV1> {
    let links = build_pool_v1_pair_copy_row_schedule_v1()?;
    let mut rows = links
        .iter()
        .flat_map(|link| [link.producer_row, link.consumer_row])
        .collect::<Vec<_>>();
    rows.sort_unstable();
    rows.dedup();
    Ok(rows)
}

pub fn pool_v1_pair_copy_active_row_masks_v1() -> Result<[u16; 64], PoolV1PairHidingLayoutErrorV1> {
    let mut masks = [0u16; 64];
    for row in pool_v1_pair_copy_active_rows_v1()? {
        masks[usize::from(row) >> 4] |= 1 << (usize::from(row) & 15);
    }
    Ok(masks)
}

pub fn pool_v1_pair_copy_inactive_row_masks_v1() -> Result<[u16; 64], PoolV1PairHidingLayoutErrorV1>
{
    Ok(pool_v1_pair_copy_active_row_masks_v1()?.map(|mask| !mask))
}

fn path_aux_cell_is_used(row: usize, column: usize) -> bool {
    for level in 0..POOL_V1_PAIR_PRIVATE_DIRECTIONS {
        let Some(base) = pool_v1_pair_path_base_row_v1(level) else {
            return false;
        };
        if (row == base && column <= 8) || (row == base + 1) || (row == (base ^ 12) && column < 8) {
            return true;
        }
    }
    false
}

fn value_aux_cell_is_used(row: usize, column: usize) -> bool {
    for value in 0..3usize {
        let base = POOL_V1_PAIR_VALUE_AUX_ROW_START + 2 * value;
        if (row == base && column <= 10)
            || (row == base + 1 && column <= 10)
            || (row == (base ^ 12) && column <= 10)
        {
            return true;
        }
    }
    (row == POOL_V1_PAIR_VALUE_AUX_ROW_START + 6 && column < 3)
        || (row == POOL_V1_PAIR_VALUE_AUX_ROW_START + 7 && column < 2)
}

fn occupancy_aux_cell_is_used(row: usize, column: usize) -> bool {
    (row == POOL_V1_PAIR_INPUT_OCCUPANCY_AUX_ROW
        && column <= POOL_V1_PAIR_INPUT_SELECTED_SIDE_COLUMN)
        || (row == POOL_V1_PAIR_OUTPUT_OCCUPANCY_AUX_ROW
            && column < POOL_V1_PAIR_OCCUPANCY_COMMITMENT_COLUMN_END)
}

pub fn pool_v1_pair_aux_cell_is_relation_used_v1(row: usize, column: usize) -> bool {
    if row < POOL_V1_PAIR_POSEIDON_ROW_END
        || row >= POOL_V1_PAIR_TRACE_ROWS
        || column >= POOL_V1_PAIR_TRACE_COLUMNS
    {
        return false;
    }
    path_aux_cell_is_used(row, column)
        || value_aux_cell_is_used(row, column)
        || occupancy_aux_cell_is_used(row, column)
}

/// Exact relation-free inventory for the proposed row schedule. Every cell
/// is absent from the 54 Poseidon relations, all auxiliary residuals and the
/// fixed row-level copy endpoint schedule.
pub fn pool_v1_pair_relation_free_mask_cells_v1(
) -> Result<Vec<TraceCell>, PoolV1PairHidingLayoutErrorV1> {
    // Building the copy schedule here ensures endpoint capacity and its exact
    // row contract are checked before this inventory is consumed.
    let _ = build_pool_v1_pair_copy_row_schedule_v1()?;
    let mut cells = Vec::new();
    for column in 0..POOL_V1_PAIR_TRACE_COLUMNS {
        for row in 0..POOL_V1_PAIR_TRACE_ROWS {
            let padding = row < POOL_V1_PAIR_POSEIDON_ROW_END
                && row % POOL_V1_PAIR_TRACE_BLOCK_ROWS
                    >= POOL_V1_PAIR_RELATION_FREE_PADDING_LOCAL_ROW_START_V1;
            let undeclared_auxiliary = row >= POOL_V1_PAIR_POSEIDON_ROW_END
                && !pool_v1_pair_aux_cell_is_relation_used_v1(row, column);
            if padding || undeclared_auxiliary {
                cells.push(TraceCell {
                    row: row as u16,
                    column: column as u8,
                });
            }
        }
    }
    Ok(cells)
}

fn fingerprint_bytes<'a>(bytes: impl IntoIterator<Item = &'a u8>) -> u64 {
    let mut hash = 0xcbf2_9ce4_8422_2325u64;
    for byte in bytes {
        hash ^= u64::from(*byte);
        hash = hash.wrapping_mul(0x0000_0100_0000_01b3);
    }
    hash
}

fn copy_row_link_kind_code_v1(kind: PoolV1PairCopyRowLinkKindV1) -> [u8; 3] {
    match kind {
        PoolV1PairCopyRowLinkKindV1::SpongeCarry { from, to } => [0, from, to],
        PoolV1PairCopyRowLinkKindV1::OwnerOutput => [1, 0, 0],
        PoolV1PairCopyRowLinkKindV1::NullifierKey => [2, 0, 0],
        PoolV1PairCopyRowLinkKindV1::InputSaltHead => [3, 0, 0],
        PoolV1PairCopyRowLinkKindV1::InputSaltTail => [4, 0, 0],
        PoolV1PairCopyRowLinkKindV1::PrivatePathCurrent { level } => [5, level, 0],
        PoolV1PairCopyRowLinkKindV1::PrivatePathLeft { level } => [6, level, 0],
        PoolV1PairCopyRowLinkKindV1::PrivatePathRight { level } => [7, level, 0],
        PoolV1PairCopyRowLinkKindV1::ValueSource { value } => [8, value, 0],
        PoolV1PairCopyRowLinkKindV1::ConservationInput => [9, 0, 0],
        PoolV1PairCopyRowLinkKindV1::ConservationRecipient => [10, 0, 0],
        PoolV1PairCopyRowLinkKindV1::ConservationChange => [11, 0, 0],
        PoolV1PairCopyRowLinkKindV1::ConservationPartial => [12, 0, 0],
        PoolV1PairCopyRowLinkKindV1::InputSecondCommitment => [13, 0, 0],
        PoolV1PairCopyRowLinkKindV1::InputSelectedSide => [14, 0, 0],
        PoolV1PairCopyRowLinkKindV1::OutputSecondCommitment => [15, 0, 0],
        PoolV1PairCopyRowLinkKindV1::OutputPairFirst => [16, 0, 0],
        PoolV1PairCopyRowLinkKindV1::OutputPairFirstWithdrawal => [17, 0, 0],
        PoolV1PairCopyRowLinkKindV1::OutputPairSecond => [18, 0, 0],
        PoolV1PairCopyRowLinkKindV1::AppendCurrentLeft { level } => [19, level, 0],
        PoolV1PairCopyRowLinkKindV1::AppendCurrentRight { level } => [20, level, 0],
    }
}

/// Fingerprint of every ordered copy-link meaning and both row endpoints.
/// This is stronger than the active-row fingerprint consumed by the rank
/// engine: it also detects swaps between producer/consumer roles, levels and
/// complementary append directions.
pub fn pool_v1_pair_copy_row_schedule_fingerprint_v1() -> Result<u64, PoolV1PairHidingLayoutErrorV1>
{
    let bytes = build_pool_v1_pair_copy_row_schedule_v1()?
        .into_iter()
        .flat_map(|link| {
            let kind = copy_row_link_kind_code_v1(link.kind);
            let producer = link.producer_row.to_le_bytes();
            let consumer = link.consumer_row.to_le_bytes();
            [
                kind[0],
                kind[1],
                kind[2],
                producer[0],
                producer[1],
                consumer[0],
                consumer[1],
            ]
        })
        .collect::<Vec<_>>();
    Ok(fingerprint_bytes(bytes.iter()))
}

pub fn pool_v1_pair_relation_free_mask_fingerprint_v1() -> Result<u64, PoolV1PairHidingLayoutErrorV1>
{
    let bytes = pool_v1_pair_relation_free_mask_cells_v1()?
        .into_iter()
        .flat_map(|cell| {
            let row = cell.row.to_le_bytes();
            [row[0], row[1], cell.column]
        })
        .collect::<Vec<_>>();
    Ok(fingerprint_bytes(bytes.iter()))
}

pub fn pool_v1_pair_copy_active_rows_fingerprint_v1() -> Result<u64, PoolV1PairHidingLayoutErrorV1>
{
    let bytes = pool_v1_pair_copy_active_rows_v1()?
        .into_iter()
        .flat_map(u16::to_le_bytes)
        .collect::<Vec<_>>();
    Ok(fingerprint_bytes(bytes.iter()))
}

const _: () = assert!(POOL_V1_PAIR_POSEIDON_BLOCKS == 54);
const _: () = assert!(POOL_V1_PAIR_POSEIDON_ROW_END == 864);
const _: () = assert!(POOL_V1_PAIR_PATH_LOCAL_ROW_OFFSET == 1);

#[cfg(test)]
mod tests {
    use super::*;

    fn contains(cells: &[TraceCell], row: usize, column: usize) -> bool {
        cells
            .binary_search_by_key(&(column as u8, row as u16), |cell| (cell.column, cell.row))
            .is_ok()
    }

    #[test]
    fn exact_row_schedule_has_bounded_endpoint_capacity() {
        let links = build_pool_v1_pair_copy_row_schedule_v1().unwrap();
        assert_eq!(links.len(), POOL_V1_PAIR_COPY_ROW_LINKS_V1);
        let selected_side = links
            .iter()
            .find(|link| link.kind == PoolV1PairCopyRowLinkKindV1::InputSelectedSide)
            .unwrap();
        assert_eq!(
            usize::from(selected_side.producer_row),
            pool_v1_pair_path_base_row_v1(0).unwrap(),
        );
        assert_eq!(
            usize::from(selected_side.consumer_row),
            POOL_V1_PAIR_INPUT_OCCUPANCY_AUX_ROW,
        );
        let (producers, consumers) = endpoint_counts(&links).unwrap();
        assert!(producers.into_iter().all(|count| count <= 2));
        assert!(consumers.into_iter().all(|count| count <= 2));
        // The public-variant dual output routing consumes the final available
        // slots at precisely these two endpoints.
        assert_eq!(producers[32 * 16 + 11], 2);
        assert_eq!(consumers[33 * 16 + 12], 2);
        assert_eq!(
            pool_v1_pair_copy_row_schedule_fingerprint_v1().unwrap(),
            PINNED_POOL_V1_PAIR_COPY_ROW_SCHEDULE_FINGERPRINT_V1,
        );
    }

    #[test]
    fn relation_free_inventory_preserves_all_48_tail_rows() {
        let cells = pool_v1_pair_relation_free_mask_cells_v1().unwrap();
        assert!(cells
            .windows(2)
            .all(|pair| (pair[0].column, pair[0].row) < (pair[1].column, pair[1].row)));
        for column in 0..POOL_V1_PAIR_TRACE_COLUMNS {
            for row in 976..POOL_V1_PAIR_TRACE_ROWS {
                assert!(contains(&cells, row, column));
            }
            for block in 0..POOL_V1_PAIR_POSEIDON_BLOCKS {
                for local in 13..16 {
                    assert!(contains(
                        &cells,
                        block * POOL_V1_PAIR_TRACE_BLOCK_ROWS + local,
                        column,
                    ));
                }
            }
        }
        for row in [
            POOL_V1_PAIR_INPUT_OCCUPANCY_AUX_ROW,
            POOL_V1_PAIR_OUTPUT_OCCUPANCY_AUX_ROW,
        ] {
            for column in 0..POOL_V1_PAIR_OCCUPANCY_COMMITMENT_COLUMN_END {
                assert!(!contains(&cells, row, column));
            }
        }
        assert!(!contains(
            &cells,
            POOL_V1_PAIR_INPUT_OCCUPANCY_AUX_ROW,
            POOL_V1_PAIR_INPUT_SELECTED_SIDE_COLUMN,
        ));
        assert_eq!(cells.len(), POOL_V1_PAIR_RELATION_FREE_MASK_CELLS_V1);
        assert_eq!(
            pool_v1_pair_relation_free_mask_fingerprint_v1().unwrap(),
            PINNED_POOL_V1_PAIR_RELATION_FREE_MASK_FINGERPRINT_V1,
        );
    }

    #[test]
    fn active_and_inactive_masks_are_exact_complements() {
        let active = pool_v1_pair_copy_active_row_masks_v1().unwrap();
        let inactive = pool_v1_pair_copy_inactive_row_masks_v1().unwrap();
        assert_eq!(
            pool_v1_pair_copy_active_rows_v1().unwrap().len(),
            POOL_V1_PAIR_COPY_ACTIVE_ROWS_V1,
        );
        assert_eq!(
            pool_v1_pair_copy_active_rows_fingerprint_v1().unwrap(),
            PINNED_POOL_V1_PAIR_COPY_ACTIVE_ROWS_FINGERPRINT_V1,
        );
        for group in 0..64 {
            assert_eq!(active[group] ^ inactive[group], u16::MAX);
            assert_eq!(active[group] & inactive[group], 0);
        }
        assert_eq!(active[63], 0);
        assert_eq!(inactive[63], u16::MAX);
    }
}

//! Production-inactive source contract for the staged Pool pair-tree profile.
//!
//! This module freezes the three design gates which must be source-bound
//! before the profile can be enabled by verifier dispatch:
//!
//! * an empty second slot is algebraically distinguished from an occupied one;
//! * the historical membership anchor is separate from the exact live append
//!   snapshot, whose complete account-derived image and candidate afterstate
//!   are absorbed before the C1 root and batching challenges; and
//! * the 1,024-row trace allocates exactly 976 semantic rows and retains the
//!   deployed degree-27 cap.
//!
//! Nothing in this module adds a dispatch tag, registry release, account
//! decoder, prover, verifier, or state mutation path.

use alloc::boxed::Box;

use aspis_core::{
    field::{M31, P},
    transcript::{label, Transcript},
};

use crate::{decode_digest_canonical, encode_digest_canonical, poseidon2::Digest};

use super::{
    decode_pool_v1_pair_verified_afterstate_v1, encode_pool_v1_pair_verified_afterstate_v1,
    PoolV1PairVerifiedAfterstateV1, PoolV1PairVerifierTransportErrorV1,
    POOL_V1_PAIR_VERIFIED_AFTERSTATE_BYTES,
};
use super::{pool_v1_tree_parent, POOL_V1_TREE_DEPTH};

pub const POOL_V1_PAIR_TREE_STORAGE_FORMAT_VERSION: u8 = 1;
pub const POOL_V1_PAIR_TREE_DEPTH: usize = POOL_V1_TREE_DEPTH;
pub const POOL_V1_PAIR_NOTE_DEPTH: usize = POOL_V1_PAIR_TREE_DEPTH + 1;
pub const POOL_V1_PAIR_CAPACITY: u64 = 1u64 << POOL_V1_PAIR_TREE_DEPTH;
pub const POOL_V1_PAIR_NOTE_SLOT_CAPACITY: u64 = 2 * POOL_V1_PAIR_CAPACITY;
pub const POOL_V1_PAIR_SECOND_SENTINEL_LANE: usize = 7;

/// Explicitly distinct from the ordinary single-note Pool V1 storage format.
/// A state account may use one format or the other; no profile may reinterpret
/// an existing root across this boundary.
pub const POOL_V1_PAIR_TREE_FORMAT_BINDING: [u8; 32] = [
    b'A',
