            build_pool_v1_private_transfer_trace_v1(&public, &witness, transfer_context(&public))
                .unwrap();
        (public, trace)
    }

    fn built_withdrawal() -> (PoolV1WithdrawalPublicV1, PoolV1PaymentTraceV1) {
        let (public, witness) = withdrawal_fixture();
        let trace =
            build_pool_v1_withdrawal_trace_v1(&public, &witness, withdrawal_context(&public))
                .unwrap();
        (public, trace)
    }

    fn assert_class_nonzero(
        residuals: &PoolV1PaymentConstraintResidualsV1,
        class: PoolV1PaymentResidualClassV1,
    ) {
        assert!(
            !residuals.class_is_zero(class),
            "class unexpectedly zero: {class:?}"
        );
        assert!(!residuals.all_zero());
    }

    fn set_value_bits(trace: &mut StateOnlyTraceFoundation, value: usize, integer: u32) {
        for bit in 0..POOL_V1_PAYMENT_VALUE_BITS {
            let target = pool_v1_payment_value_aux_v1(value).unwrap().bits[bit];
            trace.c1[usize::from(target.column)][usize::from(target.row)] =
                M31((integer >> bit) & 1);
        }
    }

    #[test]
    fn honest_variants_have_exactly_zero_complete_residuals_and_degree_25() {
        assert_eq!(POOL_V1_PAYMENT_TWO_ROUND_INTRINSIC_DEGREE, 5 * 5);
        assert_eq!(POOL_V1_PAYMENT_MAX_INTRINSIC_DEGREE, 25);
        assert_eq!(POOL_V1_PAYMENT_SELECTED_ORACLE_INDIVIDUAL_DEGREE, 26);
        assert_eq!(POOL_V1_PAYMENT_ZEROCHECK_INDIVIDUAL_DEGREE, 27);

        let (public, trace) = built_transfer();
        let residuals =
            evaluate_pool_v1_private_transfer_constraint_residuals_v1(&public, &trace.trace)
                .unwrap();
        assert!(residuals.all_zero(), "transfer residuals={residuals:?}");
        assert_eq!(residuals.poseidon_round_pairs.len(), 8_624);
        assert_eq!(residuals.sponge_schedule.len(), 626);
        assert_eq!(residuals.source_aliases.len(), 27);
        assert_eq!(residuals.path_ordering.len(), 320);
        assert_eq!(residuals.public_bindings.len(), 32);
        assert_eq!(residuals.zero_padding.len(), 5_978);
        assert_eq!(residuals.residual_count(), 15_721);

        let (public, trace) = built_withdrawal();
        let residuals =
            evaluate_pool_v1_withdrawal_constraint_residuals_v1(&public, &trace.trace).unwrap();
        assert!(residuals.all_zero(), "withdrawal residuals={residuals:?}");
        assert_eq!(residuals.sponge_schedule.len(), 548);
        assert_eq!(residuals.source_aliases.len(), 26);
        assert_eq!(residuals.public_bindings.len(), 24);
        assert_eq!(residuals.zero_padding.len(), 6_074);
        assert_eq!(residuals.residual_count(), 15_730);
    }

    #[test]
    fn every_private_transfer_semantic_class_has_a_detected_mutation() {
        let (public, honest) = built_transfer();

        let mut trace = honest.clone();
        trace.trace.c1[7][10 * 16 + 6] = trace.trace.c1[7][10 * 16 + 6].add(M31::ONE);
        let residuals =
            evaluate_pool_v1_private_transfer_constraint_residuals_v1(&public, &trace.trace)
                .unwrap();
        assert_class_nonzero(&residuals, PoolV1PaymentResidualClassV1::PoseidonRoundPairs);

        let mut trace = honest.clone();
        trace.trace.c1[0][2 * 16] = trace.trace.c1[0][2 * 16].add(M31::ONE);
        let residuals =
            evaluate_pool_v1_private_transfer_constraint_residuals_v1(&public, &trace.trace)
                .unwrap();
        assert_class_nonzero(&residuals, PoolV1PaymentResidualClassV1::SpongeSchedule);

        let mut trace = honest.clone();
        trace.trace.c1[0][24 * 16 + 12] = trace.trace.c1[0][24 * 16 + 12].add(M31::ONE);
        let residuals =
            evaluate_pool_v1_private_transfer_constraint_residuals_v1(&public, &trace.trace)
                .unwrap();
        assert_class_nonzero(&residuals, PoolV1PaymentResidualClassV1::SourceAliases);

        let mut trace = honest.clone();
        let direction = pool_v1_payment_path_aux_v1(0).unwrap().bit;
        trace.trace.c1[usize::from(direction.column)][usize::from(direction.row)] = M31(2);
        let residuals =
            evaluate_pool_v1_private_transfer_constraint_residuals_v1(&public, &trace.trace)
                .unwrap();
        assert_class_nonzero(
            &residuals,
            PoolV1PaymentResidualClassV1::DirectionBooleanity,
        );

        let mut trace = honest.clone();
        let direction = pool_v1_payment_path_aux_v1(0).unwrap().bit;
        let bit = &mut trace.trace.c1[usize::from(direction.column)][usize::from(direction.row)];
        *bit = M31::ONE.sub(*bit);
        let residuals =
            evaluate_pool_v1_private_transfer_constraint_residuals_v1(&public, &trace.trace)
                .unwrap();
        assert!(residuals.class_is_zero(PoolV1PaymentResidualClassV1::DirectionBooleanity));
        assert_class_nonzero(&residuals, PoolV1PaymentResidualClassV1::PathOrdering);

        let mut trace = honest.clone();
        let value_bit = pool_v1_payment_value_aux_v1(0).unwrap().bits[0];
        trace.trace.c1[usize::from(value_bit.column)][usize::from(value_bit.row)] = M31(2);
        let residuals =
            evaluate_pool_v1_private_transfer_constraint_residuals_v1(&public, &trace.trace)
                .unwrap();
        assert_class_nonzero(&residuals, PoolV1PaymentResidualClassV1::ValueBooleanity);

        let mut trace = honest.clone();
        let value_bit = pool_v1_payment_value_aux_v1(0).unwrap().bits[0];
        let bit = &mut trace.trace.c1[usize::from(value_bit.column)][usize::from(value_bit.row)];
        *bit = M31::ONE.sub(*bit);
        let residuals =
            evaluate_pool_v1_private_transfer_constraint_residuals_v1(&public, &trace.trace)
                .unwrap();
        assert!(residuals.class_is_zero(PoolV1PaymentResidualClassV1::ValueBooleanity));
        assert_class_nonzero(&residuals, PoolV1PaymentResidualClassV1::ValueRecomposition);

        for mutate in 0..4 {
            let mut changed = public;
            match mutate {
                0 => changed.anchor_root[0] = changed.anchor_root[0].add(M31::ONE),
                1 => changed.nullifier[0] = changed.nullifier[0].add(M31::ONE),
                2 => {
                    changed.recipient_commitment[0] = changed.recipient_commitment[0].add(M31::ONE)
                }
                3 => changed.change_commitment[0] = changed.change_commitment[0].add(M31::ONE),
                _ => unreachable!(),
            }
            let residuals =
                evaluate_pool_v1_private_transfer_constraint_residuals_v1(&changed, &honest.trace)
                    .unwrap();
            assert_class_nonzero(&residuals, PoolV1PaymentResidualClassV1::PublicBindings);
        }

        let mut trace = honest.clone();
        trace.trace.c1[0][32 * 16] = M31::ONE;
        let residuals =
            evaluate_pool_v1_private_transfer_constraint_residuals_v1(&public, &trace.trace)
                .unwrap();
        assert_class_nonzero(&residuals, PoolV1PaymentResidualClassV1::ZeroPadding);
    }

    #[test]
    fn withdrawal_amount_conservation_and_recipient_padding_mutations_are_detected() {
        let (public, honest) = built_withdrawal();

        let mut changed_public = public;
        changed_public.amount += 1;
        let mut changed_trace = honest.clone();
        set_value_bits(&mut changed_trace.trace, 1, changed_public.amount);
        let residuals = evaluate_pool_v1_withdrawal_constraint_residuals_v1(
            &changed_public,
            &changed_trace.trace,
        )
        .unwrap();
        assert!(residuals.class_is_zero(PoolV1PaymentResidualClassV1::ValueBooleanity));
        assert!(residuals.class_is_zero(PoolV1PaymentResidualClassV1::ValueRecomposition));
        assert_class_nonzero(&residuals, PoolV1PaymentResidualClassV1::Conservation);

        let mut trace = honest.clone();
        trace.trace.c1[0][26 * 16] = M31::ONE;
        let residuals =
            evaluate_pool_v1_withdrawal_constraint_residuals_v1(&public, &trace.trace).unwrap();
        assert_class_nonzero(&residuals, PoolV1PaymentResidualClassV1::ZeroPadding);
    }
}

//! Relation-free C1 masking layout for the Pool V1 payment trace.
//!
//! This is a host/compiler inventory.  The allocation-bounded terminal omits
//! the corresponding zero constraints, but does not build this `Vec` on SBF.

use alloc::vec::Vec;

use crate::{poseidon2::POSEIDON2_WIDTH, trace_v4::TraceCell};

use super::{
    payment_semantic_registry::{
        build_pool_v1_payment_semantic_registry_v1, pool_v1_payment_aux_cell_is_used_v1,
        pool_v1_payment_value_aux_v1, PoolV1PaymentSemanticRegistryErrorV1,
        PoolV1PaymentTupleLimbV1,
    },
    payment_trace::{
        PoolV1PaymentTraceVariantV1, POOL_V1_PAYMENT_TRACE_BLOCK_ROWS,
        POOL_V1_PAYMENT_TRACE_PERMUTATION_ROWS, POOL_V1_PAYMENT_TRACE_ROWS,
    },
};

pub const POOL_V1_PAYMENT_RELATION_FREE_PADDING_LOCAL_ROW_START_V1: usize = 13;

fn auxiliary_cell_is_relation_used(row: usize, column: usize) -> bool {
    if pool_v1_payment_aux_cell_is_used_v1(row, column) {
        return true;
    }
    // Direct-range lanes explicitly bind column ten to zero in the successor
    // and xor12 views.  They are not witness payload cells, but are relation
    // inputs and therefore cannot be masking material.
    (0..3).any(|value| {
        let base = usize::from(pool_v1_payment_value_aux_v1(value).unwrap().source.row);
        column == 10 && (row == base + 1 || row == (base ^ 12))
    })
}

/// Every Pool payment C1 cell which is absent from Poseidon, payment
/// semantics, public bindings, and both variants' copy registries.
///
/// The ordered inventory is deliberately variant-independent.  It contains
/// rows 13..15 of the 49 permutation blocks and undeclared cells in the
/// auxiliary tail.  The registry walk is an independent mechanical guard
/// that excludes any affine copy endpoint if a future layout changes.
pub fn pool_v1_payment_relation_free_mask_cells_v1(
) -> Result<Vec<TraceCell>, PoolV1PaymentSemanticRegistryErrorV1> {
    let mut copy_occupied = [false; POOL_V1_PAYMENT_TRACE_ROWS * POSEIDON2_WIDTH];
    for variant in [
        PoolV1PaymentTraceVariantV1::PrivateTransfer,
        PoolV1PaymentTraceVariantV1::Withdrawal,
    ] {
        for link in build_pool_v1_payment_semantic_registry_v1(variant)?.links {
            for tuple in [link.producer, link.consumer] {
                for limb in tuple.limbs {
                    if let PoolV1PaymentTupleLimbV1::AffineCell { cell, .. } = limb {
                        copy_occupied[usize::from(cell.column) * POOL_V1_PAYMENT_TRACE_ROWS
                            + usize::from(cell.row)] = true;
                    }
                }
            }
        }
    }

    let mut cells = Vec::new();
    for column in 0..POSEIDON2_WIDTH {
        for row in 0..POOL_V1_PAYMENT_TRACE_ROWS {
            let padding = row < POOL_V1_PAYMENT_TRACE_PERMUTATION_ROWS
                && row % POOL_V1_PAYMENT_TRACE_BLOCK_ROWS
                    >= POOL_V1_PAYMENT_RELATION_FREE_PADDING_LOCAL_ROW_START_V1;
            let undeclared_auxiliary = row >= POOL_V1_PAYMENT_TRACE_PERMUTATION_ROWS
                && !auxiliary_cell_is_relation_used(row, column);
            if (padding || undeclared_auxiliary)
                && !copy_occupied[column * POOL_V1_PAYMENT_TRACE_ROWS + row]
            {
                cells.push(TraceCell {
                    row: row as u16,
                    column: column as u8,
                });
            }
        }
    }
    Ok(cells)
}

pub fn pool_v1_payment_relation_free_mask_fingerprint_v1(
) -> Result<u64, PoolV1PaymentSemanticRegistryErrorV1> {
    let mut hash = 0xcbf2_9ce4_8422_2325u64;
    for cell in pool_v1_payment_relation_free_mask_cells_v1()? {
        for byte in cell.row.to_le_bytes().into_iter().chain([cell.column]) {
            hash ^= u64::from(byte);
            hash = hash.wrapping_mul(0x0000_0100_0000_01b3);
        }
    }
    Ok(hash)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn inventory_is_column_major_complete_and_copy_disjoint() {
        let cells = pool_v1_payment_relation_free_mask_cells_v1().unwrap();
        assert_eq!(cells.len(), 5_428);
        assert_eq!(
            pool_v1_payment_relation_free_mask_fingerprint_v1().unwrap(),
            0xfceb_68f3_197c_3351,
        );
        assert!(cells
            .windows(2)
            .all(|pair| { (pair[0].column, pair[0].row) < (pair[1].column, pair[1].row) }));

        for column in 0..POSEIDON2_WIDTH {
            for row in 0..POOL_V1_PAYMENT_TRACE_ROWS {
                let expected = (row < POOL_V1_PAYMENT_TRACE_PERMUTATION_ROWS
                    && row % POOL_V1_PAYMENT_TRACE_BLOCK_ROWS >= 13)
                    || (row >= POOL_V1_PAYMENT_TRACE_PERMUTATION_ROWS
                        && !auxiliary_cell_is_relation_used(row, column));
                assert_eq!(
                    cells
                        .binary_search_by_key(&(column as u8, row as u16), |cell| {
                            (cell.column, cell.row)
                        })
                        .is_ok(),
                    expected,
                    "cell ({row}, {column})",
                );
            }
        }

        for variant in [
            PoolV1PaymentTraceVariantV1::PrivateTransfer,
            PoolV1PaymentTraceVariantV1::Withdrawal,
        ] {
            for link in build_pool_v1_payment_semantic_registry_v1(variant)
                .unwrap()
                .links
            {
                for tuple in [link.producer, link.consumer] {
                    for limb in tuple.limbs {
                        if let PoolV1PaymentTupleLimbV1::AffineCell { cell, .. } = limb {
                            assert!(!cells.contains(&cell), "copy endpoint {cell:?}");
                        }
                    }
                }
            }
        }
    }
}

//! Executable Pool V1 private-transfer and withdrawal relations.
//!
//! This module is a no-proof semantic foundation.  It deliberately does not
//! claim that either relation has been compiled into the frozen Tag-73 trace,
//! terminal oracle, transcript, or verifier.  The public encodings are the
//! exact 216-byte `ASCP` and `ASWP` payloads consumed by `aspis-pool`.
//!
//! Pool V1 is fee-free.  Its canonical custody fee is zero and is not a
//! caller-selectable statement field.  `ASCP` keeps bytes 148..152 zero while
//! `ASWP` uses those bytes for the withdrawal amount.  A nonzero in-note fee
//! therefore requires a future statement/profile version.

use aspis_core::field::{M31, P};

use crate::{
    decode_digest_canonical, derive_owner_key, encode_digest_canonical, poseidon2::Digest,
    VALUE_LIMIT,
};

use super::{
    format::{pool_v1_note_commitment, pool_v1_nullifier, pool_v1_tree_parent},
    historical_anchor::{
        validate_historical_anchor_envelope_v1, HistoricalAnchorEnvelopeV1, PoolV1TransitionKind,
    },
    POOL_V1_DIGEST_ENCODING_VERSION, POOL_V1_LEAF_CAPACITY, POOL_V1_TREE_DEPTH,
};

pub const POOL_V1_PAYMENT_STATEMENT_BYTES: usize = 216;
pub const POOL_V1_PAYMENT_STATEMENT_VERSION: u8 = 1;
pub const POOL_V1_PRIVATE_TRANSFER_STATEMENT_MAGIC: [u8; 4] = *b"ASCP";
pub const POOL_V1_WITHDRAWAL_STATEMENT_MAGIC: [u8; 4] = *b"ASWP";
/// Pool V1 has no caller-selectable in-note fee.
pub const POOL_V1_CANONICAL_FEE: u32 = 0;

const POOL_OFFSET: usize = 8;
const DEPLOYMENT_DOMAIN_OFFSET: usize = 40;
const ANCHOR_SEQUENCE_OFFSET: usize = 72;
const ANCHOR_ROOT_OFFSET: usize = 80;
const NULLIFIER_OFFSET: usize = 112;
const ASSET_ID_OFFSET: usize = 144;
const AMOUNT_OR_RESERVED_OFFSET: usize = 148;
const FIRST_OUTPUT_OR_DESTINATION_OFFSET: usize = 152;
const SECOND_OUTPUT_OFFSET: usize = 184;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct PoolV1PrivateTransferPublicV1 {
    pub pool: [u8; 32],
    pub deployment_domain: [u8; 32],
    pub anchor_sequence: u64,
    pub anchor_root: Digest,
    pub nullifier: Digest,
    pub asset_id: M31,
    pub recipient_commitment: Digest,
    pub change_commitment: Digest,
