#[inline(always)]
fn lift(value: M31) -> QM31 {
    QM31::from_cm31(CM31::from_m31(value))
}

#[derive(Clone)]
struct SelectorsV1 {
    high: [QM31; 64],
    low: [QM31; 16],
}

impl SelectorsV1 {
    fn expand<const N: usize>(coordinates: &[QM31]) -> [QM31; N] {
        let mut weights = [QM31::ZERO; N];
        weights[0] = QM31::ONE;
        let mut len = 1usize;
        for coordinate in coordinates {
            for index in (0..len).rev() {
                let parent = weights[index];
                let right = parent.mul(*coordinate);
                weights[2 * index] = parent.sub(right);
                weights[2 * index + 1] = right;
            }
            len *= 2;
        }
        weights
    }

    fn at_point(point: &[QM31; 10]) -> Self {
        Self {
            high: Self::expand(&point[..6]),
            low: Self::expand(&point[6..]),
        }
    }

    #[inline(always)]
    fn row(&self, row: usize) -> QM31 {
        self.high[row >> 4].mul(self.low[row & 15])
    }
}

fn first_sponge(block: usize, variant: PoolV1PaymentTraceVariantV1) -> Option<(M31, usize)> {
    use crate::spend::{DOMAIN_NOTE, DOMAIN_NULLIFIER, DOMAIN_OWNER_KEY};
    match block {
        0 => Some((DOMAIN_OWNER_KEY, 8)),
        1 => Some((DOMAIN_NOTE, 18)),
        24 => Some((DOMAIN_NULLIFIER, 16)),
        26 if variant == PoolV1PaymentTraceVariantV1::PrivateTransfer => Some((DOMAIN_NOTE, 18)),
        29 => Some((DOMAIN_NOTE, 18)),
        _ => None,
    }
}

fn fixed_zero_block(block: usize, variant: PoolV1PaymentTraceVariantV1) -> bool {
    (32..49).contains(&block)
        || (variant == PoolV1PaymentTraceVariantV1::Withdrawal && (26..=28).contains(&block))
}

fn expected_initial_limb(
    block: usize,
    lane: usize,
    variant: PoolV1PaymentTraceVariantV1,
) -> Option<M31> {
    if let Some((domain, length)) = first_sponge(block, variant) {
        let mut state = [M31::ZERO; POSEIDON2_WIDTH];
        state[RATE] = domain;
        state[RATE + 1] = M31(length as u32);
        return Some(state[lane]);
    }
    if (4..24).contains(&block) {
        return (lane < RATE).then_some(M31::ZERO);
    }
    fixed_zero_block(block, variant).then_some(M31::ZERO)
}

fn absorption_length(block: usize, variant: PoolV1PaymentTraceVariantV1) -> usize {
    match block {
        0 | 1 | 2 | 4..=25 | 26 | 27 | 29 | 30 => {
            if variant == PoolV1PaymentTraceVariantV1::Withdrawal && (26..=27).contains(&block) {
                0
            } else {
                8
            }
        }
        3 | 28 | 31 => {
            if variant == PoolV1PaymentTraceVariantV1::Withdrawal && block == 28 {
                0
            } else {
                2
            }
        }
        32..=48 => 0,
        _ => 0,
    }
}

#[derive(Clone, Copy)]
struct CopyRowExtensionV1 {
    producer_values: [QM31; 2],
    producer_weights: [QM31; 2],
    consumer_values: [QM31; 2],
    consumer_weights: [QM31; 2],
}

fn copy_residual(row: CopyRowExtensionV1, helper: QM31, chi: QM31) -> QM31 {
    let d = [
        chi.sub(row.producer_values[0]),
        chi.sub(row.producer_values[1]),
        chi.sub(row.consumer_values[0]),
        chi.sub(row.consumer_values[1]),
    ];
    let producer_denominator = d[0].mul(d[1]);
    let consumer_denominator = d[2].mul(d[3]);
    let producer_numerator = row.producer_weights[0]
        .mul(d[1])
        .add(row.producer_weights[1].mul(d[0]));
    let consumer_numerator = row.consumer_weights[0]
        .mul(d[3])
        .add(row.consumer_weights[1].mul(d[2]));
    producer_denominator
        .mul(helper.mul(consumer_denominator).add(consumer_numerator))
        .sub(consumer_denominator.mul(producer_numerator))
}

fn compressed_opened_tuple(
    tuple: PoolV1PaymentCopyTupleV1,
    tag: M31,
    selector: QM31,
    openings: &[QM31; POSEIDON2_WIDTH],
    powers: &[QM31; POSEIDON2_WIDTH],
) -> QM31 {
    let mut value = selector.mul_m31(tag);
    for (limb, power) in tuple.limbs.into_iter().zip(powers) {
        let opened = match limb {
            PoolV1PaymentTupleLimbV1::Zero => QM31::ZERO,
            PoolV1PaymentTupleLimbV1::Constant(constant) => lift(constant),
            PoolV1PaymentTupleLimbV1::AffineCell {
                cell,
                scale,
                offset,
            } => openings[usize::from(cell.column)]
                .mul_m31(scale)
                .add(lift(offset)),
        };
        value = value.add(selector.mul(opened).mul(*power));
    }
    value
}

fn copy_terminal(
    prepared: &PoolV1PaymentSemanticPreparedV1,
    openings: &[QM31; POSEIDON2_WIDTH],
    selectors: &SelectorsV1,
    lambda: QM31,
) -> Result<(CopyRowExtensionV1, QM31), PoolV1PaymentSemanticErrorV1> {
    let mut powers = [QM31::ZERO; POSEIDON2_WIDTH];
    let mut power = lambda;
    for output in &mut powers {
        *output = power;
        power = power.mul(lambda);
    }
    let mut row = CopyRowExtensionV1 {
        producer_values: [QM31::ZERO; 2],
        producer_weights: [QM31::ZERO; 2],
        consumer_values: [QM31::ZERO; 2],
        consumer_weights: [QM31::ZERO; 2],
    };
    let mut producer_arity = [0u8; POOL_V1_PAYMENT_TRACE_ROWS];
    let mut consumer_arity = [0u8; POOL_V1_PAYMENT_TRACE_ROWS];
    for link in &prepared.registry.links {
        for (tuple, arity, values, weights) in [
            (
                link.producer,
                &mut producer_arity,
                &mut row.producer_values,
                &mut row.producer_weights,
            ),
            (
                link.consumer,
                &mut consumer_arity,
                &mut row.consumer_values,
                &mut row.consumer_weights,
            ),
        ] {
            let endpoint_row = usize::from(tuple.row);
            let slot = usize::from(arity[endpoint_row]);
            if slot >= 2 {
                return Err(PoolV1PaymentSemanticErrorV1::CopyEndpointOverflow { row: tuple.row });
            }
            arity[endpoint_row] += 1;
            let selector = selectors.row(endpoint_row);
            weights[slot] = weights[slot].add(selector);
            values[slot] = values[slot].add(compressed_opened_tuple(
                tuple, link.tag, selector, openings, &powers,
            ));
        }
    }
    let mut active_rows = [false; POOL_V1_PAYMENT_TRACE_ROWS];
    for link in &prepared.registry.links {
        active_rows[usize::from(link.producer.row)] = true;
        active_rows[usize::from(link.consumer.row)] = true;
    }
    let active = active_rows
        .into_iter()
        .enumerate()
        .filter(|(_, active)| *active)
        .fold(QM31::ZERO, |sum, (row, _)| sum.add(selectors.row(row)));
    Ok((row, active))
}

/// Exact multilinear indicator of rows carrying at least one endpoint in the
/// selected host copy registry. The compiled terminal pins the same indicator
/// as variant-specific row masks.
pub fn pool_v1_payment_copy_active_at_point_v1(
    prepared: &PoolV1PaymentSemanticPreparedV1,
    point: &[QM31; 10],
) -> QM31 {
    let selectors = SelectorsV1::at_point(point);
    let mut active_rows = [false; POOL_V1_PAYMENT_TRACE_ROWS];
    for link in &prepared.registry.links {
        active_rows[usize::from(link.producer.row)] = true;
        active_rows[usize::from(link.consumer.row)] = true;
    }
    active_rows
        .into_iter()
        .enumerate()
        .filter(|(_, active)| *active)
        .fold(QM31::ZERO, |sum, (row, _)| sum.add(selectors.row(row)))
}

fn evaluate_prepared(
    public: SemanticPublicV1,
    openings: &PoolV1PaymentSemanticOpeningsV1,
    point: &[QM31; 10],
    lambda: QM31,
    chi: QM31,
    prepared: &PoolV1PaymentSemanticPreparedV1,
) -> Result<PoolV1PaymentSemanticResidualsV1, PoolV1PaymentSemanticErrorV1> {
    if public.variant != prepared.variant() {
        return Err(PoolV1PaymentSemanticErrorV1::WrongVariant);
    }
    if public
        .withdrawal_amount
        .is_some_and(|amount| amount == 0 || amount >= (1 << 30))
    {
        return Err(PoolV1PaymentSemanticErrorV1::InvalidPublicAmount);
    }
    let selectors = SelectorsV1::at_point(point);

    let mut initial = [QM31::ZERO; POOL_V1_PAYMENT_INITIAL_LANES];
    for block in 0..49 {
        let selector = selectors.row(block * POOL_V1_PAYMENT_TRACE_BLOCK_ROWS);
        for lane in 0..POSEIDON2_WIDTH {
            if let Some(expected) = expected_initial_limb(block, lane, public.variant) {
                initial[lane] =
                    initial[lane].add(selector.mul(openings.c1.z[lane].sub(lift(expected))));
            }
        }
    }
    // Undeclared auxiliary cells are relation-free masking material.  Every
    // declared cell remains bound below or by the copy registry.

    let mut absorption_zero = [QM31::ZERO; POOL_V1_PAYMENT_ABSORPTION_ZERO_LANES];
    for block in 0..49 {
        let selector = selectors.row(block * POOL_V1_PAYMENT_TRACE_BLOCK_ROWS + 12);
        let absorbed = absorption_length(block, public.variant);
        for lane in absorbed..POSEIDON2_WIDTH {
            absorption_zero[lane] = absorption_zero[lane].add(selector.mul(openings.c1.z[lane]));
        }
    }
    // Rows 13..15 are outside Poseidon and are relation-free masking material.

    let merkle_selector = (0..20).fold(QM31::ZERO, |sum, level| {
        sum.add(selectors.row(usize::from(
            pool_v1_payment_path_aux_v1(level).unwrap().bit.row,
        )))
    });
    let bit = openings.c1.z[0];
    let mut merkle = [QM31::ZERO; POOL_V1_PAYMENT_MERKLE_LANES];
    merkle[0] = merkle_selector.mul(bit.mul(bit.sub(QM31::ONE)));
    for lane in 0..DIGEST_ELEMS {
        let current = openings.c1.z[1 + lane];
        let sibling = openings.c1.xor12_z[lane];
        let delta = sibling.sub(current);
        merkle[1 + lane] =
            merkle_selector.mul(openings.c1.succ_z[lane].sub(current.add(bit.mul(delta))));
        merkle[1 + DIGEST_ELEMS + lane] =
            merkle_selector.mul(openings.c1.succ_z[RATE + lane].sub(sibling.sub(bit.mul(delta))));
    }

    let value_selectors: [QM31; 3] = core::array::from_fn(|value| {
        selectors.row(usize::from(
            pool_v1_payment_value_aux_v1(value).unwrap().source.row,
        ))
    });
    let range_selector = value_selectors.iter().copied().fold(QM31::ZERO, QM31::add);
    let views = [&openings.c1.z, &openings.c1.succ_z, &openings.c1.xor12_z];
    let mut direct_range = [QM31::ZERO; POOL_V1_PAYMENT_DIRECT_RANGE_LANES];
    for (view_index, view) in views.into_iter().enumerate() {
        for bit_index in 0..10 {
            direct_range[view_index * 10 + bit_index] =
                range_selector.mul(view[bit_index].mul(view[bit_index].sub(QM31::ONE)));
        }
    }

    let reconstructed_value = (0..10).fold(QM31::ZERO, |sum, bit_index| {
        sum.add(openings.c1.z[bit_index].mul_m31(M31(1 << bit_index)))
            .add(openings.c1.succ_z[bit_index].mul_m31(M31(1 << (10 + bit_index))))
            .add(openings.c1.xor12_z[bit_index].mul_m31(M31(1 << (20 + bit_index))))
    });
    direct_range[30] = value_selectors
        .iter()
        .copied()
        .fold(QM31::ZERO, |sum, selector| {
            sum.add(selector.mul(openings.c1.z[10].sub(reconstructed_value)))
        });
    // Only the base-row view carries the full 30-bit source in column ten.
    direct_range[31] = range_selector.mul(openings.c1.succ_z[10]);
    direct_range[32] = range_selector.mul(openings.c1.xor12_z[10]);

    let conservation_aux = pool_v1_payment_conservation_aux_v1();
    let conservation_selector = selectors.row(usize::from(conservation_aux.input.row));
    let value = [
        conservation_selector.mul(openings.c1.z[0].sub(openings.c1.z[1]).sub(openings.c1.z[2])),
        conservation_selector.mul(openings.c1.succ_z[0].sub(openings.c1.succ_z[1])),
    ];

    let mut public_digest = [QM31::ZERO; POOL_V1_PAYMENT_PUBLIC_DIGEST_LANES];
    let digest_rows = [
        (23usize, Some(public.anchor)),
        (25, Some(public.nullifier)),
        (28, public.recipient),
        (31, Some(public.change)),
    ];
    for (block, digest) in digest_rows {
        let Some(digest) = digest else {
            continue;
        };
        let selector = selectors.row(block * POOL_V1_PAYMENT_TRACE_BLOCK_ROWS + 11);
        for lane in 0..DIGEST_ELEMS {
            public_digest[lane] =
                public_digest[lane].add(selector.mul(openings.c1.z[lane].sub(lift(digest[lane]))));
        }
    }

    let input_asset_selector = selectors.row(2 * 16 + 12);
    let mut output_scalar = selectors
        .row(30 * 16 + 12)
        .mul(openings.c1.z[1].sub(lift(public.asset_id)));
    if public.variant == PoolV1PaymentTraceVariantV1::PrivateTransfer {
        output_scalar = output_scalar.add(
            selectors
                .row(27 * 16 + 12)
                .mul(openings.c1.z[1].sub(lift(public.asset_id))),
        );
    } else if let Some(amount) = public.withdrawal_amount {
        output_scalar =
            output_scalar.add(value_selectors[1].mul(openings.c1.z[10].sub(lift(M31(amount)))));
    }
    let public_scalar = [
        input_asset_selector.mul(openings.c1.z[1].sub(lift(public.asset_id))),
        output_scalar,
    ];

    let (terminal, copy_active) = copy_terminal(prepared, &openings.c1.z, &selectors, lambda)?;
    // Inactive helper cells are hiding padding and may be random pointwise.
    // The local cleared LogUp equation is therefore selected by the exact
    // active-row indicator. The Tag-73 terminal separately binds both the
    // total helper sum and `(1 - A) * H1`, which also fixes the active sum
    // outside the roots of the degree-two mu aggregate.
    let copy = copy_active.mul(copy_residual(terminal, openings.h1_z, chi));

    Ok(PoolV1PaymentSemanticResidualsV1 {
        initial,
        absorption_zero,
        merkle,
        direct_range,
        value,
        public_digest,
        public_scalar,
        copy,
    })
}

pub fn evaluate_pool_v1_private_transfer_semantic_oracle_v1(
    public: &PoolV1PrivateTransferPublicV1,
    openings: &PoolV1PaymentSemanticOpeningsV1,
    point: &[QM31; 10],
    lambda: QM31,
    chi: QM31,
    prepared: &PoolV1PaymentSemanticPreparedV1,
) -> Result<PoolV1PaymentSemanticResidualsV1, PoolV1PaymentSemanticErrorV1> {
    evaluate_prepared(
        SemanticPublicV1 {
            variant: PoolV1PaymentTraceVariantV1::PrivateTransfer,
            anchor: public.anchor_root,
            nullifier: public.nullifier,
            asset_id: public.asset_id,
            recipient: Some(public.recipient_commitment),
            change: public.change_commitment,
            withdrawal_amount: None,
        },
        openings,
        point,
        lambda,
        chi,
        prepared,
    )
}

pub fn evaluate_pool_v1_withdrawal_semantic_oracle_v1(
    public: &PoolV1WithdrawalPublicV1,
    openings: &PoolV1PaymentSemanticOpeningsV1,
    point: &[QM31; 10],
    lambda: QM31,
    chi: QM31,
    prepared: &PoolV1PaymentSemanticPreparedV1,
) -> Result<PoolV1PaymentSemanticResidualsV1, PoolV1PaymentSemanticErrorV1> {
    evaluate_prepared(
        SemanticPublicV1 {
            variant: PoolV1PaymentTraceVariantV1::Withdrawal,
            anchor: public.anchor_root,
            nullifier: public.nullifier,
            asset_id: public.asset_id,
            recipient: None,
            change: public.change_commitment,
            withdrawal_amount: Some(public.amount),
        },
        openings,
        point,
        lambda,
        chi,
        prepared,
    )
}

pub fn build_pool_v1_payment_copy_helper_v1(
    prepared: &PoolV1PaymentSemanticPreparedV1,
    trace: &StateOnlyTraceFoundation,
    lambda: QM31,
    chi: QM31,
) -> Result<Vec<QM31>, PoolV1PaymentSemanticErrorV1> {
    if trace
        .c1
        .iter()
        .any(|column| column.len() != POOL_V1_PAYMENT_TRACE_ROWS)
    {
        return Err(PoolV1PaymentSemanticErrorV1::Shape);
    }
    let rows: Vec<CopyLogUpRow> = pool_v1_payment_copy_rows_v1(&prepared.registry, trace, lambda)?;
    Ok(build_copy_logup_helper(&rows, chi)?)
}

pub fn pool_v1_payment_semantic_openings_at_point_v1(
    trace: &StateOnlyTraceFoundation,
    h1: &[QM31],
    point: &[QM31; 10],
) -> Option<PoolV1PaymentSemanticOpeningsV1> {
    Some(PoolV1PaymentSemanticOpeningsV1 {
        c1: state_only_poseidon_openings_at_point(&trace.c1, point)?,
        h1_z: multilinear_evaluate_qm31(h1, point)?,
    })
}

pub fn pool_v1_payment_copy_helper_sum_v1(h1: &[QM31]) -> Option<QM31> {
    (h1.len() == POOL_V1_PAYMENT_TRACE_ROWS).then(|| h1.iter().copied().fold(QM31::ZERO, QM31::add))
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::pool_v1::{
        payment_semantic_registry::pool_v1_payment_aux_cell_is_used_v1,
        POOL_V1_PAYMENT_TRACE_PERMUTATION_ROWS,
    };
    use crate::{
        derive_owner_key,
        pool_v1::{
            build_pool_v1_private_transfer_trace_v1, build_pool_v1_withdrawal_trace_v1,
            pool_v1_membership_root_v1, pool_v1_note_commitment, pool_v1_nullifier,
            PoolV1InputNoteWitnessV1, PoolV1MembershipWitnessV1, PoolV1OutputNoteWitnessV1,
            PoolV1PaymentRelationContextV1, PoolV1PaymentRuntimeBindingV1,
            PoolV1PrivateTransferWitnessV1, PoolV1WithdrawalWitnessV1,
        },
    };

    fn digest(seed: u32) -> Digest {
        core::array::from_fn(|index| M31(seed + 17 * index as u32))
    }

    fn input(value: u32) -> PoolV1InputNoteWitnessV1 {
        PoolV1InputNoteWitnessV1 {
            nullifier_key: digest(10),
            salt: digest(100),
            value,
            membership: PoolV1MembershipWitnessV1 {
                siblings: core::array::from_fn(|level| digest(1_000 + level as u32 * 100)),
                index: 0x5_4321,
            },
        }
    }

    fn output(seed: u32, value: u32) -> PoolV1OutputNoteWitnessV1 {
        PoolV1OutputNoteWitnessV1 {
            owner_key: digest(seed),
            salt: digest(seed + 100),
            value,
        }
    }

    fn transfer_fixture() -> (
        PoolV1PrivateTransferPublicV1,
        PoolV1PrivateTransferWitnessV1,
        PoolV1PaymentRelationContextV1<'static>,
    ) {
        let witness = PoolV1PrivateTransferWitnessV1 {
            input: input(1_000),
            recipient: output(300, 600),
            change: output(500, 400),
        };
        let asset_id = M31(77);
        let owner_key = derive_owner_key(&witness.input.nullifier_key);
        let leaf = pool_v1_note_commitment(
            &owner_key,
            witness.input.value,
            asset_id,
            &witness.input.salt,
        );
        let anchor_root = pool_v1_membership_root_v1(leaf, &witness.input.membership).unwrap();
        let public = PoolV1PrivateTransferPublicV1 {
            pool: [1; 32],
            deployment_domain: [2; 32],
            anchor_sequence: 42,
            anchor_root,
            nullifier: pool_v1_nullifier(&witness.input.nullifier_key, &witness.input.salt),
            asset_id,
            recipient_commitment: pool_v1_note_commitment(
                &witness.recipient.owner_key,
                witness.recipient.value,
                asset_id,
                &witness.recipient.salt,
            ),
            change_commitment: pool_v1_note_commitment(
                &witness.change.owner_key,
                witness.change.value,
                asset_id,
                &witness.change.salt,
            ),
        };
        let context = PoolV1PaymentRelationContextV1 {
            runtime_binding: PoolV1PaymentRuntimeBindingV1 {
                pool: public.pool,
                deployment_domain: public.deployment_domain,
                anchor_sequence: public.anchor_sequence,
                anchor_root: public.anchor_root,
                asset_id: public.asset_id,
            },
            spent_nullifiers: &[],
        };
        (public, witness, context)
    }

    fn withdrawal_fixture() -> (
        PoolV1WithdrawalPublicV1,
        PoolV1WithdrawalWitnessV1,
        PoolV1PaymentRelationContextV1<'static>,
    ) {
        let witness = PoolV1WithdrawalWitnessV1 {
            input: input(1_000),
            change: output(700, 750),
        };
        let asset_id = M31(77);
        let owner_key = derive_owner_key(&witness.input.nullifier_key);
        let leaf = pool_v1_note_commitment(
            &owner_key,
            witness.input.value,
            asset_id,
            &witness.input.salt,
        );
        let anchor_root = pool_v1_membership_root_v1(leaf, &witness.input.membership).unwrap();
        let public = PoolV1WithdrawalPublicV1 {
            pool: [1; 32],
            deployment_domain: [2; 32],
            anchor_sequence: 42,
            anchor_root,
            nullifier: pool_v1_nullifier(&witness.input.nullifier_key, &witness.input.salt),
            asset_id,
            amount: 250,
            destination_token_account: [9; 32],
            change_commitment: pool_v1_note_commitment(
                &witness.change.owner_key,
                witness.change.value,
                asset_id,
                &witness.change.salt,
            ),
        };
        let context = PoolV1PaymentRelationContextV1 {
            runtime_binding: PoolV1PaymentRuntimeBindingV1 {
                pool: public.pool,
                deployment_domain: public.deployment_domain,
                anchor_sequence: public.anchor_sequence,
                anchor_root: public.anchor_root,
                asset_id: public.asset_id,
            },
            spent_nullifiers: &[],
        };
        (public, witness, context)
    }

    fn challenges() -> (QM31, QM31) {
        (
            QM31 {
                c0: CM31::new(M31(123), M31(456)),
                c1: CM31::new(M31(789), M31(1_011)),
            },
            QM31 {
                c0: CM31::new(M31(1_213), M31(1_415)),
                c1: CM31::new(M31(1_617), M31(1_819)),
            },
        )
    }

    fn boolean_point(row: usize) -> [QM31; 10] {
        core::array::from_fn(|coordinate| {
            if (row >> (9 - coordinate)) & 1 == 0 {
                QM31::ZERO
            } else {
                QM31::ONE
            }
        })
    }

    #[test]
    fn honest_variants_zero_all_95_semantic_lanes_on_every_boolean_row() {
        let (lambda, chi) = challenges();

        let (public, witness, context) = transfer_fixture();
        let trace = build_pool_v1_private_transfer_trace_v1(&public, &witness, context).unwrap();
        let prepared = prepare_pool_v1_payment_semantic_oracle_v1(
            PoolV1PaymentTraceVariantV1::PrivateTransfer,
        )
        .unwrap();
        let h1 =
            build_pool_v1_payment_copy_helper_v1(&prepared, &trace.trace, lambda, chi).unwrap();
        assert_eq!(pool_v1_payment_copy_helper_sum_v1(&h1), Some(QM31::ZERO));
        for row in 0..POOL_V1_PAYMENT_TRACE_ROWS {
            let point = boolean_point(row);
            let openings =
                pool_v1_payment_semantic_openings_at_point_v1(&trace.trace, &h1, &point).unwrap();
            let residuals = evaluate_pool_v1_private_transfer_semantic_oracle_v1(
                &public, &openings, &point, lambda, chi, &prepared,
            )
            .unwrap();
            assert!(residuals.all_zero(), "transfer row {row}: {residuals:?}");
            assert_eq!(residuals.packed_base_lanes().len(), 24);
        }

        let (public, witness, context) = withdrawal_fixture();
        let trace = build_pool_v1_withdrawal_trace_v1(&public, &witness, context).unwrap();
        let prepared =
            prepare_pool_v1_payment_semantic_oracle_v1(PoolV1PaymentTraceVariantV1::Withdrawal)
                .unwrap();
        let h1 =
            build_pool_v1_payment_copy_helper_v1(&prepared, &trace.trace, lambda, chi).unwrap();
        assert_eq!(pool_v1_payment_copy_helper_sum_v1(&h1), Some(QM31::ZERO));
        for row in 0..POOL_V1_PAYMENT_TRACE_ROWS {
            let point = boolean_point(row);
            let openings =
                pool_v1_payment_semantic_openings_at_point_v1(&trace.trace, &h1, &point).unwrap();
            let residuals = evaluate_pool_v1_withdrawal_semantic_oracle_v1(
                &public, &openings, &point, lambda, chi, &prepared,
            )
            .unwrap();
            assert!(residuals.all_zero(), "withdrawal row {row}: {residuals:?}");
        }
    }

    #[test]
    fn withdrawal_amount_is_bound_at_its_exact_routed_row() {
        let (lambda, chi) = challenges();
        let (public, witness, context) = withdrawal_fixture();
        let trace = build_pool_v1_withdrawal_trace_v1(&public, &witness, context).unwrap();
        let prepared =
            prepare_pool_v1_payment_semantic_oracle_v1(PoolV1PaymentTraceVariantV1::Withdrawal)
                .unwrap();
        let h1 =
            build_pool_v1_payment_copy_helper_v1(&prepared, &trace.trace, lambda, chi).unwrap();
        let amount_row = usize::from(pool_v1_payment_value_aux_v1(1).unwrap().source.row);
        let point = boolean_point(amount_row);
        let openings =
            pool_v1_payment_semantic_openings_at_point_v1(&trace.trace, &h1, &point).unwrap();
        let mut changed = public;
        changed.amount += 1;
        let residuals = evaluate_pool_v1_withdrawal_semantic_oracle_v1(
            &changed, &openings, &point, lambda, chi, &prepared,
        )
        .unwrap();
        assert!(!residuals.all_zero());
        assert_ne!(residuals.public_scalar[1], QM31::ZERO);

        changed.amount = 0;
        assert_eq!(
            evaluate_pool_v1_withdrawal_semantic_oracle_v1(
                &changed, &openings, &point, lambda, chi, &prepared,
            ),
            Err(PoolV1PaymentSemanticErrorV1::InvalidPublicAmount)
        );
    }

    #[test]
    fn inactive_copy_helper_rows_are_not_constrained_pointwise() {
        let (lambda, chi) = challenges();
        let (public, witness, context) = transfer_fixture();
        let trace = build_pool_v1_private_transfer_trace_v1(&public, &witness, context).unwrap();
        let prepared = prepare_pool_v1_payment_semantic_oracle_v1(
            PoolV1PaymentTraceVariantV1::PrivateTransfer,
        )
        .unwrap();
        let mut active = [false; POOL_V1_PAYMENT_TRACE_ROWS];
        for link in &prepared.registry().links {
            active[usize::from(link.producer.row)] = true;
            active[usize::from(link.consumer.row)] = true;
        }
        let inactive = active
            .iter()
            .enumerate()
            .filter_map(|(row, is_active)| (!is_active).then_some(row))
            .take(2)
            .collect::<Vec<_>>();
        assert_eq!(inactive.len(), 2);

        let mut h1 = alloc::vec![QM31::ZERO; POOL_V1_PAYMENT_TRACE_ROWS];
        h1[inactive[0]] = QM31::ONE;
        h1[inactive[1]] = QM31::ZERO.sub(QM31::ONE);
        assert_eq!(pool_v1_payment_copy_helper_sum_v1(&h1), Some(QM31::ZERO));

        for row in inactive {
            let point = boolean_point(row);
            let openings =
                pool_v1_payment_semantic_openings_at_point_v1(&trace.trace, &h1, &point).unwrap();
            let residuals = evaluate_pool_v1_private_transfer_semantic_oracle_v1(
                &public, &openings, &point, lambda, chi, &prepared,
            )
            .unwrap();
            assert_eq!(residuals.copy, QM31::ZERO, "inactive helper row {row}");
        }
    }

    #[test]
    fn permutation_and_auxiliary_padding_cells_are_relation_free() {
        let (lambda, chi) = challenges();
        let (public, witness, context) = transfer_fixture();
        let honest = build_pool_v1_private_transfer_trace_v1(&public, &witness, context).unwrap();
        let prepared = prepare_pool_v1_payment_semantic_oracle_v1(
            PoolV1PaymentTraceVariantV1::PrivateTransfer,
        )
        .unwrap();
        let h1 =
            build_pool_v1_payment_copy_helper_v1(&prepared, &honest.trace, lambda, chi).unwrap();

        for (row, lane) in [
            (13usize, 7usize),
            (POOL_V1_PAYMENT_TRACE_ROWS - 1, POSEIDON2_WIDTH - 1),
        ] {
            assert!(
                row < POOL_V1_PAYMENT_TRACE_PERMUTATION_ROWS
                    || !pool_v1_payment_aux_cell_is_used_v1(row, lane)
            );
            let mut changed = honest.trace.clone();
            changed.c1[lane][row] = M31(1);
            let point = boolean_point(row);
            let openings =
                pool_v1_payment_semantic_openings_at_point_v1(&changed, &h1, &point).unwrap();
            let residuals = evaluate_pool_v1_private_transfer_semantic_oracle_v1(
                &public, &openings, &point, lambda, chi, &prepared,
            )
            .unwrap();
            assert!(residuals.all_zero(), "padding cell ({row}, {lane})");
        }
    }
}

//! Exact row-local routing registry for the Pool V1 Tag-73 payment trace.
//!
//! The payment trace uses the frozen 1,024-row, 16-C1 geometry.  Cross-row
//! equalities are represented by one bounded two-producer/two-consumer LogUp
//! helper, while path selection and 30-bit value checks are placed in the
//! existing `(z, successor(z), xor12(z))` three-point geometry.  This module
//! is still a host/compiler foundation: it does not alter the production
//! verifier or claim that the Pool relation is accepted on chain.

use alloc::{vec, vec::Vec};

use aspis_core::field::{M31, QM31};

use crate::{
    logup::{
        build_copy_logup_helper, compress_tagged_tuple, verify_copy_logup_constraints, CopyLogUpRow,
    },
    poseidon2::{DIGEST_ELEMS, MERKLE_NODE_COMPRESSION_V3_TWEAK, POSEIDON2_WIDTH},
    state_only_trace::StateOnlyTraceFoundation,
    trace_v4::TraceCell,
};

use super::payment_trace::{
    PoolV1PaymentTraceVariantV1, POOL_V1_PAYMENT_TRACE_BLOCK_ROWS, POOL_V1_PAYMENT_TRACE_ROWS,
};

pub const POOL_V1_PAYMENT_PATH_AUX_BLOCK_START: usize = 49;
pub const POOL_V1_PAYMENT_PATH_LEVELS_PER_AUX_BLOCK: usize = 4;
pub const POOL_V1_PAYMENT_PATH_AUX_BLOCKS: usize = 5;
pub const POOL_V1_PAYMENT_VALUE_AUX_BLOCK: usize = 54;
pub const POOL_V1_PAYMENT_VALUE_AUX_ROW_START: usize =
    POOL_V1_PAYMENT_VALUE_AUX_BLOCK * POOL_V1_PAYMENT_TRACE_BLOCK_ROWS;
pub const POOL_V1_PAYMENT_AUX_ROW_END: usize = 879;

pub const POOL_V1_PAYMENT_BASE_SEMANTIC_LANES: usize = 94;
pub const POOL_V1_PAYMENT_PACKED_BASE_LANES: usize =
    POOL_V1_PAYMENT_BASE_SEMANTIC_LANES.div_ceil(4);
pub const POOL_V1_PAYMENT_COPY_LANES: usize = 1;
pub const POOL_V1_PAYMENT_SEMANTIC_LANES: usize =
    POOL_V1_PAYMENT_BASE_SEMANTIC_LANES + POOL_V1_PAYMENT_COPY_LANES;
pub const POOL_V1_PAYMENT_RANDOMIZED_SEMANTIC_LANES: usize =
    POOL_V1_PAYMENT_PACKED_BASE_LANES + POOL_V1_PAYMENT_COPY_LANES;
pub const POOL_V1_PAYMENT_POSEIDON_LANES: usize = 4;
pub const POOL_V1_PAYMENT_THETA_LANES: usize =
    POOL_V1_PAYMENT_POSEIDON_LANES + POOL_V1_PAYMENT_RANDOMIZED_SEMANTIC_LANES;
pub const POOL_V1_PAYMENT_THETA_COLLISION_DEGREE: usize = POOL_V1_PAYMENT_THETA_LANES - 1;
pub const POOL_V1_PAYMENT_ZEROCHECK_DEGREE: usize = 27;

const PATH_BASE_LOCAL_ROWS: [usize; POOL_V1_PAYMENT_PATH_LEVELS_PER_AUX_BLOCK] = [0, 2, 4, 6];
const VALUE_BASE_LOCAL_ROWS: [usize; 3] = [0, 2, 4];
const CONSERVATION_BASE_LOCAL_ROW: usize = 6;
const COPY_TAG_BASE: u32 = 0x4100_0000;

const _: () = assert!(DIGEST_ELEMS == 8);
const _: () = assert!(POSEIDON2_WIDTH == 16);
const _: () = assert!(POOL_V1_PAYMENT_PATH_AUX_BLOCKS * 4 == 20);
const _: () = assert!(POOL_V1_PAYMENT_PACKED_BASE_LANES == 24);
const _: () = assert!(POOL_V1_PAYMENT_RANDOMIZED_SEMANTIC_LANES == 25);
const _: () = assert!(POOL_V1_PAYMENT_SEMANTIC_LANES == 95);
const _: () = assert!(POOL_V1_PAYMENT_THETA_LANES == 29);
const _: () = assert!(POOL_V1_PAYMENT_THETA_COLLISION_DEGREE == 28);
const _: () = assert!(POOL_V1_PAYMENT_AUX_ROW_END <= POOL_V1_PAYMENT_TRACE_ROWS);

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct PoolV1PaymentPathAuxV1 {
    pub bit: TraceCell,
    pub current: [TraceCell; DIGEST_ELEMS],
    pub left: [TraceCell; DIGEST_ELEMS],
    pub right: [TraceCell; DIGEST_ELEMS],
    pub sibling: [TraceCell; DIGEST_ELEMS],
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct PoolV1PaymentValueAuxV1 {
    pub bits: [TraceCell; 30],
    pub source: TraceCell,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct PoolV1PaymentConservationAuxV1 {
    pub input: TraceCell,
    pub recipient_or_amount: TraceCell,
    pub partial: TraceCell,
    pub carried_partial: TraceCell,
    pub change: TraceCell,
}

#[inline(always)]
const fn cell(row: usize, column: usize) -> TraceCell {
    TraceCell {
        row: row as u16,
        column: column as u8,
    }
}

#[inline(always)]
const fn xor12_row(row: usize) -> usize {
    row ^ 12
}

pub fn pool_v1_payment_path_aux_v1(level: usize) -> Option<PoolV1PaymentPathAuxV1> {
    if level >= 20 {
        return None;
    }
    let block =
        POOL_V1_PAYMENT_PATH_AUX_BLOCK_START + level / POOL_V1_PAYMENT_PATH_LEVELS_PER_AUX_BLOCK;
    let local = PATH_BASE_LOCAL_ROWS[level % POOL_V1_PAYMENT_PATH_LEVELS_PER_AUX_BLOCK];
    let base = block * POOL_V1_PAYMENT_TRACE_BLOCK_ROWS + local;
    let successor = base + 1;
    let sibling = xor12_row(base);
    Some(PoolV1PaymentPathAuxV1 {
        bit: cell(base, 0),
        current: core::array::from_fn(|lane| cell(base, 1 + lane)),
        left: core::array::from_fn(|lane| cell(successor, lane)),
        right: core::array::from_fn(|lane| cell(successor, 8 + lane)),
        sibling: core::array::from_fn(|lane| cell(sibling, lane)),
    })
}

pub fn pool_v1_payment_value_aux_v1(value: usize) -> Option<PoolV1PaymentValueAuxV1> {
    if value >= 3 {
        return None;
    }
    let base = POOL_V1_PAYMENT_VALUE_AUX_ROW_START + VALUE_BASE_LOCAL_ROWS[value];
    Some(PoolV1PaymentValueAuxV1 {
        bits: core::array::from_fn(|bit| {
            let view = bit / 10;
            let row = match view {
                0 => base,
                1 => base + 1,
                _ => xor12_row(base),
            };
            cell(row, bit % 10)
        }),
        source: cell(base, 10),
    })
}

pub const fn pool_v1_payment_conservation_aux_v1() -> PoolV1PaymentConservationAuxV1 {
    let base = POOL_V1_PAYMENT_VALUE_AUX_ROW_START + CONSERVATION_BASE_LOCAL_ROW;
    PoolV1PaymentConservationAuxV1 {
        input: cell(base, 0),
        recipient_or_amount: cell(base, 1),
        partial: cell(base, 2),
        carried_partial: cell(base + 1, 0),
        change: cell(base + 1, 1),
    }
}

pub fn pool_v1_payment_aux_cell_is_used_v1(row: usize, column: usize) -> bool {
    if row >= POOL_V1_PAYMENT_TRACE_ROWS || column >= POSEIDON2_WIDTH {
        return false;
    }
    let target = cell(row, column);
    for level in 0..20 {
        let Some(aux) = pool_v1_payment_path_aux_v1(level) else {
            return false;
        };
        if target == aux.bit
            || aux.current.contains(&target)
            || aux.left.contains(&target)
            || aux.right.contains(&target)
            || aux.sibling.contains(&target)
        {
            return true;
        }
    }
    for value in 0..3 {
        let Some(aux) = pool_v1_payment_value_aux_v1(value) else {
            return false;
        };
        if target == aux.source || aux.bits.contains(&target) {
            return true;
        }
    }
    let conservation = pool_v1_payment_conservation_aux_v1();
    target == conservation.input
        || target == conservation.recipient_or_amount
        || target == conservation.partial
        || target == conservation.carried_partial
        || target == conservation.change
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum PoolV1PaymentTupleLimbV1 {
    Zero,
    Constant(M31),
    AffineCell {
        cell: TraceCell,
        scale: M31,
        offset: M31,
    },
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct PoolV1PaymentCopyTupleV1 {
    pub row: u16,
    pub limbs: [PoolV1PaymentTupleLimbV1; POSEIDON2_WIDTH],
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum PoolV1PaymentCopyLinkKindV1 {
    SpongeCarry { from: u8, to: u8 },
    OwnerOutput,
    NullifierKey,
    InputSaltHead,
    InputSaltTail,
    PathCurrent { level: u8 },
    PathLeft { level: u8 },
    PathRight { level: u8 },
    ValueSource { value: u8 },
    ConservationInput,
    ConservationRecipientOrAmount,
    ConservationChange,
    ConservationPartial,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct PoolV1PaymentCopyLinkV1 {
    pub id: u16,
    pub tag: M31,
    pub kind: PoolV1PaymentCopyLinkKindV1,
    pub producer: PoolV1PaymentCopyTupleV1,
    pub consumer: PoolV1PaymentCopyTupleV1,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct PoolV1PaymentSemanticRegistryV1 {
    pub variant: PoolV1PaymentTraceVariantV1,
    pub links: Vec<PoolV1PaymentCopyLinkV1>,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum PoolV1PaymentSemanticRegistryErrorV1 {
    Layout,
    NonRowLocalTuple { link: u16 },
    EndpointCapacity { row: u16 },
    CopyImbalance,
}

const POOL_V1_PAYMENT_SEMANTIC_REGISTRY_FINGERPRINT_DOMAIN_V1: &[u8] =
    b"aspis/pool-v1/payment-semantic-registry/v1";

#[inline(always)]
fn fingerprint_byte(hash: &mut u64, byte: u8) {
    *hash ^= u64::from(byte);
    *hash = hash.wrapping_mul(0x0000_0100_0000_01b3);
}

fn fingerprint_kind(hash: &mut u64, kind: PoolV1PaymentCopyLinkKindV1) {
    let (tag, parameter) = match kind {
        PoolV1PaymentCopyLinkKindV1::SpongeCarry { from, to } => {
            fingerprint_byte(hash, 0);
            fingerprint_byte(hash, from);
            fingerprint_byte(hash, to);
            return;
        }
        PoolV1PaymentCopyLinkKindV1::OwnerOutput => (1, 0),
        PoolV1PaymentCopyLinkKindV1::NullifierKey => (2, 0),
        PoolV1PaymentCopyLinkKindV1::InputSaltHead => (3, 0),
        PoolV1PaymentCopyLinkKindV1::InputSaltTail => (4, 0),
        PoolV1PaymentCopyLinkKindV1::PathCurrent { level } => (5, level),
        PoolV1PaymentCopyLinkKindV1::PathLeft { level } => (6, level),
        PoolV1PaymentCopyLinkKindV1::PathRight { level } => (7, level),
        PoolV1PaymentCopyLinkKindV1::ValueSource { value } => (8, value),
        PoolV1PaymentCopyLinkKindV1::ConservationInput => (9, 0),
        PoolV1PaymentCopyLinkKindV1::ConservationRecipientOrAmount => (10, 0),
        PoolV1PaymentCopyLinkKindV1::ConservationChange => (11, 0),
        PoolV1PaymentCopyLinkKindV1::ConservationPartial => (12, 0),
    };
    fingerprint_byte(hash, tag);
    fingerprint_byte(hash, parameter);
}

fn fingerprint_tuple(hash: &mut u64, tuple: PoolV1PaymentCopyTupleV1) {
    for byte in tuple.row.to_le_bytes() {
        fingerprint_byte(hash, byte);
    }
    for limb in tuple.limbs {
        match limb {
            PoolV1PaymentTupleLimbV1::Zero => fingerprint_byte(hash, 0),
            PoolV1PaymentTupleLimbV1::Constant(value) => {
                fingerprint_byte(hash, 1);
                for byte in value.0.to_le_bytes() {
                    fingerprint_byte(hash, byte);
                }
            }
            PoolV1PaymentTupleLimbV1::AffineCell {
                cell,
                scale,
                offset,
            } => {
                fingerprint_byte(hash, 2);
                for byte in cell.row.to_le_bytes() {
                    fingerprint_byte(hash, byte);
                }
                fingerprint_byte(hash, cell.column);
                for value in [scale.0, offset.0] {
                    for byte in value.to_le_bytes() {
                        fingerprint_byte(hash, byte);
                    }
                }
            }
        }
    }
}

/// FNV-1a identity of the complete ordered host registry, including variant,
/// semantic link kinds, tags and every affine tuple limb. Generated terminal
/// constants pin this value and independently compare every compiled endpoint
/// and pattern in tests.
pub fn pool_v1_payment_semantic_registry_fingerprint_v1(
    registry: &PoolV1PaymentSemanticRegistryV1,
) -> Result<u64, PoolV1PaymentSemanticRegistryErrorV1> {
    endpoint_slots(registry)?;
    let mut hash = 0xcbf2_9ce4_8422_2325u64;
    for &byte in POOL_V1_PAYMENT_SEMANTIC_REGISTRY_FINGERPRINT_DOMAIN_V1 {
        fingerprint_byte(&mut hash, byte);
    }
    fingerprint_byte(
        &mut hash,
        match registry.variant {
            PoolV1PaymentTraceVariantV1::PrivateTransfer => 0,
            PoolV1PaymentTraceVariantV1::Withdrawal => 1,
        },
    );
    for byte in (registry.links.len() as u16).to_le_bytes() {
        fingerprint_byte(&mut hash, byte);
    }
    for link in &registry.links {
        for byte in link.id.to_le_bytes() {
            fingerprint_byte(&mut hash, byte);
        }
        for byte in link.tag.0.to_le_bytes() {
            fingerprint_byte(&mut hash, byte);
        }
        fingerprint_kind(&mut hash, link.kind);
        fingerprint_tuple(&mut hash, link.producer);
        fingerprint_tuple(&mut hash, link.consumer);
    }
    Ok(hash)
}

fn affine(source: TraceCell) -> PoolV1PaymentTupleLimbV1 {
    PoolV1PaymentTupleLimbV1::AffineCell {
        cell: source,
        scale: M31::ONE,
        offset: M31::ZERO,
    }
}

fn affine_offset(source: TraceCell, offset: M31) -> PoolV1PaymentTupleLimbV1 {
    PoolV1PaymentTupleLimbV1::AffineCell {
        cell: source,
        scale: M31::ONE,
        offset,
    }
}

fn tuple(row: usize, limbs: &[PoolV1PaymentTupleLimbV1]) -> PoolV1PaymentCopyTupleV1 {
    let mut output = [PoolV1PaymentTupleLimbV1::Zero; POSEIDON2_WIDTH];
    output[..limbs.len()].copy_from_slice(limbs);
    PoolV1PaymentCopyTupleV1 {
        row: row as u16,
        limbs: output,
    }
}

fn cells_tuple(row: usize, cells: &[TraceCell]) -> PoolV1PaymentCopyTupleV1 {
    tuple(row, &cells.iter().copied().map(affine).collect::<Vec<_>>())
}

fn block_cells(block: usize, local_row: usize, start: usize, count: usize) -> Vec<TraceCell> {
    let row = block * POOL_V1_PAYMENT_TRACE_BLOCK_ROWS + local_row;
    (start..start + count)
        .map(|column| cell(row, column))
        .collect()
}

fn push_link(
    links: &mut Vec<PoolV1PaymentCopyLinkV1>,
    kind: PoolV1PaymentCopyLinkKindV1,
    producer: PoolV1PaymentCopyTupleV1,
    consumer: PoolV1PaymentCopyTupleV1,
) {
    let id = links.len() as u16;
    links.push(PoolV1PaymentCopyLinkV1 {
        id,
        tag: M31(COPY_TAG_BASE + u32::from(id)),
        kind,
        producer,
        consumer,
    });
}

pub fn build_pool_v1_payment_semantic_registry_v1(
    variant: PoolV1PaymentTraceVariantV1,
) -> Result<PoolV1PaymentSemanticRegistryV1, PoolV1PaymentSemanticRegistryErrorV1> {
    let mut links = Vec::new();

    let mut carries = vec![(1usize, 2usize), (2, 3), (24, 25), (29, 30), (30, 31)];
    if variant == PoolV1PaymentTraceVariantV1::PrivateTransfer {
        carries.extend([(26, 27), (27, 28)]);
    }
    for (from, to) in carries {
        push_link(
            &mut links,
            PoolV1PaymentCopyLinkKindV1::SpongeCarry {
                from: from as u8,
                to: to as u8,
            },
            cells_tuple(from * 16 + 11, &block_cells(from, 11, 0, POSEIDON2_WIDTH)),
            cells_tuple(to * 16, &block_cells(to, 0, 0, POSEIDON2_WIDTH)),
        );
    }

    push_link(
        &mut links,
        PoolV1PaymentCopyLinkKindV1::OwnerOutput,
        cells_tuple(11, &block_cells(0, 11, 0, DIGEST_ELEMS)),
        cells_tuple(1 * 16 + 12, &block_cells(1, 12, 0, DIGEST_ELEMS)),
    );
    push_link(
        &mut links,
        PoolV1PaymentCopyLinkKindV1::NullifierKey,
        cells_tuple(12, &block_cells(0, 12, 0, DIGEST_ELEMS)),
        cells_tuple(24 * 16 + 12, &block_cells(24, 12, 0, DIGEST_ELEMS)),
    );
    push_link(
        &mut links,
        PoolV1PaymentCopyLinkKindV1::InputSaltHead,
        cells_tuple(2 * 16 + 12, &block_cells(2, 12, 2, 6)),
        cells_tuple(25 * 16 + 12, &block_cells(25, 12, 0, 6)),
    );
    push_link(
        &mut links,
        PoolV1PaymentCopyLinkKindV1::InputSaltTail,
        cells_tuple(3 * 16 + 12, &block_cells(3, 12, 0, 2)),
        cells_tuple(25 * 16 + 12, &block_cells(25, 12, 6, 2)),
    );

    for level in 0..20 {
        let aux = pool_v1_payment_path_aux_v1(level)
            .ok_or(PoolV1PaymentSemanticRegistryErrorV1::Layout)?;
        let previous_block = 3 + level;
        push_link(
            &mut links,
            PoolV1PaymentCopyLinkKindV1::PathCurrent { level: level as u8 },
            cells_tuple(
                previous_block * 16 + 11,
                &block_cells(previous_block, 11, 0, DIGEST_ELEMS),
            ),
            cells_tuple(usize::from(aux.current[0].row), &aux.current),
        );
        push_link(
            &mut links,
            PoolV1PaymentCopyLinkKindV1::PathLeft { level: level as u8 },
            cells_tuple(usize::from(aux.left[0].row), &aux.left),
            cells_tuple(
                (4 + level) * 16 + 12,
                &block_cells(4 + level, 12, 0, DIGEST_ELEMS),
            ),
        );
        let actual_right = block_cells(4 + level, 0, 8, DIGEST_ELEMS);
        let mut adjusted = actual_right.iter().copied().map(affine).collect::<Vec<_>>();
        adjusted[DIGEST_ELEMS - 1] = affine_offset(
            actual_right[DIGEST_ELEMS - 1],
            M31::ZERO.sub(MERKLE_NODE_COMPRESSION_V3_TWEAK),
        );
        push_link(
            &mut links,
            PoolV1PaymentCopyLinkKindV1::PathRight { level: level as u8 },
            cells_tuple(usize::from(aux.right[0].row), &aux.right),
            tuple((4 + level) * 16, &adjusted),
        );
    }

    let source_cells = [
        cell(2 * 16 + 12, 0),
        cell(27 * 16 + 12, 0),
        cell(30 * 16 + 12, 0),
    ];
    for value in 0..3 {
        if value == 1 && variant == PoolV1PaymentTraceVariantV1::Withdrawal {
            continue;
        }
        let aux = pool_v1_payment_value_aux_v1(value)
            .ok_or(PoolV1PaymentSemanticRegistryErrorV1::Layout)?;
        push_link(
            &mut links,
            PoolV1PaymentCopyLinkKindV1::ValueSource { value: value as u8 },
            cells_tuple(usize::from(source_cells[value].row), &[source_cells[value]]),
            cells_tuple(usize::from(aux.source.row), &[aux.source]),
        );
    }

    let conservation = pool_v1_payment_conservation_aux_v1();
    for (kind, value, destination) in [
        (
            PoolV1PaymentCopyLinkKindV1::ConservationInput,
            0usize,
            conservation.input,
        ),
        (
            PoolV1PaymentCopyLinkKindV1::ConservationRecipientOrAmount,
            1usize,
            conservation.recipient_or_amount,
        ),
        (
            PoolV1PaymentCopyLinkKindV1::ConservationChange,
            2usize,
            conservation.change,
        ),
    ] {
        let source = pool_v1_payment_value_aux_v1(value)
            .ok_or(PoolV1PaymentSemanticRegistryErrorV1::Layout)?
            .source;
        push_link(
            &mut links,
            kind,
            cells_tuple(usize::from(source.row), &[source]),
            cells_tuple(usize::from(destination.row), &[destination]),
        );
    }
    push_link(
        &mut links,
        PoolV1PaymentCopyLinkKindV1::ConservationPartial,
        cells_tuple(
            usize::from(conservation.partial.row),
            &[conservation.partial],
        ),
        cells_tuple(
            usize::from(conservation.carried_partial.row),
            &[conservation.carried_partial],
        ),
    );

    let registry = PoolV1PaymentSemanticRegistryV1 { variant, links };
    endpoint_slots(&registry)?;
    Ok(registry)
}

fn tuple_row(
    tuple: PoolV1PaymentCopyTupleV1,
    link: u16,
) -> Result<u16, PoolV1PaymentSemanticRegistryErrorV1> {
    for limb in tuple.limbs {
        if let PoolV1PaymentTupleLimbV1::AffineCell { cell, .. } = limb {
            if cell.row != tuple.row {
                return Err(PoolV1PaymentSemanticRegistryErrorV1::NonRowLocalTuple { link });
            }
        }
    }
    Ok(tuple.row)
}

fn endpoint_slots(
    registry: &PoolV1PaymentSemanticRegistryV1,
) -> Result<([u8; 1024], [u8; 1024]), PoolV1PaymentSemanticRegistryErrorV1> {
    let mut producer = [0u8; 1024];
    let mut consumer = [0u8; 1024];
    for link in &registry.links {
        for (tuple, counts) in [
            (link.producer, &mut producer),
            (link.consumer, &mut consumer),
        ] {
            let row = usize::from(tuple_row(tuple, link.id)?);
            if counts[row] >= 2 {
                return Err(PoolV1PaymentSemanticRegistryErrorV1::EndpointCapacity {
                    row: row as u16,
                });
            }
            counts[row] += 1;
        }
    }
    Ok((producer, consumer))
}

fn tuple_value(
    trace: &StateOnlyTraceFoundation,
    tuple: PoolV1PaymentCopyTupleV1,
) -> [M31; POSEIDON2_WIDTH] {
    tuple.limbs.map(|limb| match limb {
        PoolV1PaymentTupleLimbV1::Zero => M31::ZERO,
        PoolV1PaymentTupleLimbV1::Constant(value) => value,
        PoolV1PaymentTupleLimbV1::AffineCell {
            cell,
            scale,
            offset,
        } => trace.c1[usize::from(cell.column)][usize::from(cell.row)]
            .mul(scale)
            .add(offset),
    })
}

pub fn pool_v1_payment_copy_rows_v1(
    registry: &PoolV1PaymentSemanticRegistryV1,
    trace: &StateOnlyTraceFoundation,
    lambda: QM31,
) -> Result<Vec<CopyLogUpRow>, PoolV1PaymentSemanticRegistryErrorV1> {
    let (mut producer_slots, mut consumer_slots) = endpoint_slots(registry)?;
    producer_slots.fill(0);
    consumer_slots.fill(0);
    let empty = CopyLogUpRow {
        producer_values: [QM31::ZERO; 2],
        producer_weights: [M31::ZERO; 2],
        consumer_values: [QM31::ZERO; 2],
        consumer_weights: [M31::ZERO; 2],
    };
    let mut rows = vec![empty; POOL_V1_PAYMENT_TRACE_ROWS];
    for link in &registry.links {
        for (tuple, is_producer) in [(link.producer, true), (link.consumer, false)] {
            let row_index = usize::from(tuple_row(tuple, link.id)?);
            let row = &mut rows[row_index];
            let (values, weights) = if is_producer {
                (&mut row.producer_values, &mut row.producer_weights)
            } else {
                (&mut row.consumer_values, &mut row.consumer_weights)
            };
            let slot = weights
                .iter()
                .position(|weight| *weight == M31::ZERO)
                .ok_or(PoolV1PaymentSemanticRegistryErrorV1::EndpointCapacity {
                    row: row_index as u16,
                })?;
            values[slot] = compress_tagged_tuple(link.tag, &tuple_value(trace, tuple), lambda);
            weights[slot] = M31::ONE;
        }
    }
    Ok(rows)
}

pub fn verify_pool_v1_payment_copy_registry_v1(
    variant: PoolV1PaymentTraceVariantV1,
    trace: &StateOnlyTraceFoundation,
    lambda: QM31,
    chi: QM31,
) -> Result<(), PoolV1PaymentSemanticRegistryErrorV1> {
    let registry = build_pool_v1_payment_semantic_registry_v1(variant)?;
    let rows = pool_v1_payment_copy_rows_v1(&registry, trace, lambda)?;
    let helper = build_copy_logup_helper(&rows, chi)
        .map_err(|_| PoolV1PaymentSemanticRegistryErrorV1::CopyImbalance)?;
    verify_copy_logup_constraints(&rows, &helper, chi)
        .map_err(|_| PoolV1PaymentSemanticRegistryErrorV1::CopyImbalance)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn exact_geometry_and_endpoint_capacity_are_frozen() {
        for variant in [
            PoolV1PaymentTraceVariantV1::PrivateTransfer,
            PoolV1PaymentTraceVariantV1::Withdrawal,
        ] {
            let registry = build_pool_v1_payment_semantic_registry_v1(variant).unwrap();
            assert_eq!(
                registry.links.len(),
                if variant == PoolV1PaymentTraceVariantV1::PrivateTransfer {
                    78
                } else {
                    75
                }
            );
            let (producer, consumer) = endpoint_slots(&registry).unwrap();
            assert!(producer.into_iter().all(|count| count <= 2));
            assert!(consumer.into_iter().all(|count| count <= 2));
        }
        assert_eq!(pool_v1_payment_path_aux_v1(0).unwrap().bit, cell(784, 0));
        assert_eq!(pool_v1_payment_path_aux_v1(19).unwrap().sibling[0].row, 858);
        assert_eq!(pool_v1_payment_value_aux_v1(0).unwrap().bits[20].row, 876);
        assert_eq!(pool_v1_payment_value_aux_v1(2).unwrap().bits[20].row, 872);
        let used = (POOL_V1_PAYMENT_PATH_AUX_BLOCK_START * POOL_V1_PAYMENT_TRACE_BLOCK_ROWS
            ..POOL_V1_PAYMENT_TRACE_ROWS)
            .flat_map(|row| (0..POSEIDON2_WIDTH).map(move |column| (row, column)))
            .filter(|(row, column)| pool_v1_payment_aux_cell_is_used_v1(*row, *column))
            .count();
        assert_eq!(used, 758);
    }
}

//! Allocation-bounded SBF-safe terminal for the native Pool V1 Tag-73
//! payment relations.
//!
//! Runtime evaluation consumes only checked-in copy patterns, endpoints and
//! active-row masks. The allocation-heavy host registry and oracle remain an
//! independent compiler/reference boundary and are not linked on SBF.

use alloc::boxed::Box;

use aspis_core::{
    field::{qm31_pack_base4, qm31_sum_products4, PreparedQm31Multiplier, CM31, M31, QM31},
    state_only_hiding::{state_only_selected_mask_value, STATE_ONLY_HIDING_MASK_ONLY_C1_COLUMNS},
};

use crate::{
    poseidon2::{Digest, DIGEST_ELEMS, POSEIDON2_WIDTH, RATE},
    spend::{DOMAIN_NOTE, DOMAIN_NULLIFIER, DOMAIN_OWNER_KEY},
    state_only_poseidon::{
        evaluate_state_only_poseidon_oracle_projected, StateOnlyPoseidonOpenings,
