#[inline(always)]
fn lift(value: M31) -> QM31 {
    QM31::from_cm31(CM31::from_m31(value))
}

#[inline(always)]
fn selector_mask_sum_16(values: &[QM31; 16], mut mask: u16) -> QM31 {
    let complement = mask.count_ones() > 8;
    if complement {
        mask = !mask;
    }
    let mut sum = if complement { QM31::ONE } else { QM31::ZERO };
    while mask != 0 {
        let index = mask.trailing_zeros() as usize;
        sum = if complement {
            sum.sub(values[index])
        } else {
            sum.add(values[index])
        };
        mask &= mask - 1;
    }
    sum
}

#[derive(Clone, Copy)]
struct Selectors {
    high: [QM31; 64],
    low: [QM31; 16],
    poseidon_block: QM31,
    merkle_block: QM31,
    initial_path_blocks: QM31,
    fixed_zero_blocks: QM31,
    initial_common_blocks: QM31,
    absorption_common_eight_blocks: QM31,
}

impl Selectors {
    fn expand<const N: usize>(coordinates: &[QM31]) -> [QM31; N] {
        let mut weights = [QM31::ZERO; N];
        weights[0] = QM31::ONE;
        let mut len = 1usize;
        for coordinate in coordinates {
            let prepared = PreparedQm31Multiplier::new(*coordinate);
            for index in (0..len).rev() {
                let parent = weights[index];
                let right = prepared.mul(parent);
                weights[2 * index] = parent.sub(right);
                weights[2 * index + 1] = right;
            }
            len *= 2;
        }
        weights
    }

    fn from_high_low(high: [QM31; 64], low: [QM31; 16]) -> Self {
        let sum = |range: core::ops::Range<usize>| {
            high[range].iter().copied().fold(QM31::ZERO, QM31::add)
        };
        let poseidon_block = QM31::ONE.sub(sum(49..64));
        let merkle_block = sum(49..54);
        let initial_path_blocks = sum(4..24);
        let fixed_zero_blocks = sum(32..49);
        let initial_common_blocks = high[0].add(high[1]).add(high[24]).add(high[29]);
        let absorption_common_eight_blocks = high[0]
            .add(high[1])
            .add(high[2])
            .add(sum(4..26))
            .add(high[29])
            .add(high[30]);
        Self {
            high,
            low,
            poseidon_block,
            merkle_block,
            initial_path_blocks,
            fixed_zero_blocks,
            initial_common_blocks,
            absorption_common_eight_blocks,
        }
    }

    fn at_point(point: &[QM31; 10]) -> Self {
        Self::from_high_low(Self::expand(&point[..6]), Self::expand(&point[6..]))
    }

    #[inline(never)]
    fn boxed_at_point(point: &[QM31; 10]) -> Box<Self> {
        Box::new(Self::at_point(point))
    }

    #[inline(always)]
    fn row(&self, row: usize) -> QM31 {
        debug_assert!(row < POOL_V1_PAYMENT_TERMINAL_ROWS);
        self.high[row >> 4].mul(self.low[row & 15])
    }

    fn poseidon(&self) -> StateOnlyPoseidonSelectors {
        StateOnlyPoseidonSelectors {
            block: self.poseidon_block,
            local: self.low,
        }
    }

    fn copy_active(&self, masks: &[u16; 64]) -> QM31 {
        let mut sum = QM31::ZERO;
        let mut block = 0usize;
        while block < 64 {
            let mask = masks[block];
            if mask != 0 {
                sum = sum.add(self.high[block].mul(selector_mask_sum_16(&self.low, mask)));
            }
            block += 1;
        }
        sum
    }
}

