fn pattern_values(
    openings: &[QM31; POSEIDON2_WIDTH],
    lambda: QM31,
    patterns: &[CompiledPoolV1PaymentPattern; COPY_PATTERN_COUNT],
) -> [QM31; COPY_PATTERN_COUNT] {
    let mut powers = [QM31::ZERO; POSEIDON2_WIDTH];
    let mut power = lambda;
    let mut limb = 0usize;
    while limb < POSEIDON2_WIDTH {
        powers[limb] = power;
        power = power.mul(lambda);
        limb += 1;
    }
    let mut result = [QM31::ZERO; COPY_PATTERN_COUNT];
    let mut pattern_index = 0usize;
    while pattern_index < COPY_PATTERN_COUNT {
        let pattern = patterns[pattern_index];
        let mut value = QM31::ZERO;
        limb = 0;
        while limb < POSEIDON2_WIDTH {
            let source = match pattern.kinds[limb] {
                0 => {
                    limb += 1;
                    continue;
                }
                1 => lift(M31(pattern.offsets[limb])),
                2 => openings[usize::from(pattern.columns[limb])]
                    .mul_m31(M31(pattern.scales[limb]))
                    .add(lift(M31(pattern.offsets[limb]))),
                _ => unreachable!("generated Pool V1 tuple kind"),
            };
            value = value.add(powers[limb].mul(source));
            limb += 1;
        }
        result[pattern_index] = value;
        pattern_index += 1;
    }
    result
}

#[derive(Clone, Copy)]
struct CopyRowExtension {
    producer_values: [QM31; 2],
    producer_weights: [QM31; 2],
    consumer_values: [QM31; 2],
    consumer_weights: [QM31; 2],
}

fn copy_residual(row: CopyRowExtension, helper: QM31, chi: QM31) -> QM31 {
    let denominators = [
        chi.sub(row.producer_values[0]),
        chi.sub(row.producer_values[1]),
        chi.sub(row.consumer_values[0]),
        chi.sub(row.consumer_values[1]),
    ];
    let producer_denominator = denominators[0].mul(denominators[1]);
    let consumer_denominator = denominators[2].mul(denominators[3]);
    let producer_numerator = row.producer_weights[0]
        .mul(denominators[1])
        .add(row.producer_weights[1].mul(denominators[0]));
    let consumer_numerator = row.consumer_weights[0]
        .mul(denominators[3])
        .add(row.consumer_weights[1].mul(denominators[2]));
    producer_denominator
        .mul(helper.mul(consumer_denominator).add(consumer_numerator))
        .sub(consumer_denominator.mul(producer_numerator))
}

fn accumulate_copy_endpoint(
    values: &mut [QM31; 2],
    weights: &mut [QM31; 2],
    endpoint: CompiledPoolV1PaymentEndpoint,
    tag: u32,
    patterns: &[QM31; COPY_PATTERN_COUNT],
    selectors: &Selectors,
) {
    let selector = selectors.row(usize::from(endpoint.row));
    let slot = usize::from(endpoint.slot);
    weights[slot] = weights[slot].add(selector);
    let compressed = lift(M31(tag)).add(patterns[usize::from(endpoint.pattern)]);
    values[slot] = values[slot].add(selector.mul(compressed));
}

fn copy_lane_for_registry<const LINK_COUNT: usize>(
    openings: &[QM31; POSEIDON2_WIDTH],
    h1_z: QM31,
    selectors: &Selectors,
    lambda: QM31,
    chi: QM31,
    patterns: &[CompiledPoolV1PaymentPattern; COPY_PATTERN_COUNT],
    links: &[CompiledPoolV1PaymentLink; LINK_COUNT],
    active_row_masks: &[u16; 64],
) -> (QM31, QM31) {
    let patterns = pattern_values(openings, lambda, patterns);
    let mut row = CopyRowExtension {
        producer_values: [QM31::ZERO; 2],
        producer_weights: [QM31::ZERO; 2],
        consumer_values: [QM31::ZERO; 2],
        consumer_weights: [QM31::ZERO; 2],
    };
    let mut link_index = 0usize;
    while link_index < LINK_COUNT {
        let link = links[link_index];
        accumulate_copy_endpoint(
            &mut row.producer_values,
            &mut row.producer_weights,
            link.producer,
            link.tag,
            &patterns,
            selectors,
        );
        accumulate_copy_endpoint(
            &mut row.consumer_values,
            &mut row.consumer_weights,
            link.consumer,
            link.tag,
            &patterns,
            selectors,
        );
        link_index += 1;
    }
    let active = selectors.copy_active(active_row_masks);
    (active.mul(copy_residual(row, h1_z, chi)), active)
}

fn copy_lane(
    openings: &[QM31; POSEIDON2_WIDTH],
    h1_z: QM31,
    selectors: &Selectors,
    lambda: QM31,
    chi: QM31,
    variant: CompiledVariant,
) -> (QM31, QM31) {
    match variant {
        CompiledVariant::PrivateTransfer => copy_lane_for_registry(
            openings,
            h1_z,
            selectors,
            lambda,
            chi,
            &constants::PRIVATE_TRANSFER_COPY_PATTERNS,
            &constants::PRIVATE_TRANSFER_COPY_LINKS,
            &constants::PRIVATE_TRANSFER_ACTIVE_ROW_MASKS,
        ),
        CompiledVariant::Withdrawal => copy_lane_for_registry(
            openings,
            h1_z,
            selectors,
            lambda,
            chi,
            &constants::WITHDRAWAL_COPY_PATTERNS,
            &constants::WITHDRAWAL_COPY_LINKS,
            &constants::WITHDRAWAL_ACTIVE_ROW_MASKS,
        ),
    }
}

/// Source-extraction entry for the Boolean restriction of the compiled Copy
/// lane. `variant` is zero for private transfer and one for withdrawal; all
/// other values and rows outside the 1,024-row terminal are rejected.
///
/// This is deliberately a wrapper around `copy_lane`, not a second evaluator.
/// The one-hot selectors are exactly `Selectors::at_point` at the Boolean
/// terminal point for `selected_row`.
#[doc(hidden)]
pub fn pool_v1_payment_copy_lane_boolean_extraction_v1(
    variant: u8,
    selected_row: u16,
    openings: &[QM31; POSEIDON2_WIDTH],
    h1_z: QM31,
    lambda: QM31,
    chi: QM31,
) -> Option<(QM31, QM31)> {
    if usize::from(selected_row) >= POOL_V1_PAYMENT_TERMINAL_ROWS {
        return None;
    }
    let variant = match variant {
        0 => CompiledVariant::PrivateTransfer,
        1 => CompiledVariant::Withdrawal,
        _ => return None,
    };
    let mut high = [QM31::ZERO; 64];
    let mut low = [QM31::ZERO; 16];
    high[usize::from(selected_row >> 4)] = QM31::ONE;
    low[usize::from(selected_row & 15)] = QM31::ONE;
    let selectors = Selectors::from_high_low(high, low);
    Some(copy_lane(openings, h1_z, &selectors, lambda, chi, variant))
}

#[inline(always)]
fn add_preweighted<const N: usize>(
    packed: &mut [QM31; POOL_V1_PAYMENT_PACKED_SEMANTIC_LANES],
    start: usize,
    values: &[QM31; N],
) {
    let first = start / 4;
    let last = (start + N - 1) / 4;
    for group in first..=last {
        let lanes: [QM31; 4] = core::array::from_fn(|slot| {
            let source = 4 * group + slot;
            if source >= start && source < start + N {
                values[source - start]
            } else {
                QM31::ZERO
            }
        });
        packed[group] = packed[group].add(qm31_pack_base4(&lanes));
    }
}

/// Accumulate four independently selected residual vectors into one packed
/// semantic range. The lazy four-product kernel is byte-for-byte field
/// arithmetic only; it does not change selector or lane order.
#[inline(always)]
fn add_selected4<const N: usize>(
    packed: &mut [QM31; POOL_V1_PAYMENT_PACKED_SEMANTIC_LANES],
    start: usize,
    values: &[[QM31; N]; 4],
    selectors: [QM31; 4],
) {
    let first = start / 4;
    let last = (start + N - 1) / 4;
    for group in first..=last {
        let grouped: [QM31; 4] = core::array::from_fn(|input| {
            let lanes: [QM31; 4] = core::array::from_fn(|slot| {
                let source = 4 * group + slot;
                if source >= start && source < start + N {
                    values[input][source - start]
                } else {
                    QM31::ZERO
                }
            });
            qm31_pack_base4(&lanes)
        });
        packed[group] = packed[group].add(qm31_sum_products4(selectors, grouped));
    }
}

/// Exact little-endian reconstruction of ten extension-field bits.
#[inline(always)]
fn reconstruct_10(view: &[QM31; 16]) -> QM31 {
    view[..9]
        .iter()
        .rev()
        .fold(view[9], |acc, bit| acc.add(acc).add(*bit))
}

#[cfg(test)]
fn first_sponge(block: usize, variant: CompiledVariant) -> Option<(M31, usize)> {
    match block {
        0 => Some((DOMAIN_OWNER_KEY, 8)),
        1 => Some((DOMAIN_NOTE, 18)),
        24 => Some((DOMAIN_NULLIFIER, 16)),
        26 if variant == CompiledVariant::PrivateTransfer => Some((DOMAIN_NOTE, 18)),
        29 => Some((DOMAIN_NOTE, 18)),
        _ => None,
    }
}

#[cfg(test)]
fn fixed_zero_block(block: usize, variant: CompiledVariant) -> bool {
    (32..49).contains(&block)
        || (variant == CompiledVariant::Withdrawal && (26..=28).contains(&block))
}

#[cfg(test)]
fn expected_initial_limb(block: usize, lane: usize, variant: CompiledVariant) -> Option<M31> {
    if let Some((domain, length)) = first_sponge(block, variant) {
        return Some(match lane {
            RATE => domain,
            lane if lane == RATE + 1 => M31(length as u32),
            _ => M31::ZERO,
        });
    }
    if (4..24).contains(&block) {
        return (lane < RATE).then_some(M31::ZERO);
    }
    fixed_zero_block(block, variant).then_some(M31::ZERO)
}

#[cfg(test)]
fn absorption_length(block: usize, variant: CompiledVariant) -> usize {
    match block {
        0 | 1 | 2 | 4..=25 | 26 | 27 | 29 | 30 => {
            if variant == CompiledVariant::Withdrawal && (26..=27).contains(&block) {
                0
            } else {
                8
            }
        }
        3 | 28 | 31 => {
            if variant == CompiledVariant::Withdrawal && block == 28 {
                0
            } else {
                2
            }
        }
        _ => 0,
    }
}

/// Factor the two dense Poseidon-row checks through the six-bit block basis
/// and four-bit local basis. This is the same multilinear polynomial as the
/// literal block/lane scan: it only groups rows which carry the same residual
/// shape before multiplying by the opened column values.
fn semantic_initial_and_absorption_factored(
    public: SemanticPublic,
    openings: &StateOnlyPoseidonOpenings,
    selectors: &Selectors,
) -> ([QM31; 16], [QM31; 16]) {
    let extra_initial_zero = match public.variant {
        CompiledVariant::PrivateTransfer => selectors.high[26],
        CompiledVariant::Withdrawal => selectors.high[26]
            .add(selectors.high[27])
            .add(selectors.high[28]),
    };
    let full_initial_blocks = selectors
        .fixed_zero_blocks
        .add(selectors.initial_common_blocks)
        .add(extra_initial_zero);
    let full_initial_selector = selectors.low[0].mul(full_initial_blocks);
    let rate_initial_selector = selectors.low[0].mul(selectors.initial_path_blocks);
    let full_initial = PreparedQm31Multiplier::new(full_initial_selector);
    let full_and_rate_initial =
        PreparedQm31Multiplier::new(full_initial_selector.add(rate_initial_selector));
    let mut initial: [QM31; 16] = core::array::from_fn(|lane| {
        if lane < RATE {
            full_and_rate_initial.mul(openings.z[lane])
        } else {
            full_initial.mul(openings.z[lane])
        }
    });

    let note_initial_blocks = match public.variant {
        CompiledVariant::PrivateTransfer => selectors.high[1]
            .add(selectors.high[26])
            .add(selectors.high[29]),
        CompiledVariant::Withdrawal => selectors.high[1].add(selectors.high[29]),
    };
    let domain_high = selectors.high[0]
        .mul_m31(DOMAIN_OWNER_KEY)
        .add(note_initial_blocks.mul_m31(DOMAIN_NOTE))
        .add(selectors.high[24].mul_m31(DOMAIN_NULLIFIER));
    let length_high = selectors.high[0]
        .mul_m31(M31(8))
        .add(note_initial_blocks.mul_m31(M31(18)))
        .add(selectors.high[24].mul_m31(M31(16)));
    initial[RATE] = initial[RATE].sub(selectors.low[0].mul(domain_high));
    initial[RATE + 1] = initial[RATE + 1].sub(selectors.low[0].mul(length_high));

    let (length_eight_blocks, length_two_blocks, length_zero_blocks) = match public.variant {
        CompiledVariant::PrivateTransfer => (
            selectors
                .absorption_common_eight_blocks
                .add(selectors.high[26])
                .add(selectors.high[27]),
            selectors.high[3]
                .add(selectors.high[28])
                .add(selectors.high[31]),
            selectors.fixed_zero_blocks,
        ),
        CompiledVariant::Withdrawal => (
            selectors.absorption_common_eight_blocks,
            selectors.high[3].add(selectors.high[31]),
            selectors
                .fixed_zero_blocks
                .add(selectors.high[26])
                .add(selectors.high[27])
                .add(selectors.high[28]),
        ),
    };
    let zero_selector = selectors.low[12].mul(length_zero_blocks);
    let zero_or_two_selector = selectors.low[12].mul(length_zero_blocks.add(length_two_blocks));
    let all_absorption_selector = selectors.low[12].mul(
        length_zero_blocks
            .add(length_two_blocks)
            .add(length_eight_blocks),
    );
    let zero = PreparedQm31Multiplier::new(zero_selector);
    let zero_or_two = PreparedQm31Multiplier::new(zero_or_two_selector);
    let all = PreparedQm31Multiplier::new(all_absorption_selector);
    let absorption_zero = core::array::from_fn(|lane| {
        if lane < 2 {
            zero.mul(openings.z[lane])
        } else if lane < RATE {
            zero_or_two.mul(openings.z[lane])
        } else {
            all.mul(openings.z[lane])
        }
    });
    (initial, absorption_zero)
}

/// Deliberately literal correspondence spelling retained only for focused
/// host tests of the selector factorization above.
#[cfg(test)]
fn semantic_initial_and_absorption_unfactored_reference(
    public: SemanticPublic,
    openings: &StateOnlyPoseidonOpenings,
    selectors: &Selectors,
) -> ([QM31; 16], [QM31; 16]) {
    let mut initial = [QM31::ZERO; 16];
    for block in 0..49 {
        let selector = selectors.row(block * 16);
        for lane in 0..POSEIDON2_WIDTH {
            if let Some(expected) = expected_initial_limb(block, lane, public.variant) {
                initial[lane] =
                    initial[lane].add(selector.mul(openings.z[lane].sub(lift(expected))));
            }
        }
    }
    let mut absorption_zero = [QM31::ZERO; 16];
    for block in 0..49 {
        let selector = selectors.row(block * 16 + 12);
        for lane in absorption_length(block, public.variant)..16 {
            absorption_zero[lane] = absorption_zero[lane].add(selector.mul(openings.z[lane]));
        }
    }
    (initial, absorption_zero)
}

fn semantic_packed(
    public: SemanticPublic,
    openings: &StateOnlyPoseidonOpenings,
    selectors: &Selectors,
) -> [QM31; POOL_V1_PAYMENT_PACKED_SEMANTIC_LANES] {
    let mut packed = [QM31::ZERO; POOL_V1_PAYMENT_PACKED_SEMANTIC_LANES];

    let (initial, absorption_zero) =
        semantic_initial_and_absorption_factored(public, openings, selectors);
    // Undeclared auxiliary cells are the Pool relation-free C1 masks.
    add_preweighted(&mut packed, 0, &initial);

    // Permutation rows 13..15 are outside Poseidon and relation-free.
    add_preweighted(&mut packed, 16, &absorption_zero);

    let path_locals = selectors.low[0]
        .add(selectors.low[2])
        .add(selectors.low[4])
        .add(selectors.low[6]);
    let merkle_selector = selectors.merkle_block.mul(path_locals);
    let bit = openings.z[0];
    let mut merkle = [QM31::ZERO; 17];
    merkle[0] = merkle_selector.mul(bit.mul(bit.sub(QM31::ONE)));
    for lane in 0..DIGEST_ELEMS {
        let current = openings.z[1 + lane];
        let sibling = openings.xor12_z[lane];
        let delta = sibling.sub(current);
        merkle[1 + lane] =
            merkle_selector.mul(openings.succ_z[lane].sub(current.add(bit.mul(delta))));
        merkle[1 + DIGEST_ELEMS + lane] =
            merkle_selector.mul(openings.succ_z[RATE + lane].sub(sibling.sub(bit.mul(delta))));
    }
    add_preweighted(&mut packed, 32, &merkle);

    let value_selectors = [0usize, 2, 4].map(|local| selectors.row(54 * 16 + local));
    let range_selector = value_selectors.iter().copied().fold(QM31::ZERO, QM31::add);
    let views = [&openings.z, &openings.succ_z, &openings.xor12_z];
    let mut direct_range = [QM31::ZERO; 33];
    for (view, values) in views.into_iter().zip(direct_range[..30].chunks_mut(10)) {
        for bit_index in 0..10 {
            values[bit_index] = range_selector.mul(view[bit_index].square().sub(view[bit_index]));
        }
    }
    let reconstructed_value = reconstruct_10(&openings.z)
        .add(reconstruct_10(&openings.succ_z).mul_m31(M31(1 << 10)))
        .add(reconstruct_10(&openings.xor12_z).mul_m31(M31(1 << 20)));
    direct_range[30] = range_selector.mul(openings.z[10].sub(reconstructed_value));
    direct_range[31] = range_selector.mul(openings.succ_z[10]);
    direct_range[32] = range_selector.mul(openings.xor12_z[10]);
    add_preweighted(&mut packed, 49, &direct_range);

    let conservation_selector = selectors.row(VALUE_AUXILIARY_BLOCK * 16 + 6);
    let value = [
        conservation_selector.mul(openings.z[0].sub(openings.z[1]).sub(openings.z[2])),
        conservation_selector.mul(openings.succ_z[0].sub(openings.succ_z[1])),
    ];
    add_preweighted(&mut packed, 82, &value);

    let public_digests = [
        public.anchor,
        public.nullifier,
        public.recipient.unwrap_or([M31::ZERO; DIGEST_ELEMS]),
        public.change,
    ];
    let public_residuals: [[QM31; DIGEST_ELEMS]; 4] = core::array::from_fn(|input| {
        core::array::from_fn(|lane| openings.z[lane].sub(lift(public_digests[input][lane])))
    });
    let public_selectors = [
        selectors.row(23 * 16 + 11),
        selectors.row(25 * 16 + 11),
        if public.recipient.is_some() {
            selectors.row(28 * 16 + 11)
        } else {
            QM31::ZERO
        },
        selectors.row(31 * 16 + 11),
    ];
    add_selected4(&mut packed, 84, &public_residuals, public_selectors);

    let input_asset_selector = selectors.row(2 * 16 + 12);
    let mut output_scalar = selectors
        .row(30 * 16 + 12)
        .mul(openings.z[1].sub(lift(public.asset_id)));
    if public.variant == CompiledVariant::PrivateTransfer {
        output_scalar = output_scalar.add(
            selectors
                .row(27 * 16 + 12)
                .mul(openings.z[1].sub(lift(public.asset_id))),
        );
    } else if let Some(amount) = public.withdrawal_amount {
        output_scalar =
            output_scalar.add(value_selectors[1].mul(openings.z[10].sub(lift(M31(amount)))));
    }
    let public_scalar = [
        input_asset_selector.mul(openings.z[1].sub(lift(public.asset_id))),
        output_scalar,
    ];
    add_preweighted(&mut packed, 92, &public_scalar);

    packed
}

fn selected_claim(
    claims: &[QM31; POOL_V1_PAYMENT_SELECTED_TERMINAL_CLAIMS],
    point: usize,
    column: usize,
) -> QM31 {
    claims[point * POOL_V1_PAYMENT_SELECTED_TERMINAL_COLUMNS + column]
}

fn equality_value(left: &[QM31; 10], right: &[QM31; 10]) -> QM31 {
    let factor = |a: QM31, b: QM31| {
        let ab = a.mul(b);
        QM31::ONE.sub(a).sub(b).add(ab).add(ab)
    };
    left[1..]
        .iter()
        .zip(&right[1..])
        .fold(factor(left[0], right[0]), |product, (&a, &b)| {
            product.mul(factor(a, b))
        })
}

#[allow(clippy::type_complexity)]
fn composition_parts(
    public: SemanticPublic,
    claims: &[QM31; POOL_V1_PAYMENT_SELECTED_TERMINAL_CLAIMS],
    point: &[QM31; 10],
    lambda: QM31,
    chi: QM31,
    theta: QM31,
) -> Result<
    (
        QM31,
        [QM31; 16],
        [QM31; STATE_ONLY_HIDING_MASK_ONLY_C1_COLUMNS],
        QM31,
        QM31,
        QM31,
    ),
    PoolV1PaymentSemanticTerminalErrorV1,
> {
    if public
        .withdrawal_amount
        .is_some_and(|amount| amount == 0 || amount >= (1 << 30))
    {
        return Err(PoolV1PaymentSemanticTerminalErrorV1::InvalidPublicAmount);
    }
    let openings = StateOnlyPoseidonOpenings {
        z: core::array::from_fn(|column| selected_claim(claims, 0, column)),
        succ_z: core::array::from_fn(|column| selected_claim(claims, 1, column)),
        xor12_z: core::array::from_fn(|column| selected_claim(claims, 2, column)),
    };
    let mask_only = core::array::from_fn(|column| {
        selected_claim(claims, 0, POOL_V1_PAYMENT_TERMINAL_C1_COLUMNS + column)
    });
    let selectors = Selectors::boxed_at_point(point);
    let poseidon = evaluate_state_only_poseidon_oracle_projected(&openings, &selectors.poseidon());
    let semantic = semantic_packed(public, &openings, selectors.as_ref());
    let h1_z = selected_claim(claims, 0, SELECTED_H1_COLUMN);
    let (copy, copy_active) = copy_lane(
        &openings.z,
        h1_z,
        selectors.as_ref(),
        lambda,
        chi,
        public.variant,
    );
    let prepared_theta = PreparedQm31Multiplier::new(theta);
    let mut composition = copy;
    for lane in semantic.into_iter().rev() {
        composition = prepared_theta.mul(composition).add(lane);
    }
    for lane in poseidon.into_iter().rev() {
        composition = prepared_theta.mul(composition).add(lane);
    }
    Ok((
        composition,
        openings.z,
        mask_only,
        selected_claim(claims, 0, SELECTED_G_COLUMN),
        h1_z,
        copy_active,
    ))
}

fn terminal_parts(
    public: SemanticPublic,
    claims: &[QM31; POOL_V1_PAYMENT_SELECTED_TERMINAL_CLAIMS],
    point: &[QM31; 10],
    lambda: QM31,
    chi: QM31,
    theta: QM31,
    zerocheck_point: &[QM31; 10],
    mu: QM31,
) -> Result<
    (
        QM31,
        [QM31; 16],
        [QM31; STATE_ONLY_HIDING_MASK_ONLY_C1_COLUMNS],
        QM31,
    ),
    PoolV1PaymentSemanticTerminalErrorV1,
> {
    let (composition, c1, mask_only, g, h1_z, copy_active) =
        composition_parts(public, claims, point, lambda, chi, theta)?;
    let original = equality_value(zerocheck_point, point)
        .mul(composition)
        .add(mu.mul(h1_z))
        .add(mu.mul(mu).mul(QM31::ONE.sub(copy_active).mul(h1_z)));
    Ok((original, c1, mask_only, g))
}

