#[cfg(test)]
mod tests {
    use super::*;

    fn registry() -> VerifierRegistryV1 {
        VerifierRegistryV1 {
            flags: 0,
            bump: 253,
            pool: [1u8; 32],
            authority: [2u8; 32],
            policy_binding: [3u8; 32],
            generation: 4,
            minimum_activation_delay_slots: 5,
        }
    }

    fn entry() -> VerifierRegistryEntryV1 {
        VerifierRegistryEntryV1 {
            status: VerifierEntryStatusV1::Active,
            statement_version: 1,
            bump: 252,
            pool: [1u8; 32],
            verifier_program: [2u8; 32],
            profile_binding: [3u8; 32],
            release_binding: [4u8; 32],
            activation_slot: 10,
            retirement_slot: POOL_V1_VERIFIER_ENTRY_NO_RETIREMENT_SLOT,
            policy_binding: [5u8; 32],
        }
    }

    #[test]
    fn registry_image_roundtrips_and_rejects_unknown_flags_and_reserved_bytes() {
        let original = registry();
        let encoded = encode_verifier_registry_v1(&original).unwrap();
        assert_eq!(encoded.len(), POOL_V1_VERIFIER_REGISTRY_BYTES);
        assert_eq!(decode_verifier_registry_v1(&encoded), Ok(original));

        let mut unknown_flags = encoded;
        unknown_flags[5] = 0x80;
        assert_eq!(
            decode_verifier_registry_v1(&unknown_flags),
            Err(PoolV1VerifierRegistryFormatError::UnsupportedFlags)
        );
        let mut reserved = encoded;
        reserved[127] = 1;
        assert_eq!(
            decode_verifier_registry_v1(&reserved),
            Err(PoolV1VerifierRegistryFormatError::NonZeroReserved)
        );
        assert_eq!(
            encode_verifier_registry_v1(&VerifierRegistryV1 {
                minimum_activation_delay_slots: 0,
                ..original
            }),
            Err(PoolV1VerifierRegistryFormatError::InvalidActivationDelay)
        );
    }

    #[test]
    fn entry_image_roundtrips_and_rejects_status_retirement_and_reserved_bytes() {
        let original = entry();
        let encoded = encode_verifier_registry_entry_v1(&original).unwrap();
        assert_eq!(encoded.len(), POOL_V1_VERIFIER_ENTRY_BYTES);
        assert_eq!(decode_verifier_registry_entry_v1(&encoded), Ok(original));

        let mut invalid_status = encoded;
        invalid_status[5] = 4;
        assert_eq!(
            decode_verifier_registry_entry_v1(&invalid_status),
            Err(PoolV1VerifierRegistryFormatError::InvalidStatus)
        );
        let mut reserved = encoded;
        reserved[191] = 1;
        assert_eq!(
            decode_verifier_registry_entry_v1(&reserved),
            Err(PoolV1VerifierRegistryFormatError::NonZeroReserved)
        );
        assert_eq!(
            encode_verifier_registry_entry_v1(&VerifierRegistryEntryV1 {
                retirement_slot: original.activation_slot,
                ..original
            }),
            Err(PoolV1VerifierRegistryFormatError::InvalidRetirementSlot)
        );
    }

    #[test]
    fn active_interval_and_exact_replacement_are_fail_closed() {
        let retiring = entry();
        let replacement = VerifierRegistryEntryV1 {
            verifier_program: [9u8; 32],
            release_binding: [6u8; 32],
            activation_slot: 9,
            ..retiring
        };

        assert!(replacement.is_active_at(10));
        assert!(replacement.is_exact_compatible_replacement_for(&retiring, 10));
        assert!(!VerifierRegistryEntryV1 {
            profile_binding: [7u8; 32],
            ..replacement
        }
        .is_exact_compatible_replacement_for(&retiring, 10));
        assert!(!VerifierRegistryEntryV1 {
            release_binding: retiring.release_binding,
            ..replacement
        }
        .is_exact_compatible_replacement_for(&retiring, 10));
        assert!(!VerifierRegistryEntryV1 {
            status: VerifierEntryStatusV1::Paused,
            ..replacement
        }
        .is_exact_compatible_replacement_for(&retiring, 10));
    }

    fn registry_v2() -> VerifierRegistryV2 {
        VerifierRegistryV2 {
            flags: 0,
            bump: 253,
            pool: [1u8; 32],
            authority: [2u8; 32],
            policy_binding: [3u8; 32],
            generation: 4,
            minimum_activation_delay_slots: 5,
            registry_program: [6u8; 32],
            loader_program: [7u8; 32],
            programdata_address: [8u8; 32],
            programdata_bump: 251,
            executable_hash: [9u8; 32],
        }
    }

    fn entry_v2() -> VerifierRegistryEntryV2 {
        VerifierRegistryEntryV2 {
            status: VerifierEntryStatusV1::Active,
            statement_version: 1,
            bump: 252,
            pool: [1u8; 32],
            verifier_program: [2u8; 32],
            profile_binding: [3u8; 32],
            release_binding: [4u8; 32],
            loader_program: [5u8; 32],
            programdata_address: [6u8; 32],
            programdata_bump: 250,
            executable_hash: [7u8; 32],
            expected_upgrade_authority: [0u8; 32],
            activation_slot: 10,
            retirement_slot: POOL_V1_VERIFIER_ENTRY_NO_RETIREMENT_SLOT,
            policy_binding: [8u8; 32],
        }
    }

    #[test]
    fn v2_registry_and_entry_roundtrip_without_reinterpreting_v1() {
        let registry = registry_v2();
        let encoded_registry = encode_verifier_registry_v2(&registry).unwrap();
        assert_eq!(encoded_registry.len(), POOL_V1_VERIFIER_REGISTRY_V2_BYTES);
        assert_eq!(decode_verifier_registry_v2(&encoded_registry), Ok(registry));
        assert!(decode_verifier_registry_v1(&encoded_registry).is_err());

        let entry = entry_v2();
        let encoded_entry = encode_verifier_registry_entry_v2(&entry).unwrap();
        assert_eq!(encoded_entry.len(), POOL_V1_VERIFIER_ENTRY_V2_BYTES);
        assert_eq!(decode_verifier_registry_entry_v2(&encoded_entry), Ok(entry));
        assert!(decode_verifier_registry_entry_v1(&encoded_entry).is_err());

        let mut bad_mode = encoded_entry;
        bad_mode[7] = 2;
        assert_eq!(
            decode_verifier_registry_entry_v2(&bad_mode),
            Err(PoolV1VerifierRegistryFormatError::InvalidDeploymentMode)
        );
        assert_eq!(
            encode_verifier_registry_entry_v2(&VerifierRegistryEntryV2 {
                expected_upgrade_authority: [1u8; 32],
                ..entry
            }),
            Err(PoolV1VerifierRegistryFormatError::InvalidAuthorityMode)
        );
    }

    #[test]
    fn bump_fields_have_exact_offsets_and_remaining_reserved_bytes_stay_zero() {
        let registry = encode_verifier_registry_v1(&registry()).unwrap();
        let entry = encode_verifier_registry_entry_v1(&entry()).unwrap();
        let registry_v2 = encode_verifier_registry_v2(&registry_v2()).unwrap();
        let entry_v2 = encode_verifier_registry_entry_v2(&entry_v2()).unwrap();
        assert_eq!((registry[4], registry[6]), (2, 253));
        assert_eq!((entry[4], entry[7]), (2, 252));
        assert_eq!(
            (registry_v2[4], registry_v2[7], registry_v2[248]),
            (3, 253, 251)
        );
        assert_eq!((entry_v2[4], entry_v2[312], entry_v2[313]), (3, 252, 250));

        for index in core::iter::once(7).chain(120..128) {
            assert_eq!(registry[index], 0);
            let mut malformed = registry;
            malformed[index] = 1;
            assert_eq!(
                decode_verifier_registry_v1(&malformed),
                Err(PoolV1VerifierRegistryFormatError::NonZeroReserved)
            );
        }
        for index in 184..192 {
            assert_eq!(entry[index], 0);
            let mut malformed = entry;
            malformed[index] = 1;
            assert_eq!(
                decode_verifier_registry_entry_v1(&malformed),
                Err(PoolV1VerifierRegistryFormatError::NonZeroReserved)
            );
        }
        for index in 249..256 {
            assert_eq!(registry_v2[index], 0);
            let mut malformed = registry_v2;
            malformed[index] = 1;
            assert_eq!(
                decode_verifier_registry_v2(&malformed),
                Err(PoolV1VerifierRegistryFormatError::NonZeroReserved)
            );
        }
        for index in 314..320 {
            assert_eq!(entry_v2[index], 0);
            let mut malformed = entry_v2;
            malformed[index] = 1;
            assert_eq!(
                decode_verifier_registry_entry_v2(&malformed),
                Err(PoolV1VerifierRegistryFormatError::NonZeroReserved)
            );
        }
    }

    #[test]
    fn old_zero_reserved_images_are_never_reinterpreted_as_attested_bumps() {
        let mut registry = encode_verifier_registry_v1(&registry()).unwrap();
        registry[4] = 1;
        registry[6] = 0;
        assert_eq!(
            decode_verifier_registry_v1(&registry),
            Err(PoolV1VerifierRegistryFormatError::WrongVersion)
        );
        let mut entry = encode_verifier_registry_entry_v1(&entry()).unwrap();
        entry[4] = 1;
        entry[7] = 0;
        assert_eq!(
            decode_verifier_registry_entry_v1(&entry),
            Err(PoolV1VerifierRegistryFormatError::WrongVersion)
        );
        let mut registry_v2 = encode_verifier_registry_v2(&registry_v2()).unwrap();
        registry_v2[4] = 2;
        registry_v2[7] = 0;
        registry_v2[248] = 0;
        assert_eq!(
            decode_verifier_registry_v2(&registry_v2),
            Err(PoolV1VerifierRegistryFormatError::WrongVersion)
        );
        let mut entry_v2 = encode_verifier_registry_entry_v2(&entry_v2()).unwrap();
        entry_v2[4] = 2;
        entry_v2[312] = 0;
        entry_v2[313] = 0;
        assert_eq!(
            decode_verifier_registry_entry_v2(&entry_v2),
            Err(PoolV1VerifierRegistryFormatError::WrongVersion)
        );
    }
}

crates/aspis-statement/src/poseidon2.rs:
//! Pinned Plonky3 Poseidon2-M31 width-16 permutation.
//!
//! Parameters and constants are copied from `p3-mersenne-31 = 0.6.1`:
//! width 16, alpha 5, 8 full rounds (4+4), 14 partial rounds. The constants
//! were generated by Plonky3's Grain-LFSR script with
//! `(field_type=1, n=31, t=16, R_F=8, R_P=14)`. Unit tests include the
//! upstream KAT and differential checks against the pinned crate.
//!
//! # Domain separation
//!
//! Every semantic hash is separated by a distinct domain constant that is
//! injected into the sponge capacity (or, for the fixed-arity node
//! compression, added into the last state limb). Separation is therefore a
//! property of the injected bytes, not of caller convention. The generic
//! sponge entry ([`hash_fields`]) is `pub(crate)`; external callers reach the
//! primitive only through the typed wrappers below, each of which pins one
//! domain. The cross-domain non-equality and per-wrapper regression KATs in
//! this module's test module lock these constants against accidental drift.
//!
//! | Semantic domain            | Constant       | Entry point                                    | Framing                          |
//! |----------------------------|----------------|------------------------------------------------|----------------------------------|
//! | Owner-key derivation       | `0x4153_0001`  | [`hash_owner_key`] (`DOMAIN_OWNER_KEY`)        | length-committing rate-8 sponge  |
//! | Nullifier derivation       | `0x4153_0002`  | [`hash_nullifier`] (`DOMAIN_NULLIFIER`)        | length-committing rate-8 sponge  |
//! | Note / leaf / output commit | `0x4153_0003` | [`hash_note_commitment`] (`DOMAIN_NOTE`)       | length-committing rate-8 sponge  |
//! | Retired output (unspendable) | `0x4153_0004` | test-only reference (`DOMAIN_OUTPUT_LEGACY`)  | length-committing rate-8 sponge  |
//! | Merkle node (v2 sponge)    | `0x4153_0005`  | [`merkle_node_sponge_v2`] (`MERKLE_NODE_DOMAIN_V2` = `DOMAIN_MERKLE_NODE`) | length-committing rate-8 sponge, two permutations |
//! | Merkle node (v3 compress)  | `0x4153_1005`  | [`merkle_node_compress_v3`] (`MERKLE_NODE_COMPRESSION_V3_TWEAK`) | fixed-arity width-16 compression, one permutation |
//!
//! The owner-key, nullifier, note and v2-node domains share the
//! variable-length rate-8 sponge in [`hash_fields`]: the domain tag sits in
//! capacity limb `RATE`, the exact input length in capacity limb `RATE + 1`,
//! so chunk boundaries and trailing zeros are unambiguous and inputs of
//! different arity never collide.
//!
//! ## Leaf versus node
//!
//! Leaves (note commitments, and spendable outputs, which reuse the leaf
//! domain) are produced by the length-committing sponge under `DOMAIN_NOTE`.
//! Internal Merkle nodes are produced by the fixed-arity 16-limb compression
//! [`merkle_node_compress_v3`], whose node tag is added into the final state
//! limb before a single permutation. A node therefore never shares a
//! construction with a leaf: the leaf is a variable-length sponge digest, the
//! node is a fixed two-digest compression, and the two carry different
//! injected tags. This is what prevents a second-preimage that reinterprets a
//! node digest as a leaf, or vice versa. The pre-v2 rate-8 node sponge
//! ([`merkle_node_sponge_v2`], tag `0x4153_0005`) is retained only as a
//! migration reference and is separated from the v3 root by the
//! statement/tree version.
//!
//! The domain constants themselves are defined in [`crate::spend`]; the typed
//! wrappers below re-use those exact values so the wrapper output is
//! byte-identical to the generic call it replaces.

use aspis_core::field::M31;

pub const POSEIDON2_WIDTH: usize = 16;
pub const RATE: usize = 8;
pub const DIGEST_ELEMS: usize = 8;
pub const POSEIDON2_ROUNDS: usize = 22;
pub type Digest = [M31; DIGEST_ELEMS];

/// Round class and index inside the pinned 4 + 14 + 4 schedule.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Poseidon2RoundKind {
    ExternalInitial(u8),
    Internal(u8),
    ExternalFinal(u8),
}

/// One input/output transition of the optimized permutation.
///
/// The first transition includes the permutation's leading external linear
/// layer; its `input` is therefore the raw sponge state supplied to
/// [`permute_optimized`]. Every later input equals the previous output.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Poseidon2RoundTransition {
    pub round: u8,
    pub kind: Poseidon2RoundKind,
    pub input: [M31; POSEIDON2_WIDTH],
    pub output: [M31; POSEIDON2_WIDTH],
}

