            z: core::array::from_fn(|lane| lift(atomic.trace.c1[lane][row])),
            succ_z: core::array::from_fn(|lane| {
                lift(atomic.trace.c1[lane][(row + 1) & (STATE_ONLY_POSEIDON_TRACE_ROWS - 1)])
