fn every_level_one_path_sibling_and_direction_mutation_rejects() {
    let (statement, witness) = fixture();
    let honest = build_atomic_state_only_trace_v3(&statement, &witness).unwrap();
    for level in 0..20 {
        for output_path in [false, true] {
