                ATOMIC_STATE_ONLY_INPUT_PATH_BLOCK_START + level
            } else {
                ATOMIC_STATE_ONLY_OUTPUT_PATH_BLOCK_START + level
            };
            let untouched = block_image(&honest, untouched_block);

