//! Native differential gate of the writer migration (LOG D68.2).
//!
//! The shipped forest compiler (`compile_pool_v1_pair_forest_*_merged_c1_v1`,
//! every C1 cell written by the extracted copies) is compared with the retained
//! pre-migration compiler (`pair_forest_trace::reference`, the legacy writers
//! plus relocation) on the whole `Result`: on success every field of the
//! compilation (both banks, the merged semantic C1, directions, value bits,
//! public outputs, afterstate, public statement); on failure the exact error.
//! Witnesses: the two saved fixtures, the 512 randomized honest witnesses of
//! refine/diffharness/tests/glue.rs (same generator and seed), and 31 witness,
//! public, context and snapshot mutations of the fixtures and of the first 64
//! randomized witnesses, which exercise the error paths in order.
use std::collections::BTreeMap;

use aspis_core::field::{M31, P};
use aspis_statement::{
    derive_owner_key,
    poseidon2::Digest,
    pool_v1::{
        pair_forest_trace::{
            compile_pool_v1_pair_forest_private_transfer_merged_c1_v1,
            compile_pool_v1_pair_forest_withdrawal_merged_c1_v1, reference,
            PoolV1PairForestInputNoteWitnessV1, PoolV1PairForestMergedC1CompilationV1,
            PoolV1PairForestPrivateTransferWitnessV1, PoolV1PairForestWithdrawalWitnessV1,
        },
        pair_trace::{PoolV1PairInputNoteWitnessV1, PoolV1PairTraceErrorV1},
        pool_v1_note_commitment, pool_v1_nullifier, pool_v1_tree_parent, IncrementalMerkleTreeV1,
        PoolV1MembershipWitnessV1, PoolV1OutputNoteWitnessV1, PoolV1PairLeafWitnessV1,
        PoolV1PairLiveSnapshotV1, PoolV1PaymentRelationContextV1, PoolV1PaymentRuntimeBindingV1,
        PoolV1PrivateTransferPublicV1, PoolV1WithdrawalPublicV1, POOL_V1_PAIR_TREE_DEPTH,
    },
};

struct Rng(u64);
impl Rng {
    fn next(&mut self) -> u64 {
        let mut x = self.0;
        x ^= x << 13;
        x ^= x >> 7;
        x ^= x << 17;
        self.0 = x;
        x
    }
    fn below(&mut self, n: u64) -> u64 {
        self.next() % n
    }
    fn m31(&mut self) -> u32 {
        self.below(P as u64) as u32
    }
    fn digest(&mut self) -> Digest {
        core::array::from_fn(|_| M31(self.m31()))
    }
}

fn digest_seed(seed: u32) -> Digest {
    core::array::from_fn(|lane| M31(seed + 17 * lane as u32 + 1))
}

fn pair_empty_roots() -> [Digest; POOL_V1_PAIR_TREE_DEPTH + 1] {
    let zero = [M31(0); 8];
    let mut roots = [zero; POOL_V1_PAIR_TREE_DEPTH + 1];
    roots[0] = pool_v1_tree_parent(&zero, &zero);
    for level in 0..POOL_V1_PAIR_TREE_DEPTH {
        roots[level + 1] = pool_v1_tree_parent(&roots[level], &roots[level]);
    }
    roots
}

fn snapshot_at(pool: [u8; 32], dom: [u8; 32], index: u64) -> PoolV1PairLiveSnapshotV1 {
    let empty = pair_empty_roots();
    let mut tree = IncrementalMerkleTreeV1::from_parts_with_empty_roots(
        0, empty[POOL_V1_PAIR_TREE_DEPTH], core::array::from_fn(|level| empty[level]), &empty).unwrap();
    for leaf in 0..index {
        tree = tree.append_one_with_empty_roots(digest_seed(20_000 + 32 * leaf as u32), &empty).unwrap().0;
    }
    PoolV1PairLiveSnapshotV1 {
        pool,
        deployment_domain: dom,
        sequence: index,
        next_pair_index: index,
        current_root: tree.root,
        frontier: tree.frontier,
    }
}

/// glue.rs `input_witness`: the saved fixture when `rng` is None.
fn input_witness(value: u32, rng: Option<&mut Rng>) -> PoolV1PairForestInputNoteWitnessV1 {
    let asset = M31(77);
    match rng {
        None => {
            let nullifier_key = digest_seed(10);
            let salt = digest_seed(100);
            let owner = derive_owner_key(&nullifier_key);
            let c = pool_v1_note_commitment(&owner, value, asset, &salt);
            PoolV1PairForestInputNoteWitnessV1 {
                pair: PoolV1PairInputNoteWitnessV1 {
                    nullifier_key,
                    salt,
                    value,
                    pair_leaf: PoolV1PairLeafWitnessV1::two_outputs(c, digest_seed(900)).unwrap(),
                    selected_second: false,
                    membership: PoolV1MembershipWitnessV1 {
                        siblings: core::array::from_fn(|level| digest_seed(2_000 + 20 * level as u32)),
                        index: 0x5_4321,
                    },
                },
                super_root_siblings: [digest_seed(3_000), digest_seed(3_100), digest_seed(3_200)],
                super_root_directions: [true, false, true],
            }
        }
        Some(rng) => {
            let nullifier_key = rng.digest();
            let salt = rng.digest();
            let owner = derive_owner_key(&nullifier_key);
            let c = pool_v1_note_commitment(&owner, value, asset, &salt);
            let mut other = rng.digest();
            if other[7].0 == 0 {
                other[7] = M31(1);
            }
            let selected_second = rng.below(2) == 1;
            let pair_leaf = if selected_second {
                PoolV1PairLeafWitnessV1::two_outputs(other, c).unwrap()
            } else if rng.below(2) == 1 {
                PoolV1PairLeafWitnessV1::two_outputs(c, other).unwrap()
            } else {
                PoolV1PairLeafWitnessV1::single_output(c).unwrap()
            };
            PoolV1PairForestInputNoteWitnessV1 {
                pair: PoolV1PairInputNoteWitnessV1 {
                    nullifier_key,
                    salt,
                    value,
                    pair_leaf,
                    selected_second,
                    membership: PoolV1MembershipWitnessV1 {
                        siblings: core::array::from_fn(|_| rng.digest()),
                        index: rng.below(1 << 20) as u32,
                    },
                },
                super_root_siblings: [rng.digest(), rng.digest(), rng.digest()],
                super_root_directions: core::array::from_fn(|_| rng.below(2) == 1),
            }
        }
    }
}

fn global_anchor(input: &PoolV1PairForestInputNoteWitnessV1) -> Digest {
    let mut current = input.pair.pair_leaf.leaf_digest().unwrap();
    for level in 0..POOL_V1_PAIR_TREE_DEPTH {
        let s = input.pair.membership.siblings[level];
        current = if ((input.pair.membership.index >> level) & 1) == 0 {
            pool_v1_tree_parent(&current, &s)
        } else {
            pool_v1_tree_parent(&s, &current)
        };
    }
    for level in 0..3 {
        let s = input.super_root_siblings[level];
        current = if input.super_root_directions[level] {
            pool_v1_tree_parent(&s, &current)
        } else {
            pool_v1_tree_parent(&current, &s)
        };
    }
    current
}

#[derive(Clone)]
enum Stmt {
    Transfer(PoolV1PrivateTransferPublicV1, PoolV1PairForestPrivateTransferWitnessV1),
    Withdrawal(PoolV1WithdrawalPublicV1, PoolV1PairForestWithdrawalWitnessV1),
}

#[derive(Clone)]
struct Case {
    stmt: Stmt,
    binding: PoolV1PaymentRuntimeBindingV1,
    spent: Vec<Digest>,
    snapshot: PoolV1PairLiveSnapshotV1,
}

type Out = Result<PoolV1PairForestMergedC1CompilationV1, PoolV1PairTraceErrorV1>;

impl Case {
    fn run(&self) -> (Out, Out) {
        let context = PoolV1PaymentRelationContextV1 { runtime_binding: self.binding, spent_nullifiers: &self.spent };
        match &self.stmt {
            Stmt::Transfer(public, witness) => (
                compile_pool_v1_pair_forest_private_transfer_merged_c1_v1(public, witness, context, self.snapshot),
                reference::compile_pool_v1_pair_forest_private_transfer_merged_c1_v1(public, witness, context, self.snapshot),
            ),
            Stmt::Withdrawal(public, witness) => (
                compile_pool_v1_pair_forest_withdrawal_merged_c1_v1(public, witness, context, self.snapshot),
                reference::compile_pool_v1_pair_forest_withdrawal_merged_c1_v1(public, witness, context, self.snapshot),
            ),
        }
    }
    fn input(&mut self) -> &mut PoolV1PairForestInputNoteWitnessV1 {
        match &mut self.stmt {
            Stmt::Transfer(_, w) => &mut w.input,
            Stmt::Withdrawal(_, w) => &mut w.input,
        }
    }
    fn change(&mut self) -> &mut PoolV1OutputNoteWitnessV1 {
        match &mut self.stmt {
            Stmt::Transfer(_, w) => &mut w.change,
            Stmt::Withdrawal(_, w) => &mut w.change,
        }
    }
    fn anchor(&mut self) -> &mut Digest {
        match &mut self.stmt {
            Stmt::Transfer(p, _) => &mut p.anchor_root,
            Stmt::Withdrawal(p, _) => &mut p.anchor_root,
        }
    }
    fn nullifier(&mut self) -> &mut Digest {
        match &mut self.stmt {
            Stmt::Transfer(p, _) => &mut p.nullifier,
            Stmt::Withdrawal(p, _) => &mut p.nullifier,
        }
    }
    fn change_commitment(&mut self) -> &mut Digest {
        match &mut self.stmt {
            Stmt::Transfer(p, _) => &mut p.change_commitment,
            Stmt::Withdrawal(p, _) => &mut p.change_commitment,
        }
    }
    fn asset(&mut self) -> &mut M31 {
        match &mut self.stmt {
            Stmt::Transfer(p, _) => &mut p.asset_id,
            Stmt::Withdrawal(p, _) => &mut p.asset_id,
        }
    }
}

/// glue.rs `build`, keeping the case even when production rejects it.
fn honest(mut rng: Option<&mut Rng>, transfer: bool) -> Case {
    let randomized = rng.is_some();
    let (input_value, part, index) = match rng.as_deref_mut() {
        Some(r) => {
            let v = 2 + r.below((1 << 30) - 2) as u32;
            (v, 1 + r.below(v as u64 - 1) as u32, r.below(64))
        }
        None => (1_000, if transfer { 600 } else { 250 }, 13),
    };
    let input = match rng.as_deref_mut() { Some(r) => input_witness(input_value, Some(r)), None => input_witness(input_value, None) };
    let asset = M31(77);
    let anchor = global_anchor(&input);
    let snapshot = snapshot_at([1; 32], [2; 32], index);
    let nullifier = pool_v1_nullifier(&input.pair.nullifier_key, &input.pair.salt);
    let mut fresh = || -> Digest { match rng.as_deref_mut() { Some(r) => r.digest(), None => unreachable!() } };
    let binding = PoolV1PaymentRuntimeBindingV1 { pool: [1; 32], deployment_domain: [2; 32], anchor_sequence: 42, anchor_root: anchor, asset_id: asset };
    let stmt = if transfer {
        let (rec, chg) = if randomized {
            (PoolV1OutputNoteWitnessV1 { owner_key: fresh(), salt: fresh(), value: part },
             PoolV1OutputNoteWitnessV1 { owner_key: fresh(), salt: fresh(), value: input_value - part })
        } else {
            (PoolV1OutputNoteWitnessV1 { owner_key: digest_seed(300), salt: digest_seed(400), value: 600 },
             PoolV1OutputNoteWitnessV1 { owner_key: digest_seed(500), salt: digest_seed(600), value: 400 })
        };
        let rc = pool_v1_note_commitment(&rec.owner_key, rec.value, asset, &rec.salt);
        let cc = pool_v1_note_commitment(&chg.owner_key, chg.value, asset, &chg.salt);
        let public = PoolV1PrivateTransferPublicV1 {
            pool: [1; 32], deployment_domain: [2; 32], anchor_sequence: 42, anchor_root: anchor,
            nullifier, asset_id: asset, recipient_commitment: rc, change_commitment: cc,
        };
        Stmt::Transfer(public, PoolV1PairForestPrivateTransferWitnessV1 { input, recipient: rec, change: chg })
    } else {
        let chg = if randomized {
            PoolV1OutputNoteWitnessV1 { owner_key: fresh(), salt: fresh(), value: input_value - part }
        } else {
            PoolV1OutputNoteWitnessV1 { owner_key: digest_seed(700), salt: digest_seed(800), value: 750 }
        };
        let cc = pool_v1_note_commitment(&chg.owner_key, chg.value, asset, &chg.salt);
        let public = PoolV1WithdrawalPublicV1 {
            pool: [1; 32], deployment_domain: [2; 32], anchor_sequence: 42, anchor_root: anchor,
            nullifier, asset_id: asset, amount: part, destination_token_account: [9; 32], change_commitment: cc,
        };
        Stmt::Withdrawal(public, PoolV1PairForestWithdrawalWitnessV1 { input, change: chg })
    };
    Case { stmt, binding, spent: Vec::new(), snapshot }
}

fn label(out: &Out) -> String {
    match out {
        Ok(_) => "Ok".into(),
        Err(e) => {
            let s = format!("{e:?}");
            s.split(['{', ' ']).next().unwrap().to_string()
        }
    }
}

/// Run one case; assert the shipped and reference results are identical.
fn check(case: &Case, tally: &mut BTreeMap<String, usize>) -> bool {
    let (shipped, reference) = case.run();
    assert_eq!(shipped, reference, "shipped and reference compilations differ");
    *tally.entry(label(&shipped)).or_default() += 1;
    shipped.is_ok()
}

fn mutations() -> Vec<(&'static str, fn(&mut Case))> {
    vec![
        ("public anchor", |c| c.anchor()[0].0 ^= 1),
        ("public nullifier", |c| c.nullifier()[0].0 ^= 1),
        ("public change commitment", |c| c.change_commitment()[3].0 ^= 1),
        ("recipient commitment / amount", |c| match &mut c.stmt {
            Stmt::Transfer(p, _) => p.recipient_commitment[5].0 ^= 1,
            Stmt::Withdrawal(p, _) => p.amount += 1,
        }),
        ("recipient value / change value +1", |c| match &mut c.stmt {
            Stmt::Transfer(_, w) => w.recipient.value += 1,
            Stmt::Withdrawal(_, w) => w.change.value += 1,
        }),
        ("change value zero", |c| c.change().value = 0),
        ("input value zero", |c| c.input().pair.value = 0),
        ("nullifier already spent", |c| { let n = *c.nullifier(); c.spent.push(n) }),
        ("context pool", |c| c.binding.pool[0] ^= 1),
        ("context asset", |c| c.binding.asset_id.0 ^= 1),
        ("context anchor sequence", |c| c.binding.anchor_sequence += 1),
        ("public asset", |c| c.asset().0 ^= 1),
        ("snapshot pool", |c| c.snapshot.pool[3] ^= 1),
        ("snapshot sequence", |c| c.snapshot.sequence += 1),
        ("snapshot index and sequence", |c| { c.snapshot.sequence += 1; c.snapshot.next_pair_index += 1 }),
        ("snapshot current root", |c| c.snapshot.current_root[2].0 ^= 1),
        ("snapshot frontier 0", |c| c.snapshot.frontier[0][0].0 ^= 1),
        ("snapshot frontier non-canonical at lowest set bit", |c| {
            let n = c.snapshot.next_pair_index;
            let level = if n == 0 { 0 } else { n.trailing_zeros() as usize };
            c.snapshot.frontier[level][7].0 = P + 3;
        }),
        ("super-root sibling non-canonical", |c| c.input().super_root_siblings[1][3].0 = P),
        ("super-root sibling value", |c| c.input().super_root_siblings[0][0].0 ^= 1),
        ("super-root direction", |c| c.input().super_root_directions[2] ^= true),
        ("membership sibling non-canonical", |c| c.input().pair.membership.siblings[4][2].0 = P + 5),
        ("membership sibling value", |c| c.input().pair.membership.siblings[7][6].0 ^= 1),
        ("membership index bit", |c| c.input().pair.membership.index ^= 1 << 9),
        ("membership index out of range", |c| c.input().pair.membership.index = 1 << 20),
        ("input salt", |c| c.input().pair.salt[0].0 ^= 1),
        ("input nullifier key non-canonical", |c| c.input().pair.nullifier_key[0].0 = P),
        ("input selected side", |c| c.input().pair.selected_second ^= true),
        ("pair occupancy inverse", |c| c.input().pair.pair_leaf.second_occupancy_inverse.0 ^= 1),
        ("pair first commitment non-canonical", |c| c.input().pair.pair_leaf.first_commitment[0].0 = P),
        ("change owner key", |c| c.change().owner_key[0].0 ^= 1),
    ]
}

#[test]
fn shipped_compiler_equals_pre_migration_compiler() {
    let mut tally = BTreeMap::new();
    let mut base = Vec::new();
    for transfer in [true, false] {
        let case = honest(None, transfer);
        assert!(check(&case, &mut tally), "saved fixture must compile");
        base.push(case);
    }
    println!("saved fixtures: 2 compiled, shipped == reference");

    let mut rng = Rng(0x61_7573_7069_7331);
    let (mut ok, mut rejected, mut i) = (0u32, 0u32, 0u64);
    while ok < 512 {
        let case = honest(Some(&mut rng), i % 2 == 0);
        if check(&case, &mut tally) { ok += 1 } else { rejected += 1 }
        if base.len() < 2 + 64 {
            base.push(case);
        }
        i += 1;
    }
    println!("randomized: {ok} honest witnesses compiled (glue.rs generator and seed), {rejected} rejected identically, shipped == reference");

    let muts = mutations();
    let mut mutated = 0usize;
    for case in &base {
        for (_, m) in &muts {
            let mut c = case.clone();
            m(&mut c);
            check(&c, &mut tally);
            mutated += 1;
        }
    }
    println!("mutations: {} kinds x {} base cases = {mutated} cases, shipped == reference", muts.len(), base.len());
    println!("result tally (all cases): {tally:?}");
    assert!(tally.len() >= 10, "the mutations must reach many distinct error paths");
}

/// Teeth: the comparison distinguishes different compilations, and one
/// changed cell of the shipped semantic C1 is detected.
#[test]
fn comparison_has_teeth() {
    let case = honest(None, true);
    let (shipped, reference) = case.run();
    let mut shipped = shipped.unwrap();
    assert_eq!(shipped, reference.clone().unwrap());
    shipped.semantic_c1.c1[7][300].0 ^= 1;
    assert_ne!(Ok(shipped), reference);
    let mut other = case.clone();
    other.snapshot = snapshot_at([1; 32], [2; 32], 14);
    let (a, _) = other.run();
    assert_ne!(a.unwrap(), reference.unwrap());
    println!("comparison_has_teeth: a one-cell change and a different snapshot are detected");
}

crates/aspis-statement/tests/r0_transpor:
use aspis_core::r0::{opening, transport};
use aspis_statement::pool_v1::{
    pool_v1_pair_forest_copy_active_rows_v1, pool_v1_pair_forest_relation_free_mask_cells_v1,
};

#[test]
fn transport_pads_match_authoritative_inventory_and_historical_order() {
    let active = pool_v1_pair_forest_copy_active_rows_v1().unwrap();
    let cells = pool_v1_pair_forest_relation_free_mask_cells_v1().unwrap();
    let legal = |r| (0..16).all(|c| cells.iter().any(|x| x.row == r && x.column == c));
    let pads: Vec<u16> = (0..1023)
        .filter(|r| !active.contains(r) && *r != 1014 && legal(*r))
        .take(89)
        .collect();
    assert_eq!(pads.len(), 89);
    assert_eq!(pads.as_slice(), transport::PAD_ROWS);
    for &r in pads.iter().chain(core::iter::once(&1023)) {
        assert!(!active.contains(&r));
        for column in 0..16 {
            assert!(cells.iter().any(|x| x.row == r && x.column == column));
        }
    }
    let mut order = pads.clone();
    order.extend((0..1023).filter(|r| !pads.contains(r)));
    order.push(1023);
    assert_eq!(order.as_slice(), transport::COEFFICIENT_TO_ROW);
    for r in 0..1024 {
        assert_eq!(opening::inactive(r).unwrap(), !active.contains(&(r as u16)));
    }
}

programs/aspis-pool/src/anchor.rs:
//! Read-only Pool V1 historical-anchor authentication.
//!
//! This layer binds an exact versioned statement envelope to the canonical
//! Pool state, the exact indexed root in its canonical history-page PDA and an
//! expected verifier profile/release.  It does not check nullifier freshness,
//! invoke a verifier, append outputs, or expose an instruction.

use aspis_statement::pool_v1::{
    decode_historical_anchor_envelope_v1, root_history_location, HistoricalAnchorEnvelopeV1,
    PoolV1TransitionKind,
};
use solana_program::{account_info::AccountInfo, program_error::ProgramError, pubkey::Pubkey};

use crate::{
    error::PoolV1ProgramError,
    history::{
        read_retained_root, require_program_owned, require_root_page_address,
        validate_root_page_bytes, RootPageHeaderV1,
    },
    state::{pool_v1_state_address, CanonicalPoolStateV1, PoolStateV1},
};

/// Exact transition/profile/release selected by the separately authenticated
/// verifier-registry layer.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct HistoricalAnchorAuthorizationV1 {
    pub transition_kind: PoolV1TransitionKind,
    pub verifier_profile: [u8; 32],
    pub verifier_release: [u8; 32],
}

/// Evidence that one envelope names the exact retained Pool root and expected
/// transition/profile/release.  Possessing this value is not proof acceptance
/// and grants no state-write authority.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct AuthenticatedHistoricalAnchorV1 {
    pub pool: [u8; 32],
    pub deployment_domain: [u8; 32],
    pub anchor_sequence: u64,
    pub anchor_root: aspis_statement::poseidon2::Digest,
    pub nullifier: aspis_statement::poseidon2::Digest,
    pub transition_kind: PoolV1TransitionKind,
    pub verifier_profile: [u8; 32],
    pub verifier_release: [u8; 32],
}

/// Sealed evidence that the exact anchor page passed one complete canonical
/// validation against an already authenticated Pool state.  The private
/// fields prevent callers from manufacturing a page-validation capability.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) struct PrevalidatedHistoricalAnchorV1 {
    authenticated: AuthenticatedHistoricalAnchorV1,
    history_page: Pubkey,
    header: RootPageHeaderV1,
}

impl PrevalidatedHistoricalAnchorV1 {
    pub(crate) fn authenticated(self) -> AuthenticatedHistoricalAnchorV1 {
        self.authenticated
    }

    pub(crate) fn history_page(self) -> Pubkey {
        self.history_page
    }

    pub(crate) fn header(self) -> RootPageHeaderV1 {
        self.header
    }
}

fn load_canonical_pool_state(
    program_id: &Pubkey,
    pool_account: &AccountInfo,
) -> Result<PoolStateV1, ProgramError> {
    require_program_owned(pool_account, program_id)?;
    if pool_account.is_signer {
        return Err(ProgramError::InvalidAccountData);
    }
    let state = {
        let data = pool_account.try_borrow_data()?;
        PoolStateV1::decode(&data, pool_account.key)?
    };
    let asset_mint = Pubkey::new_from_array(state.identity.asset_mint);
    if pool_account.key != &pool_v1_state_address(program_id, &asset_mint).0 {
        return Err(PoolV1ProgramError::InvalidPoolStateAddress.into());
    }
    Ok(state)
}

fn bind_envelope_to_state_and_selection(
    pool_account: &AccountInfo,
    state: &PoolStateV1,
    envelope: &HistoricalAnchorEnvelopeV1,
    expected: HistoricalAnchorAuthorizationV1,
) -> Result<(), ProgramError> {
    if envelope.pool != pool_account.key.to_bytes()
        || envelope.pool != state.identity.pool
        || envelope.deployment_domain != state.identity.deployment_domain
    {
        return Err(PoolV1ProgramError::HistoricalAnchorIdentityMismatch.into());
    }
    if envelope.transition_kind != expected.transition_kind
        || envelope.verifier_profile != expected.verifier_profile
        || envelope.verifier_release != expected.verifier_release
    {
        return Err(PoolV1ProgramError::HistoricalAnchorSelectionMismatch.into());
    }
    if envelope.anchor_sequence > state.current_root_sequence() {
        return Err(PoolV1ProgramError::HistoricalAnchorInFuture.into());
    }
    Ok(())
}

fn require_history_page_privileges(
    history_page_account: &AccountInfo,
    anchor_page_number: u64,
    current_page_number: u64,
) -> Result<(), ProgramError> {
    if history_page_account.is_signer
        || (anchor_page_number != current_page_number && history_page_account.is_writable)
    {
        return Err(PoolV1ProgramError::InvalidHistoricalAnchorPage.into());
    }
    Ok(())
}

/// Authenticate one exact historical anchor without modifying any account.
///
/// `pool_account` may be writable because the atomic spend handler also appends
/// to it. An older history page must be read-only. The page that
/// contains the current root may be writable because it can also be the
/// transition's current output page; the later append kernel independently
/// enforces the precise page writability required by that transition.
fn authenticate_historical_anchor_against_state_v1(
    program_id: &Pubkey,
    pool_account: &AccountInfo,
    history_page_account: &AccountInfo,
    envelope_bytes: &[u8],
    expected: HistoricalAnchorAuthorizationV1,
    state: &PoolStateV1,
) -> Result<PrevalidatedHistoricalAnchorV1, ProgramError> {
    let envelope = decode_historical_anchor_envelope_v1(envelope_bytes)
        .map_err(|_| PoolV1ProgramError::InvalidHistoricalAnchorEnvelope)?;
    bind_envelope_to_state_and_selection(pool_account, state, &envelope, expected)?;

    let location = root_history_location(envelope.anchor_sequence);
    let current_location = root_history_location(state.current_root_sequence());
    require_program_owned(history_page_account, program_id)?;
    require_history_page_privileges(
        history_page_account,
        location.page_number,
        current_location.page_number,
    )?;
    require_root_page_address(
        program_id,
        pool_account.key,
        location.page_number,
        history_page_account,
    )?;
    let (header, retained_root) = {
        let data = history_page_account.try_borrow_data()?;
        let header = validate_root_page_bytes(&data, pool_account.key, location.page_number)
            .map_err(|_| ProgramError::from(PoolV1ProgramError::InvalidHistoricalAnchorPage))?;
        let retained = read_retained_root(&data, header, envelope.anchor_sequence)
            .map_err(|_| PoolV1ProgramError::InvalidHistoricalAnchorPage)?;
        (header, retained)
    };
    if retained_root != envelope.anchor_root {
        return Err(PoolV1ProgramError::HistoricalAnchorRootMismatch.into());
    }

    Ok(PrevalidatedHistoricalAnchorV1 {
        authenticated: AuthenticatedHistoricalAnchorV1 {
            pool: envelope.pool,
            deployment_domain: envelope.deployment_domain,
            anchor_sequence: envelope.anchor_sequence,
            anchor_root: envelope.anchor_root,
            nullifier: envelope.nullifier,
            transition_kind: envelope.transition_kind,
            verifier_profile: envelope.verifier_profile,
            verifier_release: envelope.verifier_release,
        },
        history_page: *history_page_account.key,
        header,
    })
}

/// Processor-only adapter that carries forward its already complete canonical
/// Pool decode.  The Pool account is not exposed to an intervening CPI before
/// this call, so repeating the depth-20 reconstruction would prove the same
/// fact twice.
pub(crate) fn authenticate_historical_anchor_after_prevalidated_state_v1(
    program_id: &Pubkey,
    pool_account: &AccountInfo,
    history_page_account: &AccountInfo,
    envelope_bytes: &[u8],
    expected: HistoricalAnchorAuthorizationV1,
    state: &CanonicalPoolStateV1,
) -> Result<PrevalidatedHistoricalAnchorV1, ProgramError> {
    state.require_same_writable_account(program_id, pool_account)?;
    authenticate_historical_anchor_against_state_v1(
        program_id,
        pool_account,
        history_page_account,
        envelope_bytes,
        expected,
        state.as_state(),
    )
}

pub fn authenticate_historical_anchor_v1(
    program_id: &Pubkey,
    pool_account: &AccountInfo,
    history_page_account: &AccountInfo,
    envelope_bytes: &[u8],
    expected: HistoricalAnchorAuthorizationV1,
) -> Result<AuthenticatedHistoricalAnchorV1, ProgramError> {
    let state = load_canonical_pool_state(program_id, pool_account)?;
    authenticate_historical_anchor_against_state_v1(
        program_id,
        pool_account,
        history_page_account,
        envelope_bytes,
        expected,
        &state,
    )
    .map(PrevalidatedHistoricalAnchorV1::authenticated)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::{
        empty_roots::POOL_V1_EMPTY_ROOTS,
        state::{PoolInitializationV1, POOL_V1_STATE_ACCOUNT_BYTES},
        LEGACY_SPL_TOKEN_PROGRAM_ID,
    };
    use aspis_core::field::M31;
    use aspis_statement::{
        pool_v1::{encode_historical_anchor_envelope_v1, RootHistoryPageV1, VerifierPolicyV1},
        poseidon2::Digest,
    };
    use solana_program::clock::Epoch;

    fn digest(seed: u32) -> Digest {
        core::array::from_fn(|index| M31(seed + 29 * index as u32))
    }

    fn initialization(mint: &Pubkey) -> PoolInitializationV1 {
        PoolInitializationV1 {
            asset_mint: mint.to_bytes(),
            token_program: LEGACY_SPL_TOKEN_PROGRAM_ID.to_bytes(),
            asset_id: M31(4),
            deployment_domain: [5u8; 32],
            verifier_policy: VerifierPolicyV1 {
                flags: 0,
                registry_program: [6u8; 32],
                registry_authority: [7u8; 32],
                policy_binding: [8u8; 32],
            },
        }
    }

    fn expected() -> HistoricalAnchorAuthorizationV1 {
        HistoricalAnchorAuthorizationV1 {
            transition_kind: PoolV1TransitionKind::PrivateTransfer,
            verifier_profile: [9u8; 32],
            verifier_release: [10u8; 32],
        }
    }

    fn account<'a>(
        key: &'a Pubkey,
        owner: &'a Pubkey,
        lamports: &'a mut u64,
        data: &'a mut [u8],
        signer: bool,
        writable: bool,
    ) -> AccountInfo<'a> {
        AccountInfo::new(
            key,
            signer,
            writable,
            lamports,
            data,
            owner,
            false,
            Epoch::default(),
        )
    }

    #[derive(Clone)]
    struct Fixture {
        program_id: Pubkey,
        pool_key: Pubkey,
        page_key: Pubkey,
        pool_data: [u8; POOL_V1_STATE_ACCOUNT_BYTES],
        page_data: std::vec::Vec<u8>,
        first_root: Digest,
        current_root: Digest,
    }

    fn fixture() -> Fixture {
        let program_id = Pubkey::new_unique();
        let mint = Pubkey::new_unique();
        let pool_key = pool_v1_state_address(&program_id, &mint).0;
        let base = PoolStateV1::genesis(&pool_key, initialization(&mint)).unwrap();
        let (tree, first) = base
            .tree
            .append_one_with_empty_roots(digest(100), &POOL_V1_EMPTY_ROOTS)
            .unwrap();
        let (tree, second) = tree
            .append_one_with_empty_roots(digest(200), &POOL_V1_EMPTY_ROOTS)
            .unwrap();
        let state = PoolStateV1 { tree, ..base };
        let mut page = RootHistoryPageV1::genesis(
            pool_key.to_bytes(),
            POOL_V1_EMPTY_ROOTS[aspis_statement::pool_v1::POOL_V1_TREE_DEPTH],
        );
        page.push(1, first.root).unwrap();
        page.push(2, second.root).unwrap();
        let page_key = crate::pool_v1_root_page_address(&program_id, &pool_key, 0).0;
        Fixture {
            program_id,
            pool_key,
            page_key,
            pool_data: state.encode().unwrap(),
            page_data: page.encode().unwrap().to_vec(),
            first_root: first.root,
            current_root: second.root,
        }
    }

    fn envelope(fixture: &Fixture, sequence: u64, root: Digest) -> HistoricalAnchorEnvelopeV1 {
        HistoricalAnchorEnvelopeV1 {
            transition_kind: PoolV1TransitionKind::PrivateTransfer,
            pool: fixture.pool_key.to_bytes(),
            deployment_domain: [5u8; 32],
            anchor_sequence: sequence,
            anchor_root: root,
            nullifier: digest(300),
            verifier_profile: [9u8; 32],
            verifier_release: [10u8; 32],
        }
    }

    fn authenticate(
        fixture: &mut Fixture,
        envelope: HistoricalAnchorEnvelopeV1,
        expected: HistoricalAnchorAuthorizationV1,
        page_key: Pubkey,
        page_signer: bool,
        page_writable: bool,
    ) -> Result<AuthenticatedHistoricalAnchorV1, ProgramError> {
        let encoded = encode_historical_anchor_envelope_v1(&envelope).unwrap();
        let mut pool_lamports = 1;
        let mut page_lamports = 1;
        let pool = account(
            &fixture.pool_key,
            &fixture.program_id,
            &mut pool_lamports,
            &mut fixture.pool_data,
            false,
            true,
        );
        let page = account(
            &page_key,
            &fixture.program_id,
            &mut page_lamports,
            &mut fixture.page_data,
            page_signer,
            page_writable,
        );
        authenticate_historical_anchor_v1(&fixture.program_id, &pool, &page, &encoded, expected)
    }

    #[test]
    fn retained_sequence_one_authenticates_after_sequence_two_is_appended() {
        let mut fixture = fixture();
        let envelope = envelope(&fixture, 1, fixture.first_root);
        let page_key = fixture.page_key;
        let before_pool = fixture.pool_data;
        let before_page = fixture.page_data.clone();
        let authenticated =
            authenticate(&mut fixture, envelope, expected(), page_key, false, false).unwrap();
        assert_eq!(authenticated.anchor_sequence, 1);
        assert_eq!(authenticated.anchor_root, fixture.first_root);
        assert_ne!(authenticated.anchor_root, fixture.current_root);
        assert_eq!(fixture.pool_data, before_pool);
        assert_eq!(fixture.page_data, before_page);
    }

    #[test]
    fn exact_current_root_also_authenticates_without_mutation() {
        let mut fixture = fixture();
        let envelope = envelope(&fixture, 2, fixture.current_root);
        let page_key = fixture.page_key;
        let authenticated =
            authenticate(&mut fixture, envelope, expected(), page_key, false, true).unwrap();
        assert_eq!(authenticated.anchor_sequence, 2);
        assert_eq!(authenticated.anchor_root, fixture.current_root);
    }

    #[test]
    fn prevalidated_state_adapter_is_exact_and_still_rejects_page_corruption() {
        let base = fixture();
        let selected = envelope(&base, 1, base.first_root);
        let encoded = encode_historical_anchor_envelope_v1(&selected).unwrap();

        let mut standalone = base.clone();
        let standalone_page_key = standalone.page_key;
        let standalone_result = authenticate(
            &mut standalone,
            selected,
            expected(),
            standalone_page_key,
            false,
            false,
        )
        .unwrap();

        let mut prevalidated = base.clone();
        let mut pool_lamports = 1;
        let mut page_lamports = 1;
        let canonical = {
            let pool = account(
                &prevalidated.pool_key,
                &prevalidated.program_id,
                &mut pool_lamports,
                &mut prevalidated.pool_data,
                false,
                true,
            );
            CanonicalPoolStateV1::decode_account(&prevalidated.program_id, &pool).unwrap()
        };
        let sealed = {
            let pool = account(
                &prevalidated.pool_key,
                &prevalidated.program_id,
                &mut pool_lamports,
                &mut prevalidated.pool_data,
                false,
                true,
            );
            let page = account(
                &prevalidated.page_key,
                &prevalidated.program_id,
                &mut page_lamports,
                &mut prevalidated.page_data,
                false,
                false,
            );
            authenticate_historical_anchor_after_prevalidated_state_v1(
                &prevalidated.program_id,
                &pool,
                &page,
                &encoded,
                expected(),
                &canonical,
            )
            .unwrap()
        };
        assert_eq!(sealed.authenticated(), standalone_result);
        assert_eq!(sealed.history_page(), prevalidated.page_key);
        assert_eq!(sealed.header().filled, 3);

        let mut corrupt = base;
        let last = corrupt.page_data.len() - 1;
        corrupt.page_data[last] = 1;
        let mut corrupt_pool_lamports = 1;
        let mut corrupt_page_lamports = 1;
        let canonical = {
            let pool = account(
                &corrupt.pool_key,
                &corrupt.program_id,
                &mut corrupt_pool_lamports,
                &mut corrupt.pool_data,
                false,
                true,
            );
            CanonicalPoolStateV1::decode_account(&corrupt.program_id, &pool).unwrap()
        };
        let result = {
            let pool = account(
                &corrupt.pool_key,
                &corrupt.program_id,
                &mut corrupt_pool_lamports,
                &mut corrupt.pool_data,
                false,
                true,
            );
            let page = account(
                &corrupt.page_key,
                &corrupt.program_id,
                &mut corrupt_page_lamports,
                &mut corrupt.page_data,
                false,
                false,
            );
            authenticate_historical_anchor_after_prevalidated_state_v1(
                &corrupt.program_id,
                &pool,
                &page,
                &encoded,
                expected(),
                &canonical,
            )
        };
        assert_eq!(
            result,
            Err(PoolV1ProgramError::InvalidHistoricalAnchorPage.into())
        );
    }

    #[test]
    fn wrong_root_domain_selection_future_or_page_fails_closed() {
        let base = fixture();
        let cases = [
            (
                HistoricalAnchorEnvelopeV1 {
                    anchor_root: digest(999),
                    ..envelope(&base, 1, base.first_root)
                },
                expected(),
                base.page_key,
                PoolV1ProgramError::HistoricalAnchorRootMismatch.into(),
            ),
            (
                HistoricalAnchorEnvelopeV1 {
                    deployment_domain: [99u8; 32],
                    ..envelope(&base, 1, base.first_root)
                },
                expected(),
                base.page_key,
                PoolV1ProgramError::HistoricalAnchorIdentityMismatch.into(),
            ),
            (
                envelope(&base, 1, base.first_root),
                HistoricalAnchorAuthorizationV1 {
                    verifier_release: [99u8; 32],
                    ..expected()
                },
                base.page_key,
                PoolV1ProgramError::HistoricalAnchorSelectionMismatch.into(),
            ),
            (
                envelope(&base, 3, base.current_root),
                expected(),
                base.page_key,
                PoolV1ProgramError::HistoricalAnchorInFuture.into(),
            ),
            (
                envelope(&base, 1, base.first_root),
                expected(),
                Pubkey::new_unique(),
                PoolV1ProgramError::InvalidRootPageAddress.into(),
            ),
        ];
        for (envelope, expected, page_key, error) in cases {
            let mut fixture = base.clone();
            let before_pool = fixture.pool_data;
            let before_page = fixture.page_data.clone();
            assert_eq!(
                authenticate(&mut fixture, envelope, expected, page_key, false, false),
                Err(error)
            );
            assert_eq!(fixture.pool_data, before_pool);
            assert_eq!(fixture.page_data, before_page);
        }
    }

    #[test]
    fn history_page_signer_is_rejected_without_writes() {
        let mut fixture = fixture();
        let envelope = envelope(&fixture, 1, fixture.first_root);
        let page_key = fixture.page_key;
        let before_pool = fixture.pool_data;
        let before_page = fixture.page_data.clone();
        assert_eq!(
            authenticate(&mut fixture, envelope, expected(), page_key, true, false),
            Err(PoolV1ProgramError::InvalidHistoricalAnchorPage.into())
        );
        assert_eq!(fixture.pool_data, before_pool);
        assert_eq!(fixture.page_data, before_page);
    }

    #[test]
    fn older_page_writable_privilege_is_rejected() {
        let mut fixture = fixture();
        let mut page_lamports = 1;
        let page = account(
            &fixture.page_key,
            &fixture.program_id,
            &mut page_lamports,
            &mut fixture.page_data,
            false,
            true,
        );
        assert_eq!(
            require_history_page_privileges(&page, 0, 1),
            Err(PoolV1ProgramError::InvalidHistoricalAnchorPage.into())
        );
    }
}

programs/aspis-pool/src/cancel_prepared_:
//! Exact public instruction wire for cancelling and refunding one prepared
//! Pool V1 settlement plan.
//!
//! Cancellation carries no state or timing claim. The shape byte commits the
//! exact account cardinality needed to authenticate and close either an `ASPS`
//! core alone or an `ASPS` core plus its `ASRS` rollover shard.

use solana_program::program_error::ProgramError;

use crate::instruction::POOL_V1_INSTRUCTION_VERSION;

pub const POOL_V1_CANCEL_PREPARED_SETTLEMENT_INSTRUCTION_MAGIC: [u8; 4] = *b"ASPX";
pub const POOL_V1_CANCEL_PREPARED_SETTLEMENT_INSTRUCTION_BYTES: usize = 8;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum CancelPreparedSettlementAccountShapeV1 {
    CoreOnly = 1,
    CoreAndRolloverShard = 2,
}

impl CancelPreparedSettlementAccountShapeV1 {
    pub const fn account_count(self) -> usize {
        match self {
            Self::CoreOnly => 2,
            Self::CoreAndRolloverShard => 3,
        }
    }

    pub const fn has_rollover_shard(self) -> bool {
        matches!(self, Self::CoreAndRolloverShard)
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum CancelPreparedSettlementInstructionFormatErrorV1 {
    WrongLength,
    WrongMagic,
    WrongVersion,
    WrongAccountShape,
    NonZeroReserved,
}

impl From<CancelPreparedSettlementInstructionFormatErrorV1> for ProgramError {
    fn from(_: CancelPreparedSettlementInstructionFormatErrorV1) -> Self {
        ProgramError::InvalidInstructionData
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct CancelPreparedSettlementInstructionV1 {
    pub account_shape: CancelPreparedSettlementAccountShapeV1,
}

pub fn decode_cancel_prepared_settlement_instruction_v1(
    bytes: &[u8],
) -> Result<CancelPreparedSettlementInstructionV1, CancelPreparedSettlementInstructionFormatErrorV1>
{
    if bytes.len() != POOL_V1_CANCEL_PREPARED_SETTLEMENT_INSTRUCTION_BYTES {
        return Err(CancelPreparedSettlementInstructionFormatErrorV1::WrongLength);
    }
    if bytes[..4] != POOL_V1_CANCEL_PREPARED_SETTLEMENT_INSTRUCTION_MAGIC {
        return Err(CancelPreparedSettlementInstructionFormatErrorV1::WrongMagic);
    }
    if bytes[4] != POOL_V1_INSTRUCTION_VERSION {
        return Err(CancelPreparedSettlementInstructionFormatErrorV1::WrongVersion);
    }
    let account_shape = match bytes[5] {
        1 => CancelPreparedSettlementAccountShapeV1::CoreOnly,
        2 => CancelPreparedSettlementAccountShapeV1::CoreAndRolloverShard,
        _ => return Err(CancelPreparedSettlementInstructionFormatErrorV1::WrongAccountShape),
    };
    if bytes[6..] != [0u8; 2] {
        return Err(CancelPreparedSettlementInstructionFormatErrorV1::NonZeroReserved);
    }
    Ok(CancelPreparedSettlementInstructionV1 { account_shape })
}

pub fn encode_cancel_prepared_settlement_instruction_v1(
    account_shape: CancelPreparedSettlementAccountShapeV1,
) -> [u8; POOL_V1_CANCEL_PREPARED_SETTLEMENT_INSTRUCTION_BYTES] {
    let mut bytes = [0u8; POOL_V1_CANCEL_PREPARED_SETTLEMENT_INSTRUCTION_BYTES];
    bytes[..4].copy_from_slice(&POOL_V1_CANCEL_PREPARED_SETTLEMENT_INSTRUCTION_MAGIC);
    bytes[4] = POOL_V1_INSTRUCTION_VERSION;
    bytes[5] = account_shape as u8;
    bytes
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn cancel_prepared_wire_is_exact_shape_bound_and_canonical() {
        for shape in [
            CancelPreparedSettlementAccountShapeV1::CoreOnly,
            CancelPreparedSettlementAccountShapeV1::CoreAndRolloverShard,
        ] {
            let encoded = encode_cancel_prepared_settlement_instruction_v1(shape);
            assert_eq!(
                encoded.len(),
                POOL_V1_CANCEL_PREPARED_SETTLEMENT_INSTRUCTION_BYTES
            );
            assert_eq!(
                decode_cancel_prepared_settlement_instruction_v1(&encoded),
                Ok(CancelPreparedSettlementInstructionV1 {
                    account_shape: shape,
                })
            );
        }

        let encoded = encode_cancel_prepared_settlement_instruction_v1(
            CancelPreparedSettlementAccountShapeV1::CoreOnly,
        );
        let mut trailing = encoded.to_vec();
        trailing.push(0);
        assert_eq!(
            decode_cancel_prepared_settlement_instruction_v1(&trailing),
            Err(CancelPreparedSettlementInstructionFormatErrorV1::WrongLength)
        );
        assert_eq!(
            decode_cancel_prepared_settlement_instruction_v1(&encoded[..7]),
            Err(CancelPreparedSettlementInstructionFormatErrorV1::WrongLength)
        );

        for (offset, expected) in [
            (
                0,
                CancelPreparedSettlementInstructionFormatErrorV1::WrongMagic,
            ),
            (
                4,
                CancelPreparedSettlementInstructionFormatErrorV1::WrongVersion,
            ),
            (
                5,
                CancelPreparedSettlementInstructionFormatErrorV1::WrongAccountShape,
            ),
            (
                6,
                CancelPreparedSettlementInstructionFormatErrorV1::NonZeroReserved,
            ),
            (
                7,
                CancelPreparedSettlementInstructionFormatErrorV1::NonZeroReserved,
            ),
        ] {
            let mut mutated = encoded;
            mutated[offset] ^= 0xff;
            assert_eq!(
                decode_cancel_prepared_settlement_instruction_v1(&mutated),
                Err(expected)
            );
        }
    }
}

programs/aspis-pool/src/deposit.rs:
//! Vault-backed Pool V1 deposit kernel.
//!
//! The native entrypoint reaches this crate-private kernel only through the
//! exact `ASDI` decoder. It validates one exact legacy SPL Token transfer,
//! computes the frozen note commitment from public fields, then appends exactly
//! one leaf/root. The encrypted payload is bounded opaque delivery data and is
//! never an input to the commitment.

extern crate alloc;

use alloc::boxed::Box;

use aspis_core::field::P;
use aspis_statement::{
    pool_v1::{
        pool_v1_note_commitment, DepositEventV1, DepositReceiptV1,
        POOL_V1_ENCRYPTED_NOTE_PAYLOAD_MAX_BYTES,
    },
    poseidon2::Digest,
    VALUE_LIMIT,
};
use solana_program::{
    account_info::AccountInfo, instruction::Instruction, program, program_error::ProgramError,
    pubkey::Pubkey,
};

use crate::{
    error::PoolV1ProgramError,
    history::require_program_account,
    state::{pool_v1_state_address, CanonicalPoolStateV1, PoolStateV1},
    transition::{
        apply_authorized_append_after_prevalidated_v1, apply_authorized_append_after_v1,
        AuthorizedAppendReceiptV1, AuthorizedAppendV1,
    },
    vault::{
        exact_transfer_account_infos_v1, plan_legacy_deposit_transfer_v1,
        validate_exact_deposit_delta_v1, LegacyDepositTransferPlanV1,
    },
};

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct DepositRequestV1<'a> {
    pub owner_key: Digest,
    pub amount: u32,
    pub salt: Digest,
    pub encrypted_note_payload: &'a [u8],
}

fn digest_is_canonical(digest: &Digest) -> bool {
    digest.iter().all(|limb| limb.0 < P)
}

fn validate_request(request: &DepositRequestV1<'_>) -> Result<(), ProgramError> {
    // The public instruction field is exactly u32, while the frozen spend
    // relation additionally requires the 30-bit VALUE_LIMIT range.
    if request.amount == 0 || request.amount >= VALUE_LIMIT {
        return Err(PoolV1ProgramError::InvalidDepositAmount.into());
    }
    if request.encrypted_note_payload.len() > POOL_V1_ENCRYPTED_NOTE_PAYLOAD_MAX_BYTES {
        return Err(PoolV1ProgramError::InvalidEncryptedNotePayload.into());
    }
    if !digest_is_canonical(&request.owner_key) || !digest_is_canonical(&request.salt) {
        return Err(PoolV1ProgramError::NonCanonicalLeaf.into());
    }
    Ok(())
}

fn load_pool_state_for_deposit(
    program_id: &Pubkey,
    state_accounts: &[AccountInfo],
) -> Result<Box<PoolStateV1>, ProgramError> {
    let pool_account = state_accounts
        .first()
        .ok_or(ProgramError::NotEnoughAccountKeys)?;
    require_program_account(pool_account, program_id, true)?;
    let state = {
        let data = pool_account.try_borrow_data()?;
        PoolStateV1::decode_boxed(&data, pool_account.key)?
    };
    let asset_mint = Pubkey::new_from_array(state.identity.asset_mint);
    if pool_account.key != &pool_v1_state_address(program_id, &asset_mint).0 {
        return Err(PoolV1ProgramError::InvalidPoolStateAddress.into());
    }
    Ok(state)
}

fn require_disjoint_account_groups(
    state_accounts: &[AccountInfo],
    token_accounts: &[AccountInfo],
) -> Result<(), ProgramError> {
    for state_account in state_accounts {
        for token_account in token_accounts {
            if state_account.key == token_account.key {
                return Err(ProgramError::InvalidArgument);
            }
        }
    }
    Ok(())
}

struct PreparedDepositV1<'info> {
    transfer_plan: LegacyDepositTransferPlanV1,
    transfer_infos: [AccountInfo<'info>; 5],
    note_commitment: Digest,
}

fn prepare_deposit_after_state_validation_v1<'info>(
    program_id: &Pubkey,
    state: &PoolStateV1,
    token_accounts: &[AccountInfo<'info>],
    request: &DepositRequestV1<'_>,
) -> Result<PreparedDepositV1<'info>, ProgramError> {
    let pool = Pubkey::new_from_array(state.identity.pool);
    let transfer_plan =
        plan_legacy_deposit_transfer_v1(program_id, &pool, state, token_accounts, request.amount)?;
    let note_commitment = pool_v1_note_commitment(
        &request.owner_key,
        request.amount,
        state.identity.asset_id,
        &request.salt,
    );
    let transfer_infos = exact_transfer_account_infos_v1(token_accounts)?;
    Ok(PreparedDepositV1 {
        transfer_plan,
        transfer_infos,
        note_commitment,
    })
}

fn finish_deposit_event_v1<'payload>(
    state: &PoolStateV1,
    request: DepositRequestV1<'payload>,
    prepared: &PreparedDepositV1<'_>,
    append: AuthorizedAppendReceiptV1,
) -> DepositEventV1<'payload> {
    let receipt = DepositReceiptV1 {
        pool: state.identity.pool,
        asset_mint: state.identity.asset_mint,
        source_token_account: prepared.transfer_plan.source.to_bytes(),
        vault_token_account: prepared.transfer_plan.vault.to_bytes(),
        amount: request.amount,
        encrypted_note_payload_bytes: request.encrypted_note_payload.len() as u16,
        note_commitment: prepared.note_commitment,
        leaf_index: append.first.leaf_index,
        root_sequence: append.first.leaf_index + 1,
        root: append.first.root,
    };
    DepositEventV1 {
        receipt,
        encrypted_note_payload: request.encrypted_note_payload,
    }
}

#[inline(never)]
fn apply_vault_backed_deposit_with_transfer_v1<'payload, 'info, F>(
    program_id: &Pubkey,
    state_accounts: &[AccountInfo<'info>],
    token_accounts: &[AccountInfo<'info>],
    request: DepositRequestV1<'payload>,
    transfer: F,
) -> Result<DepositEventV1<'payload>, ProgramError>
where
    F: FnOnce(&Instruction, &[AccountInfo<'info>]) -> Result<(), ProgramError>,
{
    validate_request(&request)?;
    require_disjoint_account_groups(state_accounts, token_accounts)?;
    let state = load_pool_state_for_deposit(program_id, state_accounts)?;
    let prepared =
        prepare_deposit_after_state_validation_v1(program_id, &state, token_accounts, &request)?;

    // The transition kernel completes all tree/history validation, planning
    // and mutable Pool borrow acquisition before calling this closure. The
    // exact transfer and post-CPI delta check therefore precede the first Pool
    // state write. Returning Err relies on Solana transaction rollback for any
    // successful CPI effects; CPI/runtime atomicity remains an external gate.
    let append = apply_authorized_append_after_v1(
        program_id,
        state_accounts,
        AuthorizedAppendV1::One(prepared.note_commitment),
        || {
            transfer(
                &prepared.transfer_plan.instruction,
                &prepared.transfer_infos,
            )?;
            validate_exact_deposit_delta_v1(token_accounts, &prepared.transfer_plan)
        },
    )?;
    Ok(finish_deposit_event_v1(&state, request, &prepared, append))
}

#[inline(never)]
fn apply_prevalidated_vault_backed_deposit_with_transfer_v1<'payload, 'info, F>(
    program_id: &Pubkey,
    state_accounts: &[AccountInfo<'info>],
    token_accounts: &[AccountInfo<'info>],
    state: &CanonicalPoolStateV1,
    request: DepositRequestV1<'payload>,
    transfer: F,
) -> Result<DepositEventV1<'payload>, ProgramError>
where
    F: FnOnce(&Instruction, &[AccountInfo<'info>]) -> Result<(), ProgramError>,
{
    validate_request(&request)?;
    require_disjoint_account_groups(state_accounts, token_accounts)?;
    let pool_account = state_accounts
        .first()
        .ok_or(ProgramError::NotEnoughAccountKeys)?;
    state.require_same_writable_account(program_id, pool_account)?;
    let prepared = prepare_deposit_after_state_validation_v1(
        program_id,
        state.as_state(),
        token_accounts,
        &request,
    )?;
    let append = apply_authorized_append_after_prevalidated_v1(
        program_id,
        state_accounts,
        state,
        AuthorizedAppendV1::One(prepared.note_commitment),
        || {
            transfer(
                &prepared.transfer_plan.instruction,
                &prepared.transfer_infos,
            )?;
            validate_exact_deposit_delta_v1(token_accounts, &prepared.transfer_plan)
        },
    )?;
    Ok(finish_deposit_event_v1(
        state.as_state(),
        request,
        &prepared,
        append,
    ))
}

/// Apply one vault-backed deposit through the legacy SPL Token program.
///
/// Exact account groups are:
///
/// - state: `[pool_state, current_root_page]`, plus the zeroed next page only
///   when the one-leaf append rolls over;
/// - token: `[mint, source, source_authority, vault, token_program]`.
///
/// There is intentionally no public raw-append function or instruction.
#[inline(never)]
pub fn apply_vault_backed_deposit_v1<'payload, 'info>(
    program_id: &Pubkey,
    state_accounts: &[AccountInfo<'info>],
    token_accounts: &[AccountInfo<'info>],
    request: DepositRequestV1<'payload>,
) -> Result<DepositEventV1<'payload>, ProgramError> {
    apply_vault_backed_deposit_with_transfer_v1(
        program_id,
        state_accounts,
        token_accounts,
        request,
        program::invoke,
    )
}

/// Processor-only path carrying the one canonical decoded Pool state through
/// deposit authorization and persistence. Standalone callers keep using
/// `apply_vault_backed_deposit_v1`, which performs its own canonical decode.
#[inline(never)]
pub(crate) fn apply_prevalidated_vault_backed_deposit_v1<'payload, 'info>(
    program_id: &Pubkey,
    state_accounts: &[AccountInfo<'info>],
    token_accounts: &[AccountInfo<'info>],
    state: &CanonicalPoolStateV1,
    request: DepositRequestV1<'payload>,
) -> Result<DepositEventV1<'payload>, ProgramError> {
    apply_prevalidated_vault_backed_deposit_with_transfer_v1(
        program_id,
        state_accounts,
        token_accounts,
        state,
        request,
        program::invoke,
    )
}

