    Ok(Box::new(decode_pair_forest_initialize_instruction_v1(
        instruction_data,
    )?))
}

#[inline(never)]
fn forest_master_image_box_v1(
    expected_master: &Pubkey,
    initialization: &PoolInitializationV1,
    master_bump: u8,
