                Some(&invalid),
                &mut untouched_runtime,
            )
            .is_err());
            assert!(untouched_runtime.invoked.is_none());
        }
        let mut runtime = MockRuntime {
            returned: None,
            invoked: None,
        };
        let authenticated = invoke_pair_forest_terminal_with_runtime_v1(
            plan,
            &proof,
            &master,
            &checkpoint,
            &lane,
