                )
                .unwrap()
            }
            PoolV1TransitionKind::Withdrawal => {
                let statement =
                    decode_pool_v1_withdrawal_public_v1(&fixture.statement_payload).unwrap();
                encode_withdrawal_instruction_v1(
                    &envelope,
                    &WithdrawalStatementV1 {
                        pool: statement.pool,
