//! Exact Pool V1 state account image.

extern crate alloc;

use alloc::boxed::Box;

use aspis_core::field::M31;
use aspis_statement::pool_v1::{
    decode_pool_identity_v1, decode_verifier_policy_v1, encode_pool_identity_v1,
    root_history_location, validate_verifier_policy_v1, IncrementalMerkleTreeV1, PoolIdentityV1,
    ValidatedIncrementalMerkleTreeV1, VerifierPolicyV1, POOL_V1_DIGEST_ENCODING_VERSION,
    POOL_V1_FORMAT_BINDING, POOL_V1_FORMAT_VERSION, POOL_V1_IDENTITY_BYTES, POOL_V1_LEAF_CAPACITY,
    POOL_V1_ROOT_HISTORY_CAPACITY_LOG2, POOL_V1_TREE_DEPTH, POOL_V1_TREE_HASH_VERSION,
    POOL_V1_TREE_STATE_ACCOUNT_BYTES, POOL_V1_TREE_STATE_MAGIC, POOL_V1_TREE_STATE_VERSION,
    POOL_V1_VERIFIER_POLICY_BYTES, POOL_V1_VERIFIER_POLICY_MAGIC, POOL_V1_VERIFIER_POLICY_VERSION,
};
use solana_program::{program_error::ProgramError, pubkey::Pubkey};

use crate::{
    empty_roots::POOL_V1_EMPTY_ROOTS, error::PoolV1ProgramError, history::require_program_account,
    vault::LEGACY_SPL_TOKEN_PROGRAM_ID,
};

pub const POOL_V1_STATE_ACCOUNT_MAGIC: [u8; 4] = *b"ASPK";
/// Revision two is intentionally incompatible with the never-deployed
/// revision-one image that embedded one exact verifier release.
pub const POOL_V1_STATE_ACCOUNT_VERSION: u8 = 2;
pub const POOL_V1_STATE_SEED: &[u8] = b"aspis-pool-state-v1";
pub const POOL_V1_STATE_HEADER_BYTES: usize = 64;
pub const POOL_V1_STATE_IDENTITY_OFFSET: usize = POOL_V1_STATE_HEADER_BYTES;
pub const POOL_V1_STATE_POLICY_OFFSET: usize =
    POOL_V1_STATE_IDENTITY_OFFSET + POOL_V1_IDENTITY_BYTES;
pub const POOL_V1_STATE_TREE_OFFSET: usize =
    POOL_V1_STATE_POLICY_OFFSET + POOL_V1_VERIFIER_POLICY_BYTES;
pub const POOL_V1_STATE_ACCOUNT_BYTES: usize =
    POOL_V1_STATE_TREE_OFFSET + POOL_V1_TREE_STATE_ACCOUNT_BYTES;

const STATE_SEQUENCE_OFFSET: usize = 40;
const STATE_PAGE_OFFSET: usize = 48;
const STATE_SLOT_OFFSET: usize = 56;

fn exact_state_array<const N: usize>(bytes: &[u8]) -> Result<[u8; N], ProgramError> {
    bytes
        .try_into()
        .map_err(|_| ProgramError::InvalidAccountData)
}

/// One canonical Pool V1 state PDA per asset mint and program deployment.
pub fn pool_v1_state_address(program_id: &Pubkey, asset_mint: &Pubkey) -> (Pubkey, u8) {
    Pubkey::find_program_address(&[POOL_V1_STATE_SEED, asset_mint.as_ref()], program_id)
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct PoolInitializationV1 {
    pub asset_mint: [u8; 32],
    pub token_program: [u8; 32],
    pub asset_id: M31,
    pub deployment_domain: [u8; 32],
    pub verifier_policy: VerifierPolicyV1,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct PoolStateV1 {
    pub identity: PoolIdentityV1,
    pub verifier_policy: VerifierPolicyV1,
    pub tree: IncrementalMerkleTreeV1,
}

/// One state image that has passed the complete canonical account decoder and
/// canonical per-mint PDA check at the native instruction boundary.
///
/// The fields are private so downstream kernels cannot manufacture this token
/// from an unchecked `PoolStateV1`. They may cheaply re-check that the same
/// runtime account/program pair is still being used, without reparsing the
/// 1,000-byte image or reconstructing its depth-20 root.
pub(crate) struct CanonicalPoolStateV1 {
    program_id: Pubkey,
    pool: Pubkey,
    state: Box<PoolStateV1>,
    tree_evidence: CanonicalTreeEvidenceV1,
}

enum CanonicalTreeEvidenceV1 {
    /// The root/frontier relation was recomputed in this instruction.
    Reconstructed(Box<ValidatedIncrementalMerkleTreeV1<'static>>),
    /// The exact program-owned PDA image was parsed canonically and its tree
    /// relation is carried by the Pool program's inductive write invariant.
    /// Only the prepared-settlement path may mint this cheaper capability.
    ProgramInvariant,
}

impl CanonicalPoolStateV1 {
    pub(crate) fn decode_account(
        program_id: &Pubkey,
        pool_account: &solana_program::account_info::AccountInfo<'_>,
    ) -> Result<Self, ProgramError> {
        require_program_account(pool_account, program_id, true)?;
        if pool_account.is_signer {
            return Err(ProgramError::InvalidAccountData);
        }
        let (state, validated_tree) = PoolStateV1::decode_boxed_with_validated_tree(
            &pool_account.try_borrow_data()?,
            pool_account.key,
        )?;
        let mint = Pubkey::new_from_array(state.identity.asset_mint);
        if pool_account.key != &pool_v1_state_address(program_id, &mint).0 {
            return Err(PoolV1ProgramError::InvalidPoolStateAddress.into());
        }
        Ok(Self {
            program_id: *program_id,
            pool: *pool_account.key,
            state,
            tree_evidence: CanonicalTreeEvidenceV1::Reconstructed(validated_tree),
        })
    }

    /// Decode a live Pool-owned state under the program's inductive tree
    /// invariant, without recomputing its already-persisted depth-20 root.
    ///
    /// This remains fail-closed on account ownership, signer/writable shape,
    /// canonical PDA, every byte-level format rule, field canonicality,
    /// cursor metadata, inactive frontier slots, and the unique genesis
    /// image. The omitted relation is exactly the invariant established by
    /// initialization and preserved by every successful Pool state write.
    pub(crate) fn decode_account_from_program_invariant(
        program_id: &Pubkey,
        pool_account: &solana_program::account_info::AccountInfo<'_>,
    ) -> Result<Self, ProgramError> {
        require_program_account(pool_account, program_id, true)?;
        if pool_account.is_signer {
            return Err(ProgramError::InvalidAccountData);
        }
        let state = PoolStateV1::decode_boxed_from_program_invariant(
            &pool_account.try_borrow_data()?,
            pool_account.key,
        )?;
        let mint = Pubkey::new_from_array(state.identity.asset_mint);
        if pool_account.key != &pool_v1_state_address(program_id, &mint).0 {
            return Err(PoolV1ProgramError::InvalidPoolStateAddress.into());
        }
        Ok(Self {
            program_id: *program_id,
            pool: *pool_account.key,
            state,
            tree_evidence: CanonicalTreeEvidenceV1::ProgramInvariant,
        })
    }

    pub(crate) fn require_same_writable_account(
        &self,
        program_id: &Pubkey,
        pool_account: &solana_program::account_info::AccountInfo<'_>,
    ) -> Result<(), ProgramError> {
        require_program_account(pool_account, program_id, true)?;
        // `decode_account` already proved that `(self.program_id, self.pool)`
        // is the canonical per-mint PDA. Exact equality with that sealed pair
        // carries the PDA proof forward without another address derivation.
        if pool_account.is_signer
            || self.program_id != *program_id
            || self.pool != *pool_account.key
            || self.state.identity.pool != pool_account.key.to_bytes()
        {
            return Err(ProgramError::InvalidAccountData);
        }
        Ok(())
    }

    pub(crate) fn as_state(&self) -> &PoolStateV1 {
        &self.state
    }

    pub(crate) fn reconstructed_tree(&self) -> Option<&ValidatedIncrementalMerkleTreeV1<'static>> {
        match &self.tree_evidence {
            CanonicalTreeEvidenceV1::Reconstructed(tree) => Some(tree),
            CanonicalTreeEvidenceV1::ProgramInvariant => None,
        }
    }
}

impl core::ops::Deref for CanonicalPoolStateV1 {
    type Target = PoolStateV1;

    fn deref(&self) -> &Self::Target {
        self.as_state()
    }
}

impl PoolStateV1 {
    pub fn genesis(
        pool: &Pubkey,
        initialization: PoolInitializationV1,
    ) -> Result<Self, ProgramError> {
        if initialization.asset_id.0 >= aspis_core::field::P {
            return Err(ProgramError::InvalidInstructionData);
        }
        if initialization.token_program != LEGACY_SPL_TOKEN_PROGRAM_ID.to_bytes() {
            return Err(PoolV1ProgramError::InvalidTokenProgram.into());
        }
        validate_verifier_policy_v1(&initialization.verifier_policy)
            .map_err(|_| ProgramError::InvalidInstructionData)?;
        // The Pool binary pins and KAT-checks this exact recursive empty-root
        // table.  Constructing sequence zero directly is therefore equivalent
        // to asking the generic tree constructor to recompute twenty
        // Poseidon parents, but avoids paying for that proof repeatedly in the
        // initialization instruction.
        let tree = IncrementalMerkleTreeV1 {
            next_leaf_index: 0,
            root: POOL_V1_EMPTY_ROOTS[POOL_V1_TREE_DEPTH],
            frontier: core::array::from_fn(|level| POOL_V1_EMPTY_ROOTS[level]),
        };
        Ok(Self {
            identity: PoolIdentityV1 {
                pool: pool.to_bytes(),
                asset_mint: initialization.asset_mint,
                token_program: initialization.token_program,
                asset_id: initialization.asset_id,
                deployment_domain: initialization.deployment_domain,
            },
            verifier_policy: initialization.verifier_policy,
            tree,
        })
    }

    pub fn current_root_sequence(&self) -> u64 {
        self.tree.next_leaf_index
    }

    /// Construct genesis state on the heap so SBF callers do not reserve the
    /// complete 1,000-byte state image in an already-busy instruction frame.
    pub(crate) fn genesis_boxed(
        pool: &Pubkey,
        initialization: PoolInitializationV1,
    ) -> Result<Box<Self>, ProgramError> {
        Ok(Box::new(Self::genesis(pool, initialization)?))
    }

    /// Decode state on the heap for the same SBF stack reason. The canonical
    /// decoder remains the only parser; this changes storage, not semantics.
    pub(crate) fn decode_boxed(
        data: &[u8],
        expected_pool: &Pubkey,
    ) -> Result<Box<Self>, ProgramError> {
        Ok(Box::new(Self::decode(data, expected_pool)?))
    }

    pub(crate) fn decode_boxed_with_validated_tree(
        data: &[u8],
        expected_pool: &Pubkey,
    ) -> Result<(Box<Self>, Box<ValidatedIncrementalMerkleTreeV1<'static>>), ProgramError> {
        let (state, validated_tree) = Self::decode_with_validated_tree(data, expected_pool)?;
        Ok((Box::new(state), Box::new(validated_tree)))
    }

    pub(crate) fn decode_boxed_from_program_invariant(
        data: &[u8],
        expected_pool: &Pubkey,
    ) -> Result<Box<Self>, ProgramError> {
        Ok(Box::new(Self::decode_from_program_invariant(
            data,
            expected_pool,
        )?))
    }

    /// Perform every fallible check required by the canonical encoder.
    /// Callers may then write through `write_encoding_prevalidated` after an
    /// irreversible CPI without introducing a new error path.
    pub(crate) fn validate_encoding(&self) -> Result<(), ProgramError> {
        if self.tree.next_leaf_index == 0 {
            // Sequence zero has one canonical image.  Exact comparison with
            // the pinned table is the fail-closed specialization of generic
            // root reconstruction for genesis; every non-genesis state still
            // takes the complete validation path below.
            if self.tree.root != POOL_V1_EMPTY_ROOTS[POOL_V1_TREE_DEPTH]
                || self
                    .tree
                    .frontier
                    .iter()
                    .enumerate()
                    .any(|(level, node)| *node != POOL_V1_EMPTY_ROOTS[level])
            {
                return Err(ProgramError::InvalidAccountData);
            }
        } else {
            self.tree
                .validate_with_empty_roots(&POOL_V1_EMPTY_ROOTS)
                .map_err(|_| ProgramError::InvalidAccountData)?;
        }
        validate_verifier_policy_v1(&self.verifier_policy)
            .map_err(|_| ProgramError::InvalidAccountData)
    }

    /// Write the exact state image after `validate_encoding` has succeeded.
    /// The fixed-size destination makes this phase infallible and avoids a
    /// second 1,000-byte stack allocation in the transition frame.
    pub(crate) fn write_encoding_prevalidated(
        &self,
        output: &mut [u8; POOL_V1_STATE_ACCOUNT_BYTES],
    ) {
        output.fill(0);
        output[..4].copy_from_slice(&POOL_V1_STATE_ACCOUNT_MAGIC);
        output[4] = POOL_V1_STATE_ACCOUNT_VERSION;
        output[5] = POOL_V1_FORMAT_VERSION;
        output[6] = POOL_V1_TREE_DEPTH as u8;
        output[7] = POOL_V1_ROOT_HISTORY_CAPACITY_LOG2;
        output[8..40].copy_from_slice(&POOL_V1_FORMAT_BINDING);
        let sequence = self.current_root_sequence();
        let location = root_history_location(sequence);
        output[STATE_SEQUENCE_OFFSET..STATE_PAGE_OFFSET].copy_from_slice(&sequence.to_le_bytes());
        output[STATE_PAGE_OFFSET..STATE_SLOT_OFFSET]
            .copy_from_slice(&location.page_number.to_le_bytes());
        output[STATE_SLOT_OFFSET..58].copy_from_slice(&location.slot.to_le_bytes());

        let identity = encode_pool_identity_v1(&self.identity);
        output[POOL_V1_STATE_IDENTITY_OFFSET..POOL_V1_STATE_POLICY_OFFSET]
            .copy_from_slice(&identity);
        let policy = &mut output[POOL_V1_STATE_POLICY_OFFSET..POOL_V1_STATE_TREE_OFFSET];
        policy[..4].copy_from_slice(&POOL_V1_VERIFIER_POLICY_MAGIC);
        policy[4] = POOL_V1_VERIFIER_POLICY_VERSION;
        policy[5] = self.verifier_policy.flags;
        policy[8..40].copy_from_slice(&self.verifier_policy.registry_program);
        policy[40..72].copy_from_slice(&self.verifier_policy.registry_authority);
        policy[72..104].copy_from_slice(&self.verifier_policy.policy_binding);

        let tree = &mut output[POOL_V1_STATE_TREE_OFFSET..];
        tree[..4].copy_from_slice(&POOL_V1_TREE_STATE_MAGIC);
        tree[4] = POOL_V1_TREE_STATE_VERSION;
        tree[5] = POOL_V1_TREE_DEPTH as u8;
        tree[6] = POOL_V1_TREE_HASH_VERSION;
        tree[7] = aspis_statement::pool_v1::POOL_V1_DIGEST_ENCODING_VERSION;
        tree[8..16].copy_from_slice(&self.tree.next_leaf_index.to_le_bytes());
        tree[16..48].copy_from_slice(&aspis_statement::encode_digest_canonical(&self.tree.root));
        for (level, node) in self.tree.frontier.iter().enumerate() {
            let start = 48 + level * 32;
            tree[start..start + 32]
                .copy_from_slice(&aspis_statement::encode_digest_canonical(node));
        }
    }

    #[inline(never)]
    pub fn encode(&self) -> Result<[u8; POOL_V1_STATE_ACCOUNT_BYTES], ProgramError> {
        self.validate_encoding()?;
        let mut output = [0u8; POOL_V1_STATE_ACCOUNT_BYTES];
        self.write_encoding_prevalidated(&mut output);
        Ok(output)
    }

    fn decode_with_validated_tree(
        data: &[u8],
        expected_pool: &Pubkey,
    ) -> Result<(Self, ValidatedIncrementalMerkleTreeV1<'static>), ProgramError> {
        if data.len() != POOL_V1_STATE_ACCOUNT_BYTES
            || data[..4] != POOL_V1_STATE_ACCOUNT_MAGIC
            || data[4] != POOL_V1_STATE_ACCOUNT_VERSION
            || data[5] != POOL_V1_FORMAT_VERSION
            || data[6] != POOL_V1_TREE_DEPTH as u8
            || data[7] != POOL_V1_ROOT_HISTORY_CAPACITY_LOG2
            || data[8..40] != POOL_V1_FORMAT_BINDING
            || data[58..64] != [0u8; 6]
        {
            return Err(PoolV1ProgramError::InvalidAccountType.into());
        }
        let identity = decode_pool_identity_v1(
            &data[POOL_V1_STATE_IDENTITY_OFFSET..POOL_V1_STATE_POLICY_OFFSET],
        )
        .map_err(|_| ProgramError::InvalidAccountData)?;
        if identity.pool != expected_pool.to_bytes() {
            return Err(PoolV1ProgramError::StateHistoryMismatch.into());
        }
        let verifier_policy = decode_verifier_policy_v1(
            &data[POOL_V1_STATE_POLICY_OFFSET..POOL_V1_STATE_TREE_OFFSET],
        )
        .map_err(|_| ProgramError::InvalidAccountData)?;
        let validated_tree = ValidatedIncrementalMerkleTreeV1::decode(
            &data[POOL_V1_STATE_TREE_OFFSET..],
            &POOL_V1_EMPTY_ROOTS,
        )
        .map_err(|_| ProgramError::InvalidAccountData)?;
        let tree = *validated_tree.as_tree();
        let sequence = u64::from_le_bytes(exact_state_array(
            &data[STATE_SEQUENCE_OFFSET..STATE_PAGE_OFFSET],
        )?);
        let page_number = u64::from_le_bytes(exact_state_array(
            &data[STATE_PAGE_OFFSET..STATE_SLOT_OFFSET],
        )?);
        let slot = u16::from_le_bytes(exact_state_array(&data[STATE_SLOT_OFFSET..58])?);
        let expected_location = root_history_location(tree.next_leaf_index);
        if sequence != tree.next_leaf_index
            || page_number != expected_location.page_number
            || slot != expected_location.slot
        {
            return Err(PoolV1ProgramError::StateHistoryMismatch.into());
        }
        Ok((
            Self {
                identity,
                verifier_policy,
                tree,
            },
            validated_tree,
        ))
    }

    fn decode_from_program_invariant(
        data: &[u8],
        expected_pool: &Pubkey,
    ) -> Result<Self, ProgramError> {
        if data.len() != POOL_V1_STATE_ACCOUNT_BYTES
            || data[..4] != POOL_V1_STATE_ACCOUNT_MAGIC
            || data[4] != POOL_V1_STATE_ACCOUNT_VERSION
            || data[5] != POOL_V1_FORMAT_VERSION
            || data[6] != POOL_V1_TREE_DEPTH as u8
            || data[7] != POOL_V1_ROOT_HISTORY_CAPACITY_LOG2
            || data[8..40] != POOL_V1_FORMAT_BINDING
            || data[58..64] != [0u8; 6]
        {
            return Err(PoolV1ProgramError::InvalidAccountType.into());
        }
        let identity = decode_pool_identity_v1(
            &data[POOL_V1_STATE_IDENTITY_OFFSET..POOL_V1_STATE_POLICY_OFFSET],
        )
        .map_err(|_| ProgramError::InvalidAccountData)?;
        if identity.pool != expected_pool.to_bytes() {
            return Err(PoolV1ProgramError::StateHistoryMismatch.into());
        }
        let verifier_policy = decode_verifier_policy_v1(
            &data[POOL_V1_STATE_POLICY_OFFSET..POOL_V1_STATE_TREE_OFFSET],
        )
        .map_err(|_| ProgramError::InvalidAccountData)?;
        let tree_bytes = &data[POOL_V1_STATE_TREE_OFFSET..];
        if tree_bytes.len() != POOL_V1_TREE_STATE_ACCOUNT_BYTES
            || tree_bytes[..4] != POOL_V1_TREE_STATE_MAGIC
            || tree_bytes[4] != POOL_V1_TREE_STATE_VERSION
            || tree_bytes[5] != POOL_V1_TREE_DEPTH as u8
            || tree_bytes[6] != POOL_V1_TREE_HASH_VERSION
            || tree_bytes[7] != POOL_V1_DIGEST_ENCODING_VERSION
        {
            return Err(ProgramError::InvalidAccountData);
        }
        let next_leaf_index = u64::from_le_bytes(exact_state_array(&tree_bytes[8..16])?);
        if next_leaf_index > POOL_V1_LEAF_CAPACITY {
            return Err(ProgramError::InvalidAccountData);
        }
        let root =
            aspis_statement::decode_digest_canonical(&exact_state_array(&tree_bytes[16..48])?)
                .map_err(|_| ProgramError::InvalidAccountData)?;
        let mut frontier =
            [[M31::ZERO; aspis_statement::poseidon2::DIGEST_ELEMS]; POOL_V1_TREE_DEPTH];
        for (level, node) in frontier.iter_mut().enumerate() {
            let start = 48 + level * 32;
            *node = aspis_statement::decode_digest_canonical(&exact_state_array(
                &tree_bytes[start..start + 32],
            )?)
            .map_err(|_| ProgramError::InvalidAccountData)?;
            if (next_leaf_index >> level) & 1 == 0 && *node != POOL_V1_EMPTY_ROOTS[level] {
                return Err(ProgramError::InvalidAccountData);
            }
        }
        if next_leaf_index == 0 && root != POOL_V1_EMPTY_ROOTS[POOL_V1_TREE_DEPTH] {
            return Err(ProgramError::InvalidAccountData);
        }
        let tree = IncrementalMerkleTreeV1 {
            next_leaf_index,
            root,
            frontier,
        };
        let sequence = u64::from_le_bytes(exact_state_array(
            &data[STATE_SEQUENCE_OFFSET..STATE_PAGE_OFFSET],
        )?);
        let page_number = u64::from_le_bytes(exact_state_array(
            &data[STATE_PAGE_OFFSET..STATE_SLOT_OFFSET],
        )?);
        let slot = u16::from_le_bytes(exact_state_array(&data[STATE_SLOT_OFFSET..58])?);
        let expected_location = root_history_location(tree.next_leaf_index);
        if sequence != tree.next_leaf_index
            || page_number != expected_location.page_number
            || slot != expected_location.slot
        {
            return Err(PoolV1ProgramError::StateHistoryMismatch.into());
        }
        Ok(Self {
            identity,
            verifier_policy,
            tree,
        })
    }

    pub fn decode(data: &[u8], expected_pool: &Pubkey) -> Result<Self, ProgramError> {
        Self::decode_with_validated_tree(data, expected_pool).map(|(state, _)| state)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn digest(seed: u32) -> aspis_statement::poseidon2::Digest {
        core::array::from_fn(|index| M31(seed + 101 * index as u32))
    }

    fn initialization() -> PoolInitializationV1 {
        PoolInitializationV1 {
            asset_mint: [2u8; 32],
            token_program: LEGACY_SPL_TOKEN_PROGRAM_ID.to_bytes(),
            asset_id: M31(4),
            deployment_domain: [5u8; 32],
            verifier_policy: VerifierPolicyV1 {
                flags: 0,
                registry_program: [6u8; 32],
                registry_authority: [7u8; 32],
                policy_binding: [8u8; 32],
            },
        }
    }

    #[test]
    fn exact_state_image_roundtrips_and_rejects_type_reserved_cursor_and_pool_confusion() {
        let pool = Pubkey::new_unique();
        let state = PoolStateV1::genesis(&pool, initialization()).unwrap();
        let encoded = state.encode().unwrap();
        assert_eq!(encoded.len(), 1_000);
        assert_eq!(
            &encoded[POOL_V1_STATE_IDENTITY_OFFSET..POOL_V1_STATE_POLICY_OFFSET],
            &aspis_statement::pool_v1::encode_pool_identity_v1(&state.identity)
        );
        assert_eq!(
            &encoded[POOL_V1_STATE_POLICY_OFFSET..POOL_V1_STATE_TREE_OFFSET],
            &aspis_statement::pool_v1::encode_verifier_policy_v1(&state.verifier_policy).unwrap()
        );
        assert_eq!(
            &encoded[POOL_V1_STATE_TREE_OFFSET..],
            &state
                .tree
                .encode_with_empty_roots(&POOL_V1_EMPTY_ROOTS)
                .unwrap()
        );
        assert_eq!(PoolStateV1::decode(&encoded, &pool), Ok(state));

        let mut wrong_version = encoded;
        wrong_version[4] = 1;
        assert_eq!(
            PoolStateV1::decode(&wrong_version, &pool),
            Err(PoolV1ProgramError::InvalidAccountType.into())
        );

        let mut reserved = encoded;
        reserved[63] = 1;
        assert_eq!(
            PoolStateV1::decode(&reserved, &pool),
            Err(PoolV1ProgramError::InvalidAccountType.into())
        );

        let mut cursor = encoded;
        cursor[STATE_SEQUENCE_OFFSET] = 1;
        assert_eq!(
            PoolStateV1::decode(&cursor, &pool),
            Err(PoolV1ProgramError::StateHistoryMismatch.into())
        );

        assert_eq!(
            PoolStateV1::decode(&encoded, &Pubkey::new_unique()),
            Err(PoolV1ProgramError::StateHistoryMismatch.into())
        );

        assert_eq!(
            PoolStateV1::genesis(
                &pool,
                PoolInitializationV1 {
                    token_program: [3u8; 32],
                    ..initialization()
                }
            ),
            Err(PoolV1ProgramError::InvalidTokenProgram.into())
        );
    }

    #[test]
    fn specialized_genesis_is_exactly_the_generic_checked_tree_and_fails_closed() {
        let pool = Pubkey::new_unique();
        let state = PoolStateV1::genesis(&pool, initialization()).unwrap();
        let checked_tree = IncrementalMerkleTreeV1::from_parts_with_empty_roots(
            0,
            POOL_V1_EMPTY_ROOTS[POOL_V1_TREE_DEPTH],
            core::array::from_fn(|level| POOL_V1_EMPTY_ROOTS[level]),
            &POOL_V1_EMPTY_ROOTS,
        )
        .unwrap();
        assert_eq!(state.tree, checked_tree);
        assert_eq!(state.validate_encoding(), Ok(()));

        let mut corrupt_root = state;
        corrupt_root.tree.root[0] = M31(1);
        assert_eq!(
            corrupt_root.validate_encoding(),
            Err(ProgramError::InvalidAccountData)
        );

        let mut corrupt_frontier = state;
        corrupt_frontier.tree.frontier[7][3] = M31(1);
        assert_eq!(
            corrupt_frontier.validate_encoding(),
            Err(ProgramError::InvalidAccountData)
        );
    }

    #[test]
    fn program_invariant_decoder_has_one_explicit_relation_boundary() {
        let pool = Pubkey::new_unique();
        let mut state = PoolStateV1::genesis(&pool, initialization()).unwrap();
        state.tree = state
            .tree
            .append_two_with_empty_roots(digest(100), digest(200), &POOL_V1_EMPTY_ROOTS)
            .unwrap()
            .0;
        let encoded = state.encode().unwrap();
        assert_eq!(
            PoolStateV1::decode_from_program_invariant(&encoded, &pool),
            Ok(state)
        );

        // The cheaper decoder deliberately does not re-prove the active
        // frontier/root relation. That relation is the named inductive Pool
        // write invariant; the generic decoder still rejects its mutation.
        let mut wrong_root = state;
        wrong_root.tree.root = digest(300);
        let mut wrong_root_image = [0u8; POOL_V1_STATE_ACCOUNT_BYTES];
        wrong_root.write_encoding_prevalidated(&mut wrong_root_image);
        assert_eq!(
            PoolStateV1::decode(&wrong_root_image, &pool),
            Err(ProgramError::InvalidAccountData)
        );
        assert_eq!(
            PoolStateV1::decode_from_program_invariant(&wrong_root_image, &pool),
            Ok(wrong_root)
        );

        // Everything outside that single relation remains fail-closed. At
        // sequence two, level zero is inactive and must be the pinned empty.
        let mut wrong_inactive = state;
        wrong_inactive.tree.frontier[0] = digest(400);
        let mut wrong_inactive_image = [0u8; POOL_V1_STATE_ACCOUNT_BYTES];
        wrong_inactive.write_encoding_prevalidated(&mut wrong_inactive_image);
        assert_eq!(
            PoolStateV1::decode_from_program_invariant(&wrong_inactive_image, &pool),
            Err(ProgramError::InvalidAccountData)
        );

        let mut wrong_cursor = encoded;
        wrong_cursor[STATE_SEQUENCE_OFFSET] ^= 1;
        assert_eq!(
            PoolStateV1::decode_from_program_invariant(&wrong_cursor, &pool),
            Err(PoolV1ProgramError::StateHistoryMismatch.into())
        );
    }
}

programs/aspis-pool/src/transition.rs:
//! Authenticated initialization and internal atomic tree/history transitions.
//!
//! There is deliberately no public raw-append API. The native instruction
//! processor calls these crate-private functions only after backing or proof
//! authorization has succeeded.

extern crate alloc;

use alloc::boxed::Box;

use aspis_core::field::M31;
#[cfg(test)]
use aspis_statement::pool_v1::POOL_V1_ROOT_HISTORY_PAGE_ACCOUNT_BYTES;
use aspis_statement::{
    pool_v1::{
        pool_v1_tree_parent, root_history_location, AppendOneV1, IncrementalMerkleTreeV1,
        PoolV1TreeError, POOL_V1_LEAF_CAPACITY, POOL_V1_ROOT_HISTORY_CAPACITY,
    },
    poseidon2::{Digest, DIGEST_ELEMS},
};
use solana_program::{account_info::AccountInfo, program_error::ProgramError, pubkey::Pubkey};

use crate::{
    anchor::PrevalidatedHistoricalAnchorV1,
    empty_roots::POOL_V1_EMPTY_ROOTS,
    error::PoolV1ProgramError,
    history::{
        append_roots_unchecked, digest_is_canonical, read_retained_root, require_program_account,
        require_program_owned, require_root_page_address, validate_new_page_account,
        validate_root_page_bytes, write_new_page_unchecked, RootPageHeaderV1,
    },
    state::{
        pool_v1_state_address, CanonicalPoolStateV1, PoolInitializationV1, PoolStateV1,
        POOL_V1_STATE_ACCOUNT_BYTES,
    },
};

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum AuthorizedAppendV1 {
    One(Digest),
    Two(Digest, Digest),
}

impl AuthorizedAppendV1 {
    pub(crate) fn count(self) -> u64 {
        match self {
            Self::One(_) => 1,
            Self::Two(_, _) => 2,
        }
    }

    pub(crate) fn validate_leaves(self) -> Result<(), ProgramError> {
        let valid = match self {
            Self::One(leaf) => digest_is_canonical(&leaf),
            Self::Two(first, second) => digest_is_canonical(&first) && digest_is_canonical(&second),
        };
        if !valid {
            return Err(PoolV1ProgramError::NonCanonicalLeaf.into());
        }
        Ok(())
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) struct AuthorizedAppendReceiptV1 {
    pub first: AppendOneV1,
    pub second: Option<AppendOneV1>,
}

/// Sealed evidence that the current root-history page passed one complete
/// canonical validation for one exact Pool state.  It can only be created
/// before verifier dispatch, while the Pool/current-page accounts are not
/// exposed to any CPI, and is identity-bound again at append consumption.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) struct PrevalidatedCurrentHistoryV1 {
    program_id: Pubkey,
    pool: Pubkey,
    history_page: Pubkey,
    sequence: u64,
    root: Digest,
    header: RootPageHeaderV1,
}

/// Sealed evidence that one exact rollover history PDA is the required
/// all-zero, rent-exempt Pool-owned page. The preparation processor creates or
/// validates it once and performs no intervening CPI before plan construction.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) struct PrevalidatedNewHistoryPageV1 {
    program_id: Pubkey,
    pool: Pubkey,
    page: Pubkey,
    page_number: u64,
}

impl PrevalidatedNewHistoryPageV1 {
    pub(crate) fn require_matches(
        self,
        program_id: &Pubkey,
        pool: &Pubkey,
        page_number: u64,
        page: &AccountInfo<'_>,
    ) -> Result<(), ProgramError> {
        if self.program_id != *program_id
            || self.pool != *pool
            || self.page != *page.key
            || self.page_number != page_number
        {
            return Err(PoolV1ProgramError::StateHistoryMismatch.into());
        }
        Ok(())
    }
}

pub(crate) fn prevalidate_new_history_page_v1(
    program_id: &Pubkey,
    pool: &Pubkey,
    page_number: u64,
    page: &AccountInfo<'_>,
) -> Result<PrevalidatedNewHistoryPageV1, ProgramError> {
    validate_new_page_account(program_id, pool, page_number, page)?;
    Ok(PrevalidatedNewHistoryPageV1 {
        program_id: *program_id,
        pool: *pool,
        page: *page.key,
        page_number,
    })
}

impl PrevalidatedCurrentHistoryV1 {
    pub(crate) fn require_matches(
        self,
        program_id: &Pubkey,
        pool_account: &AccountInfo,
        history_account: &AccountInfo,
        state: &PoolStateV1,
    ) -> Result<RootPageHeaderV1, ProgramError> {
        require_program_owned(history_account, program_id)?;
        let location = root_history_location(state.current_root_sequence());
        require_root_page_address(
            program_id,
            pool_account.key,
            location.page_number,
            history_account,
        )?;
        if self.program_id != *program_id
            || self.pool != *pool_account.key
            || self.history_page != *history_account.key
            || self.sequence != state.current_root_sequence()
            || self.root != state.tree.root
            || self.header.pool != *pool_account.key
            || self.header.page_number != location.page_number
            || self.header.filled != location.slot + 1
        {
            return Err(PoolV1ProgramError::StateHistoryMismatch.into());
        }
        Ok(self.header)
    }
}

/// Exact checked append output used by the prepared-settlement builder.
///
/// This capability is crate-private: the only constructor below consumes the
/// processor's sealed canonical-state token and delegates to the same checked
/// incremental-tree append used by the direct atomic path.
#[derive(Clone, Debug, PartialEq, Eq)]
pub(crate) struct PreparedAuthorizedAppendImagesV1 {
    pub next_state_image: Box<[u8; POOL_V1_STATE_ACCOUNT_BYTES]>,
    pub receipt: AuthorizedAppendReceiptV1,
}

/// A transition whose output tree was produced by the checked incremental
/// append kernel. Its fields are private so persistence cannot receive an
/// arbitrary, unchecked next-state image.
#[derive(Clone, Debug, PartialEq, Eq)]
struct PreparedAuthorizedAppendV1 {
    next_state: Box<PoolStateV1>,
    receipt: AuthorizedAppendReceiptV1,
}

#[derive(Clone, Copy)]
enum AuthorizedSourceStateV1<'a> {
    /// The processor's sealed result of one complete account decode/PDA check.
    Canonical(&'a CanonicalPoolStateV1),
    /// The compatibility wrapper's locally decoded state. This path retains
    /// its historical extra whole-state validation below.
    Standalone(&'a PoolStateV1),
}

impl<'a> AuthorizedSourceStateV1<'a> {
    fn as_state(self) -> &'a PoolStateV1 {
        match self {
            Self::Canonical(state) => state.as_state(),
            Self::Standalone(state) => state,
        }
    }

    fn prepare(
        self,
        request: AuthorizedAppendV1,
    ) -> Result<PreparedAuthorizedAppendV1, ProgramError> {
        let source = self.as_state();
        let prepared = match self {
            Self::Canonical(state) => prepare_append_from_canonical_state(state, request)?,
            Self::Standalone(_) => {
                let prepared = prepare_checked_append(source, request)?;
                prepared.next_state.validate_encoding()?;
                prepared
            }
        };
        prepared.validate_inherited_state_and_cursor(source, request)?;
        Ok(prepared)
    }
}

impl PreparedAuthorizedAppendV1 {
    /// The checked append already validates its produced tree. For a sealed
    /// canonical source, the only remaining Pool-state invariants are that
    /// immutable identity/policy fields were inherited and the exact cursor /
    /// receipt progression agrees with the requested append count.
    fn validate_inherited_state_and_cursor(
        &self,
        source: &PoolStateV1,
        request: AuthorizedAppendV1,
    ) -> Result<(), ProgramError> {
        let first_sequence = source
            .current_root_sequence()
            .checked_add(1)
            .ok_or(PoolV1ProgramError::ArithmeticOverflow)?;
        let final_sequence = source
            .current_root_sequence()
            .checked_add(request.count())
            .ok_or(PoolV1ProgramError::ArithmeticOverflow)?;
        let receipt_shape_is_exact = self.receipt.first.leaf_index
            == source.current_root_sequence()
            && self.receipt.first.root_sequence == first_sequence
            && match (request, self.receipt.second) {
                (AuthorizedAppendV1::One(_), None) => {
                    self.receipt.first.root == self.next_state.tree.root
                }
                (AuthorizedAppendV1::Two(_, _), Some(second)) => {
                    second.leaf_index == first_sequence
                        && second.root_sequence == final_sequence
                        && second.root == self.next_state.tree.root
                }
                _ => false,
            };
        if self.next_state.identity != source.identity
            || self.next_state.verifier_policy != source.verifier_policy
            || self.next_state.current_root_sequence() != final_sequence
            || !receipt_shape_is_exact
        {
            return Err(ProgramError::InvalidAccountData);
        }
        Ok(())
    }
}

fn map_tree_error(error: PoolV1TreeError) -> ProgramError {
    match error {
        PoolV1TreeError::TreeFull => PoolV1ProgramError::TreeFull.into(),
        PoolV1TreeError::InsufficientCapacity => {
            PoolV1ProgramError::InsufficientTreeCapacity.into()
        }
        _ => ProgramError::InvalidAccountData,
    }
}

#[inline(never)]
fn prepare_checked_append(
    state: &PoolStateV1,
    request: AuthorizedAppendV1,
) -> Result<PreparedAuthorizedAppendV1, ProgramError> {
    let mut next_state = Box::new(*state);
    let (tree, receipt) = match request {
        AuthorizedAppendV1::One(leaf) => {
            let (tree, receipt) = next_state
                .tree
                .append_one_with_empty_roots(leaf, &POOL_V1_EMPTY_ROOTS)
                .map_err(map_tree_error)?;
            (
                tree,
                AuthorizedAppendReceiptV1 {
                    first: receipt,
                    second: None,
                },
            )
        }
        AuthorizedAppendV1::Two(first, second) => {
            let (tree, receipts) = next_state
                .tree
                .append_two_with_empty_roots(first, second, &POOL_V1_EMPTY_ROOTS)
                .map_err(map_tree_error)?;
            (
                tree,
                AuthorizedAppendReceiptV1 {
                    first: receipts.first,
                    second: Some(receipts.second),
                },
            )
        }
    };
    next_state.tree = tree;
    Ok(PreparedAuthorizedAppendV1 {
        next_state,
        receipt,
    })
}

#[inline(never)]
fn prepare_append_from_canonical_state(
    state: &CanonicalPoolStateV1,
    request: AuthorizedAppendV1,
) -> Result<PreparedAuthorizedAppendV1, ProgramError> {
    let mut next_state = Box::new(*state.as_state());
    let (tree, receipt) = match state.reconstructed_tree() {
        Some(validated) => {
            if state.as_state().tree != *validated.as_tree() {
                return Err(ProgramError::InvalidAccountData);
            }
            match request {
                AuthorizedAppendV1::One(leaf) => {
                    let (tree, receipt) = validated.append_one(leaf).map_err(map_tree_error)?;
                    (
                        tree.into_inner(),
                        AuthorizedAppendReceiptV1 {
                            first: receipt,
                            second: None,
                        },
                    )
                }
                AuthorizedAppendV1::Two(first, second) => {
                    let (tree, receipts) = validated
                        .append_two(first, second)
                        .map_err(map_tree_error)?;
                    (
                        tree.into_inner(),
                        AuthorizedAppendReceiptV1 {
                            first: receipts.first,
                            second: Some(receipts.second),
                        },
                    )
                }
            }
        }
        None => match request {
            AuthorizedAppendV1::One(leaf) => {
                let (tree, receipt) = append_one_from_program_invariant(&state.tree, leaf)?;
                (
                    tree,
                    AuthorizedAppendReceiptV1 {
                        first: receipt,
                        second: None,
                    },
                )
            }
            AuthorizedAppendV1::Two(first, second) => {
                let (after_first, first_receipt) =
                    append_one_from_program_invariant(&state.tree, first)?;
                let (after_second, second_receipt) =
                    append_one_from_program_invariant(&after_first, second)?;
                (
                    after_second,
                    AuthorizedAppendReceiptV1 {
                        first: first_receipt,
                        second: Some(second_receipt),
                    },
                )
            }
        },
    };
    next_state.tree = tree;
    Ok(PreparedAuthorizedAppendV1 {
        next_state,
        receipt,
    })
}

/// Apply one append to a source whose complete root/frontier relation is
/// carried by the Pool program's inductive state invariant. The caller's
/// sealed account token has already checked ownership, canonical PDA, exact
/// syntax, cursor metadata, canonical field encodings, and inactive slots.
///
/// The transition below is the same binary-carry construction as
/// `ValidatedIncrementalMerkleTreeV1::append_one`. Starting reconstruction at
/// the carry level skips only recursive empty parents fixed by the pinned
/// table, keeping the number of Poseidon parents exactly equal to tree depth.
fn append_one_from_program_invariant(
    source: &IncrementalMerkleTreeV1,
    leaf: Digest,
) -> Result<(IncrementalMerkleTreeV1, AppendOneV1), ProgramError> {
    if source.next_leaf_index == POOL_V1_LEAF_CAPACITY {
        return Err(PoolV1ProgramError::TreeFull.into());
    }
    let leaf_index = source.next_leaf_index;
    let mut frontier = source.frontier;
    let mut carry = leaf;
    let mut carry_level = 0usize;
    while carry_level < aspis_statement::pool_v1::POOL_V1_TREE_DEPTH
        && (leaf_index >> carry_level) & 1 == 1
    {
        carry = pool_v1_tree_parent(&frontier[carry_level], &carry);
        frontier[carry_level] = POOL_V1_EMPTY_ROOTS[carry_level];
        carry_level += 1;
    }
    let next_leaf_index = leaf_index
        .checked_add(1)
        .ok_or(PoolV1ProgramError::ArithmeticOverflow)?;
    let root = if carry_level == aspis_statement::pool_v1::POOL_V1_TREE_DEPTH {
        carry
    } else {
        frontier[carry_level] = carry;
        let mut node = POOL_V1_EMPTY_ROOTS[carry_level];
        for level in carry_level..aspis_statement::pool_v1::POOL_V1_TREE_DEPTH {
            node = if (next_leaf_index >> level) & 1 == 0 {
                pool_v1_tree_parent(&node, &POOL_V1_EMPTY_ROOTS[level])
            } else {
                pool_v1_tree_parent(&frontier[level], &node)
            };
        }
        node
    };
    let next = IncrementalMerkleTreeV1 {
        next_leaf_index,
        root,
        frontier,
    };
    let receipt = AppendOneV1 {
        leaf_index,
        root_sequence: next_leaf_index,
        root,
        history: root_history_location(next_leaf_index),
    };
    Ok((next, receipt))
}

/// Produce the exact next Pool image and append receipts from one already
/// validated state. Poseidon is intentionally confined to this preparation
/// function; the later prepared-settlement apply gate consumes only bytes,
/// SHA-256 bindings and the checked receipts returned here.
pub(crate) fn prepare_authorized_append_images_v1(
    state: &CanonicalPoolStateV1,
    request: AuthorizedAppendV1,
) -> Result<PreparedAuthorizedAppendImagesV1, ProgramError> {
    request.validate_leaves()?;
    let prepared = AuthorizedSourceStateV1::Canonical(state).prepare(request)?;
    let image: Box<[u8]> = alloc::vec![0u8; POOL_V1_STATE_ACCOUNT_BYTES].into_boxed_slice();
    let mut image: Box<[u8; POOL_V1_STATE_ACCOUNT_BYTES]> = image
        .try_into()
        .map_err(|_| ProgramError::InvalidAccountData)?;
    prepared.next_state.write_encoding_prevalidated(&mut image);
    Ok(PreparedAuthorizedAppendImagesV1 {
        next_state_image: image,
        receipt: prepared.receipt,
    })
}

pub(crate) fn validate_current_history(
    program_id: &Pubkey,
    pool_account: &AccountInfo,
    history_account: &AccountInfo,
    state: &PoolStateV1,
) -> Result<RootPageHeaderV1, ProgramError> {
    let sequence = state.current_root_sequence();
    let location = root_history_location(sequence);
    require_program_owned(history_account, program_id)?;
    require_root_page_address(
        program_id,
        pool_account.key,
        location.page_number,
        history_account,
    )?;
    let data = history_account.try_borrow_data()?;
    let header = validate_root_page_bytes(&data, pool_account.key, location.page_number)?;
    if header.filled != location.slot + 1 {
        return Err(PoolV1ProgramError::StateHistoryMismatch.into());
    }
    let retained = read_retained_root(&data, header, sequence)?;
    if retained != state.tree.root {
        return Err(PoolV1ProgramError::StateHistoryMismatch.into());
    }
    if sequence == POOL_V1_LEAF_CAPACITY {
        state
            .tree
            .validate_terminal_root_against_history_with_empty_roots(
                &retained,
                &POOL_V1_EMPTY_ROOTS,
            )
            .map_err(map_tree_error)?;
    }
    Ok(header)
}

/// Validate the current page exactly once after historical-anchor
/// authentication.  When the anchor and current root live in the same page,
/// reuse the anchor's sealed full-page validation and re-read only the exact
/// current root.  Distinct historical/current pages retain one complete
/// validation each.
pub(crate) fn validate_current_history_after_prevalidated_anchor_v1(
    program_id: &Pubkey,
    pool_account: &AccountInfo,
    history_account: &AccountInfo,
    state: &CanonicalPoolStateV1,
    anchor: PrevalidatedHistoricalAnchorV1,
) -> Result<PrevalidatedCurrentHistoryV1, ProgramError> {
    state.require_same_writable_account(program_id, pool_account)?;
    let sequence = state.current_root_sequence();
    let location = root_history_location(sequence);
    let authenticated = anchor.authenticated();
    if authenticated.pool != pool_account.key.to_bytes()
        || authenticated.pool != state.identity.pool
        || authenticated.anchor_sequence > sequence
    {
        return Err(PoolV1ProgramError::StateHistoryMismatch.into());
    }

    let header = if anchor.history_page() == *history_account.key
        && anchor.header().page_number == location.page_number
    {
        require_program_owned(history_account, program_id)?;
        require_root_page_address(
            program_id,
            pool_account.key,
            location.page_number,
            history_account,
        )?;
        let header = anchor.header();
        if header.pool != *pool_account.key || header.filled != location.slot + 1 {
            return Err(PoolV1ProgramError::StateHistoryMismatch.into());
        }
        let data = history_account.try_borrow_data()?;
        let retained = read_retained_root(&data, header, sequence)?;
        if retained != state.tree.root {
            return Err(PoolV1ProgramError::StateHistoryMismatch.into());
        }
        if sequence == POOL_V1_LEAF_CAPACITY {
            state
                .tree
                .validate_terminal_root_against_history_with_empty_roots(
                    &retained,
                    &POOL_V1_EMPTY_ROOTS,
                )
                .map_err(map_tree_error)?;
        }
        header
    } else {
        validate_current_history(program_id, pool_account, history_account, state.as_state())?
    };

    Ok(PrevalidatedCurrentHistoryV1 {
        program_id: *program_id,
        pool: *pool_account.key,
        history_page: *history_account.key,
        sequence,
        root: state.tree.root,
        header,
    })
}

/// Initialize exactly `[pool_state, root_page_0]`.
///
/// The pool account must be the writable canonical per-mint Pool V1 PDA,
/// already owned by this Pool program. It need not be a transaction signer:
/// the entrypoint initializer creates it with `invoke_signed`. The page must
/// be the canonical writable page-zero PDA. Both accounts must have their
/// exact lengths and contain only zero bytes. This kernel performs no
/// system-program CPI.
pub(crate) fn initialize_pool_accounts_v1(
    program_id: &Pubkey,
    accounts: &[AccountInfo],
    initialization: PoolInitializationV1,
) -> Result<(), ProgramError> {
    let [pool_account, page_zero_account] = accounts else {
        return Err(ProgramError::NotEnoughAccountKeys);
    };
    require_program_account(pool_account, program_id, true)?;
    let asset_mint = Pubkey::new_from_array(initialization.asset_mint);
    if pool_account.key != &pool_v1_state_address(program_id, &asset_mint).0 {
        return Err(PoolV1ProgramError::InvalidPoolStateAddress.into());
    }
    validate_new_page_account(program_id, pool_account.key, 0, page_zero_account)?;
    if pool_account.key == page_zero_account.key {
        return Err(ProgramError::InvalidAccountData);
    }
    {
        let pool_data = pool_account.try_borrow_data()?;
        if pool_data.len() != POOL_V1_STATE_ACCOUNT_BYTES || pool_data.iter().any(|byte| *byte != 0)
        {
            return Err(ProgramError::InvalidAccountData);
        }
    }
    let state = PoolStateV1::genesis_boxed(pool_account.key, initialization)?;
    state.validate_encoding()?;

    // Acquire every mutable borrow before the first write. Borrow failure
    // therefore cannot leave a partially initialized account pair.
    let mut pool_data = pool_account.try_borrow_mut_data()?;
    let pool_image: &mut [u8; POOL_V1_STATE_ACCOUNT_BYTES] = (&mut **pool_data)
        .try_into()
        .map_err(|_| ProgramError::InvalidAccountData)?;
    let mut page_data = page_zero_account.try_borrow_mut_data()?;
    state.write_encoding_prevalidated(pool_image);
    write_new_page_unchecked(
        &mut page_data,
        pool_account.key,
        0,
        0,
        &[POOL_V1_EMPTY_ROOTS[aspis_statement::pool_v1::POOL_V1_TREE_DEPTH]],
    );
    Ok(())
}

/// Apply an already-authorized append to exactly the required accounts.
///
/// Account order is `[pool_state, current_root_page]` without rollover and
/// `[pool_state, current_root_page, zeroed_next_root_page]` with rollover.
/// This function is crate-private and is reachable only after the entrypoint's
/// deposit/proof/vault authorization path has completed its preflight.
#[allow(clippy::too_many_arguments)]
#[inline(never)]
fn apply_authorized_append_after_checked_state_v1<F>(
    program_id: &Pubkey,
    pool_account: &AccountInfo,
    current_page_account: &AccountInfo,
    supplied_next_page: Option<&AccountInfo>,
    source: AuthorizedSourceStateV1<'_>,
    prevalidated_history: Option<PrevalidatedCurrentHistoryV1>,
    request: AuthorizedAppendV1,
    before_persist: F,
) -> Result<AuthorizedAppendReceiptV1, ProgramError>
where
    F: FnOnce() -> Result<(), ProgramError>,
{
    let state = source.as_state();
    let current_header = match prevalidated_history {
        Some(history) => {
            history.require_matches(program_id, pool_account, current_page_account, state)?
        }
        None => validate_current_history(program_id, pool_account, current_page_account, state)?,
    };

    let count = request.count();
    let remaining = POOL_V1_LEAF_CAPACITY
        .checked_sub(state.current_root_sequence())
        .ok_or(PoolV1ProgramError::StateHistoryMismatch)?;
    if remaining == 0 {
        return Err(PoolV1ProgramError::TreeFull.into());
    }
    if remaining < count {
        return Err(PoolV1ProgramError::InsufficientTreeCapacity.into());
    }

    let first_location = root_history_location(state.current_root_sequence() + 1);
    let last_location = root_history_location(state.current_root_sequence() + count);
    let current_page_number = current_header.page_number;
    if first_location.page_number < current_page_number
        || last_location.page_number > current_page_number + 1
    {
        return Err(PoolV1ProgramError::StateHistoryMismatch.into());
    }
    let roots_in_current = if first_location.page_number == current_page_number {
        if last_location.page_number == current_page_number {
            count as usize
        } else {
            1
        }
    } else {
        0
    };
    let roots_in_next = count as usize - roots_in_current;
    let mutate_current = roots_in_current != 0;
    if current_page_account.is_writable != mutate_current {
        return Err(ProgramError::InvalidAccountData);
    }
    let next_page = match (roots_in_next != 0, supplied_next_page) {
        (false, None) => None,
        (true, Some(next)) => {
            let next_page_number = current_page_number
                .checked_add(1)
                .ok_or(PoolV1ProgramError::ArithmeticOverflow)?;
            let first_sequence = next_page_number
                .checked_mul(POOL_V1_ROOT_HISTORY_CAPACITY as u64)
                .ok_or(PoolV1ProgramError::ArithmeticOverflow)?;
            validate_new_page_account(program_id, pool_account.key, next_page_number, next)?;
            if next.key == pool_account.key || next.key == current_page_account.key {
                return Err(ProgramError::InvalidAccountData);
            }
            Some((next, next_page_number, first_sequence))
        }
        _ => return Err(PoolV1ProgramError::UnexpectedRootPage.into()),
    };
    let next_page_metadata =
        next_page.map(|(_, page_number, first_sequence)| (page_number, first_sequence));
    if pool_account.key == current_page_account.key {
        return Err(ProgramError::InvalidAccountData);
    }

    let plan = source.prepare(request)?;
    let mut current_roots = [[M31::ZERO; DIGEST_ELEMS]; 2];
    let mut next_roots = [[M31::ZERO; DIGEST_ELEMS]; 2];
    let first = plan.receipt.first.root;
    let second = plan.receipt.second.map(|receipt| receipt.root);
    if roots_in_current == 0 {
        next_roots[0] = first;
        if let Some(root) = second {
            next_roots[1] = root;
        }
    } else {
        current_roots[0] = first;
        if roots_in_current == 2 {
            current_roots[1] = second.ok_or(ProgramError::InvalidAccountData)?;
        } else if let Some(root) = second {
            next_roots[0] = root;
        }
    }
    if usize::from(current_header.filled) + roots_in_current > POOL_V1_ROOT_HISTORY_CAPACITY {
        return Err(PoolV1ProgramError::StateHistoryMismatch.into());
    }
    // Acquire every mutable Pool-state borrow before the backing or proof
    // action. A deposit uses `before_persist` for its token CPI and exact
    // post-CPI balance-delta check. If it fails, no Pool bytes have changed;
    // if it succeeds, persistence below contains no fallible operation.
    let mut pool_data = pool_account.try_borrow_mut_data()?;
    let pool_image: &mut [u8; POOL_V1_STATE_ACCOUNT_BYTES] = (&mut **pool_data)
        .try_into()
        .map_err(|_| ProgramError::InvalidAccountData)?;
    let mut current_data = if mutate_current {
        Some(current_page_account.try_borrow_mut_data()?)
    } else {
        None
    };
    let mut next_data = match next_page {
        Some((next, _, _)) => Some(next.try_borrow_mut_data()?),
        None => None,
    };
    before_persist()?;
    plan.next_state.write_encoding_prevalidated(pool_image);
    if let Some(data) = current_data.as_mut() {
        append_roots_unchecked(data, current_header, &current_roots[..roots_in_current]);
    }
    if let (Some(data), Some((page_number, first_sequence))) =
        (next_data.as_mut(), next_page_metadata)
    {
        write_new_page_unchecked(
            data,
            pool_account.key,
            page_number,
            first_sequence,
            &next_roots[..roots_in_next],
        );
    }
    Ok(plan.receipt)
}

/// Apply an append using the processor's one canonical decoded-state token.
/// Account/PDA identity and leaf canonicality are re-checked, but the Pool
/// image and depth-20 root are not decoded or reconstructed again.
#[inline(never)]
pub(crate) fn apply_authorized_append_after_prevalidated_v1<F>(
    program_id: &Pubkey,
    accounts: &[AccountInfo],
    state: &CanonicalPoolStateV1,
    request: AuthorizedAppendV1,
    before_persist: F,
) -> Result<AuthorizedAppendReceiptV1, ProgramError>
where
    F: FnOnce() -> Result<(), ProgramError>,
{
    let (pool_account, current_page_account, supplied_next_page) = match accounts {
        [pool, current] => (pool, current, None),
        [pool, current, next] => (pool, current, Some(next)),
        _ => return Err(ProgramError::NotEnoughAccountKeys),
    };
    state.require_same_writable_account(program_id, pool_account)?;
    request.validate_leaves()?;
    apply_authorized_append_after_checked_state_v1(
        program_id,
        pool_account,
        current_page_account,
        supplied_next_page,
        AuthorizedSourceStateV1::Canonical(state),
        None,
        request,
        before_persist,
    )
}

/// Consume both the processor's sealed Pool decode and its sealed current-page
/// validation.  No intervening CPI receives either account, so this skips
/// only a duplicate full-page scan while retaining cheap identity binding.
#[inline(never)]
pub(crate) fn apply_authorized_append_after_prevalidated_history_v1<F>(
    program_id: &Pubkey,
    accounts: &[AccountInfo],
    state: &CanonicalPoolStateV1,
    history: PrevalidatedCurrentHistoryV1,
    request: AuthorizedAppendV1,
    before_persist: F,
) -> Result<AuthorizedAppendReceiptV1, ProgramError>
where
    F: FnOnce() -> Result<(), ProgramError>,
{
    let (pool_account, current_page_account, supplied_next_page) = match accounts {
        [pool, current] => (pool, current, None),
        [pool, current, next] => (pool, current, Some(next)),
        _ => return Err(ProgramError::NotEnoughAccountKeys),
    };
    state.require_same_writable_account(program_id, pool_account)?;
    request.validate_leaves()?;
    apply_authorized_append_after_checked_state_v1(
        program_id,
        pool_account,
        current_page_account,
        supplied_next_page,
        AuthorizedSourceStateV1::Canonical(state),
        Some(history),
        request,
        before_persist,
    )
}

#[inline(never)]
pub(crate) fn apply_authorized_append_after_v1<F>(
    program_id: &Pubkey,
    accounts: &[AccountInfo],
    request: AuthorizedAppendV1,
    before_persist: F,
) -> Result<AuthorizedAppendReceiptV1, ProgramError>
where
    F: FnOnce() -> Result<(), ProgramError>,
{
    let (pool_account, current_page_account, supplied_next_page) = match accounts {
        [pool, current] => (pool, current, None),
        [pool, current, next] => (pool, current, Some(next)),
        _ => return Err(ProgramError::NotEnoughAccountKeys),
    };
    require_program_account(pool_account, program_id, true)?;
    request.validate_leaves()?;
    let state = {
        let data = pool_account.try_borrow_data()?;
        PoolStateV1::decode_boxed(&data, pool_account.key)?
    };
    let asset_mint = Pubkey::new_from_array(state.identity.asset_mint);
    if pool_account.key != &pool_v1_state_address(program_id, &asset_mint).0 {
        return Err(PoolV1ProgramError::InvalidPoolStateAddress.into());
    }
    apply_authorized_append_after_checked_state_v1(
        program_id,
        pool_account,
        current_page_account,
        supplied_next_page,
        AuthorizedSourceStateV1::Standalone(&state),
        None,
        request,
        before_persist,
    )
}

#[cfg(test)]
fn apply_authorized_append_v1(
    program_id: &Pubkey,
    accounts: &[AccountInfo],
    request: AuthorizedAppendV1,
) -> Result<AuthorizedAppendReceiptV1, ProgramError> {
    apply_authorized_append_after_v1(program_id, accounts, request, || Ok(()))
}

