        )
        .unwrap();
        let state = PoolStateV1::decode(&pool_data, &pool_key).unwrap();
        assert_eq!(state.current_root_sequence(), 256);
        assert_eq!(page_data, before_current);
        let header = validate_root_page_bytes(&next_data, &pool_key, 1).unwrap();
        assert_eq!(header.filled, 1);
        assert_eq!(
            read_retained_root(&next_data, header, 256).unwrap(),
            state.tree.root
        );
    }

    #[test]
    fn two_leaf_append_splits_exactly_across_page_boundary() {
        let program_id = Pubkey::new_unique();
        let pool_key = canonical_pool_key(&program_id);
        let (state, mut current_data) = state_and_history_at(&pool_key, 254);
        let mut pool_data = state.encode().unwrap();
        let current_key = crate::pool_v1_root_page_address(&program_id, &pool_key, 0).0;
        let next_key = crate::pool_v1_root_page_address(&program_id, &pool_key, 1).0;
        let mut next_data = vec![0u8; POOL_V1_ROOT_HISTORY_PAGE_ACCOUNT_BYTES];
        let mut pool_lamports = 1;
        let mut current_lamports = 1;
        let mut next_lamports = 1;
        let pool = account(
            &pool_key,
            &program_id,
            &mut pool_lamports,
            &mut pool_data,
            false,
            true,
        );
        let current = account(
            &current_key,
            &program_id,
            &mut current_lamports,
            &mut current_data,
            false,
            true,
        );
        let next = account(
            &next_key,
            &program_id,
            &mut next_lamports,
            &mut next_data,
            false,
            true,
        );
        let receipt = apply_authorized_append_v1(
            &program_id,
            &[pool, current, next],
            AuthorizedAppendV1::Two(digest(700), digest(701)),
        )
        .unwrap();
        assert_eq!(receipt.first.root_sequence, 255);
        assert_eq!(receipt.second.unwrap().root_sequence, 256);
        let state = PoolStateV1::decode(&pool_data, &pool_key).unwrap();
        assert_eq!(state.current_root_sequence(), 256);
        let current_header = validate_root_page_bytes(&current_data, &pool_key, 0).unwrap();
        let next_header = validate_root_page_bytes(&next_data, &pool_key, 1).unwrap();
        assert_eq!(current_header.filled, 256);
        assert_eq!(next_header.filled, 1);
        assert_eq!(
            read_retained_root(&current_data, current_header, 255).unwrap(),
            receipt.first.root
        );
        assert_eq!(
            read_retained_root(&next_data, next_header, 256).unwrap(),
            state.tree.root
        );
    }

    fn one_slot_remaining_state(pool_key: &Pubkey) -> PoolStateV1 {
        let frontier = core::array::from_fn(|level| digest(50_000 + level as u32));
        let mut node = POOL_V1_EMPTY_ROOTS[0];
        for sibling in frontier.iter().take(POOL_V1_TREE_DEPTH) {
            node = pool_v1_tree_parent(sibling, &node);
        }
        let tree = IncrementalMerkleTreeV1::from_parts_with_empty_roots(
            POOL_V1_LEAF_CAPACITY - 1,
            node,
            frontier,
            &POOL_V1_EMPTY_ROOTS,
        )
        .unwrap();
        PoolStateV1 {
            tree,
            ..PoolStateV1::genesis(pool_key, initialization()).unwrap()
        }
    }

    fn terminal_current_page(pool_key: &Pubkey, root: Digest) -> std::vec::Vec<u8> {
        let page_number = root_history_location(POOL_V1_LEAF_CAPACITY - 1).page_number;
        let first = page_number * POOL_V1_ROOT_HISTORY_CAPACITY as u64;
        let mut page = RootHistoryPageV1::new(pool_key.to_bytes(), page_number).unwrap();
        for sequence in first..=POOL_V1_LEAF_CAPACITY - 1 {
            let value = if sequence == POOL_V1_LEAF_CAPACITY - 1 {
                root
            } else {
                digest(sequence as u32)
            };
            page.push(sequence, value).unwrap();
        }
        page.encode().unwrap().to_vec()
    }

    #[test]
    fn final_append_reaches_full_tree_and_future_append_fails_closed() {
        let program_id = Pubkey::new_unique();
        let pool_key = canonical_pool_key(&program_id);
        let state = one_slot_remaining_state(&pool_key);
        let mut pool_data = state.encode().unwrap();
        let current_page_number = root_history_location(POOL_V1_LEAF_CAPACITY - 1).page_number;
        let current_key =
            crate::pool_v1_root_page_address(&program_id, &pool_key, current_page_number).0;
        let next_key =
            crate::pool_v1_root_page_address(&program_id, &pool_key, current_page_number + 1).0;
        let mut current_data = terminal_current_page(&pool_key, state.tree.root);
        let mut next_data = vec![0u8; POOL_V1_ROOT_HISTORY_PAGE_ACCOUNT_BYTES];
        let mut pool_lamports = 1;
        let mut current_lamports = 1;
        let mut next_lamports = 1;

        let before_pool = pool_data;
        let before_current = current_data.clone();
        let pool = account(
            &pool_key,
            &program_id,
            &mut pool_lamports,
            &mut pool_data,
            false,
            true,
        );
        let current = account(
            &current_key,
            &program_id,
            &mut current_lamports,
            &mut current_data,
            false,
            false,
        );
        assert_eq!(
            apply_authorized_append_v1(
                &program_id,
                &[pool, current],
                AuthorizedAppendV1::Two(digest(1233), digest(1234))
            ),
            Err(PoolV1ProgramError::InsufficientTreeCapacity.into())
        );
        assert_eq!(pool_data, before_pool);
        assert_eq!(current_data, before_current);

        let pool = account(
            &pool_key,
            &program_id,
            &mut pool_lamports,
            &mut pool_data,
            false,
            true,
        );
        let current = account(
            &current_key,
            &program_id,
            &mut current_lamports,
            &mut current_data,
            false,
            false,
        );
        let next = account(
            &next_key,
            &program_id,
            &mut next_lamports,
            &mut next_data,
            false,
            true,
        );
        let receipt = apply_authorized_append_v1(
            &program_id,
            &[pool, current, next],
            AuthorizedAppendV1::One(digest(1234)),
        )
        .unwrap();
        assert_eq!(receipt.first.root_sequence, POOL_V1_LEAF_CAPACITY);
        let full = PoolStateV1::decode(&pool_data, &pool_key).unwrap();
        assert_eq!(full.current_root_sequence(), POOL_V1_LEAF_CAPACITY);
        let header =
            validate_root_page_bytes(&next_data, &pool_key, current_page_number + 1).unwrap();
        assert_eq!(header.filled, 1);
        assert_eq!(
            read_retained_root(&next_data, header, POOL_V1_LEAF_CAPACITY).unwrap(),
            full.tree.root
        );

        let before_pool = pool_data;
        let before_page = next_data.clone();
        let pool = account(
            &pool_key,
            &program_id,
            &mut pool_lamports,
            &mut pool_data,
            false,
            true,
        );
        let current = account(
            &next_key,
            &program_id,
            &mut next_lamports,
            &mut next_data,
            false,
            false,
        );
        assert_eq!(
            apply_authorized_append_v1(
                &program_id,
                &[pool, current],
                AuthorizedAppendV1::One(digest(1235))
            ),
            Err(PoolV1ProgramError::TreeFull.into())
        );
        assert_eq!(pool_data, before_pool);
        assert_eq!(next_data, before_page);
    }
}

programs/aspis-pool/src/vault.rs:
//! Canonical Pool V1 vault addresses and strict legacy SPL Token parsing.
//!
//! Launch supports only the original SPL Token program and its exact
//! 82-byte mint / 165-byte account images. Token-2022 and extension-bearing
//! accounts fail closed. CPI execution remains a Solana runtime boundary.

extern crate alloc;

use alloc::{vec, vec::Vec};

use solana_program::{
    account_info::AccountInfo,
    instruction::{AccountMeta, Instruction},
    program_error::ProgramError,
    pubkey::Pubkey,
};
use solana_sdk_ids::system_program;

use aspis_statement::pool_v1::PoolIdentityV1;

use crate::{error::PoolV1ProgramError, state::PoolStateV1};

pub const LEGACY_SPL_TOKEN_PROGRAM_ID: Pubkey =
    Pubkey::from_str_const("TokenkegQfeZyiNwAJbNbGKPFXCWuBvf9Ss623VQ5DA");
pub const LEGACY_SPL_TOKEN_MINT_ACCOUNT_BYTES: usize = 82;
pub const LEGACY_SPL_TOKEN_ACCOUNT_BYTES: usize = 165;
pub const POOL_V1_VAULT_AUTHORITY_SEED: &[u8] = b"aspis-pool-vault-authority-v1";
pub const POOL_V1_VAULT_TOKEN_ACCOUNT_SEED: &[u8] = b"aspis-pool-vault-token-v1";

const TOKEN_ACCOUNT_MINT_OFFSET: usize = 0;
const TOKEN_ACCOUNT_AUTHORITY_OFFSET: usize = 32;
const TOKEN_ACCOUNT_AMOUNT_OFFSET: usize = 64;
const TOKEN_ACCOUNT_DELEGATE_OFFSET: usize = 72;
const TOKEN_ACCOUNT_STATE_OFFSET: usize = 108;
const TOKEN_ACCOUNT_IS_NATIVE_OFFSET: usize = 109;
const TOKEN_ACCOUNT_DELEGATED_AMOUNT_OFFSET: usize = 121;
const TOKEN_ACCOUNT_CLOSE_AUTHORITY_OFFSET: usize = 129;

const TOKEN_MINT_SUPPLY_OFFSET: usize = 36;
const TOKEN_MINT_DECIMALS_OFFSET: usize = 44;
const TOKEN_MINT_INITIALIZED_OFFSET: usize = 45;
const TOKEN_MINT_FREEZE_AUTHORITY_OFFSET: usize = 46;

const SPL_TOKEN_ACCOUNT_STATE_INITIALIZED: u8 = 1;
const SPL_TOKEN_TRANSFER_CHECKED_DISCRIMINANT: u8 = 12;

pub fn pool_v1_vault_authority_address(program_id: &Pubkey, pool: &Pubkey) -> (Pubkey, u8) {
    Pubkey::find_program_address(&[POOL_V1_VAULT_AUTHORITY_SEED, pool.as_ref()], program_id)
}

pub fn pool_v1_vault_token_account_address(program_id: &Pubkey, pool: &Pubkey) -> (Pubkey, u8) {
    Pubkey::find_program_address(
        &[POOL_V1_VAULT_TOKEN_ACCOUNT_SEED, pool.as_ref()],
        program_id,
    )
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) struct LegacyMintV1 {
    pub supply: u64,
    pub decimals: u8,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) struct LegacyTokenAccountV1 {
    pub mint: Pubkey,
    pub authority: Pubkey,
    pub amount: u64,
    pub has_delegate: bool,
    pub is_native: bool,
    pub delegated_amount: u64,
    pub has_close_authority: bool,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub(crate) struct LegacyDepositTransferPlanV1 {
    pub instruction: Instruction,
    pub source: Pubkey,
    pub mint: Pubkey,
    pub vault: Pubkey,
    pub authority: Pubkey,
    pub amount: u64,
    pub source_before: u64,
    pub source_after: u64,
    pub vault_before: u64,
    pub vault_after: u64,
    pub decimals: u8,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub(crate) struct LegacyWithdrawalTransferPlanV1 {
    pub instruction: Instruction,
    pub mint: Pubkey,
    pub vault: Pubkey,
    pub destination: Pubkey,
    pub authority: Pubkey,
    pub amount: u64,
    pub vault_before: u64,
    pub vault_after: u64,
    pub destination_before: u64,
    pub destination_after: u64,
    pub decimals: u8,
    pub authority_bump: u8,
}

fn require_zero(bytes: &[u8]) -> Result<(), ProgramError> {
    if bytes.iter().any(|byte| *byte != 0) {
        return Err(PoolV1ProgramError::UnsupportedTokenConfiguration.into());
    }
    Ok(())
}

fn token_array<const N: usize>(bytes: &[u8]) -> Result<[u8; N], ProgramError> {
    bytes
        .try_into()
        .map_err(|_| PoolV1ProgramError::InvalidTokenAccount.into())
}

fn parse_coption_pubkey(bytes: &[u8]) -> Result<Option<Pubkey>, ProgramError> {
    if bytes.len() != 36 {
        return Err(PoolV1ProgramError::InvalidTokenAccount.into());
    }
    match u32::from_le_bytes(token_array(&bytes[..4])?) {
        0 => {
            require_zero(&bytes[4..])?;
            Ok(None)
        }
        1 => Ok(Some(Pubkey::new_from_array(token_array(&bytes[4..])?))),
        _ => Err(PoolV1ProgramError::InvalidTokenAccount.into()),
    }
}

fn parse_coption_u64(bytes: &[u8]) -> Result<Option<u64>, ProgramError> {
    if bytes.len() != 12 {
        return Err(PoolV1ProgramError::InvalidTokenAccount.into());
    }
    match u32::from_le_bytes(token_array(&bytes[..4])?) {
        0 => {
            require_zero(&bytes[4..])?;
            Ok(None)
        }
        1 => Ok(Some(u64::from_le_bytes(token_array(&bytes[4..])?))),
        _ => Err(PoolV1ProgramError::InvalidTokenAccount.into()),
    }
}

pub(crate) fn parse_legacy_mint_v1(data: &[u8]) -> Result<LegacyMintV1, ProgramError> {
    if data.len() != LEGACY_SPL_TOKEN_MINT_ACCOUNT_BYTES {
        return Err(PoolV1ProgramError::UnsupportedTokenConfiguration.into());
    }
    parse_coption_pubkey(&data[..36])?;
    parse_coption_pubkey(&data[TOKEN_MINT_FREEZE_AUTHORITY_OFFSET..])?;
    if data[TOKEN_MINT_INITIALIZED_OFFSET] != 1 {
        return Err(PoolV1ProgramError::InvalidMint.into());
    }
    Ok(LegacyMintV1 {
        supply: u64::from_le_bytes(token_array(
            &data[TOKEN_MINT_SUPPLY_OFFSET..TOKEN_MINT_DECIMALS_OFFSET],
        )?),
        decimals: data[TOKEN_MINT_DECIMALS_OFFSET],
    })
}

pub(crate) fn parse_legacy_token_account_v1(
    data: &[u8],
) -> Result<LegacyTokenAccountV1, ProgramError> {
    if data.len() != LEGACY_SPL_TOKEN_ACCOUNT_BYTES {
        return Err(PoolV1ProgramError::UnsupportedTokenConfiguration.into());
    }
    let delegate =
        parse_coption_pubkey(&data[TOKEN_ACCOUNT_DELEGATE_OFFSET..TOKEN_ACCOUNT_STATE_OFFSET])?;
    if data[TOKEN_ACCOUNT_STATE_OFFSET] != SPL_TOKEN_ACCOUNT_STATE_INITIALIZED {
        return Err(PoolV1ProgramError::InvalidTokenAccount.into());
    }
    let is_native = parse_coption_u64(
        &data[TOKEN_ACCOUNT_IS_NATIVE_OFFSET..TOKEN_ACCOUNT_DELEGATED_AMOUNT_OFFSET],
    )?;
    let close_authority = parse_coption_pubkey(&data[TOKEN_ACCOUNT_CLOSE_AUTHORITY_OFFSET..])?;
    Ok(LegacyTokenAccountV1 {
        mint: Pubkey::new_from_array(token_array(
            &data[TOKEN_ACCOUNT_MINT_OFFSET..TOKEN_ACCOUNT_AUTHORITY_OFFSET],
        )?),
        authority: Pubkey::new_from_array(token_array(
            &data[TOKEN_ACCOUNT_AUTHORITY_OFFSET..TOKEN_ACCOUNT_AMOUNT_OFFSET],
        )?),
        amount: u64::from_le_bytes(token_array(
            &data[TOKEN_ACCOUNT_AMOUNT_OFFSET..TOKEN_ACCOUNT_DELEGATE_OFFSET],
        )?),
        has_delegate: delegate.is_some(),
        is_native: is_native.is_some(),
        delegated_amount: u64::from_le_bytes(token_array(
            &data[TOKEN_ACCOUNT_DELEGATED_AMOUNT_OFFSET..TOKEN_ACCOUNT_CLOSE_AUTHORITY_OFFSET],
        )?),
        has_close_authority: close_authority.is_some(),
    })
}

fn require_token_owned_account(account: &AccountInfo, writable: bool) -> Result<(), ProgramError> {
    if account.owner != &LEGACY_SPL_TOKEN_PROGRAM_ID
        || account.executable
        || account.is_signer
        || account.is_writable != writable
    {
        return Err(PoolV1ProgramError::InvalidTokenAccount.into());
    }
    Ok(())
}

fn exact_five_accounts<'slice, 'info>(
    accounts: &'slice [AccountInfo<'info>],
) -> Result<[&'slice AccountInfo<'info>; 5], ProgramError> {
    let [mint, source, authority, vault, token_program] = accounts else {
        return Err(if accounts.len() < 5 {
            ProgramError::NotEnoughAccountKeys
        } else {
            ProgramError::InvalidArgument
        });
    };
    let values = [mint, source, authority, vault, token_program];
    for left in 0..values.len() {
        for right in left + 1..values.len() {
            if values[left].key == values[right].key {
                return Err(PoolV1ProgramError::InvalidTokenAccount.into());
            }
        }
    }
    Ok(values)
}

/// Validate exactly `[mint, source, source_authority, vault, token_program]`
/// and construct one direct-owner `TransferChecked` instruction.
pub(crate) fn plan_legacy_deposit_transfer_v1(
    program_id: &Pubkey,
    pool: &Pubkey,
    state: &PoolStateV1,
    accounts: &[AccountInfo],
    amount: u32,
) -> Result<LegacyDepositTransferPlanV1, ProgramError> {
    plan_legacy_deposit_transfer_from_identity_v1(
        program_id,
        pool,
        &state.identity,
        accounts,
        amount,
    )
}

/// Pair-forest and legacy-state deposits share the exact vault identity,
/// token parsing and direct-owner `TransferChecked` semantics.
pub(crate) fn plan_legacy_deposit_transfer_from_identity_v1(
    program_id: &Pubkey,
    pool: &Pubkey,
    identity: &PoolIdentityV1,
    accounts: &[AccountInfo],
    amount: u32,
) -> Result<LegacyDepositTransferPlanV1, ProgramError> {
    let [mint_account, source_account, source_authority, vault_account, token_program] =
        exact_five_accounts(accounts)?;
    if identity.token_program != LEGACY_SPL_TOKEN_PROGRAM_ID.to_bytes()
        || token_program.key != &LEGACY_SPL_TOKEN_PROGRAM_ID
        || !token_program.executable
        || token_program.is_signer
        || token_program.is_writable
    {
        return Err(PoolV1ProgramError::InvalidTokenProgram.into());
    }

    let expected_mint = Pubkey::new_from_array(identity.asset_mint);
    if mint_account.key != &expected_mint {
        return Err(PoolV1ProgramError::InvalidMint.into());
    }
    require_token_owned_account(mint_account, false)?;
    let mint = {
        let data = mint_account.try_borrow_data()?;
        parse_legacy_mint_v1(&data)?
    };

    require_token_owned_account(source_account, true)?;
    require_token_owned_account(vault_account, true)?;
    if !source_authority.is_signer || source_authority.is_writable || source_authority.executable {
        return Err(PoolV1ProgramError::InvalidSourceAuthority.into());
    }

    let source = {
        let data = source_account.try_borrow_data()?;
        parse_legacy_token_account_v1(&data)?
    };
    let vault = {
        let data = vault_account.try_borrow_data()?;
        parse_legacy_token_account_v1(&data)?
    };
    if source.mint != expected_mint
        || vault.mint != expected_mint
        || source.authority != *source_authority.key
    {
        return Err(PoolV1ProgramError::InvalidTokenAccount.into());
    }
    let expected_vault = pool_v1_vault_token_account_address(program_id, pool).0;
    if vault_account.key != &expected_vault {
        return Err(PoolV1ProgramError::InvalidVaultTokenAddress.into());
    }
    let expected_vault_authority = pool_v1_vault_authority_address(program_id, pool).0;
    if vault.authority != expected_vault_authority {
        return Err(PoolV1ProgramError::InvalidVaultAuthority.into());
    }
    // The launch vault has no delegate/close/native side channels. In
    // particular wrapped-native reserve semantics are deferred rather than
    // silently folded into the conservation invariant.
    if vault.has_delegate
        || vault.is_native
        || vault.delegated_amount != 0
        || vault.has_close_authority
    {
        return Err(PoolV1ProgramError::UnsupportedTokenConfiguration.into());
    }

    let amount = u64::from(amount);
    let source_after = source
        .amount
        .checked_sub(amount)
        .ok_or(PoolV1ProgramError::InsufficientDepositFunds)?;
    let vault_after = vault
        .amount
        .checked_add(amount)
        .ok_or(PoolV1ProgramError::ArithmeticOverflow)?;
    let mut data = Vec::with_capacity(10);
    data.push(SPL_TOKEN_TRANSFER_CHECKED_DISCRIMINANT);
    data.extend_from_slice(&amount.to_le_bytes());
    data.push(mint.decimals);
    let instruction = Instruction {
        program_id: LEGACY_SPL_TOKEN_PROGRAM_ID,
        accounts: vec![
            AccountMeta::new(*source_account.key, false),
            AccountMeta::new_readonly(*mint_account.key, false),
            AccountMeta::new(*vault_account.key, false),
            AccountMeta::new_readonly(*source_authority.key, true),
        ],
        data,
    };
    Ok(LegacyDepositTransferPlanV1 {
        instruction,
        source: *source_account.key,
        mint: *mint_account.key,
        vault: *vault_account.key,
        authority: *source_authority.key,
        amount,
        source_before: source.amount,
        source_after,
        vault_before: vault.amount,
        vault_after,
        decimals: mint.decimals,
    })
}

pub(crate) fn exact_transfer_account_infos_v1<'a>(
    accounts: &[AccountInfo<'a>],
) -> Result<[AccountInfo<'a>; 5], ProgramError> {
    let [mint, source, authority, vault, token_program] = exact_five_accounts(accounts)?;
    Ok([
        (*source).clone(),
        (*mint).clone(),
        (*vault).clone(),
        (*authority).clone(),
        (*token_program).clone(),
    ])
}

fn exact_five_withdrawal_accounts<'slice, 'info>(
    accounts: &'slice [AccountInfo<'info>],
) -> Result<[&'slice AccountInfo<'info>; 5], ProgramError> {
    let [mint, vault, destination, vault_authority, token_program] = accounts else {
        return Err(if accounts.len() < 5 {
            ProgramError::NotEnoughAccountKeys
        } else {
            ProgramError::InvalidArgument
        });
    };
    let values = [mint, vault, destination, vault_authority, token_program];
    for left in 0..values.len() {
        for right in left + 1..values.len() {
            if values[left].key == values[right].key {
                return Err(PoolV1ProgramError::InvalidTokenAccount.into());
            }
        }
    }
    Ok(values)
}

/// Validate exactly `[mint, vault, destination, vault_authority,
/// token_program]` and construct one PDA-authorized `TransferChecked`.
pub(crate) fn plan_legacy_withdrawal_transfer_v1(
    program_id: &Pubkey,
    pool: &Pubkey,
    state: &PoolStateV1,
    accounts: &[AccountInfo],
    destination: &Pubkey,
    amount: u32,
) -> Result<LegacyWithdrawalTransferPlanV1, ProgramError> {
    plan_legacy_withdrawal_transfer_from_identity_v1(
        program_id,
        pool,
        &state.identity,
        accounts,
        destination,
        amount,
        None,
    )
}

/// Pool-only bump hints for the two constant-seed custody PDAs (pair-forest
/// R1 withdrawal). They are carried in Pool instruction data only; the master
/// format and the verifier are unchanged.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct VaultBumpHintsV1 {
    pub vault_authority: u8,
    pub vault_token_account: u8,
}

/// Pair-state and legacy-state withdrawal paths share the exact vault
/// identity and custody rules. Keeping the planner on the sealed Pool
/// identity avoids duplicating token-account parsing or transfer semantics.
pub(crate) fn plan_legacy_withdrawal_transfer_from_identity_v1(
    program_id: &Pubkey,
    pool: &Pubkey,
    identity: &PoolIdentityV1,
    accounts: &[AccountInfo],
    destination: &Pubkey,
    amount: u32,
    bump_hints: Option<VaultBumpHintsV1>,
) -> Result<LegacyWithdrawalTransferPlanV1, ProgramError> {
    let [mint_account, vault_account, destination_account, vault_authority, token_program] =
        exact_five_withdrawal_accounts(accounts)?;
    if amount == 0 {
        return Err(PoolV1ProgramError::InvalidWithdrawalAmount.into());
    }
    if identity.token_program != LEGACY_SPL_TOKEN_PROGRAM_ID.to_bytes()
        || token_program.key != &LEGACY_SPL_TOKEN_PROGRAM_ID
        || !token_program.executable
        || token_program.is_signer
        || token_program.is_writable
    {
        return Err(PoolV1ProgramError::InvalidTokenProgram.into());
    }

    let expected_mint = Pubkey::new_from_array(identity.asset_mint);
    if mint_account.key != &expected_mint {
        return Err(PoolV1ProgramError::InvalidMint.into());
    }
    require_token_owned_account(mint_account, false)?;
    let mint = {
        let data = mint_account.try_borrow_data()?;
        parse_legacy_mint_v1(&data)?
    };

    require_token_owned_account(vault_account, true)?;
    require_token_owned_account(destination_account, true)?;
    // With hints (B4-style, Pool-only): one `create_program_address` each.
    // A hinted non-canonical authority cannot pass, because the vault token
    // account (authenticated below) records the canonical authority, and the
    // Pool creates the vault token account only at its canonical bump.
    let (expected_authority, authority_bump) = match bump_hints {
        Some(hints) => (
            if crate::registry::stored_bump_address_matches(
                &[
                    POOL_V1_VAULT_AUTHORITY_SEED,
                    pool.as_ref(),
                    &[hints.vault_authority],
                ],
                program_id,
                vault_authority.key,
            ) {
                *vault_authority.key
            } else {
                return Err(PoolV1ProgramError::InvalidVaultAuthority.into());
            },
            hints.vault_authority,
        ),
        None => pool_v1_vault_authority_address(program_id, pool),
    };
    if vault_authority.key != &expected_authority
        || vault_authority.owner != &system_program::id()
        || vault_authority.executable
        || vault_authority.is_signer
        || vault_authority.is_writable
        || !vault_authority.data_is_empty()
    {
        return Err(PoolV1ProgramError::InvalidVaultAuthority.into());
    }
    if destination_account.key != destination {
        return Err(PoolV1ProgramError::InvalidDestinationTokenAccount.into());
    }

    let vault = {
        let data = vault_account.try_borrow_data()?;
        parse_legacy_token_account_v1(&data)?
    };
    let destination_state = {
        let data = destination_account.try_borrow_data()?;
        parse_legacy_token_account_v1(&data)?
    };
    let vault_address_ok = match bump_hints {
        Some(hints) => crate::registry::stored_bump_address_matches(
            &[
                POOL_V1_VAULT_TOKEN_ACCOUNT_SEED,
                pool.as_ref(),
                &[hints.vault_token_account],
            ],
            program_id,
            vault_account.key,
        ),
        None => vault_account.key == &pool_v1_vault_token_account_address(program_id, pool).0,
    };
    if !vault_address_ok {
        return Err(PoolV1ProgramError::InvalidVaultTokenAddress.into());
    }
    if vault.mint != expected_mint
        || destination_state.mint != expected_mint
        || vault.authority != expected_authority
    {
        return Err(PoolV1ProgramError::InvalidTokenAccount.into());
    }
    if vault.has_delegate
        || vault.is_native
        || vault.delegated_amount != 0
        || vault.has_close_authority
        || destination_state.is_native
    {
        return Err(PoolV1ProgramError::UnsupportedTokenConfiguration.into());
    }

    let amount = u64::from(amount);
    let vault_after = vault
        .amount
        .checked_sub(amount)
        .ok_or(PoolV1ProgramError::InsufficientVaultFunds)?;
    let destination_after = destination_state
        .amount
        .checked_add(amount)
        .ok_or(PoolV1ProgramError::ArithmeticOverflow)?;
    let mut data = Vec::with_capacity(10);
    data.push(SPL_TOKEN_TRANSFER_CHECKED_DISCRIMINANT);
    data.extend_from_slice(&amount.to_le_bytes());
    data.push(mint.decimals);
    let instruction = Instruction {
        program_id: LEGACY_SPL_TOKEN_PROGRAM_ID,
        accounts: vec![
            AccountMeta::new(*vault_account.key, false),
            AccountMeta::new_readonly(*mint_account.key, false),
            AccountMeta::new(*destination_account.key, false),
            AccountMeta::new_readonly(*vault_authority.key, true),
        ],
        data,
    };
    Ok(LegacyWithdrawalTransferPlanV1 {
        instruction,
        mint: *mint_account.key,
        vault: *vault_account.key,
        destination: *destination_account.key,
        authority: *vault_authority.key,
        amount,
        vault_before: vault.amount,
        vault_after,
        destination_before: destination_state.amount,
        destination_after,
        decimals: mint.decimals,
        authority_bump,
    })
}

pub(crate) fn exact_withdrawal_transfer_account_infos_v1<'a>(
    accounts: &[AccountInfo<'a>],
) -> Result<[AccountInfo<'a>; 5], ProgramError> {
    let [mint, vault, destination, vault_authority, token_program] =
        exact_five_withdrawal_accounts(accounts)?;
    Ok([
        (*vault).clone(),
        (*mint).clone(),
        (*destination).clone(),
        (*vault_authority).clone(),
        (*token_program).clone(),
    ])
}

/// Re-read both balances after the withdrawal CPI.  The Pool state and
/// nullifier marker are not persisted until this exact delta has authenticated.
pub(crate) fn validate_exact_withdrawal_delta_v1(
    accounts: &[AccountInfo],
    plan: &LegacyWithdrawalTransferPlanV1,
) -> Result<(), ProgramError> {
    let [mint_account, vault_account, destination_account, vault_authority, token_program] =
        exact_five_withdrawal_accounts(accounts)?;
    if mint_account.key != &plan.mint
        || vault_account.key != &plan.vault
        || destination_account.key != &plan.destination
        || vault_authority.key != &plan.authority
        || token_program.key != &LEGACY_SPL_TOKEN_PROGRAM_ID
    {
        return Err(PoolV1ProgramError::TokenBalanceDeltaMismatch.into());
    }
    let vault = {
        let data = vault_account.try_borrow_data()?;
        parse_legacy_token_account_v1(&data)?
    };
    let destination = {
        let data = destination_account.try_borrow_data()?;
        parse_legacy_token_account_v1(&data)?
    };
    if vault.mint != plan.mint
        || destination.mint != plan.mint
        || vault.authority != plan.authority
        || vault.amount != plan.vault_after
        || destination.amount != plan.destination_after
    {
        return Err(PoolV1ProgramError::TokenBalanceDeltaMismatch.into());
    }
    Ok(())
}

/// Re-read balances after CPI and require the exact requested debit/credit.
/// Any mismatch returns before the Pool state/history bytes are persisted.
pub(crate) fn validate_exact_deposit_delta_v1(
    accounts: &[AccountInfo],
    plan: &LegacyDepositTransferPlanV1,
) -> Result<(), ProgramError> {
    let [mint_account, source_account, source_authority, vault_account, token_program] =
        exact_five_accounts(accounts)?;
    if mint_account.key != &plan.mint
        || source_account.key != &plan.source
        || source_authority.key != &plan.authority
        || vault_account.key != &plan.vault
        || token_program.key != &LEGACY_SPL_TOKEN_PROGRAM_ID
    {
        return Err(PoolV1ProgramError::TokenBalanceDeltaMismatch.into());
    }
    let source = {
        let data = source_account.try_borrow_data()?;
        parse_legacy_token_account_v1(&data)?
    };
    let vault = {
        let data = vault_account.try_borrow_data()?;
        parse_legacy_token_account_v1(&data)?
    };
    if source.mint != plan.mint
        || vault.mint != plan.mint
        || source.authority != plan.authority
        || source.amount != plan.source_after
        || vault.amount != plan.vault_after
    {
        return Err(PoolV1ProgramError::TokenBalanceDeltaMismatch.into());
    }
    Ok(())
}

#[cfg(test)]
pub(crate) fn write_token_amount_for_test(
    account: &AccountInfo,
    amount: u64,
) -> Result<(), ProgramError> {
    let mut data = account.try_borrow_mut_data()?;
    if data.len() != LEGACY_SPL_TOKEN_ACCOUNT_BYTES {
        return Err(PoolV1ProgramError::InvalidTokenAccount.into());
    }
    data[TOKEN_ACCOUNT_AMOUNT_OFFSET..TOKEN_ACCOUNT_DELEGATE_OFFSET]
        .copy_from_slice(&amount.to_le_bytes());
    Ok(())
}

programs/aspis-pool/src/verifier_dispatc:
//! Read-only Pool V1 authenticated-verifier dispatch and capture.
//!
//! This module composes the already-reviewed registry selection with the exact
//! P3a envelope, selected executable program account and sealed proof account.
//! P3d produces the exact request and sole acceptable fixed return-data result.
//! P3e can invoke that selected verifier through one exact read-only CPI and
//! authenticate the immediately captured return data. It writes no Pool,
//! marker, tree, vault, registry, proof, or verifier account. The Pool
//! entrypoint reaches it only from private-transfer and withdrawal processing
//! after all Pool-side preflight checks.

extern crate alloc;

use alloc::{vec, vec::Vec};
use aspis_core::transcript::HashFn;
use aspis_statement::pool_v1::{
    decode_historical_anchor_envelope_v1, decode_verifier_dispatch_result_v1,
    encode_verifier_dispatch_request_v1, encode_verifier_dispatch_result_v1,
    verifier_dispatch_binding_from_envelope_v1, verifier_proof_body_digest_v1,
    HistoricalAnchorEnvelopeV1, VerifierDispatchBindingV1, VerifierDispatchRequestV1,
    VerifierDispatchResultV1, VerifierPolicyV1, POOL_V1_HISTORICAL_ANCHOR_VERSION,
    POOL_V1_VERIFIER_DISPATCH_RESULT_BYTES, POOL_V1_VERIFIER_DISPATCH_SUCCESS_CODE,
    POOL_V1_VERIFIER_PROOF_ACCOUNT_HEADER_BYTES, POOL_V1_VERIFIER_PROOF_ACCOUNT_MAGIC,
};
use solana_program::{
    account_info::AccountInfo,
    instruction::{AccountMeta, Instruction},
    program,
    program_error::ProgramError,
    pubkey::Pubkey,
};
use solana_sdk_ids::{bpf_loader, bpf_loader_upgradeable, loader_v4};

use crate::{
    error::PoolV1ProgramError,
    registry::{authenticate_verifier_selection_v1, VerifierSelectionV1},
};

const PROOF_LENGTH_OFFSET: usize = 4;
const PROOF_AUTHORITY_OFFSET: usize = 8;

/// Caller-supplied immutable identifiers that must match the actual accounts
/// and proof body before a request can be planned.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct VerifierDispatchClaimV1 {
    pub verifier_program: [u8; 32],
    pub proof_account: [u8; 32],
    pub proof_body_digest: [u8; 32],
    pub proof_body_length: u32,
}

/// Derive the immutable claim from the exact accounts supplied to the Pool
/// instruction.  The full planner subsequently rechecks ownership, loader,
/// privileges, body bounds and digest; deriving here avoids a caller-provided
/// duplicate key/digest wire that could diverge from the account list.
pub(crate) fn derive_verifier_dispatch_claim_v1(
    verifier_program_account: &AccountInfo,
    proof_account: &AccountInfo,
    hash: HashFn,
) -> Result<VerifierDispatchClaimV1, ProgramError> {
    let data = proof_account.try_borrow_data()?;
    if data.len() < POOL_V1_VERIFIER_PROOF_ACCOUNT_HEADER_BYTES
        || data[..4] != POOL_V1_VERIFIER_PROOF_ACCOUNT_MAGIC
        || data[PROOF_AUTHORITY_OFFSET..POOL_V1_VERIFIER_PROOF_ACCOUNT_HEADER_BYTES]
            .iter()
            .any(|byte| *byte != 0)
    {
        return Err(PoolV1ProgramError::InvalidVerifierProofAccount.into());
    }
    let proof_body_length = u32::from_le_bytes(
        data[PROOF_LENGTH_OFFSET..PROOF_AUTHORITY_OFFSET]
            .try_into()
            .map_err(|_| PoolV1ProgramError::InvalidVerifierProofAccount)?,
    );
    if proof_body_length == 0 {
        return Err(PoolV1ProgramError::VerifierProofBindingMismatch.into());
    }
    let body_end = POOL_V1_VERIFIER_PROOF_ACCOUNT_HEADER_BYTES
        .checked_add(proof_body_length as usize)
        .ok_or(PoolV1ProgramError::VerifierProofBindingMismatch)?;
    if body_end > data.len() {
        return Err(PoolV1ProgramError::VerifierProofBindingMismatch.into());
    }
    let proof_body = &data[POOL_V1_VERIFIER_PROOF_ACCOUNT_HEADER_BYTES..body_end];
    Ok(VerifierDispatchClaimV1 {
        verifier_program: verifier_program_account.key.to_bytes(),
        proof_account: proof_account.key.to_bytes(),
        proof_body_digest: verifier_proof_body_digest_v1(proof_body, hash),
        proof_body_length,
    })
}

/// Read-only output of complete pre-dispatch authentication.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct PlannedVerifierDispatchV1 {
    pub envelope: HistoricalAnchorEnvelopeV1,
    pub registry_generation: u64,
    pub request_binding: VerifierDispatchBindingV1,
    pub request_bytes: Vec<u8>,
    pub expected_result: VerifierDispatchResultV1,
    pub expected_result_bytes: [u8; POOL_V1_VERIFIER_DISPATCH_RESULT_BYTES],
}

/// Evidence available only after the freshly planned request has been invoked
/// and its exact selected-program return data has authenticated successfully.
/// The private field prevents external construction of accepted evidence.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct AuthenticatedVerifierDispatchV1 {
    plan: PlannedVerifierDispatchV1,
}

impl AuthenticatedVerifierDispatchV1 {
    pub fn plan(&self) -> &PlannedVerifierDispatchV1 {
        &self.plan
    }
}

trait VerifierDispatchRuntimeV1 {
    fn clear_return_data(&mut self);

    fn invoke(
        &mut self,
        instruction: &Instruction,
        account_infos: &[AccountInfo<'_>],
    ) -> Result<(), ProgramError>;

    fn get_return_data(&mut self) -> Option<(Pubkey, Vec<u8>)>;
}

struct SolanaVerifierDispatchRuntimeV1;

impl VerifierDispatchRuntimeV1 for SolanaVerifierDispatchRuntimeV1 {
    fn clear_return_data(&mut self) {
        program::set_return_data(&[]);
    }

    fn invoke(
        &mut self,
        instruction: &Instruction,
        account_infos: &[AccountInfo<'_>],
    ) -> Result<(), ProgramError> {
        program::invoke(instruction, account_infos)
    }

    fn get_return_data(&mut self) -> Option<(Pubkey, Vec<u8>)> {
        program::get_return_data()
    }
}

fn supported_verifier_loader(owner: &Pubkey) -> bool {
    owner == &bpf_loader::id()
        || owner == &bpf_loader_upgradeable::id()
        || owner == &loader_v4::id()
}

fn require_selected_verifier_program_account(
    account: &AccountInfo,
    selected_program: &Pubkey,
) -> Result<(), ProgramError> {
    if account.key != selected_program
        || !account.executable
        || account.is_signer
        || account.is_writable
        || !supported_verifier_loader(account.owner)
    {
        return Err(PoolV1ProgramError::InvalidVerifierProgramAccount.into());
    }
    Ok(())
}

fn authenticate_proof_account_body_v1(
    account: &AccountInfo,
    selected_program: &Pubkey,
    pool: &Pubkey,
    claim: &VerifierDispatchClaimV1,
    hash: HashFn,
) -> Result<(), ProgramError> {
    if account.key.to_bytes() != claim.proof_account
        || account.key == selected_program
        || account.key == pool
        || account.owner != selected_program
        || account.executable
        || account.is_signer
        || account.is_writable
    {
        return Err(PoolV1ProgramError::InvalidVerifierProofAccount.into());
    }
    let data = account.try_borrow_data()?;
    if data.len() < POOL_V1_VERIFIER_PROOF_ACCOUNT_HEADER_BYTES
        || data[..4] != POOL_V1_VERIFIER_PROOF_ACCOUNT_MAGIC
        || data[PROOF_AUTHORITY_OFFSET..POOL_V1_VERIFIER_PROOF_ACCOUNT_HEADER_BYTES]
            .iter()
            .any(|byte| *byte != 0)
    {
        return Err(PoolV1ProgramError::InvalidVerifierProofAccount.into());
    }
    let declared_length = u32::from_le_bytes([
        data[PROOF_LENGTH_OFFSET],
        data[PROOF_LENGTH_OFFSET + 1],
        data[PROOF_LENGTH_OFFSET + 2],
        data[PROOF_LENGTH_OFFSET + 3],
    ]);
    if declared_length == 0 || declared_length != claim.proof_body_length {
        return Err(PoolV1ProgramError::VerifierProofBindingMismatch.into());
    }
    let body_end = POOL_V1_VERIFIER_PROOF_ACCOUNT_HEADER_BYTES
        .checked_add(declared_length as usize)
        .ok_or(PoolV1ProgramError::VerifierProofBindingMismatch)?;
    if body_end > data.len() {
        return Err(PoolV1ProgramError::VerifierProofBindingMismatch.into());
    }
    let body = &data[POOL_V1_VERIFIER_PROOF_ACCOUNT_HEADER_BYTES..body_end];
    if verifier_proof_body_digest_v1(body, hash) != claim.proof_body_digest {
        return Err(PoolV1ProgramError::VerifierProofBindingMismatch.into());
    }
    Ok(())
}

/// Authenticate every immutable input needed by the selected-verifier CPI and
/// freeze both the exact request and the only acceptable success result.
///
/// The Pool derives `statement_digest` internally from the exact supplied
/// payload, selected profile/release, length and frozen digest domain. Payload
/// semantics remain profile-dispatched and are not interpreted by this layer.
#[allow(clippy::too_many_arguments)]
pub fn plan_authenticated_verifier_dispatch_v1(
    pool: &Pubkey,
    expected_deployment_domain: &[u8; 32],
    policy: &VerifierPolicyV1,
    registry_accounts: &[AccountInfo],
    verifier_program_account: &AccountInfo,
    proof_account: &AccountInfo,
    encoded_envelope: &[u8],
    statement_payload: &[u8],
    claim: VerifierDispatchClaimV1,
    current_slot: u64,
    hash: HashFn,
) -> Result<PlannedVerifierDispatchV1, ProgramError> {
    let envelope = decode_historical_anchor_envelope_v1(encoded_envelope)
        .map_err(|_| PoolV1ProgramError::InvalidVerifierDispatchEnvelope)?;
    if envelope.pool != pool.to_bytes() || envelope.deployment_domain != *expected_deployment_domain
    {
        return Err(PoolV1ProgramError::VerifierDispatchIdentityMismatch.into());
    }

    let selected_program = Pubkey::new_from_array(claim.verifier_program);
    let authenticated_selection = authenticate_verifier_selection_v1(
        pool,
        policy,
        registry_accounts,
        VerifierSelectionV1 {
            verifier_program: claim.verifier_program,
            profile_binding: envelope.verifier_profile,
            release_binding: envelope.verifier_release,
            statement_version: POOL_V1_HISTORICAL_ANCHOR_VERSION,
        },
        current_slot,
    )?;
    require_selected_verifier_program_account(verifier_program_account, &selected_program)?;
    if !authenticated_selection.matches_verifier_owner(verifier_program_account.owner) {
        return Err(PoolV1ProgramError::InvalidVerifierProgramAccount.into());
    }
    authenticate_proof_account_body_v1(proof_account, &selected_program, pool, &claim, hash)?;

    if !authenticated_selection.matches(
        envelope.pool,
        claim.verifier_program,
        envelope.verifier_profile,
        envelope.verifier_release,
        POOL_V1_HISTORICAL_ANCHOR_VERSION,
    ) {
        return Err(PoolV1ProgramError::VerifierDispatchIdentityMismatch.into());
    }

    let binding = verifier_dispatch_binding_from_envelope_v1(
        claim.verifier_program,
        &envelope,
        statement_payload,
        claim.proof_account,
        claim.proof_body_digest,
        claim.proof_body_length,
        hash,
    )
    .map_err(|_| PoolV1ProgramError::VerifierDispatchIdentityMismatch)?;
    let request = VerifierDispatchRequestV1 {
        binding,
        statement_payload,
    };
    let request_bytes = encode_verifier_dispatch_request_v1(&request, hash)
        .map_err(|_| PoolV1ProgramError::VerifierDispatchIdentityMismatch)?;
    let expected_result = VerifierDispatchResultV1 {
        success_code: POOL_V1_VERIFIER_DISPATCH_SUCCESS_CODE,
        binding,
    };
    let expected_result_bytes = encode_verifier_dispatch_result_v1(&expected_result)
        .map_err(|_| PoolV1ProgramError::VerifierDispatchIdentityMismatch)?;

    Ok(PlannedVerifierDispatchV1 {
        envelope,
        registry_generation: authenticated_selection.registry_generation(),
        request_binding: binding,
        request_bytes,
        expected_result,
        expected_result_bytes,
    })
}

/// Authenticate an already-snapshotted return-data pair without calling the
/// Solana runtime. Future composition must call `get_return_data` immediately
/// after the selected CPI and pass its `(program_id, bytes)` here unchanged.
pub fn authenticate_verifier_return_data_v1(
    expected: &PlannedVerifierDispatchV1,
    returned_program_id: &Pubkey,
    returned_data: &[u8],
) -> Result<(), ProgramError> {
    let selected_program = Pubkey::new_from_array(expected.request_binding.verifier_program);
    if returned_program_id != &selected_program {
        return Err(PoolV1ProgramError::InvalidVerifierReturnProgram.into());
    }
    if returned_data.len() != POOL_V1_VERIFIER_DISPATCH_RESULT_BYTES {
        return Err(PoolV1ProgramError::InvalidVerifierReturnData.into());
    }
    let returned = decode_verifier_dispatch_result_v1(returned_data)
        .map_err(|_| PoolV1ProgramError::InvalidVerifierReturnData)?;
    if returned != expected.expected_result || returned_data != expected.expected_result_bytes {
        return Err(PoolV1ProgramError::VerifierResultBindingMismatch.into());
    }
    Ok(())
}

fn require_exact_readonly_cpi_accounts_v1(
    plan: &PlannedVerifierDispatchV1,
    verifier_program_account: &AccountInfo<'_>,
    proof_account: &AccountInfo<'_>,
) -> Result<Pubkey, ProgramError> {
    let selected_program = Pubkey::new_from_array(plan.request_binding.verifier_program);
    require_selected_verifier_program_account(verifier_program_account, &selected_program)?;
    if proof_account.key.to_bytes() != plan.request_binding.proof_account
        || proof_account.owner != &selected_program
        || proof_account.executable
        || proof_account.is_signer
        || proof_account.is_writable
        || plan.expected_result.binding != plan.request_binding
    {
        return Err(PoolV1ProgramError::InvalidVerifierProofAccount.into());
    }
    Ok(selected_program)
}

/// Consume only a freshly constructed plan through one exact read-only CPI.
///
/// The invoking primitive is private, so an external caller cannot submit a
/// fabricated `PlannedVerifierDispatchV1`. It nevertheless rechecks the actual
/// verifier/proof identities and privileges against the plan before deriving
/// the instruction. The sole instruction meta is the nonsigning, read-only
/// sealed proof account; the executable verifier account is supplied to the
/// runtime only as the CPI program account.
fn invoke_freshly_planned_verifier_v1<'info, R: VerifierDispatchRuntimeV1>(
    plan: PlannedVerifierDispatchV1,
    verifier_program_account: &AccountInfo<'info>,
    proof_account: &AccountInfo<'info>,
    runtime: &mut R,
) -> Result<AuthenticatedVerifierDispatchV1, ProgramError> {
    let selected_program =
        require_exact_readonly_cpi_accounts_v1(&plan, verifier_program_account, proof_account)?;
    let instruction = Instruction {
        program_id: selected_program,
        accounts: vec![AccountMeta::new_readonly(*proof_account.key, false)],
        data: plan.request_bytes.clone(),
    };
    let account_infos = [proof_account.clone(), verifier_program_account.clone()];

    // This ordering is security-critical. Even though the current runtime also
    // clears return data on CPI entry, explicitly clear the Pool's buffer so a
    // successful callee that returns nothing cannot inherit an acceptable
    // stale image in either the production runtime or an equivalent harness.
    runtime.clear_return_data();
    runtime.invoke(&instruction, &account_infos)?;
    let returned = runtime
        .get_return_data()
        .ok_or(PoolV1ProgramError::MissingVerifierReturnData)?;

    authenticate_verifier_return_data_v1(&plan, &returned.0, &returned.1)?;
    Ok(AuthenticatedVerifierDispatchV1 { plan })
}

#[allow(clippy::too_many_arguments)]
fn dispatch_authenticated_verifier_readonly_with_runtime_v1<'info, R: VerifierDispatchRuntimeV1>(
    pool: &Pubkey,
    expected_deployment_domain: &[u8; 32],
    policy: &VerifierPolicyV1,
    registry_accounts: &[AccountInfo<'info>],
    verifier_program_account: &AccountInfo<'info>,
    proof_account: &AccountInfo<'info>,
    encoded_envelope: &[u8],
    statement_payload: &[u8],
    claim: VerifierDispatchClaimV1,
    current_slot: u64,
    hash: HashFn,
    runtime: &mut R,
) -> Result<AuthenticatedVerifierDispatchV1, ProgramError> {
    let plan = plan_authenticated_verifier_dispatch_v1(
        pool,
        expected_deployment_domain,
        policy,
        registry_accounts,
        verifier_program_account,
        proof_account,
        encoded_envelope,
        statement_payload,
        claim,
        current_slot,
        hash,
    )?;
    invoke_freshly_planned_verifier_v1(plan, verifier_program_account, proof_account, runtime)
}

/// Plan, invoke and authenticate one selected verifier without any Pool write.
///
/// This is a composition function rather than a standalone instruction
/// handler. The Pool entrypoint calls it with its runtime-derived identity and
/// exact top-level accounts. The selected verifier must implement the
/// separately reviewed profile-specific ASVQ handler before this path can be
/// exercised against a real proof.
#[allow(clippy::too_many_arguments)]
pub fn dispatch_authenticated_verifier_readonly_v1<'info>(
    pool: &Pubkey,
    expected_deployment_domain: &[u8; 32],
    policy: &VerifierPolicyV1,
    registry_accounts: &[AccountInfo<'info>],
    verifier_program_account: &AccountInfo<'info>,
    proof_account: &AccountInfo<'info>,
    encoded_envelope: &[u8],
    statement_payload: &[u8],
    claim: VerifierDispatchClaimV1,
    current_slot: u64,
    hash: HashFn,
) -> Result<AuthenticatedVerifierDispatchV1, ProgramError> {
    let mut runtime = SolanaVerifierDispatchRuntimeV1;
    dispatch_authenticated_verifier_readonly_with_runtime_v1(
        pool,
        expected_deployment_domain,
        policy,
        registry_accounts,
        verifier_program_account,
        proof_account,
        encoded_envelope,
        statement_payload,
        claim,
        current_slot,
        hash,
        &mut runtime,
    )
}

