    authority.is_signer = true;

    assert_eq!(
        invoke_simple(
            &program_id,
            &mut registry,
            &mut authority,
            RegistryMutationOpcodeV1::Unpause,
            4,
        ),
        Ok(())
    );
    let unpaused = decode_verifier_registry_v1(&registry.data).unwrap();
    assert!(!unpaused.is_paused());
    assert_eq!(unpaused.bump, paused.bump);
