                    let mut data = pool_handle.try_borrow_mut_data().unwrap();
                    data[POOL_ANCHOR_OFFSET..POOL_DEPLOYMENT_DOMAIN_OFFSET]
                        .copy_from_slice(&[0x5c; 32]);
