                false,
                system_id,
                true,
                true,
                false,
                11,
                8,
                ProgramError::InvalidAccountData,
            ),
            (
                program_id,
                true,
                true,
                system_id,
                true,
                false,
                false,
                11,
                8,
                ProgramError::InvalidAccountData,
            ),
            (
                program_id,
                true,
                true,
                system_id,
                true,
                true,
                true,
                11,
                8,
                ProgramError::InvalidArgument,
            ),
            (
                program_id,
                true,
                true,
                system_id,
                true,
                true,
                false,
                0,
                8,
                ProgramError::InvalidAccountData,
            ),
            (
                program_id,
                true,
                true,
                system_id,
                true,
                true,
                false,
                11,
                100,
                ProgramError::InvalidAccountData,
            ),
        ] {
            let mut proof_lamports = initial_proof_lamports;
            let mut refund_lamports = 7u64;
            let mut proof_data = [0u8; PROOF_ACCOUNT_HEADER_LEN + 8];
            proof_data[..4].copy_from_slice(&PROOF_ACCOUNT_MAGIC);
            proof_data[4..8].copy_from_slice(&(declared_len as u32).to_le_bytes());
            let proof_before = proof_data;
            let mut refund_data = [];
            {
                let proof = make_account(
                    &proof_key,
                    &proof_owner,
                    &mut proof_lamports,
                    &mut proof_data,
                    proof_signer,
                    proof_writable,
                );
                let effective_refund_key = if aliased { &proof_key } else { &refund_key };
                let refund = make_account(
                    effective_refund_key,
                    &refund_owner,
                    &mut refund_lamports,
                    &mut refund_data,
                    refund_signer,
                    refund_writable,
                );
                assert_eq!(
                    process_instruction(&program_id, &[proof, refund], &close),
                    Err(expected)
                );
            }
            assert_eq!(proof_lamports, initial_proof_lamports);
            assert_eq!(refund_lamports, 7);
            assert_eq!(proof_data, proof_before);
        }
    }

    #[test]
    fn initialize_atomic_pool_is_signed_canonical_and_one_shot() {
        let program_id = id();
        let pool_key = Pubkey::new_unique();
        let authority_key = Pubkey::new_unique();
        let mut pool_lamports = 0;
        let mut authority_lamports = 0;
        let mut pool_data = [0u8; atomic_payment::ATOMIC_POOL_STATE_LEN];
        let mut authority_data = [];
        let anchor = [0u8; 32];
        let initialize = borsh::to_vec(&AspisInstruction::InitializeAtomicPool {
            sequence: 73,
            anchor,
            domain_tag: b"devnet".to_vec(),
        })
        .unwrap();

        {
            let unsigned_pool = make_account(
                &pool_key,
                &program_id,
                &mut pool_lamports,
                &mut pool_data,
                false,
                true,
            );
            assert_eq!(
                process_instruction(&program_id, &[unsigned_pool], &initialize),
                Err(ProgramError::MissingRequiredSignature)
            );
        }
        {
            let pool = make_account(
                &pool_key,
                &program_id,
                &mut pool_lamports,
                &mut pool_data,
                true,
                true,
            );
            assert_eq!(
                process_instruction(&program_id, &[pool], &initialize),
                Ok(())
            );
        }
        assert_eq!(
            atomic_payment::AtomicPoolStateV2::decode(&pool_data).unwrap(),
            atomic_payment::AtomicPoolStateV2 {
                sequence: 73,
                anchor,
                deployment_domain: aspis_statement::atomic_deployment_domain(
                    crate::verify::sbf_hashv,
                    &program_id.to_bytes(),
                    b"devnet",
                ),
            }
        );

        // Rejected domain tags: empty and oversized both fail before any
        // account write.
        for bad_tag in [Vec::new(), vec![0x61u8; DEPLOYMENT_DOMAIN_TAG_MAX_LEN + 1]] {
            let bad_pool_key = Pubkey::new_unique();
            let mut bad_pool_lamports = 0;
            let mut bad_pool_data = [0u8; atomic_payment::ATOMIC_POOL_STATE_LEN];
            let bad_initialize = borsh::to_vec(&AspisInstruction::InitializeAtomicPool {
                sequence: 0,
                anchor,
                domain_tag: bad_tag,
            })
            .unwrap();
            let bad_pool = make_account(
                &bad_pool_key,
                &program_id,
                &mut bad_pool_lamports,
                &mut bad_pool_data,
                true,
                true,
            );
            assert_eq!(
                process_instruction(&program_id, &[bad_pool], &bad_initialize),
                Err(ProgramError::InvalidInstructionData)
            );
            assert!(bad_pool_data.iter().all(|byte| *byte == 0));
        }

        let pool = make_account(
            &pool_key,
            &program_id,
            &mut pool_lamports,
            &mut pool_data,
            true,
            true,
        );
        assert_eq!(
            process_instruction(&program_id, &[pool], &initialize),
            Err(ProgramError::InvalidAccountData)
        );

        let pool_before = pool_data;
        let init_proof = borsh::to_vec(&AspisInstruction::InitProof { total_len: 8 }).unwrap();
        let pool = make_account(
            &pool_key,
            &program_id,
            &mut pool_lamports,
            &mut pool_data,
            true,
            true,
        );
        let authority = make_account(
            &authority_key,
            &program_id,
            &mut authority_lamports,
            &mut authority_data,
            true,
            false,
        );
        assert_eq!(
            process_instruction(&program_id, &[pool, authority], &init_proof),
            Err(ProgramError::InvalidAccountData),
            "an initialized pool must not be retyped as a proof account"
        );
        assert_eq!(pool_data, pool_before);

        let overflow_pool_key = Pubkey::new_unique();
        let mut overflow_pool_lamports = 0;
        let mut overflow_pool_data = [0u8; atomic_payment::ATOMIC_POOL_STATE_LEN];
        let overflow_initialize = borsh::to_vec(&AspisInstruction::InitializeAtomicPool {
            sequence: u64::MAX,
            anchor,
            domain_tag: b"devnet".to_vec(),
        })
        .unwrap();
        let overflow_pool = make_account(
            &overflow_pool_key,
            &program_id,
            &mut overflow_pool_lamports,
            &mut overflow_pool_data,
            true,
            true,
        );
        assert_eq!(
            process_instruction(&program_id, &[overflow_pool], &overflow_initialize),
            Err(ProgramError::ArithmeticOverflow)
        );
        assert!(overflow_pool_data.iter().all(|byte| *byte == 0));
    }
}

//! Never-production R0 diagnostic, tag 241. Both accounts are read-only:
//! [sealed ASPU proof, canonical ASF8 public context]. No checks are disabled.
use aspis_statement::{
    pool_v1::{
        decode_pool_v1_pair_forest_terminal_statement_v1,
        pair_forest_semantic_terminal::r0::Public, PoolV1PairForestTerminalStatementV1,
    },
    r0::{r0_verify, Phase},
};
use solana_program::{
    account_info::AccountInfo, entrypoint::ProgramResult, hash::hashv, log::sol_log_compute_units,
    msg, program_error::ProgramError, pubkey::Pubkey,
};

/// Matched by request_heap_frame(256 KiB) in the local measurement harness.
#[cfg(target_os = "solana")]
#[global_allocator]
static ALLOCATOR: solana_program::entrypoint::BumpAllocator =
    solana_program::entrypoint::BumpAllocator {
        start: solana_program::entrypoint::HEAP_START_ADDRESS as usize,
        len: 256 * 1024,
    };

pub const R0_CU_PROBE_TAG: u8 = 241;
#[cfg(not(feature = "no-entrypoint"))]
solana_program::entrypoint!(process_r0_cu_probe_instruction);

#[inline(never)]
fn trace(phase: Phase) {
    match phase {
        Phase::Parsed => msg!("r0:parsed"),
        Phase::Semantic => msg!("r0:semantic"),
        Phase::ChordClaims => msg!("r0:chord-claims"),
        Phase::V2 => msg!("r0:v2"),
        Phase::Merkle(i) => msg!("r0:merkle:{}", i),
        Phase::V1(i) => msg!("r0:v1:{}", i),
    }
    sol_log_compute_units();
}
pub fn process_r0_cu_probe_instruction(
    program_id: &Pubkey,
    accounts: &[AccountInfo],
    data: &[u8],
) -> ProgramResult {
    if data != [R0_CU_PROBE_TAG] {
        return Err(ProgramError::InvalidInstructionData);
    }
    if accounts.len() != 2 {
        return Err(ProgramError::NotEnoughAccountKeys);
    }
    for account in accounts {
        if account.owner != program_id || account.is_writable || account.executable {
            return Err(ProgramError::InvalidAccountData);
        }
    }
    let bytes = accounts[0].try_borrow_data()?;
    if !crate::lifecycle::proof_account_finalized(&bytes) {
        return Err(ProgramError::InvalidAccountData);
    }
    let (start, end) = crate::lifecycle::uploaded_proof_bounds(&bytes)?;
    if end != bytes.len() {
        return Err(ProgramError::InvalidAccountData);
    }
    let public_bytes = accounts[1].try_borrow_data()?;
    let statement = decode_pool_v1_pair_forest_terminal_statement_v1(&public_bytes)
        .map_err(|_| ProgramError::InvalidInstructionData)?;
    let public = match &statement {
        PoolV1PairForestTerminalStatementV1::PrivateTransfer { common, public } => {
            Public::Transfer(public, &common.lane_transition)
        }
        PoolV1PairForestTerminalStatementV1::Withdrawal { common, public } => {
            Public::Withdrawal(public, &common.lane_transition)
        }
    };
    msg!("r0:begin");
    sol_log_compute_units();
    r0_verify(
        public,
        &bytes[start..end],
        |p| hashv(p).to_bytes(),
        Some(trace),
    )
    .map_err(|e| {
        msg!("r0:error:{:?}", e);
        ProgramError::InvalidInstructionData
    })?;
    #[cfg(target_os = "solana")]
    unsafe {
        let cursor = *(solana_program::entrypoint::HEAP_START_ADDRESS as *const usize);
        // Non-allocating logging preserves the final bump high-water mark.
        msg!("r0:heap-high-water");
        solana_program::log::sol_log_64(
            (solana_program::entrypoint::HEAP_START_ADDRESS as usize + 256 * 1024 - cursor
                + core::mem::size_of::<usize>()) as u64,
            0,
            0,
            0,
            0,
        );
    }
    msg!("r0:done");
    sol_log_compute_units();
    Ok(())
}

