                let expected = evaluations[usize::from(selected)];
                assert_eq!(
                    actual,
                    if expected {
                        Ok(selected)
                    } else {
                        Err(ProgramError::InvalidAccountData)
                    },
                    "selector {selected}, bits {bits:03b}"
                );
                assert_eq!(
                    derived,
                    core::array::from_fn(|candidate| candidate == usize::from(selected))
                );
                assert_eq!(
                    evaluated,
                    core::array::from_fn(|candidate| candidate == usize::from(selected))
                );
                selected += 1;
            }
            bits += 1;
        }
    }

