//! Five-section private-opening grammar for V5.
//!
//! The earlier production helper fixes C1 at 416 bytes. V5 keeps the same query
//! universe, depths, tree tags, C2 width, and three later-tree widths, but its
//! real sixteen-lane C1 leaf is 256 bytes. The production verifier and local CU
//! probe share this grammar and the public `aspis-core` authentication
//! primitives.

use aspis_core::circle_line_merkle::{
    derive_circle_line_query_indices_for_count, CircleLineMerkleError, CircleLineQueryIndices,
    CIRCLE_LINE_TAGS,
};
use aspis_core::circle_merkle::{CIRCLE_C1_LAYER0_TAG, CIRCLE_C2_LAYER0_TAG};
use aspis_core::merkle::Radix4BinaryCapTopology;
use aspis_core::state_only_private_openings::{
    verify_state_only_private_opening_from_proof_with_topology, StateOnlyPrivateOpening,
    StateOnlyPrivateOpeningError,
};
use aspis_core::HashFn;

pub const V5_PRIVATE_LAYER0_LEAVES: usize = 1 << 17;
pub const V5_PRIVATE_SECTION_COUNT: usize = 5;
pub const V5_PRIVATE_DEPTHS: [u32; V5_PRIVATE_SECTION_COUNT] = [17, 17, 15, 13, 11];
pub const V5_PRIVATE_VALUE_WIDTHS: [usize; V5_PRIVATE_SECTION_COUNT] = [256, 192, 64, 64, 64];
pub const V5_PRIVATE_TREE_TAGS: [u8; V5_PRIVATE_SECTION_COUNT] = [
    CIRCLE_C1_LAYER0_TAG,
    CIRCLE_C2_LAYER0_TAG,
    CIRCLE_LINE_TAGS[0],
    CIRCLE_LINE_TAGS[1],
    CIRCLE_LINE_TAGS[2],
];

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct V5PrivateOpeningRoots {
    pub c1: [u8; 32],
    pub c2: [u8; 32],
    pub later: [[u8; 32]; 3],
}

impl V5PrivateOpeningRoots {
    fn as_array(self) -> [[u8; 32]; V5_PRIVATE_SECTION_COUNT] {
        [
            self.c1,
            self.c2,
            self.later[0],
            self.later[1],
            self.later[2],
        ]
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum V5PrivateOpeningError {
    Query(CircleLineMerkleError),
    Section {
        section: u8,
        error: StateOnlyPrivateOpeningError,
    },
    TrailingBytes {
        offset: usize,
        remaining: usize,
    },
    InvalidSharedTopology,
}

impl From<CircleLineMerkleError> for V5PrivateOpeningError {
    fn from(error: CircleLineMerkleError) -> Self {
        Self::Query(error)
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct VerifiedV5PrivateOpenings<'a> {
    pub c1: StateOnlyPrivateOpening<'a>,
    pub c2: StateOnlyPrivateOpening<'a>,
    pub later: [StateOnlyPrivateOpening<'a>; 3],
    pub indices: CircleLineQueryIndices,
    pub bytes_consumed: usize,
}

/// Authenticate five canonical sections at the transcript-derived queries and
/// return the unconsumed proof suffix.  Query indices are never proof bytes.
pub fn verify_v5_private_openings_from_proof<'a>(
    hash: HashFn,
    roots: &V5PrivateOpeningRoots,
    queries: &[u32],
    proof_bytes: &'a [u8],
) -> Result<(VerifiedV5PrivateOpenings<'a>, &'a [u8]), V5PrivateOpeningError> {
    let indices = derive_circle_line_query_indices_for_count(queries, V5_PRIVATE_LAYER0_LEAVES)?;
    let section_indices: [&[u32]; V5_PRIVATE_SECTION_COUNT] = [
        &indices.layer0,
        &indices.layer0,
        &indices.later[0],
        &indices.later[1],
        &indices.later[2],
    ];
    let roots = roots.as_array();
    let topology = Radix4BinaryCapTopology::new(V5_PRIVATE_DEPTHS[0], &indices.layer0)
        .ok_or(V5PrivateOpeningError::InvalidSharedTopology)?;
    let mut hash_level = Vec::<[u8; 32]>::with_capacity(indices.layer0.len());
    let mut hash_next = Vec::<[u8; 32]>::with_capacity(indices.layer0.len());
    let mut remainder = proof_bytes;
    let mut parsed = [None; V5_PRIVATE_SECTION_COUNT];
    for section in 0..V5_PRIVATE_SECTION_COUNT {
        let (opening, next) = verify_state_only_private_opening_from_proof_with_topology(
            hash,
            &roots[section],
            V5_PRIVATE_DEPTHS[section],
            V5_PRIVATE_TREE_TAGS[section],
            V5_PRIVATE_VALUE_WIDTHS[section],
            section_indices[section],
            remainder,
            &topology,
            if section < 2 { 0 } else { section - 1 },
            &mut hash_level,
            &mut hash_next,
        )
        .map_err(|error| V5PrivateOpeningError::Section {
            section: section as u8,
            error,
        })?;
        parsed[section] = Some(opening);
        remainder = next;
    }
    let bytes_consumed = proof_bytes.len() - remainder.len();
    Ok((
        VerifiedV5PrivateOpenings {
            c1: parsed[0].unwrap(),
            c2: parsed[1].unwrap(),
            later: [parsed[2].unwrap(), parsed[3].unwrap(), parsed[4].unwrap()],
            indices,
            bytes_consumed,
        },
        remainder,
    ))
}

/// Authenticate exactly the five private sections and reject a trailing byte.
pub fn verify_v5_private_openings<'a>(
    hash: HashFn,
    roots: &V5PrivateOpeningRoots,
    queries: &[u32],
    proof_bytes: &'a [u8],
) -> Result<VerifiedV5PrivateOpenings<'a>, V5PrivateOpeningError> {
    let (verified, remainder) =
        verify_v5_private_openings_from_proof(hash, roots, queries, proof_bytes)?;
    if !remainder.is_empty() {
        return Err(V5PrivateOpeningError::TrailingBytes {
            offset: verified.bytes_consumed,
            remaining: remainder.len(),
        });
    }
    Ok(verified)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn v5_changes_only_the_c1_private_width() {
        assert_eq!(V5_PRIVATE_DEPTHS, [17, 17, 15, 13, 11]);
        assert_eq!(V5_PRIVATE_VALUE_WIDTHS, [256, 192, 64, 64, 64]);
        assert_eq!(V5_PRIVATE_SECTION_COUNT, 5);
    }
}

programs/aspis-verifier/src/v5_relation_:
//! V5-only stress path for the complete four-round PCS relation algebra.
//!
//! This module deliberately owns no production dispatch.  It parses a fixed
//! payload, adds both OOD observations at each round, checks the relation
//! sumcheck boundary, advances the running claim, dual-folds the public
//! covector, and checks the disclosed final polynomial.  The local-validator
//! composite calls it after constructing the v5 relation accumulator.

use aspis_core::circle::SecureCirclePoint;
use aspis_core::field::QM31;
use aspis_core::sumcheck::{
    boundary_sum, evaluate, SumcheckPolynomial, TensorWeightError, WeightAccumulator,
    SUMCHECK_COEFFICIENTS,
};

pub const V5_RELATION_STRESS_ROUNDS: usize = 4;
pub const V5_RELATION_STRESS_OOD_SAMPLES: usize = 2;
pub const V5_RELATION_STRESS_FINAL_COEFFICIENTS: usize = 4;
const QM31_BYTES: usize = 16;

const CIRCLE_COORDINATES: usize = 2 * V5_RELATION_STRESS_OOD_SAMPLES;
const LINE_POINTS: usize = (V5_RELATION_STRESS_ROUNDS - 1) * V5_RELATION_STRESS_OOD_SAMPLES;
const OOD_VALUES: usize = V5_RELATION_STRESS_ROUNDS * V5_RELATION_STRESS_OOD_SAMPLES;
const OOD_MIXES: usize = OOD_VALUES;
const SUMCHECK_VALUES: usize = V5_RELATION_STRESS_ROUNDS * SUMCHECK_COEFFICIENTS;

pub const V5_RELATION_STRESS_CIRCLE_OFFSET: usize = 0;
pub const V5_RELATION_STRESS_LINE_OFFSET: usize =
    V5_RELATION_STRESS_CIRCLE_OFFSET + CIRCLE_COORDINATES * QM31_BYTES;
pub const V5_RELATION_STRESS_OOD_OFFSET: usize =
    V5_RELATION_STRESS_LINE_OFFSET + LINE_POINTS * QM31_BYTES;
pub const V5_RELATION_STRESS_MIX_OFFSET: usize =
    V5_RELATION_STRESS_OOD_OFFSET + OOD_VALUES * QM31_BYTES;
pub const V5_RELATION_STRESS_SUMCHECK_OFFSET: usize =
    V5_RELATION_STRESS_MIX_OFFSET + OOD_MIXES * QM31_BYTES;
pub const V5_RELATION_STRESS_FINAL_OFFSET: usize =
    V5_RELATION_STRESS_SUMCHECK_OFFSET + SUMCHECK_VALUES * QM31_BYTES;
pub const V5_RELATION_STRESS_BYTES: usize =
    V5_RELATION_STRESS_FINAL_OFFSET + V5_RELATION_STRESS_FINAL_COEFFICIENTS * QM31_BYTES;

const _: () = assert!(V5_RELATION_STRESS_BYTES == 928);

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum V5RelationStressError {
    NonCanonicalField { offset: usize },
    InvalidCirclePoint { sample: usize },
    ZeroMix { round: usize, sample: usize },
    ZeroAlpha { round: usize },
    WeightShape(TensorWeightError),
    BoundaryMismatch { round: usize },
    TerminalMismatch,
}

impl From<TensorWeightError> for V5RelationStressError {
    fn from(error: TensorWeightError) -> Self {
        Self::WeightShape(error)
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct VerifiedV5RelationStress {
    pub final_coefficients: [QM31; V5_RELATION_STRESS_FINAL_COEFFICIENTS],
    pub terminal_claim: QM31,
}

/// A structured public covector which shares the relation's four dual folds
/// without being materialized inside [`WeightAccumulator`].  Component B's
/// compact degree-27 weights implement this interface in the composite probe.
pub trait V5RelationStressAdditive {
    fn fold(&mut self, alpha: QM31);
    fn dot(&self, final_coefficients: &[QM31; V5_RELATION_STRESS_FINAL_COEFFICIENTS]) -> QM31;
}

#[derive(Clone, Copy, Default)]
struct NoAdditiveWeights;

impl V5RelationStressAdditive for NoAdditiveWeights {
    #[inline(always)]
    fn fold(&mut self, _alpha: QM31) {}

    #[inline(always)]
    fn dot(&self, _final_coefficients: &[QM31; V5_RELATION_STRESS_FINAL_COEFFICIENTS]) -> QM31 {
        QM31::ZERO
    }
}

fn decode_qm31(
    bytes: &[u8; V5_RELATION_STRESS_BYTES],
    offset: usize,
) -> Result<QM31, V5RelationStressError> {
    QM31::from_le_bytes(&bytes[offset..offset + QM31_BYTES])
        .ok_or(V5RelationStressError::NonCanonicalField { offset })
}

fn decode_indexed(
    bytes: &[u8; V5_RELATION_STRESS_BYTES],
    offset: usize,
    index: usize,
) -> Result<QM31, V5RelationStressError> {
    decode_qm31(bytes, offset + index * QM31_BYTES)
}

/// Decode the final polynomial without running the relation checks.  The
/// later-FRI checker uses this to consume exactly the coefficients accepted
/// by [`verify_v5_relation_stress`].
pub fn decode_v5_relation_stress_final(
    bytes: &[u8; V5_RELATION_STRESS_BYTES],
) -> Result<[QM31; V5_RELATION_STRESS_FINAL_COEFFICIENTS], V5RelationStressError> {
    let mut final_coefficients = [QM31::ZERO; V5_RELATION_STRESS_FINAL_COEFFICIENTS];
    for (index, output) in final_coefficients.iter_mut().enumerate() {
        *output = decode_indexed(bytes, V5_RELATION_STRESS_FINAL_OFFSET, index)?;
    }
    Ok(final_coefficients)
}

/// Execute the exact production relation work over caller-supplied initial
/// weights and claim.  The four alphas are transcript outputs supplied by the
/// composite; they are not proof-carried by this payload.
pub fn verify_v5_relation_stress(
    weights: WeightAccumulator,
    running_claim: QM31,
    alphas: [QM31; V5_RELATION_STRESS_ROUNDS],
    bytes: &[u8; V5_RELATION_STRESS_BYTES],
) -> Result<VerifiedV5RelationStress, V5RelationStressError> {
    verify_v5_relation_stress_with_additive(
        weights,
        running_claim,
        alphas,
        bytes,
        NoAdditiveWeights,
    )
}

/// Execute the same relation while carrying one compact additive covector
/// through the identical folds and terminal dot.  This is the exact v5
/// composition: the main point/copy weights and Component B share one set of
/// OOD additions, sumcheck checks, folds, and final coefficients.
pub fn verify_v5_relation_stress_with_additive<A: V5RelationStressAdditive>(
    mut weights: WeightAccumulator,
    mut running_claim: QM31,
    alphas: [QM31; V5_RELATION_STRESS_ROUNDS],
    bytes: &[u8; V5_RELATION_STRESS_BYTES],
    mut additive: A,
) -> Result<VerifiedV5RelationStress, V5RelationStressError> {
    let mut circle_points = [SecureCirclePoint {
        x: QM31::ZERO,
        y: QM31::ZERO,
    }; V5_RELATION_STRESS_OOD_SAMPLES];
    for (sample, point) in circle_points.iter_mut().enumerate() {
        point.x = decode_indexed(bytes, V5_RELATION_STRESS_CIRCLE_OFFSET, 2 * sample)?;
        point.y = decode_indexed(bytes, V5_RELATION_STRESS_CIRCLE_OFFSET, 2 * sample + 1)?;
        if point.x.square().add(point.y.square()) != QM31::ONE {
            return Err(V5RelationStressError::InvalidCirclePoint { sample });
        }
    }
    for (round, alpha) in alphas.into_iter().enumerate() {
        for sample in 0..V5_RELATION_STRESS_OOD_SAMPLES {
            let observation = round * V5_RELATION_STRESS_OOD_SAMPLES + sample;
            let value = decode_indexed(bytes, V5_RELATION_STRESS_OOD_OFFSET, observation)?;
            let mix = decode_indexed(bytes, V5_RELATION_STRESS_MIX_OFFSET, observation)?;
            if round == 0 {
                weights.add_circle_tensor(mix, circle_points[sample])?;
            } else {
                let line_index = (round - 1) * V5_RELATION_STRESS_OOD_SAMPLES + sample;
                let point = decode_indexed(bytes, V5_RELATION_STRESS_LINE_OFFSET, line_index)?;
                weights.add_line_tensor(mix, point)?;
            }
            running_claim = running_claim.add(mix.mul(value));
        }
        let mut polynomial: SumcheckPolynomial = [QM31::ZERO; SUMCHECK_COEFFICIENTS];
        for (coefficient, output) in polynomial.iter_mut().enumerate() {
            *output = decode_indexed(
                bytes,
                V5_RELATION_STRESS_SUMCHECK_OFFSET,
                round * SUMCHECK_COEFFICIENTS + coefficient,
            )?;
        }
        if boundary_sum(&polynomial) != running_claim {
            return Err(V5RelationStressError::BoundaryMismatch { round });
        }
        running_claim = evaluate(&polynomial, alpha);
        weights.fold(alpha);
        additive.fold(alpha);
    }

    let final_coefficients = decode_v5_relation_stress_final(bytes)?;
    if weights
        .dot(&final_coefficients)
        .add(additive.dot(&final_coefficients))
        != running_claim
    {
        return Err(V5RelationStressError::TerminalMismatch);
    }
    Ok(VerifiedV5RelationStress {
        final_coefficients,
        terminal_claim: running_claim,
    })
}

#[cfg(not(target_os = "solana"))]
pub fn build_v5_relation_stress_tail_for_initial_claim(
    initial_claim: QM31,
    alphas: [QM31; V5_RELATION_STRESS_ROUNDS],
) -> [u8; V5_RELATION_STRESS_BYTES] {
    use aspis_core::circle::secure_ood_circle_point_from_parameter;
    use aspis_core::field::{CM31, M31};

    fn q(seed: u32) -> QM31 {
        QM31 {
            c0: CM31::new(M31(seed), M31(seed + 1)),
            c1: CM31::new(M31(seed + 2), M31(seed + 3)),
        }
    }
    fn write(output: &mut [u8], offset: usize, value: QM31) {
        value.write_le_bytes(&mut output[offset..offset + QM31_BYTES]);
    }

    let mut output = [0u8; V5_RELATION_STRESS_BYTES];
    for sample in 0..V5_RELATION_STRESS_OOD_SAMPLES {
        let point = secure_ood_circle_point_from_parameter(q(17 + 8 * sample as u32))
            .expect("fixed v5 stress circle parameter is nonsingular and out of domain");
        write(
            &mut output,
            V5_RELATION_STRESS_CIRCLE_OFFSET + (2 * sample) * QM31_BYTES,
            point.x,
        );
        write(
            &mut output,
            V5_RELATION_STRESS_CIRCLE_OFFSET + (2 * sample + 1) * QM31_BYTES,
            point.y,
        );
    }
    for index in 0..LINE_POINTS {
        write(
            &mut output,
            V5_RELATION_STRESS_LINE_OFFSET + index * QM31_BYTES,
            q(101 + 8 * index as u32),
        );
    }
    for index in 0..OOD_MIXES {
        write(
            &mut output,
            V5_RELATION_STRESS_MIX_OFFSET + index * QM31_BYTES,
            q(211 + 8 * index as u32),
        );
    }

    // The relation boundary is the arity-four identity
    // `4 * (c0 + c4) = initial_claim`.  Map that claim to zero at alpha0 so
    // the remaining three messages and final4 can stay canonical zero.  The
    // alpha-zero branch uses c4 because X^4 vanishes at zero; otherwise c1
    // cancels c0 at alpha0 without changing the boundary.
    let boundary_quarter = initial_claim.half().half();
    if alphas[0].is_zero() {
        write(
            &mut output,
            V5_RELATION_STRESS_SUMCHECK_OFFSET + 4 * QM31_BYTES,
            boundary_quarter,
        );
    } else {
        write(
            &mut output,
            V5_RELATION_STRESS_SUMCHECK_OFFSET,
            boundary_quarter,
        );
        let cancellation = QM31::ZERO.sub(
            boundary_quarter.mul(
                alphas[0]
                    .try_inv()
                    .expect("nonzero QM31 alpha has an inverse"),
            ),
        );
        write(
            &mut output,
            V5_RELATION_STRESS_SUMCHECK_OFFSET + QM31_BYTES,
            cancellation,
        );
    }
    // OOD values, the later three sumcheck messages, and final4 remain zero.
    output
}

#[cfg(not(target_os = "solana"))]
pub fn build_zero_v5_relation_stress_tail() -> [u8; V5_RELATION_STRESS_BYTES] {
    build_v5_relation_stress_tail_for_initial_claim(
        QM31::ZERO,
        [QM31::ONE; V5_RELATION_STRESS_ROUNDS],
    )
}

#[cfg(test)]
mod tests {
    use super::*;
    use aspis_core::field::{CM31, M31};

    fn q(value: u32) -> QM31 {
        QM31::from_cm31(CM31::from_m31(M31(value)))
    }

    #[test]
    fn zero_stress_tail_roundtrips_and_boundary_corruption_rejects() {
        let alphas = [q(3), q(5), q(7), q(11)];
        let mut tail = build_zero_v5_relation_stress_tail();
        let verified =
            verify_v5_relation_stress(WeightAccumulator::empty(10), QM31::ZERO, alphas, &tail)
                .unwrap();
        assert_eq!(verified.final_coefficients, [QM31::ZERO; 4]);
        assert_eq!(verified.terminal_claim, QM31::ZERO);

        q(1).write_le_bytes(
            &mut tail[V5_RELATION_STRESS_SUMCHECK_OFFSET
                ..V5_RELATION_STRESS_SUMCHECK_OFFSET + QM31_BYTES],
        );
        assert_eq!(
            verify_v5_relation_stress(WeightAccumulator::empty(10), QM31::ZERO, alphas, &tail,),
            Err(V5RelationStressError::BoundaryMismatch { round: 0 })
        );
    }

    #[test]
    fn arbitrary_initial_claim_is_mapped_to_zero_for_nonzero_and_zero_alpha() {
        let initial = q(29);
        for alphas in [[q(3), q(5), q(7), q(11)], [QM31::ZERO, q(5), q(7), q(11)]] {
            let tail = build_v5_relation_stress_tail_for_initial_claim(initial, alphas);
            let verified =
                verify_v5_relation_stress(WeightAccumulator::empty(10), initial, alphas, &tail)
                    .unwrap();
            assert_eq!(verified.final_coefficients, [QM31::ZERO; 4]);
            assert_eq!(verified.terminal_claim, QM31::ZERO);
        }
    }
}

//! Isolated, fixed-width stress wire for the v5 PCS relation verifier.
//!
//! This checker executes the production relation kernel in its deployed
//! order: two circle OOD claims are mixed into round zero, two line OOD
//! claims are mixed into each later round, each degree-six sumcheck message
//! is checked and evaluated, the public covector is dual-folded, and the
//! resulting four weights are checked against the final tensor polynomial.
//! The payload is deliberately separate from every production proof grammar.

use aspis_core::circle::SecureCirclePoint;
use aspis_core::circle_fri::FIXED_TRACE_LOG_SIZE;
use aspis_core::field::QM31;
use aspis_core::sumcheck::{
    boundary_sum, evaluate, SumcheckPolynomial, TensorWeightError, WeightAccumulator,
    SUMCHECK_COEFFICIENTS,
};

pub const V5_RELATION_STRESS_MAGIC: [u8; 8] = *b"AV5REL01";
pub const V5_RELATION_STRESS_ROUNDS: usize = 4;
pub const V5_RELATION_STRESS_SAMPLES: usize = 2;
pub const V5_RELATION_STRESS_FINAL_COEFFICIENTS: usize = 4;

const QM31_BYTES: usize = 16;
const CIRCLE_POINT_VALUES: usize = V5_RELATION_STRESS_SAMPLES * 2;
const LINE_POINT_VALUES: usize = (V5_RELATION_STRESS_ROUNDS - 1) * V5_RELATION_STRESS_SAMPLES;
const MIX_VALUES: usize = V5_RELATION_STRESS_ROUNDS * V5_RELATION_STRESS_SAMPLES;
const ALPHA_VALUES: usize = V5_RELATION_STRESS_ROUNDS;
const OOD_VALUES: usize = V5_RELATION_STRESS_ROUNDS * V5_RELATION_STRESS_SAMPLES;
const SUMCHECK_VALUES: usize = V5_RELATION_STRESS_ROUNDS * SUMCHECK_COEFFICIENTS;

pub const V5_RELATION_STRESS_INITIAL_CLAIM_OFFSET: usize = V5_RELATION_STRESS_MAGIC.len();
pub const V5_RELATION_STRESS_CIRCLE_POINTS_OFFSET: usize =
    V5_RELATION_STRESS_INITIAL_CLAIM_OFFSET + QM31_BYTES;
pub const V5_RELATION_STRESS_LINE_POINTS_OFFSET: usize =
    V5_RELATION_STRESS_CIRCLE_POINTS_OFFSET + CIRCLE_POINT_VALUES * QM31_BYTES;
pub const V5_RELATION_STRESS_MIXES_OFFSET: usize =
    V5_RELATION_STRESS_LINE_POINTS_OFFSET + LINE_POINT_VALUES * QM31_BYTES;
pub const V5_RELATION_STRESS_ALPHAS_OFFSET: usize =
    V5_RELATION_STRESS_MIXES_OFFSET + MIX_VALUES * QM31_BYTES;
pub const V5_RELATION_STRESS_OOD_VALUES_OFFSET: usize =
    V5_RELATION_STRESS_ALPHAS_OFFSET + ALPHA_VALUES * QM31_BYTES;
pub const V5_RELATION_STRESS_SUMCHECKS_OFFSET: usize =
    V5_RELATION_STRESS_OOD_VALUES_OFFSET + OOD_VALUES * QM31_BYTES;
pub const V5_RELATION_STRESS_FINAL_OFFSET: usize =
    V5_RELATION_STRESS_SUMCHECKS_OFFSET + SUMCHECK_VALUES * QM31_BYTES;
pub const V5_RELATION_STRESS_BYTES: usize =
    V5_RELATION_STRESS_FINAL_OFFSET + V5_RELATION_STRESS_FINAL_COEFFICIENTS * QM31_BYTES;

const _: () = assert!(FIXED_TRACE_LOG_SIZE == 10);
const _: () = assert!(V5_RELATION_STRESS_BYTES == 1_016);

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum V5RelationStressError {
    WrongLength,
    WrongMagic,
    NonCanonicalField { value: usize },
    WeightShape(TensorWeightError),
    BoundaryMismatch { round: usize },
    TerminalMismatch,
}

impl From<TensorWeightError> for V5RelationStressError {
    fn from(error: TensorWeightError) -> Self {
        Self::WeightShape(error)
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct V5RelationStressSink {
    pub terminal_claim: QM31,
    pub terminal_dot: QM31,
}

fn decode_qm31(payload: &[u8], offset: usize, value: usize) -> Result<QM31, V5RelationStressError> {
    QM31::from_le_bytes(
        payload
            .get(offset..offset + QM31_BYTES)
            .ok_or(V5RelationStressError::WrongLength)?,
    )
    .ok_or(V5RelationStressError::NonCanonicalField { value })
}

/// Execute the exact four-round OOD/relation/final-tensor arithmetic over a
/// fixed-size canonical payload. No transcript state or production proof tag
/// is accepted here; the caller must bind this stress record separately.
pub fn verify_v5_relation_stress_payload(
    payload: &[u8],
) -> Result<V5RelationStressSink, V5RelationStressError> {
    if payload.len() != V5_RELATION_STRESS_BYTES {
        return Err(V5RelationStressError::WrongLength);
    }
    if payload[..V5_RELATION_STRESS_MAGIC.len()] != V5_RELATION_STRESS_MAGIC {
        return Err(V5RelationStressError::WrongMagic);
    }

    let mut field_index = 0usize;
    let mut decode = |offset| {
        let result = decode_qm31(payload, offset, field_index);
        field_index += 1;
        result
    };

    let mut running_claim = decode(V5_RELATION_STRESS_INITIAL_CLAIM_OFFSET)?;
    let mut circle_points = [SecureCirclePoint {
        x: QM31::ZERO,
        y: QM31::ZERO,
    }; V5_RELATION_STRESS_SAMPLES];
    for (sample, point) in circle_points.iter_mut().enumerate() {
        let start = V5_RELATION_STRESS_CIRCLE_POINTS_OFFSET + sample * 2 * QM31_BYTES;
        point.x = decode(start)?;
        point.y = decode(start + QM31_BYTES)?;
    }

    let mut line_points = [[QM31::ZERO; V5_RELATION_STRESS_SAMPLES]; V5_RELATION_STRESS_ROUNDS - 1];
    for (round, points) in line_points.iter_mut().enumerate() {
        for (sample, point) in points.iter_mut().enumerate() {
            let ordinal = round * V5_RELATION_STRESS_SAMPLES + sample;
            *point = decode(V5_RELATION_STRESS_LINE_POINTS_OFFSET + ordinal * QM31_BYTES)?;
        }
    }

    let mut mixes = [[QM31::ZERO; V5_RELATION_STRESS_SAMPLES]; V5_RELATION_STRESS_ROUNDS];
    for (round, round_mixes) in mixes.iter_mut().enumerate() {
        for (sample, mix) in round_mixes.iter_mut().enumerate() {
            let ordinal = round * V5_RELATION_STRESS_SAMPLES + sample;
            *mix = decode(V5_RELATION_STRESS_MIXES_OFFSET + ordinal * QM31_BYTES)?;
        }
    }

    let mut alphas = [QM31::ZERO; V5_RELATION_STRESS_ROUNDS];
    for (round, alpha) in alphas.iter_mut().enumerate() {
        *alpha = decode(V5_RELATION_STRESS_ALPHAS_OFFSET + round * QM31_BYTES)?;
    }

    let mut ood_values = [[QM31::ZERO; V5_RELATION_STRESS_SAMPLES]; V5_RELATION_STRESS_ROUNDS];
    for (round, values) in ood_values.iter_mut().enumerate() {
        for (sample, output) in values.iter_mut().enumerate() {
            let ordinal = round * V5_RELATION_STRESS_SAMPLES + sample;
            *output = decode(V5_RELATION_STRESS_OOD_VALUES_OFFSET + ordinal * QM31_BYTES)?;
        }
    }

    let mut sumchecks = [[QM31::ZERO; SUMCHECK_COEFFICIENTS]; V5_RELATION_STRESS_ROUNDS];
    for (round, polynomial) in sumchecks.iter_mut().enumerate() {
        for (coefficient, output) in polynomial.iter_mut().enumerate() {
            let ordinal = round * SUMCHECK_COEFFICIENTS + coefficient;
            *output = decode(V5_RELATION_STRESS_SUMCHECKS_OFFSET + ordinal * QM31_BYTES)?;
        }
    }

    let mut final_coefficients = [QM31::ZERO; V5_RELATION_STRESS_FINAL_COEFFICIENTS];
    for (coefficient, output) in final_coefficients.iter_mut().enumerate() {
        *output = decode(V5_RELATION_STRESS_FINAL_OFFSET + coefficient * QM31_BYTES)?;
    }

    let mut weights = WeightAccumulator::empty(FIXED_TRACE_LOG_SIZE);
    for round in 0..V5_RELATION_STRESS_ROUNDS {
        for sample in 0..V5_RELATION_STRESS_SAMPLES {
            let mix = mixes[round][sample];
            if round == 0 {
                weights.add_circle_tensor(mix, circle_points[sample])?;
            } else {
                weights.add_line_tensor(mix, line_points[round - 1][sample])?;
            }
            running_claim = running_claim.add(mix.mul(ood_values[round][sample]));
        }

        let polynomial: SumcheckPolynomial = sumchecks[round];
        if boundary_sum(&polynomial) != running_claim {
            return Err(V5RelationStressError::BoundaryMismatch { round });
        }
        running_claim = evaluate(&polynomial, alphas[round]);
        weights.fold(alphas[round]);
    }

    let terminal_dot = weights.dot(&final_coefficients);
    if terminal_dot != running_claim {
        return Err(V5RelationStressError::TerminalMismatch);
    }
    Ok(V5RelationStressSink {
        terminal_claim: running_claim,
        terminal_dot,
    })
}

/// Build one deterministic accepting host record. The points, mixing
/// challenges, and fold challenges are all nonzero. The circle samples use
/// the same rational OOD parameterization as production. Zero claims and
/// messages make the acceptance witness transparent while retaining every
/// tensor-construction, sumcheck, fold, and final-dot operation.
#[cfg(not(target_os = "solana"))]
pub fn build_deterministic_v5_relation_stress_payload() -> Vec<u8> {
    use aspis_core::circle::secure_ood_circle_point_from_parameter;
    use aspis_core::field::{CM31, M31};

    fn q(seed: u32) -> QM31 {
        QM31 {
            c0: CM31::new(M31(seed), M31(seed + 1)),
            c1: CM31::new(M31(seed + 2), M31(seed + 3)),
        }
    }

    fn write(output: &mut [u8], offset: usize, value: QM31) {
        value.write_le_bytes(&mut output[offset..offset + QM31_BYTES]);
    }

    let mut output = vec![0u8; V5_RELATION_STRESS_BYTES];
    output[..V5_RELATION_STRESS_MAGIC.len()].copy_from_slice(&V5_RELATION_STRESS_MAGIC);
    write(
        &mut output,
        V5_RELATION_STRESS_INITIAL_CLAIM_OFFSET,
        QM31::ZERO,
    );

    for sample in 0..V5_RELATION_STRESS_SAMPLES {
        let point = secure_ood_circle_point_from_parameter(q(100 + 20 * sample as u32))
            .expect("pinned non-singular secure OOD parameter");
        let start = V5_RELATION_STRESS_CIRCLE_POINTS_OFFSET + sample * 2 * QM31_BYTES;
        write(&mut output, start, point.x);
        write(&mut output, start + QM31_BYTES, point.y);
    }
    for ordinal in 0..LINE_POINT_VALUES {
        write(
            &mut output,
            V5_RELATION_STRESS_LINE_POINTS_OFFSET + ordinal * QM31_BYTES,
            q(1_000 + 20 * ordinal as u32),
        );
    }
    for ordinal in 0..MIX_VALUES {
        write(
            &mut output,
            V5_RELATION_STRESS_MIXES_OFFSET + ordinal * QM31_BYTES,
            q(2_000 + 20 * ordinal as u32),
        );
    }
    for round in 0..ALPHA_VALUES {
        write(
            &mut output,
            V5_RELATION_STRESS_ALPHAS_OFFSET + round * QM31_BYTES,
            q(3_000 + 20 * round as u32),
        );
    }
    output
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn deterministic_payload_runs_every_relation_round() {
        let payload = build_deterministic_v5_relation_stress_payload();
        assert_eq!(payload.len(), V5_RELATION_STRESS_BYTES);
        assert_eq!(
            verify_v5_relation_stress_payload(&payload),
            Ok(V5RelationStressSink {
                terminal_claim: QM31::ZERO,
                terminal_dot: QM31::ZERO,
            })
        );
    }

    #[test]
    fn corrupted_sumcheck_is_rejected() {
        let mut payload = build_deterministic_v5_relation_stress_payload();
        QM31::ONE.write_le_bytes(
            &mut payload[V5_RELATION_STRESS_SUMCHECKS_OFFSET
                ..V5_RELATION_STRESS_SUMCHECKS_OFFSET + QM31_BYTES],
        );
        assert_eq!(
            verify_v5_relation_stress_payload(&payload),
            Err(V5RelationStressError::BoundaryMismatch { round: 0 })
        );
    }
}

//! Isolated production-order PCS-relation stress kernel for the v5 CU probe.
//!
//! The byte payload is deliberately self-contained. It carries the two
//! circle OOD points, six later-line OOD points, eight values and mixing
//! scalars, four degree-six sumcheck messages, and the final four natural
//! coefficients. The verifier executes the same accumulator operations and
//! checks in the same order as the production state-only relation verifier.

use aspis_core::circle::SecureCirclePoint;
use aspis_core::field::QM31;
use aspis_core::sumcheck::{
    boundary_sum, evaluate, SumcheckPolynomial, TensorWeightError, WeightAccumulator,
    SUMCHECK_COEFFICIENTS,
};

pub const V5_RELATION_STRESS_ROUNDS: usize = 4;
pub const V5_RELATION_STRESS_SAMPLES: usize = 2;
pub const V5_RELATION_STRESS_POINT_VALUES: usize = 10;
pub const V5_RELATION_STRESS_OOD_VALUES: usize =
    V5_RELATION_STRESS_ROUNDS * V5_RELATION_STRESS_SAMPLES;
pub const V5_RELATION_STRESS_MIXES: usize = V5_RELATION_STRESS_OOD_VALUES;
pub const V5_RELATION_STRESS_FINAL_VALUES: usize = 4;
pub const V5_RELATION_STRESS_QM31_VALUES: usize = V5_RELATION_STRESS_POINT_VALUES
    + V5_RELATION_STRESS_OOD_VALUES
    + V5_RELATION_STRESS_MIXES
    + V5_RELATION_STRESS_ROUNDS * SUMCHECK_COEFFICIENTS
    + V5_RELATION_STRESS_FINAL_VALUES;
pub const V5_RELATION_STRESS_BYTES: usize = V5_RELATION_STRESS_QM31_VALUES * 16;

const POINT_OFFSET: usize = 0;
const OOD_VALUE_OFFSET: usize = POINT_OFFSET + V5_RELATION_STRESS_POINT_VALUES;
const MIX_OFFSET: usize = OOD_VALUE_OFFSET + V5_RELATION_STRESS_OOD_VALUES;
const SUMCHECK_OFFSET: usize = MIX_OFFSET + V5_RELATION_STRESS_MIXES;
const FINAL_OFFSET: usize =
    SUMCHECK_OFFSET + V5_RELATION_STRESS_ROUNDS * SUMCHECK_COEFFICIENTS;

const _: () = assert!(V5_RELATION_STRESS_QM31_VALUES == 58);
const _: () = assert!(V5_RELATION_STRESS_BYTES == 928);
const _: () = assert!(FINAL_OFFSET == 54);

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum V5RelationStressError {
    WrongLength,
    NonCanonical { value: usize },
    Weight(TensorWeightError),
    BoundaryMismatch { round: usize },
    TerminalMismatch,
}

impl From<TensorWeightError> for V5RelationStressError {
    fn from(error: TensorWeightError) -> Self {
        Self::Weight(error)
    }
}

#[inline(always)]
fn decode(payload: &[u8], value: usize) -> Result<QM31, V5RelationStressError> {
    let start = value * 16;
    QM31::from_le_bytes(&payload[start..start + 16])
        .ok_or(V5RelationStressError::NonCanonical { value })
}

/// Execute the exact production-order four-round OOD/sumcheck/final relation
/// checks. The initial claim is zero for this CU stress instance; the payload
/// builder below produces a valid algebraically-zero proof while retaining
/// nonzero mixing scalars and therefore all accumulator work.
pub fn verify_v5_relation_stress(
    payload: &[u8],
    alphas: [QM31; V5_RELATION_STRESS_ROUNDS],
) -> Result<QM31, V5RelationStressError> {
    if payload.len() != V5_RELATION_STRESS_BYTES {
        return Err(V5RelationStressError::WrongLength);
    }

    // Decode the whole fixed grammar before doing relation work. This keeps
    // malformed encodings from changing which verifier operations execute.
    let mut values = [QM31::ZERO; V5_RELATION_STRESS_QM31_VALUES];
    for (index, value) in values.iter_mut().enumerate() {
        *value = decode(payload, index)?;
    }

    let mut weights = WeightAccumulator::empty(10);
    let mut running_claim = QM31::ZERO;
    for round in 0..V5_RELATION_STRESS_ROUNDS {
        for sample in 0..V5_RELATION_STRESS_SAMPLES {
            let sample_index = round * V5_RELATION_STRESS_SAMPLES + sample;
            let mix = values[MIX_OFFSET + sample_index];
            if round == 0 {
                let point_index = POINT_OFFSET + 2 * sample;
                weights.add_circle_tensor(
                    mix,
                    SecureCirclePoint {
                        x: values[point_index],
                        y: values[point_index + 1],
                    },
                )?;
            } else {
                let point_index =
                    POINT_OFFSET + 4 + (round - 1) * V5_RELATION_STRESS_SAMPLES + sample;
                weights.add_line_tensor(mix, values[point_index])?;
            }
            running_claim = running_claim.add(mix.mul(values[OOD_VALUE_OFFSET + sample_index]));
        }

        let polynomial: SumcheckPolynomial = core::array::from_fn(|coefficient| {
            values[SUMCHECK_OFFSET + round * SUMCHECK_COEFFICIENTS + coefficient]
        });
        if boundary_sum(&polynomial) != running_claim {
            return Err(V5RelationStressError::BoundaryMismatch { round });
        }
        running_claim = evaluate(&polynomial, alphas[round]);
        weights.fold(alphas[round]);
    }

    let final_values: [QM31; V5_RELATION_STRESS_FINAL_VALUES] =
        core::array::from_fn(|index| values[FINAL_OFFSET + index]);
    let terminal = weights.dot(&final_values);
    if terminal != running_claim {
        return Err(V5RelationStressError::TerminalMismatch);
    }
    Ok(terminal)
}

/// Deterministic valid payload for host tooling and unit tests. Circle points
/// are `(1, 0)`, later line points and all OOD mixing scalars are one, while
/// OOD values, sumcheck messages, and final coefficients are zero. Thus every
/// production operation runs and every checked relation is exactly zero.
pub fn build_zero_v5_relation_stress_payload() -> [u8; V5_RELATION_STRESS_BYTES] {
    let mut payload = [0u8; V5_RELATION_STRESS_BYTES];
    let mut write = |index: usize, value: QM31| {
        value.write_le_bytes(&mut payload[index * 16..index * 16 + 16]);
    };
    write(POINT_OFFSET, QM31::ONE);
    write(POINT_OFFSET + 2, QM31::ONE);
    for point in 4..V5_RELATION_STRESS_POINT_VALUES {
        write(POINT_OFFSET + point, QM31::ONE);
    }
    for mix in 0..V5_RELATION_STRESS_MIXES {
        write(MIX_OFFSET + mix, QM31::ONE);
    }
    payload
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn zero_instance_executes_complete_relation() {
        let payload = build_zero_v5_relation_stress_payload();
        assert_eq!(payload.len(), 928);
        assert_eq!(
            verify_v5_relation_stress(&payload, [QM31::ONE; 4]),
            Ok(QM31::ZERO)
        );
    }

    #[test]
    fn changed_sumcheck_is_rejected() {
        let mut payload = build_zero_v5_relation_stress_payload();
        QM31::ONE.write_le_bytes(
            &mut payload[SUMCHECK_OFFSET * 16..SUMCHECK_OFFSET * 16 + 16],
        );
        assert_eq!(
            verify_v5_relation_stress(&payload, [QM31::ONE; 4]),
            Err(V5RelationStressError::BoundaryMismatch { round: 0 })
        );
    }
}

programs/aspis-verifier/src/v5_wire_skel:
//! Fail-closed executable grammar for the proposed v5 Spend prefix.
//!
//! This module deliberately stops at the first missing cryptographic seam.
//! It pins byte order, lane roles, dimensions, the ten degree-27 sumcheck
//! messages, the 19-by-4 opening table, and the component-B terminal identity.
//! The trailing lane-digest table is synthetic test data, not a circle-PCS
//! proof.  [`verify_v5_wire_for_production`] therefore rejects every value
//! accepted by [`verify_synthetic_v5_wire`].  Replacing that rejection requires
//! a real opening proof authenticating all 76 claims against the pre-eta root.

use aspis_core::field::{CM31, M31, P, QM31};

pub const V5_WIRE_MAGIC: [u8; 8] = *b"AV5PFX01";
pub const V5_WIRE_VERSION: u8 = 1;
pub const V5_WIRE_SYNTHETIC_PCS_FLAG: u8 = 1;

pub const V5_WIRE_C1_LANES: usize = 16;
pub const V5_WIRE_AUX_LANES: usize = 3;
pub const V5_WIRE_LANES: usize = V5_WIRE_C1_LANES + V5_WIRE_AUX_LANES;
pub const V5_WIRE_HCOPY_LANE: usize = 16;
pub const V5_WIRE_COMPONENT_B_LANE: usize = 17;
pub const V5_WIRE_COMPONENT_C_LANE: usize = 18;

pub const V5_WIRE_C1_VALUE_BYTES: usize = 256;
pub const V5_WIRE_C2_VALUE_BYTES: usize = 192;
pub const V5_WIRE_CLAIMS_PER_LANE: usize = 4;
pub const V5_WIRE_OPENING_CLAIMS: usize = V5_WIRE_LANES * V5_WIRE_CLAIMS_PER_LANE;
pub const V5_WIRE_ROUNDS: usize = 10;
pub const V5_WIRE_SUMCHECK_DEGREE: usize = 27;
pub const V5_WIRE_ROUND_COEFFICIENTS: usize = V5_WIRE_SUMCHECK_DEGREE + 1;

const QM31_BYTES: usize = 16;
const DIGEST_BYTES: usize = 32;
const POINT_MAJOR_CLAIM_LAYOUT: u8 = 0;
const AUX_ROLE_HCOPY: u8 = 1;
const AUX_ROLE_COMPONENT_B: u8 = 2;
const AUX_ROLE_COMPONENT_C: u8 = 3;
pub const V5_WIRE_AUX_ROLES: [u8; V5_WIRE_AUX_LANES] =
    [AUX_ROLE_HCOPY, AUX_ROLE_COMPONENT_B, AUX_ROLE_COMPONENT_C];

/// Fixed header through the point-major layout tag.  The transcript root is
/// the next field; the synthetic lane table lives after the transcript fields
/// and is not absorbed as a challenge after the fact.
pub const V5_WIRE_HEADER_BYTES: usize = 23;
pub const V5_WIRE_ROOT_OFFSET: usize = V5_WIRE_HEADER_BYTES;
pub const V5_WIRE_INITIAL_CLAIM_OFFSET: usize = V5_WIRE_ROOT_OFFSET + DIGEST_BYTES;
pub const V5_WIRE_ROUNDS_OFFSET: usize = V5_WIRE_INITIAL_CLAIM_OFFSET + QM31_BYTES;
pub const V5_WIRE_ROUND_MESSAGE_BYTES: usize = V5_WIRE_ROUND_COEFFICIENTS * QM31_BYTES;
pub const V5_WIRE_ROUND_RECORD_BYTES: usize = V5_WIRE_ROUND_MESSAGE_BYTES;
pub const V5_WIRE_OPENINGS_OFFSET: usize =
    V5_WIRE_ROUNDS_OFFSET + V5_WIRE_ROUNDS * V5_WIRE_ROUND_RECORD_BYTES;
pub const V5_WIRE_TERMINALS_OFFSET: usize =
    V5_WIRE_OPENINGS_OFFSET + V5_WIRE_OPENING_CLAIMS * QM31_BYTES;
pub const V5_WIRE_SYNTHETIC_LANES_OFFSET: usize = V5_WIRE_TERMINALS_OFFSET + 3 * QM31_BYTES;
pub const V5_WIRE_PREFIX_BYTES: usize =
    V5_WIRE_SYNTHETIC_LANES_OFFSET + V5_WIRE_LANES * DIGEST_BYTES;

const SYNTHETIC_ROOT_DOMAIN: &[u8] = b"aspis-v5-wire-synthetic-root-v1";
const SYNTHETIC_LANE_DOMAIN: &[u8] = b"aspis-v5-wire-synthetic-lane-v1";
const SYNTHETIC_B_LANE_DOMAIN: &[u8] = b"aspis-v5-wire-synthetic-b-state-v1";
const SYNTHETIC_TRANSCRIPT_DOMAIN: &[u8] = b"aspis-v5-wire-transcript-v1";
const SYNTHETIC_ROUND_DOMAIN: &[u8] = b"aspis-v5-wire-round-v1";
const SYNTHETIC_KAPPA_DOMAIN: &[u8] = b"aspis-v5-wire-kappa-v1";

pub type Hashv = fn(&[&[u8]]) -> [u8; DIGEST_BYTES];

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum V5WireError {
    WrongLength,
    WrongMagic,
    WrongVersion,
    UnsupportedFlags,
    WrongWidths,
    WrongLaneShape,
    WrongAuxRoles,
    WrongRoundShape,
    WrongClaimShape,
    NonCanonicalField,
    ZeroTranscriptChallenge,
    SyntheticRootMismatch,
    SumcheckBoundaryMismatch,
    SumcheckTerminalMismatch,
    ComponentBOpeningMismatch,
    TerminalIdentityMismatch,
    EmptySyntheticLaneDigest,
    /// The exact blocker at the edge of the executable skeleton: no real PCS
    /// opening proof authenticates the 76 released claims against the root.
    SyntheticPcsAuthenticationForbidden,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum V5AuxLaneRole {
    Hcopy,
    ComponentB,
    ComponentC,
}

#[derive(Clone, Copy)]
pub struct ParsedV5Wire<'a> {
    bytes: &'a [u8],
}

impl ParsedV5Wire<'_> {
    pub fn root(&self) -> &[u8; DIGEST_BYTES] {
        self.bytes[V5_WIRE_ROOT_OFFSET..V5_WIRE_INITIAL_CLAIM_OFFSET]
            .try_into()
            .expect("fixed root bounds")
    }

    pub fn initial_claim(&self) -> Result<QM31, V5WireError> {
        decode_qm31(self.bytes, V5_WIRE_INITIAL_CLAIM_OFFSET)
    }

    pub fn round_message(&self, round: usize) -> &[u8] {
        let start = V5_WIRE_ROUNDS_OFFSET + round * V5_WIRE_ROUND_RECORD_BYTES;
        &self.bytes[start..start + V5_WIRE_ROUND_MESSAGE_BYTES]
    }

    /// Claims are serialized point-major: `point * 19 + lane`.
    pub fn opening_claim(&self, point: usize, lane: usize) -> Result<QM31, V5WireError> {
        if point >= V5_WIRE_CLAIMS_PER_LANE || lane >= V5_WIRE_LANES {
            return Err(V5WireError::WrongClaimShape);
        }
        decode_qm31(
            self.bytes,
            V5_WIRE_OPENINGS_OFFSET + (point * V5_WIRE_LANES + lane) * QM31_BYTES,
        )
    }

    pub fn terminal_real(&self) -> Result<QM31, V5WireError> {
        decode_qm31(self.bytes, V5_WIRE_TERMINALS_OFFSET)
    }

    pub fn terminal_mask(&self) -> Result<QM31, V5WireError> {
        decode_qm31(self.bytes, V5_WIRE_TERMINALS_OFFSET + QM31_BYTES)
    }

    pub fn terminal_masked(&self) -> Result<QM31, V5WireError> {
        decode_qm31(self.bytes, V5_WIRE_TERMINALS_OFFSET + 2 * QM31_BYTES)
    }

    pub fn synthetic_lane_digest(&self, lane: usize) -> Result<&[u8; DIGEST_BYTES], V5WireError> {
        if lane >= V5_WIRE_LANES {
            return Err(V5WireError::WrongLaneShape);
        }
        let start = V5_WIRE_SYNTHETIC_LANES_OFFSET + lane * DIGEST_BYTES;
        Ok(self.bytes[start..start + DIGEST_BYTES]
            .try_into()
            .expect("fixed lane digest bounds"))
    }

    pub const fn aux_role(lane: usize) -> Option<V5AuxLaneRole> {
        match lane {
            V5_WIRE_HCOPY_LANE => Some(V5AuxLaneRole::Hcopy),
            V5_WIRE_COMPONENT_B_LANE => Some(V5AuxLaneRole::ComponentB),
            V5_WIRE_COMPONENT_C_LANE => Some(V5AuxLaneRole::ComponentC),
            _ => None,
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct VerifiedSyntheticV5Wire {
    pub eta: QM31,
    pub round_challenges: [QM31; V5_WIRE_ROUNDS],
    pub kappa: QM31,
    pub terminal_real: QM31,
    pub terminal_mask: QM31,
    pub terminal_masked: QM31,
}

pub fn parse_v5_wire(bytes: &[u8]) -> Result<ParsedV5Wire<'_>, V5WireError> {
    if bytes.len() != V5_WIRE_PREFIX_BYTES {
        return Err(V5WireError::WrongLength);
    }
    if bytes[..V5_WIRE_MAGIC.len()] != V5_WIRE_MAGIC {
        return Err(V5WireError::WrongMagic);
    }
    if bytes[8] != V5_WIRE_VERSION {
        return Err(V5WireError::WrongVersion);
    }
    if bytes[9] != V5_WIRE_SYNTHETIC_PCS_FLAG {
        return Err(V5WireError::UnsupportedFlags);
    }
    if u16::from_le_bytes(bytes[10..12].try_into().unwrap()) != V5_WIRE_C1_VALUE_BYTES as u16
        || u16::from_le_bytes(bytes[12..14].try_into().unwrap()) != V5_WIRE_C2_VALUE_BYTES as u16
    {
        return Err(V5WireError::WrongWidths);
    }
    if usize::from(bytes[14]) != V5_WIRE_C1_LANES || usize::from(bytes[15]) != V5_WIRE_AUX_LANES {
        return Err(V5WireError::WrongLaneShape);
    }
    if bytes[16..19] != V5_WIRE_AUX_ROLES {
        return Err(V5WireError::WrongAuxRoles);
    }
    if usize::from(bytes[19]) != V5_WIRE_ROUNDS || usize::from(bytes[20]) != V5_WIRE_SUMCHECK_DEGREE
    {
        return Err(V5WireError::WrongRoundShape);
    }
    if usize::from(bytes[21]) != V5_WIRE_CLAIMS_PER_LANE {
        return Err(V5WireError::WrongClaimShape);
    }
    if bytes[22] != POINT_MAJOR_CLAIM_LAYOUT {
        return Err(V5WireError::WrongClaimShape);
    }
    Ok(ParsedV5Wire { bytes })
}

fn decode_qm31(bytes: &[u8], offset: usize) -> Result<QM31, V5WireError> {
    QM31::from_le_bytes(
        bytes
            .get(offset..offset + QM31_BYTES)
            .ok_or(V5WireError::WrongLength)?,
    )
    .ok_or(V5WireError::NonCanonicalField)
}

fn digest_to_synthetic_qm31(digest: [u8; DIGEST_BYTES]) -> QM31 {
    let limb = |index: usize| {
        let word = u32::from_le_bytes(
            digest[index * 4..index * 4 + 4]
                .try_into()
                .expect("digest limb bounds"),
        ) & P;
        M31(if word == P { 0 } else { word })
    };
    QM31 {
        c0: CM31::new(limb(0), limb(1)),
        c1: CM31::new(limb(2), limb(3)),
    }
}

fn synthetic_root(parsed: ParsedV5Wire<'_>, hashv: Hashv) -> [u8; DIGEST_BYTES] {
    hashv(&[
        SYNTHETIC_ROOT_DOMAIN,
        &parsed.bytes[..V5_WIRE_ROOT_OFFSET],
        &parsed.bytes[V5_WIRE_SYNTHETIC_LANES_OFFSET..],
    ])
}

fn round_coefficients(
    parsed: ParsedV5Wire<'_>,
    round: usize,
) -> Result<[QM31; V5_WIRE_ROUND_COEFFICIENTS], V5WireError> {
    let message = parsed.round_message(round);
    let mut coefficients = [QM31::ZERO; V5_WIRE_ROUND_COEFFICIENTS];
    for (index, coefficient) in coefficients.iter_mut().enumerate() {
        *coefficient = decode_qm31(message, index * QM31_BYTES)?;
    }
    Ok(coefficients)
}

fn polynomial_evaluation(coefficients: &[QM31; V5_WIRE_ROUND_COEFFICIENTS], point: QM31) -> QM31 {
    coefficients
        .iter()
        .rev()
        .copied()
        .fold(QM31::ZERO, |value, coefficient| {
            value.mul(point).add(coefficient)
        })
}

pub fn verify_synthetic_v5_wire(
    bytes: &[u8],
    hashv: Hashv,
) -> Result<VerifiedSyntheticV5Wire, V5WireError> {
    let parsed = parse_v5_wire(bytes)?;
    for lane in 0..V5_WIRE_LANES {
        if parsed
            .synthetic_lane_digest(lane)?
            .iter()
            .all(|byte| *byte == 0)
        {
            return Err(V5WireError::EmptySyntheticLaneDigest);
        }
    }
    let root = synthetic_root(parsed, hashv);
    if &root != parsed.root() {
        return Err(V5WireError::SyntheticRootMismatch);
    }
    let eta = digest_to_synthetic_qm31(hashv(&[SYNTHETIC_TRANSCRIPT_DOMAIN, parsed.root()]));
    if eta.is_zero() {
        return Err(V5WireError::ZeroTranscriptChallenge);
    }

    let mut incoming_claim = parsed.initial_claim()?;
    let mut eta_bytes = [0u8; QM31_BYTES];
    eta.write_le_bytes(&mut eta_bytes);
    let mut transcript_state = hashv(&[
        SYNTHETIC_TRANSCRIPT_DOMAIN,
        parsed.root(),
        &eta_bytes,
        &bytes[V5_WIRE_INITIAL_CLAIM_OFFSET..V5_WIRE_ROUNDS_OFFSET],
    ]);
    let mut round_challenges = [QM31::ZERO; V5_WIRE_ROUNDS];
    for round in 0..V5_WIRE_ROUNDS {
        let coefficients = round_coefficients(parsed, round)?;
        let at_zero = coefficients[0];
        let at_one = coefficients.iter().copied().fold(QM31::ZERO, QM31::add);
        if at_zero.add(at_one) != incoming_claim {
            return Err(V5WireError::SumcheckBoundaryMismatch);
        }

        let round_byte = [round as u8];
        transcript_state = hashv(&[
            SYNTHETIC_ROUND_DOMAIN,
            &transcript_state,
            &round_byte,
            parsed.round_message(round),
        ]);
        let challenge = digest_to_synthetic_qm31(transcript_state);
        round_challenges[round] = challenge;
        incoming_claim = polynomial_evaluation(&coefficients, challenge);
    }

    // Decode every released coordinate even though only B's fourth claim is
    // used by the terminal equation.  This pins the canonical 19-by-4 wire.
    for point in 0..V5_WIRE_CLAIMS_PER_LANE {
        for lane in 0..V5_WIRE_LANES {
            parsed.opening_claim(point, lane)?;
        }
    }
    let terminal_real = parsed.terminal_real()?;
    let terminal_mask = parsed.terminal_mask()?;
    let terminal_masked = parsed.terminal_masked()?;
    if terminal_masked != incoming_claim {
        return Err(V5WireError::SumcheckTerminalMismatch);
    }
    if parsed.opening_claim(V5_WIRE_CLAIMS_PER_LANE - 1, V5_WIRE_COMPONENT_B_LANE)? != terminal_mask
    {
        return Err(V5WireError::ComponentBOpeningMismatch);
    }
    if terminal_mask.add(eta.mul(terminal_real)) != terminal_masked {
        return Err(V5WireError::TerminalIdentityMismatch);
    }
    // Functional batching is sampled only after the verifier has absorbed
    // every one of the 76 claims and the terminal tuple.  Kappa is not proof
    // data and cannot be selected by the prover.
    let kappa = digest_to_synthetic_qm31(hashv(&[
        SYNTHETIC_KAPPA_DOMAIN,
        &transcript_state,
        &bytes[V5_WIRE_OPENINGS_OFFSET..V5_WIRE_TERMINALS_OFFSET],
        &bytes[V5_WIRE_TERMINALS_OFFSET..V5_WIRE_SYNTHETIC_LANES_OFFSET],
    ]));
    if kappa.is_zero() {
        return Err(V5WireError::ZeroTranscriptChallenge);
    }

    Ok(VerifiedSyntheticV5Wire {
        eta,
        round_challenges,
        kappa,
        terminal_real,
        terminal_mask,
        terminal_masked,
    })
}

/// Deliberately fail closed until the synthetic lane table is replaced by a
/// real, pre-eta circle-PCS root plus opening authentication for all 76 claims.
pub fn verify_v5_wire_for_production(bytes: &[u8]) -> Result<(), V5WireError> {
    let _ = parse_v5_wire(bytes)?;
    Err(V5WireError::SyntheticPcsAuthenticationForbidden)
}

#[cfg(not(target_os = "solana"))]
fn next_m31(state: &mut u64) -> M31 {
    *state = state
        .wrapping_mul(6_364_136_223_846_793_005)
        .wrapping_add(1_442_695_040_888_963_407);
    M31((*state % u64::from(P)) as u32)
}

#[cfg(not(target_os = "solana"))]
fn next_qm31(state: &mut u64) -> QM31 {
    QM31 {
        c0: CM31::new(next_m31(state), next_m31(state)),
        c1: CM31::new(next_m31(state), next_m31(state)),
    }
}

#[cfg(not(target_os = "solana"))]
fn write_qm31(output: &mut [u8], offset: usize, value: QM31) {
    value.write_le_bytes(&mut output[offset..offset + QM31_BYTES]);
}

#[cfg(not(target_os = "solana"))]
fn synthetic_b_terminal(
    initial: QM31,
    tails: &[[QM31; V5_WIRE_SUMCHECK_DEGREE]; V5_WIRE_ROUNDS],
    point: &[QM31; V5_WIRE_ROUNDS],
) -> QM31 {
    let half = QM31::ONE.half();
    let mut state = initial;
    for round in 0..V5_WIRE_ROUNDS {
        let mut power = point[round];
        let contribution = tails[round]
            .iter()
            .copied()
            .fold(QM31::ZERO, |sum, coefficient| {
                let next = sum.add(coefficient.mul(power.sub(half)));
                power = power.mul(point[round]);
                next
            });
        state = state.half().add(contribution);
    }
    state
}

/// Deterministic host/KAT prover for the fail-closed grammar.  The component-B
/// lane digest commits (by a plain SHA-256 test hash) to one initial state and
/// 270 tail coordinates; its fourth opening is their exact compact terminal
/// functional.  No PCS authentication path is emitted, hence production
/// verification still rejects the result.
#[cfg(not(target_os = "solana"))]
pub fn build_deterministic_synthetic_v5_wire(hashv: Hashv) -> Vec<u8> {
    let mut random = 0x7055_19c2_27b0_0041u64;
    let mut output = vec![0u8; V5_WIRE_PREFIX_BYTES];
    output[..8].copy_from_slice(&V5_WIRE_MAGIC);
    output[8] = V5_WIRE_VERSION;
    output[9] = V5_WIRE_SYNTHETIC_PCS_FLAG;
    output[10..12].copy_from_slice(&(V5_WIRE_C1_VALUE_BYTES as u16).to_le_bytes());
    output[12..14].copy_from_slice(&(V5_WIRE_C2_VALUE_BYTES as u16).to_le_bytes());
    output[14] = V5_WIRE_C1_LANES as u8;
    output[15] = V5_WIRE_AUX_LANES as u8;
    output[16..19].copy_from_slice(&V5_WIRE_AUX_ROLES);
    output[19] = V5_WIRE_ROUNDS as u8;
    output[20] = V5_WIRE_SUMCHECK_DEGREE as u8;
    output[21] = V5_WIRE_CLAIMS_PER_LANE as u8;
    output[22] = POINT_MAJOR_CLAIM_LAYOUT;

    let b_initial = next_qm31(&mut random);
    let b_tails: [[QM31; V5_WIRE_SUMCHECK_DEGREE]; V5_WIRE_ROUNDS] =
        core::array::from_fn(|_| core::array::from_fn(|_| next_qm31(&mut random)));
    let mut b_state_bytes = vec![0u8; (1 + V5_WIRE_ROUNDS * V5_WIRE_SUMCHECK_DEGREE) * QM31_BYTES];
    write_qm31(&mut b_state_bytes, 0, b_initial);
    for (round, tails) in b_tails.iter().enumerate() {
        for (coefficient, value) in tails.iter().copied().enumerate() {
            write_qm31(
                &mut b_state_bytes,
                (1 + round * V5_WIRE_SUMCHECK_DEGREE + coefficient) * QM31_BYTES,
                value,
            );
        }
    }

    for lane in 0..V5_WIRE_LANES {
        let start = V5_WIRE_SYNTHETIC_LANES_OFFSET + lane * DIGEST_BYTES;
        let lane_byte = [lane as u8];
        let digest = if lane == V5_WIRE_COMPONENT_B_LANE {
            hashv(&[SYNTHETIC_B_LANE_DOMAIN, &lane_byte, &b_state_bytes])
        } else {
            let seed = next_qm31(&mut random);
            let mut seed_bytes = [0u8; QM31_BYTES];
            seed.write_le_bytes(&mut seed_bytes);
            hashv(&[SYNTHETIC_LANE_DOMAIN, &lane_byte, &seed_bytes])
        };
        output[start..start + DIGEST_BYTES].copy_from_slice(&digest);
    }
    let parsed = parse_v5_wire(&output).expect("builder writes the pinned header");
    let root = synthetic_root(parsed, hashv);
    output[V5_WIRE_ROOT_OFFSET..V5_WIRE_INITIAL_CLAIM_OFFSET].copy_from_slice(&root);
    let eta = digest_to_synthetic_qm31(hashv(&[SYNTHETIC_TRANSCRIPT_DOMAIN, &root]));
    assert!(!eta.is_zero(), "pinned synthetic eta must remain nonzero");

    let mut incoming_claim = next_qm31(&mut random);
    write_qm31(&mut output, V5_WIRE_INITIAL_CLAIM_OFFSET, incoming_claim);
    let mut eta_bytes = [0u8; QM31_BYTES];
    eta.write_le_bytes(&mut eta_bytes);
    let mut transcript_state = hashv(&[
        SYNTHETIC_TRANSCRIPT_DOMAIN,
        &root,
        &eta_bytes,
        &output[V5_WIRE_INITIAL_CLAIM_OFFSET..V5_WIRE_ROUNDS_OFFSET],
    ]);
    let mut point = [QM31::ZERO; V5_WIRE_ROUNDS];
    for round in 0..V5_WIRE_ROUNDS {
        let start = V5_WIRE_ROUNDS_OFFSET + round * V5_WIRE_ROUND_RECORD_BYTES;
        let mut coefficients = [QM31::ZERO; V5_WIRE_ROUND_COEFFICIENTS];
        let mut tail_sum = QM31::ZERO;
        for coefficient in coefficients.iter_mut().skip(1) {
            *coefficient = next_qm31(&mut random);
            tail_sum = tail_sum.add(*coefficient);
        }
        coefficients[0] = incoming_claim.sub(tail_sum).half();
        for (index, coefficient) in coefficients.iter().copied().enumerate() {
            write_qm31(&mut output, start + index * QM31_BYTES, coefficient);
        }
        let round_byte = [round as u8];
        transcript_state = hashv(&[
            SYNTHETIC_ROUND_DOMAIN,
            &transcript_state,
            &round_byte,
            &output[start..start + V5_WIRE_ROUND_MESSAGE_BYTES],
        ]);
        let challenge = digest_to_synthetic_qm31(transcript_state);
        point[round] = challenge;
        incoming_claim = polynomial_evaluation(&coefficients, challenge);
    }

    for claim in 0..V5_WIRE_OPENING_CLAIMS {
        write_qm31(
            &mut output,
            V5_WIRE_OPENINGS_OFFSET + claim * QM31_BYTES,
            next_qm31(&mut random),
        );
    }
    let terminal_mask = synthetic_b_terminal(b_initial, &b_tails, &point);
    let component_b_fourth = V5_WIRE_OPENINGS_OFFSET
        + ((V5_WIRE_CLAIMS_PER_LANE - 1) * V5_WIRE_LANES + V5_WIRE_COMPONENT_B_LANE) * QM31_BYTES;
    write_qm31(&mut output, component_b_fourth, terminal_mask);
    let terminal_real = incoming_claim.sub(terminal_mask).mul(eta.inv());
    write_qm31(&mut output, V5_WIRE_TERMINALS_OFFSET, terminal_real);
    write_qm31(
        &mut output,
        V5_WIRE_TERMINALS_OFFSET + QM31_BYTES,
        terminal_mask,
    );
    write_qm31(
        &mut output,
        V5_WIRE_TERMINALS_OFFSET + 2 * QM31_BYTES,
        incoming_claim,
    );

    verify_synthetic_v5_wire(&output, hashv).expect("synthetic builder must round-trip");
    output
}

#[cfg(test)]
mod tests {
    use super::*;

    fn hashv(inputs: &[&[u8]]) -> [u8; 32] {
        solana_program::hash::hashv(inputs).to_bytes()
    }

    #[test]
    fn deterministic_serializer_parser_verifier_round_trip() {
        let bytes = build_deterministic_synthetic_v5_wire(hashv);
        let verified = verify_synthetic_v5_wire(&bytes, hashv).unwrap();
        let parsed = parse_v5_wire(&bytes).unwrap();
        assert_eq!(bytes.len(), V5_WIRE_PREFIX_BYTES);
        assert_eq!(V5_WIRE_LANES, 19);
        assert_eq!(V5_WIRE_OPENING_CLAIMS, 76);
        assert_eq!(ParsedV5Wire::aux_role(16), Some(V5AuxLaneRole::Hcopy));
        assert_eq!(ParsedV5Wire::aux_role(17), Some(V5AuxLaneRole::ComponentB));
        assert_eq!(ParsedV5Wire::aux_role(18), Some(V5AuxLaneRole::ComponentC));
        assert_eq!(
            parsed.opening_claim(3, V5_WIRE_COMPONENT_B_LANE).unwrap(),
            verified.terminal_mask
        );
        assert_eq!(
            verified
                .terminal_mask
                .add(verified.eta.mul(verified.terminal_real)),
            verified.terminal_masked
        );
        assert_eq!(
            verify_v5_wire_for_production(&bytes),
            Err(V5WireError::SyntheticPcsAuthenticationForbidden)
        );
    }

    #[test]
    fn every_placeholder_mutation_fails_closed() {
        let bytes = build_deterministic_synthetic_v5_wire(hashv);
        let mut mutation = bytes.clone();
        mutation[9] = 0;
        assert!(matches!(
            parse_v5_wire(&mutation),
            Err(V5WireError::UnsupportedFlags)
        ));

        mutation = bytes.clone();
        mutation[V5_WIRE_SYNTHETIC_LANES_OFFSET] ^= 1;
        assert_eq!(
            verify_synthetic_v5_wire(&mutation, hashv),
            Err(V5WireError::SyntheticRootMismatch)
        );

        mutation = bytes.clone();
        mutation[V5_WIRE_ROUNDS_OFFSET] ^= 1;
        assert!(verify_synthetic_v5_wire(&mutation, hashv).is_err());

        mutation = bytes.clone();
        let b_fourth = V5_WIRE_OPENINGS_OFFSET
            + ((V5_WIRE_CLAIMS_PER_LANE - 1) * V5_WIRE_LANES + V5_WIRE_COMPONENT_B_LANE)
                * QM31_BYTES;
        mutation[b_fourth] ^= 1;
        assert_eq!(
            verify_synthetic_v5_wire(&mutation, hashv),
            Err(V5WireError::ComponentBOpeningMismatch)
        );
    }

    #[test]
    fn offsets_and_exact_size_are_pinned() {
        assert_eq!(V5_WIRE_HEADER_BYTES, 23);
        assert_eq!(V5_WIRE_ROOT_OFFSET, 23);
        assert_eq!(V5_WIRE_INITIAL_CLAIM_OFFSET, 55);
        assert_eq!(V5_WIRE_ROUNDS_OFFSET, 71);
        assert_eq!(V5_WIRE_OPENINGS_OFFSET, 4_551);
        assert_eq!(V5_WIRE_TERMINALS_OFFSET, 5_767);
        assert_eq!(V5_WIRE_SYNTHETIC_LANES_OFFSET, 5_815);
        assert_eq!(V5_WIRE_PREFIX_BYTES, 6_423);
    }
}

//! Isolated local-validator probe for the V6 packed parser and final evaluator.
//!
//! This module is never part of a production feature set. It measures the
//! exact no-allocation parser, compact-frontier counter, and all sixteen
//! packed final-256 evaluations against a sealed proof account.

use aspis_core::field::{CM31, M31, QM31};
use aspis_core::v6_onefold::{
    binary_frontier_nodes, evaluate_packed_final256_at_queries, fold_v6_onefold_queries,
    prepare_v6_onefold_coordinates, verify_and_gamma_combine_v6_binary_openings,
    verify_and_gamma_combine_v6_binary_openings_prepared, V6OneFoldWire, V6_QUERY_COUNT,
};
use aspis_core::v6_query_batch::V6AuthenticatedQueryBatch;
use aspis_core::v6_transcript::{
    verify_v6_transcript_and_relation_prepared,
    verify_v6_transcript_and_relation_prepared_with_diagnostic_trace, V6RelationDiagnosticPhase,
    V6SemanticView, V6TranscriptContext, V6TranscriptError,
};
use aspis_statement::atomic_state_only_terminal::{
    atomic_state_only_copy_inactive_group_masks_v3, atomic_state_only_copy_inactive_row_groups_v3,
    atomic_state_only_selected_masked_terminal_value_compiled_v3,
    atomic_state_only_selected_masked_terminal_value_compiled_with_diagnostic_trace_v3,
};
use aspis_statement::state_only_terminal::StateOnlyTerminalDiagnosticPhase;
use aspis_statement::{AtomicPaymentStatementV4, SpendPublic, STATE_ONLY_SELECTED_TERMINAL_CLAIMS};
use solana_program::{
    account_info::AccountInfo,
    entrypoint::ProgramResult,
    hash::hashv,
    log::{sol_log_compute_units, sol_log_data},
    msg,
    program_error::ProgramError,
    pubkey::Pubkey,
};

pub const V6_CU_PROBE_TAG: u8 = 68;
pub const V6_CU_PROBE_WIRE_BYTES: usize = 1 + 2 + 2 + V6_QUERY_COUNT * 4;
/// Full read-only algebra/PCS diagnostic. This remains unreachable from every
/// production build and deliberately substitutes `true` for the live
/// statement terminal while measuring all other V6 verification work.
pub const V6_FULL_CU_PROBE_TAG: u8 = 69;
pub const V6_FULL_CU_PROBE_WIRE_BYTES: usize = 1 + 2 + 2 + 1;
/// Exact semantic-terminal phase diagnostic. It shares the full probe wire,
/// runs the real terminal polynomial on transcript-derived inputs, and stops
/// before the PCS relation. It is unreachable from production builds.
pub const V6_TERMINAL_CU_PROBE_TAG: u8 = 70;
pub const V6_TERMINAL_CU_PROBE_WIRE_BYTES: usize = V6_FULL_CU_PROBE_WIRE_BYTES;
/// One-instruction core-verifier diagnostic: exact terminal, all three work
/// hashes, relation, Merkle authentication and one-fold checks. It still
/// excludes the atomic account wrapper/state write and is unreachable from
/// production builds.
pub const V6_INTEGRATED_CU_PROBE_TAG: u8 = 71;
pub const V6_INTEGRATED_CU_PROBE_WIRE_BYTES: usize = V6_FULL_CU_PROBE_WIRE_BYTES;
/// Complete diagnostic atomic wrapper around the uninstrumented V6 core.
/// This tag exists only under `v6-cu-probe`; production will use the same
/// wrapper and digest handoff after an honest proof fixture is available.
pub const V6_ATOMIC_CU_PROBE_TAG: u8 = 72;
const V6_ATOMIC_PUBLIC_WIRE_BYTES: usize = 4 * 32 + 2 * 4 + 32;
pub const V6_ATOMIC_CU_PROBE_WIRE_BYTES: usize =
    V6_FULL_CU_PROBE_WIRE_BYTES + V6_ATOMIC_PUBLIC_WIRE_BYTES;
pub const V6_PROBE_RELEASE_BINDING: [u8; 32] = [0x56; 32];
pub const V6_PROBE_STATEMENT_DIGEST: [u8; 32] = [0x53; 32];

#[cfg(not(feature = "no-entrypoint"))]
solana_program::entrypoint!(process_v6_cu_probe_instruction);

fn read_u16(input: &mut &[u8]) -> Result<u16, ProgramError> {
    let (head, tail) = input
        .split_first_chunk::<2>()
        .ok_or(ProgramError::InvalidInstructionData)?;
    *input = tail;
    Ok(u16::from_le_bytes(*head))
}

fn read_u32(input: &mut &[u8]) -> Result<u32, ProgramError> {
    let (head, tail) = input
        .split_first_chunk::<4>()
        .ok_or(ProgramError::InvalidInstructionData)?;
    *input = tail;
    Ok(u32::from_le_bytes(*head))
}

fn read_array<const N: usize>(input: &mut &[u8]) -> Result<[u8; N], ProgramError> {
    let (head, tail) = input
        .split_first_chunk::<N>()
        .ok_or(ProgramError::InvalidInstructionData)?;
    *input = tail;
    Ok(*head)
}

fn qm31_bytes(value: QM31) -> [u8; 16] {
    let mut bytes = [0u8; 16];
    value.write_le_bytes(&mut bytes);
    bytes
}

/// Execute the real SBF SHA-256 syscall for every transcript operation. A
/// grinding call is uniquely shaped as `(32-byte state, 1-byte domain,
/// 8-byte nonce)`; only for that diagnostic call, clear the returned leading
/// bytes so the all-zero CU fixture can pass 34-bit work and continue. Work
/// hashes do not mutate transcript state, so every subsequent challenge is
/// identical to the production hash path.
fn sbf_hashv_accept_probe_work(inputs: &[&[u8]]) -> [u8; 32] {
    let mut digest = crate::verify::sbf_hashv(inputs);
    if inputs.len() == 3 && inputs[0].len() == 32 && inputs[1].len() == 1 && inputs[2].len() == 8 {
        digest[..5].fill(0);
    }
    digest
}

fn diagnostic_statement() -> AtomicPaymentStatementV4 {
    AtomicPaymentStatementV4 {
        pool: [0u8; 32],
        sequence: 0,
        spend: SpendPublic {
            anchor: [M31::ZERO; 8],
            nullifier: [M31::ZERO; 8],
            output_commitment: [M31::ZERO; 8],
            asset_id: M31::ZERO,
            fee: 0,
        },
        output_anchor: [M31::ZERO; 8],
        deployment_domain: [0u8; 32],
    }
}

fn terminal_claims(view: &V6SemanticView<'_>) -> [QM31; STATE_ONLY_SELECTED_TERMINAL_CLAIMS] {
    core::array::from_fn(|index| {
        let row = index / 28;
        let column = index % 28;
        view.point_claims[row][column]
    })
}

