#[inline(never)]
fn process_v6_integrated_probe(
    program_id: &Pubkey,
    proof_account: &AccountInfo,
    proof: &[u8],
    c1_frontier_nodes: usize,
    c2_frontier_nodes: usize,
    selector: u8,
) -> ProgramResult {
    msg!("aspis-v6-integrated:entry");
    sol_log_compute_units();
    let parsed =
        V6OneFoldWire::parse_deferred_canonicality(proof, c1_frontier_nodes, c2_frontier_nodes)
            .map_err(|_| ProgramError::InvalidAccountData)?;
    msg!("aspis-v6-integrated:parsed");
    sol_log_compute_units();

    let context = V6TranscriptContext {
        program_id: program_id.to_bytes(),
        release_binding: V6_PROBE_RELEASE_BINDING,
        statement_digest: V6_PROBE_STATEMENT_DIGEST,
        attempt_id: proof_account.key.to_bytes(),
    };
    let statement = diagnostic_statement();
    let mut terminal_value = QM31::ZERO;
    let verified = verify_v6_transcript_and_relation_prepared_with_diagnostic_trace(
        sbf_hashv_accept_probe_work,
        &parsed,
        &context,
        selector,
        atomic_state_only_copy_inactive_row_groups_v3(),
        atomic_state_only_copy_inactive_group_masks_v3(),
        true,
        |view| {
            msg!("aspis-v6-integrated:terminal-start");
            sol_log_compute_units();
            let Ok(value) = atomic_state_only_selected_masked_terminal_value_compiled_v3(
                &statement,
                &terminal_claims(view),
                &view.point,
                view.lambda,
                view.chi,
                view.batching.theta,
                &view.batching.zerocheck_point,
                view.batching.mu,
                view.eta,
            ) else {
                return false;
            };
            terminal_value = value;
            msg!("aspis-v6-integrated:terminal-end");
            sol_log_compute_units();
            true
        },
        |view| {
            msg!("aspis-v6-integrated:query-start");
            sol_log_compute_units();
            let combined = verify_and_gamma_combine_v6_binary_openings_prepared(
                sbf_hashv_accept_probe_work,
                &parsed,
                view.queries,
                view.gamma_powers,
            )?;
            msg!("aspis-v6-integrated:merkle-and-gamma");
            sol_log_compute_units();
            let coordinates = prepare_v6_onefold_coordinates(view.queries)?;
            msg!("aspis-v6-integrated:coordinates");
            sol_log_compute_units();
            let folded = fold_v6_onefold_queries(&combined, &coordinates, view.alpha0);
            msg!("aspis-v6-integrated:onefold-query-values");
            sol_log_compute_units();
            Ok(V6AuthenticatedQueryBatch {
                values: folded,
                line_x: coordinates.line_x,
            })
        },
        log_relation_phase,
    )
    .map_err(|_| ProgramError::InvalidAccountData)?;
    msg!("aspis-v6-integrated:relation-tail");
    sol_log_compute_units();
    let folded_sum = qm31_bytes(verified.folded_query_sum);
    let terminal = qm31_bytes(terminal_value);
    let slices = [
        folded_sum.as_slice(),
        terminal.as_slice(),
        verified.transcript_state_after_queries.as_slice(),
    ];
    let sink = hashv(&slices);
    sol_log_data(&[b"aspis-v6-integrated-core-probe-v1", sink.as_ref()]);
    msg!("aspis-v6-integrated:sink");
    sol_log_compute_units();
    Ok(())
}

#[inline(never)]
fn process_v6_atomic_probe<'a>(
    program_id: &Pubkey,
    accounts: &[AccountInfo<'a>],
    public: &crate::atomic_payment::AtomicPaymentPublicInputs,
    c1_frontier_nodes: usize,
    c2_frontier_nodes: usize,
    selector: u8,
) -> ProgramResult {
    crate::atomic_payment::verify_and_apply_atomic_payment_state(
        program_id,
        accounts,
        public,
        |proof_account, statement, statement_digest| {
            let account_data = proof_account.try_borrow_data()?;
            if !crate::lifecycle::proof_account_finalized(&account_data) {
                return Err(ProgramError::InvalidAccountData);
            }
            let (proof_start, proof_end) = crate::lifecycle::uploaded_proof_bounds(&account_data)?;
            let proof = &account_data[proof_start..proof_end];
            let parsed = V6OneFoldWire::parse_deferred_canonicality(
                proof,
                c1_frontier_nodes,
                c2_frontier_nodes,
            )
            .map_err(|_| ProgramError::InvalidAccountData)?;
            let context = V6TranscriptContext {
                program_id: program_id.to_bytes(),
                release_binding: V6_PROBE_RELEASE_BINDING,
                statement_digest: *statement_digest,
                attempt_id: proof_account.key.to_bytes(),
            };
            verify_v6_transcript_and_relation_prepared(
                sbf_hashv_accept_probe_work,
                &parsed,
                &context,
                selector,
                atomic_state_only_copy_inactive_row_groups_v3(),
                atomic_state_only_copy_inactive_group_masks_v3(),
                true,
                |view| {
                    atomic_state_only_selected_masked_terminal_value_compiled_v3(
                        statement,
                        &terminal_claims(view),
                        &view.point,
                        view.lambda,
                        view.chi,
                        view.batching.theta,
                        &view.batching.zerocheck_point,
                        view.batching.mu,
                        view.eta,
                    )
                    .is_ok()
                },
                |view| {
                    let combined = verify_and_gamma_combine_v6_binary_openings_prepared(
                        sbf_hashv_accept_probe_work,
                        &parsed,
                        view.queries,
                        view.gamma_powers,
                    )?;
                    let coordinates = prepare_v6_onefold_coordinates(view.queries)?;
                    Ok(V6AuthenticatedQueryBatch {
                        values: fold_v6_onefold_queries(&combined, &coordinates, view.alpha0),
                        line_x: coordinates.line_x,
                    })
                },
            )
            .map_err(|_| ProgramError::InvalidAccountData)?;
            Ok(())
        },
    )
}

#[inline(never)]
fn process_v6_atomic_probe_instruction(
    program_id: &Pubkey,
    accounts: &[AccountInfo],
    instruction_data: &[u8],
) -> ProgramResult {
    if instruction_data.len() != V6_ATOMIC_CU_PROBE_WIRE_BYTES {
        return Err(ProgramError::InvalidInstructionData);
    }
    let proof_account = accounts.first().ok_or(ProgramError::NotEnoughAccountKeys)?;
    if proof_account.owner != program_id || proof_account.is_writable {
        return Err(ProgramError::IncorrectProgramId);
    }
    let mut input = &instruction_data[1..];
    let c1_frontier_nodes = usize::from(read_u16(&mut input)?);
    let c2_frontier_nodes = usize::from(read_u16(&mut input)?);
    let selector = input
        .first()
        .copied()
        .ok_or(ProgramError::InvalidInstructionData)?;
    input = &input[1..];
    let public = crate::atomic_payment::AtomicPaymentPublicInputs {
        current_anchor: read_array(&mut input)?,
        nullifier: read_array(&mut input)?,
        output_commitment: read_array(&mut input)?,
        output_anchor: read_array(&mut input)?,
        asset_id: read_u32(&mut input)?,
        fee: read_u32(&mut input)?,
        deployment_domain: read_array(&mut input)?,
    };
    if !input.is_empty() {
        return Err(ProgramError::InvalidInstructionData);
    }
    process_v6_atomic_probe(
        program_id,
        accounts,
        &public,
        c1_frontier_nodes,
        c2_frontier_nodes,
        selector,
    )
}

pub fn process_v6_cu_probe_instruction(
    program_id: &Pubkey,
    accounts: &[AccountInfo],
    instruction_data: &[u8],
) -> ProgramResult {
    let tag = instruction_data
        .first()
        .copied()
        .ok_or(ProgramError::InvalidInstructionData)?;
    if tag == V6_ATOMIC_CU_PROBE_TAG {
        return process_v6_atomic_probe_instruction(program_id, accounts, instruction_data);
    }
    let expected_wire_bytes = match tag {
        V6_CU_PROBE_TAG => V6_CU_PROBE_WIRE_BYTES,
        V6_FULL_CU_PROBE_TAG => V6_FULL_CU_PROBE_WIRE_BYTES,
        V6_TERMINAL_CU_PROBE_TAG => V6_TERMINAL_CU_PROBE_WIRE_BYTES,
        V6_INTEGRATED_CU_PROBE_TAG => V6_INTEGRATED_CU_PROBE_WIRE_BYTES,
        _ => return Err(ProgramError::InvalidInstructionData),
    };
    if instruction_data.len() != expected_wire_bytes {
        return Err(ProgramError::InvalidInstructionData);
    }
    let proof_account = accounts.first().ok_or(ProgramError::NotEnoughAccountKeys)?;
    if proof_account.owner != program_id || proof_account.is_writable {
        return Err(ProgramError::IncorrectProgramId);
    }

    let mut input = &instruction_data[1..];
    let c1_frontier_nodes = usize::from(read_u16(&mut input)?);
    let c2_frontier_nodes = usize::from(read_u16(&mut input)?);
    let mut queries = [0u32; V6_QUERY_COUNT];
    let full_selector = if tag == V6_FULL_CU_PROBE_TAG
        || tag == V6_TERMINAL_CU_PROBE_TAG
        || tag == V6_INTEGRATED_CU_PROBE_TAG
    {
        let selector = input
            .first()
            .copied()
            .ok_or(ProgramError::InvalidInstructionData)?;
        input = &input[1..];
        Some(selector)
    } else {
        for query in &mut queries {
            *query = read_u32(&mut input)?;
        }
        None
    };
    if !input.is_empty() {
        return Err(ProgramError::InvalidInstructionData);
    }

    let account_data = proof_account.try_borrow_data()?;
    if !crate::lifecycle::proof_account_finalized(&account_data) {
        return Err(ProgramError::InvalidAccountData);
    }
    let (proof_start, proof_end) = crate::lifecycle::uploaded_proof_bounds(&account_data)?;
    let proof = &account_data[proof_start..proof_end];

    if tag == V6_TERMINAL_CU_PROBE_TAG {
        let selector = full_selector.ok_or(ProgramError::InvalidInstructionData)?;
        msg!("aspis-v6-terminal:entry");
        sol_log_compute_units();
        let parsed =
            V6OneFoldWire::parse_deferred_canonicality(proof, c1_frontier_nodes, c2_frontier_nodes)
                .map_err(|_| ProgramError::InvalidAccountData)?;
        msg!("aspis-v6-terminal:parsed");
        sol_log_compute_units();
        let context = V6TranscriptContext {
            program_id: program_id.to_bytes(),
            release_binding: V6_PROBE_RELEASE_BINDING,
            statement_digest: V6_PROBE_STATEMENT_DIGEST,
            attempt_id: proof_account.key.to_bytes(),
        };
        let statement = diagnostic_statement();
        let result = verify_v6_transcript_and_relation_prepared(
            crate::verify::sbf_hashv,
            &parsed,
            &context,
            selector,
            atomic_state_only_copy_inactive_row_groups_v3(),
            atomic_state_only_copy_inactive_group_masks_v3(),
            false,
            |view| {
                msg!("aspis-v6-terminal:start");
                sol_log_compute_units();
                let value = atomic_state_only_selected_masked_terminal_value_compiled_with_diagnostic_trace_v3(
                    &statement,
                    &terminal_claims(view),
                    &view.point,
                    view.lambda,
                    view.chi,
                    view.batching.theta,
                    &view.batching.zerocheck_point,
                    view.batching.mu,
                    view.eta,
                    log_terminal_phase,
                );
                let Ok(value) = value else {
                    return false;
                };
                let bytes = qm31_bytes(value);
                sol_log_data(&[b"aspis-v6-terminal-value-v1", bytes.as_slice()]);
                msg!("aspis-v6-terminal:output");
                sol_log_compute_units();
                false
            },
            |_| Err(aspis_core::v6_onefold::V6WireError::WrongLength),
        );
        return match result {
            Err(V6TranscriptError::TerminalRejected) => Ok(()),
            _ => Err(ProgramError::InvalidAccountData),
        };
    }

    if tag == V6_INTEGRATED_CU_PROBE_TAG {
        let selector = full_selector.ok_or(ProgramError::InvalidInstructionData)?;
        return process_v6_integrated_probe(
            program_id,
            proof_account,
            proof,
            c1_frontier_nodes,
            c2_frontier_nodes,
            selector,
        );
    }

    if tag == V6_FULL_CU_PROBE_TAG {
        let selector = full_selector.ok_or(ProgramError::InvalidInstructionData)?;

        msg!("aspis-v6-full:entry");
        sol_log_compute_units();
        let parsed =
            V6OneFoldWire::parse_deferred_canonicality(proof, c1_frontier_nodes, c2_frontier_nodes)
                .map_err(|_| ProgramError::InvalidAccountData)?;
        msg!("aspis-v6-full:parsed");
        sol_log_compute_units();

        let context = V6TranscriptContext {
            program_id: program_id.to_bytes(),
            release_binding: V6_PROBE_RELEASE_BINDING,
            statement_digest: V6_PROBE_STATEMENT_DIGEST,
            attempt_id: proof_account.key.to_bytes(),
        };
        let verified = verify_v6_transcript_and_relation_prepared(
            crate::verify::sbf_hashv,
            &parsed,
            &context,
            selector,
            atomic_state_only_copy_inactive_row_groups_v3(),
            atomic_state_only_copy_inactive_group_masks_v3(),
            false,
            |_| true,
            |view| {
                msg!("aspis-v6-full:transcript-prefix");
                sol_log_compute_units();
                let combined = verify_and_gamma_combine_v6_binary_openings_prepared(
                    crate::verify::sbf_hashv,
                    &parsed,
                    view.queries,
                    view.gamma_powers,
                )?;
                msg!("aspis-v6-full:merkle-and-gamma");
                sol_log_compute_units();
                let coordinates = prepare_v6_onefold_coordinates(view.queries)?;
                msg!("aspis-v6-full:coordinates");
                sol_log_compute_units();
                let folded = fold_v6_onefold_queries(&combined, &coordinates, view.alpha0);
                msg!("aspis-v6-full:onefold-query-values");
                sol_log_compute_units();
                Ok(V6AuthenticatedQueryBatch {
                    values: folded,
                    line_x: coordinates.line_x,
                })
            },
        )
        .map_err(|_| ProgramError::InvalidAccountData)?;
        msg!("aspis-v6-full:relation-tail");
        sol_log_compute_units();
        let folded_sum = qm31_bytes(verified.folded_query_sum);
        let slices = [
            folded_sum.as_slice(),
            verified.transcript_state_after_queries.as_slice(),
        ];
        let sink = hashv(&slices);
        sol_log_data(&[b"aspis-v6-full-readonly-probe-v1", sink.as_ref()]);
        msg!("aspis-v6-full:sink");
        sol_log_compute_units();
        return Ok(());
    }

    msg!("aspis-v6-cu:entry");
    sol_log_compute_units();
    let parsed =
        V6OneFoldWire::parse_deferred_canonicality(proof, c1_frontier_nodes, c2_frontier_nodes)
            .map_err(|_| ProgramError::InvalidAccountData)?;
    msg!("aspis-v6-cu:parsed");
    sol_log_compute_units();

    let frontier =
        binary_frontier_nodes(queries, 18).map_err(|_| ProgramError::InvalidInstructionData)?;
    if frontier != c1_frontier_nodes || frontier != c2_frontier_nodes {
        return Err(ProgramError::InvalidInstructionData);
    }
    msg!("aspis-v6-cu:frontier");
    sol_log_compute_units();

    let gamma = QM31 {
        c0: CM31::new(M31(17), M31(23)),
        c1: CM31::new(M31(31), M31(47)),
    };
    let alpha = QM31 {
        c0: CM31::new(M31(53), M31(59)),
        c1: CM31::new(M31(61), M31(67)),
    };
    let combined = verify_and_gamma_combine_v6_binary_openings(
        crate::verify::sbf_hashv,
        &parsed,
        queries,
        gamma,
    )
    .map_err(|_| ProgramError::InvalidAccountData)?;
    msg!("aspis-v6-cu:merkle-and-gamma");
    sol_log_compute_units();
    let expected = evaluate_packed_final256_at_queries(parsed.fixed_fields_packed, queries)
        .map_err(|_| ProgramError::InvalidAccountData)?;
    msg!("aspis-v6-cu:final-evaluations");
    sol_log_compute_units();
    let coordinates =
        prepare_v6_onefold_coordinates(queries).map_err(|_| ProgramError::InvalidAccountData)?;
    msg!("aspis-v6-cu:coordinates");
    sol_log_compute_units();
    let folded = fold_v6_onefold_queries(&combined, &coordinates, alpha);
    if folded != expected {
        return Err(ProgramError::InvalidAccountData);
    }
    let outputs = folded.map(qm31_bytes);
    msg!("aspis-v6-cu:onefold-query-checks");
    sol_log_compute_units();

    let slices: [&[u8]; V6_QUERY_COUNT] = core::array::from_fn(|index| outputs[index].as_slice());
    let sink = hashv(&slices);
    sol_log_data(&[b"aspis-v6-final256-probe-v1", sink.as_ref()]);
    msg!("aspis-v6-cu:sink");
    sol_log_compute_units();
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::lifecycle::PROOF_ACCOUNT_HEADER_LEN;
    use crate::test_support::make_account;
    use aspis_core::merkle::node_hash;
    use aspis_core::state_only_private_merkle::private_leaf_hash;
    use aspis_core::v6_onefold::{
        V6_BODY_WITHOUT_FRONTIERS, V6_C1_TREE_TAG, V6_C2_TREE_TAG, V6_FIXED_PACKED_FIELD_BYTES,
        V6_FRONTIER_CAP_PER_TREE,
    };

    fn clustered_queries() -> [u32; V6_QUERY_COUNT] {
        core::array::from_fn(|index| index as u32)
    }

    fn wire(frontier: usize, queries: [u32; V6_QUERY_COUNT]) -> Vec<u8> {
        let mut wire = Vec::with_capacity(V6_CU_PROBE_WIRE_BYTES);
        wire.push(V6_CU_PROBE_TAG);
        wire.extend_from_slice(&(frontier as u16).to_le_bytes());
        wire.extend_from_slice(&(frontier as u16).to_le_bytes());
        for query in queries {
            wire.extend_from_slice(&query.to_le_bytes());
        }
        wire
    }

    fn minimal_binary_root(entries: &[(u32, [u8; 32])], frontier: &[[u8; 32]]) -> [u8; 32] {
        let mut stream = frontier.iter();
        let mut level = entries.to_vec();
        for _ in 0..18 {
            let mut next = Vec::with_capacity(level.len());
            let mut index = 0usize;
            while index < level.len() {
                let (position, digest) = level[index];
                let parent = if position & 1 == 0
                    && index + 1 < level.len()
                    && level[index + 1].0 == position + 1
                {
                    let combined =
                        node_hash(crate::verify::sbf_hashv, &digest, &level[index + 1].1);
                    index += 2;
                    combined
                } else {
                    let sibling = stream.next().unwrap();
                    index += 1;
                    if position & 1 == 0 {
                        node_hash(crate::verify::sbf_hashv, &digest, sibling)
                    } else {
                        node_hash(crate::verify::sbf_hashv, sibling, &digest)
                    }
                };
                next.push((position >> 1, parent));
            }
            level = next;
        }
        assert!(stream.next().is_none());
        level[0].1
    }

    fn valid_body(queries: [u32; V6_QUERY_COUNT], frontier: usize) -> Vec<u8> {
        let mut body = vec![0u8; V6_BODY_WITHOUT_FRONTIERS + 2 * frontier * 32];
        let parsed = V6OneFoldWire::parse(&body, frontier, frontier).unwrap();
        let mut order: [(u32, usize); V6_QUERY_COUNT] =
            core::array::from_fn(|ordinal| (queries[ordinal], ordinal));
        order.sort_unstable_by_key(|entry| entry.0);
        let c1_entries: Vec<_> = order
            .iter()
            .map(|(query, ordinal)| {
                let record = parsed.query(*ordinal).unwrap();
                (
                    *query,
                    private_leaf_hash(
                        crate::verify::sbf_hashv,
                        V6_C1_TREE_TAG,
                        record.c1_packed,
                        record.salt,
                    ),
                )
            })
            .collect();
        let c2_entries: Vec<_> = order
            .iter()
            .map(|(query, ordinal)| {
                let record = parsed.query(*ordinal).unwrap();
                (
                    *query,
                    private_leaf_hash(
                        crate::verify::sbf_hashv,
                        V6_C2_TREE_TAG,
                        record.c2_packed,
                        record.salt,
                    ),
                )
            })
            .collect();
        let zero_frontier = vec![[0u8; 32]; frontier];
        let c1_root = minimal_binary_root(&c1_entries, &zero_frontier);
        let c2_root = minimal_binary_root(&c2_entries, &zero_frontier);
        body[V6_FIXED_PACKED_FIELD_BYTES..V6_FIXED_PACKED_FIELD_BYTES + 32]
            .copy_from_slice(&c1_root);
        body[V6_FIXED_PACKED_FIELD_BYTES + 32..V6_FIXED_PACKED_FIELD_BYTES + 64]
            .copy_from_slice(&c2_root);
        body
    }

    #[test]
    fn exact_sealed_probe_accepts_and_mismatched_frontier_rejects() {
        let program_id = crate::id();
        let proof_key = Pubkey::new_unique();
        let queries = clustered_queries();
        let frontier = binary_frontier_nodes(queries, 18).unwrap();
        assert!(frontier <= V6_FRONTIER_CAP_PER_TREE);
        let body_len = V6_BODY_WITHOUT_FRONTIERS + 2 * frontier * 32;
        let body = valid_body(queries, frontier);
        assert_eq!(body.len(), body_len);
        let mut data = vec![0u8; PROOF_ACCOUNT_HEADER_LEN + body_len];
        data[0..4].copy_from_slice(b"ASPU");
        data[4..8].copy_from_slice(&(body_len as u32).to_le_bytes());
        data[PROOF_ACCOUNT_HEADER_LEN..].copy_from_slice(&body);
        let mut lamports = 1;
        let proof = make_account(
            &proof_key,
            &program_id,
            &mut lamports,
            &mut data,
            false,
            false,
        );
        assert_eq!(
            process_v6_cu_probe_instruction(
                &program_id,
                &[proof.clone()],
                &wire(frontier, queries)
            ),
            Ok(())
        );
        assert_eq!(
            process_v6_cu_probe_instruction(&program_id, &[proof], &wire(frontier + 1, queries)),
            Err(ProgramError::InvalidAccountData)
        );
    }

    #[test]
    fn probe_feature_cannot_change_the_production_dispatch() {
        assert_eq!(
            crate::dispatch::process_spend_production_instruction(
                &crate::id(),
                &[],
                &[V6_CU_PROBE_TAG]
            ),
            Err(ProgramError::InvalidInstructionData)
        );
    }
}

programs/aspis-verifier/src/v6_transacti:
//! Production transaction wrapper for the V6 26+3 one-fold verifier.
//!
//! This module contains no diagnostic hash substitution and no acceptance
//! shortcut. Tag 72 checks all three work witnesses, exact terminal equality,
//! both authenticated binary openings, the one-fold query equalities, and the
//! complete relation tail before the shared atomic wrapper mutates any state.

use solana_program::{
    account_info::AccountInfo, entrypoint::ProgramResult, program_error::ProgramError,
    pubkey::Pubkey,
};

use crate::atomic_payment::{self, AtomicPaymentPublicInputs};

pub const V6_PRODUCTION_TAG: u8 = 72;
const V6_ATOMIC_PUBLIC_WIRE_BYTES: usize = 4 * 32 + 2 * 4 + 32;
pub const V6_ATOMIC_WIRE_BYTES: usize = 1 + 2 + 2 + 1 + V6_ATOMIC_PUBLIC_WIRE_BYTES;

/// SHA-256("aspis:v6:onefold:26c1-3c2:b10:q16:frontier209:work34-31-34:release-v1").
///
/// This compiled value separates V6 proofs from probes and from every future
/// release even when the program id and public statement are otherwise equal.
pub const V6_RELEASE_BINDING: [u8; 32] = [
    0x36, 0xd1, 0xd6, 0xa7, 0x1b, 0x6a, 0x6e, 0x66, 0x99, 0x82, 0xca, 0x9e, 0xa6, 0x7b, 0xc1, 0x9f,
    0xd1, 0x33, 0x1a, 0x2c, 0x21, 0x2c, 0xa8, 0x03, 0xa1, 0xb6, 0xc5, 0xda, 0x17, 0x6e, 0x5e, 0x18,
];

fn take<const N: usize>(input: &mut &[u8]) -> Result<[u8; N], ProgramError> {
    let (head, tail) = input
        .split_first_chunk::<N>()
        .ok_or(ProgramError::InvalidInstructionData)?;
    *input = tail;
    Ok(*head)
}

fn u16_le(input: &mut &[u8]) -> Result<u16, ProgramError> {
    Ok(u16::from_le_bytes(take::<2>(input)?))
}

fn u32_le(input: &mut &[u8]) -> Result<u32, ProgramError> {
    Ok(u32::from_le_bytes(take::<4>(input)?))
}

/// Parse and execute the exact production V6 atomic wire.
pub fn process_v6_atomic_instruction(
    program_id: &Pubkey,
    accounts: &[AccountInfo],
    instruction_data: &[u8],
) -> ProgramResult {
    if instruction_data.len() != V6_ATOMIC_WIRE_BYTES
        || instruction_data.first().copied() != Some(V6_PRODUCTION_TAG)
    {
        return Err(ProgramError::InvalidInstructionData);
    }

    let mut input = &instruction_data[1..];
    let c1_frontier_nodes = usize::from(u16_le(&mut input)?);
    let c2_frontier_nodes = usize::from(u16_le(&mut input)?);
    let selector = take::<1>(&mut input)?[0];
    let public = AtomicPaymentPublicInputs {
        current_anchor: take(&mut input)?,
        nullifier: take(&mut input)?,
        output_commitment: take(&mut input)?,
        output_anchor: take(&mut input)?,
        asset_id: u32_le(&mut input)?,
        fee: u32_le(&mut input)?,
        deployment_domain: take(&mut input)?,
    };
    if !input.is_empty() {
        return Err(ProgramError::InvalidInstructionData);
    }

    atomic_payment::verify_and_apply_atomic_payment_state(
        program_id,
        accounts,
        &public,
        |proof_account, statement, statement_digest| {
            let account_data = proof_account.try_borrow_data()?;
            if !crate::lifecycle::proof_account_finalized(&account_data) {
                return Err(ProgramError::InvalidAccountData);
            }
            let (proof_start, proof_end) = crate::lifecycle::uploaded_proof_bounds(&account_data)?;
            let proof = &account_data[proof_start..proof_end];
            crate::v6_verifier::verify_v6_read_only_with_statement_digest(
                crate::verify::sbf_hashv,
                proof,
                c1_frontier_nodes,
                c2_frontier_nodes,
                selector,
                program_id,
                V6_RELEASE_BINDING,
                proof_account.key,
                statement,
                *statement_digest,
                true,
            )
            .map_err(|_| ProgramError::InvalidAccountData)?;
            Ok(())
        },
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn release_binding_matches_documented_preimage() {
        assert_eq!(
            solana_program::hash::hash(
                b"aspis:v6:onefold:26c1-3c2:b10:q16:frontier209:work34-31-34:release-v1"
            )
            .to_bytes(),
            V6_RELEASE_BINDING
        );
    }

    #[test]
    fn production_wire_is_exact_and_rejects_trailing_bytes() {
        let wire = vec![0u8; V6_ATOMIC_WIRE_BYTES];
        assert_eq!(
            process_v6_atomic_instruction(&crate::id(), &[], &wire),
            Err(ProgramError::InvalidInstructionData)
        );

        let mut exact = wire;
        exact[0] = V6_PRODUCTION_TAG;
        assert_eq!(
            process_v6_atomic_instruction(&crate::id(), &[], &exact),
            Err(ProgramError::NotEnoughAccountKeys)
        );
        exact.push(0);
        assert_eq!(
            process_v6_atomic_instruction(&crate::id(), &[], &exact),
            Err(ProgramError::InvalidInstructionData)
        );
    }
}

//! Complete read-only verifier composition for the V6 26+3 one-fold path.
//!
//! The frozen tag-72 instruction dispatches this composition surface.  Keep
//! it as the single measured and source-translated V6 acceptance entrypoint.

use aspis_core::field::QM31;
use aspis_core::v6_onefold::{
    fold_v6_onefold_queries, parse_v6_onefold_wire_deferred, prepare_v6_onefold_coordinates,
    verify_and_gamma_combine_v6_binary_openings_prepared, V6OneFoldWire, V6WireError,
};
use aspis_core::v6_query_batch::V6AuthenticatedQueryBatch;
use aspis_core::v6_transcript::{
    verify_v6_transcript_and_relation_prepared, V6QueryBatchView, V6SemanticView,
    V6TranscriptContext, V6TranscriptError, V6VerifiedTranscript,
};
use aspis_core::HashFn;
use aspis_statement::atomic_state_only_terminal::{
    atomic_state_only_copy_inactive_group_masks_v3, atomic_state_only_copy_inactive_row_groups_v3,
    atomic_state_only_selected_masked_terminal_value_compiled_v3,
};
use aspis_statement::{
    atomic_payment_statement_digest_v4, AtomicPaymentStatementV4,
    STATE_ONLY_SELECTED_TERMINAL_CLAIMS,
};
use solana_program::pubkey::Pubkey;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum V6VerifyError {
    StatementDigest,
    Transcript(V6TranscriptError),
    Query(V6WireError),
}

impl From<V6TranscriptError> for V6VerifyError {
    fn from(error: V6TranscriptError) -> Self {
        Self::Transcript(error)
    }
}

impl From<V6WireError> for V6VerifyError {
    fn from(error: V6WireError) -> Self {
        Self::Query(error)
    }
}

#[derive(Debug)]
pub struct VerifiedV6ReadOnly {
    pub transcript: V6VerifiedTranscript,
    pub folded_query_sum: QM31,
}

pub(crate) fn terminal_claims(
    view: &V6SemanticView<'_>,
) -> [QM31; STATE_ONLY_SELECTED_TERMINAL_CLAIMS] {
    // The maintained atomic selected-hiding terminal consumes 3 x 28 lanes:
    // C1[0..26], H and G. V6's appended D lane is column 28 and participates
    // only in the PCS relation, exactly as in the maintained spend profile.
    core::array::from_fn(|index| {
        let row = index / 28;
        let column = index % 28;
        view.point_claims[row][column]
    })
}

pub(crate) fn terminal_matches(
    statement: &AtomicPaymentStatementV4,
    view: &V6SemanticView<'_>,
) -> bool {
    atomic_state_only_selected_masked_terminal_value_compiled_v3(
        statement,
        &terminal_claims(view),
        &view.point,
        view.lambda,
        view.chi,
        view.batching.theta,
        &view.batching.zerocheck_point,
        view.batching.mu,
        view.eta,
    )
    .is_ok_and(|expected| expected == view.terminal_claim)
}

#[inline(never)]
fn authenticate_and_fold_queries(
    hash: HashFn,
    wire: &V6OneFoldWire<'_>,
    view: &V6QueryBatchView<'_>,
) -> Result<V6AuthenticatedQueryBatch, V6WireError> {
    let combined = verify_and_gamma_combine_v6_binary_openings_prepared(
        hash,
        wire,
        view.queries,
        view.gamma_powers,
    )?;
    let coordinates = prepare_v6_onefold_coordinates(view.queries)?;
    Ok(V6AuthenticatedQueryBatch {
        values: fold_v6_onefold_queries(&combined, &coordinates, view.alpha0),
        line_x: coordinates.line_x,
    })
}

/// Verify the exact V6 read-only proof path. The caller supplies frontier
/// counts and selector from the instruction, while queries and the compact
/// counter are derived entirely by the transcript.
#[allow(clippy::too_many_arguments)]
pub fn verify_v6_read_only(
    hash: HashFn,
    proof: &[u8],
    c1_frontier_nodes: usize,
    c2_frontier_nodes: usize,
    selector: u8,
    program_id: &Pubkey,
    release_binding: [u8; 32],
    attempt_id: &Pubkey,
    statement: &AtomicPaymentStatementV4,
    check_pow: bool,
) -> Result<VerifiedV6ReadOnly, V6VerifyError> {
    let statement_digest = atomic_payment_statement_digest_v4(statement, hash)
        .map_err(|_| V6VerifyError::StatementDigest)?;
    verify_v6_read_only_with_statement_digest(
        hash,
        proof,
        c1_frontier_nodes,
        c2_frontier_nodes,
        selector,
        program_id,
        release_binding,
        attempt_id,
        statement,
        statement_digest,
        check_pow,
    )
}

/// Verify V6 with the exact statement digest already checked by the atomic
/// transition wrapper. This is the production entrypoint: the wrapper must
/// construct `statement` and `statement_digest` together and supplies both
/// to this function, avoiding a duplicate SHA-256 statement serialization
/// without weakening the transcript binding.
#[allow(clippy::too_many_arguments)]
pub fn verify_v6_read_only_with_statement_digest(
    hash: HashFn,
    proof: &[u8],
    c1_frontier_nodes: usize,
    c2_frontier_nodes: usize,
    selector: u8,
    program_id: &Pubkey,
    release_binding: [u8; 32],
    attempt_id: &Pubkey,
    statement: &AtomicPaymentStatementV4,
    statement_digest: [u8; 32],
    check_pow: bool,
) -> Result<VerifiedV6ReadOnly, V6VerifyError> {
    verify_v6_read_only_with_statement_digest_and_schedule(
        hash,
        proof,
        c1_frontier_nodes,
        c2_frontier_nodes,
        selector,
        program_id,
        release_binding,
        attempt_id,
        statement,
        statement_digest,
        atomic_state_only_copy_inactive_row_groups_v3(),
        atomic_state_only_copy_inactive_group_masks_v3(),
        check_pow,
    )
}

/// Source-translation boundary for the production entrypoint.  The public
/// wrapper above supplies the two frozen generated schedules; separating
/// those references from the acceptance kernel avoids asking Aeneas to
/// synthesize a loan for an opaque `&'static` return value.
#[allow(clippy::too_many_arguments)]
#[inline(always)]
pub(crate) fn verify_v6_read_only_with_statement_digest_and_schedule(
    hash: HashFn,
    proof: &[u8],
    c1_frontier_nodes: usize,
    c2_frontier_nodes: usize,
    selector: u8,
    program_id: &Pubkey,
    release_binding: [u8; 32],
    attempt_id: &Pubkey,
    statement: &AtomicPaymentStatementV4,
    statement_digest: [u8; 32],
    inactive_row_groups: &[u8; 64],
    inactive_group_masks: &[u16],
    check_pow: bool,
) -> Result<VerifiedV6ReadOnly, V6VerifyError> {
    let wire = parse_v6_onefold_wire_deferred(proof, c1_frontier_nodes, c2_frontier_nodes)?;
    let context = V6TranscriptContext {
        program_id: program_id.to_bytes(),
        release_binding,
        statement_digest,
        attempt_id: attempt_id.to_bytes(),
    };
    let transcript = verify_v6_transcript_and_relation_prepared(
        hash,
        &wire,
        &context,
        selector,
        inactive_row_groups,
        inactive_group_masks,
        check_pow,
        |view| terminal_matches(statement, view),
        |view| authenticate_and_fold_queries(hash, &wire, view),
    )?;
    let folded_query_sum = transcript.folded_query_sum;
    Ok(VerifiedV6ReadOnly {
        transcript,
        folded_query_sum,
    })
}

