    0x33, 0x62, 0x4b, 0x1b, 0x47, 0x4b, 0x42, 0x31, 0x07, 0x84, 0xb6, 0xa0, 0x60, 0xe0, 0x67, 0x36,
];
const PRESERVED_NATIVE_RECIPIENT_COMMITMENT: [M31; 8] = [
    M31(148_482_930),
    M31(1_116_651_461),
    M31(1_440_257_094),
    M31(1_397_310_823),
