        );
        let verify_calls = Cell::new(0);
        let slot_calls = Cell::new(0);
        let result = process_v7_pool_receipt_finalize_with_runtime(
            &fixture.program_id,
            &[proof, receipt],
            &fixture.request,
            sha256,
            |program_id, accounts, instruction_data, hash| {
                verify_v7_pool_tag73_asvq_with_runtime(
                    program_id,
