#[test]
fn measured_core_call_counts_include_zero_progress_checkpoint() {
    // These are measurements of this saved fixture and the concrete HashFn,
    // not a universal source theorem or an instrumentation of PDA syscalls.
    let statement = decode_pool_v1_pair_forest_terminal_statement_v1(PUBLIC).unwrap();
    let public = match &statement {
        PoolV1PairForestTerminalStatementV1::PrivateTransfer { common, public } => {
            Public::Transfer(public, &common.lane_transition)
        }
        PoolV1PairForestTerminalStatementV1::Withdrawal { common, public } => {
            Public::Withdrawal(public, &common.lane_transition)
        }
    };
    // Adopted format: per batch and tree, three leaf hashes per query and,
    // for a binary multiproof over d distinct indices with n supplied nodes,
    // n + d - 1 parent hashes (sum over levels of the occupied parents).
    let k = verifier::SPLIT;
    HASH_CALLS.with(|count| count.set(0));
    let checkpoint = verifier::tx1(public, PUBLIC, PROOF, k, CountedDigest, None).unwrap();
    let stage1_calls = HASH_CALLS.with(|count| count.get());
    let queries: Vec<u32> = (0..22)
        .map(|i| u32::from_le_bytes(checkpoint[320 + 4 * i..324 + 4 * i].try_into().unwrap()))
        .collect();
    let parents = |lo: usize, hi: usize| -> usize {
        (0..3)
            .map(|tree| {
                let mut idx: Vec<u32> = queries[lo..hi]
                    .iter()
                    .map(|&u| if tree == 2 { u / 4 } else { u })
                    .collect();
                idx.sort();
                idx.dedup();
                aspis_r1_cost_probe::multiproof::node_count(
                    aspis_r1_cost_probe::multiproof::Arity::Two,
                    &idx,
                )
                .unwrap()
                    + idx.len()
                    - 1
            })
            .sum()
    };
    assert_eq!(stage1_calls, 118 + 3 * k + parents(0, k));
    HASH_CALLS.with(|count| count.set(0));
    verifier::tx2_authenticated(PUBLIC, PROOF, &checkpoint, CountedDigest, None).unwrap();
    HASH_CALLS.with(|count| assert_eq!(count.get(), 3 + 3 * (22 - k) + parents(k, 22)));
    // Unkeyed checksum plus arbitrary account bytes admits next=0 at resume.
    // The adopted stage 2 requires next == SPLIT (its batch multiproof covers
    // exactly queries SPLIT..22), so this zero-progress checkpoint is rejected
    // after the three resume hashes. Account provenance is still required.
    let mut checkpoint = saved_checkpoint().to_vec();
    checkpoint[9] = 0;
    let end = checkpoint.len() - 32;
    let checksum = sha256(&[b"UNPROVED:R1:checkpoint", &checkpoint[..end]]);
    checkpoint[end..].copy_from_slice(&checksum);
    HASH_CALLS.with(|count| count.set(0));
    assert_eq!(
        verifier::tx2_authenticated(PUBLIC, PROOF, &checkpoint, CountedDigest, None),
        Err(verifier::Error::Checkpoint)
    );
    HASH_CALLS.with(|count| assert_eq!(count.get(), 3));
}

#[test]
fn r15_read_binding_rejects_account_buffer_changes_after_stage1() {
    let mut fixture = Stage1Fixture::new();
    // Use the admitted release entrypoint to produce the checkpoint, then end
    // all AccountInfo borrows before modelling the inter-transaction mutation.
    {
        let infos: Vec<_> = fixture.accounts.iter_mut().map(TestAccount::info).collect();
        super::super::process_r1_cost_probe_instruction(&fixture.program, &infos, &[3, 10])
            .unwrap();
    }
    let checkpoint = fixture.accounts[2].data.clone();
    let proof_start = POOL_V1_PAIR_VERIFIED_AFTERSTATE_BYTES;
    verifier::resume(&checkpoint, &fixture.accounts[0].data[proof_start..],
        &fixture.accounts[1].data, Variant::S2, TestDigest).unwrap();
    assert_eq!(verifier::tx2_authenticated(&fixture.accounts[1].data,
        &fixture.accounts[0].data[proof_start..], &checkpoint, TestDigest, None), Ok(()));

    fixture.accounts[0].data[proof_start + verifier::HEADER] ^= 1;
    assert_hash_binding_rejection(&fixture.accounts[0].data[proof_start..],
        &fixture.accounts[1].data, &checkpoint, 1);
    fixture.accounts[0].data[proof_start + verifier::HEADER] ^= 1;
    fixture.accounts[1].data[0] ^= 1;
    assert_hash_binding_rejection(&fixture.accounts[0].data[proof_start..],
        &fixture.accounts[1].data, &checkpoint, 2);
    // Stage2 has no public account: this is its resume input contract. The
    // separate reconstruction regression checks the ASQ8-to-public binding.
    assert_eq!(fixture.accounts[2].data, checkpoint);
}

#[test]
fn r15_read_stage1_rejects_wrong_lengths_and_non_distinct_accounts() {
    let reject = |mut fixture: Stage1Fixture, error| {
        let before: Vec<_> = fixture.accounts.iter().map(|a| a.data.clone()).collect();
        let balances: Vec<_> = fixture.accounts.iter().map(|a| a.lamports).collect();
        let infos: Vec<_> = fixture.accounts.iter_mut().map(TestAccount::info).collect();
        assert_eq!(super::super::process_r1_cost_probe_instruction(
            &fixture.program, &infos, &[3, 10]), Err(error));
        drop(infos);
        for (i, account) in fixture.accounts.iter().enumerate() {
            assert_eq!(account.data, before[i]);
            assert_eq!(account.lamports, balances[i]);
        }
    };
    for index in 0..3 {
        for delta in [-1isize, 1] {
            let mut fixture = Stage1Fixture::new();
            let length = (fixture.accounts[index].data.len() as isize + delta) as usize;
            fixture.accounts[index].data.resize(length, 0);
            reject(fixture, ProgramError::InvalidAccountData);
        }
    }
    for (left, right) in [(0, 1), (0, 2), (1, 2)] {
        let mut fixture = Stage1Fixture::new();
        fixture.accounts[right].key = fixture.accounts[left].key;
        reject(fixture, ProgramError::InvalidArgument);
    }
}

